window.TAROT_ACADEMY_CONTENT={"version":"LM-1.0-R3.2","source":"docs/LEARNING_MASTER.md","sourceHash":"a14bcb9d494357d58a08fcf1907409ff73eb14e1d0ffd3dc0d5bf575f19c4bb3","lessons":[{"id":"B01","kind":"lesson","level":"B","title":{"zh":"认识这 78 张牌","en":"Meet the 78 cards"},"teachings":[{"zh":"我们用的是伟特系塔罗，英文简称 RWS。一副有 78 张，分成 22 张大阿尔卡纳和 56 张小阿尔卡纳。先认清分类，不用急着背牌义。","en":"We use the Rider–Waite–Smith deck, abbreviated RWS. It has 78 cards: 22 Major Arcana and 56 Minor Arcana. Start with the groups; you do not need to memorize meanings yet."},{"zh":"小阿尔卡纳分成权杖、圣杯、宝剑、星币四组，这四组叫“花色”，不是指颜色。每组有王牌（Ace，可记作 1）到十，共 10 张数字牌，还有侍从、骑士、王后、国王 4 张宫廷牌。所以 56 张小牌里，已经包括 40 张数字牌和 16 张宫廷牌。","en":"The Minor Arcana has four suits—Wands, Cups, Swords and Pentacles. A suit is a group, not a color. Each has ten numbered cards, Ace (which can be remembered as 1) through Ten, plus Page, Knight, Queen and King. The 56 minors already include 40 numbered cards and 16 courts."},{"zh":"试着拆开牌名：星币八＝星币花色＋数字八；圣杯骑士＝圣杯花色＋骑士角色；力量是大阿尔卡纳。本教材力量编号 VIII、正义编号 XI。大牌不代表一定更重要或更准确。","en":"Read the name: Eight of Pentacles combines a suit and a number; Knight of Cups combines a suit and a court role; Strength is a Major Arcana card. Here Strength is VIII and Justice is XI. Major cards are not automatically more important or more accurate."}],"questions":{"Q1":{"id":"B01-Q1","prompt":{"zh":"圣杯王后属于哪一类牌？","en":"Where does the Queen of Cups belong?"},"options":[{"id":"B01-Q1-7fe1affe1f","text":{"zh":"宫廷牌","en":"Court card"},"feedback":{"zh":"王后是四种宫廷角色之一。","en":"Queen is one of the four court roles."}},{"id":"B01-Q1-3fab633637","text":{"zh":"数字牌","en":"Numbered card"},"feedback":{"zh":"数字牌是王牌至十；王后是角色。","en":"Numbered cards run from Ace to Ten; Queen is a role."}}],"correct":"B01-Q1-7fe1affe1f","support":"R1"},"Q2":{"id":"B01-Q2","prompt":{"zh":"56 张小牌是否已经包含 16 张宫廷牌？","en":"Do the 56 minors already include the 16 courts?"},"options":[{"id":"B01-Q2-5f60ffcf60","text":{"zh":"不包含","en":"No"},"feedback":{"zh":"这样会重复计算宫廷牌。","en":"That would count the courts twice."}},{"id":"B01-Q2-107319b8b3","text":{"zh":"包含","en":"Yes"},"feedback":{"zh":"40 张数字牌加 16 张宫廷牌等于 56。","en":"Forty numbered cards plus sixteen courts make 56."}}],"correct":"B01-Q2-107319b8b3","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"先看后半个名字：八是数字，骑士是角色。分类不需要知道它是什么意思。","en":"Look at the second part of the name: Eight is a number; Knight is a role. You can classify a card before knowing its meaning."}],"question":{"id":"B01-R1","prompt":{"zh":"宝剑侍从应放在哪一类？","en":"Where does the Page of Swords belong?"},"options":[{"id":"B01-R1-7fe1affe1f","text":{"zh":"宫廷牌","en":"Court"},"feedback":{"zh":"侍从是角色，因此属于宫廷。","en":"Page is a role, so this is a court card."}},{"id":"B01-R1-3fab633637","text":{"zh":"数字牌","en":"Numbered"},"feedback":{"zh":"侍从不是王牌至十中的数字名称。","en":"Page is not a rank from Ace to Ten."}}],"correct":"B01-R1-7fe1affe1f"}},"R2":{"teach":[{"zh":"56 张小牌里已经有 40 张数字牌和 16 张宫廷牌。算整副牌时，不要把宫廷牌再加一次。","en":"Picture 56 as a box holding two bags: 40 cards and 16 cards. Both bags are already inside."}],"question":{"id":"B01-R2","prompt":{"zh":"整副牌怎样相加？","en":"Which sum describes the whole deck?"},"options":[{"id":"B01-R2-81d56549b4","text":{"zh":"22＋56＋16","en":"22+56+16"},"feedback":{"zh":"16 已包含在 56 中。","en":"The 16 are already inside the 56."}},{"id":"B01-R2-3408fb3702","text":{"zh":"22＋40＋16","en":"22+40+16"},"feedback":{"zh":"三类互不重复，合计 78。","en":"The three groups do not overlap and total 78."}}],"correct":"B01-R2-3408fb3702"}}},"revisit":{"id":"B01-V1","prompt":{"zh":"权杖九的名字由什么组成？","en":"What makes up the name Nine of Wands?"},"options":[{"id":"B01-V1-121c9cb789","text":{"zh":"花色＋数字","en":"Suit + number"},"feedback":{"zh":"权杖是花色，九是数字。","en":"Wands is the suit and Nine the number."}},{"id":"B01-V1-f4104558ef","text":{"zh":"花色＋宫廷角色","en":"Suit + court role"},"feedback":{"zh":"九不是侍从、骑士、王后或国王。","en":"Nine is not a court role."}}],"correct":"B01-V1-121c9cb789"},"summary":{"zh":"本课介绍了牌组的分类。接下来学一次抽牌如何开始。","en":"This lesson introduced the deck’s categories. Next, learn how a reading begins."},"cards":["p08","c12","m08"]},{"id":"B02","kind":"lesson","level":"B","title":{"zh":"从洗牌到解读","en":"From shuffling to reading"},"teachings":[{"zh":"先确定问题和牌位，再抽牌。问题告诉你在问什么；牌位告诉你这张牌负责回答哪一部分。今天问：这周我可以怎样练摄影？这一张用来给行动建议。今天先读正位，也就是牌图朝正方向；倒着的情况以后再学。","en":"Choose the question and position before drawing. The question says what you are asking; the position says which part this card answers. Today: How can I practice photography this week? This card offers action advice. We start with upright cards, whose images face the usual way; reversed cards come later."},{"zh":"洗牌是打乱牌序。这里示范把牌分成两叠、交替合回；实体牌也可使用你拿得稳的方法。切牌是把牌堆分开后重新合拢，可作为洗牌结束的标记，不是必须步骤，没有唯一次数。然后选一张，仍按刚才定好的“行动建议”来读。","en":"Shuffling changes the order. We demonstrate splitting into two piles and interleaving them; with physical cards, use a method you can handle comfortably. Cutting separates and recombines the stack. It can mark the end of shuffling, but is optional and has no mandatory count. Draw one card and keep the position you agreed on."},{"zh":"示范抽到星币八。这张牌讲的是认真练技能，把手上的事做熟、做好。回答摄影问题时，可以这样建议：“挑一个想练的拍摄技巧，拍一些照片，再看看哪里需要改。”最后用一句话回答最初的问题。不熟悉这张牌时，可以查资料。它没有告诉我们哪天会获奖。","en":"Our example draws the Eight of Pentacles: attentive skill practice and care for quality. The advice becomes: choose one photography skill, take photographs, then review the results. Finish with a concise answer. We did not ask when you would win an award, so advice is not an award guarantee. Looking up an unfamiliar card is allowed."}],"questions":{"Q1":{"id":"B02-Q1","prompt":{"zh":"应该在什么时候决定，这张牌用来给行动建议？","en":"When do you define the advice position?"},"options":[{"id":"B02-Q1-751298a494","text":{"zh":"抽完牌、看清牌面后","en":"After drawing and seeing the card"},"feedback":{"zh":"原本问的是“接下来怎样做”，看完牌后再改，就变成了另一个问题。","en":"Changing it afterward alters the reading's rules."}},{"id":"B02-Q1-153205e495","text":{"zh":"抽牌前","en":"Before drawing"},"feedback":{"zh":"这样知道牌在回答什么。","en":"That defines what the card will answer."}}],"correct":"B02-Q1-153205e495","support":"R1"},"Q2":{"id":"B02-Q2","prompt":{"zh":"本课的切牌必须做三次吗？","en":"Must you cut three times in this lesson?"},"options":[{"id":"B02-Q2-560eedecb9","text":{"zh":"不必，切牌是可选操作","en":"No; cutting is optional"},"feedback":{"zh":"本课不规定次数。","en":"This lesson does not prescribe a count."}},{"id":"B02-Q2-3b37370369","text":{"zh":"必须，否则无法读牌","en":"Yes, or the reading cannot work"},"feedback":{"zh":"切牌是可选步骤，不切也可以继续解牌。","en":"That turns an optional ritual into a requirement."}}],"correct":"B02-Q2-560eedecb9","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"抽牌前定好这一张给建议，解牌时就要回答接下来怎样做。","en":"A position is a task label: once it says Advice, the interpretation should address an approach."}],"question":{"id":"B02-R1","prompt":{"zh":"已经约定建议位，抽到牌后能为得到满意答案改成结果位吗？","en":"Can you change an agreed advice position into an outcome position to get a preferred answer?"},"options":[{"id":"B02-R1-0ef5c86fab","text":{"zh":"可以","en":"Yes"},"feedback":{"zh":"原先问的是怎样做，改成结果位后，回答的就不是同一个问题了。","en":"Changing the task breaks consistency."}},{"id":"B02-R1-3bfed63472","text":{"zh":"不能，仍然按建议位来读","en":"No; keep its task"},"feedback":{"zh":"保留了抽牌前的约定。","en":"This preserves the agreement."}}],"correct":"B02-R1-3bfed63472"}},"R2":{"teach":[{"zh":"切牌在本课是可选步骤，没有必须完成的次数。是否切牌，不改变已经定好的问题和牌位。","en":"Cutting is optional here and has no required count. Cutting or not cutting leaves the agreed question and position unchanged."}],"question":{"id":"B02-R2","prompt":{"zh":"小安洗好牌后忘了切牌，已按原问题抽出一张。本课怎样继续？","en":"An shuffled but forgot to cut, then drew one card for the agreed question. How should this lesson continue?"},"options":[{"id":"B02-R2-4613ca4662","text":{"zh":"保留原问题和位置，继续读这张牌","en":"Keep the question and position and continue reading this card"},"feedback":{"zh":"没有漏掉必须条件，切牌本来就是可选操作。","en":"No required condition is missing; cutting was optional."}},{"id":"B02-R2-b85758f650","text":{"zh":"必须作废，切满三次才能重来","en":"Discard the draw and restart only after three cuts"},"feedback":{"zh":"本课没有必须切三次的规定，忘了切牌也可以继续。","en":"This again makes an optional act and an invented count into a gate."}}],"correct":"B02-R2-4613ca4662"}}},"revisit":{"id":"B02-V1","prompt":{"zh":"问本周怎样练习，抽到星币八建议位。哪句话是在回答本周怎样练习？","en":"For this week's practice, Eight of Pentacles appears as advice. Which answer keeps that task?"},"options":[{"id":"B02-V1-0920851b38","text":{"zh":"你下周必得奖","en":"You will win next week"},"feedback":{"zh":"增加了没有提供的事件与时间保证。","en":"This adds an unsupported event and date."}},{"id":"B02-V1-b7b8974ad7","text":{"zh":"实际练一个技能并检查作品","en":"Practise a skill and review your work"},"feedback":{"zh":"把牌义转成做法。","en":"This turns meaning into an action."}}],"correct":"B02-V1-b7b8974ad7"},"summary":{"zh":"你看过了一次完整示范：先定问题和牌位，再洗牌、选牌，最后围绕问题解读。接下来认识四种花色。","en":"You have followed a complete example: set the question and position, shuffle, draw, then interpret the card for that question. Next, meet the four suits."},"cards":["p08"]},{"id":"B03","kind":"lesson","level":"B","title":{"zh":"四种花色分别讲什么","en":"What the four suits describe"},"teachings":[{"zh":"权杖对应火，可以帮你记住行动、热情和创造；圣杯对应水，常说感受和人与人的关系；宝剑对应风，常说想法、判断和沟通；星币对应土，常说钱、物品、技能，以及生活中的实际安排。这是本课用来理解塔罗的对应方式。","en":"Wands–Fire highlights action, motivation and creativity; Cups–Water highlights feelings, relationships and responses; Swords–Air highlights thought, judgment and communication; Pentacles–Earth highlights resources, skills and practical arrangements. These are symbolic correspondences used by this course, not scientific categories."},{"zh":"同样是合办小店：想不想开始，是动力；是否信任彼此，是关系；约定是否清楚，是沟通；预算够不够，是资源。一件事可以有四个观察角度。","en":"Consider opening a shop together: willingness to begin concerns motivation; mutual trust concerns relationships; clear agreements concern communication; a workable budget concerns resources. One situation can involve all four perspectives."},{"zh":"因此圣杯不只用于恋爱，星币也不只用于赚钱。先确认花色，再学具体牌。画面背景有水，不意味着整张牌都按圣杯来读。","en":"Cups is not restricted to romance, and Pentacles is not restricted to money. Identify the suit, then learn the particular card. Water in a picture does not turn the card into a Cups card."}],"questions":{"Q1":{"id":"B03-Q1","prompt":{"zh":"这次只看“预算够不够、工具够不够用”，对应刚学的哪种花色？","en":"Which suit relates directly to having enough money and tools?"},"options":[{"id":"B03-Q1-68d53932b9","text":{"zh":"星币：钱和工具","en":"Pentacles: money and tools"},"feedback":{"zh":"预算是可用的钱，工具是做事要用的东西，都属于星币关注的实际资源。","en":"Budgets and tools are practical resources."}},{"id":"B03-Q1-057105ea9f","text":{"zh":"圣杯：彼此的感受","en":"Cups: feelings between people"},"feedback":{"zh":"这里在谈可用的钱和工具，没有在谈彼此的感受。","en":"Emotional response is not the resource perspective specified here."}}],"correct":"B03-Q1-68d53932b9","support":"R1"},"Q2":{"id":"B03-Q2","prompt":{"zh":"工作问题里能讨论圣杯的关系角度吗？","en":"Can Cups' relationship perspective matter in a work question?"},"options":[{"id":"B03-Q2-a12282e607","text":{"zh":"不能，圣杯只能问恋爱","en":"No, Cups only applies to romance"},"feedback":{"zh":"这把关系缩成了恋爱一类。","en":"This reduces all relationships to romance."}},{"id":"B03-Q2-5c1c0c4459","text":{"zh":"能，例如同事的信任","en":"Yes, such as trust among colleagues"},"feedback":{"zh":"工作里也有同事之间的信任，所以也能用圣杯来理解。","en":"Life domains do not restrict suits."}}],"correct":"B03-Q2-5c1c0c4459","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"先看看这句话在谈什么。谈钱、时间、工具，可以想到星币；谈感受、信任、彼此怎样回应，可以想到圣杯。一件事里可能两方面都有，这题先练习分清正在谈哪方面。","en":"Start with the nouns: money, time and tools are resources; feelings, trust and responses concern relationships. Both can matter in the same situation. First, look at which aspect the sentence describes."}],"question":{"id":"B03-R1","prompt":{"zh":"“对方听后感到被理解”属于哪一栏？","en":"Which column fits feeling understood after being heard?"},"options":[{"id":"B03-R1-37c166b25b","text":{"zh":"圣杯：感受与回应","en":"Cups: feelings and responses"},"feedback":{"zh":"重点是情感体验。","en":"The focus is emotional experience."}},{"id":"B03-R1-bec9a87bd8","text":{"zh":"星币：预算","en":"Pentacles: budget"},"feedback":{"zh":"这里没有预算信息。","en":"No budget is described."}}],"correct":"B03-R1-37c166b25b"}},"R2":{"teach":[{"zh":"同一件事里，可能既要考虑钱，也要考虑感受、沟通和行动。不能把工作只分给星币，把恋爱只分给圣杯。","en":"Suits are four lenses, not four rooms that admit only certain questions."}],"question":{"id":"B03-R2","prompt":{"zh":"恋爱中的共同生活开支，可以从星币角度看吗？","en":"Can Pentacles address shared living expenses in a relationship?"},"options":[{"id":"B03-R2-aaf6f7c76d","text":{"zh":"不可以","en":"No"},"feedback":{"zh":"恋爱也要安排开支，不能因为是恋爱问题就排除星币。","en":"This again confuses a suit with a life domain."}},{"id":"B03-R2-0ef5c86fab","text":{"zh":"可以","en":"Yes"},"feedback":{"zh":"两个人一起生活，也需要安排钱和其他生活用品。","en":"Relationships also involve practical resources."}}],"correct":"B03-R2-0ef5c86fab"}}},"revisit":{"id":"B03-V1","prompt":{"zh":"合作前，大家要把“谁负责什么、什么时候完成”说清楚。这一部分更直接对应哪种花色？","en":"Before working together, people need to clarify who will do what and when it will be finished. Which suit directly relates to clarifying these agreements?"},"options":[{"id":"B03-V1-9e315da817","text":{"zh":"宝剑：把想法和约定说清楚","en":"Swords: clear thoughts and agreements"},"feedback":{"zh":"题目在说怎样把安排讲清楚，对应刚学的沟通和判断。","en":"The question concerns making arrangements clear, matching the communication and judgment you learned."}},{"id":"B03-V1-256372d660","text":{"zh":"圣杯：彼此是否亲近、信任","en":"Cups: closeness and trust"},"feedback":{"zh":"同一次合作也可能涉及信任，但这题问的是把安排说清楚，没有在问大家是否亲近。","en":"The same project may involve trust, but this question asks about clear arrangements, not how close people feel."}}],"correct":"B03-V1-9e315da817"},"summary":{"zh":"元素帮助找到观察角度，具体含义仍要回到单牌。接下来认识数字的作用。","en":"Elements offer perspectives; specific meanings still belong to individual cards. Next, explore numbers."},"cards":[]},{"id":"B04","kind":"lesson","level":"B","title":{"zh":"数字能告诉我们什么","en":"What the numbers can tell us"},"teachings":[{"zh":"数字可以帮助记忆：王牌让人想到刚开始；二让人想到两方之间的关系；三让人想到事情开始发展；四让人想到安定下来或暂时停住；五让人想到原来的状态被打破；六让人想到重新调整；七让人想到检查目前的情况；八让人想到继续做下去；九让人想到已经积累了不少；十让人想到一件事发展到最后阶段。这些只是大致提示，尤其七、八、九，不能直接套在每一张牌上。","en":"Numbers can organize memory: Ace suggests a beginning; Two, two sides or response; Three, development; Four, structure or pause; Five, disruption; Six, adjustment; Seven, testing; Eight, an ongoing process; Nine, accumulation; Ten, a developed stage or ending. These are broad prompts, particularly loose for Seven, Eight and Nine."},{"zh":"以星币八为例：“八”可以帮助记住持续练习。但还要单独学这张牌的意思：认真练技能，把手上的活做好。只知道它对应土、编号是八，还不够了解这张牌，也算不出人物能赚多少钱。","en":"Focus on the Eight of Pentacles: Eight may prompt attention to a continuing process, but you still need its meaning—attentive skill practice and quality. Earth plus Eight cannot tell you what the craftsperson is doing or predict an income."},{"zh":"例如小林在学木工，可以先用“认真练习，把活做好”来记星币八，再用数字八帮助记忆。如果数字的说法反而让你困惑，先学这张牌本身就可以。","en":"For Lin learning woodwork, first use the card's learned meaning of practice and detail; then use the number as an index. If the number prompt confuses you, set it aside."}],"questions":{"Q1":{"id":"B04-Q1","prompt":{"zh":"“八＋星币”是否已足够学懂全部牌义？","en":"Is Eight plus Pentacles enough to know the complete card meaning?"},"options":[{"id":"B04-Q1-0ceb7a2f46","text":{"zh":"够，可以跳过牌义","en":"Yes, skip the meaning"},"feedback":{"zh":"这样遗漏这张牌自己的场景与传统解释。","en":"That omits its scene and interpretive tradition."}},{"id":"B04-Q1-69c42271d3","text":{"zh":"不够，还需单牌学习","en":"No, the individual card still needs study"},"feedback":{"zh":"还要单独学这张牌在说什么。","en":"Structure does not replace meaning."}}],"correct":"B04-Q1-69c42271d3","support":"R1"},"Q2":{"id":"B04-Q2","prompt":{"zh":"数字提示越用越困惑时，先做什么？","en":"If a number prompt increases confusion, what should come first?"},"options":[{"id":"B04-Q2-3299036c3f","text":{"zh":"回到已讲清的单牌含义","en":"Return to the taught card meaning"},"feedback":{"zh":"先学懂这张牌就可以，不必等到数字全背熟。","en":"Numbers are aids, not a gate."}},{"id":"B04-Q2-7a236bccc9","text":{"zh":"强行让每张同数字牌含义一样","en":"Force every same-number card to mean the same"},"feedback":{"zh":"编号相同，不代表每张牌的意思都相同。","en":"Broad cues cannot erase individual meanings."}}],"correct":"B04-Q2-3299036c3f","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"书架编号帮你找书，但不等于书的内容。数字对牌义也起类似的整理作用。","en":"A shelf number helps you find a book; it is not the book's content. Numbers similarly organize card meanings."}],"question":{"id":"B04-R1","prompt":{"zh":"知道编号以后，还要不要了解这一张牌讲什么？","en":"After learning the number, do you still need this card's meaning?"},"options":[{"id":"B04-R1-77af2f337c","text":{"zh":"不要","en":"No"},"feedback":{"zh":"只知道编号，还不知道这张牌在说什么。","en":"That mistakes an index for an explanation."}},{"id":"B04-R1-975f35218e","text":{"zh":"要","en":"Yes"},"feedback":{"zh":"编号没有替代内容。","en":"The index does not replace the content."}}],"correct":"B04-R1-975f35218e"}},"R2":{"teach":[{"zh":"如果数字口诀和刚学的牌义对不上，先按这张牌本身来记。不必为了凑口诀，把所有同数字的牌都解释成一个意思。","en":"If a broad number cue does not fit an already-taught card meaning, return to that meaning. Numbers are indexes, not a requirement for identical same-number meanings. Setting a cue aside does not prevent understanding."}],"question":{"id":"B04-R2","prompt":{"zh":"你理解星币八在讲技能练习，却被‘八’的不同口诀弄混。下一步怎样学？","en":"You understand Eight of Pentacles as skill practice but conflicting number-eight slogans confuse you. What next?"},"options":[{"id":"B04-R2-f7776465bd","text":{"zh":"先记住认真练习、把活做好的意思，暂时不背数字口诀","en":"Use the taught meaning of skill practice and detail, setting the slogan aside"},"feedback":{"zh":"保留已有理解，没有为口诀改写牌义。","en":"This retains understanding without rewriting the card to fit a slogan."}},{"id":"B04-R2-865e9d02ff","text":{"zh":"为了口诀整齐，把所有八号牌强改成同一意思","en":"Rewrite every Eight to mean the same thing for a tidy slogan"},"feedback":{"zh":"每张牌各有自己的意思，不能为了口诀好背就改掉牌义。","en":"This replaces knowledge with a memory aid, the exact error being corrected."}}],"correct":"B04-R2-f7776465bd"}}},"revisit":{"id":"B04-V1","prompt":{"zh":"忘了数字八的提示，但仍理解星币八的技能练习，可以继续应用吗？","en":"If you forget the number cue but understand the Eight of Pentacles' skill practice, can you still use it?"},"options":[{"id":"B04-V1-324ef69c9f","text":{"zh":"必须先背全数字表","en":"Memorize the whole number table first"},"feedback":{"zh":"这把辅助变成了不必要门槛。","en":"That creates an unnecessary gate."}},{"id":"B04-V1-0ef5c86fab","text":{"zh":"可以","en":"Yes"},"feedback":{"zh":"单牌理解是主线，数字是帮助。","en":"Card understanding is primary; number cues help."}}],"correct":"B04-V1-0ef5c86fab"},"summary":{"zh":"你知道怎样借助数字，也知道什么时候不用它。接下来认识宫廷角色。","en":"You know how numbers can help and when to leave them aside. Next, meet court roles."},"cards":["p08"]},{"id":"B05","kind":"lesson","level":"B","title":{"zh":"认识宫廷牌","en":"Meet the court cards"},"teachings":[{"zh":"先用做事方式来认识宫廷牌：侍从开始接触和学习；骑士主动追求想要的东西；王后留意自己和别人的需要，并给予照顾；国王安排事情，并承担责任。这只是入门时的记忆提示，四种角色没有高低之分，也不是每个人必须依次经历的阶段。","en":"Start with behaviour: Pages suggest discovery and learning; Knights, action and pursuit; Queens, understanding and care; Kings, coordination and responsibility. These are introductory cues, not a ranking or a mandatory life path."},{"zh":"把角色和花色放在一起看。星币侍从可以描述刚开始学一项实际技能、愿意认真打基础的状态。它不等于没能力，也不一定指小孩。接下来还要学习这张牌的具体含义。","en":"Role and suit work together. The Page of Pentacles combines practical skills with early learning: a useful cue is seriously beginning a practical subject. It does not mean incompetence or necessarily a child. The individual picture and meaning still need study."},{"zh":"例子：小周刚接触陶艺，认真练习基本手法。这里用星币侍从描述他的学习方式，不是在算年龄。王后也可以描述任何人的照料方式，国王可以描述任何人的组织责任。","en":"Example: Zhou has just started pottery and carefully practises basic techniques. Page of Pentacles describes a learning approach, not an age. A Queen can describe anyone's way of caring; a King can describe anyone's organizing responsibility."}],"questions":{"Q1":{"id":"B05-Q1","prompt":{"zh":"本课哪种角色提示是‘开始接触新事物、学习基础’？","en":"Which role cue means initial discovery and learning?"},"options":[{"id":"B05-Q1-8e90579808","text":{"zh":"侍从","en":"Page"},"feedback":{"zh":"侍从在本课代表刚接触一件事、愿意学习的状态。","en":"This matches the taught cue."}},{"id":"B05-Q1-38e917f021","text":{"zh":"国王","en":"King"},"feedback":{"zh":"本课用国王帮助记住安排事情、承担责任，不是刚开始学基础。","en":"Here the King's cue is coordination and responsibility."}}],"correct":"B05-Q1-8e90579808","support":"R1"},"Q2":{"id":"B05-Q2","prompt":{"zh":"王后是否必须解释成现实中的女性？","en":"Must a Queen mean a woman in real life?"},"options":[{"id":"B05-Q2-2c08cddfb1","text":{"zh":"必须","en":"Yes"},"feedback":{"zh":"牌名叫王后，不代表现实里一定是女性。","en":"That overinterprets a title as identity."}},{"id":"B05-Q2-32c9a336ed","text":{"zh":"不必，可指处事方式","en":"No, it can describe an approach"},"feedback":{"zh":"任何性别的人，都可能用这种方式做事。","en":"The role does not fix gender or identity."}}],"correct":"B05-Q2-32c9a336ed","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"本课的侍从，先记开始学习；国王，先记安排事情、承担责任。看例子里的人正在做什么，不要按头衔大小猜。","en":"This lesson uses Page for beginning to discover and learn, and King for coordinating and taking responsibility. Identify the behaviour described rather than guessing by title."}],"question":{"id":"B05-R1","prompt":{"zh":"新例：小安第一次学习器材操作，正在跟着示范练基础动作。更符合本课哪种角色的做事方式？","en":"New example: An is learning equipment operation for the first time and follows a demonstration of basic movements. Which taught role cue is direct?"},"options":[{"id":"B05-R1-9b899bcd7d","text":{"zh":"侍从的初步学习","en":"The Page's initial learning"},"feedback":{"zh":"题目明确描述接触新技能、练基础。","en":"The question explicitly describes beginning a skill and practising basics."}},{"id":"B05-R1-55d1beabc0","text":{"zh":"国王安排事情、承担责任","en":"The King's coordination and responsibility"},"feedback":{"zh":"例子是在跟着示范学基础，还没有说他在安排别人的工作。","en":"No team coordination or organizing responsibility is stated; it does not replace the learning cue."}}],"correct":"B05-R1-9b899bcd7d"}},"R2":{"teach":[{"zh":"本课用王后帮助记住留意别人的需要、给予照顾。看的是怎样做事，不能只凭牌名判断这个人是什么性别。","en":"Queen is a role used here for understanding and care, not a label establishing someone's gender. Start with behaviour and the question before deciding whether a specific person is relevant."}],"question":{"id":"B05-R2","prompt":{"zh":"一位男性成员留意到同伴的需要，并主动照顾对方，能用本课王后的角色提示描述这种方式吗？","en":"A male group member understands companions' needs and provides care. Can this lesson's Queen cue describe that approach?"},"options":[{"id":"B05-R2-f37d587fd6","text":{"zh":"不能，男性不能体现王后角色","en":"No; a man cannot express a Queen role"},"feedback":{"zh":"这仍按头衔固定性别，忽略了本课描述的是行为方式。","en":"This still fixes gender from a title and ignores the behavioural approach."}},{"id":"B05-R2-5370d45d94","text":{"zh":"能，这里是在说他怎样关心和照顾同伴","en":"Yes; attend to the understanding and care"},"feedback":{"zh":"这里描述的是照顾同伴的方式，不是在判断性别。","en":"It preserves the role's meaning without making it an identity restriction."}}],"correct":"B05-R2-5370d45d94"}}},"revisit":{"id":"B05-V1","prompt":{"zh":"一位经验丰富的人第一次学木工，能用侍从描述这次学习方式吗？","en":"Can a Page describe an experienced adult's first woodworking lessons?"},"options":[{"id":"B05-V1-413c06bcef","text":{"zh":"能","en":"Yes"},"feedback":{"zh":"新领域的学习方式不由年龄决定。","en":"Learning a new subject is not determined by age."}},{"id":"B05-V1-fb3401163e","text":{"zh":"不能，侍从只指儿童","en":"No, Pages only mean children"},"feedback":{"zh":"这是本课已经排除的固定身份解释。","en":"This is the fixed identity reading the lesson excluded."}}],"correct":"B05-V1-413c06bcef"},"summary":{"zh":"先看行为，再看问题在问谁。接下来用一张牌体验完整学习。","en":"Start with behaviour, then consider who the question concerns. Next, learn one card in full."},"cards":["p11"]},{"id":"B06","kind":"lesson","level":"B","title":{"zh":"读懂星币八","en":"Understand the Eight of Pentacles"},"teachings":[{"zh":"星币八讲的是专心做事、练习技能，把手上的事做熟、做好。可以用“专注、练习、不断改进、细心”帮助记忆，不必逐字背下来。","en":"The Eight of Pentacles often concerns attentive work, learning a skill and caring about quality. The focus is becoming skilled and careful in what you do. Focus, skill learning, refinement and attention to detail can all help organize the meaning; you need not memorize a fixed list."},{"zh":"画面里，人物低头加工一枚星币，旁边已有多枚作品。正在做工帮助记住投入，多件作品帮助记住练习，手中加工帮助记住细节。‘他一定得到加薪’不是图中事实；‘检查后改进’是把牌义用在学习中的方法。","en":"The figure works on a pentacle, with several pieces nearby. Working supports the memory of effort; repeated pieces, practice; the craftwork, detail. A pay rise is not a pictured fact. Reviewing and improving is an application of the meaning to learning."},{"zh":"例子：小林练琴，总在同一小节出错。星币八可以这样给建议：先把总出错的那一小节单独拿出来慢练，找到错在哪里，改好后再连起来弹整首。一直从头弹到尾，却不管反复出现的错误，很难把这一处练好。","en":"Example: Lin keeps making a mistake in one musical passage. As Eight of Pentacles advice, isolate it, check the technique and then return it to the whole piece. Repeating the whole piece without addressing the mistake spends time but misses this example's improvement."}],"questions":{"Q1":{"id":"B06-Q1","prompt":{"zh":"小林总在同一小节出错。怎样练，才是在改进？","en":"Lin keeps making a mistake in the same passage. Which practice would help him improve?"},"options":[{"id":"B06-Q1-5dc4ee01fc","text":{"zh":"完全不检查，只增加重复次数","en":"Never review; only increase repetitions"},"feedback":{"zh":"只多弹几遍，却不检查错在哪里，同一个错误可能还会出现。","en":"This adds quantity without the improvement taught here."}},{"id":"B06-Q1-54ff8e0bbd","text":{"zh":"找出问题，练习并改进操作","en":"Find the difficulty, practise and improve technique"},"feedback":{"zh":"先找到错误，再练习改正，才能把总出错的这一小节练好。","en":"This preserves skill and quality."}}],"correct":"B06-Q1-54ff8e0bbd","support":"R1"},"Q2":{"id":"B06-Q2","prompt":{"zh":"哪项是牌图中可直接看见的？","en":"Which is directly visible in the picture?"},"options":[{"id":"B06-Q2-6deb7cd7ee","text":{"zh":"人物正在制作星币","en":"A figure working on a pentacle"},"feedback":{"zh":"这是可见动作。","en":"This is a visible action."}},{"id":"B06-Q2-5d9b934933","text":{"zh":"他已获得加薪","en":"He has received a pay rise"},"feedback":{"zh":"工资结果没有画在图里。","en":"A pay outcome is not depicted."}}],"correct":"B06-Q2-6deb7cd7ee","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"练很多遍，不一定就改好了。这个例子里同一处总出错，下一步要先找出错在哪里。","en":"Working often and improving can coexist, but they are not identical. The example explicitly gives a repeated error, so the advice must address it."}],"question":{"id":"B06-R1","prompt":{"zh":"练字总写歪同一笔，怎样练更能改正这一笔？","en":"When one stroke is repeatedly crooked, which action applies improvement?"},"options":[{"id":"B06-R1-33761f5a9c","text":{"zh":"不看结果地加写十页","en":"Add ten pages without looking at results"},"feedback":{"zh":"没有检查已知错误。","en":"This does not check the known error."}},{"id":"B06-R1-ba8697b386","text":{"zh":"单练那一笔，检查后再写","en":"Practise that stroke, review, then repeat"},"feedback":{"zh":"直接处理已知困难。","en":"This addresses the known difficulty."}}],"correct":"B06-R1-ba8697b386"}},"R2":{"teach":[{"zh":"先说看见的，再说用来理解的：看见加工动作；用它记住认真工作。收入提高还需要别的信息。","en":"Separate what is seen from how it helps: we see craftwork; we use it to remember attentive work. Higher income needs other information."}],"question":{"id":"B06-R2","prompt":{"zh":"旁边有多枚作品，就能确定每枚都更好吗？","en":"Do several finished pieces prove each is better than the last?"},"options":[{"id":"B06-R2-282b36e365","text":{"zh":"不能。能看见多件作品，但看不出哪件做得更好","en":"No, no quality comparison is shown"},"feedback":{"zh":"图上画出了多件作品，却没有告诉我们它们是不是一件比一件好。","en":"Quantity is visible; improvement piece by piece is not established."}},{"id":"B06-R2-413c06bcef","text":{"zh":"能","en":"Yes"},"feedback":{"zh":"这张牌可以帮助记住练习，但图画没有证明每次练习都进步了。","en":"This treats a practice theme as a verified result."}}],"correct":"B06-R2-282b36e365"}}},"revisit":{"id":"B06-V1","prompt":{"zh":"学摄影时只收藏教程，很少拍摄。哪项用上星币八的本课含义？","en":"A photography learner collects tutorials but rarely shoots. Which action uses this lesson's meaning?"},"options":[{"id":"B06-V1-0fd3e3ccbd","text":{"zh":"继续收藏，不开始练","en":"Keep collecting without practising"},"feedback":{"zh":"没有回应缺少实际练习的问题。","en":"It leaves the lack of practice unchanged."}},{"id":"B06-V1-1e723a719b","text":{"zh":"选一个技能实际拍摄，再检查照片","en":"Practise one skill by shooting and reviewing photographs"},"feedback":{"zh":"题目说很少实际拍摄，所以先动手拍，再检查哪里需要改。","en":"This applies effort, skill and quality to the context."}}],"correct":"B06-V1-1e723a719b"},"summary":{"zh":"本课把星币八的意思连到画面和实际练习。接下来分别学圣杯二和力量。","en":"This lesson connected the Eight of Pentacles to its picture and practical learning. Next, meet connection and gentle strength."},"cards":["p08"]},{"id":"B07","kind":"lesson","level":"B","title":{"zh":"认识圣杯二和力量","en":"Meet the Two of Cups and Strength"},"teachings":[{"zh":"先学圣杯二。它常说两个人愿意互相了解：表达自己的想法，也听对方怎么说。可以是朋友、合作伙伴或恋人。“互相回应、亲近、合作”能帮助记忆。图中两人面对面，各自拿着杯子，可以用来记住“彼此”。只有一方希望合作，还不等于双方已经说好了。","en":"First, Two of Cups: two participants form connection through expression and response, in friendship, collaboration or romance. Mutual response, connection and cooperation are useful cues. Two facing figures with cups support the memory of reciprocity; one person's hopes are not mutual commitment."},{"zh":"例子：同事讨论合作时，各自说出需要，也认真回应对方。建议可以是‘先交换想法，确认共同意愿’。它不保证对方一定接受你的邀请。","en":"Example: colleagues state their needs and respond to one another. Advice might be: exchange ideas and check shared willingness. It does not guarantee acceptance of an invitation."},{"zh":"再学力量。它强调面对强烈情绪或困难时的勇气、耐心和自我调节。人物以双手接触狮子，而非持武器搏斗，帮助记住不靠蛮力的应对。例子：方案被批评，先听清具体问题，再说清自己的理由，以及哪些要求不能接受。温和不等于无条件忍让。","en":"Next, Strength: courage, patience and self-regulation when facing strong feelings or difficulty. Hands meet the lion without a weapon, supporting the memory of a response without brute force. If a proposal is criticized, first understand the objection, then clearly state reasons and boundaries. Gentleness is not unconditional submission."}],"questions":{"Q1":{"id":"B07-Q1","prompt":{"zh":"圣杯二的本课例子，哪里能看出两个人都参与了交流？","en":"What makes the Two of Cups example reciprocal?"},"options":[{"id":"B07-Q1-a5e0d7ea17","text":{"zh":"双方都表达并回应","en":"Both express and respond"},"feedback":{"zh":"双方都说出想法，也听取对方的回应，不是只有一个人在说。","en":"Both sides participate in the connection."}},{"id":"B07-Q1-d77d303d76","text":{"zh":"一方独自想象对方答应","en":"One imagines the other has agreed"},"feedback":{"zh":"你希望对方答应，不代表对方已经答应。","en":"Hope supplies no response from the other person."}}],"correct":"B07-Q1-a5e0d7ea17","support":"R1"},"Q2":{"id":"B07-Q2","prompt":{"zh":"受到批评后，怎样做符合刚才讲的力量牌？","en":"Which response to criticism fits this lesson's Strength advice?"},"options":[{"id":"B07-Q2-8e6723cbb6","text":{"zh":"不管能不能接受，所有要求都答应","en":"Agree to everything and express no boundaries"},"feedback":{"zh":"耐心听别人说，不代表必须答应所有要求。","en":"Patience does not mean abandoning boundaries."}},{"id":"B07-Q2-2086eca223","text":{"zh":"听清问题，再平静说出自己的理由和不能接受的要求","en":"Understand the issue, then calmly state reasons and boundaries"},"feedback":{"zh":"没有回避问题，也没有急着争吵，而是先听清楚再表达自己。","en":"This faces the issue and regulates the response."}}],"correct":"B07-Q2-2086eca223","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"邀请是一个人的动作；形成相互回应还需要另一人的实际参与。","en":"An invitation is one person's action; reciprocity needs actual participation from the other."}],"question":{"id":"B07-R1","prompt":{"zh":"你发出了邀请但尚未收到回复，能确定双方已经达成共同意愿吗？","en":"You invited someone but have no reply. Is shared willingness established?"},"options":[{"id":"B07-R1-9cdae4bd98","text":{"zh":"尚不能","en":"Not yet"},"feedback":{"zh":"缺少对方回应。","en":"The other response is missing."}},{"id":"B07-R1-413c06bcef","text":{"zh":"能","en":"Yes"},"feedback":{"zh":"发出邀请只是你这一方的行动，还不知道对方怎么想。","en":"This turns one person's action into a mutual state."}}],"correct":"B07-R1-9cdae4bd98"}},"R2":{"teach":[{"zh":"力量提醒我们先稳住情绪，再面对问题。可以好好说话，也可以拒绝无法接受的要求；不需要为了显得温和而全答应。","en":"Strength's gentleness regulates a response; it does not mean accepting every request. Steady yourself while explaining reasons and what you cannot accept. Patience does not erase courage or boundaries."}],"question":{"id":"B07-R2","prompt":{"zh":"新例：组员临时要求你承担无法完成的额外工作。怎样用本课力量的建议？","en":"New example: a teammate requests extra work you cannot complete. How does this lesson's Strength advice apply?"},"options":[{"id":"B07-R2-cf080a85f4","text":{"zh":"为了显得温和，全部答应而不说能力范围","en":"Agree to everything to appear gentle, without stating capacity"},"feedback":{"zh":"明明做不完却全答应，既没有说明困难，也没有解决安排上的问题。","en":"This turns gentleness into unconditional submission and loses boundaries."}},{"id":"B07-R2-d8c98c7dfc","text":{"zh":"平静说明可承担的部分与限制，再讨论安排","en":"Calmly state your capacity and limits, then discuss arrangements"},"feedback":{"zh":"既没有生气回避，也没有勉强全接下来，而是把能做和不能做的说清楚。","en":"It retains patience, courage to face the issue and boundaries."}}],"correct":"B07-R2-d8c98c7dfc"}}},"revisit":{"id":"B07-V1","prompt":{"zh":"合作建议位是圣杯二。哪项回应合作问题？","en":"Two of Cups is advice for a collaboration. Which response addresses that question?"},"options":[{"id":"B07-V1-07abc0598e","text":{"zh":"彼此说出期待，确认共同目标","en":"Exchange expectations and check a shared goal"},"feedback":{"zh":"两个人都说出想法，再一起确认要做什么。","en":"This applies reciprocal communication."}},{"id":"B07-V1-994e87452f","text":{"zh":"只按自己的目标宣布对方同意","en":"Announce agreement based only on your own goals"},"feedback":{"zh":"缺少实际确认。","en":"Actual confirmation is missing."}}],"correct":"B07-V1-07abc0598e"},"summary":{"zh":"圣杯二帮助理解相互回应；力量帮助理解怎样面对困难。两张分别记住各自的意思就好。","en":"Two of Cups addresses reciprocal connection; Strength addresses facing difficulty. You have learned each separately, without forcing a comparison."},"cards":["c02","m08"]},{"id":"B08","kind":"lesson","level":"B","title":{"zh":"试着用一张牌给建议","en":"Give advice with one card"},"teachings":[{"zh":"读一张建议牌时，依次确认：本题问什么，这张牌本来的含义是什么，怎样把这个含义变成针对问题的做法。解释要符合刚学的牌义，也要回答原来的问题。建议说的是怎样做，不是保证一定会成功。","en":"For an advice card, identify the question, recall the card's meaning, then turn that meaning into an approach to the issue. Meaning cannot become any answer, and advice is not an outcome guarantee."},{"zh":"完整例子：朋友误会了我发的一条消息，这周我能先做什么？这次用圣杯二正位示范，牌位是“我能采取的第一步”。可以这样建议：先问朋友愿不愿意聊聊，说清自己的本意，也听听朋友当时是怎样理解的。如果朋友暂时不想谈，就先别强求。","en":"Worked example: a message caused a misunderstanding with a friend. How can I start repairing it this week? The upright position is My first step, illustrated by Two of Cups. Its reciprocity theme becomes: sincerely invite a conversation, explain your intention and invite the friend's perspective. If they do not want to talk yet, respect that response."},{"zh":"这回答的是你能做什么，并没有确认对方一定原谅你。学完后可以自己选新牌，也可以随机学一张。学过的牌，以后会换个例子再练。","en":"This answers what you can do; it does not establish that the friend will forgive you. Afterward, choose or randomly receive a new card; learned material returns later in a different context. You do not need to rate your memory: practice responses guide the help."}],"questions":{"Q1":{"id":"B08-Q1","prompt":{"zh":"朋友案例里，哪个句子回应‘第一步’？","en":"Which sentence answers the friend's case about a first step?"},"options":[{"id":"B08-Q1-440645bc97","text":{"zh":"对方必定已经原谅","en":"They have certainly forgiven you"},"feedback":{"zh":"这是未被提供的结果，不是第一步。","en":"That is an unprovided outcome, not a first step."}},{"id":"B08-Q1-ab384a82f6","text":{"zh":"邀请交流，也听对方的理解","en":"Invite a conversation and listen to their understanding"},"feedback":{"zh":"把双向回应转成可做的动作。","en":"This turns reciprocity into an action."}}],"correct":"B08-Q1-ab384a82f6","support":"R1"},"Q2":{"id":"B08-Q2","prompt":{"zh":"朋友暂时不想谈，怎样做才顾及双方的意愿？","en":"If the friend does not want to talk yet, which response preserves reciprocity?"},"options":[{"id":"B08-Q2-231fb471fa","text":{"zh":"尊重回应，暂不强求","en":"Respect the response without forcing"},"feedback":{"zh":"对方的意愿也是双向关系的一部分。","en":"Their willingness is part of reciprocity."}},{"id":"B08-Q2-cbc730ac96","text":{"zh":"持续追问直到同意","en":"Keep pressing until they agree"},"feedback":{"zh":"只顾自己想谈，没有听取朋友暂时不想谈的回应。","en":"This replaces mutual participation with pressure."}}],"correct":"B08-Q2-231fb471fa","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"建议句回答‘我可以做什么’，不是‘别人一定会怎样’。","en":"Advice answers what I can do, not what someone else will certainly do."}],"question":{"id":"B08-R1","prompt":{"zh":"哪句是建议？","en":"Which is advice?"},"options":[{"id":"B08-R1-f7d6772b6a","text":{"zh":"朋友明天一定回复","en":"The friend will definitely reply tomorrow"},"feedback":{"zh":"是没有依据的他人结果。","en":"It is an unsupported outcome involving someone else."}},{"id":"B08-R1-512cff4527","text":{"zh":"先把自己的本意说清","en":"First explain your intention clearly"},"feedback":{"zh":"是自己的行动。","en":"It is your own action."}}],"correct":"B08-R1-512cff4527"}},"R2":{"teach":[{"zh":"双向不等于双方必须同意；它要求听见彼此真实回应。","en":"Reciprocity does not require agreement; it requires attending to each person's actual response."}],"question":{"id":"B08-R2","prompt":{"zh":"合作伙伴说需要时间考虑，接下来怎样做比较合适？","en":"A partner needs time to consider. Which respects that response?"},"options":[{"id":"B08-R2-7ac4391c1c","text":{"zh":"约定合适时间再确认","en":"Agree on a suitable time to check back"},"feedback":{"zh":"让对方有时间考虑，之后再一起决定。","en":"This leaves room for participation."}},{"id":"B08-R2-99e9151a14","text":{"zh":"立刻宣布合作已成","en":"Announce the collaboration is settled"},"feedback":{"zh":"对方还没答应，不能宣布双方已经同意合作。","en":"This skips the agreement not yet reached."}}],"correct":"B08-R2-7ac4391c1c"}}},"revisit":{"id":"B08-V1","prompt":{"zh":"换成备考问题，建议位是已经学过的星币八。哪项符合这张牌刚才讲的意思？","en":"For exam preparation, the advice card is the already-learned Eight of Pentacles. Which retains its meaning?"},"options":[{"id":"B08-V1-3ee0a6df65","text":{"zh":"只要抽到这张便可停止准备","en":"Stop preparing because you drew this card"},"feedback":{"zh":"违背了实际投入的主题。","en":"This contradicts practical effort."}},{"id":"B08-V1-c766072bc4","text":{"zh":"针对薄弱题型练习，检查错误","en":"Practise weak areas and review mistakes"},"feedback":{"zh":"针对不会的题多练，再检查错误，符合认真练习、不断改进的意思。","en":"It preserves practice and quality."}}],"correct":"B08-V1-c766072bc4"},"summary":{"zh":"你已完成第一次建议牌解读。接下来可以自选一张新牌，也可以继续中级，学习更完整的单牌方法。","en":"You have completed your first advice-card interpretation. Next, choose a new card or continue to the intermediate lessons for fuller card study."},"cards":["c02"]},{"id":"I01","kind":"lesson","level":"I","title":{"zh":"怎样读懂一张牌","en":"How to understand a card"},"teachings":[{"zh":"先学完整意思，再用关键词整理。每张牌看六件事：主要含义、帮助记忆的画面、关键词各指什么、花色、数字或宫廷角色怎样帮助记忆、放进问题怎样使用、哪些说法没有依据。关键词可以多种措辞，但核心主题不能随意改变。","en":"Learn the full meaning, then organize it with keywords. Examine six things: the main meaning, visual memory cues, what the keywords mean, structural aids, use in a question, and unsupported claims. Wording can vary; the central theme cannot change arbitrarily."},{"zh":"星币八讲的是认真做事、练习技能，把手上的活做好。“专注、练习、不断改进、细心”分别帮你记住其中一部分。可以借图中的工匠和作品记忆；星币对应土，也能帮助你想起动手做事。数字只用来帮助记忆，不能代替这张牌的完整意思。","en":"Eight of Pentacles means attentive practical work, learning and refining a craft, and caring for quality. Focus, learning, refinement and detail name aspects of that meaning. The craftsperson and pieces support memory; Earth prompts practical effort; the number is an index, not a substitute for this explanation."},{"zh":"小林只购买摄影器材，很少练构图。建议位的星币八可解释为：固定一个构图任务，拍摄、检查、针对问题重拍。这是根据背景做出的应用，不是图里写着必须拍几次。大阿尔卡纳也沿用此方法：先学每张的意思，以后也可以把大牌串成故事来复习。常说的“愚人旅程”就是一种串故事的方式；现在不用学，故事也不能代替每张牌本身。","en":"Lin buys photography equipment but rarely practices composition. In an advice position, Eight of Pentacles can suggest choosing a composition task, taking photographs, checking them and retaking them to address problems. This applies the meaning to the context; the image does not prescribe a number of attempts. Learn each Major card first. Later, a story such as the Fool’s Journey can help review them; you do not need that story now, and it does not replace individual meanings."}],"questions":{"Q1":{"id":"I01-Q1","prompt":{"zh":"‘认真练习，把手艺练好’没逐字说出教材关键词，是否仍保留星币八核心？","en":"Does 'careful practice and refining a skill' retain the meaning without quoting the keywords?"},"options":[{"id":"I01-Q1-b5141d3d19","text":{"zh":"是","en":"Yes"},"feedback":{"zh":"虽然换了说法，仍是在说认真练习、把事做好。","en":"The wording differs, but effort and skilled quality remain."}},{"id":"I01-Q1-c004bcb868","text":{"zh":"否，必须逐字背诵","en":"No, exact quotation is required"},"feedback":{"zh":"意思说对就可以，不必和教材一字不差。","en":"This lesson checks meaning, not an exact phrase."}}],"correct":"I01-Q1-b5141d3d19","support":"R1"},"Q2":{"id":"I01-Q2","prompt":{"zh":"摄影例子中，哪项同时回应背景与牌义？","en":"Which responds to both the photography context and the card?"},"options":[{"id":"I01-Q2-cc4576acdd","text":{"zh":"继续买设备，技能会自动提高","en":"Keep buying equipment; skills improve automatically"},"feedback":{"zh":"设备购买没有替代技能练习。","en":"Equipment does not replace practice."}},{"id":"I01-Q2-a0ad28ebf3","text":{"zh":"围绕构图拍摄、检查和修改","en":"Shoot, review and adjust composition"},"feedback":{"zh":"处理了缺少实践的困难。","en":"It addresses the lack of practice."}}],"correct":"I01-Q2-a0ad28ebf3","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"关键词是帮你记意思的，换种说法也可以。只要仍然说清认真练习、把手上的事做好，就不需要逐字照背。","en":"Keywords help retrieve meaning; exact wording is not required. Judge a paraphrase by whether it retains attentive effort, skill learning and quality, not by identical words."}],"question":{"id":"I01-R1","prompt":{"zh":"新例：小周把星币八解释为‘专心做实际练习，慢慢把手艺磨好’，没有照抄词表。这种表达可以吗？","en":"New example: Zhou explains Eight of Pentacles as 'concentrated hands-on practice to gradually refine a craft' without quoting the list. Is that acceptable?"},"options":[{"id":"I01-R1-307a5ebee0","text":{"zh":"可以，保留了投入、技能与改进","en":"Yes; it retains effort, skill and improvement"},"feedback":{"zh":"换了说法，意思没有变。","en":"The paraphrase conveys the full theme."}},{"id":"I01-R1-e628030caa","text":{"zh":"不可以，没有逐字说出词表","en":"No; it does not quote the exact list"},"feedback":{"zh":"不必逐字照背；只要意思没变，就不算错。","en":"This mistakes a memory aid for a required formula rather than checking understanding."}}],"correct":"I01-R1-307a5ebee0"}},"R2":{"teach":[{"zh":"小林已经有设备，却很少拍照。问题不在工具不够，而在还没动手练。这里的星币八建议他先实际拍摄，再检查和修改，并不是说不能买工具。","en":"Equipment can support practice, but the question says Lin rarely takes photographs; further purchases do not fill that gap. In this example, Eight of Pentacles emphasizes doing, reviewing and improving, not banning tools."}],"question":{"id":"I01-R2","prompt":{"zh":"新例：小周已有能正常使用的吉他，却只浏览设备评测，很少弹奏。接下来怎样做符合刚才的建议？","en":"New example: Zhou has a working guitar but mostly reads equipment reviews and rarely plays. How can this lesson's advice be applied?"},"options":[{"id":"I01-R2-3d6e603376","text":{"zh":"先继续比较更多设备，仍不安排弹奏","en":"Compare more equipment first, still without scheduling playing"},"feedback":{"zh":"工具已能使用，继续比较仍未回应缺少实际练习。","en":"The instrument works; more comparison still does not address the missing practice."}},{"id":"I01-R2-2de99b6200","text":{"zh":"选一个和弦转换练习，听录音检查，再修正","en":"Practise one chord transition, listen to a recording and adjust"},"feedback":{"zh":"他缺的是实际弹奏。先练，再听录音检查，正好解决这个问题。","en":"This applies skill practice and quality review to the stated gap."}}],"correct":"I01-R2-2de99b6200"}}},"revisit":{"id":"I01-V1","prompt":{"zh":"学写作时，哪项保留同一核心？","en":"In learning to write, which retains the same theme?"},"options":[{"id":"I01-V1-bbfbaedb46","text":{"zh":"写一段，检查结构，再修改","en":"Write a paragraph, review its structure and revise"},"feedback":{"zh":"先写、再检查和修改，也是在通过实际练习把事情做得更好。","en":"It transfers skill and quality to a new area."}},{"id":"I01-V1-e8cf66c237","text":{"zh":"凭星币八确定出版日期","en":"Use the card to establish a publication date"},"feedback":{"zh":"单牌核心不提供这个日期。","en":"The core meaning provides no such date."}}],"correct":"I01-V1-bbfbaedb46"},"summary":{"zh":"你可以用相同框架理解不同牌，不必让每张牌拥有相同数量的词。","en":"You can use a consistent framework without giving every card the same number of keywords."},"cards":["p08"]},{"id":"I02","kind":"lesson","level":"I","title":{"zh":"读懂圣杯十","en":"Understand the Ten of Cups"},"teachings":[{"zh":"圣杯十常说：和重要的人相处融洽，大家在一起感到开心、安心，觉得自己被接纳。可以是恋人、家人，也可以是一群相处得好的朋友。可以用“和睦、归属感、一起幸福”帮助记忆。它不只是在说有钱，也不要求你的生活和图中的家庭一模一样。","en":"Ten of Cups emphasizes shared fulfillment and belonging through emotional connection—in close relationships, family or an accepting group. Harmony, belonging and shared happiness are useful cues. It is not success defined solely by wealth or a requirement to copy the pictured family."},{"zh":"图上有两位成人、两个孩子，远处有房屋，头顶是杯子组成的彩虹。把这些画面放在一起，可以帮助记住“一家人共享幸福”。圣杯让人想到感受和关系；十帮助记住一件事已经发展到后面的阶段。不过，幸福是这张牌本身的含义，不是只凭“水加十”算出来的，更算不出结婚日期。","en":"Adults, children, a distant home and the rainbow of cups support memory of sharing. Cups concerns feelings and relationships; Ten may suggest a developed stage. Neither cue alone establishes happiness or a wedding date. Shared fulfillment is the individual meaning you have been taught."},{"zh":"一群朋友准备办相识周年聚会，问怎样让大家玩得开心、没人被冷落。圣杯十可以这样给方向：一起回忆这些年的经历，让每个人都有参与的机会，感到自己是大家的一员。它没有告诉我们会来多少人；相处融洽也不等于所有人想法都一样。","en":"Friends are planning an anniversary gathering and ask how to make it enjoyable without leaving anyone out. Ten of Cups can suggest recalling shared experiences and giving everyone a chance to join in and feel included. It does not specify attendance; harmony does not require identical opinions."}],"questions":{"Q1":{"id":"I02-Q1","prompt":{"zh":"圣杯十说的幸福，重点是什么？","en":"What is distinctive about fulfillment in this lesson's Ten of Cups?"},"options":[{"id":"I02-Q1-bf1c4837b9","text":{"zh":"仅表示账户金额增长","en":"Only an increased account balance"},"feedback":{"zh":"账户有多少钱，不能说明和重要的人相处得怎样。","en":"This replaces an emotional theme with a sum of money."}},{"id":"I02-Q1-fdb39a06fe","text":{"zh":"和在意的人一起感到幸福、相处融洽","en":"Shared experience among emotionally connected people"},"feedback":{"zh":"重点是大家在一起感到开心、被接纳，不只是一个人拥有很多东西。","en":"It preserves sharing and belonging."}}],"correct":"I02-Q1-fdb39a06fe","support":"R1"},"Q2":{"id":"I02-Q2","prompt":{"zh":"只凭水＋十，能确定下个月结婚吗？","en":"Can Water plus Ten establish a wedding next month?"},"options":[{"id":"I02-Q2-6c47574119","text":{"zh":"不能","en":"No"},"feedback":{"zh":"知道元素和数字，不能算出婚期。","en":"Structure supplies neither event nor date."}},{"id":"I02-Q2-413c06bcef","text":{"zh":"能","en":"Yes"},"feedback":{"zh":"水和十是帮助记忆的，不能用来计算下个月会发生什么。","en":"This treats cues as an event formula."}}],"correct":"I02-Q2-6c47574119","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"这里说的幸福，是大家在一起相处得好，不只是一个人得到了什么。","en":"Look for shared experience: fulfillment here concerns connection between people, not one person possessing a prize."}],"question":{"id":"I02-R1","prompt":{"zh":"怎样安排聚会，更符合刚才讲的意思？","en":"Which gathering goal applies that meaning?"},"options":[{"id":"I02-R1-0194149a05","text":{"zh":"只统计主人拥有多少物品","en":"Count only the host's possessions"},"feedback":{"zh":"只数主人有多少东西，看不出朋友们相处得开不开心。","en":"It does not express shared feeling."}},{"id":"I02-R1-c6793c4105","text":{"zh":"让每个人都能参与，一起回忆共同经历","en":"Help everyone feel accepted and share experiences"},"feedback":{"zh":"让每个人都感到自己是大家的一员。","en":"It directly expresses belonging."}}],"correct":"I02-R1-c6793c4105"}},"R2":{"teach":[{"zh":"水帮助记情感与关系，十帮助记阶段性状态；两者没有给出事件日期。若要知道何时聚会，要看现实安排，不能把牌号换算成天数。","en":"Water helps organize feelings and relationships; Ten cues a stage. Neither gives an event date. A gathering's date comes from real arrangements, not converting the rank into days."}],"question":{"id":"I02-R2","prompt":{"zh":"新例：朋友尚未定聚会日期，抽到圣杯十。能因编号十就断定十天后聚会吗？","en":"New example: friends have not set a gathering date and draw Ten of Cups. Does its rank establish a gathering ten days later?"},"options":[{"id":"I02-R2-f24faf05ef","text":{"zh":"不能。它讲的是大家相处的感受，聚会日期还要另定","en":"No; retain shared fulfillment and confirm the date separately"},"feedback":{"zh":"区分了牌义和未提供的时间信息。","en":"This separates meaning from the missing timing information."}},{"id":"I02-R2-60afcfd6b0","text":{"zh":"能，十固定等于十天","en":"Yes; Ten always means ten days"},"feedback":{"zh":"把数字提示变成没有依据的日期公式。","en":"This turns a number cue into an unsupported date formula."}}],"correct":"I02-R2-f24faf05ef"}}},"revisit":{"id":"I02-V1","prompt":{"zh":"工作团队庆祝合作完成，能用圣杯十讨论归属吗？","en":"Can Ten of Cups discuss belonging when a work team celebrates completion?"},"options":[{"id":"I02-V1-6f557bb474","text":{"zh":"不能，圣杯不能进工作题","en":"No, Cups cannot appear in work questions"},"feedback":{"zh":"同事一起完成工作也会感到开心，不能把圣杯只用于恋爱。","en":"This wrongly restricts the suit to one domain."}},{"id":"I02-V1-eb8023ddda","text":{"zh":"能。同事也会因为一起完成工作而开心","en":"Yes, work also involves emotional connections"},"feedback":{"zh":"这里也在说大家一起完成一件事、分享开心的感受。","en":"It preserves the core of shared experience."}}],"correct":"I02-V1-eb8023ddda"},"summary":{"zh":"先有单牌含义，再让元素和数字帮助整理。接下来把这个方法用于宫廷牌。","en":"Begin with the individual meaning; let element and number organize it. Next, apply this to court cards."},"cards":["c10"]},{"id":"I03","kind":"lesson","level":"I","title":{"zh":"把宫廷牌放进问题里","en":"Read court cards in a question"},"teachings":[{"zh":"四种角色与四花色形成 16 张宫廷牌。角色帮助你记住怎样做事，花色帮助你记住在关注什么。侍从开始学习，骑士主动追求，王后关心需要、给予照顾，国王安排事情、承担责任。记住这些以后，每张宫廷牌的具体意思仍要单独学。","en":"Four roles across four suits make sixteen courts. The role suggests an approach; the suit suggests a focus. Pages learn, Knights pursue, Queens understand and care, Kings coordinate and take responsibility. This is an index; each card still has its own meaning."},{"zh":"圣杯骑士常说愿意为自己的感受或理想主动做些什么，比如温和地表达心意、发出邀请，或追求向往的事情。骑士拿着杯子向前，可以帮你记住“主动表达”。可以记“表达心意、浪漫、追求理想”。不过，说出心意，还不等于以后一直做得到。","en":"Knight of Cups is moved by feeling or an ideal, expressing, inviting or pursuing in a gentle, appealing way. The mounted figure holding a cup helps recall bringing feeling outward. Expression, romance and pursuit of ideals summarize aspects, but expression is not yet lasting commitment."},{"zh":"问‘怎样邀请朋友谈误会’，建议可说：告诉朋友自己想把误会说开，再问对方是否愿意找时间聊聊。若问‘活动氛围’，可强调理想与情绪体验。两种说法都来自同一含义，由问题决定应用方向；不能跳成某个年龄的男人必定出现。","en":"Asked how to invite a friend to discuss a misunderstanding, advice can be: gently express a wish to repair and ask whether they would like to talk. Asked about an event's atmosphere, the same card can emphasize ideals and emotional experience. The question selects the use of the same meaning; it does not establish that a man of a certain age will appear."}],"questions":{"Q1":{"id":"I03-Q1","prompt":{"zh":"本课用圣杯骑士描述的，首先是哪类信息？","en":"What kind of information does Knight of Cups primarily describe in this lesson?"},"options":[{"id":"I03-Q1-0039de8d3c","text":{"zh":"一种表达或追求方式","en":"A way of expressing or pursuing"},"feedback":{"zh":"这正是本课所讲的重点。","en":"This is the taught emphasis."}},{"id":"I03-Q1-a98741c48e","text":{"zh":"对方已作出终身承诺","en":"The other person has made a lifelong commitment"},"feedback":{"zh":"长期承诺需要额外信息。","en":"Lasting commitment needs additional information."}}],"correct":"I03-Q1-0039de8d3c","support":"R1"},"Q2":{"id":"I03-Q2","prompt":{"zh":"问‘我怎样邀请朋友’，哪项回应了问句？","en":"For 'How should I invite my friend?', which responds to the question?"},"options":[{"id":"I03-Q2-fca28ed69e","text":{"zh":"断定会出现一个特定性别的人","en":"Predict a person of a specified gender"},"feedback":{"zh":"改变了问题对象，也加入身份推断。","en":"It changes the subject and adds an identity claim."}},{"id":"I03-Q2-4873433dc4","text":{"zh":"好好说出想把误会说开，再问朋友愿不愿意聊聊","en":"Gently express a wish to repair and ask their willingness"},"feedback":{"zh":"说的是自己怎样发出邀请，正好回答“我怎样邀请朋友”。","en":"It applies an approach to your own action."}}],"correct":"I03-Q2-4873433dc4","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"‘会表达’和‘长期做到’是不同信息。邀约是起点，承诺需要持续行为支持。","en":"Being expressive and following through long term are different information. An invitation begins contact; commitment needs sustained behaviour."}],"question":{"id":"I03-R1","prompt":{"zh":"一封浪漫邀请能保证今后一直合作吗？","en":"Does a romantic invitation guarantee lasting cooperation?"},"options":[{"id":"I03-R1-6c47574119","text":{"zh":"不能","en":"No"},"feedback":{"zh":"表达不等于长期落实。","en":"Expression is not sustained follow-through."}},{"id":"I03-R1-413c06bcef","text":{"zh":"能","en":"Yes"},"feedback":{"zh":"从风格跳到了保证。","en":"This jumps from style to guarantee."}}],"correct":"I03-R1-6c47574119"}},"R2":{"teach":[{"zh":"先看问题在问什么。如果问活动氛围，就说这场活动给人的感受，不要突然改成猜主办人是谁。","en":"First check whether the question concerns a person, an action or an atmosphere. Then choose that level of expression."}],"question":{"id":"I03-R2","prompt":{"zh":"问题是“这场活动的氛围怎样”。哪句话在回答它？","en":"For an event's atmosphere, which matches the taught level?"},"options":[{"id":"I03-R2-c716a293a2","text":{"zh":"必须是一位男性举办","en":"It must be hosted by a man"},"feedback":{"zh":"角色并不提供主办者性别。","en":"The role does not supply the host's gender."}},{"id":"I03-R2-daf062e6d5","text":{"zh":"大家愿意表达感受，也一起畅想想做的事","en":"It emphasizes emotional experience and an appealing ideal"},"feedback":{"zh":"在描述氛围。","en":"It describes atmosphere."}}],"correct":"I03-R2-daf062e6d5"}}},"revisit":{"id":"I03-V1","prompt":{"zh":"为社团发合作邀请，圣杯骑士建议怎样表达？","en":"How might Knight of Cups advise inviting another club to collaborate?"},"options":[{"id":"I03-V1-15fcb2fcef","text":{"zh":"真诚说出想一起做什么，再听听对方愿不愿意","en":"Express the shared ideal sincerely and allow a choice"},"feedback":{"zh":"延续温和邀请，未保证接受。","en":"It retains a gentle invitation without guaranteeing acceptance."}},{"id":"I03-V1-cdff079806","text":{"zh":"宣布对方一定愿意，不必询问","en":"Declare they agree without asking"},"feedback":{"zh":"跳过真实回应。","en":"It bypasses their actual response."}}],"correct":"I03-V1-15fcb2fcef"},"summary":{"zh":"先学清这张牌的意思，再看问题是在问一个人、下一步怎样做，还是活动的气氛。下一课开始理解逆位。","en":"Role and suit offer an entry point; the question determines the level of expression. Next, learn reversals."},"cards":["c12"]},{"id":"I04","kind":"lesson","level":"I","title":{"zh":"逆位应该怎样读","en":"How to read reversals"},"teachings":[{"zh":"逆位是指抽出的牌图倒着。它的意思不一定和正位相反，也不一定是坏结果。不同传统有不同处理方式。本课程保留牌的主题，再结合背景、问题和牌位判断变化：可能是这件事做不起来、做过了头，或想在心里还没表现出来，也可能是原来的困难正在减轻。它们不是每张牌都适用的固定清单，更不能全部同时当结论。","en":"Reversed first describes orientation, not an opposite meaning or a bad outcome. Traditions differ. Here retain the card's theme, then use context, question and position to identify a change: blockage, excess, an inward expression, or easing of an existing difficulty. These are not a universal checklist for every card or simultaneous conclusions."},{"zh":"一个先讲清的小例子：宝剑九正位常涉及忧虑、反复想着令人不安的事。虚构背景是活动负责人原来不断担忧，但在分工确定、沟通之后，担忧开始减少。此时若用宝剑九逆位作教学解释，可以读为原有忧虑正在缓解；这是结合已经给出的改善背景，不是见到逆位就保证问题消失。这个例子供理解，不要求现在记住一张新牌的全部含义。","en":"A fully explained example: upright Nine of Swords often concerns worry and repeatedly dwelling on distressing matters. In this fictional context, an event organizer had recurring worries, but clearer responsibilities and communication have reduced them. Reversed Nine of Swords can then be taught as worry beginning to ease. This follows the supplied improvement in context; reversal alone does not guarantee the problem has disappeared. This example illustrates the idea, without requiring the whole meaning of a new card now."},{"zh":"读星币八逆位，仍然围绕练习和做事来理解，但要看具体发生了什么。例 A：报名后一直没练，问题是还没有动手。例 B：每天练，却从不检查反复出现的错误，问题可能是练法需要改。例 C：作品已符合要求，却一直改细节不交，这时才适合说改得太多、耽误了完成。这些情况由题目告诉我们，不能只凭逆位断定。","en":"For reversed Eight of Pentacles, retain effort, skill and quality. A: enrolled but never practised—effort is not implemented. B: practises daily but never reviews repeated errors—the method is ineffective. C: meets requirements but endlessly revises and never submits—over-refinement is supported. The context is supplied, not proved by the reversal."},{"zh":"这次看例 B：他每天都练，但没有找出并纠正反复出现的错误。可以建议他先选一个总出错的地方，找到原因，再换个方法练。题目已经说他每天在练，所以不能说他完全没练，也不能保证改完马上得奖。","en":"Now read case B: the learner practices daily but has not identified and corrected recurring errors. Advice can be to choose one repeated mistake, find its cause and try a different practice method. Saying they never practice contradicts the context; there is no basis for promising an immediate prize."}],"questions":{"Q1":{"id":"I04-Q1","prompt":{"zh":"每天练却不检查错误，哪项与背景一致？","en":"With daily practice but no error review, which fits the context?"},"options":[{"id":"I04-Q1-7e9d736186","text":{"zh":"从未投入任何练习","en":"No practice has ever happened"},"feedback":{"zh":"与每天练习矛盾。","en":"It contradicts daily practice."}},{"id":"I04-Q1-afd9940233","text":{"zh":"一直在练，但没有改掉反复出现的错误","en":"Effort is not effectively producing improvement"},"feedback":{"zh":"既承认投入，也指出缺少检查。","en":"It acknowledges effort and identifies missing review."}}],"correct":"I04-Q1-afd9940233","support":"R1"},"Q2":{"id":"I04-Q2","prompt":{"zh":"只有一张逆位，没有问题或背景，能确定是哪种变化吗？","en":"With only a reversed card and no context, can you identify the exact change?"},"options":[{"id":"I04-Q2-65d1065927","text":{"zh":"不能。还要知道发生了什么，才能判断","en":"No, context is needed to narrow it"},"feedback":{"zh":"朝向没有提供现实细节。","en":"Orientation supplies no real-world details."}},{"id":"I04-Q2-36dc054e35","text":{"zh":"能，逆位一律过度努力","en":"Yes, all reversals mean excessive effort"},"feedback":{"zh":"把一种可能误作通用规律。","en":"This turns one possibility into a universal rule."}}],"correct":"I04-Q2-65d1065927","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"题目已经说他每天都练，就不能再说他完全没练。再看怎样练，才能改掉错误。","en":"Keep the stated fact: daily practice rules out no practice. Then use the card to discuss quality."}],"question":{"id":"I04-R1","prompt":{"zh":"每天练字但不看字形，优先补什么？","en":"Practising handwriting daily without looking at letter forms: what is missing first?"},"options":[{"id":"I04-R1-0b2eb67afb","text":{"zh":"假设从未动笔","en":"Assume no writing happened"},"feedback":{"zh":"否认已有练习。","en":"It denies the given practice."}},{"id":"I04-R1-10a5887a73","text":{"zh":"检查并修正字形","en":"Review and correct the forms"},"feedback":{"zh":"题目说不看字形，所以要先检查，再改正。","en":"It addresses the stated gap."}}],"correct":"I04-R1-10a5887a73"}},"R2":{"teach":[{"zh":"同一个技能主题，问题可能在开始投入，也可能在投入方法。不能在没有背景时任选一个当事实。","en":"Within the same skill theme, the issue may be starting practice or its method. Without context, neither is established as fact."}],"question":{"id":"I04-R2","prompt":{"zh":"要区分两种情况，哪条信息有帮助？","en":"Which information helps distinguish them?"},"options":[{"id":"I04-R2-a8e062be23","text":{"zh":"实际有没有练、怎样练","en":"Whether and how practice occurs"},"feedback":{"zh":"直接区分投入与方法。","en":"It distinguishes effort from method."}},{"id":"I04-R2-010c05a8cc","text":{"zh":"把逆位再旋转一次","en":"Rotate the card again"},"feedback":{"zh":"旋转不会补充背景。","en":"Rotation does not add context."}}],"correct":"I04-R2-a8e062be23"}}},"revisit":{"id":"I04-V1","prompt":{"zh":"作品已经达标却一直改小细节不交，哪项符合题目说的情况？","en":"Work meets requirements but endless tiny revisions prevent submission. Which is supported?"},"options":[{"id":"I04-V1-b45fd4bd6a","text":{"zh":"从未认真处理作品","en":"The work was never attended to"},"feedback":{"zh":"与反复修改不符。","en":"It conflicts with repeated revision."}},{"id":"I04-V1-f3f088c862","text":{"zh":"小细节一直改，反而迟迟交不了作品","en":"Refinement is unbalanced and obstructs completion"},"feedback":{"zh":"作品已达标，却仍因小细节交不出去，和刚才的例 C 一样。","en":"It matches C's conditions."}}],"correct":"I04-V1-f3f088c862"},"summary":{"zh":"同一张逆位牌，要结合发生的事情来读。有时是做不起来或做过头，也可能是原来的困难在减轻；不能只选自己喜欢的解释。","en":"The same reversed card is read in context. Sometimes something is blocked or overdone; sometimes an earlier difficulty is easing. Choose an interpretation supported by the situation, not simply the one you prefer."},"cards":["s09","p08"]},{"id":"I05","kind":"lesson","level":"I","title":{"zh":"同一张牌，换个问题怎么读","en":"Read one card in different questions"},"teachings":[{"zh":"现状位回答“现在怎么样”，建议位回答“接下来怎样做”，趋势位回答“照这样下去，可能怎样发展”。牌本身的意思不变，重点随着它要回答的问题改变。","en":"Situation describes what is happening; advice suggests an approach; tendency discusses possible development under current conditions. These give the meaning different tasks, not permission to change it arbitrarily."},{"zh":"小林准备两个月后的作品展，正在练摄影。星币八放在现状位，可以说他正在认真练摄影；放在建议位，可以说按展览要求练习、改好照片细节；放在趋势位，可以说继续认真练和改，摄影水平和作品有望逐步改善，但不能保证获奖。三种说法都围绕认真练习、把事做好。","en":"Lin is practising photography for an exhibition in two months. Eight of Pentacles as situation: a phase of skill training. As advice: practise to the exhibition's needs and refine details. As tendency: a direction of improving skill and quality, not a guaranteed prize. All three retain the same theme."},{"zh":"换成沟通问题，建议可以是练习明确表达并确认对方理解；换成备考，则是针对薄弱题型练习。障碍位回答“什么在妨碍这件事”。如果星币八在这里，要先看看有没有只顾改一小部分、却迟迟没做完整件事的情况，不能一看是障碍位就说努力错了。","en":"For communication, advice could be to practice expressing yourself clearly and checking how the other person understood it; for an exam, practice weaker question types. An obstacle position asks what is getting in the way. With Eight of Pentacles here, check whether attention to one small part is delaying completion of the whole task; the position alone does not mean effort is wrong."}],"questions":{"Q1":{"id":"I05-Q1","prompt":{"zh":"在作品展的建议位，哪句话是在说下一步怎样做？","en":"Which sentence fulfills the advice position for the exhibition?"},"options":[{"id":"I05-Q1-3bf61c0e48","text":{"zh":"按展示要求练习和完善细节","en":"Practise and refine details to meet exhibition needs"},"feedback":{"zh":"给出与牌义一致的做法。","en":"It offers an approach consistent with the card."}},{"id":"I05-Q1-66501ab99f","text":{"zh":"你以前练过很多","en":"You practised a lot previously"},"feedback":{"zh":"这是过去描述，没有回答下一步做法。","en":"This describes the past rather than the next approach."}}],"correct":"I05-Q1-3bf61c0e48","support":"R1"},"Q2":{"id":"I05-Q2","prompt":{"zh":"星币八在障碍位，就能断定过度努力吗？","en":"Does Eight of Pentacles in an obstacle position establish excessive effort?"},"options":[{"id":"I05-Q2-7b2eed8f9b","text":{"zh":"能，障碍位都会把牌反过来","en":"Yes, obstacle positions reverse every meaning"},"feedback":{"zh":"位置不是自动反义开关。","en":"Position is not an automatic opposite switch."}},{"id":"I05-Q2-ac1e5bc0c6","text":{"zh":"不能，还要核对背景","en":"No, check the context"},"feedback":{"zh":"位置不提供缺少的现实情况。","en":"A position does not supply missing facts."}}],"correct":"I05-Q2-ac1e5bc0c6","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"用句子的任务检查：‘现在正……’是描述，‘接下来可以……’是建议。","en":"Check the sentence's task: 'Currently…' describes; 'Next, you could…' advises."}],"question":{"id":"I05-R1","prompt":{"zh":"问下一步怎样备考，哪句更直接？","en":"For the next step in exam preparation, which is direct?"},"options":[{"id":"I05-R1-c41347ece6","text":{"zh":"针对薄弱题型练习并查错","en":"Practise weak question types and review errors"},"feedback":{"zh":"给出下一步。","en":"It gives a next step."}},{"id":"I05-R1-5e3490b965","text":{"zh":"你之前买了资料","en":"You previously bought materials"},"feedback":{"zh":"只描述过去，而且购买并非牌所证明。","en":"It only describes the past; the purchase is not proved by the card."}}],"correct":"I05-R1-c41347ece6"}},"R2":{"teach":[{"zh":"如果有人一直改同一张照片，却还没准备整场展览，才可以说他被这一张照片拖住了。如果他只是刚开始练习，就不能直接这样判断。","en":"If someone refines one photograph but never organizes the exhibition, detail blocking the whole has support. If they just began training, that conclusion may not fit."}],"question":{"id":"I05-R2","prompt":{"zh":"哪种情况说明，一直改细节已经耽误了整场展览？","en":"Which fact supports this obstacle reading?"},"options":[{"id":"I05-R2-66f1712c48","text":{"zh":"仅知道牌在障碍位","en":"Only knowing the obstacle position"},"feedback":{"zh":"仍缺少实际表现。","en":"Actual behaviour is still missing."}},{"id":"I05-R2-d61c417e7b","text":{"zh":"一直改同一张照片，还没开始整理整组展览照片","en":"Revising one image while never organizing the set"},"feedback":{"zh":"一直改一张照片，却没有准备整场展览，确实耽误了原本要做的事。","en":"It shows effort disconnected from the overall goal."}}],"correct":"I05-R2-d61c417e7b"}}},"revisit":{"id":"I05-V1","prompt":{"zh":"用星币八给沟通建议，哪项符合认真练习、不断改进的意思？","en":"Which retains Eight of Pentacles in communication advice?"},"options":[{"id":"I05-V1-88d5527893","text":{"zh":"练习明确表达，核对理解并调整","en":"Practise clear expression, check understanding and adjust"},"feedback":{"zh":"将技能练习用于沟通。","en":"It applies practice to communication."}},{"id":"I05-V1-eeaf986a0c","text":{"zh":"一看到星币就改问工资","en":"Change the question to salary because it is Pentacles"},"feedback":{"zh":"花色不能擅自替换原问题。","en":"A suit cannot replace the original question."}}],"correct":"I05-V1-88d5527893"},"summary":{"zh":"先看这张牌要回答什么，再结合实际问题，把意思说清楚。下一课把三张已学牌连起来。","en":"Position changes the task; the question supplies the context. Next, connect three learned cards."},"cards":["p08"]},{"id":"I06","kind":"lesson","level":"I","title":{"zh":"试着把三张牌一起读","en":"Read three cards together"},"teachings":[{"zh":"虚构问题：我们小组要合办摄影展，大家很有热情，但不知道怎样开始。我可以怎么推进？抽牌前约定左至右：1 现状、2 建议、3 发展趋势。教学牌全部正位：圣杯骑士、星币八、圣杯十。","en":"Fictional question: Our group wants to organize a photography exhibition. Everyone is enthusiastic, but we do not know how to begin. How can I move it forward? Before drawing, define left to right: 1 situation, 2 advice, 3 tendency. The worked cards are all upright: Knight of Cups, Eight of Pentacles, Ten of Cups."},{"zh":"先回顾三张牌：圣杯骑士愿意为向往的事行动；星币八认真练习、把作品做好；圣杯十和重要的人一起感到幸福。在这个摄影展里，大家想一起办好展览，是现状；把照片选好、修好、布置好，是建议；认真做完后，大家一起体会完成展览的开心，是可能的发展。只有热情，还不够把展览办起来。","en":"Knight of Cups: motivated by an ideal, ready to express and participate. Eight of Pentacles: practical work, practice and quality. Ten of Cups: shared fulfillment and belonging. Here, shared vision is the situation, making the work is the advice, and a shared experience of completion is the tendency. Enthusiasm itself does not install an exhibition."},{"zh":"可以这样回答：你们都想把展览办好，接下来要分清谁选片、谁修图、谁布展，并一起检查完成得怎么样。把这些工作做好后，这组牌更倾向于大家能一起完成展览，并为此感到开心。但它没有保证会来多少观众、赚多少钱。选片和布展是结合摄影展举出的做法，不是每次抽到这些牌都必须做的事。","en":"Worked reading: You have a vision and willingness to join. Next, make selection, editing and installation into concrete tasks and check quality. If this work is implemented, the cards lean toward a meaningful shared achievement and belonging. They give no guaranteed audience or income. The task list is an application, not a command written on the cards."}],"questions":{"Q1":{"id":"I06-Q1","prompt":{"zh":"大家想把展览办好。中间的星币八提醒他们接下来做什么？","en":"What needs implementation between the vision and shared fulfillment?"},"options":[{"id":"I06-Q1-6e0214a99a","text":{"zh":"只保留愿望，工作自动完成","en":"Keep wishing; the work completes itself"},"feedback":{"zh":"光想办好还不够，中间的星币八提醒他们实际准备。","en":"This removes the action condition."}},{"id":"I06-Q1-094a042010","text":{"zh":"动手准备展览，并检查照片和布置是否做好","en":"Practical production and quality checks"},"feedback":{"zh":"星币八在建议位，正是在提醒他们动手做，并检查做得怎样。","en":"This is Eight of Pentacles in advice."}}],"correct":"I06-Q1-094a042010","support":"R1"},"Q2":{"id":"I06-Q2","prompt":{"zh":"哪句话既说出可能的发展，也说清要先做什么？","en":"Which preserves the tendency's condition?"},"options":[{"id":"I06-Q2-103abe610e","text":{"zh":"先把展览认真准备好，大家才更有机会一起体会办成展览的开心","en":"Implementing the work supports a shared achievement"},"feedback":{"zh":"没有把方向变成无条件保证。","en":"This does not turn a tendency into an unconditional guarantee."}},{"id":"I06-Q2-d1e0bc7efe","text":{"zh":"不用制作，观众一定很多","en":"No work is needed; attendance is guaranteed"},"feedback":{"zh":"既取消条件，也加入人数保证。","en":"This removes the condition and adds an attendance guarantee."}}],"correct":"I06-Q2-103abe610e","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"先找中间那张的任务：它是建议，所以要说明可以做什么，而非再描述热情。","en":"Check the middle card's task: it is advice, so it should offer an approach, not merely describe enthusiasm again."}],"question":{"id":"I06-R1","prompt":{"zh":"哪句解释位置2？","en":"Which explains position 2?"},"options":[{"id":"I06-R1-cfa6a7131f","text":{"zh":"大家很向往这次活动","en":"Everyone likes the idea"},"feedback":{"zh":"重复现状，未处理建议。","en":"It repeats the situation instead of advice."}},{"id":"I06-R1-54206daff9","text":{"zh":"把选片和制作分成任务，逐项检查","en":"Organize selection and production tasks and check each"},"feedback":{"zh":"具体说明了接下来要做什么，不只是说大家有热情。","en":"It applies practical effort."}}],"correct":"I06-R1-54206daff9"}},"R2":{"teach":[{"zh":"这里说的是：先把展览准备好，才更有机会一起庆祝完成。不能省掉准备，直接保证成功。","en":"The interpretation says: prepare the exhibition carefully first, then there is a better chance to celebrate its completion together. Do not remove the preparation and promise success."}],"question":{"id":"I06-R2","prompt":{"zh":"哪种删减改变了原意？","en":"Which edit changes the meaning?"},"options":[{"id":"I06-R2-c11a344441","text":{"zh":"删掉‘先把展览认真准备好’，改成‘一定成功’","en":"Remove “prepare the exhibition carefully first” and replace it with “success is certain”"},"feedback":{"zh":"对，原来是先认真准备、才更有机会办好，删改后却成了不管做什么都一定成功。","en":"Correct identification: this changes a conditional direction into a guarantee."}},{"id":"I06-R2-6d13f2cc8e","text":{"zh":"把‘大家为完成展览感到开心’换成‘大家一起庆祝展览办成’","en":"Replace “everyone feels happy about completing the exhibition” with “everyone celebrates the exhibition’s completion together”"},"feedback":{"zh":"这只是换个说法，仍是在说大家为完成展览感到开心。","en":"This is equivalent wording that preserves the theme."}}],"correct":"I06-R2-c11a344441"}}},"revisit":{"id":"I06-V1","prompt":{"zh":"换成合办小型读书会，仍用同一教学牌位和三张牌。哪句话把这次的三张牌连起来回答了问题？","en":"For a small reading club with the same worked positions and cards, which keeps the method?"},"options":[{"id":"I06-V1-a91b2d3e42","text":{"zh":"三张牌分别说三个词即可，不必回应问题","en":"State three isolated words without answering the question"},"feedback":{"zh":"没有完成整组连接。","en":"It does not connect the reading."}},{"id":"I06-V1-91b1475b7b","text":{"zh":"大家想一起办读书会；先准备内容；认真办完后，一起分享收获","en":"Shared vision—prepare content—shared experience after effort"},"feedback":{"zh":"仍然是先说大家的想法，再说准备工作，最后说做好后可能得到的收获。","en":"It transfers the position tasks."}}],"correct":"I06-V1-91b1475b7b"},"summary":{"zh":"本课练习了把三张牌连起来，回答事情可能怎样发展，以及先要做什么。高级课程会进一步练习提问、牌阵与完整解读。","en":"This lesson practised connecting three cards into a conditional response. Advanced lessons develop questions, spreads and whole readings."},"cards":["c12","p08","c10"]},{"id":"A01","kind":"lesson","level":"A","title":{"zh":"把想问的事说清楚","en":"Make your question clear"},"teachings":[{"zh":"要回答到点上，先说清在问哪件事，已经发生了什么，以及想看哪段时间。‘事业怎么样’可能指找工作、做项目或同事关系；先说清当前最想问哪件事。补充会影响判断的情况就好，不用讲所有经历。","en":"An answerable question usually specifies the issue, relevant context, scope and key conditions. 'How is my career?' might mean job hunting, a project or colleagues. Identify the current issue first. Add information that changes the interpretation, not your entire life story."},{"zh":"例子：‘我适合做设计吗？’补充背景是刚自学两周，希望三个月完成作品集，暂不转职。可以这样问：我想用三个月做出作品集。现在准备得怎样，主要困难是什么，接下来该先做什么？这保留设计目标，适用三牌现状—阻碍—建议。不是在替人判定一生天赋。","en":"Example: 'Am I suited to design?' Context: two weeks of self-study, a portfolio goal in three months, no job change planned. Refine it to: For completing a portfolio in three months, what are my situation, main obstacle and next-step advice? This preserves the design goal and fits situation–obstacle–advice. It does not judge lifelong talent."},{"zh":"如果真正在问‘能否完成’，可以保留结果问题，说明目标、时间与准备情况。解读给倾向、理由和条件，而不编造确定日期。比较两个方案时，先固定 A/B 和共同时间范围；只问今天练习重点，单牌就够，不因专业感而增加牌数。","en":"If the real concern is whether it can be completed, keep that outcome question and clarify goal, timing and preparation. Give a tendency, reasons and conditions without inventing an exact date. For two choices, define A/B and a common timeframe first. A single card is enough for today's practice focus; more cards do not make it more professional."}],"questions":{"Q1":{"id":"A01-Q1","prompt":{"zh":"他现在想用三个月做出作品集。哪项是在继续问这件事？","en":"Which keeps the stated design-learning goal?"},"options":[{"id":"A01-Q1-9c193abed2","text":{"zh":"三个月作品集的现状、阻碍与建议","en":"Situation, obstacle and advice for the three-month portfolio"},"feedback":{"zh":"沿用已知事项与时间。","en":"It uses the given issue and timeframe."}},{"id":"A01-Q1-51d78aaa20","text":{"zh":"明年转职后会赚多少","en":"Earnings after a job change next year"},"feedback":{"zh":"新增了未计划的转职和时间。","en":"It adds an unplanned job change and timeframe."}}],"correct":"A01-Q1-9c193abed2","support":"R1"},"Q2":{"id":"A01-Q2","prompt":{"zh":"比较两个方案前，哪项必须先固定？","en":"Before comparing two options, what should be fixed?"},"options":[{"id":"A01-Q2-f9e2fcbc10","text":{"zh":"先抽，哪条好就贴给喜欢的方案","en":"Draw first and give the better line to the preferred option"},"feedback":{"zh":"事后贴标签改变了比较规则。","en":"Relabelling afterward changes the comparison."}},{"id":"A01-Q2-e380ceba9e","text":{"zh":"A 和 B 分别是什么，以及比较哪段时间","en":"What A/B mean and their shared scope"},"feedback":{"zh":"保证两条路径可比较。","en":"This makes the two paths comparable."}}],"correct":"A01-Q2-e380ceba9e","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"整理问题是在减少含糊，不是在替用户换目标。已知不转职，就不能突然开始预测转职工资。","en":"Clarifying reduces ambiguity; it does not replace the person's goal. If no job change is planned, do not start predicting a new salary."}],"question":{"id":"A01-R1","prompt":{"zh":"摄影新手希望半年拍完一组人像，哪项范围合适？","en":"A beginner wants to finish a portrait series in six months. Which scope fits?"},"options":[{"id":"A01-R1-c969921f22","text":{"zh":"围绕人像作品的学习状态、障碍和建议","en":"Learning situation, obstacles and advice for the portrait series"},"feedback":{"zh":"保留给定目标。","en":"It preserves the given goal."}},{"id":"A01-R1-6aed232ede","text":{"zh":"何时开摄影公司并上市","en":"When a photography company will go public"},"feedback":{"zh":"加入了不存在的目标。","en":"It invents a goal."}}],"correct":"A01-R1-c969921f22"}},"R2":{"teach":[{"zh":"先固定 A 与 B，才知道每条路线在回答哪个方案。看到牌后再把好看的路线给喜欢的方案，会让比较失去原来的对象；如果真实选项改变，可以重新提出问题，但不能倒改已经抽出的标签。","en":"Define A and B first so each path has a clear subject. Giving the preferred option the better-looking path after seeing the cards changes the comparison. If the real choices change, ask a new question; do not relabel an existing draw."}],"question":{"id":"A01-R2","prompt":{"zh":"新例：小安比较周末参加实体摄影班与在线摄影班，时间范围都是未来两个月。抽牌前怎样准备？","en":"New example: An compares an in-person weekend photography class with an online class, both over the next two months. What should happen before drawing?"},"options":[{"id":"A01-R2-b7fff8d9ae","text":{"zh":"先不定 A/B，抽完把更好的路线给实体班","en":"Leave A/B undefined, then give the better path to the in-person class"},"feedback":{"zh":"抽完才决定 A、B，容易把喜欢的牌分给自己本来就偏好的选择。","en":"The subjects are assigned after the cards, so there is no preserved advance comparison."}},{"id":"A01-R2-4af097e905","text":{"zh":"写定 A 为实体班、B 为在线班，并保持共同时间范围","en":"Fix A as in-person and B as online, with the shared timeframe"},"feedback":{"zh":"两条路线先有明确对象与相同范围，才可比较。","en":"Each path has a defined subject and the same scope before comparison."}}],"correct":"A01-R2-4af097e905"}}},"revisit":{"id":"A01-V1","prompt":{"zh":"‘这次考核能否通过’是否必须改成‘我感觉如何’？","en":"Must 'Will I pass this assessment?' become 'How do I feel?'"},"options":[{"id":"A01-V1-f273ac4f99","text":{"zh":"不必。说清是哪次考核、准备得怎样，就可以讨论更倾向于通过还是不通过","en":"No; clarify the assessment and conditions, then address outcome tendency"},"feedback":{"zh":"保留真正关心的问题，同时说明条件。","en":"It retains the concern and its conditions."}},{"id":"A01-V1-3e5c2fd714","text":{"zh":"必须，永远不能讨论结果","en":"Yes; outcomes can never be discussed"},"feedback":{"zh":"用户在问能不能通过，应该回答这个问题，不能强行改成只谈感受。","en":"This conflicts with retaining the question's intent."}}],"correct":"A01-V1-f273ac4f99"},"summary":{"zh":"先确定要回答的事，再选择需要的位置。下一课把单牌放回位置。","en":"Establish the issue, then select the needed positions. Next, place meanings within them."},"cards":[]},{"id":"A02","kind":"lesson","level":"A","title":{"zh":"看清每张牌在回答什么","en":"Know what each position answers"},"teachings":[{"zh":"固定顺序：先知道牌的核心，再看牌位的任务，最后回应问题。圣杯二常说双方愿意交流、互相回应；宝剑二在本例说的是迟迟没有决定、事情卡住；节制常说调整不同做法，让彼此逐步配合。下面先把这些含义讲清，再读位置。","en":"Use a stable sequence: the card's core, the position's task, then the question. Two of Cups concerns reciprocity; Two of Swords here concerns suspended choice and stalemate; Temperance concerns adjusting proportions, coordinating differences and gradual integration. Learn these meanings before applying the positions."},{"zh":"虚构背景：伴侣商量共同出行，常因时间安排争执，双方仍愿意沟通。问题是这次计划的现状、主要阻碍及我能采取的建议。采用现状—阻碍—建议，左至右 1 圣杯二正位、2 宝剑二正位、3 节制正位。现状位可以理解为双方还愿意一起计划；阻碍位提醒看看有什么迟迟没决定，例如各自哪些日期不能改；建议位可以说先讲清哪些时间能改、哪些不能，再找两个人都能接受的安排。","en":"Fictional context: partners disagree about dates for a trip but both still wish to communicate. The question asks for the plan's situation, main obstacle and advice I can take. Use situation–obstacle–advice, left to right: 1 Two of Cups upright, 2 Two of Swords upright, 3 Temperance upright. The situation retains willingness to connect. The obstacle prompts checking whether non-negotiable dates remain unclear. Advice is to state necessary conditions and flexible parts, then seek a shared plan."},{"zh":"可以这样回答：你们还想一起出行，但安排卡住了。可以先问清各自哪些日期能改、哪些不能，再找两个人都能接受的安排。节制在建议位给协调方法，不保证旅行一定成行；宝剑二也没有证明谁秘密订了别的行程。","en":"Whole response: willingness to cooperate remains, but a key choice is unclear. State timing and necessary conditions, then try an arrangement both can accept. Temperance in advice offers coordination, not a guaranteed trip; Two of Swords does not prove a secret alternative booking."}],"questions":{"Q1":{"id":"A02-Q1","prompt":{"zh":"节制在建议位，哪句话是在给下一步的做法？","en":"Which correctly uses Temperance in this advice position?"},"options":[{"id":"A02-Q1-513a1732c9","text":{"zh":"旅行肯定已经安排成功","en":"The trip is certainly already settled"},"feedback":{"zh":"把建议误作已实现结果。","en":"This mistakes advice for an achieved result."}},{"id":"A02-Q1-960d095283","text":{"zh":"各自说清哪些日期不能改，再商量可以调整的安排","en":"Clarify necessities and coordinate flexible parts"},"feedback":{"zh":"先说清差别，再找双方能配合的安排，符合节制刚才讲的意思。","en":"It turns coordination into an approach."}}],"correct":"A02-Q1-960d095283","support":"R1"},"Q2":{"id":"A02-Q2","prompt":{"zh":"想断言某人秘密订了别的行程，缺什么？","en":"To assert someone secretly booked another trip, what is missing?"},"options":[{"id":"A02-Q2-9db04b9eb9","text":{"zh":"现实信息的支持","en":"Supporting real-world information"},"feedback":{"zh":"迟迟没决定出行日期，不等于对方已经秘密订了别的行程。","en":"Stalemate does not prove a secret event."}},{"id":"A02-Q2-c2a6997d0c","text":{"zh":"更肯定的语气","en":"A more confident tone"},"feedback":{"zh":"语气不能提供证据。","en":"Tone supplies no evidence."}}],"correct":"A02-Q2-9db04b9eb9","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"建议位可以说‘怎样增加协调机会’，不能直接说‘已经成功’。前者是做法，后者是结果。","en":"Advice can say how to improve coordination, not that success is already achieved. One is an approach; the other an outcome."}],"question":{"id":"A02-R1","prompt":{"zh":"哪句仍是节制建议？","en":"Which remains Temperance advice?"},"options":[{"id":"A02-R1-5802e86bbc","text":{"zh":"无需沟通，一定同日有空","en":"No discussion is needed; schedules certainly match"},"feedback":{"zh":"取消行动并编造结果。","en":"It removes action and invents an outcome."}},{"id":"A02-R1-92f44af7ce","text":{"zh":"先各自说清能调整的日期","en":"First state which dates each can adjust"},"feedback":{"zh":"提供协调动作。","en":"It offers a coordinating action."}}],"correct":"A02-R1-92f44af7ce"}},"R2":{"teach":[{"zh":"用‘可以核实是否……’标明假设，不能把它偷换为‘已经查明……’。","en":"Mark a hypothesis with 'check whether…'; do not replace it with 'it has been established…'."}],"question":{"id":"A02-R2","prompt":{"zh":"根据本例宝剑二，哪句话没有把猜测说成事实？","en":"Which correctly expresses the level of inference for Two of Swords here?"},"options":[{"id":"A02-R2-a1fee69e3b","text":{"zh":"可以核实双方是否没说清日期限制","en":"Check whether date constraints remain unstated"},"feedback":{"zh":"这是接下来可以问清楚的事，没有假装已经知道答案。","en":"It is a checkable interpretive hypothesis."}},{"id":"A02-R2-da9b301359","text":{"zh":"已经证明对方另有安排","en":"It proves the partner has other plans"},"feedback":{"zh":"越过了现有信息。","en":"It exceeds the available information."}}],"correct":"A02-R2-a1fee69e3b"}}},"revisit":{"id":"A02-V1","prompt":{"zh":"同事筹办活动仍用本课三位与三牌，哪项建议也适合用在这个活动安排上？","en":"Colleagues plan an event with the same positions and cards. Which transfers the advice?"},"options":[{"id":"A02-V1-4c21425c90","text":{"zh":"只要出现圣杯，必须改成恋爱解读","en":"Cups means the question must become romantic"},"feedback":{"zh":"没有尊重原问题。","en":"It disregards the original question."}},{"id":"A02-V1-cf1ef2ffff","text":{"zh":"明确各自限制，协调可调整的安排","en":"Clarify constraints and coordinate flexible arrangements"},"feedback":{"zh":"虽然换成同事，仍是在找双方能配合的安排。","en":"It preserves coordination in a new domain."}}],"correct":"A02-V1-cf1ef2ffff"},"summary":{"zh":"先读位置任务，再组织全组；单牌资料可以查，但最终回答要回到原问题。","en":"Read the position's task, then the whole spread. Card references can help, but the final response must return to the question."},"cards":["c02","s02","m14"]},{"id":"A03","kind":"lesson","level":"A","title":{"zh":"把三张牌连起来回答","en":"Answer with three connected cards"},"teachings":[{"zh":"几张牌有时在强调同一件事，有时各说一部分，也可能一张想往前、一张想维持原样。如果事先定了过去、现在、未来，还可以按时间连起来读。不必硬把每两张连起来；摆在旁边，不代表前一张就是后一张的原因。","en":"Cards can reinforce a theme, add a perspective, create tension, or form a process within agreed time positions. You need not link every pair; sitting beside another card does not establish causation."},{"zh":"本例先学三张摘要：星币侍从是认真开始实际学习；圣杯七是许多可能与设想，需要选择；星币八是认真练习、把手艺练好。虚构背景：小林收藏许多摄影课程，买了工具，两个月没完成专题；想四周内完成十张照片。用现状—阻碍—建议：1 星币侍从正位，2 圣杯七正位，3 星币八正位。","en":"First learn the example's card summaries: Page of Pentacles is a serious practical beginning; Seven of Cups concerns many possibilities and images requiring selection; Eight of Pentacles concerns skilled effort and refinement. Fictional context: Lin collected courses and tools but finished no series in two months; the goal is ten photographs in four weeks. Situation–obstacle–advice: 1 Page of Pentacles upright, 2 Seven of Cups upright, 3 Eight of Pentacles upright."},{"zh":"可以这样解读：小林想学摄影，但想做的太多，迟迟没有完成一组照片。先选一个题材，实际拍摄、检查和修改，争取四周内做完这一组。三张连起来是：想学，但拿不定主意做什么，所以先选一件认真做。不是说他没有天赋。两张星币可辅助总结实际投入，但不是唯一依据。若改用无牌阵三张，三张共同回应问题，编号仅为抽取顺序，不能临时把第三张命名为结果位。","en":"Whole reading: willingness to learn exists, but scattered options prevent preparation from becoming finished work. Fix one subject, shoot, review and improve toward a series in four weeks. The thread is willingness to learn—distraction by possibilities—focused practice, not lack of talent. Two Pentacles cards support a practical summary but are not the sole basis. In an open three-card draw, all three address the question; numbers show draw order only. Do not invent an outcome position for the third card afterward."}],"questions":{"Q1":{"id":"A03-Q1","prompt":{"zh":"哪句话把现状、阻碍和建议都说清楚了？","en":"Which retains information from all three positions?"},"options":[{"id":"A03-Q1-14a3aed86e","text":{"zh":"有学习意愿，选择分散，应集中做一组作品","en":"Willing to learn but scattered; focus on one series"},"feedback":{"zh":"连接现状、阻碍和建议。","en":"It connects situation, obstacle and advice."}},{"id":"A03-Q1-ce549902dd","text":{"zh":"没有任何学习意愿，只能放弃","en":"No willingness to learn, so give up"},"feedback":{"zh":"否认现状，也遗漏建议。","en":"It denies the situation and omits the advice."}}],"correct":"A03-Q1-14a3aed86e","support":"R1"},"Q2":{"id":"A03-Q2","prompt":{"zh":"无牌阵第三张是否自动是结果？","en":"Is the third card in an open draw automatically the outcome?"},"options":[{"id":"A03-Q2-858dc590f2","text":{"zh":"是，最后抽就叫结果","en":"Yes, last drawn means outcome"},"feedback":{"zh":"第三个抽出来，不代表抽牌前已约好它代表结果。","en":"This changes order into a position meaning."}},{"id":"A03-Q2-2ca3c0c49e","text":{"zh":"不是，数字只记抽取顺序","en":"No, the number records draw order"},"feedback":{"zh":"没有事前约定结果位。","en":"No outcome position was agreed."}}],"correct":"A03-Q2-2ca3c0c49e","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"本例星币侍从说明他想认真学，圣杯七提醒他想做的太多，星币八建议先选一件、动手练好。只说‘毫无意愿’会否定第一张，也解释不了为什么第三张建议练习。","en":"Page of Pentacles preserves a serious learning start, Seven of Cups identifies scattered choices, and Eight of Pentacles advises focused practice. Saying 'no willingness' denies the first card and does not explain the third."}],"question":{"id":"A03-R1","prompt":{"zh":"新例：小周认真看木工资料，却同时想做桌子、柜子和书架，迟迟没做出东西。沿用本课三位与三牌，哪句话既指出目前的困难，也给出了下一步的做法？","en":"New example: Zhou seriously studies woodworking but wants to make a table, cabinet and shelf at once and has finished nothing. With this lesson's positions and cards, which retains the whole thread?"},"options":[{"id":"A03-R1-f19783647b","text":{"zh":"愿意学习，但选择太散；先定一个小作品，实际制作和打磨","en":"Willing to learn but scattered; choose one small item, then make and refine it"},"feedback":{"zh":"既说出了他愿意学，也指出想做的太多，最后给出先做一件的办法。","en":"It keeps the positive foundation, scattered-choice obstacle and practical advice."}},{"id":"A03-R1-df0c7e4fc9","text":{"zh":"没有成品就说明完全无意愿，应直接停止","en":"No finished work proves no willingness, so stop"},"feedback":{"zh":"忽略已给的认真学习，也丢掉练习建议。","en":"It ignores the stated serious study and loses the practice advice."}}],"correct":"A03-R1-f19783647b"}},"R2":{"teach":[{"zh":"位置需要抽牌前约定。自由三张仍可谈共同主题，只是不假装有过去或结果的位置。","en":"Positions require advance agreement. Open draws can still discuss shared themes without pretending to have past or outcome positions."}],"question":{"id":"A03-R2","prompt":{"zh":"自由抽三张后，哪种说法没有临时给牌加上未约定的位置？","en":"Which respects an open three-card draw?"},"options":[{"id":"A03-R2-1642a6c0d2","text":{"zh":"第一张现在改叫过去","en":"Rename the first card Past"},"feedback":{"zh":"事后补了未约定的位置。","en":"It adds an unagreed position afterward."}},{"id":"A03-R2-2c731cf95f","text":{"zh":"这三张共同强调实践与选择","en":"These cards jointly emphasize practice and choice"},"feedback":{"zh":"是在一起解释三张牌，没有临时给某张加上过去或结果的意思。","en":"It discusses contributions without inventing positions."}}],"correct":"A03-R2-2c731cf95f"}}},"revisit":{"id":"A03-V1","prompt":{"zh":"新例：小周认真看烹饪课，收藏了很多菜谱，却没有做出一道成品。仍用本课三位与三张正位牌：现状星币侍从、阻碍圣杯七、建议星币八。他想学，却一直没做出一道菜。哪项建议更符合这组三张牌？","en":"New example: Zhou studies cooking seriously and collects many recipes but has made no finished dish. Use the same upright spread: Page of Pentacles as situation, Seven of Cups as obstacle and Eight of Pentacles as advice. Which better addresses the main blockage?"},"options":[{"id":"A03-V1-8b39e526b7","text":{"zh":"先缩小到一道菜，实际制作并检查哪里需要改进","en":"Narrow the choice to one dish, cook it and review what needs improvement"},"feedback":{"zh":"星币侍从说他愿意学，圣杯七提醒想做的太多，星币八建议认真动手练。因此先做一道菜、做好后再改，能把三张牌连起来。","en":"The situation acknowledges willingness; the obstacle identifies scattered choices; the advice turns learning into focused practice. All three positions are retained."}},{"id":"A03-V1-aa0f925572","text":{"zh":"既然还在初学，先继续增加课程和菜谱，等所有方向都学完再动手","en":"Because the learner is still a beginner, add more courses and recipes and wait until every direction is covered before cooking"},"feedback":{"zh":"这只抓住星币侍从的初学，却忽略圣杯七已指出的选择分散，也延后了星币八的实际练习。本题不是认定课程无用，而是按已给牌位处理当前卡点。","en":"This uses only the Page's beginner status, ignores the Seven's scattered choices and postpones the Eight's practice. Courses are not inherently useless; this question asks about the stated blockage and positions."}}],"correct":"A03-V1-8b39e526b7"},"summary":{"zh":"本课示范了怎样把逐张解释连成一条主线。下一课检查逆位怎样进入整组。","en":"This lesson demonstrated how separate meanings form a main thread. Next, integrate a reversal."},"cards":["p11","c07","p08"]},{"id":"A04","kind":"lesson","level":"A","title":{"zh":"整组牌里有逆位怎么办","en":"Read reversals within a spread"},"teachings":[{"zh":"读逆位时，先记住这张牌原本在说什么，再看具体情况。某些牌可能是在说做得不够，也可能是在说做过了头；这次是哪一种，要看题目告诉了我们什么。旁边的牌能帮助一起理解，但不能凭空增加没发生过的事。","en":"Retain the theme before identifying this reversal's change. Lack and excess may both be possible for some cards, but you cannot assert both indiscriminately in one case. Other cards help integration; they do not create real-world facts."},{"zh":"虚构背景：作品已符合展示要求，小林仍不断修改细节，错过自己定的提交时间。教学三牌：1 现状星币侍从正位——仍愿意认真学、动手做；2 阻碍星币八逆位——细节一直改，反而迟迟做不完；3 建议星币骑士正位——稳步执行、可靠跟进。骑士本课含义先明示，不要求猜陌生牌。","en":"Fictional context: Lin's work meets exhibition requirements, but repeated tiny revisions have missed a self-set deadline. Worked spread: 1 situation, Page of Pentacles upright—practical learning matters; 2 obstacle, Eight of Pentacles reversed—unbalanced refinement obstructs completion; 3 advice, Knight of Pentacles upright—steady execution and reliable follow-through. The Knight's meaning is supplied; you are not expected to guess it."},{"zh":"可以这样回答：小林一直在认真做，但作品已经够用，还在反复改细节，结果没按时交。先列出真正必须改的地方，改完就按计划提交。这里要改的是做法，不能说他从来没努力。星币骑士是行动方式，不能据此确定有某位男性来替你完成。如果不知道他练过没有、怎样练，就先问清楚，再判断是没开始做，还是做法需要调整。","en":"Whole response: serious learning is a foundation, but refinement no longer serving delivery calls for step-by-step completion. Define required changes and a stopping condition, then submit to plan. This supports changing the refinement process, not claiming no effort. Knight of Pentacles is an approach, not proof that a man will finish it for you. Without practice context, insufficient effort and an unbalanced method remain alternatives; actual practice information is needed to distinguish them."}],"questions":{"Q1":{"id":"A04-Q1","prompt":{"zh":"本例哪项更符合星币八逆位？","en":"Which reading of reversed Eight of Pentacles fits this case?"},"options":[{"id":"A04-Q1-8255ec0cb9","text":{"zh":"从未付出时间","en":"No time was invested"},"feedback":{"zh":"与反复修改矛盾。","en":"It contradicts repeated revision."}},{"id":"A04-Q1-50534deda1","text":{"zh":"细节改得太多，耽误了提交作品","en":"Excessive refinement obstructs delivery"},"feedback":{"zh":"与已达要求却持续修改相符。","en":"It fits continued revision after requirements are met."}}],"correct":"A04-Q1-50534deda1","support":"R1"},"Q2":{"id":"A04-Q2","prompt":{"zh":"建议位星币骑士在这里补充了什么？","en":"What does Knight of Pentacles add in advice here?"},"options":[{"id":"A04-Q2-c58645f18c","text":{"zh":"稳步执行到完成的方式","en":"A steady way to follow through to completion"},"feedback":{"zh":"这里卡在一直改、迟迟不交，所以建议按步骤做完并提交。","en":"It addresses the blockage from unbalanced refinement."}},{"id":"A04-Q2-bb1a48fbab","text":{"zh":"确定帮助者的性别","en":"A helper's certain gender"},"feedback":{"zh":"角色没有提供身份保证。","en":"The role provides no identity guarantee."}}],"correct":"A04-Q2-c58645f18c","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"两个说法先与背景对照：有大量修改，就不能说完全没做。再看修改是否推进了目标。","en":"Compare each claim with the context: extensive revision rules out doing nothing. Then check whether revision advances the goal."}],"question":{"id":"A04-R1","prompt":{"zh":"改动越来越小，提交却不断延后，优先关注什么？","en":"Revisions shrink while submission keeps slipping. What should be examined first?"},"options":[{"id":"A04-R1-50dbe69b3c","text":{"zh":"当事人是否根本没碰作品","en":"Whether the person never touched the work"},"feedback":{"zh":"已知修改事实排除了这项。","en":"The given revisions rule this out."}},{"id":"A04-R1-239bddec0e","text":{"zh":"是否一直改小细节，耽误了按时做完","en":"Whether detail work and completion are out of balance"},"feedback":{"zh":"直接回应已给变化。","en":"It addresses the given change."}}],"correct":"A04-R1-239bddec0e"}},"R2":{"teach":[{"zh":"星币骑士在这个建议位给出的是稳步做完、可靠跟进的做法，不是在宣布某个男性会出现。任何人都能采取这种方式；若现实有人协助，仍要另外确认。","en":"In this advice position, Knight of Pentacles offers steady completion and reliable follow-through, not the arrival of a man. Anyone can use that approach; real assistance still needs separate confirmation."}],"question":{"id":"A04-R2","prompt":{"zh":"新例：小安为社团整理活动材料，建议位是星币骑士。怎样做符合星币骑士刚才讲的建议？","en":"New example: An is preparing event materials for a club, with Knight of Pentacles as advice. Which applies this lesson's use of the role?"},"options":[{"id":"A04-R2-2f4ed1e0c6","text":{"zh":"把材料列清，按顺序完成并跟进遗漏","en":"List the materials, complete them in sequence and follow up omissions"},"feedback":{"zh":"把稳步执行变成自己的行动，不依赖虚构帮助者。","en":"It makes steady execution your action without inventing a helper."}},{"id":"A04-R2-a06b2df806","text":{"zh":"暂停整理，等待牌里预告的男性替自己做完","en":"Stop preparing and wait for the predicted man to finish it"},"feedback":{"zh":"牌位没有提供帮助者身份或到来保证，也没有回答自己的行动。","en":"The position establishes neither a helper's identity nor arrival, and it fails to address your action."}}],"correct":"A04-R2-2f4ed1e0c6"}}},"revisit":{"id":"A04-V1","prompt":{"zh":"若背景改成报名后从未做作业，同张逆位先关注什么？","en":"If the context changes to never doing assignments after enrolling, what does the same reversal first highlight?"},"options":[{"id":"A04-V1-58276eec78","text":{"zh":"仍断定修改过度","en":"Still assert excessive revision"},"feedback":{"zh":"新背景没有任何修改支持。","en":"The new facts contain no revision to support that."}},{"id":"A04-V1-69411cdc67","text":{"zh":"报名了，却还没有开始做作业","en":"Practical effort has not been implemented"},"feedback":{"zh":"题目变成从没做作业，应该先开始动手，不能再说是修改太多。","en":"New context supports a different change within the same theme."}}],"correct":"A04-V1-69411cdc67"},"summary":{"zh":"先看实际发生了什么，选择说得通的逆位解释，再结合其他牌，一起回答问题。","en":"Context narrows a reversal's possibilities; the other positions help answer the question."},"cards":["p11","p08","p12"]},{"id":"A05","kind":"lesson","level":"A","title":{"zh":"两个选择怎么比较","en":"Compare two choices"},"teachings":[{"zh":"本课采用五牌 V 形：1 当前状况在下方中央；2 A 当前发展在左中，4 A 结果趋势在左上；3 B 当前发展在右中，5 B 结果趋势在右上。两条路线是 1→2→4 与 1→3→5。抽牌前固定选项与同一时间范围，不能读完后换标签。","en":"This five-card V places 1 current situation at the bottom centre; 2 A development at mid-left and 4 A outcome tendency at upper-left; 3 B development at mid-right and 5 B outcome tendency at upper-right. Read 1→2→4 and 1→3→5. Define the choices and a shared timeframe before drawing; do not relabel afterward."},{"zh":"虚构案例：设计助理可选 A 有资深同事指导的跨部门项目，或 B 独立负责新品牌小项目，都要兼顾现有工作。问未来三个月，哪一个更能帮他做出拿得出手、能展示能力的作品？五张均正位：1 星币二——同时安排几件事；2 星币三——合作、交流做法；3 权杖侍从——想尝试新东西；4 星币八——认真练习，把作品做好；5 权杖十——要负责的事越来越多，负担很重。","en":"Fictional case: a design assistant can choose A, a cross-team project with senior guidance, or B, independently leading a small new-brand project. Both must fit existing work. Over three months, which better supports completing a quality project that demonstrates ability? All cards are upright: 1 Two of Pentacles—balancing tasks and resources; 2 Three of Pentacles—collaboration and skill exchange; 3 Page of Wands—enthusiastic exploration; 4 Eight of Pentacles—practice, refinement and quality; 5 Ten of Wands—accumulating responsibility and burden."},{"zh":"先看共同的情况：手上还有工作，所以不论选 A 还是 B，都要看自己有没有时间做。A 有人一起讨论做法、指出问题，之后还要自己认真练习和修改。有人帮忙，但不能替他把作品做完。B 从新方向热情走向负担增加，独立自由可能伴随提案、协调和制作都落在一人身上；这符合兼顾现有工作的背景，不是说独立项目一律差。","en":"Start with the shared situation: existing work makes resources relevant to both paths. A moves from collaboration to individual refinement, with clearer support but still requiring effort. B moves from exploration to heavier responsibility; freedom may also bring proposal, coordination and production to one person. This fits the existing workload; it does not mean independent projects are always bad."},{"zh":"完整回应：如果目标是三个月内把作品做好，这组牌更支持 A：有人给意见，自己再练习和修改。B 也可以考虑，但要先少做几项，问清谁能帮忙，避免所有事都压到自己身上。如果后来发现 A 的时间根本排不开，就要重新考虑，不能因为牌更偏 A，就忽略现实里做不到。牌组也没有承诺 A 一定升职。","en":"Whole response: for a quality project in three months, this spread favors A because collaborative feedback can feed into individual practice. B remains possible, but narrow delivery and confirm help to avoid overload. If A later proves impossible to attend, acknowledge changed feasibility and reconsider; reality does not have to obey the cards. The spread also does not guarantee promotion through A."}],"questions":{"Q1":{"id":"A05-Q1","prompt":{"zh":"本版本 A 路线读哪几个位置？","en":"Which positions form path A in this version?"},"options":[{"id":"A05-Q1-34b5a33244","text":{"zh":"1→2→4","en":"1→2→4"},"feedback":{"zh":"从共同现状走到 A 发展与 A 趋势。","en":"It joins the shared situation, A development and A tendency."}},{"id":"A05-Q1-f0b25f96c9","text":{"zh":"1→2→3","en":"1→2→3"},"feedback":{"zh":"第3位是 B 发展，不属于 A 路线。","en":"Position 3 is B development, not part of A."}}],"correct":"A05-Q1-34b5a33244","support":"R1"},"Q2":{"id":"A05-Q2","prompt":{"zh":"为什么本例更支持 A？","en":"Why does this example favor A?"},"options":[{"id":"A05-Q2-5b3d55505c","text":{"zh":"星币永远比权杖好","en":"Pentacles is always better than Wands"},"feedback":{"zh":"不能给花色分高低；要看这次的问题和每个位置的牌。","en":"There is no across-context suit ranking."}},{"id":"A05-Q2-0c5fe04702","text":{"zh":"本来工作就不少，A 有人一起讨论和指导，更利于自己继续练、把作品做细","en":"Under existing workload, collaboration supports sustained refinement"},"feedback":{"zh":"他本来就要兼顾工作。A 有合作指导，最后仍要自己认真做，更符合三个月内做好作品的目标。","en":"It connects situation, development, tendency and goal."}}],"correct":"A05-Q2-0c5fe04702","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"先从第1张开始。选 A 时再看第2、4张；选 B 时再看第3、5张。第1张是两条路线共同的起点。","en":"Start with card 1. For A, continue with cards 2 and 4. For B, continue with cards 3 and 5. Card 1 is the shared starting point."}],"question":{"id":"A05-R1","prompt":{"zh":"B 结果趋势在哪里？","en":"Where is B's outcome tendency?"},"options":[{"id":"A05-R1-ef2d127de3","text":{"zh":"5","en":"5"},"feedback":{"zh":"右上第5位承接右中第3位。","en":"Upper-right 5 follows mid-right 3."}},{"id":"A05-R1-4b227777d4","text":{"zh":"4","en":"4"},"feedback":{"zh":"第4位属于 A。","en":"Position 4 belongs to A."}}],"correct":"A05-R1-ef2d127de3"}},"R2":{"teach":[{"zh":"本例更支持 A，是因为本来就有不少工作，有人一起讨论和指导，更有利于把作品做好。不是因为星币比权杖好。要结合想做成什么，以及 A、B 各自怎样发展来比较。","en":"A is favored because collaboration can support sustained refinement under an existing workload, not because Pentacles is inherently better than Wands. Retain the goal, shared situation and both paths."}],"question":{"id":"A05-R2","prompt":{"zh":"新例：小周要在两个月内完成展览作品，又有日常任务。沿用刚才五张牌：选 A，有人一起讨论，之后自己继续修改作品；选 B，独立尝试新方向，但要负责的事越来越多。为什么这里更支持 A？","en":"New example: Zhou aims to finish exhibition work in two months while keeping daily duties. The same five worked cards show collaboration leading to refinement versus carrying more work alone. Which reason actually supports the collaborative project?"},"options":[{"id":"A05-R2-82e01be237","text":{"zh":"因为有权杖的路线在任何问题里都较差","en":"Because any path with Wands is worse in every question"},"feedback":{"zh":"这是脱离目标的花色排名，没有解释两条过程。","en":"This ranks suits outside the goal and explains neither path."}},{"id":"A05-R2-a24a6f6152","text":{"zh":"本来任务就不少，有人合作指导，更方便持续修改作品、争取按期完成","en":"Collaborative support can sustain refinement and better fit completion under the existing workload"},"feedback":{"zh":"比较的是哪种安排更利于按期做好作品，不是在给花色分高低。","en":"It compares processes against the goal and workload, without ranking suits."}}],"correct":"A05-R2-a24a6f6152"}}},"revisit":{"id":"A05-V1","prompt":{"zh":"用本例 B 路线制定准备，哪项回应权杖十的负担？","en":"To prepare for path B, which action addresses Ten of Wands' burden?"},"options":[{"id":"A05-V1-15e46fd5dc","text":{"zh":"限定范围并确认能得到的协助","en":"Limit scope and confirm available help"},"feedback":{"zh":"处理任务积累的实际条件。","en":"It addresses accumulating tasks."}},{"id":"A05-V1-d43ba94a36","text":{"zh":"不断加任务，因为热情会自动解决","en":"Add tasks because enthusiasm solves everything"},"feedback":{"zh":"忽略了发展到负担的提示。","en":"It ignores the movement toward burden."}}],"correct":"A05-V1-15e46fd5dc"},"summary":{"zh":"二择一要比较整条路径，而不是只挑喜欢的一张。本课展示了倾向、理由与条件怎样放在一起。","en":"A choice reading compares whole paths, not a favorite card. This lesson showed how a tendency, reasons and conditions fit together."},"cards":["p02","p03","w11","p08","w10"]},{"id":"A06","kind":"lesson","level":"A","title":{"zh":"一步步读凯尔特十字","en":"Read the Celtic Cross step by step"},"teachings":[{"zh":"本课凯尔特十字采用这些职责：1 整体影响；2 交叉阻碍；3 目标或尚未实现的可能；4 基础；5 正在退去的影响；6 即将作用的影响；7 自己的态度；8 环境；9 希望或担忧；10 结果趋势。中心1与2，3上4下，5左6右；右边一列7至10自下向上。2的横放只表示交叉位置，不自动变成逆位；正逆位按原抽取方向记录。","en":"This Celtic Cross uses: 1 overall influence; 2 crossing obstacle; 3 goal or unrealized possibility; 4 foundation; 5 receding influence; 6 approaching influence; 7 your attitude; 8 environment; 9 hopes or fears; 10 outcome tendency. Positions 1–2 are central, 3 above, 4 below, 5 left and 6 right; the right column runs 7 to 10 from bottom to top. Card 2's horizontal placement marks crossing, not an automatic reversal; retain its originally recorded orientation."},{"zh":"虚构案例：社区小组计划两个月内举办旧物交换，场地初步获准，成员有热情，但分工和登记未确定。问：按现在的准备情况，活动接下来可能怎样？最该先解决什么？下面十张都是正位，先逐位讲清再整合。","en":"Fictional case: a community group plans a swap event in two months. Venue approval is preliminary, members are enthusiastic, but responsibilities and item registration remain unclear. How might it develop from current preparation, and what needs addressing? All ten cards below are upright. First learn each position's meaning, then integrate."},{"zh":"1 整体影响：星币三。活动需要大家一起做，分清各人擅长什么、负责什么，不能只靠发起人想办成。","en":"1 Overall influence: Three of Pentacles. The event needs collaboration and complementary skills, not only its initiator's wishes."},{"zh":"2 交叉阻碍：权杖五。大家意见不同、做法不一致，和目前分工没定的情况相符，但不代表有人故意捣乱。","en":"2 Crossing obstacle: Five of Wands. Competing opinions and approaches fit unclear responsibilities; they do not prove sabotage."},{"zh":"3 目标或可能：太阳。希望活动清楚、有趣，大家都能愉快参与。这是想办成的样子，还不是已经办成的结果。","en":"3 Goal or possibility: The Sun. An open, clear and enjoyable experience is the possibility being pursued, not success already achieved."},{"zh":"4 基础：星币六。交换涉及拿出东西、收到东西，以及怎样分配，所以要说清谁提供什么、谁能领取。","en":"4 Foundation: Six of Pentacles. Giving, receiving and resource allocation underpin the exchange; clarify who provides and receives."},{"zh":"5 渐退影响：权杖侍从。一开始因为觉得新鲜、有意思，大家想办这个活动。现在光有热情不够，还要动手准备。","en":"5 Receding influence: Page of Wands. Early exploratory enthusiasm launched the idea, but novelty alone cannot complete the next stage."},{"zh":"6 将来影响：星币骑士。接下来要一步步把准备工作做好，比如定时间、做登记、分清谁负责，不能等着一下子全解决。","en":"6 Approaching influence: Knight of Pentacles. The next emphasis is steady execution—scheduling, registration and responsibility—not a dramatic instant breakthrough."},{"zh":"7 自己的态度：魔术师。发起人愿意用自己的能力和手头工具把活动办起来。可以主动组织，但不用把所有活都揽下来。","en":"7 Your attitude: The Magician. The initiator is ready to use skills and tools actively; apply that initiative to organizing rather than owning every task."},{"zh":"8 环境：教皇。活动要按现有规则和流程来。场地只是初步同意，要再问清使用要求，不能认定主办机构会解决所有问题。","en":"8 Environment: The Hierophant. Existing rules and procedures matter. With preliminary permission, check venue requirements; institutional rescue is not guaranteed."},{"zh":"9 希望或担忧：宝剑九。发起人担心细节出错、让人失望；这张牌在这里说的是他担心什么，不是在预告会出事故。","en":"9 Hopes or fears: Nine of Swords. The initiator fears mistakes and disappointing others. In this position, fear is a theme, not a prediction of an accident."},{"zh":"10 结果趋势：权杖四。有机会把这次活动办成，让大家聚在一起庆祝。但还要结合前面各张牌，看看需要先做好什么。","en":"10 Outcome tendency: Four of Wands. Milestone completion, gathering and celebration offer a positive direction, to be read with implementation conditions."},{"zh":"把十条信息收成三条主线。第一，看第 1、2 位：需要合作，但大家做法不一致，所以先把分工说清。第二，看接下来怎么做：第 5 位的权杖侍从说起初有热情，第 6 位的星币骑士提醒现在要一步步准备。第 4 位的星币六提醒分配东西，第 8 位的教皇提醒遵守场地规则。第三，把想办成的样子、担心的事和可能的结果分开：太阳在目标位，宝剑九在担忧位，权杖四在结果趋势位，不能把担忧直接当结果。","en":"Reduce ten pieces of information to three threads. First, collaboration is the foundation and coordination the blockage: Three of Pentacles with Five of Wands supports clarifying responsibilities. Second, move from enthusiasm to execution: receding Page of Wands to approaching Knight of Pentacles, with Six of Pentacles adding resources and Hierophant adding rules. Third, separate possibility from fear: Sun is a goal, Four of Wands a tendency, and Nine of Swords a fear position, not the outcome itself."},{"zh":"完整回应：整体上，这次活动有机会办成，让大家一起庆祝。前提是把分工、登记和场地要求处理好。现在最需要说清谁负责、什么时候做完，不是继续确认大家有没有热情。优先确认负责人、进度和规则，再检查最担心的准备项目。是否最终办成仍取决于现实工作与条件变化；这组牌不能代替筹备。","en":"Whole response: the overall tendency is toward a positive milestone, provided responsibilities, registration and venue requirements are implemented. Clear ownership and steady execution matter more now than proving enthusiasm. Confirm owners, schedule and rules, then check the preparations causing most concern. Actual completion depends on real work and changing conditions; this spread does not replace preparation."}],"questions":{"Q1":{"id":"A06-Q1","prompt":{"zh":"第9张在说“希望或担忧”。这里的宝剑九说明了什么？","en":"Position 9 describes hopes or fears. What does the Nine of Swords mean here?"},"options":[{"id":"A06-Q1-04c3ec56f9","text":{"zh":"活动最后一定会出事故","en":"An accident will definitely happen at the event"},"feedback":{"zh":"把担忧当结果，又新增具体事故。","en":"It turns fear into outcome and adds an accident."}},{"id":"A06-Q1-6632ddfc12","text":{"zh":"发起人担心活动准备出错","en":"The organiser is worried about mistakes in preparing the event"},"feedback":{"zh":"第 9 位在说他担心什么。可以接着检查准备工作，不必把担心直接当成会发生的事。","en":"It keeps fear in its position and links to practical checking."}}],"correct":"A06-Q1-6632ddfc12","support":"R1"},"Q2":{"id":"A06-Q2","prompt":{"zh":"根据本例已给的背景与十个位置，哪项应优先安排来推进活动？","en":"Given this example's context and ten positions, which priority best advances the event?"},"options":[{"id":"A06-Q2-60b73f97f9","text":{"zh":"把任务分给负责人，落实登记与场地要求，再跟进执行","en":"Assign task owners, implement registration and venue requirements, then follow through"},"feedback":{"zh":"第 1、2 位说明需要合作，但做法还没谈妥；第 6 位提醒一步步准备，第 4、8 位提醒物品分配和场地规则。因此先分工、登记、确认场地，正好处理目前没定下来的事。","en":"Three of Pentacles in 1 and Five of Wands in 2 locate the coordination issue; Knight of Pentacles in 6 supports execution; Six of Pentacles in 4 and Hierophant in 8 add resources and rules. This addresses the stated unfinished preparation."}},{"id":"A06-Q2-16c799bdec","text":{"zh":"先扩大宣传和创意征集，靠更多热情解决当前分工问题","en":"Expand promotion and collect more ideas first, relying on enthusiasm to resolve the role problem"},"feedback":{"zh":"太阳说的是想办成的样子，魔术师说发起人愿意主动做，并不代表分工已经解决。第 5、6 位也提醒从想办，走到实际准备。宣传可以安排，但眼下先要确定负责人和场地要求。","en":"The Sun in 3 is a goal and Magician in 7 an organizing attitude, not reasons to bypass the coordination issue in 2. Initial enthusiasm recedes in 5 while 6 calls for execution. Promotion may have a place, but it is not the priority gap stated here."}}],"correct":"A06-Q2-60b73f97f9","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"先把第9、10张分开看：第9张宝剑九说发起人担心什么；第10张权杖四说活动有机会办成。担心出错，不等于最后一定会失败；还要看分工、登记和场地准备能否做好。","en":"Separate cards 9 and 10: the Nine of Swords in 9 describes the organiser’s worries; the Four of Wands in 10 suggests the event could succeed. Worry does not mean certain failure. Responsibilities, registration and venue preparations still need to be completed."}],"question":{"id":"A06-R1","prompt":{"zh":"把本例第9张宝剑九和第10张权杖四放在一起，哪种解释更合适？","en":"Read this example’s Nine of Swords in 9 alongside the Four of Wands in 10. Which interpretation fits?"},"options":[{"id":"A06-R1-3f52ed77e2","text":{"zh":"既然有担忧，活动就一定办不成","en":"Worry means the event is certain to fail"},"feedback":{"zh":"第9张是担忧，第10张才是结果趋势，不能用担忧直接替换结果。","en":"Position 9 describes fear; position 10 describes the outcome tendency. Fear cannot simply replace the outcome."}},{"id":"A06-R1-be6ad4dfa7","text":{"zh":"发起人有担忧，但把准备工作做好，活动仍有机会顺利完成","en":"The organiser is worried, but the event could still succeed if preparations are completed"},"feedback":{"zh":"这把担心的事和可能的结果分开，也保留了前面讲过的准备条件。","en":"This separates fear from the possible outcome and keeps the preparation conditions already explained."}}],"correct":"A06-R1-be6ad4dfa7"}},"R2":{"teach":[{"zh":"太阳在目标位，说明想把活动办得开心、有趣，但没有说现在最该做宣传。目前分工还没定，权杖五也提醒大家做法不一致。先按星币骑士的提示一步步准备，再按教皇的提示问清场地规则。多一些热情，不能代替这些工作。","en":"The Sun in the goal position describes the desired experience; it does not by itself make promotion the immediate priority. First check the current obstacle: Five of Wands fits unclear roles; Knight of Pentacles supports execution and Hierophant rules. More enthusiasm does not assign owners or confirm venue requirements."}],"question":{"id":"A06-R2","prompt":{"zh":"新例：同一活动已收集到足够创意，但登记负责人和场地使用条件仍不明确。保留本例牌位，下一次筹备会先做什么？","en":"New example: the same event has enough ideas, but the registration owner and venue conditions remain unclear. With the same positions, what should the next preparation meeting do first?"},"options":[{"id":"A06-R2-11d1fe0f3c","text":{"zh":"确定登记负责人，确认场地条件，并约定跟进日期","en":"Assign a registration owner, confirm venue conditions and set a follow-up date"},"feedback":{"zh":"先分清谁登记、场地怎样用、何时跟进，正是在解决第 2、6、8 位提醒的事，也有助于把原定活动办好。","en":"It addresses coordination in 2, execution in 6 and rules in 8 while preserving the event's goal."}},{"id":"A06-R2-3578cb4cb5","text":{"zh":"继续征集更多创意，把责任与规则等到宣传后再定","en":"Collect more ideas and defer roles and rules until after promotion"},"feedback":{"zh":"已有创意不是缺口；这延后了牌位与背景共同指出的准备问题。","en":"Ideas are not the missing piece; this postpones the preparation gap identified by both positions and context."}}],"correct":"A06-R2-11d1fe0f3c"}}},"revisit":{"id":"A06-V1","prompt":{"zh":"位置2的牌横放，就必须改记逆位吗？","en":"Does a horizontal card in position 2 have to be marked reversed?"},"options":[{"id":"A06-V1-bb95225bb4","text":{"zh":"必须，横放就是逆位","en":"Yes; horizontal means reversed"},"feedback":{"zh":"把布局姿态与牌的正逆位混为一谈。","en":"It confuses layout with drawn orientation."}},{"id":"A06-V1-803e46aa5c","text":{"zh":"不必，交叉摆法与抽取方向分开记录","en":"No; crossing placement and drawn orientation are recorded separately"},"feedback":{"zh":"遵守本课采用版本的展示约定。","en":"It follows this lesson's layout convention."}}],"correct":"A06-V1-803e46aa5c"},"summary":{"zh":"你已练习把十张牌一起读：回答正在问的事，说清更可能怎样发展、为什么这样判断，以及还要先做好什么。之后可以回到新案例继续练，不必每次使用十张。","en":"You have practised reducing a complex spread to the issue, tendency, evidence and conditions. Continue with new cases; ten cards are not required every time."},"cards":["p03","w05","m19","p06","w11","p12","m01","m05","s09","w04"]}],"cards":[{"id":"m00","kind":"card","level":"I","title":{"zh":"愚人","en":"The Fool"},"teachings":[{"zh":"愚人代表新的开始，以及面对未知时愿意尝试的态度。不必一开始就投入全部，也不意味着什么准备都不用做。","en":"The Fool represents new beginnings and a willingness to try something unfamiliar. Beginning requires neither committing everything nor abandoning preparation."},{"zh":"轻装的人靠近崖边，旁边有狗。轻装与前行帮助记住开始，崖边提醒未知；不能由图断言他会坠落。","en":"A lightly packed traveler approaches an edge with a dog nearby. Travel suggests a beginning; the edge reminds us of uncertainty, not an inevitable fall."},{"zh":"关键词：开始、开放、探索。愚人的编号是0，是认识大牌的起点。","en":"Remember: beginnings, openness, exploration. The Fool is numbered 0, a starting point for learning the majors."}],"application":{"zh":"建议位：想学陶艺但没接触过，可以先试一节入门课，再决定长期投入。这里支持开始探索，不要求一次买齐昂贵设备。","en":"Advice: try an introductory pottery class before committing long term. This supports exploration, not buying all the equipment at once."},"reversal":{"zh":"逆位示例：已打算独自进山，却没有路线与装备准备。这里需要先查清路线、备好装备，不能把逆位一概理解成以后都不能出发。","en":"Reversed example: a solo hike is planned without a route or equipment. Research the route and prepare the gear first; reversal does not mean never setting out again."},"visual":{"zh":"轻装的人靠近崖边，旁边有狗。轻装与前行帮助记住开始，崖边提醒未知；不能由图断言他会坠落。","en":"A lightly packed traveler approaches an edge with a dog nearby. Travel suggests a beginning; the edge reminds us of uncertainty, not an inevitable fall."},"questions":{"Q1":{"id":"m00-Q1","prompt":{"zh":"本课说愚人具有“开放”的态度，这是什么意思？","en":"What does the Fool’s openness mean in this lesson?"},"options":[{"id":"m00-Q1-e5f42674ed","text":{"zh":"愿意尝试未知","en":"Willingness to explore"},"feedback":{"zh":"愿意接触没做过的事，正是本课所说的开始与探索。","en":"Being willing to try something unfamiliar expresses the beginning and exploration taught here."}},{"id":"m00-Q1-cb722ce751","text":{"zh":"不必考虑条件","en":"Ignoring conditions"},"feedback":{"zh":"愿意开始尝试，也要确认自己准备得够不够；开放不等于什么都不考虑。","en":"Willingness to begin still requires checking preparation; openness does not mean ignoring every consideration."}}],"correct":"m00-Q1-e5f42674ed","support":"R1"},"Q2":{"id":"m00-Q2","prompt":{"zh":"第一次学陶艺怎样开始？","en":"How could a pottery beginner start?"},"options":[{"id":"m00-Q2-e6d3ff3509","text":{"zh":"先买齐工作室的全部设备","en":"Buy all the studio equipment first"},"feedback":{"zh":"还没试过陶艺就买齐设备，是先作了很大的投入，还没有了解自己是否喜欢。","en":"Buying everything before trying pottery commits heavily before you know whether you enjoy it."}},{"id":"m00-Q2-1b947051d4","text":{"zh":"先体验一节课","en":"Try one class"},"feedback":{"zh":"上一节课就已经开始探索，也给自己留下了解后再决定的机会。","en":"One class starts the exploration while leaving room to decide after experiencing it."}}],"correct":"m00-Q2-1b947051d4","support":"R2"},"Q3":{"id":"m00-Q3","prompt":{"zh":"在没有准备路线和装备就打算进山的例子里，愚人逆位提醒先做什么？","en":"In the unprepared hiking example, what does the reversed Fool suggest addressing first?"},"options":[{"id":"m00-Q3-cabfd61dd5","text":{"zh":"补路线和装备","en":"Prepare route and equipment"},"feedback":{"zh":"例子已经说明缺少路线与装备，先补好这两项准备才回应了问题。","en":"The example identifies a missing route and equipment; preparing them addresses that problem."}},{"id":"m00-Q3-a6bfb57e4c","text":{"zh":"永久放弃户外活动","en":"Abandon outdoor activity forever"},"feedback":{"zh":"例子指出的是这次没有准备好，并没有说以后都不能参加户外活动。","en":"The example concerns this trip’s preparation, not a lifelong ban on outdoor activities."}}],"correct":"m00-Q3-cabfd61dd5","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"开始可以很小。先试一次和把全部资源押上，是两种不同规模的行动。","en":"A beginning can be small. Trying once differs from committing everything."}],"question":{"id":"m00-R1","prompt":{"zh":"只试一天新爱好算开始吗？","en":"Is trying a hobby for one day a beginning?"},"options":[{"id":"m00-R1-aa69704b03","text":{"zh":"不算，必须长期承诺","en":"No, it requires a long commitment"},"feedback":{"zh":"开始不要求先答应长期坚持；试一天也能让你接触一种新体验。","en":"Beginning does not require a long commitment; one day can introduce a new experience."}},{"id":"m00-R1-898b48e3e2","text":{"zh":"算，已经接触未知","en":"Yes, it explores something new"},"feedback":{"zh":"试一天已经从没接触过走到亲自尝试，投入虽小，也算开始。","en":"One day moves you from unfamiliarity to experience; a small attempt still counts as a beginning."}}],"correct":"m00-R1-898b48e3e2"}},"R2":{"teach":[{"zh":"还不了解陶艺时，先上一节体验课，看看自己是否喜欢，再考虑买工具。","en":"If pottery is unfamiliar, try one class to see whether you enjoy it before buying tools."}],"question":{"id":"m00-R2","prompt":{"zh":"先体验陶艺，再决定是否买工具，与愚人的开放态度矛盾吗？","en":"Does trying pottery before deciding whether to buy tools conflict with the Fool’s openness?"},"options":[{"id":"m00-R2-ca0b132438","text":{"zh":"不矛盾，先探索再决定","en":"No, explore before deciding"},"feedback":{"zh":"先体验可以帮助你了解陶艺，再决定买什么，既愿意尝试，也保留判断。","en":"A trial helps you understand pottery before choosing equipment, combining openness with judgment."}},{"id":"m00-R2-b41d6da6f0","text":{"zh":"矛盾，开始必须全押","en":"Yes, a start requires everything"},"feedback":{"zh":"愚人的开始不要求一次投入全部；本课正是示范先试一节课。","en":"The Fool does not require committing everything; the taught example starts with one class."}}],"correct":"m00-R2-ca0b132438"}},"R3":{"teach":[{"zh":"这里担心的是没有路线和装备的准备。查清路线、备好装备，是在处理已经知道的风险；逆位不等于一定出事。","en":"The concern is the missing route and equipment. Preparing both addresses known risks; a reversed card does not make disaster inevitable."}],"question":{"id":"m00-R3","prompt":{"zh":"补齐装备后还必定出事吗？","en":"Is trouble inevitable after preparation?"},"options":[{"id":"m00-R3-af82850448","text":{"zh":"是，逆位已经决定","en":"Yes, the reversal decides it"},"feedback":{"zh":"逆位指出本例的准备不足，不能据此断定之后必定发生事故。","en":"The reversal highlights poor preparation here; it cannot establish a later accident."}},{"id":"m00-R3-f5c19d8b31","text":{"zh":"无法由这张牌断定","en":"The card cannot establish that"},"feedback":{"zh":"准备可以处理已知风险，但这张牌本身既不能保证出事，也不能保证完全安全。","en":"Preparation addresses known risks, but the card itself guarantees neither trouble nor complete safety."}}],"correct":"m00-R3-f5c19d8b31"}}},"revisit":{"id":"m00-V1","prompt":{"zh":"你想试试写作。哪种开始方式符合本课讲的愚人？","en":"You want to try writing. Which way of starting fits the Fool as taught here?"},"options":[{"id":"m00-V1-9e0aaf7508","text":{"zh":"先写一个短篇","en":"Write a short piece first"},"feedback":{"zh":"写一个短篇能让你亲自接触写作，符合从小尝试开始探索的含义。","en":"A short piece gives direct experience of writing, fitting exploration through a small beginning."}},{"id":"m00-V1-39b414549c","text":{"zh":"等完全不再陌生才开始","en":"Wait until nothing is unfamiliar"},"feedback":{"zh":"写作还陌生时，也能通过小尝试去了解；等完全熟悉才开始，就失去了探索这一步。","en":"Small attempts help you learn something unfamiliar; waiting for complete familiarity removes that exploration."}}],"correct":"m00-V1-9e0aaf7508"},"summary":{"zh":"愚人代表新的开始，以及面对未知时愿意尝试的态度。不必一开始就投入全部，也不意味着什么准备都不用做。","en":"The Fool represents new beginnings and a willingness to try something unfamiliar. Beginning requires neither committing everything nor abandoning preparation."},"cards":["m00"]},{"id":"m01","kind":"card","level":"I","title":{"zh":"魔术师","en":"The Magician"},"teachings":[{"zh":"魔术师代表把想法变成行动：先知道自己想完成什么，再把已有的能力和工具用起来。仅仅拥有工具或表现得自信，还不等于已经做成了事情。","en":"The Magician represents turning an intention into action: know what you want to achieve, then use available abilities and tools. Owning tools or appearing confident is not the same as producing a result."},{"zh":"桌上的四类工具，以及一手朝上、一手朝下的姿势，可以帮助记住“把已有资源用来实现目标”。这些手势不是超自然能力的证明。","en":"The four kinds of tools and the raised and lowered hands help recall using available resources toward a goal. The gestures do not prove supernatural power."},{"zh":"关键词：目标、能力与工具、主动行动。这里的I是魔术师的大牌编号，不表示它与四种花色的首牌含义相同。","en":"Remember: goals, abilities and tools, initiative. I is the Magician’s major-card number; it does not give the four aces the same meaning."}],"application":{"zh":"工作建议：已经有资料、剪辑软件与时间，先明确短片主题，再制作一个片段，而非继续囤软件。","en":"Work advice: with research, editing software and time available, choose a theme and produce a clip rather than collecting more software."},"reversal":{"zh":"逆位示例：工具充足，却一直在讲计划，还没有实际动手。这里要留意的是工具有没有用起来，不能只凭这一点就断定当事人在骗人。","en":"Reversed example: tools are available, but the plan is only being discussed. Check whether they are actually being used; this alone does not establish deception."},"visual":{"zh":"桌上的四类工具，以及一手朝上、一手朝下的姿势，可以帮助记住“把已有资源用来实现目标”。这些手势不是超自然能力的证明。","en":"The four kinds of tools and the raised and lowered hands help recall using available resources toward a goal. The gestures do not prove supernatural power."},"questions":{"Q1":{"id":"m01-Q1","prompt":{"zh":"哪种做法体现了魔术师的核心含义？","en":"Which action expresses the Magician’s core meaning?"},"options":[{"id":"m01-Q1-e78962ba55","text":{"zh":"只陈列所有工具","en":"Only display every tool"},"feedback":{"zh":"把工具摆出来还没有使用它们；本课强调的是运用工具去做事。","en":"Displaying tools leaves them unused; this lesson emphasizes using them to do the work."}},{"id":"m01-Q1-f0d2db59c3","text":{"zh":"把现有能力和工具用来实现目标","en":"Use available abilities and tools toward a goal"},"feedback":{"zh":"先知道想完成什么，再使用现有工具和能力，才把目标变成了行动。","en":"A goal becomes action when available tools and abilities are used toward it."}}],"correct":"m01-Q1-f0d2db59c3","support":"R1"},"Q2":{"id":"m01-Q2","prompt":{"zh":"资料、剪辑软件和时间都已具备。按照刚才的示范，下一步做什么？","en":"With material, editing software and time available, what comes next in the example?"},"options":[{"id":"m01-Q2-fd7df8bac4","text":{"zh":"制作一个主题片段","en":"Make a focused clip"},"feedback":{"zh":"做出一个围绕主题的片段，就把已有资料和软件实际用起来了。","en":"Making a focused clip puts the available material and software to use."}},{"id":"m01-Q2-c293baba56","text":{"zh":"再买重复的软件","en":"Buy duplicate software"},"feedback":{"zh":"软件已经够用，再买重复的软件仍然没有开始制作短片。","en":"The software is already sufficient; buying duplicates still does not start the film."}}],"correct":"m01-Q2-fd7df8bac4","support":"R2"},"Q3":{"id":"m01-Q3","prompt":{"zh":"工具充足，却一直只讲计划。在这个逆位例子中，应该先检查什么？","en":"In the reversal example with enough tools but only talk, what should be checked first?"},"options":[{"id":"m01-Q3-3faf34e2d5","text":{"zh":"当事人是否天生骗子","en":"Whether the person is inherently deceitful"},"feedback":{"zh":"没有动手不等于天生爱骗人；这个例子没有提供判断人格的依据。","en":"Not starting work does not establish deceitful character; the example supplies no such evidence."}},{"id":"m01-Q3-ce9005ae15","text":{"zh":"是否已经实际执行","en":"Whether action has begun"},"feedback":{"zh":"例子的问题是工具都有了却未动手，因此先看是否真的开始执行。","en":"Tools are available but unused, so the relevant check is whether work has actually begun."}}],"correct":"m01-Q3-ce9005ae15","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"有工具是条件，用工具完成一步才是行动。","en":"Having tools is a condition; using them to complete a step is action."}],"question":{"id":"m01-R1","prompt":{"zh":"拥有画笔等于画了画吗？","en":"Does owning brushes mean a picture is painted?"},"options":[{"id":"m01-R1-a874ff3dca","text":{"zh":"不等于，要实际使用","en":"No, they must be used"},"feedback":{"zh":"画笔只是能用的工具，拿起它作画才算开始做这件事。","en":"A brush is an available tool; using it to paint begins the work."}},{"id":"m01-R1-c8b33e7e97","text":{"zh":"等于，资源就是成果","en":"Yes, resources are results"},"feedback":{"zh":"拥有画笔还没有产生画作，不能把工具本身当成成果。","en":"Owning brushes has not produced a painting; tools are not the finished result."}}],"correct":"m01-R1-a874ff3dca"}},"R2":{"teach":[{"zh":"先想清楚这次要做成什么，再挑适合的工具。工具用得多，不等于离目标更近。","en":"Decide what you want to make, then select suitable tools. Using more tools does not necessarily bring the goal closer."}],"question":{"id":"m01-R2","prompt":{"zh":"目标是短片，必须用全部工具吗？","en":"Must the clip use every tool?"},"options":[{"id":"m01-R2-82516a87d4","text":{"zh":"必须，否则不算行动","en":"Yes, otherwise it is not action"},"feedback":{"zh":"是否开始行动，要看有没有制作短片，不取决于用了多少工具。","en":"Action depends on making the clip, not on the number of tools used."}},{"id":"m01-R2-e1a2fa9854","text":{"zh":"不必，选择适用的","en":"No, use what serves it"},"feedback":{"zh":"按短片需要选工具，才能让现有资源帮助你完成目标。","en":"Selecting tools for the film lets available resources serve the goal."}}],"correct":"m01-R2-e1a2fa9854"}},"R3":{"teach":[{"zh":"把计划讲得精彩，不等于已经做出了成品。还要看有没有实际动手、做出了什么。","en":"Presenting a plan well is not the same as producing the work. Check whether work has begun and what has actually been made."}],"question":{"id":"m01-R3","prompt":{"zh":"把计划演示得很精彩，能证明作品已经做完了吗？","en":"Does an impressive presentation prove that the work is finished?"},"options":[{"id":"m01-R3-e7d11bcd48","text":{"zh":"不能，还需成果证据","en":"No, inspect the actual output"},"feedback":{"zh":"演示告诉我们计划怎样做；实际做出的作品，才能说明做到了哪一步。","en":"A presentation describes the plan; actual work shows what has been completed."}},{"id":"m01-R3-2036b44e1d","text":{"zh":"能，表达就是完成","en":"Yes, speaking is completion"},"feedback":{"zh":"讲出计划和做出作品是两件事，表达精彩不能替代制作。","en":"Presenting a plan and producing the work are different; eloquence does not replace making."}}],"correct":"m01-R3-e7d11bcd48"}}},"revisit":{"id":"m01-V1","prompt":{"zh":"已有材料想做手工，先做什么？","en":"With craft materials ready, what fits?"},"options":[{"id":"m01-V1-e4bdcfd679","text":{"zh":"永远等更好的材料","en":"Keep waiting for better materials"},"feedback":{"zh":"材料已经有了，一直等更好的材料，仍没有把现有资源用起来。","en":"Materials are available; continually waiting for better ones leaves them unused."}},{"id":"m01-V1-cda67796f4","text":{"zh":"选目标并动手做样品","en":"Choose a goal and make a sample"},"feedback":{"zh":"确定要做什么并做个样品，把已有材料变成了实际行动。","en":"Choosing what to make and building a sample turns available materials into action."}}],"correct":"m01-V1-cda67796f4"},"summary":{"zh":"魔术师代表把想法变成行动：先知道自己想完成什么，再把已有的能力和工具用起来。仅仅拥有工具或表现得自信，还不等于已经做成了事情。","en":"The Magician represents turning an intention into action: know what you want to achieve, then use available abilities and tools. Owning tools or appearing confident is not the same as producing a result."},"cards":["m01"]},{"id":"m02","kind":"card","level":"I","title":{"zh":"女祭司","en":"The High Priestess"},"teachings":[{"zh":"女祭司提醒我们先留意自己的感受，还不清楚的事，先别急着下结论。可以安静观察，也可以继续了解；不必假定自己已经知道别人的秘密，更不需要一直等着不动。","en":"The High Priestess invites attention to inner feelings and patience with what is still unclear. Observe or seek understanding before concluding; do not assume secret knowledge or wait indefinitely."},{"zh":"人物静坐，两柱之间有帷幕，卷轴部分被衣服遮住。这些被遮住的细节，可以帮助记住“有些信息还没看清”。","en":"A seated figure, a veil between pillars and a partly covered scroll support remembering information not fully revealed."},{"zh":"关键词：观察、直觉、还不清楚的信息。女祭司的编号是II，不能仅凭数字2就解释成两个人恋爱。","en":"Remember: observation, intuition, information still unclear. The High Priestess is numbered II; the number two alone does not mean romance."}],"application":{"zh":"收到一句意思不清的回复，心里有些不安。可以先想想是哪句话让你不舒服，再问清对方的意思；不要仅凭不安就认定对方在隐瞒。","en":"An unclear reply leaves you uneasy. Notice which words bothered you, then ask what the other person meant. Unease alone does not establish that they are hiding something."},"reversal":{"zh":"逆位示例：明明觉得不舒服，却没有理会自己的感受，反而凭传言下结论。先留意这份不安，再查证消息；感到不安还不能证明传言是真的。","en":"Reversed example: someone ignores personal unease but accepts a rumor. Notice the feeling and check the report; unease does not prove the rumor true."},"visual":{"zh":"人物静坐，两柱之间有帷幕，卷轴部分被衣服遮住。这些被遮住的细节，可以帮助记住“有些信息还没看清”。","en":"A seated figure, a veil between pillars and a partly covered scroll support remembering information not fully revealed."},"questions":{"Q1":{"id":"m02-Q1","prompt":{"zh":"信息还不清楚时，女祭司提醒我们怎样做？","en":"What does the High Priestess suggest doing when information is still unclear?"},"options":[{"id":"m02-Q1-0e68c2c9f9","text":{"zh":"先观察，了解更多后再下结论","en":"Observe and learn more before concluding"},"feedback":{"zh":"信息还不清楚时，先了解再判断，才不会把猜测当成已经知道的事。","en":"Learning before judging unclear information avoids treating guesses as known facts."}},{"id":"m02-Q1-b1247bfab5","text":{"zh":"证明自己知道秘密","en":"Prove secret knowledge"},"feedback":{"zh":"看到某些内容被遮住，只能知道没有看清，不能因此知道藏着什么。","en":"Seeing concealment shows that something is unclear, not what it contains."}}],"correct":"m02-Q1-0e68c2c9f9","support":"R1"},"Q2":{"id":"m02-Q2","prompt":{"zh":"收到含糊的回复后感到不安，怎样运用女祭司的含义？","en":"How can you apply the High Priestess when an unclear reply makes you uneasy?"},"options":[{"id":"m02-Q2-ef41397288","text":{"zh":"因为自己感到不安，就认定对方在撒谎","en":"Conclude that the other person is lying because you feel uneasy"},"feedback":{"zh":"不安说明你有这种感受，还不能证明对方撒谎或有所隐瞒。","en":"Unease establishes your feeling, not that the other person is lying or hiding something."}},{"id":"m02-Q2-2b09752cbc","text":{"zh":"先留意自己的不安，再问清对方的意思","en":"Notice your unease, then ask what the other person means"},"feedback":{"zh":"先弄清自己为什么不舒服，再问清对方的意思。这样既没有忽略自己的感受，也没有把猜测当成事实。","en":"Notice what bothered you, then clarify what the other person meant. This acknowledges your feelings without treating a guess as fact."}}],"correct":"m02-Q2-2b09752cbc","support":"R2"},"Q3":{"id":"m02-Q3","prompt":{"zh":"在忽视不适、却凭传言下结论的例子里，女祭司逆位提醒什么？","en":"What does the reversed High Priestess highlight when unease is ignored but rumor is accepted?"},"options":[{"id":"m02-Q3-71db1585c0","text":{"zh":"留意自己的不安并查证传言，不把感受当成事实","en":"Notice your unease and verify the rumor instead of treating a feeling as fact"},"feedback":{"zh":"例子漏掉了对自身感受的留意，也没有查证传言；这两步都需要补上。","en":"The example neglects inner feelings and verification of rumor; both need attention."}},{"id":"m02-Q3-ecefdcd13c","text":{"zh":"相信传言就是真相","en":"Treat the rumor as truth"},"feedback":{"zh":"传言还没有核实，不能因为听到了它就当成事实。","en":"An unverified rumor does not become fact simply because it has been heard."}}],"correct":"m02-Q3-71db1585c0","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"感到不安是真实的体验，但其原因仍需核实。","en":"Unease is a real experience; its cause still needs checking."}],"question":{"id":"m02-R1","prompt":{"zh":"感到不安，能证明对方心里一定在想什么吗？","en":"Does feeling uneasy establish what another person must be thinking?"},"options":[{"id":"m02-R1-6afaa85312","text":{"zh":"能，直觉不会有错","en":"Yes, intuition is infallible"},"feedback":{"zh":"心里有一种感觉，不等于已经查明对方为什么这样做。","en":"Having an inner feeling does not establish why another person acted that way."}},{"id":"m02-R1-d1edcd6eb8","text":{"zh":"不能，需要核实","en":"No, check the cause"},"feedback":{"zh":"你确实感到不安，但为什么不安、对方在想什么，还需要分别了解。","en":"Your unease is real, but its cause and the other person’s motives still need checking."}}],"correct":"m02-R1-d1edcd6eb8"}},"R2":{"teach":[{"zh":"还没想清楚时可以先不判断，同时问一问对方究竟是什么意思。","en":"You can withhold judgment while asking what the other person means."}],"question":{"id":"m02-R2","prompt":{"zh":"暂时不下结论时，可以主动询问对方吗？","en":"Can you ask the other person while withholding judgment?"},"options":[{"id":"m02-R2-7af945c65c","text":{"zh":"可以，询问帮助澄清","en":"Yes, questions clarify"},"feedback":{"zh":"询问可以补充尚不清楚的信息，暂时不判断不妨碍主动了解。","en":"Questions can clarify missing information; withholding judgment does not prevent inquiry."}},{"id":"m02-R2-df3b3ca4e0","text":{"zh":"不行，只能一直等待","en":"No, only wait forever"},"feedback":{"zh":"本课的暂缓是先了解再判断，不是要求一直等待、什么都不做。","en":"The pause allows understanding before judgment; it is not an instruction to wait forever."}}],"correct":"m02-R2-7af945c65c"}},"R3":{"teach":[{"zh":"抽到逆位也不能证明传言是真的。先留意自己的不安，再核对传言的来源和事实。","en":"A reversed card cannot prove a rumor true. Notice your unease, then check the source and facts."}],"question":{"id":"m02-R3","prompt":{"zh":"逆位是否让传言可靠？","en":"Does reversal make a rumor reliable?"},"options":[{"id":"m02-R3-0a966f681d","text":{"zh":"会，隐藏信息被证实","en":"Yes, hidden facts are confirmed"},"feedback":{"zh":"逆位没有提供新的事实，不能让没有查证的消息变成可靠消息。","en":"A reversal supplies no new facts and cannot make unchecked news reliable."}},{"id":"m02-R3-b40899d33c","text":{"zh":"不会，还需核对","en":"No, verification remains needed"},"feedback":{"zh":"传言是否可靠仍要看来源和事实，不能由牌的方向决定。","en":"Reliability depends on sources and facts, not on the card’s orientation."}}],"correct":"m02-R3-b40899d33c"}}},"revisit":{"id":"m02-V1","prompt":{"zh":"审阅资料时，有些信息还不完整。哪种做法符合本课含义？","en":"While reviewing incomplete material, which action fits this lesson?"},"options":[{"id":"m02-V1-5b9666609c","text":{"zh":"标出疑问后求证","en":"Identify questions and verify"},"feedback":{"zh":"把不清楚的地方标出来再求证，正是先承认不知道，再继续了解。","en":"Marking uncertainties and checking them acknowledges what is unknown before learning more."}},{"id":"m02-V1-cf03650575","text":{"zh":"用猜测填满空白","en":"Fill gaps with guesses"},"feedback":{"zh":"猜测填满了空白，却没有增加事实，不能代替求证。","en":"Filling gaps with guesses adds no facts and cannot replace verification."}}],"correct":"m02-V1-5b9666609c"},"summary":{"zh":"女祭司提醒我们先留意自己的感受，还不清楚的事，先别急着下结论。可以安静观察，也可以继续了解；不必假定自己已经知道别人的秘密，更不需要一直等着不动。","en":"The High Priestess invites attention to inner feelings and patience with what is still unclear. Observe or seek understanding before concluding; do not assume secret knowledge or wait indefinitely."},"cards":["m02"]},{"id":"m03","kind":"card","level":"I","title":{"zh":"皇后","en":"The Empress"},"teachings":[{"zh":"皇后代表照顾、创造，以及事物慢慢成长的丰盛。成长需要时间、材料和照顾，照顾者也需要休息，不是要求一个人无止境地付出。","en":"The Empress represents care, creativity and the abundance of gradual growth. Growth needs time, materials and care, including rest for the caregiver; it does not demand endless giving."},{"zh":"麦田、树木与舒适坐席帮助记住适合生长的环境，不据此判断任何人的怀孕或身体状况。","en":"Grain, trees and a comfortable seat suggest a nourishing environment, not anyone’s pregnancy or health."},{"zh":"关键词：照顾、创造、成长、丰盛。皇后的编号是III，理解含义时仍要看这张牌本身。","en":"Remember: care, creativity, growth, abundance. The Empress is numbered III; its meaning still belongs to the card itself."}],"application":{"zh":"创作建议：给插画安排固定时间、合适材料与休息，让作品逐渐成形；不是只催自己马上交出成果。","en":"Creative advice: provide time, materials and rest for an illustration to develop, rather than demanding an instant result."},"reversal":{"zh":"逆位示例：一直照顾团队却忽略自身休息，创造力下降。这里需要留意自己是否只顾付出、没有休息，并留出时间恢复精力。","en":"Reversed example: caring for a team without resting has drained creativity. Notice giving without recovery and make time to restore energy."},"visual":{"zh":"麦田、树木与舒适坐席帮助记住适合生长的环境，不据此判断任何人的怀孕或身体状况。","en":"Grain, trees and a comfortable seat suggest a nourishing environment, not anyone’s pregnancy or health."},"questions":{"Q1":{"id":"m03-Q1","prompt":{"zh":"滋养主要指什么？","en":"What does nourishment mean here?"},"options":[{"id":"m03-Q1-9ae9cf624f","text":{"zh":"强迫立即完成","en":"Force instant completion"},"feedback":{"zh":"只要求马上完成，没有提供成长需要的时间与支持。","en":"Demanding instant completion does not provide the time and support that growth needs."}},{"id":"m03-Q1-1115e538c3","text":{"zh":"提供成长需要的时间、资源与照顾","en":"Provide the time, resources and care needed for growth"},"feedback":{"zh":"有时间、资源和照顾，事物才有机会逐渐发展，这就是本课的滋养。","en":"Time, resources and care allow gradual development, which is nurture as taught here."}}],"correct":"m03-Q1-1115e538c3","support":"R1"},"Q2":{"id":"m03-Q2","prompt":{"zh":"在插画创作的例子里，哪种做法体现了皇后的滋养？","en":"Which action expresses the Empress’s nurture in the illustration example?"},"options":[{"id":"m03-Q2-7dc456fd46","text":{"zh":"安排材料时间与休息","en":"Arrange materials, time and rest"},"feedback":{"zh":"材料帮助完成作品，时间和休息让创作者能持续创作。","en":"Materials support the work; time and rest help the creator keep making it."}},{"id":"m03-Q2-31aaa03ff1","text":{"zh":"只增加完成压力","en":"Add only pressure to finish"},"feedback":{"zh":"增加压力不能补足材料、时间或休息，创作仍然缺少支持。","en":"More pressure does not provide materials, time or rest; support is still missing."}}],"correct":"m03-Q2-7dc456fd46","support":"R2"},"Q3":{"id":"m03-Q3","prompt":{"zh":"在照顾团队却忽略自己休息的例子里，皇后逆位提醒关注什么？","en":"What does the reversed Empress highlight when someone cares for a team but neglects rest?"},"options":[{"id":"m03-Q3-186e28f2f1","text":{"zh":"永久停止关心他人","en":"Stop caring forever"},"feedback":{"zh":"问题是长期只付出、不休息，不是关心别人这件事本身有错。","en":"The problem is giving without rest, not that caring for others is wrong."}},{"id":"m03-Q3-26c3ec6bd6","text":{"zh":"留出休息时间，恢复精力","en":"Make time to rest and recover energy"},"feedback":{"zh":"例子中创造力已经因缺少休息而下降，先恢复精力回应了这种失衡。","en":"Creativity has fallen through lack of rest; recovering energy addresses that imbalance."}}],"correct":"m03-Q3-26c3ec6bd6","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"照顾不是替事物瞬间长大，而是提供持续生长的条件。","en":"Care provides conditions for growth; it does not force instant maturity."}],"question":{"id":"m03-R1","prompt":{"zh":"花盆缺水时“滋养”是什么？","en":"What is nurture for a dry plant?"},"options":[{"id":"m03-R1-9e8deea435","text":{"zh":"提供合适水分","en":"Supply suitable water"},"feedback":{"zh":"花缺水时，提供合适水分才能支持它生长。","en":"When a plant lacks water, suitable watering supports its growth."}},{"id":"m03-R1-f850a6954c","text":{"zh":"要求今天开花","en":"Demand flowers today"},"feedback":{"zh":"要求开花并没有给花补水，不能代替实际照顾。","en":"Demanding flowers does not supply water or replace care."}}],"correct":"m03-R1-9e8deea435"}},"R2":{"teach":[{"zh":"支持作品也包括支持创作者：休息是条件之一。","en":"Supporting work includes supporting its creator; rest is one condition."}],"question":{"id":"m03-R2","prompt":{"zh":"创作者休息属于照顾作品吗？","en":"Can the creator's rest support the work?"},"options":[{"id":"m03-R2-9398b513d9","text":{"zh":"不属于，只有材料重要","en":"No, only materials matter"},"feedback":{"zh":"作品需要材料，也需要有精力的创作者；只看材料会漏掉人的需要。","en":"A work needs both materials and an energized creator; materials alone omit the person’s needs."}},{"id":"m03-R2-3ff0db56f8","text":{"zh":"属于，休息能恢复创作精力","en":"Yes, rest restores energy for creating"},"feedback":{"zh":"作品由人完成，创作者休息好，才更有精力继续创作。","en":"People make the work; rest restores the energy needed to continue."}}],"correct":"m03-R2-3ff0db56f8"}},"R3":{"teach":[{"zh":"本例不是“不能再关心别人”，而是不能长期只付出不恢复。","en":"This example concerns unrenewed giving, not a ban on caring for others."}],"question":{"id":"m03-R3","prompt":{"zh":"已经因持续付出而疲惫，还需要无休止地继续付出吗？","en":"When continual giving has caused exhaustion, is endless further giving needed?"},"options":[{"id":"m03-R3-ef201d2c90","text":{"zh":"不需要，先调整失衡","en":"No, address the imbalance"},"feedback":{"zh":"已经疲惫，说明需要休息与恢复；继续只付出会延续同一个问题。","en":"Existing exhaustion calls for rest and recovery; unbroken giving continues the same problem."}},{"id":"m03-R3-553b376c45","text":{"zh":"需要，越耗尽自己越能照顾大家","en":"Yes, exhausting yourself lets you care for everyone better"},"feedback":{"zh":"把自己耗尽并没有提供持续照顾的能力，与本课支持成长的含义相反。","en":"Exhausting yourself does not sustain care and conflicts with supporting growth."}}],"correct":"m03-R3-ef201d2c90"}}},"revisit":{"id":"m03-V1","prompt":{"zh":"一个新社团想慢慢发展起来，哪种做法符合皇后的滋养？","en":"Which action expresses nurture as a new club develops?"},"options":[{"id":"m03-V1-341bdbc9a4","text":{"zh":"只要求人数立刻翻倍","en":"Only demand instant growth"},"feedback":{"zh":"要求人数翻倍只规定了结果，没有说明怎样支持成员成长。","en":"Demanding doubled membership names a result without supporting members’ growth."}},{"id":"m03-V1-f9c475f5f8","text":{"zh":"给成员资源与支持","en":"Offer resources and support"},"feedback":{"zh":"给成员所需的资源和帮助，才是在建立能够逐渐发展的环境。","en":"Giving members resources and help creates conditions in which the club can develop."}}],"correct":"m03-V1-f9c475f5f8"},"summary":{"zh":"皇后代表照顾、创造，以及事物慢慢成长的丰盛。成长需要时间、材料和照顾，照顾者也需要休息，不是要求一个人无止境地付出。","en":"The Empress represents care, creativity and the abundance of gradual growth. Growth needs time, materials and care, including rest for the caregiver; it does not demand endless giving."},"cards":["m03"]},{"id":"m04","kind":"card","level":"I","title":{"zh":"皇帝","en":"The Emperor"},"teachings":[{"zh":"皇帝代表秩序、责任和清楚的界限。谁负责什么、有哪些需要遵守的规则，安排清楚了才容易稳定；不等于所有决定都必须由一个人控制。","en":"The Emperor represents order, responsibility and clear limits. Stability benefits from clear duties and rules, not necessarily one person controlling every decision."},{"zh":"石座、铠甲和端正姿态可以帮助记住稳定的秩序与保护；不能用人物性别断定现实中的某位男性。","en":"The stone throne, armor and upright posture support structure and protection, not identification of a particular man."},{"zh":"关键词：秩序、责任、边界。IV可帮助整理稳定主题，不证明一切规则合理。","en":"Recall labels: order, responsibility, boundaries. IV may organize stability, not validate every rule."}],"application":{"zh":"工作建议：项目常漏交接，先说明谁负责交、谁负责接、什么时候交，以及怎样才算交接完成。","en":"Work advice: when handovers are missed, specify who hands over to whom, the deadline, and what counts as completion."},"reversal":{"zh":"逆位示例：负责人不许按实际情况调整，流程停滞。本例强调控制与僵化，而不是所有管理都不好。","en":"Reversed example: a manager forbids adjustments and work stalls. Here control becomes rigidity, not a rejection of all management."},"visual":{"zh":"石座、铠甲和端正姿态可以帮助记住稳定的秩序与保护；不能用人物性别断定现实中的某位男性。","en":"The stone throne, armor and upright posture support structure and protection, not identification of a particular man."},"questions":{"Q1":{"id":"m04-Q1","prompt":{"zh":"皇帝的秩序靠什么落实？","en":"What makes this order practical?"},"options":[{"id":"m04-Q1-fa3f7fab0a","text":{"zh":"明确责任与边界","en":"Clear responsibilities and boundaries"},"feedback":{"zh":"每个人知道负责什么、有哪些界限，工作才有清楚的安排。","en":"Work has a clear arrangement when people know their responsibilities and limits."}},{"id":"m04-Q1-102c203728","text":{"zh":"所有事只听一人","en":"One person dictates everything"},"feedback":{"zh":"所有事只听一人，并不能保证责任清楚，也不等于安排合理。","en":"One person dictating everything does not ensure clear duties or sound arrangements."}}],"correct":"m04-Q1-fa3f7fab0a","support":"R1"},"Q2":{"id":"m04-Q2","prompt":{"zh":"项目经常漏交接，按照刚才的示范，先改进什么？","en":"What should change first when project handovers are often missed?"},"options":[{"id":"m04-Q2-7cbe7a9d45","text":{"zh":"只重复要求认真","en":"Only demand more care"},"feedback":{"zh":"只说认真一点，没有说明谁来交接、何时完成，原来的遗漏仍可能发生。","en":"Asking for more care does not identify who hands over or when; the same omission may recur."}},{"id":"m04-Q2-33fdfead43","text":{"zh":"明确谁交给谁及期限","en":"Specify people and deadlines"},"feedback":{"zh":"把交接双方和时间说清楚，才让每个人知道该完成哪一步。","en":"Naming both parties and the deadline tells each person what to do."}}],"correct":"m04-Q2-33fdfead43","support":"R2"},"Q3":{"id":"m04-Q3","prompt":{"zh":"在负责人不许调整、流程因此停滞的逆位例子里，怎样调整更合适？","en":"In the reversal example where rigid management stalls work, what adjustment fits?"},"options":[{"id":"m04-Q3-f47a4c9977","text":{"zh":"保留边界并调整流程","en":"Keep boundaries, adapt procedures"},"feedback":{"zh":"必要的职责仍然保留，同时按实际情况改流程，可以让事情重新推进。","en":"Keeping necessary duties while adapting the process lets work proceed again."}},{"id":"m04-Q3-3296fe7db3","text":{"zh":"禁止一切调整","en":"Ban every adjustment"},"feedback":{"zh":"例子已说明不能调整使流程停滞，继续禁止调整会保留这个问题。","en":"The example says rigidity has stalled work; forbidding change preserves that problem."}}],"correct":"m04-Q3-f47a4c9977","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"责任清楚才能协作；规则不是为了证明谁更强。","en":"Clear responsibility supports cooperation; rules are not a strength contest."}],"question":{"id":"m04-R1","prompt":{"zh":"规则应帮助协作还是争强？","en":"Should rules support cooperation or domination?"},"options":[{"id":"m04-R1-f71e43c2eb","text":{"zh":"证明谁最强","en":"Prove who is strongest"},"feedback":{"zh":"规则是让大家知道怎样协作，不是用来证明某个人比别人强。","en":"Rules clarify cooperation; they are not a contest over who is strongest."}},{"id":"m04-R1-950f493e63","text":{"zh":"支持协作","en":"Support cooperation"},"feedback":{"zh":"责任分清楚，大家才知道怎样配合，规则因此有实际作用。","en":"Clear responsibilities show people how to work together and give rules practical value."}}],"correct":"m04-R1-950f493e63"}},"R2":{"teach":[{"zh":"交接问题需要能执行的约定，单纯催促不能替代负责人。","en":"Handover needs workable agreements; pressure cannot replace ownership."}],"question":{"id":"m04-R2","prompt":{"zh":"只有期限没有负责人够吗？","en":"Is a deadline enough without an owner?"},"options":[{"id":"m04-R2-320b9132c1","text":{"zh":"不够，还需职责","en":"No, assign responsibility"},"feedback":{"zh":"知道什么时候交，还要知道谁来交、谁来接，否则仍可能无人负责。","en":"A deadline also needs identified senders and recipients, or responsibility may remain unassigned."}},{"id":"m04-R2-c8ccd28cd1","text":{"zh":"足够，时间解决一切","en":"Yes, time solves everything"},"feedback":{"zh":"期限不会自动指定负责人，时间到了仍可能没有人交接。","en":"A deadline does not assign responsibility; the handover may still lack an owner."}}],"correct":"m04-R2-320b9132c1"}},"R3":{"teach":[{"zh":"保留必要边界，同时允许按已知变化修订流程。","en":"Keep necessary boundaries while revising procedures for known changes."}],"question":{"id":"m04-R3","prompt":{"zh":"灵活调整等于取消全部规则吗？","en":"Does adapting mean removing every rule?"},"options":[{"id":"m04-R3-4bc69a0562","text":{"zh":"等于","en":"Yes"},"feedback":{"zh":"修改不合适的步骤，可以继续保留职责和必要界限，不必把规则全部取消。","en":"Unsuitable steps can change while duties and necessary limits remain."}},{"id":"m04-R3-9678e3a7cb","text":{"zh":"不等于","en":"No"},"feedback":{"zh":"可以保留谁负责什么，同时调整怎样交接；两者并不冲突。","en":"Responsibilities can stay clear while handover methods change; the two are compatible."}}],"correct":"m04-R3-9678e3a7cb"}}},"revisit":{"id":"m04-V1","prompt":{"zh":"怎样把皇帝的含义用在合租的公共事务中？","en":"How can the Emperor’s meaning apply to shared-house responsibilities?"},"options":[{"id":"m04-V1-fb485b5f28","text":{"zh":"约定分工与边界","en":"Agree duties and boundaries"},"feedback":{"zh":"把清洁等公共事务的分工和界限约定好，大家才知道各自的责任。","en":"Agreed duties and limits for shared tasks tell residents what each is responsible for."}},{"id":"m04-V1-5218dc7539","text":{"zh":"靠一人一直包办","en":"Let one person do everything"},"feedback":{"zh":"一人包办没有让其他人承担清楚的责任，也没有建立共同遵守的安排。","en":"One person doing everything leaves others without clear duties or a shared arrangement."}}],"correct":"m04-V1-fb485b5f28"},"summary":{"zh":"皇帝代表秩序、责任和清楚的界限。谁负责什么、有哪些需要遵守的规则，安排清楚了才容易稳定；不等于所有决定都必须由一个人控制。","en":"The Emperor represents order, responsibility and clear limits. Stability benefits from clear duties and rules, not necessarily one person controlling every decision."},"cards":["m04"]},{"id":"m05","kind":"card","level":"I","title":{"zh":"教皇","en":"The Hierophant"},"teachings":[{"zh":"教皇代表向老师、机构或群体学习已有的知识和方法，也包括大家共同遵守的规范。已有经验可以帮助新手起步，但学习传统不等于不能提问。","en":"The Hierophant represents learning established knowledge and methods from teachers, institutions or groups, including shared standards. Tradition can support beginners without forbidding questions."},{"zh":"居中的人物、两名学习者与钥匙，可以帮助记住向已有经验学习，不用宗教服饰判断人的信仰。","en":"The central figure, two learners and keys support teaching and entry into a tradition, not claims about a person’s faith."},{"zh":"关键词：传承、向前人学习、共同规范。教皇的编号是V，但不能只凭数字5就把它解释成混乱。","en":"Remember: tradition, learning from others’ experience, shared standards. The Hierophant is numbered V, but five alone does not make its meaning chaos."}],"application":{"zh":"学习建议：首次学木工，先跟合格老师学安全流程与基本技法，再逐步独立。","en":"Study advice: learn safety and basic woodworking from a qualified teacher before working independently."},"reversal":{"zh":"逆位示例：某条老规定已不适用，却只因“过去如此”继续执行。需要重新检查这条规则现在是否合用，不等于拒绝所有指导。","en":"Reversed example: an outdated rule is kept only because it has always been used. Reassess this rule’s present relevance rather than reject all guidance."},"visual":{"zh":"居中的人物、两名学习者与钥匙，可以帮助记住向已有经验学习，不用宗教服饰判断人的信仰。","en":"The central figure, two learners and keys support teaching and entry into a tradition, not claims about a person’s faith."},"questions":{"Q1":{"id":"m05-Q1","prompt":{"zh":"本课讲的教皇，主要与哪种学习方式有关？","en":"Which approach to learning matches the Hierophant as taught here?"},"options":[{"id":"m05-Q1-2cfb27d81d","text":{"zh":"拒绝任何学习方法","en":"Reject every method"},"feedback":{"zh":"本课讲的是从已有经验中学习，拒绝所有方法就没有进行这一步。","en":"This lesson concerns learning from established experience; rejecting every method prevents that."}},{"id":"m05-Q1-9d2fc7807a","text":{"zh":"跟着已有的知识和方法学习","en":"Learn established knowledge and methods"},"feedback":{"zh":"老师或群体传授已有的知识与做法，正体现了传承和学习。","en":"A teacher or group passing on established knowledge and methods expresses tradition and learning."}}],"correct":"m05-Q1-9d2fc7807a","support":"R1"},"Q2":{"id":"m05-Q2","prompt":{"zh":"木工新手先做什么？","en":"What should the woodworking beginner do?"},"options":[{"id":"m05-Q2-5906b04891","text":{"zh":"学安全与基本技法","en":"Learn safety and basics"},"feedback":{"zh":"安全流程和基本技法，是新手能够逐步开始木工的基础。","en":"Safety procedures and basic techniques provide a foundation for beginning woodworking."}},{"id":"m05-Q2-5d4fe5fb83","text":{"zh":"跳过基础直接操作","en":"Skip basics and start working"},"feedback":{"zh":"还没学过怎样安全操作就直接动手，跳过了例子要求先学习的基础。","en":"Working before learning safe operation skips the foundation taught in the example."}}],"correct":"m05-Q2-5906b04891","support":"R2"},"Q3":{"id":"m05-Q3","prompt":{"zh":"在老规定已经不适用的逆位例子里，应该怎样做？","en":"What should be done in the reversal example about an outdated rule?"},"options":[{"id":"m05-Q3-79ab602c4b","text":{"zh":"因古老就永远照做","en":"Obey forever because it is old"},"feedback":{"zh":"沿用多久不能证明现在仍适用；例子已经指出这条规定不合实际。","en":"A rule’s age does not prove present relevance; this example says it no longer fits."}},{"id":"m05-Q3-aa722cd937","text":{"zh":"评估规则是否适用","en":"Assess its relevance"},"feedback":{"zh":"先弄清规则现在是否有用，才能决定继续保留还是修改。","en":"Checking current relevance supports a decision about retaining or revising the rule."}}],"correct":"m05-Q3-aa722cd937","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"向已有方法学习，要弄懂怎样做、为什么这样做，不只是记住是谁说的。","en":"Learning an established method involves understanding how and why, not merely who said it."}],"question":{"id":"m05-R1","prompt":{"zh":"向老师提问违反传承吗？","en":"Does asking a teacher violate tradition?"},"options":[{"id":"m05-R1-2319a5cbf9","text":{"zh":"不违反，可帮助理解","en":"No, it can deepen understanding"},"feedback":{"zh":"问清为什么这样做，可以帮助理解传授的方法，并没有拒绝学习。","en":"Asking why a method works deepens understanding rather than rejecting instruction."}},{"id":"m05-R1-62997ad7dd","text":{"zh":"违反，只能照抄","en":"Yes, only copying is allowed"},"feedback":{"zh":"本课没有要求只能照抄；理解原因也是学习的一部分。","en":"The lesson does not require copying alone; understanding reasons is part of learning."}}],"correct":"m05-R1-2319a5cbf9"}},"R2":{"teach":[{"zh":"基础教学给新手一套可以照着练的方法；遇到不懂的地方提问，才能理解规则的原因。","en":"Foundational teaching gives beginners a method to practise. Questions help explain the reasons behind unfamiliar rules."}],"question":{"id":"m05-R2","prompt":{"zh":"新手学习规范是为了什么？","en":"Why learn basic standards?"},"options":[{"id":"m05-R2-a87c42c919","text":{"zh":"永不形成自己的判断","en":"Never develop judgment"},"feedback":{"zh":"学习方法是帮助起步，不是要求以后所有事情都由老师替你判断。","en":"Learning a method supports a beginning, not permanent dependence on a teacher’s judgment."}},{"id":"m05-R2-6ce321b20e","text":{"zh":"建立可依循的方法","en":"Establish a usable method"},"feedback":{"zh":"先有可以照着练的方法，才能逐步理解并形成自己的判断。","en":"A method to practise provides a starting point for understanding and developing judgment."}}],"correct":"m05-R2-6ce321b20e"}},"R3":{"teach":[{"zh":"审视一条过时规则不等于所有规则都失效。","en":"Questioning an outdated rule does not invalidate every rule."}],"question":{"id":"m05-R3","prompt":{"zh":"一条规则过时说明什么？","en":"What follows from one outdated rule?"},"options":[{"id":"m05-R3-cfe819d93a","text":{"zh":"这条需要重新评估","en":"This rule needs reassessment"},"feedback":{"zh":"已知的是这一条不适用，所以先重新检查这一条规则。","en":"The known issue concerns this particular rule, so reassess that rule first."}},{"id":"m05-R3-9340c7c1b1","text":{"zh":"所有指导都无用","en":"All guidance is useless"},"feedback":{"zh":"一条规则失效，并没有证明其他规则或指导也都没有用。","en":"One unsuitable rule does not establish that all other guidance is useless."}}],"correct":"m05-R3-cfe819d93a"}}},"revisit":{"id":"m05-V1","prompt":{"zh":"刚加入合唱团，哪种做法符合本课讲的教皇？","en":"Which action fits the Hierophant when joining a choir?"},"options":[{"id":"m05-V1-f56f7a6c9f","text":{"zh":"不听说明直接各唱各的","en":"Ignore guidance and sing separately"},"feedback":{"zh":"合唱需要共同的练习方法，各唱各的没有学会怎样配合。","en":"A choir needs shared practice methods; singing separately does not teach coordination."}},{"id":"m05-V1-40d8037726","text":{"zh":"学共同练习规范","en":"Learn shared practice standards"},"feedback":{"zh":"先学团体共同使用的练习规范，符合从已有方法和群体经验中学习。","en":"Learning shared practice standards fits learning from established methods and group experience."}}],"correct":"m05-V1-40d8037726"},"summary":{"zh":"教皇代表向老师、机构或群体学习已有的知识和方法，也包括大家共同遵守的规范。已有经验可以帮助新手起步，但学习传统不等于不能提问。","en":"The Hierophant represents learning established knowledge and methods from teachers, institutions or groups, including shared standards. Tradition can support beginners without forbidding questions."},"cards":["m05"]},{"id":"m06","kind":"card","level":"I","title":{"zh":"恋人","en":"The Lovers"},"teachings":[{"zh":"恋人代表吸引、关系，以及按照自己真正重视的事情作选择。涉及两个人时，还要看双方是否认同。它不只指恋爱，也不保证关系结果。","en":"The Lovers represents attraction, relationships and choices reflecting what matters most. When two people are involved, mutual agreement also matters. Romance is not its only meaning or a guaranteed outcome."},{"zh":"两个人物和上方天使，可以帮助记住关系，以及自己真正重视的事情；画面不能替对方作承诺。","en":"Two figures and an angel support relationship and values; the image cannot make another person’s commitment."},{"zh":"关键词：连接、重要选择、相互认同。恋人的编号是VI，但抽到它并不保证感情一定成功。","en":"Remember: connection, important choices, mutual agreement. The Lovers is numbered VI, but drawing it does not guarantee romantic success."}],"application":{"zh":"职业选择建议：两份工作待遇相近，一份支持你重视的创作，另一份要求放弃它。先想清楚自己是否愿意为了工作放下创作，再作决定。","en":"Career advice: two jobs offer similar pay, but only one supports valued creative work. Decide whether you are willing to give up creativity for the job before choosing."},"reversal":{"zh":"逆位示例：两人已明确想要不同的生活安排，却回避讨论。先看看双方哪里想得不同、为什么迟迟不作选择；不能据此认定他们一定会分手。","en":"Reversed example: two people want different living arrangements but avoid discussing them. Examine the disagreement and delayed choice without declaring inevitable separation."},"visual":{"zh":"两个人物和上方天使，可以帮助记住关系，以及自己真正重视的事情；画面不能替对方作承诺。","en":"Two figures and an angel support relationship and values; the image cannot make another person’s commitment."},"questions":{"Q1":{"id":"m06-Q1","prompt":{"zh":"恋人只适用于恋爱吗？","en":"Is the Lovers only about romance?"},"options":[{"id":"m06-Q1-ed64e280f9","text":{"zh":"不是，也涉及按自己重视的事情作选择","en":"No, it also involves choosing according to what matters to you"},"feedback":{"zh":"职业、合作等选择也可能涉及自己重视的事情，并不只有恋爱才会遇到。","en":"Work and collaboration choices can also involve personal values; this is not limited to romance."}},{"id":"m06-Q1-3ed9cd510b","text":{"zh":"是，其他问题不能用","en":"Yes, no other issue applies"},"feedback":{"zh":"本课已经包括重要选择与相互认同，因此把它限制为恋爱会漏掉这些含义。","en":"The lesson also includes important choices and mutual agreement, which a romance-only reading omits."}}],"correct":"m06-Q1-ed64e280f9","support":"R1"},"Q2":{"id":"m06-Q2","prompt":{"zh":"两份工作的待遇相近，但只有一份允许继续创作。这个例子首先要想清楚什么？","en":"Two jobs offer similar pay, but only one allows continued creative work. What needs clarifying first?"},"options":[{"id":"m06-Q2-040510c54d","text":{"zh":"只看两份工资相同","en":"Only note equal salaries"},"feedback":{"zh":"工资相近已经是背景条件，真正的差别是能否保留自己重视的创作。","en":"Similar pay is already given; the relevant difference is whether valued creative work can continue."}},{"id":"m06-Q2-8bad8f0a14","text":{"zh":"想清楚是否愿意为了工作放下创作","en":"Decide whether you are willing to give up creative work for the job"},"feedback":{"zh":"例子明确说你重视创作，先弄清能否接受放下它，才是在处理这次取舍。","en":"The example says creativity matters to you, so deciding whether to relinquish it addresses the trade-off."}}],"correct":"m06-Q2-8bad8f0a14","support":"R2"},"Q3":{"id":"m06-Q3","prompt":{"zh":"两人想要的生活安排不同，又回避讨论。在这个逆位例子里，先处理什么？","en":"Two people want different living arrangements and avoid discussing them. What should be addressed first?"},"options":[{"id":"m06-Q3-2ed70e765b","text":{"zh":"讨论双方不一致","en":"Discuss the disagreement"},"feedback":{"zh":"已经知道双方想法不同却没有谈清楚，讨论差异才回应了当前问题。","en":"Different wishes and avoided discussion are given; discussing them addresses the present issue."}},{"id":"m06-Q3-69e97092ee","text":{"zh":"宣布必然分手","en":"Declare inevitable separation"},"feedback":{"zh":"生活安排不同不等于关系已经结束，例子没有说明双方会怎样决定。","en":"Different living preferences do not establish separation; the example gives no final decision."}}],"correct":"m06-Q3-2ed70e765b","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"两个人互相吸引，不等于他们重视的事情和想过的生活都一样。这两个方面需要分别了解。","en":"Mutual attraction does not establish identical priorities or desired lives. Examine those aspects separately."}],"question":{"id":"m06-R1","prompt":{"zh":"互相吸引，就代表想要的生活和重视的事情都相同吗？","en":"Does attraction prove shared values?"},"options":[{"id":"m06-R1-9db6b1dec8","text":{"zh":"代表","en":"Yes"},"feedback":{"zh":"互相吸引只能说明有吸引，不能因此知道双方对生活和原则的看法都相同。","en":"Attraction alone does not establish matching views about life or principles."}},{"id":"m06-R1-b8fa898323","text":{"zh":"不代表","en":"No"},"feedback":{"zh":"是否吸引与重视什么是两个方面，需要分别了解。","en":"Attraction and personal priorities are distinct and need separate consideration."}}],"correct":"m06-R1-b8fa898323"}},"R2":{"teach":[{"zh":"选择要看你自己重视什么。有人最看重创作，有人更看重别的事情，因此不能替所有人规定同一个职业答案。","en":"Choices depend on personal priorities. Creativity matters most to some people, while others prioritize differently, so no career answer fits everyone."}],"question":{"id":"m06-R2","prompt":{"zh":"建议能替所有人选同一职业吗？","en":"Can this advice choose the same career for everyone?"},"options":[{"id":"m06-R2-5c900122b2","text":{"zh":"不能，价值取舍不同","en":"No, priorities differ"},"feedback":{"zh":"每个人重视的事情不同，相同职业也可能适合一人、不适合另一人。","en":"Priorities differ; the same career may suit one person and not another."}},{"id":"m06-R2-6d92b04cf9","text":{"zh":"能，牌给统一职业","en":"Yes, the card names one career"},"feedback":{"zh":"牌没有给所有人指定同一种职业；本课要求结合个人重视的事情作选择。","en":"The card assigns no universal career; the lesson relates choices to personal priorities."}}],"correct":"m06-R2-5c900122b2"}},"R3":{"teach":[{"zh":"差异需要被讨论；牌面不替双方决定关系去留。","en":"Differences need discussion; the card does not decide whether people stay."}],"question":{"id":"m06-R3","prompt":{"zh":"不一致是否等于关系已结束？","en":"Does disagreement mean the relationship has ended?"},"options":[{"id":"m06-R3-4bc69a0562","text":{"zh":"等于","en":"Yes"},"feedback":{"zh":"差异和回避说明有待处理的问题，不是已经作出了分开的决定。","en":"Disagreement and avoidance identify an unresolved problem, not an established decision to separate."}},{"id":"m06-R3-9678e3a7cb","text":{"zh":"不等于","en":"No"},"feedback":{"zh":"例子只说明安排不同且没有讨论，之后如何选择仍需双方决定。","en":"Only different preferences and avoidance are stated; the later choice remains with the people involved."}}],"correct":"m06-R3-9678e3a7cb"}}},"revisit":{"id":"m06-V1","prompt":{"zh":"收到的合作邀请与个人原则冲突，怎样运用恋人的含义？","en":"How can the Lovers apply when an invitation conflicts with personal principles?"},"options":[{"id":"m06-V1-a4285ebc08","text":{"zh":"明确原则再作选择","en":"Clarify principles before choosing"},"feedback":{"zh":"先明确自己不能放弃的原则，再决定是否合作，就是在按自己重视的事情作选择。","en":"Clarifying principles before accepting the invitation expresses values-based choice."}},{"id":"m06-V1-2896f3397b","text":{"zh":"只因被邀请就答应","en":"Accept merely because invited"},"feedback":{"zh":"被邀请不代表合作符合自己的原则，直接答应没有处理已知冲突。","en":"An invitation does not ensure compatibility with your principles; immediate acceptance leaves the conflict unresolved."}}],"correct":"m06-V1-a4285ebc08"},"summary":{"zh":"恋人代表吸引、关系，以及按照自己真正重视的事情作选择。涉及两个人时，还要看双方是否认同。它不只指恋爱，也不保证关系结果。","en":"The Lovers represents attraction, relationships and choices reflecting what matters most. When two people are involved, mutual agreement also matters. Romance is not its only meaning or a guaranteed outcome."},"cards":["m06"]},{"id":"m07","kind":"card","level":"I","title":{"zh":"战车","en":"The Chariot"},"teachings":[{"zh":"战车代表朝着明确目标努力向前，也包括把不同方向的行动协调好。进展不只靠速度，还要让大家的行动朝着同一个目标。","en":"The Chariot represents determined progress toward a clear goal, including coordinating different efforts. Speed alone is not enough; action needs a shared direction."},{"zh":"驾车者、车体与一黑一白的狮身像帮助记住驾驭不同力量，不表示现实必须有敌人。","en":"The driver, vehicle and contrasting sphinxes support coordination of different forces, not a necessary enemy."},{"zh":"关键词：方向、自律、推进。VII不是保证胜利的数字。","en":"Recall labels: direction, discipline, progress. VII does not guarantee victory."}],"application":{"zh":"项目建议：多项任务都要占用同一段时间，先确定本周要完成的目标，再安排各项任务的时间。","en":"Project advice: when tasks compete for the same time, decide what must be achieved this week and schedule the tasks around it."},"reversal":{"zh":"逆位示例：团队各自追不同目标，忙却没有共同进展。先明确大家要一起完成什么，而不只是催每个人做得更快。","en":"Reversed example: team members pursue different goals and stay busy without shared progress. Agree what to achieve together instead of only demanding more speed."},"visual":{"zh":"驾车者、车体与一黑一白的狮身像帮助记住驾驭不同力量，不表示现实必须有敌人。","en":"The driver, vehicle and contrasting sphinxes support coordination of different forces, not a necessary enemy."},"questions":{"Q1":{"id":"m07-Q1","prompt":{"zh":"本课讲的战车，除了行动速度，还需要什么才能推进？","en":"Besides speed, what does the Chariot need for progress in this lesson?"},"options":[{"id":"m07-Q1-31cbf1379b","text":{"zh":"单纯加快动作","en":"Simply move faster"},"feedback":{"zh":"如果不知道要完成什么，只加快动作仍可能各做各的。","en":"Without a shared goal, moving faster may still send efforts in separate directions."}},{"id":"m07-Q1-3d4bed7e6d","text":{"zh":"确定目标，让行动朝同一方向推进","en":"Set a goal and coordinate action toward it"},"feedback":{"zh":"明确要完成什么，再让各项行动围绕目标安排，才有共同方向。","en":"A clear goal and coordinated actions give effort a shared direction."}}],"correct":"m07-Q1-3d4bed7e6d","support":"R1"},"Q2":{"id":"m07-Q2","prompt":{"zh":"多项任务要占用同一段时间，怎样运用战车的含义？","en":"How can the Chariot apply when several tasks compete for the same time?"},"options":[{"id":"m07-Q2-40bc77f56c","text":{"zh":"定目标并协调排期","en":"Set a goal and coordinate schedules"},"feedback":{"zh":"先定目标再排时间，能决定先做什么，避免任务挤在一起。","en":"A goal and schedule establish priorities instead of crowding tasks together."}},{"id":"m07-Q2-e52ad0b087","text":{"zh":"所有任务同时加码","en":"Intensify every task at once"},"feedback":{"zh":"各项任务同时加量，仍在争用同一段时间，没有解决安排上的冲突。","en":"Intensifying every task leaves them competing for the same time and does not resolve scheduling conflicts."}}],"correct":"m07-Q2-40bc77f56c","support":"R2"},"Q3":{"id":"m07-Q3","prompt":{"zh":"这个逆位案例中，团队先做什么？","en":"In this reversed-card example, what should the team do first?"},"options":[{"id":"m07-Q3-86a1788591","text":{"zh":"加快不同方向行动","en":"Accelerate conflicting actions"},"feedback":{"zh":"目标本来就不同，加快各自动作仍不会让团队朝同一目标前进。","en":"Accelerating conflicting efforts does not give the team a shared goal."}},{"id":"m07-Q3-1e7805fe84","text":{"zh":"统一目标","en":"Align goals"},"feedback":{"zh":"先说清共同目标，再协调每个人的工作，才能改变各自为政的情况。","en":"Clarifying a shared goal before coordinating work addresses the conflicting directions."}}],"correct":"m07-Q3-1e7805fe84","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"战车讲的前进，是朝着明确目标推进。有很多动作、很忙碌，不代表正在接近目标。","en":"The Chariot’s progress moves toward a clear goal. Being busy and active does not necessarily mean approaching it."}],"question":{"id":"m07-R1","prompt":{"zh":"忙碌一定等于前进吗？","en":"Does being busy necessarily mean progress?"},"options":[{"id":"m07-R1-be483a09ab","text":{"zh":"不一定，要看方向","en":"No, direction matters"},"feedback":{"zh":"要看忙的事情有没有帮助接近目标，不能只按动作多少判断进展。","en":"Progress depends on whether activity approaches the goal, not on the amount of activity."}},{"id":"m07-R1-73b9f3a075","text":{"zh":"一定，动作多就行","en":"Yes, activity is enough"},"feedback":{"zh":"做了很多事，也可能没有做当前目标需要的事。","en":"Many actions can still omit the work the present goal requires."}}],"correct":"m07-R1-be483a09ab"}},"R2":{"teach":[{"zh":"排期要先看当前目标最需要完成什么，再安排各项任务；不是把所有事都挤在同一时间做。","en":"Scheduling begins with what the current goal needs, then arranges tasks accordingly rather than squeezing everything into the same time."}],"question":{"id":"m07-R2","prompt":{"zh":"合理安排任务，就是同时做尽可能多的事吗？","en":"Does arranging work well mean doing as many tasks as possible at once?"},"options":[{"id":"m07-R2-e82ea7de81","text":{"zh":"是，越多越有掌控","en":"Yes, more means more control"},"feedback":{"zh":"同时做得多，仍可能任务冲突；数量不能证明安排得好。","en":"More simultaneous tasks may still conflict; quantity does not establish good coordination."}},{"id":"m07-R2-2d155fa729","text":{"zh":"不是，要围绕目标安排","en":"No, arrange work around the goal"},"feedback":{"zh":"围绕目标安排先后，才是在协调时间与精力。","en":"Ordering work around the goal coordinates time and effort."}}],"correct":"m07-R2-2d155fa729"}},"R3":{"teach":[{"zh":"如果大家朝不同目标行动，做得越快也可能离共同目标越远。先确认要一起完成什么，再继续推进。","en":"When people pursue different goals, speed may increase divergence. Agree what to achieve together before moving on."}],"question":{"id":"m07-R3","prompt":{"zh":"目标相反时加速能解决吗？","en":"Can speed fix opposing goals?"},"options":[{"id":"m07-R3-43fd3a88f5","text":{"zh":"不能，先统一目标","en":"No, align the goals first"},"feedback":{"zh":"真正的问题是目标不一致，先统一目标才知道接下来怎样配合。","en":"The actual problem is conflicting goals; alignment comes before coordinated action."}},{"id":"m07-R3-3c68254525","text":{"zh":"能，速度会统一目标","en":"Yes, speed aligns goals"},"feedback":{"zh":"速度改变的是做得多快，并不会自动改变大家想完成什么。","en":"Speed changes how fast people act, not what each intends to achieve."}}],"correct":"m07-R3-43fd3a88f5"}}},"revisit":{"id":"m07-V1","prompt":{"zh":"为了参加比赛而训练，哪种做法体现战车的含义？","en":"Which approach to competition training fits the Chariot?"},"options":[{"id":"m07-V1-1a485fb9aa","text":{"zh":"每天随机换目标","en":"Change goals randomly each day"},"feedback":{"zh":"每天随意换目标，会让训练缺少持续方向，难以围绕比赛准备。","en":"Randomly changing goals removes consistent direction from preparation."}},{"id":"m07-V1-8b572875ab","text":{"zh":"围绕目标安排训练","en":"Organize training around a goal"},"feedback":{"zh":"围绕比赛目标安排训练，让持续行动服务于明确方向。","en":"Training organized around the competition goal gives sustained action a clear direction."}}],"correct":"m07-V1-8b572875ab"},"summary":{"zh":"战车代表朝着明确目标努力向前，也包括把不同方向的行动协调好。进展不只靠速度，还要让大家的行动朝着同一个目标。","en":"The Chariot represents determined progress toward a clear goal, including coordinating different efforts. Speed alone is not enough; action needs a shared direction."},"cards":["m07"]},{"id":"m08","kind":"card","level":"I","title":{"zh":"力量","en":"Strength"},"teachings":[{"zh":"力量表达面对困难的勇气和耐心。即使很生气、很想立刻反击，也能先稳住自己，再选择怎样回应。温和不等于退让，坚定也不必靠压过别人。","en":"Strength expresses courage and patience in difficulty. Even when angry and ready to retaliate, you can steady yourself before responding. Gentleness need not surrender, and firmness need not overpower."},{"zh":"人物靠近狮子，双手放在狮子嘴边，可以帮助记住温和地应对强烈的力量，不据此鼓励接近真实猛兽。","en":"The figure’s hands near the lion support approaching and regulating force, not approaching real wild animals."},{"zh":"关键词：勇气、耐心、温和而坚定。这套RWS牌中，力量的编号是VIII。","en":"Remember: courage, patience, gentle firmness. Strength is numbered VIII in this RWS deck."}],"application":{"zh":"沟通建议：意见被否定时先稳住情绪，再清楚表达理由。不是忍到不说，也不是吼赢对方。","en":"Communication advice: steady yourself after criticism and explain your reasons, rather than silence yourself or shout someone down."},"reversal":{"zh":"逆位示例：压力大时一受刺激就爆发。这里需要留意自己为什么难以稳住情绪，先休息或求助；不能据此给人贴上“永远软弱”的标签。","en":"Reversed example: stress brings quick outbursts. Notice the difficulty steadying emotions and seek rest or support; this does not establish permanent weakness."},"visual":{"zh":"人物靠近狮子，双手放在狮子嘴边，可以帮助记住温和地应对强烈的力量，不据此鼓励接近真实猛兽。","en":"The figure’s hands near the lion support approaching and regulating force, not approaching real wild animals."},"questions":{"Q1":{"id":"m08-Q1","prompt":{"zh":"按照本课讲的力量，很想冲动反击时可以怎样回应？","en":"How does Strength, as taught here, respond to an impulse to retaliate?"},"options":[{"id":"m08-Q1-6ee44da268","text":{"zh":"先稳住情绪，再选择怎样回应","en":"Steady yourself before choosing how to respond"},"feedback":{"zh":"先稳住自己，仍然可以回应问题，只是不让一时冲动决定怎么做。","en":"Steadying yourself still allows a response without letting impulse decide it."}},{"id":"m08-Q1-8055ab6906","text":{"zh":"一律靠压制取胜","en":"Always win through suppression"},"feedback":{"zh":"压过别人只是在争输赢，没有体现本课的温和与耐心。","en":"Overpowering others pursues victory without the taught gentleness and patience."}}],"correct":"m08-Q1-6ee44da268","support":"R1"},"Q2":{"id":"m08-Q2","prompt":{"zh":"意见被否定后，哪种回应符合刚才的沟通示范？","en":"Which response fits the example of having your opinion rejected?"},"options":[{"id":"m08-Q2-1f8fe4e511","text":{"zh":"永远不再表达","en":"Never express yourself again"},"feedback":{"zh":"冷静下来不等于永远闭口；本课仍要求清楚表达自己的理由。","en":"Calming down does not mean permanent silence; the lesson retains clear expression."}},{"id":"m08-Q2-f310b1d333","text":{"zh":"稳住后说明理由","en":"Steady yourself and give reasons"},"feedback":{"zh":"先稳住情绪，再讲理由，既没有冲动反击，也没有放弃表达。","en":"Steadying yourself before giving reasons avoids both retaliation and abandoning expression."}}],"correct":"m08-Q2-f310b1d333","support":"R2"},"Q3":{"id":"m08-Q3","prompt":{"zh":"在压力很大、一受刺激就爆发的逆位例子里，应关注什么？","en":"What matters in the reversal example of outbursts under stress?"},"options":[{"id":"m08-Q3-4e0c6a76fd","text":{"zh":"恢复稳住情绪的能力","en":"Restore the ability to steady emotions"},"feedback":{"zh":"例子说明目前压力大、容易爆发，应帮助自己休息和恢复，而不是贴标签。","en":"The example concerns stress and outbursts, calling for recovery rather than a label."}},{"id":"m08-Q3-e1c03cc00d","text":{"zh":"证明此人永久软弱","en":"Prove permanent weakness"},"feedback":{"zh":"一次或一段时间的困难，不能证明这个人以后的性格永远如此。","en":"A current difficulty does not establish someone’s permanent character."}}],"correct":"m08-Q3-4e0c6a76fd","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"可以平静地说话，也可以清楚说明自己不能接受什么。语气温和，不等于必须答应对方。","en":"You can speak calmly while clearly stating what you cannot accept. A gentle tone does not require agreement."}],"question":{"id":"m08-R1","prompt":{"zh":"平静地表达，还能清楚说明自己不能接受什么吗？","en":"Can you speak calmly while clearly stating what you cannot accept?"},"options":[{"id":"m08-R1-aaf6f7c76d","text":{"zh":"不可以","en":"No"},"feedback":{"zh":"语气平静不等于答应一切，不能接受的要求仍然可以说清楚。","en":"A calm tone does not require agreement; unacceptable requests can still be refused clearly."}},{"id":"m08-R1-0ef5c86fab","text":{"zh":"可以","en":"Yes"},"feedback":{"zh":"怎样说话和是否坚持自己的立场，是两回事，可以同时做到。","en":"A gentle manner and a firm position can coexist."}}],"correct":"m08-R1-0ef5c86fab"}},"R2":{"teach":[{"zh":"先冷静下来，是为了把想说的话说清楚，不是要求以后都不再表达。","en":"Calming down helps you express yourself clearly; it does not require permanent silence."}],"question":{"id":"m08-R2","prompt":{"zh":"先冷静是否代表不再说？","en":"Does calming down mean never speaking?"},"options":[{"id":"m08-R2-b8fa898323","text":{"zh":"不代表","en":"No"},"feedback":{"zh":"冷静之后仍可继续表达，只是更容易把理由讲清楚。","en":"You can still speak after calming down and may explain your reasons more clearly."}},{"id":"m08-R2-9db6b1dec8","text":{"zh":"代表","en":"Yes"},"feedback":{"zh":"示范说的是先稳住再表达，没有要求取消后面的表达。","en":"The example says to steady yourself and then speak, not to remove expression."}}],"correct":"m08-R2-b8fa898323"}},"R3":{"teach":[{"zh":"最近很难稳住情绪，可以先休息或寻求帮助。这是目前遇到的困难，不能据此认定一个人永远软弱。","en":"Recent difficulty managing emotions can call for rest or help. It describes a present difficulty, not permanent weakness."}],"question":{"id":"m08-R3","prompt":{"zh":"最近难以稳住情绪，能说明这个人永远软弱吗？","en":"Does recent difficulty managing emotions establish permanent weakness?"},"options":[{"id":"m08-R3-413c06bcef","text":{"zh":"能","en":"Yes"},"feedback":{"zh":"例子只说明最近压力下的表现，不能推出永远不会改变。","en":"The example describes a current response to stress, not an unchangeable trait."}},{"id":"m08-R3-6c47574119","text":{"zh":"不能","en":"No"},"feedback":{"zh":"休息和帮助仍可能有用，不能用当前困难给一个人下终身定论。","en":"Rest and support may help; present difficulty is not a lifelong verdict."}}],"correct":"m08-R3-6c47574119"}}},"revisit":{"id":"m08-V1","prompt":{"zh":"学新技能时遇到挫折，怎样运用力量的含义？","en":"How can Strength apply to frustration while learning a skill?"},"options":[{"id":"m08-V1-a04c7708c7","text":{"zh":"耐心处理挫败再尝试","en":"Handle frustration patiently and retry"},"feedback":{"zh":"耐心处理挫败后再试，既面对困难，也照顾了自己的情绪。","en":"Patiently handling frustration and retrying combines courage with emotional care."}},{"id":"m08-V1-ae8dc31ed1","text":{"zh":"用羞辱逼自己继续","en":"Shame yourself into continuing"},"feedback":{"zh":"羞辱只增加压力，没有教会自己怎样耐心面对困难。","en":"Shame adds pressure without teaching a patient response to difficulty."}}],"correct":"m08-V1-a04c7708c7"},"summary":{"zh":"力量表达面对困难的勇气和耐心。即使很生气、很想立刻反击，也能先稳住自己，再选择怎样回应。温和不等于退让，坚定也不必靠压过别人。","en":"Strength expresses courage and patience in difficulty. Even when angry and ready to retaliate, you can steady yourself before responding. Gentleness need not surrender, and firmness need not overpower."},"cards":["m08"]},{"id":"m09","kind":"card","level":"I","title":{"zh":"隐士","en":"The Hermit"},"teachings":[{"zh":"隐士强调主动独处、反思与寻找自己的方向。暂时离开喧闹，是为了看清问题，不是把孤立和拒绝帮助当作理想。","en":"The Hermit emphasizes deliberate solitude, reflection and finding direction. Stepping away from noise serves understanding, not isolation or rejection of help."},{"zh":"灯笼、手杖与独自站立的人物帮助记住照亮眼前的一段路，不保证立刻知道全部未来。","en":"The lantern, staff and solitary figure suggest illuminating the next part of a path, not knowing the entire future."},{"zh":"关键词：独处、反思、寻找方向。IX不能代替具体牌义。","en":"Recall labels: solitude, reflection, seeking direction. IX does not replace the meaning."}],"application":{"zh":"学习建议：被各种课程推荐弄乱时，先安静检查自己真正缺什么，再选择资源。","en":"Study advice: when course recommendations overwhelm you, review your actual needs before choosing resources."},"reversal":{"zh":"逆位示例：长时间拒绝交流，连需要的信息也得不到。这里的问题是把自己孤立起来，而不是安静思考本身有错。","en":"Reversed example: prolonged refusal to communicate blocks needed information. The issue is isolation, not quiet reflection itself."},"visual":{"zh":"灯笼、手杖与独自站立的人物帮助记住照亮眼前的一段路，不保证立刻知道全部未来。","en":"The lantern, staff and solitary figure suggest illuminating the next part of a path, not knowing the entire future."},"questions":{"Q1":{"id":"m09-Q1","prompt":{"zh":"本课里，隐士暂时独处是为了什么？","en":"What is the purpose of the Hermit’s temporary solitude here?"},"options":[{"id":"m09-Q1-85da3ca3d5","text":{"zh":"永久拒绝外界","en":"Reject the outside forever"},"feedback":{"zh":"暂时独处是为了想清楚问题，不是要求以后都拒绝外界。","en":"Solitude serves understanding, not permanent rejection of the outside world."}},{"id":"m09-Q1-d8907405b9","text":{"zh":"反思并找方向","en":"Reflect and find direction"},"feedback":{"zh":"留出安静思考的时间，帮助自己看清需要什么、往哪里走。","en":"Quiet reflection helps clarify needs and direction."}}],"correct":"m09-Q1-d8907405b9","support":"R1"},"Q2":{"id":"m09-Q2","prompt":{"zh":"课程推荐太多先做什么？","en":"What first when course options overwhelm?"},"options":[{"id":"m09-Q2-043d6cd422","text":{"zh":"检查自己的学习需要","en":"Examine your learning needs"},"feedback":{"zh":"先知道自己真正需要学什么，才更容易判断哪些课程适合。","en":"Knowing your learning needs helps identify suitable courses."}},{"id":"m09-Q2-d9d81ce11c","text":{"zh":"继续跟随所有推荐","en":"Follow every recommendation"},"feedback":{"zh":"所有推荐都跟随，仍然没有回答自己究竟需要什么。","en":"Following every recommendation still leaves your own needs unclear."}}],"correct":"m09-Q2-043d6cd422","support":"R2"},"Q3":{"id":"m09-Q3","prompt":{"zh":"在拒绝交流、连必要信息也得不到的逆位例子里，需要调整什么？","en":"What needs changing when refusing contact blocks necessary information?"},"options":[{"id":"m09-Q3-ad9aa3947f","text":{"zh":"继续拒绝所有帮助","en":"Keep refusing all help"},"feedback":{"zh":"已经因拒绝交流而缺少信息，继续拒绝只会保留这个问题。","en":"Continued refusal preserves the lack of information described in the example."}},{"id":"m09-Q3-0c85d261b5","text":{"zh":"恢复必要交流","en":"Restore necessary communication"},"feedback":{"zh":"恢复必要联系，才能获得需要的信息；之后仍可以独立判断。","en":"Necessary contact restores access to information while leaving judgment independent."}}],"correct":"m09-Q3-0c85d261b5","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"一个人安静下来，是为了想清楚遇到的问题。周围没人说话，并不等于已经想清楚了。","en":"Quiet time alone can help examine a problem. Silence does not mean the problem is already understood."}],"question":{"id":"m09-R1","prompt":{"zh":"没人说话就等于有效反思吗？","en":"Does silence alone equal reflection?"},"options":[{"id":"m09-R1-07618ea291","text":{"zh":"不等于，还要理解问题","en":"No, examine the issue"},"feedback":{"zh":"安静只是提供思考的时间，还需要实际去理解遇到的问题。","en":"Quiet provides time for reflection; the problem still needs examination."}},{"id":"m09-R1-aeb4ae6de1","text":{"zh":"等于，安静就是答案","en":"Yes, silence is the answer"},"feedback":{"zh":"没有人说话，并不能自动带来对问题的理解。","en":"Silence does not automatically produce understanding."}}],"correct":"m09-R1-07618ea291"}},"R2":{"teach":[{"zh":"先想清楚自己哪里不懂，再带着具体问题请教别人，会更容易找到需要的信息。","en":"Clarifying what you do not understand before asking a specific question helps locate the information you need."}],"question":{"id":"m09-R2","prompt":{"zh":"想清问题后还能请教吗？","en":"Can you seek advice after reflecting?"},"options":[{"id":"m09-R2-6a6eb86228","text":{"zh":"不可，隐士只能独自解决","en":"No, solve everything alone"},"feedback":{"zh":"主动独处不要求所有事都独自解决，想清楚问题后仍能请教。","en":"Solitude does not require solving everything alone; consultation remains possible."}},{"id":"m09-R2-3bd21cdbf5","text":{"zh":"可以，带着明确问题","en":"Yes, with a clear question"},"feedback":{"zh":"带着明确问题请教，是在为自己的判断寻找需要的信息。","en":"A clear question seeks information to inform your own judgment."}}],"correct":"m09-R2-3bd21cdbf5"}},"R3":{"teach":[{"zh":"如果一直不与人交流，连需要的信息和帮助也得不到，可以恢复一些联系。听到别人的信息后，仍能自己判断是否采用。","en":"When isolation blocks needed information or support, some contact can help. You can still decide independently whether to use what others provide."}],"question":{"id":"m09-R3","prompt":{"zh":"恢复交流会取消独立判断吗？","en":"Does reconnecting erase independent judgment?"},"options":[{"id":"m09-R3-c7ae73a94d","text":{"zh":"不会","en":"No"},"feedback":{"zh":"别人可以提供信息，是否采用仍由自己思考决定。","en":"Others can supply information while you decide whether to use it."}},{"id":"m09-R3-5ba1e3c0eb","text":{"zh":"会","en":"Yes"},"feedback":{"zh":"交流不等于把决定全部交给别人，仍可保留自己的判断。","en":"Communication does not hand every decision to others."}}],"correct":"m09-R3-c7ae73a94d"}}},"revisit":{"id":"m09-V1","prompt":{"zh":"收到许多互相冲突的创作建议时，怎样运用隐士的含义？","en":"How can the Hermit apply to conflicting feedback about your creative work?"},"options":[{"id":"m09-V1-575b21df95","text":{"zh":"立刻迎合每个意见","en":"Immediately please every reviewer"},"feedback":{"zh":"意见彼此冲突时，一一迎合仍然没有形成自己的创作方向。","en":"Pleasing conflicting reviewers does not establish your creative direction."}},{"id":"m09-V1-76cd7097c7","text":{"zh":"留时间澄清自己的方向","en":"Take time to clarify your direction"},"feedback":{"zh":"先想清楚自己想表达什么，再决定采用哪些意见，符合本课的反思。","en":"Clarifying your intent before choosing feedback applies the reflection taught here."}}],"correct":"m09-V1-76cd7097c7"},"summary":{"zh":"隐士强调主动独处、反思与寻找自己的方向。暂时离开喧闹，是为了看清问题，不是把孤立和拒绝帮助当作理想。","en":"The Hermit emphasizes deliberate solitude, reflection and finding direction. Stepping away from noise serves understanding, not isolation or rejection of help."},"cards":["m09"]},{"id":"m10","kind":"card","level":"I","title":{"zh":"命运之轮","en":"Wheel of Fortune"},"teachings":[{"zh":"命运之轮关注周期、转折和不完全受个人控制的变化。它提醒观察时机并调整，不承诺变化必定带来好运。","en":"The Wheel of Fortune concerns cycles, turning points and change beyond personal control. Notice timing and adapt; change does not guarantee good luck."},{"zh":"轮子居中，周围有不同形象。轮形帮助记住循环与转动；具体事情何时发生不能从轮子直接确定。","en":"A wheel occupies the centre, surrounded by figures. Its form helps recall cycles and turning, but does not specify when an event will occur."},{"zh":"关键词：周期、转折、时机、变化。编号X是大牌序号，不等于所有数字十的牌义。","en":"Recall labels: cycles, turning points, timing, change. X is this major card’s number, not the meaning of every Ten."}],"application":{"zh":"建议位：展会日期被主办方调整，你可以重新安排准备和交通。先区分外部变化与自己可调整的部分，而不是责备自己控制不了全部。","en":"Advice: an organiser changes an exhibition date. Revise preparation and travel, distinguishing external change from what you can adjust."},"reversal":{"zh":"逆位示例：安排已经变化，仍坚持旧时间表，结果接连遇到阻碍。需要重新看看现在怎样安排才合适，不代表这个人会永远倒霉。","en":"Reversed example: circumstances have changed, but an old schedule produces repeated obstacles. Reconsider a suitable present plan rather than declaring permanent bad luck."},"visual":{"zh":"轮子居中，周围有不同形象。轮形帮助记住循环与转动；具体事情何时发生不能从轮子直接确定。","en":"A wheel occupies the centre, surrounded by figures. Its form helps recall cycles and turning, but does not specify when an event will occur."},"questions":{"Q1":{"id":"m10-Q1","prompt":{"zh":"本课讲的命运之轮，主要表达什么？","en":"What does the Wheel of Fortune mainly express here?"},"options":[{"id":"m10-Q1-858f72aa03","text":{"zh":"周期与局面变化","en":"Cycles and changing circumstances"},"feedback":{"zh":"轮子让我们记住周期和转折：事情会变化，不总由一个人决定。","en":"The wheel recalls cycles and turning points: circumstances change beyond one person’s control."}},{"id":"m10-Q1-37f969779b","text":{"zh":"所有事情必定变好","en":"Everything must improve"},"feedback":{"zh":"变化可能带来机会，也可能带来困难，不能保证每件事都变好。","en":"Change can bring opportunities or difficulties; improvement is not guaranteed."}}],"correct":"m10-Q1-858f72aa03","support":"R1"},"Q2":{"id":"m10-Q2","prompt":{"zh":"展会已经改期，哪种做法符合刚才的建议？","en":"Which action fits the advice after the exhibition date changes?"},"options":[{"id":"m10-Q2-ef4563838a","text":{"zh":"坚持原日期去参加","en":"Attend on the original date"},"feedback":{"zh":"活动已经改期，按旧日期到场没有回应现实中的改变。","en":"Attending on the old date ignores the actual change."}},{"id":"m10-Q2-cd508d55de","text":{"zh":"重排准备与交通","en":"Revise preparation and travel"},"feedback":{"zh":"日期不能由你决定，但准备顺序和出行安排可以随之调整。","en":"The date is outside your control, but preparation and travel can adapt."}}],"correct":"m10-Q2-cd508d55de","support":"R2"},"Q3":{"id":"m10-Q3","prompt":{"zh":"安排已经改变，却仍坚持旧时间表。这个逆位例子的问题在哪里？","en":"What is wrong in the reversal example of keeping an old schedule after plans change?"},"options":[{"id":"m10-Q3-769df1c16c","text":{"zh":"旧安排不适合新条件","en":"The old plan no longer fits"},"feedback":{"zh":"已知的是旧时间表不再合用，仍坚持它才造成反复受阻。","en":"The old schedule no longer fits; insisting on it causes the repeated obstacles."}},{"id":"m10-Q3-84a3b352d6","text":{"zh":"当事人永远没有机会","en":"The person will never have opportunities"},"feedback":{"zh":"一份安排目前不适用，不能推出这个人以后都没有机会。","en":"One unsuitable plan does not mean a person will never have opportunities."}}],"correct":"m10-Q3-769df1c16c","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"轮子帮助我们记住事情会变化。变化可能带来机会，也可能带来新的困难；变化本身并不保证好运。","en":"The wheel recalls changing circumstances. Change can bring opportunities or new difficulties; it does not itself guarantee good fortune."}],"question":{"id":"m10-R1","prompt":{"zh":"变化与好运是同一件事吗？","en":"Are change and good luck identical?"},"options":[{"id":"m10-R1-90d812c012","text":{"zh":"是，转动就必定获利","en":"Yes; turning guarantees gain"},"feedback":{"zh":"轮子代表变化，不是保证获利；结果还要结合具体情况看。","en":"The wheel represents change, not guaranteed gain; circumstances still matter."}},{"id":"m10-R1-e7369bebb4","text":{"zh":"不是，需要看具体条件","en":"No; context matters"},"feedback":{"zh":"变化会有不同影响，需要看改变了什么、目前能怎样回应。","en":"Change has different effects; examine what changed and how to respond."}}],"correct":"m10-R1-e7369bebb4"}},"R2":{"teach":[{"zh":"展会改期由主办方决定，但怎样安排准备和交通，是你可以调整的。先把这两件事分开，才知道自己接下来能做什么。","en":"The organizer changes the date, while you can adjust preparation and travel. Separating these identifies your available next actions."}],"question":{"id":"m10-R2","prompt":{"zh":"活动地点已经改变，按照刚才的讲解，先检查什么？","en":"The event location has changed. What should you check first?"},"options":[{"id":"m10-R2-b36bd8d1b1","text":{"zh":"路线与原计划是否仍适用","en":"Whether the route and plan still fit"},"feedback":{"zh":"地点变了，原路线和时间安排可能不合用，先检查它们才好继续准备。","en":"A new location may invalidate the route and timing, so check them before proceeding."}},{"id":"m10-R2-4d747cf36d","text":{"zh":"如何让过去的安排从未发生","en":"How to undo the past"},"feedback":{"zh":"已经发生的改动不能靠愿望取消；本课讲的是调整接下来的安排。","en":"Wishing cannot undo a past change; the lesson concerns adapting future plans."}}],"correct":"m10-R2-b36bd8d1b1"}},"R3":{"teach":[{"zh":"事情接连不顺，不必认定是自己被诅咒。先看看实际情况是否已经变化，而自己还在按旧安排做。","en":"Repeated setbacks need not mean a curse. Check whether circumstances have changed while you are still following an old plan."}],"question":{"id":"m10-R3","prompt":{"zh":"情况已经变化，按旧安排做又接连受阻，可以先怎样调整？","en":"Circumstances have changed and the old plan keeps failing. What can change first?"},"options":[{"id":"m10-R3-25b6f28320","text":{"zh":"放弃所有今后的安排","en":"Abandon every future plan"},"feedback":{"zh":"问题是一份安排不合用，不是所有将来的安排都不值得做。","en":"The issue is one unsuitable plan, not that all future planning is worthless."}},{"id":"m10-R3-90ace7fc5a","text":{"zh":"更新不合适的安排","en":"Update the unsuitable plan"},"feedback":{"zh":"把旧安排改成适合现在情况的安排，才回应了已知阻碍。","en":"Updating the plan to fit present circumstances addresses the identified obstacle."}}],"correct":"m10-R3-90ace7fc5a"}}},"revisit":{"id":"m10-V1","prompt":{"zh":"图书馆临时闭馆，怎样运用命运之轮的含义继续安排学习？","en":"How can the Wheel of Fortune inform study plans when the library closes temporarily?"},"options":[{"id":"m10-V1-291303faa1","text":{"zh":"根据新条件寻找替代学习地点","en":"Find another place under the new conditions"},"feedback":{"zh":"闭馆是外部变化，换个学习地点是自己能够作出的调整。","en":"The closure is external; finding another study place is an available adjustment."}},{"id":"m10-V1-d41f9055c6","text":{"zh":"认定学习永远无法继续","en":"Decide learning is impossible forever"},"feedback":{"zh":"临时闭馆只改变了这个地点的使用，不能证明学习永远无法继续。","en":"A temporary closure affects that location, not the possibility of all future study."}}],"correct":"m10-V1-291303faa1"},"summary":{"zh":"命运之轮关注周期、转折和不完全受个人控制的变化。它提醒观察时机并调整，不承诺变化必定带来好运。","en":"The Wheel of Fortune concerns cycles, turning points and change beyond personal control. Notice timing and adapt; change does not guarantee good luck."},"cards":["m10"]},{"id":"m11","kind":"card","level":"I","title":{"zh":"正义","en":"Justice"},"teachings":[{"zh":"正义关注事实、公平、责任与选择的后果。它要求核对依据和规则，再作判断；不是保证自己一定被判为正确。","en":"Justice concerns facts, fairness, responsibility and consequences. Examine evidence and rules before judging; it does not guarantee that your side is right."},{"zh":"人物持天平和直立宝剑。天平帮助记住衡量，宝剑帮助记住清楚判断；画面不提供某个现实争议的全部证据。","en":"The figure holds scales and an upright sword. They help recall weighing evidence and clear judgment, not the facts of a real dispute."},{"zh":"关键词：公平、事实、责任、后果。编号XI只作识牌信息，本课不加入额外数字公式。","en":"Recall labels: fairness, facts, responsibility, consequences. XI identifies this card; no extra numerical formula is required."}],"application":{"zh":"建议位：两位同事对工作量有争议，先核对约定、实际任务和记录，再讨论责任。不是因为抽到正义就证明其中一人有错。","en":"Advice: colleagues dispute workload. Check agreements, tasks and records before discussing responsibility. The card does not prove either person guilty."},"reversal":{"zh":"逆位示例：评选对不同人使用不同标准。这里关注对不同人区别对待的不公平，建议查清情况，并按同一标准评选。","en":"Reversed example: different candidates are judged by inconsistent standards. This highlights bias and unfairness; clarify and apply the standards consistently."},"visual":{"zh":"人物持天平和直立宝剑。天平帮助记住衡量，宝剑帮助记住清楚判断；画面不提供某个现实争议的全部证据。","en":"The figure holds scales and an upright sword. They help recall weighing evidence and clear judgment, not the facts of a real dispute."},"questions":{"Q1":{"id":"m11-Q1","prompt":{"zh":"正义首先要求什么？","en":"What does Justice first require?"},"options":[{"id":"m11-Q1-d3d22ba221","text":{"zh":"保证自己赢","en":"Guarantee your victory"},"feedback":{"zh":"公平要看事实和规则，并不保证结果一定对自己有利。","en":"Fairness depends on facts and rules, not a guaranteed favorable result."}},{"id":"m11-Q1-a9ccc8fd21","text":{"zh":"核对事实和规则","en":"Examine facts and rules"},"feedback":{"zh":"先核对事实，再按规则判断，才能说明结论为什么公平。","en":"Facts checked against rules provide reasons for a fair judgment."}}],"correct":"m11-Q1-a9ccc8fd21","support":"R1"},"Q2":{"id":"m11-Q2","prompt":{"zh":"工作量争议先怎么做？","en":"What first in the workload dispute?"},"options":[{"id":"m11-Q2-f906f727ec","text":{"zh":"对照约定与任务记录","en":"Compare agreements and records"},"feedback":{"zh":"约定说明本来由谁做什么，任务记录说明实际做了什么，两者可以一起核对。","en":"Agreements show assigned work; task records show actual work, allowing comparison."}},{"id":"m11-Q2-7e66ec940d","text":{"zh":"宣布牌证明对方错误","en":"Say the card proves the other person wrong"},"feedback":{"zh":"抽到正义没有增加任务记录或证据，不能据此证明谁错了。","en":"Drawing Justice adds no task records or evidence and does not establish blame."}}],"correct":"m11-Q2-f906f727ec","support":"R2"},"Q3":{"id":"m11-Q3","prompt":{"zh":"评选对不同人用了不同标准。在这个逆位例子里，正义提醒检查什么？","en":"What does reversed Justice highlight when different standards are applied to different people?"},"options":[{"id":"m11-Q3-774e3e4072","text":{"zh":"只要我满意就公平","en":"It is fair if I am satisfied"},"feedback":{"zh":"自己满意只说明结果合心意，不能证明对所有人使用了同样标准。","en":"Personal satisfaction does not establish consistent standards for everyone."}},{"id":"m11-Q3-4de328902c","text":{"zh":"检查偏差并统一标准","en":"Check bias and apply consistent criteria"},"feedback":{"zh":"问题是标准使用不一致，查清并统一使用标准才回应了它。","en":"Inconsistent standards are the problem; checking and applying them consistently addresses it."}}],"correct":"m11-Q3-4de328902c","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"公平不等于我获胜。先核对事实，再看同样的情况是否用了同样的规则、每个人应承担什么责任。","en":"Fairness does not mean that I win. Check facts, consistent rules for comparable cases, and each person’s responsibility."}],"question":{"id":"m11-R1","prompt":{"zh":"怎样辨认公平的判断？","en":"What supports a fair judgment?"},"options":[{"id":"m11-R1-14a3c0ed37","text":{"zh":"对同类情况使用同一标准","en":"Use consistent criteria for comparable cases"},"feedback":{"zh":"同类情况用同一标准，才不会因为对象不同而随意改变判断。","en":"Consistent criteria for comparable cases prevent arbitrary changes based on the person."}},{"id":"m11-R1-2d12fb2004","text":{"zh":"先定赢家再找理由","en":"Choose a winner before reasons"},"feedback":{"zh":"先选赢家再补理由，是让证据迁就结论，没有先公平比较。","en":"Picking a winner first makes evidence serve a conclusion rather than a fair comparison."}}],"correct":"m11-R1-14a3c0ed37"}},"R2":{"teach":[{"zh":"先把“我觉得”与任务记录分开，再协商分工；不要拿牌替任何一方作证。","en":"Separate impressions from task records, then negotiate. A card cannot testify for either side."}],"question":{"id":"m11-R2","prompt":{"zh":"团队分工重新协商要带什么？","en":"What helps renegotiate teamwork?"},"options":[{"id":"m11-R2-776107a677","text":{"zh":"只有对人的好恶","en":"Only personal likes and dislikes"},"feedback":{"zh":"喜欢或不喜欢某个人，不能说明对方实际承担了多少任务。","en":"Personal preference does not show how much work someone actually did."}},{"id":"m11-R2-7ad8cfd9fc","text":{"zh":"实际任务与约定记录","en":"Records of tasks and agreements"},"feedback":{"zh":"记录可以共同核对，帮助大家按实际工作讨论分工。","en":"Shared records let people discuss responsibilities using actual work."}}],"correct":"m11-R2-7ad8cfd9fc"}},"R3":{"teach":[{"zh":"修正不公平，需要检查标准怎样使用，不是换一个自己喜欢的赢家。","en":"Correcting unfairness requires checking how standards are applied, not choosing a preferred winner."}],"question":{"id":"m11-R3","prompt":{"zh":"要改正刚才例子中不公平的评选，应该改什么？","en":"What should change to correct the unfair judging in the example?"},"options":[{"id":"m11-R3-3d2b72dd4b","text":{"zh":"标准的使用方式","en":"How criteria are applied"},"feedback":{"zh":"检查同类情况是否用了同一标准，才能修正例子里的区别对待。","en":"Checking consistent treatment addresses the unequal standards in the example."}},{"id":"m11-R3-9e1d8d7c78","text":{"zh":"只换成喜欢的获奖者","en":"Merely choose a preferred winner"},"feedback":{"zh":"换成喜欢的人获奖，没有改变评选偏向个人喜好的问题。","en":"Selecting a preferred winner preserves favoritism."}}],"correct":"m11-R3-3d2b72dd4b"}}},"revisit":{"id":"m11-V1","prompt":{"zh":"社团报销发生争议，怎样运用正义的含义？","en":"How can Justice apply to a dispute over club reimbursements?"},"options":[{"id":"m11-V1-a082740077","text":{"zh":"用抽牌决定谁撒谎","en":"Draw to decide who is lying"},"feedback":{"zh":"牌没有查验票据或对话，不能用来认定某个人撒谎。","en":"The card has not verified receipts or statements and cannot establish lying."}},{"id":"m11-V1-b6090b0932","text":{"zh":"核对票据与事先规则","en":"Check receipts and agreed rules"},"feedback":{"zh":"票据说明花了什么，事先规则说明哪些可报销，能据此核对争议。","en":"Receipts show spending and agreed rules show eligibility, providing grounds to examine the dispute."}}],"correct":"m11-V1-b6090b0932"},"summary":{"zh":"正义关注事实、公平、责任与选择的后果。它要求核对依据和规则，再作判断；不是保证自己一定被判为正确。","en":"Justice concerns facts, fairness, responsibility and consequences. Examine evidence and rules before judging; it does not guarantee that your side is right."},"cards":["m11"]},{"id":"m12","kind":"card","level":"I","title":{"zh":"倒吊人","en":"The Hanged Man"},"teachings":[{"zh":"倒吊人表达暂停、放下原来的做法，以及换个角度理解问题。一直沿用同一种办法想不通时，停下来重新看，可能发现以前没注意的地方；并不是只要等待就会有答案。","en":"The Hanged Man represents pausing, releasing an old approach and seeing differently. When one approach fails, reconsidering may reveal something overlooked; waiting alone does not guarantee answers."},{"zh":"人物倒悬，姿态相对平静，头部有光环。倒置帮助记住视角改变；不能由此要求人在现实中承受伤害。","en":"A figure hangs upside down with a relatively calm posture and halo. Inversion suggests a changed perspective; it is not an instruction to endure harm."},{"zh":"关键词：暂停、换角度、放手、等待。编号XII不在本课拆成数字运算。","en":"Recall labels: pause, perspective, letting go, waiting. XII is not reduced through arithmetic here."}],"application":{"zh":"建议位：设计一直改颜色却没解决用户看不清信息的问题。暂停修改，先按读者阅读的先后顺序，检查信息怎样摆放。","en":"Advice: repeated color changes have not made a design readable. Pause editing and examine information placement in the order readers encounter it."},"reversal":{"zh":"逆位示例：一直说等一等，却不收集信息也不尝试新角度。这里关注停滞和无效等待。","en":"Reversed example: repeatedly waiting without gathering information or considering another perspective. Here the issue is stagnation and unproductive delay."},"visual":{"zh":"人物倒悬，姿态相对平静，头部有光环。倒置帮助记住视角改变；不能由此要求人在现实中承受伤害。","en":"A figure hangs upside down with a relatively calm posture and halo. Inversion suggests a changed perspective; it is not an instruction to endure harm."},"questions":{"Q1":{"id":"m12-Q1","prompt":{"zh":"倒吊人的暂停为了什么？","en":"What is the pause for?"},"options":[{"id":"m12-Q1-990f58c871","text":{"zh":"先停下原来的做法，换个角度看问题","en":"Pause the old approach and view the problem differently"},"feedback":{"zh":"暂时不沿用原来的做法，才能尝试从读者等其他角度理解问题。","en":"Pausing the old approach allows another perspective, such as the reader’s."}},{"id":"m12-Q1-a050e41177","text":{"zh":"不做任何事就必有答案","en":"Doing nothing guarantees an answer"},"feedback":{"zh":"本课没有说时间会自动带来答案，还需要重新观察和理解。","en":"Time alone does not supply an answer; observation and reconsideration are still needed."}}],"correct":"m12-Q1-990f58c871","support":"R1"},"Q2":{"id":"m12-Q2","prompt":{"zh":"设计改了很多次颜色，读者还是看不清信息。按照刚才的示范，先做什么？","en":"Colors have changed repeatedly but readers still struggle. What comes first in the example?"},"options":[{"id":"m12-Q2-dfa0d28477","text":{"zh":"继续随机换颜色","en":"Keep changing colours randomly"},"feedback":{"zh":"前面已经试过反复改颜色却无效，再做同样的事没有换角度。","en":"Repeated color changes have failed; repeating them does not change perspective."}},{"id":"m12-Q2-d54c5d5be5","text":{"zh":"按读者阅读的先后顺序检查信息摆放","en":"Check information placement in the order readers encounter it"},"feedback":{"zh":"改从读者怎样看到信息来检查，才从“我怎么改”转向“读者怎么看”。","en":"Examining how readers encounter information changes the perspective from editing to reading."}}],"correct":"m12-Q2-d54c5d5be5","support":"R2"},"Q3":{"id":"m12-Q3","prompt":{"zh":"逆位示例为什么停滞？","en":"Why is the reversed example stagnant?"},"options":[{"id":"m12-Q3-13198e0ca2","text":{"zh":"等待没带来信息或新角度","en":"Waiting brings no information or perspective"},"feedback":{"zh":"例子明确说没有收集信息，也没有换角度，只等着并未帮助理解。","en":"The example supplies neither new information nor a new perspective, so waiting has not helped understanding."}},{"id":"m12-Q3-fa9104006b","text":{"zh":"所有暂停都错误","en":"Every pause is wrong"},"feedback":{"zh":"有目的的暂停可以帮助重新理解，问题不是所有暂停都错。","en":"A purposeful pause can aid understanding; not every pause is a problem."}}],"correct":"m12-Q3-13198e0ca2","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"停下来后，还要试着从别的角度看问题。只是不动手，却仍然按原来的想法理解，就还没有换角度。","en":"After pausing, try another perspective. Merely stopping while retaining the same understanding does not change perspective."}],"question":{"id":"m12-R1","prompt":{"zh":"什么使暂停有价值？","en":"What makes a pause useful?"},"options":[{"id":"m12-R1-83759aa14f","text":{"zh":"只计算等了多久","en":"Only counting elapsed time"},"feedback":{"zh":"等待多久不能说明是否想清楚了，需要看理解有没有变化。","en":"Elapsed time does not show whether understanding has changed."}},{"id":"m12-R1-c27cba242b","text":{"zh":"帮助重新理解问题","en":"It helps reconsider the problem"},"feedback":{"zh":"停下来重新检查原来的理解，才用到了暂停后换角度的含义。","en":"Reexamining the original understanding uses the pause to change perspective."}}],"correct":"m12-R1-c27cba242b"}},"R2":{"teach":[{"zh":"读者看不清信息时，可以按他们阅读的顺序，检查标题、正文等内容放在哪里；不必继续只改颜色。","en":"When information is unclear to readers, inspect the placement of headings and text in reading order instead of only changing colors."}],"question":{"id":"m12-R2","prompt":{"zh":"反复使用同一种修改方法仍然无效，下一步怎样做？","en":"What comes next when repeating the same change has not worked?"},"options":[{"id":"m12-R2-e697bc8aa4","text":{"zh":"检查原先对问题的理解","en":"Reconsider your definition of the problem"},"feedback":{"zh":"原办法无效时，先检查是不是把问题想错了，才可能找到另一种做法。","en":"When an approach fails, reconsidering the problem can reveal another approach."}},{"id":"m12-R2-dbf5c4df6f","text":{"zh":"把同样修改再做十遍","en":"Repeat it ten more times"},"feedback":{"zh":"重复十遍仍是同一种办法，没有回应前面已经发现的无效。","en":"Ten repetitions remain the same approach and do not address its failure."}}],"correct":"m12-R2-e697bc8aa4"}},"R3":{"teach":[{"zh":"等待有没有作用，要看它是否带来必要信息或理解；这里明确两者都没有。","en":"Ask whether waiting brings useful information or understanding; this example explicitly brings neither."}],"question":{"id":"m12-R3","prompt":{"zh":"一直等待，却没有获得新信息，可以怎样调整？","en":"How can waiting be adjusted when it brings no new information?"},"options":[{"id":"m12-R3-6801c26fe7","text":{"zh":"永远等到答案自己来","en":"Wait forever for an answer"},"feedback":{"zh":"例子已经说明一直等没有帮助，继续无限等待仍会停在原处。","en":"The example says waiting has not helped; indefinite waiting preserves the same state."}},{"id":"m12-R3-7ee003eec8","text":{"zh":"明确还缺什么信息并去核实","en":"Identify and check missing information"},"feedback":{"zh":"先知道自己还不清楚什么，再去核实，等待才不只是空耗时间。","en":"Identifying and checking what is unknown gives waiting a purpose beyond elapsed time."}}],"correct":"m12-R3-7ee003eec8"}}},"revisit":{"id":"m12-V1","prompt":{"zh":"反复逐字读，还是不理解一句话。怎样运用倒吊人的含义？","en":"How can the Hanged Man apply when repeated word-by-word reading brings no understanding?"},"options":[{"id":"m12-V1-363d311bfc","text":{"zh":"暂停逐字硬读，结合上下文重看","en":"Pause word-by-word struggle and reread in context"},"feedback":{"zh":"从单个字转向前后文，是改变理解的角度，并没有停止学习。","en":"Moving from individual words to context changes perspective without abandoning study."}},{"id":"m12-V1-cd0440501a","text":{"zh":"认定暂停等于放弃学习","en":"Treat any pause as abandoning study"},"feedback":{"zh":"暂停逐字硬读，是为了换一种理解方法，不等于放弃学习。","en":"Pausing word-by-word struggle allows a different approach rather than giving up."}}],"correct":"m12-V1-363d311bfc"},"summary":{"zh":"倒吊人表达暂停、放下原来的做法，以及换个角度理解问题。一直沿用同一种办法想不通时，停下来重新看，可能发现以前没注意的地方；并不是只要等待就会有答案。","en":"The Hanged Man represents pausing, releasing an old approach and seeing differently. When one approach fails, reconsidering may reveal something overlooked; waiting alone does not guarantee answers."},"cards":["m12"]},{"id":"m13","kind":"card","level":"I","title":{"zh":"死神","en":"Death"},"teachings":[{"zh":"死神常说一件事告一段落，需要结束已经不适用的做法，再开始下一阶段。它让我们面对该结束的事，不是在预告有人死亡。","en":"Death often describes something coming to an end: leave behind an approach that no longer fits and move into the next stage. It asks us to face an ending, not predict someone’s death."},{"zh":"骷髅骑士前行，画面中有不同人物，远处可见光。前行与变化的场面帮助记住结束和过渡，不是现实死亡证据。","en":"A skeletal rider advances among different figures, with light in the distance. The scene supports remembering endings and transition, not evidence of a real death."},{"zh":"关键词：结束、告别、转变、更新。变化之后不一定马上觉得轻松。可以先承认这件事已经结束，再慢慢适应。","en":"Recall labels: ending, farewell, transition, renewal. Change may not bring immediate relief. Acknowledge that something has ended and give yourself time to adjust."}],"application":{"zh":"建议位：一个已完成的社团活动还占着你的时间，文件和职责没有收尾。整理交接，结束旧任务，才能腾出时间与精力开始下一阶段。","en":"Advice: a completed club event still consumes time because files and duties remain open. Finish the handover and close the old task to make room for the next stage."},"reversal":{"zh":"逆位示例：明知旧项目已经结束，仍不愿交接，继续重复已经没有作用的工作。这里要留意不愿承认结束的情况，不能理解成项目会自动重新开始。","en":"Reversed example: a finished project is not handed over, and useless work continues. Notice reluctance to accept an ending; it does not promise automatic revival."},"visual":{"zh":"骷髅骑士前行，画面中有不同人物，远处可见光。前行与变化的场面帮助记住结束和过渡，不是现实死亡证据。","en":"A skeletal rider advances among different figures, with light in the distance. The scene supports remembering endings and transition, not evidence of a real death."},"questions":{"Q1":{"id":"m13-Q1","prompt":{"zh":"本课讲的死神，主要表达什么意思？","en":"What does Death mainly express in this lesson?"},"options":[{"id":"m13-Q1-fc07587f7a","text":{"zh":"必定有人死亡","en":"Someone must die"},"feedback":{"zh":"本课用结束来解释阶段变化，没有用牌名判断现实中的死亡事件。","en":"The lesson uses endings to discuss changing phases, not to establish an actual death."}},{"id":"m13-Q1-131e4c03ee","text":{"zh":"阶段结束与转变","en":"Ending and transition"},"feedback":{"zh":"一件事结束后，把该收尾的事处理好，再准备下一阶段，符合刚才的讲解。","en":"Finish what needs closing when something ends, then prepare for the next stage. This matches the explanation."}}],"correct":"m13-Q1-131e4c03ee","support":"R1"},"Q2":{"id":"m13-Q2","prompt":{"zh":"已完成活动还占时间，建议是什么？","en":"What is the advice for the completed event?"},"options":[{"id":"m13-Q2-74f936b308","text":{"zh":"做交接并收尾","en":"Complete the handover and closure"},"feedback":{"zh":"把资料和职责交接清楚，旧任务才有真正的结束，也能腾出时间做下一件事。","en":"Clear handover finishes the old task and frees time for the next one."}},{"id":"m13-Q2-4ca18eab99","text":{"zh":"永久维持原任务","en":"Keep the old task forever"},"feedback":{"zh":"活动已经完成，仍无限保留原任务，是没有处理已经到来的结束。","en":"Keeping a completed activity’s duties indefinitely avoids closing what has ended."}}],"correct":"m13-Q2-74f936b308","support":"R2"},"Q3":{"id":"m13-Q3","prompt":{"zh":"旧项目已经结束，却仍不愿交接。这个逆位例子强调什么？","en":"What does the reversal example emphasize when someone refuses to hand over a finished project?"},"options":[{"id":"m13-Q3-39a2c5ea62","text":{"zh":"项目保证重新成功","en":"Guaranteed renewed success"},"feedback":{"zh":"例子只说明不愿交接，没有提供项目会重新成功的依据。","en":"Refusal to hand over supplies no evidence of renewed success."}},{"id":"m13-Q3-af47fc0988","text":{"zh":"抗拒承认结束","en":"Resistance to acknowledging the end"},"feedback":{"zh":"知道项目已结束却不愿放手，正是例子中的抗拒。","en":"Knowing a project has ended while refusing to let go is the resistance described."}}],"correct":"m13-Q3-af47fc0988","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"牌名有冲击力，但教学中的主题是阶段转换。要先看问题是否存在已结束的关系、习惯或任务。","en":"The name is striking, but the theme is transition. Look for a completed task, habit or phase in the stated context."}],"question":{"id":"m13-R1","prompt":{"zh":"可以只凭“死神”这个牌名，就认定现实中有人死亡吗？","en":"Can the name Death alone establish that someone has died?"},"options":[{"id":"m13-R1-14a41bf1ac","text":{"zh":"不可，要回到问题与阶段变化","en":"No; return to context and transition"},"feedback":{"zh":"牌名可以提醒我们理解结束与变化，不能替代对现实事件的核实。","en":"The name can recall endings and change, but cannot replace checking real events."}},{"id":"m13-R1-210852f335","text":{"zh":"可以，不必看背景","en":"Yes, regardless of context"},"feedback":{"zh":"跳过背景直接把牌名当事实，会把象征含义误当成已经发生的事件。","en":"Treating a name as fact without context mistakes symbolism for an established event."}}],"correct":"m13-R1-14a41bf1ac"}},"R2":{"teach":[{"zh":"收尾是实在的行动：交还职责、整理资料、确认结束，不是突然丢掉所有责任。","en":"Closure can mean handing over duties, organising files and confirming completion, not dropping every responsibility."}],"question":{"id":"m13-R2","prompt":{"zh":"收尾行动是哪一个？","en":"Which action provides closure?"},"options":[{"id":"m13-R2-7567c338ba","text":{"zh":"不告知任何人就丢下责任","en":"Disappear without communicating"},"feedback":{"zh":"突然不管，会把未交接的责任留给别人；这不等于妥善结束任务。","en":"Disappearing leaves duties untransferred and does not properly close the task."}},{"id":"m13-R2-001c42178f","text":{"zh":"确认已完成并移交剩余职责","en":"Confirm completion and transfer duties"},"feedback":{"zh":"确认哪些做完、剩余职责由谁接手，是实际完成收尾。","en":"Confirming completion and transferring remaining duties provides real closure."}}],"correct":"m13-R2-001c42178f"}},"R3":{"teach":[{"zh":"不愿承认项目结束，并不能让已经结束的项目继续下去。这个逆位例子讲的是不愿放下，不是保证项目会重新开始。","en":"Refusing to acknowledge a finished project cannot keep it alive. This reversal concerns reluctance to let go, not guaranteed revival."}],"question":{"id":"m13-R3","prompt":{"zh":"不愿结束等于不会结束吗？","en":"Does resisting an ending prevent it?"},"options":[{"id":"m13-R3-9678e3a7cb","text":{"zh":"不等于","en":"No"},"feedback":{"zh":"人的不舍可以影响交接，却不能让已经结束的项目自动恢复。","en":"Reluctance may delay handover but cannot automatically revive a finished project."}},{"id":"m13-R3-4bc69a0562","text":{"zh":"等于","en":"Yes"},"feedback":{"zh":"不愿接受结束是一种反应，不是能够改变事实的保证。","en":"Reluctance is a response, not a guarantee that circumstances will change."}}],"correct":"m13-R3-9678e3a7cb"}}},"revisit":{"id":"m13-V1","prompt":{"zh":"旧的学习习惯已经不适用，怎样运用死神的含义？","en":"How can Death apply when an old study habit no longer works?"},"options":[{"id":"m13-V1-a641c00e5c","text":{"zh":"因舍不得而永不调整","en":"Never adjust because it feels familiar"},"feedback":{"zh":"习惯已经不合用，只因熟悉而保留它，会继续遇到原来的问题。","en":"Keeping an unsuitable habit only because it is familiar preserves the problem."}},{"id":"m13-V1-b5f844e451","text":{"zh":"结束旧做法并建立替代方式","en":"Let the old approach end and build a replacement"},"feedback":{"zh":"让不再适用的做法结束，再开始替代方法，符合告别与转变。","en":"Ending an unsuitable approach and adopting another applies ending and transition."}}],"correct":"m13-V1-b5f844e451"},"summary":{"zh":"死神常说一件事告一段落，需要结束已经不适用的做法，再开始下一阶段。它让我们面对该结束的事，不是在预告有人死亡。","en":"Death often describes something coming to an end: leave behind an approach that no longer fits and move into the next stage. It asks us to face an ending, not predict someone’s death."},"cards":["m13"]},{"id":"m14","kind":"card","level":"I","title":{"zh":"节制","en":"Temperance"},"teachings":[{"zh":"节制表达适度、耐心和相互配合。不同的需要放在一起时，要一点点调整到合适的程度，不是所有事都各占一半，也不是压下自己的所有需要。","en":"Temperance expresses moderation, patience and cooperation. Different needs require gradual adjustment, not equal halves for everything or suppressing every need."},{"zh":"人物在两个杯子之间倾倒液体，一脚在水中、一脚在地面。流动与两种环境帮助记住调和；不是精确配方。","en":"A figure pours between two cups, with one foot in water and one on land. Flow and two settings suggest integration, not an exact recipe."},{"zh":"关键词：适度、配合、耐心、平衡。重点是适合实际需要，不是机械地平均分配。","en":"Remember: moderation, cooperation, patience, balance. Fit actual needs rather than dividing everything mechanically into equal parts."}],"application":{"zh":"建议位：备考和休息总是顾此失彼，可以先试一份自己能坚持的时间安排，再看精力是否够用，继续调整。不会因为节制就规定每天必须一半学习一半休息。","en":"Advice: study and rest crowd each other out. Try a sustainable schedule and adjust to energy levels; the card does not prescribe a fifty-fifty split."},"reversal":{"zh":"逆位示例：连续熬夜后又完全停学，节奏在两端摆动。这里关注失衡与缺少协调，先把学习和休息安排到自己能够坚持的程度。","en":"Reversed example: all-night study alternates with abandoning study entirely. This concerns imbalance; restore a sustainable rhythm."},"visual":{"zh":"人物在两个杯子之间倾倒液体，一脚在水中、一脚在地面。流动与两种环境帮助记住调和；不是精确配方。","en":"A figure pours between two cups, with one foot in water and one on land. Flow and two settings suggest integration, not an exact recipe."},"questions":{"Q1":{"id":"m14-Q1","prompt":{"zh":"节制所说的平衡，应该怎样理解？","en":"How should the balance of Temperance be understood?"},"options":[{"id":"m14-Q1-4f807ad50a","text":{"zh":"按实际需要，调整到合适的程度","en":"Adjust to a level that fits actual needs"},"feedback":{"zh":"不同人、不同任务需要的安排不一样，合适比固定比例更重要。","en":"Different people and tasks need different arrangements; suitability matters more than a fixed ratio."}},{"id":"m14-Q1-82f61b9a9d","text":{"zh":"凡事都平均一半","en":"Split everything exactly in half"},"feedback":{"zh":"平均分配不一定符合实际需要，本课没有规定固定比例。","en":"Equal division may not fit actual needs; no fixed ratio is taught."}}],"correct":"m14-Q1-4f807ad50a","support":"R1"},"Q2":{"id":"m14-Q2","prompt":{"zh":"在备考与休息总是顾此失彼的例子里，哪种做法符合刚才的示范？","en":"Which action fits the study-and-rest example?"},"options":[{"id":"m14-Q2-47eadc00fb","text":{"zh":"无论状态都机械对半分","en":"Always split time equally regardless of condition"},"feedback":{"zh":"不看精力和任务只对半分，可能仍然让自己疲惫或无法完成任务。","en":"An equal split that ignores energy and workload may still cause exhaustion or unfinished work."}},{"id":"m14-Q2-24ce9b7f67","text":{"zh":"先试一份能坚持的安排，再按精力调整","en":"Try a manageable schedule and adjust it to your energy"},"feedback":{"zh":"先试再按实际精力调整，才能找到学习和休息都能兼顾的安排。","en":"Trying and adjusting to actual energy can produce workable study and rest."}}],"correct":"m14-Q2-24ce9b7f67","support":"R2"},"Q3":{"id":"m14-Q3","prompt":{"zh":"连续熬夜后又完全停学。这个逆位例子中，需要改进什么？","en":"What needs changing in the reversal example of all-nighters followed by stopping study completely?"},"options":[{"id":"m14-Q3-c72eccd6df","text":{"zh":"熬夜后又完全停学的反复","en":"The cycle of all-nighters followed by stopping study"},"feedback":{"zh":"问题正是熬夜后又完全停止，需要减少这两种极端之间的反复。","en":"The problem is swinging from all-nighters to stopping completely; reduce that swing."}},{"id":"m14-Q3-460f8ad618","text":{"zh":"自己还不够拼命","en":"Not pushing yourself hard enough"},"feedback":{"zh":"例子已经过于极端，更加极端地努力会延续原来的问题。","en":"Greater extremes would continue the very problem described."}}],"correct":"m14-Q3-c72eccd6df","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"这就像调水温：先看看水温是否合适，再一点点加冷水或热水，不是规定冷热水永远各一半。","en":"This resembles adjusting water temperature: add cold or hot water gradually as needed, rather than requiring equal quantities."}],"question":{"id":"m14-R1","prompt":{"zh":"为什么节制不要求学习和休息永远各占一半？","en":"Why does Temperance not require study and rest always to be split equally?"},"options":[{"id":"m14-R1-89e1021acb","text":{"zh":"调和完全不需要安排","en":"Integration needs no planning"},"feedback":{"zh":"不固定一半不等于不安排，仍需要根据精力和任务作调整。","en":"Rejecting a fixed half does not remove planning; energy and tasks still guide adjustments."}},{"id":"m14-R1-6c451caba5","text":{"zh":"需求和条件会不同","en":"Needs and conditions vary"},"feedback":{"zh":"实际精力和任务量会变化，所以合适的时间分配也可能变化。","en":"Energy and workload vary, so suitable time allocations may vary too."}}],"correct":"m14-R1-6c451caba5"}},"R2":{"teach":[{"zh":"新安排先试着做，再看精力够不够、任务能不能按时完成；不合适的地方再慢慢改。","en":"Try a schedule, check whether energy is sufficient and tasks can be completed, then gradually revise unsuitable parts."}],"question":{"id":"m14-R2","prompt":{"zh":"新安排试行后看什么？","en":"What do you review after trying a schedule?"},"options":[{"id":"m14-R2-85072582b9","text":{"zh":"精力是否够用，任务能否按这个节奏完成","en":"Whether energy is sufficient and tasks can be completed at this pace"},"feedback":{"zh":"这些情况能告诉你安排是否做得下去，哪里需要减少或增加。","en":"These checks show whether the schedule works and where it needs adjustment."}},{"id":"m14-R2-c573bf4f91","text":{"zh":"是否严格复制别人作息","en":"Whether it copies someone else exactly"},"feedback":{"zh":"别人的精力和任务可能不同，照搬作息不能说明适合自己。","en":"Someone else’s energy and workload may differ; copying does not establish suitability."}}],"correct":"m14-R2-85072582b9"}},"R3":{"teach":[{"zh":"逆位例不是要求更极端地控制自己，而是减少在两端来回摆动。","en":"The reversal does not call for harsher control; reduce the swing between extremes."}],"question":{"id":"m14-R3","prompt":{"zh":"要减少熬夜和完全停学之间的反复，可以先怎样做？","en":"What can reduce the swing between all-nighters and stopping study?"},"options":[{"id":"m14-R3-f6534f62b6","text":{"zh":"熬夜更多来弥补全部","en":"Add more all-nighters to compensate"},"feedback":{"zh":"增加熬夜仍在延续过度用力，可能又接着完全停下来。","en":"More all-nighters continue overexertion and may lead back to stopping completely."}},{"id":"m14-R3-1a77eba9d2","text":{"zh":"先安排一段能坚持的学习和休息时间","en":"Start with manageable study and rest periods"},"feedback":{"zh":"从能坚持的时段开始，再逐渐调整，才有机会不再反复走向极端。","en":"Manageable periods followed by gradual adjustment can reduce repeated extremes."}}],"correct":"m14-R3-1a77eba9d2"}}},"revisit":{"id":"m14-V1","prompt":{"zh":"合作双方做事速度不同，怎样运用节制的含义？","en":"How can Temperance apply when collaborators work at different speeds?"},"options":[{"id":"m14-V1-750c68e903","text":{"zh":"商定衔接节奏并试着调整","en":"Agree on a shared rhythm and adjust it"},"feedback":{"zh":"商定怎样衔接工作，再根据实际情况调整，能让不同速度也配合起来。","en":"Agreed handoffs and adjustment can coordinate different working speeds."}},{"id":"m14-V1-4864c67994","text":{"zh":"要求双方所有习惯完全一样","en":"Require identical habits in every respect"},"feedback":{"zh":"配合不要求习惯全部一样；重点是双方工作能够接得上。","en":"Cooperation does not require identical habits, only work that connects effectively."}}],"correct":"m14-V1-750c68e903"},"summary":{"zh":"节制表达适度、耐心和相互配合。不同的需要放在一起时，要一点点调整到合适的程度，不是所有事都各占一半，也不是压下自己的所有需要。","en":"Temperance expresses moderation, patience and cooperation. Different needs require gradual adjustment, not equal halves for everything or suppressing every need."},"cards":["m14"]},{"id":"m15","kind":"card","level":"I","title":{"zh":"恶魔","en":"The Devil"},"teachings":[{"zh":"恶魔表达束缚、依赖和难以摆脱的诱惑。有些事短暂让人舒服，却让人越来越难停下来，挤掉原本想做的事。它不证明有人邪恶或受到了诅咒。","en":"The Devil represents constraint, dependence and hard-to-resist temptation. Something briefly comforting can become hard to stop and crowd out intended activities. It does not establish evil or a curse."},{"zh":"人物被链条连接在座前，链圈看起来有松动空间。链条帮助记住束缚，松动空间提醒检查可改变之处；不表示所有现实限制都容易解除。","en":"Figures are chained before a pedestal, with apparently loose loops. Chains recall constraint; the space invites examining possible change, not assuming every real constraint is easy to escape."},{"zh":"关键词：束缚、依赖、诱惑、难以停下。留意想停却不容易停的处境，不要据此判断一个人的好坏。","en":"Remember: constraint, dependence, temptation, difficulty stopping. Notice the hard-to-stop situation rather than judging a person’s worth."}],"application":{"zh":"建议位：总忍不住刷新短视频，已经挤掉计划中的练习时间。先留意自己什么时候开始刷、为什么停不下来，再给使用时间作具体限制，不必把自己骂成没有价值的人。","en":"Advice: repeated video scrolling crowds out planned practice. Notice when it starts and why it continues, then set concrete time limits instead of condemning your worth."},"reversal":{"zh":"逆位示例：已经看见刷屏的代价，并开始关掉自动播放。这里可以理解为开始改变让自己停不下来的习惯，不保证从此再无反复。","en":"Reversed example: recognising the cost of scrolling and disabling autoplay. This can suggest beginning to loosen a pattern, not a guarantee of no recurrence."},"visual":{"zh":"人物被链条连接在座前，链圈看起来有松动空间。链条帮助记住束缚，松动空间提醒检查可改变之处；不表示所有现实限制都容易解除。","en":"Figures are chained before a pedestal, with apparently loose loops. Chains recall constraint; the space invites examining possible change, not assuming every real constraint is easy to escape."},"questions":{"Q1":{"id":"m15-Q1","prompt":{"zh":"恶魔在本课关注什么？","en":"What does the Devil focus on here?"},"options":[{"id":"m15-Q1-d97e5ff396","text":{"zh":"证明某人邪恶","en":"Proving someone evil"},"feedback":{"zh":"这张牌讨论让人难以停下的依赖，不能用来证明某个人邪恶。","en":"The card discusses constraining dependence, not proof that a person is evil."}},{"id":"m15-Q1-e9ff223125","text":{"zh":"越来越依赖某种习惯，想停却不容易停","en":"Becoming dependent on a habit that is hard to stop"},"feedback":{"zh":"想停却很难停，连原本计划也受影响，正体现了本课的束缚与依赖。","en":"Difficulty stopping despite effects on other plans expresses the taught constraint and dependence."}}],"correct":"m15-Q1-e9ff223125","support":"R1"},"Q2":{"id":"m15-Q2","prompt":{"zh":"总忍不住刷短视频，练习时间因此被挤掉。哪种建议符合刚才的示范？","en":"Scrolling crowds out planned practice. Which advice fits the example?"},"options":[{"id":"m15-Q2-d8257e4d23","text":{"zh":"留意何时开始刷，并限制使用时间","en":"Notice when scrolling starts and limit usage time"},"feedback":{"zh":"知道什么时候容易开始刷，再限制使用时间，才是在改变具体习惯。","en":"Noticing when scrolling begins and limiting time addresses the specific habit."}},{"id":"m15-Q2-50fb043030","text":{"zh":"只反复责骂自己","en":"Only repeat self-blame"},"feedback":{"zh":"责骂没有改变什么时候打开、为什么继续，也没有给行为作出新的安排。","en":"Blame does not change when scrolling starts, why it continues, or how it is managed."}}],"correct":"m15-Q2-d8257e4d23","support":"R2"},"Q3":{"id":"m15-Q3","prompt":{"zh":"看见刷屏的代价后，开始关闭自动播放。这个逆位例子说明什么？","en":"What does the reversal example show when autoplay is turned off after recognizing the cost of scrolling?"},"options":[{"id":"m15-Q3-8f05a3056f","text":{"zh":"从此绝不再反复","en":"Guaranteed permanent freedom"},"feedback":{"zh":"关掉自动播放是一个开始，不能据此保证以后绝不会再刷过头。","en":"Turning off autoplay is a beginning, not a guarantee against future overuse."}},{"id":"m15-Q3-d321267058","text":{"zh":"开始改变让自己停不下来的习惯","en":"Begin changing a hard-to-stop habit"},"feedback":{"zh":"已经采取具体行动，开始减少原来让自己不断刷下去的影响。","en":"A concrete action begins reducing what previously kept the scrolling going."}}],"correct":"m15-Q3-d321267058","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"一件事当下让人舒服，也可能慢慢占掉时间、让人难以停下。要同时看到它为什么吸引自己，以及为此放弃了什么。","en":"Something comforting now may take increasing time and become hard to stop. Consider both its attraction and what it costs."}],"question":{"id":"m15-R1","prompt":{"zh":"短暂舒服是否可能伴随限制？","en":"Can short-term comfort coexist with restriction?"},"options":[{"id":"m15-R1-0fd96c7ab3","text":{"zh":"可以，要一起看吸引与代价","en":"Yes; consider both attraction and cost"},"feedback":{"zh":"刷视频可以当下轻松，同时挤掉练习时间，舒服与付出代价可以并存。","en":"Scrolling can feel relaxing while taking practice time; comfort and cost can coexist."}},{"id":"m15-R1-ec9b43d928","text":{"zh":"不可能，舒服就是完全自由","en":"No; comfort means complete freedom"},"feedback":{"zh":"感到舒服不等于可以随时停下，也不代表没有失去别的时间。","en":"Comfort does not establish an ability to stop or the absence of costs."}}],"correct":"m15-R1-0fd96c7ab3"}},"R2":{"teach":[{"zh":"把“我不行”换成具体问题：什么时候打开、什么让你一直刷下去、可以先限制哪一段使用时间。","en":"Replace “I am incapable” with specific questions: when does scrolling start, what keeps it going, and which period of use can you limit first?"}],"question":{"id":"m15-R2","prompt":{"zh":"想改变停不下来的刷屏习惯，先问自己哪一个问题？","en":"Which question helps examine a hard-to-stop scrolling habit?"},"options":[{"id":"m15-R2-c5882dbe7f","text":{"zh":"我是不是完全没有价值","en":"Am I entirely worthless"},"feedback":{"zh":"这把一个可以检查的习惯，变成了对整个人价值的否定。","en":"This turns an examinable habit into a judgment about the person’s entire worth."}},{"id":"m15-R2-fc548cd2fb","text":{"zh":"什么场景让我不断继续","en":"What situation keeps the behaviour going"},"feedback":{"zh":"问清什么情况让自己一直刷，才可能找到具体能调整的地方。","en":"Understanding what keeps scrolling going helps identify a specific change."}}],"correct":"m15-R2-fc548cd2fb"}},"R3":{"teach":[{"zh":"这个逆位例子已经有了关闭自动播放的行动。看清习惯不等于已经改掉，还要看之后能否继续做到。","en":"The reversal example includes disabling autoplay. Recognizing a habit does not mean it is changed; continued action still matters."}],"question":{"id":"m15-R3","prompt":{"zh":"已经看见习惯怎样限制自己，接下来还需要什么？","en":"After recognizing how a habit constrains you, what is still needed?"},"options":[{"id":"m15-R3-6e12cae40b","text":{"zh":"具体改变与持续观察","en":"Concrete change and monitoring"},"feedback":{"zh":"发现问题后仍要采取改变，并看看是否有用，才不只停在知道这一步。","en":"Recognition still needs action and observation of whether the change helps."}},{"id":"m15-R3-6b7c432408","text":{"zh":"不用行动，一切已解决","en":"No action; everything is solved"},"feedback":{"zh":"知道有问题并没有自动改变习惯，例子也是靠关掉自动播放开始改变。","en":"Awareness alone does not change the habit; the example begins with disabling autoplay."}}],"correct":"m15-R3-6e12cae40b"}}},"revisit":{"id":"m15-V1","prompt":{"zh":"冲动购物已经挤占预算，怎样运用恶魔的含义？","en":"How can the Devil apply when impulse shopping crowds out the budget?"},"options":[{"id":"m15-V1-d286d5f1e1","text":{"zh":"用牌断言商家在诅咒自己","en":"Claim the seller has cursed you"},"feedback":{"zh":"冲动消费没有提供被诅咒的证据，牌也不能代替这种证明。","en":"Impulse spending supplies no evidence of a curse, and the card cannot establish one."}},{"id":"m15-V1-06a6a681a7","text":{"zh":"看清诱因和代价，设置购买边界","en":"Examine triggers and costs, then set boundaries"},"feedback":{"zh":"检查购买冲动从哪里来、挤掉了哪些预算，再限制购买，回应了依赖与代价。","en":"Examining impulses and budget costs before setting limits addresses dependence and its cost."}}],"correct":"m15-V1-06a6a681a7"},"summary":{"zh":"恶魔表达束缚、依赖和难以摆脱的诱惑。有些事短暂让人舒服，却让人越来越难停下来，挤掉原本想做的事。它不证明有人邪恶或受到了诅咒。","en":"The Devil represents constraint, dependence and hard-to-resist temptation. Something briefly comforting can become hard to stop and crowd out intended activities. It does not establish evil or a curse."},"cards":["m15"]},{"id":"m16","kind":"card","level":"I","title":{"zh":"高塔","en":"The Tower"},"teachings":[{"zh":"高塔表达突如其来的冲击：原以为可靠的安排或看法突然行不通了，原来没看见的问题也显露出来。它不等于每次都预告事故或失业。","en":"The Tower expresses sudden disruption: arrangements or beliefs once considered reliable fail, exposing previously unseen problems. It does not invariably predict accidents or job loss."},{"zh":"闪电击中塔顶，皇冠倾落，人物坠下。这些画面可以帮助记住原本稳固的东西突然被打破；不能由图确定个人会遭遇什么事件。","en":"Lightning strikes the tower, its crown falls and people tumble. These images recall the sudden breaking of apparent stability, not a specific personal event."},{"zh":"关键词：突变、冲击、原有安排被打破、问题暴露。原来以为可靠的东西突然不再可靠，是理解这张牌的一条主线。","en":"Remember: upheaval, disruption, broken arrangements, exposed problems. The sudden failure of something once considered reliable is a central idea."}],"application":{"zh":"建议位：项目一直靠一个人记住所有交接，离岗一次就中断。把交接步骤记下来，让其他成员也知道怎样接手，而不是主动制造危机。","en":"Advice: a project relies on one person remembering every handover and stops during an absence. Record the steps so others can take over; do not deliberately create a crisis."},"reversal":{"zh":"逆位示例：已经知道原来的交接方法行不通，却为了维持表面正常而回避改动。这里关注抗拒必要改变，不保证问题不会发生。","en":"Reversed example: a failed handover structure is known but change is avoided to preserve appearances. This concerns resistance to needed change, not a guarantee that problems will disappear."},"visual":{"zh":"闪电击中塔顶，皇冠倾落，人物坠下。这些画面可以帮助记住原本稳固的东西突然被打破；不能由图确定个人会遭遇什么事件。","en":"Lightning strikes the tower, its crown falls and people tumble. These images recall the sudden breaking of apparent stability, not a specific personal event."},"questions":{"Q1":{"id":"m16-Q1","prompt":{"zh":"高塔在本课表达的核心含义是什么？","en":"What is the Tower’s core meaning in this lesson?"},"options":[{"id":"m16-Q1-3af3752d77","text":{"zh":"原以为可靠的安排突然行不通了","en":"An arrangement once thought reliable suddenly fails"},"feedback":{"zh":"原本以为稳固的塔被闪电击中，帮助记住原先可靠的东西突然被打破。","en":"Lightning striking a seemingly solid tower recalls the sudden failure of something once reliable."}},{"id":"m16-Q1-a7443682d9","text":{"zh":"一定发生交通事故","en":"A traffic accident is certain"},"feedback":{"zh":"牌面呈现突然冲击，但没有说明现实中一定发生哪一种事故。","en":"The image conveys sudden disruption without establishing a particular real accident."}}],"correct":"m16-Q1-3af3752d77","support":"R1"},"Q2":{"id":"m16-Q2","prompt":{"zh":"一个人离岗就无法交接，怎样运用高塔在建议位的含义？","en":"How does the Tower in advice apply when one person’s absence stops the handover?"},"options":[{"id":"m16-Q2-96bdcfe2a6","text":{"zh":"主动破坏项目","en":"Deliberately wreck the project"},"feedback":{"zh":"建议位是在问怎样处理问题，不是在命令人制造一次破坏。","en":"Advice asks how to handle the problem, not how to create destruction."}},{"id":"m16-Q2-19de4a764c","text":{"zh":"记录交接步骤，让其他成员也能接手","en":"Record handover steps so others can take over"},"feedback":{"zh":"写清步骤并让其他人能接手，能直接改善一人离岗就中断的问题。","en":"Written steps and additional people able to take over address the interruption caused by one absence."}}],"correct":"m16-Q2-19de4a764c","support":"R2"},"Q3":{"id":"m16-Q3","prompt":{"zh":"明知交接方法行不通，却为了表面正常而不改。这个逆位例子说明什么？","en":"What does the reversal example show when a known handover failure is ignored to preserve appearances?"},"options":[{"id":"m16-Q3-9dec55bbc0","text":{"zh":"原来交接不可靠的问题仍需处理","en":"The unreliable handover still needs attention"},"feedback":{"zh":"不改动并没有解决只靠一人的交接问题，它仍需要处理。","en":"Avoiding change does not resolve reliance on one person; the issue remains."}},{"id":"m16-Q3-eb1e01c311","text":{"zh":"原来的交接方式因此绝对可靠","en":"The original handover is therefore completely reliable"},"feedback":{"zh":"表面维持正常，没有改变实际交接方法，不能因此保证可靠。","en":"Keeping up appearances does not change the actual handover or guarantee reliability."}}],"correct":"m16-Q3-9dec55bbc0","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"突变说的是稳定感被打断；现实会发生什么，仍需要问题背景，不能从牌名挑一个灾难。","en":"Disruption means an interruption of stability; the actual event requires context, not choosing a disaster from the card’s name."}],"question":{"id":"m16-R1","prompt":{"zh":"能凭高塔确定哪种灾难吗？","en":"Can the Tower identify a specific disaster?"},"options":[{"id":"m16-R1-0566e24aeb","text":{"zh":"能，直接选最严重的","en":"Yes; choose the worst event"},"feedback":{"zh":"本课只教了突发冲击，没有依据选出某一种更严重的现实灾难。","en":"The lesson teaches disruption, not a basis for choosing a particular disaster."}},{"id":"m16-R1-da9adb8ea8","text":{"zh":"不能，需要现实背景","en":"No; context is needed"},"feedback":{"zh":"需要了解现实问题，才能讨论这张牌可能怎样对应；牌名本身不能确认灾难。","en":"Context is needed to discuss a possible application; the card’s name cannot establish a disaster."}}],"correct":"m16-R1-da9adb8ea8"}},"R2":{"teach":[{"zh":"建议位是在问怎样应对眼前的问题。工作只靠一人记住交接，就把步骤写下来，让其他人也能接手；不是要求主动破坏项目。","en":"Advice asks how to respond. A handover dependent on one person’s memory needs written steps and others able to take over, not deliberate destruction."}],"question":{"id":"m16-R2","prompt":{"zh":"刚才的建议为什么是记录并改进交接方法？","en":"Why does the advice suggest recording and improving the handover?"},"options":[{"id":"m16-R2-4b5db7fa70","text":{"zh":"问题出在工作交接只靠一个人记住","en":"The handover relies on one person’s memory"},"feedback":{"zh":"只靠一人记住步骤，离岗就断，所以记录和让别人接手正好处理这个原因。","en":"One person’s absence breaks the memory-dependent handover, so records and backup directly address it."}},{"id":"m16-R2-fde2c77143","text":{"zh":"为了让冲击更严重","en":"To intensify disruption"},"feedback":{"zh":"建议是减少已知问题造成的中断，不是让冲击更严重。","en":"The advice reduces an identified interruption rather than intensifying it."}}],"correct":"m16-R2-4b5db7fa70"}},"R3":{"teach":[{"zh":"不讨论交接问题，不能让原来的方法变得可靠。例子已经知道问题在哪里，需要的是检查和处理。","en":"Silence does not make the handover reliable. The known problem needs examination and action."}],"question":{"id":"m16-R3","prompt":{"zh":"不谈已知弱点会让它消失吗？","en":"Does silence remove a known weakness?"},"options":[{"id":"m16-R3-3bd6ccfcc6","text":{"zh":"会，逆位表示完全取消","en":"Yes; reversed means cancellation"},"feedback":{"zh":"逆位没有替你更改交接方法，不讨论也不会让已知问题消失。","en":"Reversal does not alter the handover, and silence does not remove the problem."}},{"id":"m16-R3-f7f1e2953b","text":{"zh":"不会，应检查并处理","en":"No; inspect and address it"},"feedback":{"zh":"把已经知道的问题拿出来检查、处理，才可能让交接可靠起来。","en":"Examining and addressing the known problem can make the handover more reliable."}}],"correct":"m16-R3-f7f1e2953b"}}},"revisit":{"id":"m16-V1","prompt":{"zh":"团队发现以前据旧数据得出的结论有误，怎样运用高塔的含义？","en":"How can the Tower apply when a team finds its earlier data-based conclusion was wrong?"},"options":[{"id":"m16-V1-36b35d23d5","text":{"zh":"面对发现的问题，查清数据并重新核对结论","en":"Face the problem, check the data and reassess the conclusion"},"feedback":{"zh":"旧结论已经不可靠，先核查数据再作判断，是在回应刚发现的冲击。","en":"Checking data before reassessing an unreliable conclusion responds to the newly discovered disruption."}},{"id":"m16-V1-a1acb79614","text":{"zh":"因过去稳定就拒绝核查","en":"Refuse checks because things once seemed stable"},"feedback":{"zh":"以前觉得可靠，不能取消现在已经发现的错误，仍需要核查。","en":"Past confidence does not erase a newly discovered error; checking remains necessary."}}],"correct":"m16-V1-36b35d23d5"},"summary":{"zh":"高塔表达突如其来的冲击：原以为可靠的安排或看法突然行不通了，原来没看见的问题也显露出来。它不等于每次都预告事故或失业。","en":"The Tower expresses sudden disruption: arrangements or beliefs once considered reliable fail, exposing previously unseen problems. It does not invariably predict accidents or job loss."},"cards":["m16"]},{"id":"m17","kind":"card","level":"I","title":{"zh":"星星","en":"The Star"},"teachings":[{"zh":"星星关注经历困难之后的希望、恢复与重新找到方向。经历挫折后，仍可以慢慢恢复、重新相信前面还有路可走；但不承诺愿望立刻实现。","en":"The Star concerns hope, renewal and rediscovering direction after difficulty. It supports continuing recovery, not instant fulfilment of a wish."},{"zh":"人物向水面和土地倾水，天空有星。水的流动与开阔场景帮助记住恢复和希望；星光不是现实成功的证据。","en":"A figure pours water onto water and land beneath stars. Flow and openness help recall renewal and hope; starlight is not proof of success."},{"zh":"关键词：希望、恢复、信任、方向。希望可以与仍需努力并存。","en":"Recall labels: hope, renewal, trust, direction. Hope can coexist with further effort."}],"application":{"zh":"建议位：创作受挫后想重新开始，先从自己能坚持的短练习做起，再想想自己仍然想创作什么。不是只许愿就不用行动。","en":"Advice: after a creative setback, begin with short, manageable practice and reconnect with what you still want to create. Wishing does not replace action."},"reversal":{"zh":"逆位示例：一次失败之后不再相信任何进步，连已有的小改善也看不见。这里关注希望减弱，先识别可见进展。","en":"Reversed example: after failure, no progress seems believable and small improvements go unnoticed. This concerns diminished hope; begin by recognising visible progress."},"visual":{"zh":"人物向水面和土地倾水，天空有星。水的流动与开阔场景帮助记住恢复和希望；星光不是现实成功的证据。","en":"A figure pours water onto water and land beneath stars. Flow and openness help recall renewal and hope; starlight is not proof of success."},"questions":{"Q1":{"id":"m17-Q1","prompt":{"zh":"星星主要传达什么？","en":"What does the Star mainly convey?"},"options":[{"id":"m17-Q1-77269031eb","text":{"zh":"愿望马上必定实现","en":"Immediate guaranteed fulfilment"},"feedback":{"zh":"希望说明仍有恢复与前进的可能，不是保证愿望马上实现。","en":"Hope leaves room for recovery and progress without guaranteeing immediate fulfillment."}},{"id":"m17-Q1-c0153248e0","text":{"zh":"希望与恢复","en":"Hope and renewal"},"feedback":{"zh":"困难后慢慢恢复，并重新看见可以继续的方向，正是本课的主旨。","en":"Gradual recovery and renewed direction after difficulty express the taught theme."}}],"correct":"m17-Q1-c0153248e0","support":"R1"},"Q2":{"id":"m17-Q2","prompt":{"zh":"创作受挫后怎样应用建议？","en":"How does the advice apply after creative difficulty?"},"options":[{"id":"m17-Q2-37d0a1fae3","text":{"zh":"从能坚持的短练习重新开始","en":"Restart with short, manageable practice"},"feedback":{"zh":"从做得到的短练习开始，能让恢复有实际行动，而不只停在愿望上。","en":"Manageable practice gives recovery a concrete action beyond wishing."}},{"id":"m17-Q2-ed0c514fa5","text":{"zh":"只许愿并停止行动","en":"Only wish and stop acting"},"feedback":{"zh":"愿望本身没有重新开始练习，不能代替恢复的过程。","en":"Wishing does not restart practice or replace the recovery process."}}],"correct":"m17-Q2-37d0a1fae3","support":"R2"},"Q3":{"id":"m17-Q3","prompt":{"zh":"一次失败后，只觉得再也不会进步。在这个逆位例子里，先看看什么？","en":"After a failure, someone no longer believes improvement is possible. What should be examined first?"},"options":[{"id":"m17-Q3-7a6743f083","text":{"zh":"一次失败证明永远无望","en":"One failure proves permanent hopelessness"},"feedback":{"zh":"一次失败只说明那一次未成功，不能据此否定所有后续可能。","en":"One failure does not rule out every later possibility."}},{"id":"m17-Q3-9298f793b1","text":{"zh":"已有但被忽略的小改善","en":"Small improvements being overlooked"},"feedback":{"zh":"例子已经提到小改善却看不见，重新识别它们才能回应眼前的失望。","en":"The example includes overlooked improvements; noticing them responds to the discouragement."}}],"correct":"m17-Q3-9298f793b1","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"有希望，不等于已经知道哪一天会成功。可以重新尝试，同时接受恢复需要时间和实际行动。","en":"Hope does not establish a success date. Try again while accepting that recovery takes time and action."}],"question":{"id":"m17-R1","prompt":{"zh":"星星表达希望，能保证愿望会在哪一天实现吗？","en":"Can the Star’s hope guarantee a date for fulfillment?"},"options":[{"id":"m17-R1-6c47574119","text":{"zh":"不能","en":"No"},"feedback":{"zh":"是否实现、何时实现仍取决于现实情况和后续行动，牌没有给出日期保证。","en":"Timing and fulfillment depend on circumstances and action; the card guarantees no date."}},{"id":"m17-R1-413c06bcef","text":{"zh":"能","en":"Yes"},"feedback":{"zh":"本课只讲希望与恢复，没有教可以从中读出确定日期。","en":"The lesson teaches hope and recovery, not a fixed date."}}],"correct":"m17-R1-6c47574119"}},"R2":{"teach":[{"zh":"先从自己现在做得到的小练习开始，不要求立刻恢复到以前最好的状态。","en":"Begin with small actions you can manage now, without demanding an immediate return to your previous peak."}],"question":{"id":"m17-R2","prompt":{"zh":"恢复应该怎样起步？","en":"How can renewal begin?"},"options":[{"id":"m17-R2-ce7c0bdd8d","text":{"zh":"未达巅峰就全算失败","en":"Count everything below peak as failure"},"feedback":{"zh":"还没回到最好状态，也可能已经开始进步；全算失败会忽略恢复过程。","en":"Improvement may begin before peak performance; calling all of it failure ignores recovery."}},{"id":"m17-R2-6c693415b4","text":{"zh":"从可坚持的行动开始","en":"Begin with manageable action"},"feedback":{"zh":"按目前能力做小练习，更容易真正开始并逐步恢复。","en":"Small actions suited to present ability support a real start and gradual recovery."}}],"correct":"m17-R2-6c693415b4"}},"R3":{"teach":[{"zh":"觉得没有希望时，先看看有没有被自己忽略的小进步。看见确实做得更好的地方，能帮助自己重新相信仍有进步的可能。","en":"When hope feels absent, look for overlooked improvements. Real examples of progress can renew belief that further improvement is possible."}],"question":{"id":"m17-R3","prompt":{"zh":"觉得没有希望时，回看已有的小进步有什么帮助？","en":"How can noticing small improvements help when hope is low?"},"options":[{"id":"m17-R3-56d70b559c","text":{"zh":"让自己看到仍能进步的实际例子","en":"Show real examples that improvement remains possible"},"feedback":{"zh":"具体的小进步能说明并非毫无变化，帮助重新相信自己还能继续。","en":"Concrete improvement shows that change exists and can renew belief in continuing."}},{"id":"m17-R3-3637d0a8f5","text":{"zh":"证明所有目标已经实现","en":"Prove all goals achieved"},"feedback":{"zh":"小进步只说明某处变好了，不能扩大成所有目标都已完成。","en":"A small improvement concerns one area, not completion of every goal."}}],"correct":"m17-R3-56d70b559c"}}},"revisit":{"id":"m17-V1","prompt":{"zh":"中断练琴后想重新开始，怎样运用星星的含义？","en":"How can the Star apply to resuming piano practice after a break?"},"options":[{"id":"m17-V1-ef7087982d","text":{"zh":"等待奇迹替代练习","en":"Wait for a miracle instead of practice"},"feedback":{"zh":"等待奇迹没有开始练琴，也没有建立实际恢复的过程。","en":"Waiting for a miracle starts no practice or recovery process."}},{"id":"m17-V1-2d57032d7c","text":{"zh":"从短而可持续的练习找回方向","en":"Regain direction through manageable practice"},"feedback":{"zh":"短而能坚持的练习，让重新开始有实际支撑，符合慢慢恢复的含义。","en":"Short, manageable practice supports a real restart and gradual recovery."}}],"correct":"m17-V1-2d57032d7c"},"summary":{"zh":"星星关注经历困难之后的希望、恢复与重新找到方向。经历挫折后，仍可以慢慢恢复、重新相信前面还有路可走；但不承诺愿望立刻实现。","en":"The Star concerns hope, renewal and rediscovering direction after difficulty. It supports continuing recovery, not instant fulfilment of a wish."},"cards":["m17"]},{"id":"m18","kind":"card","level":"I","title":{"zh":"月亮","en":"The Moon"},"teachings":[{"zh":"月亮关注信息不清、想象、恐惧和感受对判断的影响。它提醒分开已经知道的事实与尚未证实的猜测，不等于所有人都在欺骗你。","en":"The Moon concerns unclear information, imagination, fear and feelings influencing judgment. Separate known facts from unverified guesses; it does not mean everyone is deceiving you."},{"zh":"月光下有两座塔、动物和延伸的小路。月光照着小路，前方仍不清楚，可以帮助记住看不清时的不确定；不能把动物或阴影当作某个人撒谎的证据。","en":"Towers, animals and a path appear in moonlight. Limited light and a receding path help recall uncertainty; shadows do not prove someone is lying."},{"zh":"关键词：不确定、想象、担心、看不清。可以承认自己担心，但担心不等于事情已经发生。","en":"Remember: uncertainty, imagination, worry, lack of clarity. Acknowledge worry without treating the feared event as fact."}],"application":{"zh":"建议位：朋友暂未回复，你开始猜测关系破裂。先确认唯一事实是未收到回复；可能原因仍待沟通，不先把最担心的故事当结论。","en":"Advice: a friend has not replied and you fear the relationship is over. The known fact is no reply yet; causes still require clarification."},"reversal":{"zh":"逆位示例：通过沟通得到了原先不知道的重要信息，开始分清哪些只是自己的猜测。这里可以理解为事情逐渐清楚，但仍不代表所有未知都已解决。","en":"Reversed example: communication supplies key facts and earlier guesses become distinguishable. This can suggest clearing confusion, not complete certainty about everything."},"visual":{"zh":"月光下有两座塔、动物和延伸的小路。月光照着小路，前方仍不清楚，可以帮助记住看不清时的不确定；不能把动物或阴影当作某个人撒谎的证据。","en":"Towers, animals and a path appear in moonlight. Limited light and a receding path help recall uncertainty; shadows do not prove someone is lying."},"questions":{"Q1":{"id":"m18-Q1","prompt":{"zh":"月亮首先提醒什么？","en":"What does the Moon first remind us?"},"options":[{"id":"m18-Q1-b8c3b35181","text":{"zh":"区分事实与猜测","en":"Separate facts and guesses"},"feedback":{"zh":"还不清楚时，把已经知道的事和自己想象的原因分开，才不会误判。","en":"Separating known facts from imagined causes avoids confusing uncertainty with knowledge."}},{"id":"m18-Q1-5d13c0fd3d","text":{"zh":"认定所有人说谎","en":"Assume everyone lies"},"feedback":{"zh":"不知道实情，只能说明还不清楚，不能证明所有人都在说谎。","en":"Lacking information establishes uncertainty, not universal deceit."}}],"correct":"m18-Q1-b8c3b35181","support":"R1"},"Q2":{"id":"m18-Q2","prompt":{"zh":"朋友未回复，已知事实是什么？","en":"What is known when the friend has not replied?"},"options":[{"id":"m18-Q2-2de7f4968b","text":{"zh":"关系必定结束","en":"The relationship is certainly over"},"feedback":{"zh":"关系结束是猜测，未收到回复本身没有证明这个原因。","en":"A missing reply does not establish that the relationship has ended."}},{"id":"m18-Q2-b6dcc027fb","text":{"zh":"目前还没收到回复","en":"No reply has arrived yet"},"feedback":{"zh":"目前只知道还没回复，为什么没回仍然需要了解。","en":"Only the absence of a reply is known; the reason remains unclear."}}],"correct":"m18-Q2-b6dcc027fb","support":"R2"},"Q3":{"id":"m18-Q3","prompt":{"zh":"这个例子中，为什么可以把月亮逆位理解为事情逐渐清楚？","en":"Why can the reversed Moon indicate growing clarity in this example?"},"options":[{"id":"m18-Q3-b393f237ee","text":{"zh":"沟通提供了新事实","en":"Communication supplied new facts"},"feedback":{"zh":"例子明确说沟通带来了新事实，因此可以说原来的猜测逐渐减少。","en":"Communication supplies new facts in the example, supporting reduced uncertainty."}},{"id":"m18-Q3-52643a008d","text":{"zh":"逆位自动揭示全部秘密","en":"Reversal reveals every secret automatically"},"feedback":{"zh":"让事情清楚的是实际得到的信息，不是逆位自动提供全部答案。","en":"New information clarifies the issue; reversal does not automatically reveal every answer."}}],"correct":"m18-Q3-b393f237ee","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"“我很担心”是感受，“对方一定讨厌我”是未证实解释，两者不能互相替代。","en":"“I am worried” is a feeling; “they hate me” is an unverified interpretation. They are not interchangeable."}],"question":{"id":"m18-R1","prompt":{"zh":"担心与事实怎样区分？","en":"How do worry and fact differ?"},"options":[{"id":"m18-R1-5e03167b90","text":{"zh":"担心什么就证明发生什么","en":"Fear proves what happened"},"feedback":{"zh":"担心可以很强烈，却仍然不能证明担心的事情已经发生。","en":"Strong worry still does not establish that the feared event happened."}},{"id":"m18-R1-76ff19edb3","text":{"zh":"担心是真实感受，原因仍需核实","en":"Worry is a real feeling; its cause needs checking"},"feedback":{"zh":"“我担心”描述自己的感受，“为什么没回复”仍需要核实。","en":"Worry describes your feeling; the reason for the missing reply still needs checking."}}],"correct":"m18-R1-76ff19edb3"}},"R2":{"teach":[{"zh":"不知道朋友为什么没回复，可以在合适的时候问一问。最担心的原因只是可能性之一，不能直接当成事实。","en":"If a friend’s silence is unexplained, ask at a suitable time. The most worrying explanation remains only one possibility, not a fact."}],"question":{"id":"m18-R2","prompt":{"zh":"还不知道朋友为什么没回复时，哪种做法符合刚才的讲解？","en":"Which response fits the lesson when the reason for a missing reply is unknown?"},"options":[{"id":"m18-R2-cbde05cae8","text":{"zh":"留出其他可能并适时沟通","en":"Allow other possibilities and clarify appropriately"},"feedback":{"zh":"没有确认原因前，可以保留其他解释，再通过沟通了解实情。","en":"Other explanations remain possible until communication clarifies the reason."}},{"id":"m18-R2-5ee4021ae6","text":{"zh":"立即认定最糟猜测","en":"Immediately adopt the worst guess"},"feedback":{"zh":"最糟的猜测只是想象中的可能，不因为让人害怕就成为事实。","en":"The worst guess remains a possibility, not a fact merely because it is frightening."}}],"correct":"m18-R2-cbde05cae8"}},"R3":{"teach":[{"zh":"这个例子因为沟通得到了新信息，事情才逐渐清楚。不能省略沟通这一步，只凭逆位就说所有事情都知道了。","en":"Communication supplies new information in this example, bringing gradual clarity. Reversal alone cannot replace that step or establish complete knowledge."}],"question":{"id":"m18-R3","prompt":{"zh":"知道一项事实等于全部清楚吗？","en":"Does one new fact clarify everything?"},"options":[{"id":"m18-R3-c615f3212a","text":{"zh":"等于，其他都无需问","en":"Yes; no further questions matter"},"feedback":{"zh":"新知道一件事，不代表其他问题也已得到答案。","en":"Learning one fact does not answer every other question."}},{"id":"m18-R3-39ff3f78e2","text":{"zh":"不等于，继续区分已知未知","en":"No; distinguish known from unknown"},"feedback":{"zh":"把刚得到的信息和仍不清楚的部分分开，才符合逐渐了解的过程。","en":"Distinguishing newly known facts from remaining unknowns fits gradual clarification."}}],"correct":"m18-R3-39ff3f78e2"}}},"revisit":{"id":"m18-V1","prompt":{"zh":"听到活动取消的消息，但尚未证实，怎样运用月亮的含义？","en":"How can the Moon apply to an unconfirmed report that an event was canceled?"},"options":[{"id":"m18-V1-999b4cac00","text":{"zh":"核对主办方通知","en":"Check the organiser’s notice"},"feedback":{"zh":"核对主办方是否正式通知，可以补充判断活动是否取消的依据。","en":"Checking the organizer’s notice provides grounds to assess cancellation."}},{"id":"m18-V1-d32126413d","text":{"zh":"因为担心就当已取消","en":"Treat worry as confirmation"},"feedback":{"zh":"担心取消只是自己的感受，没有增加活动确已取消的证据。","en":"Worry supplies no evidence that cancellation has occurred."}}],"correct":"m18-V1-999b4cac00"},"summary":{"zh":"月亮关注信息不清、想象、恐惧和感受对判断的影响。它提醒分开已经知道的事实与尚未证实的猜测，不等于所有人都在欺骗你。","en":"The Moon concerns unclear information, imagination, fear and feelings influencing judgment. Separate known facts from unverified guesses; it does not mean everyone is deceiving you."},"cards":["m18"]},{"id":"m19","kind":"card","level":"I","title":{"zh":"太阳","en":"The Sun"},"teachings":[{"zh":"太阳关注清晰、活力、开放表达与可以看见的喜悦。它支持认识已取得的进展，但不能保证所有困难永远消失。","en":"The Sun concerns clarity, vitality, openness and visible joy. Recognise progress without assuming all difficulties vanish forever."},{"zh":"明亮太阳下，孩子骑白马，后方有向日葵。明亮与开放姿态帮助记住清楚和活力；不能直接推出获奖或财富数额。","en":"A child rides a white horse beneath a bright sun, with sunflowers behind. Brightness and openness recall clarity and vitality, not an award or a sum of money."},{"zh":"关键词：清晰、活力、喜悦、坦诚。可以高兴地表达进展，也要说清实际做到了什么。","en":"Remember: clarity, vitality, joy, honesty. Celebrate progress while accurately stating what has been achieved."}],"application":{"zh":"建议位：项目已经完成可展示版本，却一直不敢介绍。用清楚的话展示真实成果，分享进展并接受反馈，不夸大还没有的功能。","en":"Advice: a project has a demonstrable version, but you hesitate to present it. Show real progress clearly and welcome feedback, without exaggerating unfinished features."},"reversal":{"zh":"逆位示例：已经进步，却只盯着缺点而感受不到成就。这里关注明明有进步，却高兴不起来、也缺少自信的情况，不等于进展完全不存在。","en":"Reversed example: progress exists but focusing only on flaws blocks satisfaction. This concerns reduced joy or confidence, not the absence of all progress."},"visual":{"zh":"明亮太阳下，孩子骑白马，后方有向日葵。明亮与开放姿态帮助记住清楚和活力；不能直接推出获奖或财富数额。","en":"A child rides a white horse beneath a bright sun, with sunflowers behind. Brightness and openness recall clarity and vitality, not an award or a sum of money."},"questions":{"Q1":{"id":"m19-Q1","prompt":{"zh":"本课讲的太阳，主要表达什么？","en":"What does the Sun mainly express in this lesson?"},"options":[{"id":"m19-Q1-f3bdef439c","text":{"zh":"此后再无任何困难","en":"No difficulties ever again"},"feedback":{"zh":"本课肯定已经看见的进展与喜悦，没有保证以后所有困难都消失。","en":"The lesson recognizes progress and joy without guaranteeing a difficulty-free future."}},{"id":"m19-Q1-1caae74dde","text":{"zh":"清晰、活力与喜悦","en":"Clarity, vitality and joy"},"feedback":{"zh":"清楚看见成果、有活力地表达并感受喜悦，符合刚才的讲解。","en":"Recognizing results, expressing vitality and experiencing joy match the teaching."}}],"correct":"m19-Q1-1caae74dde","support":"R1"},"Q2":{"id":"m19-Q2","prompt":{"zh":"项目已有可以展示的版本，怎样介绍它符合刚才的建议？","en":"How should the available project version be presented in the example?"},"options":[{"id":"m19-Q2-bf925b5c99","text":{"zh":"清楚介绍已有真实成果","en":"Clearly present actual progress"},"feedback":{"zh":"真实成果已经可以展示，清楚介绍它既坦诚，也让进展被看见。","en":"Presenting actual work clearly is honest and makes progress visible."}},{"id":"m19-Q2-7280ffce3c","text":{"zh":"宣称未完成功能也已完成","en":"Claim unfinished features are finished"},"feedback":{"zh":"尚未完成却说已完成，是夸大结果，不是坦诚表达。","en":"Calling unfinished work complete exaggerates results rather than expressing them honestly."}}],"correct":"m19-Q2-bf925b5c99","support":"R2"},"Q3":{"id":"m19-Q3","prompt":{"zh":"明明已有进步，却只看到缺点。在这个逆位例子里，需要检查什么？","en":"What should be examined when real progress exists but only flaws are noticed?"},"options":[{"id":"m19-Q3-6b59553885","text":{"zh":"一切努力是否必定无效","en":"Whether all effort must be worthless"},"feedback":{"zh":"例子已经说明有进步，不能因为不满意就把全部努力说成无效。","en":"Progress is explicitly given; dissatisfaction does not erase all effort."}},{"id":"m19-Q3-440fa08cb3","text":{"zh":"被忽略的实际进展","en":"Actual progress being overlooked"},"feedback":{"zh":"先核对哪些已经进步，才有机会看见被缺点遮住的成就。","en":"Identifying progress can reveal achievements obscured by attention to flaws."}}],"correct":"m19-Q3-440fa08cb3","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"清楚展示，要说出已经做成什么，也说清还有什么没做完。积极表达不等于夸大成果。","en":"Clear presentation states both achievements and unfinished work. Positive expression does not mean exaggerating results."}],"question":{"id":"m19-R1","prompt":{"zh":"清楚介绍作品时，要说清哪些部分还没完成吗？","en":"Should a clear presentation state which parts remain unfinished?"},"options":[{"id":"m19-R1-107319b8b3","text":{"zh":"包含","en":"Yes"},"feedback":{"zh":"说清做成了什么、还缺什么，别人才能准确了解作品。","en":"Stating both completed and unfinished parts gives an accurate account."}},{"id":"m19-R1-ab0106d8d3","text":{"zh":"不包含，只讲好处","en":"No; mention only positives"},"feedback":{"zh":"只讲好处而不说尚未完成的部分，会让人误解实际成果。","en":"Omitting unfinished parts may misrepresent the actual result."}}],"correct":"m19-R1-107319b8b3"}},"R2":{"teach":[{"zh":"已有成果才拿出来分享；展示真实进展与宣布完美是两回事。","en":"Share what exists. Showing progress differs from claiming perfection."}],"question":{"id":"m19-R2","prompt":{"zh":"展示真实成果与宣称完美一样吗？","en":"Is showing progress claiming perfection?"},"options":[{"id":"m19-R2-9dc5c0158d","text":{"zh":"一样","en":"Yes"},"feedback":{"zh":"有值得分享的进步，并不等于每一处都已经完美。","en":"Progress worth sharing does not establish perfection in every part."}},{"id":"m19-R2-c891dd7027","text":{"zh":"不一样","en":"No"},"feedback":{"zh":"可以真实展示已完成的部分，同时承认仍有地方需要改进。","en":"Completed work can be shared while acknowledging further improvements."}}],"correct":"m19-R2-c891dd7027"}},"R3":{"teach":[{"zh":"不能感受成就与没有成就是两件事；先确认已做成的具体部分。","en":"Not feeling achievement differs from having none. Identify what has actually been achieved."}],"question":{"id":"m19-R3","prompt":{"zh":"已经有进步，却仍不满意，可以先怎样做？","en":"What can come first when progress exists but satisfaction is missing?"},"options":[{"id":"m19-R3-178bd3cc05","text":{"zh":"核对具体已完成部分","en":"Identify specific completed work"},"feedback":{"zh":"列出实际做成的部分，能让评价不只停留在对缺点的不满意。","en":"Identifying completed work broadens attention beyond dissatisfaction with flaws."}},{"id":"m19-R3-a91737510a","text":{"zh":"否认全部进展","en":"Deny all progress"},"feedback":{"zh":"否认全部进展与例子中已经发生的改善不一致。","en":"Denying all progress contradicts the improvements explicitly given."}}],"correct":"m19-R3-178bd3cc05"}}},"revisit":{"id":"m19-V1","prompt":{"zh":"终于能完整弹一首曲子，怎样运用太阳的含义？","en":"How can the Sun apply after playing a whole piece successfully?"},"options":[{"id":"m19-V1-870c732b7f","text":{"zh":"宣布以后不用练习","en":"Declare further practice unnecessary"},"feedback":{"zh":"这一次能完整弹奏，是一项进步，不等于以后已经没有需要学习的地方。","en":"Playing a full piece is progress, not the end of future learning."}},{"id":"m19-V1-e3fe6ef059","text":{"zh":"看见进步并坦然分享","en":"Recognise progress and share openly"},"feedback":{"zh":"承认确实取得的进步并分享，符合本课的喜悦与坦诚表达。","en":"Recognizing and sharing real progress expresses joy and openness."}}],"correct":"m19-V1-e3fe6ef059"},"summary":{"zh":"太阳关注清晰、活力、开放表达与可以看见的喜悦。它支持认识已取得的进展，但不能保证所有困难永远消失。","en":"The Sun concerns clarity, vitality, openness and visible joy. Recognise progress without assuming all difficulties vanish forever."},"cards":["m19"]},{"id":"m20","kind":"card","level":"I","title":{"zh":"审判","en":"Judgement"},"teachings":[{"zh":"审判表达回看经历后终于想明白了：有些事情不能再照旧，需要重新作决定。重点是把看清的问题用到下一次选择中，不是等别人评判自己，也不是反复责备过去的自己。","en":"Judgement represents understanding gained by reviewing experience: some things need a new decision. Apply what you learned to the next choice rather than awaiting others’ judgment or repeatedly blaming your past self."},{"zh":"号角响起，人物抬头伸臂。听到号角后抬头的姿态，可以帮助记住发现问题后作出回应；画面不是现实法律裁决。","en":"A trumpet sounds and figures rise with lifted arms. Call and response support remembering awareness followed by action, not a real legal verdict."},{"zh":"关键词：想明白了、回顾、重新决定、重新开始。回看过去，是为了知道下一步怎样选择。","en":"Remember: realization, review, renewed decision, starting again. Review the past to understand your next choice."}],"application":{"zh":"建议位：反复接下不适合的合作，终于看清共同问题。找出这些合作为什么都不适合，想清楚今后选合作时要注意什么，再决定是否接受新邀请。","en":"Advice: repeated unsuitable collaborations reveal recurring problems. Identify what made them unsuitable and what to check next time before accepting a new invitation."},"reversal":{"zh":"逆位示例：已经发现自己总在重复同样的问题，却因为不想面对而拖延决定。这里要留意看清问题后仍不愿作决定的情况，不意味着永远没有重新选择的机会。","en":"Reversed example: a recurring problem is recognized, but a decision is delayed to avoid facing it. Notice reluctance to decide after understanding; this does not remove every future chance to choose."},"visual":{"zh":"号角响起，人物抬头伸臂。听到号角后抬头的姿态，可以帮助记住发现问题后作出回应；画面不是现实法律裁决。","en":"A trumpet sounds and figures rise with lifted arms. Call and response support remembering awareness followed by action, not a real legal verdict."},"questions":{"Q1":{"id":"m20-Q1","prompt":{"zh":"审判为什么提醒我们回想过去的经历？","en":"Why does Judgement encourage us to look back at past experiences?"},"options":[{"id":"m20-Q1-b6459644ed","text":{"zh":"想清楚问题后重新作决定","en":"Make a new decision after understanding the issue"},"feedback":{"zh":"想明白过去哪里出了问题，再改变下一次选择，才把回顾用到了行动上。","en":"Understanding past problems and changing the next choice puts review into action."}},{"id":"m20-Q1-052d9cea1f","text":{"zh":"永远责备自己","en":"Blame yourself forever"},"feedback":{"zh":"反复责备没有说明下一次怎样选，也没有改变原来的做法。","en":"Repeated blame neither guides the next choice nor changes the old approach."}}],"correct":"m20-Q1-b6459644ed","support":"R1"},"Q2":{"id":"m20-Q2","prompt":{"zh":"接下的合作总是不适合自己。按照刚才的示范，下一次收到邀请时怎样做？","en":"Repeated collaborations have been unsuitable. How should the next invitation be handled?"},"options":[{"id":"m20-Q2-a32a55519c","text":{"zh":"只说后悔，仍照旧接受","en":"Express regret and accept as before"},"feedback":{"zh":"嘴上后悔但仍照旧接受，就又重复了已经发现的问题。","en":"Regret followed by the same acceptance repeats the recognized problem."}},{"id":"m20-Q2-ce6cd46e22","text":{"zh":"想清楚选合作要注意什么，再判断新邀请","en":"Clarify what to look for before assessing a new invitation"},"feedback":{"zh":"先知道哪些条件不适合自己，再检查新邀请，才用到了过去的经验。","en":"Identifying unsuitable conditions before assessing the invitation uses past experience."}}],"correct":"m20-Q2-ce6cd46e22","support":"R2"},"Q3":{"id":"m20-Q3","prompt":{"zh":"已经看清反复出现的问题，却一直拖着不决定。这个逆位例子卡在哪里？","en":"What is stuck when a recurring problem is understood but a decision is delayed?"},"options":[{"id":"m20-Q3-5b0be35d37","text":{"zh":"看见问题后回避决定","en":"Avoid deciding after recognition"},"feedback":{"zh":"例子已经看清问题，拖住的是接下来不愿作决定这一步。","en":"Understanding is already present; unwillingness to make the next decision is the obstacle."}},{"id":"m20-Q3-461fd41e2d","text":{"zh":"完全没有任何信息","en":"Having no information at all"},"feedback":{"zh":"例子明确说已经发现共同问题，不是完全没有信息。","en":"The example explicitly identifies a recurring problem, so information is not absent."}}],"correct":"m20-Q3-5b0be35d37","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"回看经历，是为了知道下次怎样选择。只责备自己，却仍然照旧作决定，还没有把发现的问题用起来。","en":"Reviewing experience should inform the next choice. Blame followed by the same decisions does not apply what you discovered."}],"question":{"id":"m20-R1","prompt":{"zh":"按照本课讲的审判，只责备自己就够了吗？","en":"According to Judgement as taught here, is blaming yourself enough?"},"options":[{"id":"m20-R1-dfe02f2016","text":{"zh":"够了，越自责就说明想得越透彻","en":"Yes; more self-blame means a more thorough understanding"},"feedback":{"zh":"自责有多痛苦，不能说明之后会怎样选择，也不能替代新的决定。","en":"The pain of blame does not establish a different next choice or replace a decision."}},{"id":"m20-R1-9721047946","text":{"zh":"不够，还要根据想明白的事，重新作决定","en":"No; use what you have understood to make a new decision"},"feedback":{"zh":"还需要让下一次选择有所改变，才把回顾的发现实际用起来。","en":"A changed next choice is needed to apply what review revealed."}}],"correct":"m20-R1-9721047946"}},"R2":{"teach":[{"zh":"先找出过去几次合作为什么不合适，把这些原因变成下次选择时要检查的事项，再看新邀请是否适合。","en":"Identify why past collaborations were unsuitable, turn those reasons into checks for the next choice, and assess the new invitation."}],"question":{"id":"m20-R2","prompt":{"zh":"回顾怎样影响新合作？","en":"How can review affect a new collaboration?"},"options":[{"id":"m20-R2-7254761c59","text":{"zh":"用明确标准检查是否适合","en":"Check suitability against clear criteria"},"feedback":{"zh":"检查新合作是否又有过去的问题，能让之前的经验真正影响选择。","en":"Checking for previous problems lets experience inform the new choice."}},{"id":"m20-R2-6d939c4c70","text":{"zh":"把全部合作一概否定","en":"Reject every collaboration equally"},"feedback":{"zh":"过去几次不合适，没有证明所有合作都不适合自己。","en":"Several unsuitable collaborations do not establish that all collaboration is unsuitable."}}],"correct":"m20-R2-7254761c59"}},"R3":{"teach":[{"zh":"例子里已经看清了问题，困难是还不愿决定接下来怎么办。需要继续作选择，而不是否认刚才已经发现的事。","en":"The problem is already understood in this example. The difficulty is choosing what to do next, not lack of recognition; do not deny what has been learned."}],"question":{"id":"m20-R3","prompt":{"zh":"已经看清问题后，怎样避免一直停在原处？","en":"After understanding the issue, how can you avoid remaining stuck?"},"options":[{"id":"m20-R3-031fb9a255","text":{"zh":"否认刚才看见的问题","en":"Deny the recognised issue"},"feedback":{"zh":"否认已经看清的问题，会重新回到不愿面对它的状态。","en":"Denying a recognized problem returns to avoidance."}},{"id":"m20-R3-74f1560112","text":{"zh":"作一个与认识相符的决定","en":"Make a decision consistent with the insight"},"feedback":{"zh":"根据刚才的发现决定下一步，才从知道问题走到处理问题。","en":"Choosing the next step based on the insight moves from recognizing to addressing the problem."}}],"correct":"m20-R3-74f1560112"}}},"revisit":{"id":"m20-V1","prompt":{"zh":"发现自己每次备考都拖到最后，怎样运用审判的含义？","en":"How can Judgement apply to repeatedly delaying exam preparation?"},"options":[{"id":"m20-V1-13523a9852","text":{"zh":"发现总在拖延，就提前安排下一次备考","en":"Recognize the repeated delay and plan the next exam preparation earlier"},"feedback":{"zh":"发现总是拖延后提前安排，让下一次做法不同，符合回顾后重新决定。","en":"Planning earlier after recognizing delay changes the next action and applies renewed choice."}},{"id":"m20-V1-b6eaf97321","text":{"zh":"只给自己贴失败标签","en":"Only label yourself a failure"},"feedback":{"zh":"失败标签没有说明下一次如何备考，仍没有改变原来的安排。","en":"A failure label supplies no new study plan and leaves the previous arrangement unchanged."}}],"correct":"m20-V1-13523a9852"},"summary":{"zh":"审判表达回看经历后终于想明白了：有些事情不能再照旧，需要重新作决定。重点是把看清的问题用到下一次选择中，不是等别人评判自己，也不是反复责备过去的自己。","en":"Judgement represents understanding gained by reviewing experience: some things need a new decision. Apply what you learned to the next choice rather than awaiting others’ judgment or repeatedly blaming your past self."},"cards":["m20"]},{"id":"m21","kind":"card","level":"I","title":{"zh":"世界","en":"The World"},"teachings":[{"zh":"世界代表这一阶段圆满完成：各部分分别做好，也合在一起，形成了完整成果。它可以带来告一段落的满足，但不意味着以后再也不用学习。","en":"The World represents fulfillment at the end of a phase: completed parts combine into a whole result. It can bring satisfaction without ending all future learning."},{"zh":"人物位于花环内，四角有形象围绕。闭合的花环与周围的形象，可以帮助记住各部分合成一个整体；不表示世界上所有愿望都完成。","en":"A figure stands within a wreath, surrounded by four corner figures. The enclosing form supports completion and integration, not fulfilment of every wish."},{"zh":"关键词：完成、完整、圆满、告一段落。先弄清楚完成的是哪一段事情。","en":"Remember: completion, wholeness, fulfillment, closure. First identify which phase is complete."}],"application":{"zh":"建议位：作品各部分已经做出，但还没合成可以提交的完整作品。把各部分组合好、检查并提交，完成这段工作的最后几步。","en":"Advice: parts of a project exist but are not yet assembled for submission. Combine, check and submit them to complete the final steps of this phase."},"reversal":{"zh":"逆位示例：大部分内容完成，但最后的检查和提交迟迟没做。这里关注还有最后的收尾工作没做，不是把所有成果归零。","en":"Reversed example: most work is done, but final checks and submission remain. This concerns unfinished closure, not erasing all achievement."},"visual":{"zh":"人物位于花环内，四角有形象围绕。闭合的花环与周围的形象，可以帮助记住各部分合成一个整体；不表示世界上所有愿望都完成。","en":"A figure stands within a wreath, surrounded by four corner figures. The enclosing form supports completion and integration, not fulfilment of every wish."},"questions":{"Q1":{"id":"m21-Q1","prompt":{"zh":"世界的完成指什么？","en":"What does the World’s completion refer to?"},"options":[{"id":"m21-Q1-0cdc7135bf","text":{"zh":"今后再也不用学习","en":"No future learning is needed"},"feedback":{"zh":"完成的是当前这一段任务，不能扩大成以后再也不需要学习。","en":"Completion concerns this phase, not an end to all future learning."}},{"id":"m21-Q1-f643bdcd19","text":{"zh":"这一阶段形成了完整成果","en":"This phase has produced a complete result"},"feedback":{"zh":"各部分合成完整成果，这一阶段才真正告一段落。","en":"Combining the parts into a complete result brings this phase to a close."}}],"correct":"m21-Q1-f643bdcd19","support":"R1"},"Q2":{"id":"m21-Q2","prompt":{"zh":"作品的各部分已经做好，却还没组合成完整作品。怎样运用世界在建议位的含义？","en":"How does the World in advice apply when completed parts have not yet been assembled?"},"options":[{"id":"m21-Q2-514e954561","text":{"zh":"组合各部分、检查并提交","en":"Assemble the parts, check and submit"},"feedback":{"zh":"把各部分组合好并检查、提交，正是在完成案例里还没做的步骤。","en":"Assembly, checking and submission address the steps still missing in the example."}},{"id":"m21-Q2-a73ae3b184","text":{"zh":"各部分有了，就说整份作品已经提交","en":"Declare the whole project submitted merely because its parts exist"},"feedback":{"zh":"各部分虽然都有了，但还没组成完整作品，也没有提交。","en":"The parts exist, but the complete work has not been assembled or submitted."}}],"correct":"m21-Q2-514e954561","support":"R2"},"Q3":{"id":"m21-Q3","prompt":{"zh":"大部分内容已完成，但最后检查和提交没做。这个逆位例子说明什么？","en":"What does the reversal example show when most work is done but final checks and submission remain?"},"options":[{"id":"m21-Q3-c466c91beb","text":{"zh":"所有成果完全无效","en":"All work is worthless"},"feedback":{"zh":"还没提交不能抹掉前面已经完成的工作，只说明最后仍有步骤没做。","en":"Missing submission does not erase finished work; it identifies remaining steps."}},{"id":"m21-Q3-407fb76735","text":{"zh":"有收尾环节未完成","en":"Closure remains unfinished"},"feedback":{"zh":"背景明确缺少最后检查与提交，因此需要补上收尾。","en":"Final checks and submission are explicitly missing, so closure remains necessary."}}],"correct":"m21-Q3-407fb76735","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"各部分分别做好以后，还要组合成一份符合要求的完整成果。例如作品的各部分都有了，也需要检查它们能否接在一起，才算完成。","en":"Finished parts must be combined into a whole that meets the requirements. Check how the parts of a project connect before calling it complete."}],"question":{"id":"m21-R1","prompt":{"zh":"作品的各部分都有了，就自动算完成整个任务了吗？","en":"Do existing parts automatically mean that the whole task is complete?"},"options":[{"id":"m21-R1-059b676fbb","text":{"zh":"不，还要组合好并完成任务要求","en":"No, assemble them properly and meet the task requirements"},"feedback":{"zh":"部分分别做好，还要能组合起来并满足任务要求，才形成完整成果。","en":"Finished parts must work together and meet requirements to form a complete result."}},{"id":"m21-R1-e2a121a4c5","text":{"zh":"是，不用检查连接","en":"Yes; connections need no checking"},"feedback":{"zh":"没有检查各部分怎样接起来，不能确认整个作品已经完成。","en":"Without checking how the parts connect, the whole work cannot be considered complete."}}],"correct":"m21-R1-059b676fbb"}},"R2":{"teach":[{"zh":"建议位是在问怎样做，所以这里讲的是把作品组合好、检查并提交。放在结果位时，才是讨论这段工作能否走向完成。","en":"The advice position asks what to do, so it calls for assembly, checking and submission. In an outcome position, the question is whether the work is heading toward completion."}],"question":{"id":"m21-R2","prompt":{"zh":"世界放在建议位，为什么这里要讲怎样完成并提交作品？","en":"Why does the World in advice discuss completing and submitting the work?"},"options":[{"id":"m21-R2-102530985e","text":{"zh":"它已证明未来必定成功","en":"It proves future success"},"feedback":{"zh":"建议是告诉你眼前可以怎样做，不是证明未来结果已经确定。","en":"Advice concerns what can be done now, not proof of a fixed future result."}},{"id":"m21-R2-9716b32d56","text":{"zh":"它要回答怎样完成","en":"It answers how to complete"},"feedback":{"zh":"这个牌位问的是怎样做，因此要把完成转成可以执行的最后几步。","en":"This position asks what to do, so completion becomes the concrete final steps."}}],"correct":"m21-R2-9716b32d56"}},"R3":{"teach":[{"zh":"还差收尾时，要找出最后哪一步没做，不代表前面完成的部分都没有价值。","en":"Unfinished closure calls for finding the missing final step; it does not make earlier work worthless."}],"question":{"id":"m21-R3","prompt":{"zh":"最后还没收尾时，先找什么？","en":"What should be identified when closure is unfinished?"},"options":[{"id":"m21-R3-7c9bce26d7","text":{"zh":"最后还有哪一步没做","en":"Which final step remains unfinished"},"feedback":{"zh":"找出最后缺少的检查或提交，既承认已有成果，也知道接下来补什么。","en":"Identifying remaining checks or submission recognizes existing work and the next step."}},{"id":"m21-R3-c862cf6d7d","text":{"zh":"理由证明全部努力没用","en":"Reasons all effort was useless"},"feedback":{"zh":"例子说的是最后一步没做，不是之前的努力都没有用。","en":"The example identifies unfinished closure, not worthless prior effort."}}],"correct":"m21-R3-7c9bce26d7"}}},"revisit":{"id":"m21-V1","prompt":{"zh":"一次展览已经完整结束，怎样运用世界的含义回看它？","en":"How can the World apply when reflecting on a completed exhibition?"},"options":[{"id":"m21-V1-538cb05412","text":{"zh":"认定以后所有展览都必然成功","en":"Assume every future exhibition will succeed"},"feedback":{"zh":"这次展览完成，只能说明这次的成果，不能保证以后每次都成功。","en":"This exhibition’s completion establishes its result, not guaranteed success for every future exhibition."}},{"id":"m21-V1-de5fc54a51","text":{"zh":"整理成果并确认本阶段完成","en":"Gather the outcomes and acknowledge completion"},"feedback":{"zh":"整理这次的成果、确认它已告一段落，符合本课的完成与圆满。","en":"Gathering this event’s results and recognizing its completion fits the taught wholeness."}}],"correct":"m21-V1-de5fc54a51"},"summary":{"zh":"世界代表这一阶段圆满完成：各部分分别做好，也合在一起，形成了完整成果。它可以带来告一段落的满足，但不意味着以后再也不用学习。","en":"The World represents fulfillment at the end of a phase: completed parts combine into a whole result. It can bring satisfaction without ending all future learning."},"cards":["m21"]},{"id":"w01","kind":"card","level":"I","title":{"zh":"权杖王牌","en":"Ace of Wands"},"teachings":[{"zh":"有了新灵感，也有了想开始做点什么的热情。 权杖刚长出新芽，可以用来记住“刚开始”。有了灵感，还得继续做下去，才会有成果。","en":"A fresh impulse or creative idea offers an opening for action. It is a beginning to explore, not a finished or guaranteed project."},{"zh":"云中伸出一只手，握着长出新芽的权杖。用这根刚发芽的权杖，记住新出现的创意和干劲。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A hand emerging from a cloud holds a sprouting wand: the shoots help recall a new impulse. This is a visual association for learning, not proof of an external event."},{"zh":"灵感、启动。 权杖对应火元素，可以联想行动的热情与创造力；王牌强调新开始，还不是成熟的成果。","en":"inspiration; beginning. Wands relate to fire: action and creation. An Ace suggests emergence, not maturity."}],"application":{"zh":"示范：有了手工产品的灵感，先做一个小样看看能否实现。先做一个小样，才能看看想法能不能实现；如果一直等所有条件齐备，就迟迟没有开始。","en":"Example: test a craft idea with a small prototype. This lesson turns fresh energy into a small trial; waiting for every condition postpones that start."},"reversal":{"zh":"案例：原来想做短片，但一直没有安排第一次拍摄。这里的逆位，是想开始却卡住了。可以先拍一个做得到的场景，不必因此认定整个作品会失败。","en":"Case: a short-film idea has never reached a first filming session. Here the reversal means a blocked start; find one achievable starting action, rather than declaring permanent failure."},"visual":{"zh":"云中伸出一只手，握着长出新芽的权杖。用这根刚发芽的权杖，记住新出现的创意和干劲。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A hand emerging from a cloud holds a sprouting wand: the shoots help recall a new impulse. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w01-Q1","prompt":{"zh":"发芽的权杖，可以帮助记住什么？","en":"What do the shoots help us remember?"},"options":[{"id":"w01-Q1-e2e6f3d8aa","text":{"zh":"有了新的创作灵感，很想试一试","en":"A creative impulse is emerging"},"feedback":{"zh":"权杖刚长出新芽，可以用来记住“刚开始”。有了灵感，还得继续做下去，才会有成果。","en":"Shoots connect to a beginning; completion requires later action and is not established here."}},{"id":"w01-Q1-b7dc35d096","text":{"zh":"整个创作已经完成","en":"The whole creation is finished"},"feedback":{"zh":"权杖刚长出新芽，可以用来记住“刚开始”。有了灵感，还得继续做下去，才会有成果。","en":"Shoots connect to a beginning; completion requires later action and is not established here."}}],"correct":"w01-Q1-e2e6f3d8aa","support":"R1"},"Q2":{"id":"w01-Q2","prompt":{"zh":"想写一个短篇故事，已经有了灵感。权杖王牌在建议位，哪种做法更合适？","en":"You have an idea for a short story. With the Ace of Wands as advice, which next step fits?"},"options":[{"id":"w01-Q2-daf66e6be0","text":{"zh":"等所有章节都完美确定才动笔","en":"Wait until every chapter is perfectly settled"},"feedback":{"zh":"先做一个小样，才能看看想法能不能实现；如果一直等所有条件齐备，就迟迟没有开始。","en":"This lesson turns fresh energy into a small trial; waiting for every condition postpones that start."}},{"id":"w01-Q2-c9a828ec93","text":{"zh":"先写一个场景，试出方向","en":"Draft one scene to test a direction"},"feedback":{"zh":"先做一个小样，才能看看想法能不能实现；如果一直等所有条件齐备，就迟迟没有开始。","en":"This lesson turns fresh energy into a small trial; waiting for every condition postpones that start."}}],"correct":"w01-Q2-c9a828ec93","support":"RA"},"Q3":{"id":"w01-Q3","prompt":{"zh":"在短片迟迟没有第一次拍摄的案例里，逆位解释是哪一个？","en":"In the case with no first filming session, which reversed reading fits?"},"options":[{"id":"w01-Q3-9dc2af4bcf","text":{"zh":"想开始却迟迟没动手，需要先找到做得到的一步","en":"The start is blocked; identify what enables it"},"feedback":{"zh":"短片还没开始拍，所以这里的问题是怎样迈出第一步，不是拍好了等别人赞赏。","en":"The case explicitly has not started; this reversal concerns starting difficulty, not recognition after completion."}},{"id":"w01-Q3-cac76ee8f5","text":{"zh":"已有成片，只差接受掌声","en":"A finished film only awaits applause"},"feedback":{"zh":"短片还没开始拍，所以这里的问题是怎样迈出第一步，不是拍好了等别人赞赏。","en":"The case explicitly has not started; this reversal concerns starting difficulty, not recognition after completion."}}],"correct":"w01-Q3-9dc2af4bcf","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"现在有了想法，也有机会动手，但还要一步步做下去。能够开始，不等于已经成功。 记住：有了新的创作灵感，很想试一试，不是“整个创作已经完成”。","en":"A beginning means an opening for action; results still need further effort. Separate an opportunity to start from a guarantee of success. Compare: A creative impulse is emerging; this cannot be replaced by “The whole creation is finished”."}],"question":{"id":"w01-R1","prompt":{"zh":"想到做一个阳台花园，刚画了第一张草图。这是开始还是成果保证？","en":"a balcony-garden idea has its first sketch. Is this a start or a guarantee?"},"options":[{"id":"w01-R1-7ab255eac1","text":{"zh":"花园一定会成功的保证","en":"A guarantee the garden will succeed"},"feedback":{"zh":"有了草图，就有机会开始布置；能不能成为花园，还得看后面的种植和照料。","en":"An idea offers an opening; the garden still depends on later conditions."}},{"id":"w01-R1-db1ac6539c","text":{"zh":"有了新想法，可以开始试一试","en":"A new opening worth trying"},"feedback":{"zh":"有了草图，就有机会开始布置；能不能成为花园，还得看后面的种植和照料。","en":"An idea offers an opening; the garden still depends on later conditions."}}],"correct":"w01-R1-db1ac6539c"}},"RA":{"teach":[{"zh":"不用第一次就把整个作品做完。先做个小样试试，看看想法行不行。可以继续计划，但总要有一次真正动手。","en":"A starting exercise need not finish the entire work. Make one small, inspectable result to test whether the idea merits development; planning should not indefinitely replace action."}],"question":{"id":"w01-RA","prompt":{"zh":"想尝试设计桌游，已经知道基本玩法，下一步怎样应用权杖王牌？","en":"A board-game idea already has basic rules. How can Ace of Wands advice apply next?"},"options":[{"id":"w01-RA-0d9edd091b","text":{"zh":"用纸片做一轮可试玩的小样。","en":"Make a paper prototype for one playable round."},"feedback":{"zh":"已经有了基本规则，就能做一个纸上版本试着玩。继续扩大设想却不试玩，仍然不知道游戏能不能玩起来。","en":"Starting conditions exist; a prototype makes the impulse testable, while more imagining still postpones practice."}},{"id":"w01-RA-67d9a42a75","text":{"zh":"继续只设想完整上市方案，不作任何试玩。","en":"Keep imagining a full launch without any trial."},"feedback":{"zh":"已经有了基本规则，就能做一个纸上版本试着玩。继续扩大设想却不试玩，仍然不知道游戏能不能玩起来。","en":"“Keep imagining a full launch without any trial.” does not address the specific conditions. Starting conditions exist; a prototype makes the impulse testable, while more imagining still postpones practice."}}],"correct":"w01-RA-0d9edd091b"}},"R2":{"teach":[{"zh":"先完成一个做得到的小步骤，才算真正开始；只换一种说法，事情仍然没有往前走。 题目描述的是“想开始却迟迟没动手，需要先找到做得到的一步”，不是“已有成片，只差接受掌声”。","en":"A feasible first action addresses the blocked start; relabelling the situation does not create action. Return to the stated context: “The start is blocked; identify what enables it” fits this case; “A finished film only awaits applause” is unsupported by that context."}],"question":{"id":"w01-R2","prompt":{"zh":"迟迟没拍短片，因为不知道先拍什么。先做什么，才能开始拍？","en":"You have delayed filming because you do not know which scene to start with. What can you do first to get filming?"},"options":[{"id":"w01-R2-9fa34e74b9","text":{"zh":"选一个容易拍的场景安排试拍","en":"Choose one manageable scene and schedule a trial"},"feedback":{"zh":"先完成一个做得到的小步骤，才算真正开始；只换一种说法，事情仍然没有往前走。","en":"A feasible first action addresses the blocked start; relabelling the situation does not create action."}},{"id":"w01-R2-b4a9dbd828","text":{"zh":"把迟迟没拍当成已经完成","en":"Treat the delay as if the film were complete"},"feedback":{"zh":"先完成一个做得到的小步骤，才算真正开始；只换一种说法，事情仍然没有往前走。","en":"A feasible first action addresses the blocked start; relabelling the situation does not create action."}}],"correct":"w01-R2-9fa34e74b9"}}},"revisit":{"id":"w01-V1","prompt":{"zh":"想开发新菜式，突然有一个搭配灵感。哪句最贴近这张牌的主题？","en":"a new flavour combination sparks an idea. Which fits this card?"},"options":[{"id":"w01-V1-a52958a385","text":{"zh":"无需试做就已证明适合开店","en":"It already proves a restaurant will succeed"},"feedback":{"zh":"有了新菜的想法，可以先做一份试试；这还不能说明以后开店的经营结果。","en":"Fresh inspiration supports a small start, not proof of a long-term business outcome."}},{"id":"w01-V1-2703198544","text":{"zh":"先试做一道菜，看看效果","en":"Make one trial dish to begin exploring"},"feedback":{"zh":"有了新菜的想法，可以先做一份试试；这还不能说明以后开店的经营结果。","en":"Fresh inspiration supports a small start, not proof of a long-term business outcome."}}],"correct":"w01-V1-2703198544"},"summary":{"zh":"有了新灵感，也有了想开始做点什么的热情。 权杖刚长出新芽，可以用来记住“刚开始”。有了灵感，还得继续做下去，才会有成果。","en":"A fresh impulse or creative idea offers an opening for action. It is a beginning to explore, not a finished or guaranteed project."},"cards":["w01"]},{"id":"w02","kind":"card","level":"I","title":{"zh":"权杖二","en":"Two of Wands"},"teachings":[{"zh":"已经有了一定基础，正在规划下一步去哪里发展。 人物向远处看，可以帮助记住“正在规划”。想好了去哪里，不等于已经在那里取得成果。","en":"With some ground already established, consider where to expand next. The emphasis is on choosing a direction and planning, before that wider venture is achieved."},{"zh":"人物站在城墙上，拿着地球仪望向远方。城墙可以帮助记住已有的基础，远望则对应下一步的打算。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A figure on a battlement holds a globe and looks outward, connecting a present base with possibilities beyond it. This is a visual association for learning, not proof of an external event."},{"zh":"规划、选择、远景。 权杖对应火元素，帮助记住想向外发展的热情；数字二在这张牌里帮助记住比较和选择，但不是每张二号牌都在讲二选一。","en":"planning; choice; outlook. Fire supports initiative; here two aids recall of choice and weighing directions, not a universal formula for every Two."}],"application":{"zh":"示范：已有本地客户，先比较两个外地市场。还没决定怎样发展，就先比较各个方向。现在有了打算，不等于已经成功开展了新活动。","en":"Example: compare two new markets after establishing local clients. Choose a direction and examine the base first; an unexamined option is not an achieved expansion."},"reversal":{"zh":"案例：已有稳定作品集，想接触外地客户，但因为不敢离开熟悉渠道而一直不做调查。这里的逆位，是因为害怕走出熟悉范围，迟迟没有规划下一步。","en":"Case: an established portfolio could reach clients elsewhere, but fear of unfamiliar channels prevents research. Here the reversal focuses on planning stalled by reluctance."},"visual":{"zh":"人物站在城墙上，拿着地球仪望向远方。城墙可以帮助记住已有的基础，远望则对应下一步的打算。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A figure on a battlement holds a globe and looks outward, connecting a present base with possibilities beyond it. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w02-Q1","prompt":{"zh":"人物拿着地球仪望向远方，对应哪种状态？","en":"Holding the globe and looking outward helps recall which stage?"},"options":[{"id":"w02-Q1-1a1938bcc2","text":{"zh":"已经收获外部拓展成果","en":"Already harvesting the expansion's results"},"feedback":{"zh":"人物向远处看，可以帮助记住“正在规划”。想好了去哪里，不等于已经在那里取得成果。","en":"Looking outward aids planning; the lesson does not turn a plan into an achieved result."}},{"id":"w02-Q1-6dc7688735","text":{"zh":"已经有了一定基础，正在考虑下一步去哪里发展","en":"Planning expansion from an existing base"},"feedback":{"zh":"人物向远处看，可以帮助记住“正在规划”。想好了去哪里，不等于已经在那里取得成果。","en":"Looking outward aids planning; the lesson does not turn a plan into an achieved result."}}],"correct":"w02-Q1-6dc7688735","support":"R1"},"Q2":{"id":"w02-Q2","prompt":{"zh":"社团已有固定活动，想去其他校区发展。权杖二在建议位，下一步更适合做什么？","en":"An established club wants to expand to other campuses. With the Two of Wands as advice, what fits next?"},"options":[{"id":"w02-Q2-b699ba686e","text":{"zh":"先看看要面向哪些人、需要什么条件，再决定去哪里发展","en":"Compare audiences and resources before choosing a direction"},"feedback":{"zh":"还没决定怎样发展，就先比较各个方向。现在有了打算，不等于已经成功开展了新活动。","en":"Choose a direction and examine the base first; an unexamined option is not an achieved expansion."}},{"id":"w02-Q2-31117423bb","text":{"zh":"把尚未比较的方向直接记作成功","en":"Record an unexamined direction as a success"},"feedback":{"zh":"还没决定怎样发展，就先比较各个方向。现在有了打算，不等于已经成功开展了新活动。","en":"Choose a direction and examine the base first; an unexamined option is not an achieved expansion."}}],"correct":"w02-Q2-b699ba686e","support":"RA"},"Q3":{"id":"w02-Q3","prompt":{"zh":"在因害怕陌生渠道而拒绝调查的案例里，逆位重点是什么？","en":"In the case of refusing research out of fear, what does the reversal emphasise?"},"options":[{"id":"w02-Q3-7243ac2abc","text":{"zh":"新市场已经带来确定收益","en":"The new market has already produced definite returns"},"feedback":{"zh":"题目说的是因为害怕陌生渠道而迟迟不调查，计划还没往前走，更谈不上已经从新市场获利。","en":"The stated issue is stalled planning, not evidence of returns from a new market."}},{"id":"w02-Q3-f7bcfe1c6d","text":{"zh":"只敢留在熟悉的范围，不敢考虑下一步","en":"The familiar comfort zone is constraining planning"},"feedback":{"zh":"题目说的是因为害怕陌生渠道而迟迟不调查，计划还没往前走，更谈不上已经从新市场获利。","en":"The stated issue is stalled planning, not evidence of returns from a new market."}}],"correct":"w02-Q3-f7bcfe1c6d","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"正在比较去哪里，说明还在规划。有没有完成，要看事情实际做到哪一步。 记住：已经有了一定基础，正在考虑下一步去哪里发展，不是“已经收获外部拓展成果”。","en":"Comparing directions is planning; completion would need separate evidence. Compare: Planning expansion from an existing base; this cannot be replaced by “Already harvesting the expansion's results”."}],"question":{"id":"w02-R1","prompt":{"zh":"已经掌握一门技能，正在比较两个发展方向。哪项是当前状态？","en":"one skill is established and two directions are being compared. What describes the present?"},"options":[{"id":"w02-R1-48c62ff816","text":{"zh":"评估下一步向哪里发展","en":"Assessing where to go next"},"feedback":{"zh":"正在比较去哪里，说明还在规划。有没有完成，要看事情实际做到哪一步。","en":"Comparing directions is planning; completion would need separate evidence."}},{"id":"w02-R1-7f58ec63ea","text":{"zh":"两个方向的目标都已完成","en":"Both directions have already been completed"},"feedback":{"zh":"正在比较去哪里，说明还在规划。有没有完成，要看事情实际做到哪一步。","en":"Comparing directions is planning; completion would need separate evidence."}}],"correct":"w02-R1-48c62ff816"}},"RA":{"teach":[{"zh":"想向外发展，先比较各个方向需要什么条件、自己已经具备什么。这样比较，是为了决定下一步去哪里。","en":"Planning compares possible directions against real conditions. Comparison is not delay: goals, requirements, and the existing base help determine where to expand."}],"question":{"id":"w02-RA","prompt":{"zh":"已有稳定线上课程，想开线下工作坊，还不清楚场地与受众。下一步是什么？","en":"An established online course may expand into workshops, but venue needs and audience are unclear. What comes next?"},"options":[{"id":"w02-RA-b023c5faff","text":{"zh":"不比较就把开办成功写入总结。","en":"Record successful expansion without comparing requirements."},"feedback":{"zh":"还没弄清场地要求和学员需要什么，就要先调查、比较，不能把想办活动当成已经办成功了。","en":"“Record successful expansion without comparing requirements.” does not address the specific conditions. Unsettled conditions call for an informed direction, not treating intention as achievement."}},{"id":"w02-RA-05168dee8c","text":{"zh":"先比较场地要求与目标学员，再决定形式。","en":"Compare venue requirements and target learners before choosing a format."},"feedback":{"zh":"还没弄清场地要求和学员需要什么，就要先调查、比较，不能把想办活动当成已经办成功了。","en":"Unsettled conditions call for an informed direction, not treating intention as achievement."}}],"correct":"w02-RA-05168dee8c"}},"R2":{"teach":[{"zh":"先调查，才知道新方向需要什么条件。现在不熟悉或不敢尝试，不等于客观上做不到。 题目描述的是“只敢留在熟悉的范围，不敢考虑下一步”，不是“新市场已经带来确定收益”。","en":"Research gives planning a basis; fear and unfamiliarity do not establish impossibility. Return to the stated context: “The familiar comfort zone is constraining planning” fits this case; “The new market has already produced definite returns” is unsupported by that context."}],"question":{"id":"w02-R2","prompt":{"zh":"想尝试远程合作，却因为不熟悉而一直不敢了解。先做什么更合适？","en":"You want to try remote collaboration but unfamiliarity keeps you from learning about it. What can you do first?"},"options":[{"id":"w02-R2-8c1615264a","text":{"zh":"把不了解直接当成永远不可能","en":"Treat unfamiliarity as permanent impossibility"},"feedback":{"zh":"先调查，才知道新方向需要什么条件。现在不熟悉或不敢尝试，不等于客观上做不到。","en":"Research gives planning a basis; fear and unfamiliarity do not establish impossibility."}},{"id":"w02-R2-a66e20a3cb","text":{"zh":"先查清合作条件，再决定是否拓展","en":"Research its conditions before deciding whether to expand"},"feedback":{"zh":"先调查，才知道新方向需要什么条件。现在不熟悉或不敢尝试，不等于客观上做不到。","en":"Research gives planning a basis; fear and unfamiliarity do not establish impossibility."}}],"correct":"w02-R2-a66e20a3cb"}}},"revisit":{"id":"w02-V1","prompt":{"zh":"咖啡店已有稳定客源，想开课程但尚未决定形式。哪句贴近主题？","en":"a café has regular customers and is considering classes. Which fits?"},"options":[{"id":"w02-V1-a10fc4360b","text":{"zh":"在现有基础上，比较接下来做什么更合适","en":"Use the current base to compare next directions"},"feedback":{"zh":"店里已有稳定客源，但还没决定课程怎么办，所以现在是在规划，不是庆祝课程已经办完。","en":"An existing base plus an undecided direction fits planning, not celebrating completion."}},{"id":"w02-V1-8246944862","text":{"zh":"课程已经成功，进入庆功阶段","en":"The classes have succeeded and it is time to celebrate"},"feedback":{"zh":"店里已有稳定客源，但还没决定课程怎么办，所以现在是在规划，不是庆祝课程已经办完。","en":"An existing base plus an undecided direction fits planning, not celebrating completion."}}],"correct":"w02-V1-a10fc4360b"},"summary":{"zh":"已经有了一定基础，正在规划下一步去哪里发展。 人物向远处看，可以帮助记住“正在规划”。想好了去哪里，不等于已经在那里取得成果。","en":"With some ground already established, consider where to expand next. The emphasis is on choosing a direction and planning, before that wider venture is achieved."},"cards":["w02"]},{"id":"w03","kind":"card","level":"I","title":{"zh":"权杖三","en":"Three of Wands"},"teachings":[{"zh":"已经迈出向外发展的第一步，正在关注合作、外部机会和接下来的进展。 这里已经采取了行动，接下来是等待回应、观察进展，不是还停留在想象中。","en":"An initiative has already reached outward. Watch how it develops, follow up connections, and prepare for the next stage of expansion."},{"zh":"人物身边立着三根权杖，目光望向海上的船只。可以借这个画面记住：已经迈出一步，正在看事情接下来怎样发展。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A figure looks toward ships at sea beside three wands, helping recall an outward venture and attention to its progress. This is a visual association for learning, not proof of an external event."},{"zh":"向外拓展、跟进消息。 权杖对应火元素，强调主动行动；三在这里帮助记住已经开始向外发展。海上的船可以辅助记忆，但不能据此认定一定是海外贸易。","en":"outward expansion; following responses. Fire aids outward initiative; three here recalls early development, but the ships do not establish literal overseas trade or dates."}],"application":{"zh":"示范：寄出合作提案后跟进回复。等消息的时候，也可以跟进进度、做好下一步准备，不必什么都不做。","en":"Example: follow up after sending a partnership proposal. Watching for a response includes follow-up and preparation, not disengaging from development."},"reversal":{"zh":"案例：提案已经发出，对方反馈却比预计晚。这里的逆位，是事情开始后进展变慢了。可以查清对方是否收到、还有什么要求，不必把回复晚了当成一定失败。","en":"Case: a proposal has been sent but the response is late. Here the reversal means delay during expansion; check communication and conditions without equating delay with certain failure."},"visual":{"zh":"人物身边立着三根权杖，目光望向海上的船只。可以借这个画面记住：已经迈出一步，正在看事情接下来怎样发展。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A figure looks toward ships at sea beside three wands, helping recall an outward venture and attention to its progress. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w03-Q1","prompt":{"zh":"权杖三更接近哪一种状态？","en":"Which state is taught for the Three of Wands here?"},"options":[{"id":"w03-Q1-6a46c5cf15","text":{"zh":"已经采取行动，正在关注回应和进展","en":"Action has reached outward and its response is being watched"},"feedback":{"zh":"这里已经采取了行动，接下来是等待回应、观察进展，不是还停留在想象中。","en":"Outward action is already part of this lesson; observation follows that action."}},{"id":"w03-Q1-3f0b03e06c","text":{"zh":"完全没有行动，只在幻想出发","en":"No action has begun; departure is only imagined"},"feedback":{"zh":"这里已经采取了行动，接下来是等待回应、观察进展，不是还停留在想象中。","en":"Outward action is already part of this lesson; observation follows that action."}}],"correct":"w03-Q1-6a46c5cf15","support":"R1"},"Q2":{"id":"w03-Q2","prompt":{"zh":"作品已提交给展览方，正在等回复。权杖三在建议位，下一步更适合做什么？","en":"Your artwork has been submitted to an exhibition and you are awaiting a reply. With the Three of Wands as advice, what fits next?"},"options":[{"id":"w03-Q2-c0748d7a59","text":{"zh":"认为等待就不需要任何准备","en":"Assume waiting requires no preparation"},"feedback":{"zh":"等消息的时候，也可以跟进进度、做好下一步准备，不必什么都不做。","en":"Watching for a response includes follow-up and preparation, not disengaging from development."}},{"id":"w03-Q2-acaf6b5219","text":{"zh":"确认接收情况并准备后续材料","en":"Confirm receipt and prepare follow-up material"},"feedback":{"zh":"等消息的时候，也可以跟进进度、做好下一步准备，不必什么都不做。","en":"Watching for a response includes follow-up and preparation, not disengaging from development."}}],"correct":"w03-Q2-acaf6b5219","support":"RA"},"Q3":{"id":"w03-Q3","prompt":{"zh":"提案发出后回复延迟，这张逆位牌提醒了什么？","en":"A proposal has been sent and the response is late. What does this reversal suggest?"},"options":[{"id":"w03-Q3-0dca55cc70","text":{"zh":"事情已经开始，但进展有延迟，需要查清原因","en":"Outward progress is delayed and conditions need checking"},"feedback":{"zh":"提案已经发出，只是回复迟迟没来。因此要跟进进度，不是认定自己从未行动。","en":"The proposal was explicitly sent; the difficulty occurs during its progress."}},{"id":"w03-Q3-2c1e78cc0b","text":{"zh":"从未发出任何提案","en":"No proposal was ever sent"},"feedback":{"zh":"提案已经发出，只是回复迟迟没来。因此要跟进进度，不是认定自己从未行动。","en":"The proposal was explicitly sent; the difficulty occurs during its progress."}}],"correct":"w03-Q3-0dca55cc70","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"产品已经交给合作方了，现在要看试用反馈、商量下一步，不能再说成还没开始行动。 记住：已经采取行动，正在关注回应和进展，不是“完全没有行动，只在幻想出发”。","en":"Delivery has occurred, so follow its development rather than describe a venture that never started. Compare: Action has reached outward and its response is being watched; this cannot be replaced by “No action has begun; departure is only imagined”."}],"question":{"id":"w03-R1","prompt":{"zh":"试用产品已经交给合作方，正在等测试回报。此时关注什么？","en":"a prototype has reached a partner and test feedback is pending. What matters now?"},"options":[{"id":"w03-R1-ed5304aed4","text":{"zh":"假装还没有开展任何合作","en":"Act as though no collaboration has begun"},"feedback":{"zh":"产品已经交给合作方了，现在要看试用反馈、商量下一步，不能再说成还没开始行动。","en":"Delivery has occurred, so follow its development rather than describe a venture that never started."}},{"id":"w03-R1-63c1a3a35f","text":{"zh":"看看对方的试用反馈，再商量下一步怎样合作","en":"Test responses and the next collaboration step"},"feedback":{"zh":"产品已经交给合作方了，现在要看试用反馈、商量下一步，不能再说成还没开始行动。","en":"Delivery has occurred, so follow its development rather than describe a venture that never started."}}],"correct":"w03-R1-63c1a3a35f"}},"RA":{"teach":[{"zh":"提案发出只是向外行动的开始。等待回应时，可以确认对方是否收到、了解后续流程，并准备对方可能需要的材料；这不等于催促对方立刻答应。","en":"Sending a proposal begins an outward venture. While awaiting a response, confirm receipt, learn the next steps, and prepare relevant materials; this need not pressure the recipient to agree immediately."}],"question":{"id":"w03-RA","prompt":{"zh":"已经投出展览申请，主办方说稍后需要作品尺寸。现在怎样做？","en":"An exhibition application is submitted and the organiser will need dimensions later. What fits now?"},"options":[{"id":"w03-RA-72f8fbdd80","text":{"zh":"核对作品尺寸并准备补充资料。","en":"Check dimensions and prepare the additional information."},"feedback":{"zh":"展览方已经要求补充作品尺寸，现在就可以核对并准备资料。只是等着、不做准备，可能耽误后续安排。","en":"The venture is in follow-up; preparing required information supports development, while stopping overlooks available work."}},{"id":"w03-RA-81ff9d9fbb","text":{"zh":"因为正在等回复，就停止一切后续准备。","en":"Stop all preparation because a reply is pending."},"feedback":{"zh":"展览方已经要求补充作品尺寸，现在就可以核对并准备资料。只是等着、不做准备，可能耽误后续安排。","en":"“Stop all preparation because a reply is pending.” does not address the specific conditions. The venture is in follow-up; preparing required information supports development, while stopping overlooks available work."}}],"correct":"w03-RA-72f8fbdd80"}},"R2":{"teach":[{"zh":"物流是已知阻碍；运输晚了，并不能说明产品没有价值。 题目描述的是“事情已经开始，但进展有延迟，需要查清原因”，不是“从未发出任何提案”。","en":"Transit is the known obstacle; delay does not establish the product's worth. Return to the stated context: “Outward progress is delayed and conditions need checking” fits this case; “No proposal was ever sent” is unsupported by that context."}],"question":{"id":"w03-R2","prompt":{"zh":"样品迟迟没有送到合作方。怎样处理更合适？","en":"Your samples have not reached the partner on time. Which response fits?"},"options":[{"id":"w03-R2-8d9fe9a1bf","text":{"zh":"查物流并与接收方调整安排","en":"Check transit and coordinate an updated arrangement"},"feedback":{"zh":"物流是已知阻碍；运输晚了，并不能说明产品没有价值。","en":"Transit is the known obstacle; delay does not establish the product's worth."}},{"id":"w03-R2-e3d208dbd5","text":{"zh":"仅凭延迟宣布产品没有价值","en":"Declare the product worthless solely because of the delay"},"feedback":{"zh":"物流是已知阻碍；运输晚了，并不能说明产品没有价值。","en":"Transit is the known obstacle; delay does not establish the product's worth."}}],"correct":"w03-R2-8d9fe9a1bf"}}},"revisit":{"id":"w03-V1","prompt":{"zh":"交换学习申请已经提交，正在安排可能的后续面试。哪句贴近？","en":"an exchange application is submitted and possible interviews are being prepared. Which fits?"},"options":[{"id":"w03-V1-4d7d0dcbef","text":{"zh":"所有结果已确定，无须关注","en":"All outcomes are fixed and need no attention"},"feedback":{"zh":"申请已经交出，下一步可以准备可能的面试；这不代表已经确定入选。","en":"Submission and preparation show follow-up after action, not a predetermined outcome."}},{"id":"w03-V1-5d5a7c2d0a","text":{"zh":"已经递交申请，继续了解后续机会","en":"Action is underway; follow the external opportunity"},"feedback":{"zh":"申请已经交出，下一步可以准备可能的面试；这不代表已经确定入选。","en":"Submission and preparation show follow-up after action, not a predetermined outcome."}}],"correct":"w03-V1-5d5a7c2d0a"},"summary":{"zh":"已经迈出向外发展的第一步，正在关注合作、外部机会和接下来的进展。 这里已经采取了行动，接下来是等待回应、观察进展，不是还停留在想象中。","en":"An initiative has already reached outward. Watch how it develops, follow up connections, and prepare for the next stage of expansion."},"cards":["w03"]},{"id":"w04","kind":"card","level":"I","title":{"zh":"权杖四","en":"Four of Wands"},"teachings":[{"zh":"一起做成了一件事，暂时安定下来，也能感受到相聚和庆祝的喜悦。 庆祝的是这一阶段已经取得的成果，不是说以后的事情都已经完成、不会再有变化。","en":"A stage has reached a stable, shared achievement. Acknowledge the milestone and enjoy belonging or celebration without assuming every future goal is finished."},{"zh":"四根权杖上有花环，人物在其后举花，呈现庆祝的场景。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Four wands carry a garland, with people raising flowers behind them: a visible setting of communal celebration. This is a visual association for learning, not proof of an external event."},{"zh":"阶段成果、安定、一起庆祝。 权杖的行动在这里有了阶段成果；四帮助记住暂时安定下来，而不是以后永远不会变化。","en":"milestone; stability; shared celebration. Fire-led action reaches a milestone; four aids recall of a stable frame, not a life without change."}],"application":{"zh":"示范：首场演出结束，团队一起庆祝并休整。第一个作品已经完成，大家可以为它高兴。不用等所有长期目标都达成，才允许庆祝。","en":"Example: celebrate and rest after a first performance. A milestone may be recognised without waiting for every long-term goal."},"reversal":{"zh":"案例：活动已完成，但团队成员尚未感到被接纳，庆祝安排也推迟。这里的逆位，提醒的是大家还没感到被接纳、得到支持。","en":"Case: an event is complete, but members do not feel included and celebration is postponed. Here the reversal concerns shared support that has not settled."},"visual":{"zh":"四根权杖上有花环，人物在其后举花，呈现庆祝的场景。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Four wands carry a garland, with people raising flowers behind them: a visible setting of communal celebration. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w04-Q1","prompt":{"zh":"这张牌里的庆祝，主要是在为什么而高兴？","en":"What does celebration mainly mean?"},"options":[{"id":"w04-Q1-1c6f7fa55d","text":{"zh":"所有目标从此永久完成","en":"Every goal is permanently complete"},"feedback":{"zh":"庆祝的是这一阶段已经取得的成果，不是说以后的事情都已经完成、不会再有变化。","en":"This is stability and celebration at a milestone, not a guarantee about all future goals."}},{"id":"w04-Q1-31a8976045","text":{"zh":"一起庆祝已经做成的事","en":"Celebrate what has been accomplished together"},"feedback":{"zh":"庆祝的是这一阶段已经取得的成果，不是说以后的事情都已经完成、不会再有变化。","en":"This is stability and celebration at a milestone, not a guarantee about all future goals."}}],"correct":"w04-Q1-31a8976045","support":"R1"},"Q2":{"id":"w04-Q2","prompt":{"zh":"课程小组完成了第一个作品。权杖四在建议位，哪种做法更合适？","en":"Your study group has completed its first project. With the Four of Wands as advice, which response fits?"},"options":[{"id":"w04-Q2-69b1bfb610","text":{"zh":"一起庆祝成果，也休息一下","en":"Acknowledge the achievement together and take a short rest"},"feedback":{"zh":"第一个作品已经完成，大家可以为它高兴。不用等所有长期目标都达成，才允许庆祝。","en":"A milestone may be recognised without waiting for every long-term goal."}},{"id":"w04-Q2-a24e50068a","text":{"zh":"认为全部人生目标完成之前，这次成果都不值得庆祝","en":"Deny any achievement until every life goal is finished"},"feedback":{"zh":"第一个作品已经完成，大家可以为它高兴。不用等所有长期目标都达成，才允许庆祝。","en":"A milestone may be recognised without waiting for every long-term goal."}}],"correct":"w04-Q2-69b1bfb610","support":"RA"},"Q3":{"id":"w04-Q3","prompt":{"zh":"已完成活动却缺少接纳感，这张逆位牌更贴近哪种情况？","en":"An event is finished but inclusion is missing. What does this reversal concern?"},"options":[{"id":"w04-Q3-ead749f76e","text":{"zh":"活动从未发生","en":"The event never happened"},"feedback":{"zh":"活动确实完成了，但成员还没有觉得自己受到接纳。逆位在这里提醒的是相处中的问题，不是说活动没发生。","en":"The reversal concerns shared support; it does not erase the stated completed event."}},{"id":"w04-Q3-2419a6797b","text":{"zh":"大家还没有感到被接纳、得到支持","en":"Shared support and belonging remain unsettled"},"feedback":{"zh":"活动确实完成了，但成员还没有觉得自己受到接纳。逆位在这里提醒的是相处中的问题，不是说活动没发生。","en":"The reversal concerns shared support; it does not erase the stated completed event."}}],"correct":"w04-Q3-2419a6797b","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"搬进新工作室，让大家暂时安定下来；以后还有新任务，也不影响庆祝这次搬迁。 记住：一起庆祝已经做成的事，不是“所有目标从此永久完成”。","en":"The new space offers a stable milestone; future work may still arise. Compare: Celebrate what has been accomplished together; this cannot be replaced by “Every goal is permanently complete”."}],"question":{"id":"w04-R1","prompt":{"zh":"搬入新工作室后邀请伙伴一起整理和庆祝。主题是什么？","en":"partners organise and celebrate a new studio. What is the theme?"},"options":[{"id":"w04-R1-44b5950ec0","text":{"zh":"为搬进新空间、暂时安定下来而一起庆祝","en":"Sharing an achieved point of stability"},"feedback":{"zh":"搬进新工作室，让大家暂时安定下来；以后还有新任务，也不影响庆祝这次搬迁。","en":"The new space offers a stable milestone; future work may still arise."}},{"id":"w04-R1-2cdce2d64d","text":{"zh":"证明以后再无任何困难","en":"Proving no difficulty will ever return"},"feedback":{"zh":"搬进新工作室，让大家暂时安定下来；以后还有新任务，也不影响庆祝这次搬迁。","en":"The new space offers a stable milestone; future work may still arise."}}],"correct":"w04-R1-44b5950ec0"}},"RA":{"teach":[{"zh":"一起庆祝已经做成的事，让大家知道各自的付出被记得，也休息一下。以后还有任务，也不影响为这次成果高兴。","en":"Celebrate what you have accomplished together, let everyone know their effort is appreciated, and take a rest. Future tasks do not stop you from enjoying this achievement."}],"question":{"id":"w04-RA","prompt":{"zh":"合唱团完成第一次公开演出，但下月还有演出。怎样应用权杖四建议？","en":"A choir finishes its first public performance, with another next month. What fits Four of Wands advice?"},"options":[{"id":"w04-RA-484cede0a0","text":{"zh":"因为还有下一场，就否认这次值得庆祝。","en":"Deny this milestone deserves celebration because another remains."},"feedback":{"zh":"这次演出已经完成，值得庆祝；下月还有演出，并不会抹去这次的成果。","en":"“Deny this milestone deserves celebration because another remains.” does not address the specific conditions. A milestone and future tasks can coexist; celebrating now does not declare everything finished."}},{"id":"w04-RA-185aad6126","text":{"zh":"一起庆祝这次演出，休息一下再准备下一场。","en":"Celebrate this performance, take a short rest, then prepare for the next one."},"feedback":{"zh":"这次演出已经完成，值得庆祝；下月还有演出，并不会抹去这次的成果。","en":"A milestone and future tasks can coexist; celebrating now does not declare everything finished."}}],"correct":"w04-RA-185aad6126"}},"R2":{"teach":[{"zh":"让大家参与庆祝、感谢各自的付出，才会让人觉得自己是其中一员。场面热闹，不代表每个人都被照顾到了。 题目描述的是“大家还没有感到被接纳、得到支持”，不是“活动从未发生”。","en":"Belonging needs participation and recognition, not merely a festive appearance. Return to the stated context: “Shared support and belonging remain unsettled” fits this case; “The event never happened” is unsupported by that context."}],"question":{"id":"w04-R2","prompt":{"zh":"庆功时只邀请了负责人，其他出过力的伙伴都被漏掉了。怎样做更合适？","en":"Only the organiser was invited to celebrate, leaving out the other contributors. What would be a better response?"},"options":[{"id":"w04-R2-714f518848","text":{"zh":"照旧不邀请他们，认为他们已经觉得自己被接纳了","en":"Leave them uninvited and assume they already feel included"},"feedback":{"zh":"让大家参与庆祝、感谢各自的付出，才会让人觉得自己是其中一员。场面热闹，不代表每个人都被照顾到了。","en":"Belonging needs participation and recognition, not merely a festive appearance."}},{"id":"w04-R2-d8ff8e8bcf","text":{"zh":"感谢每位伙伴的付出，邀请他们一起庆祝","en":"Recognise contributors and include them in celebration"},"feedback":{"zh":"让大家参与庆祝、感谢各自的付出，才会让人觉得自己是其中一员。场面热闹，不代表每个人都被照顾到了。","en":"Belonging needs participation and recognition, not merely a festive appearance."}}],"correct":"w04-R2-d8ff8e8bcf"}}},"revisit":{"id":"w04-V1","prompt":{"zh":"一家人完成搬家，准备一起吃顿饭感谢彼此。哪句贴近？","en":"a household finishes moving and shares a meal in thanks. Which fits?"},"options":[{"id":"w04-V1-d65f7e5a1a","text":{"zh":"庆祝搬家完成，一起开始新的生活","en":"Celebrate a shared life milestone"},"feedback":{"zh":"搬家终于完成了，可以一起吃饭庆祝。以后还会有别的事情要做，不是所有任务都结束了。","en":"Completing the move supports a milestone celebration, not lifelong completion."}},{"id":"w04-V1-a6fec093b2","text":{"zh":"已经完成所有终身任务","en":"Every lifetime task is finished"},"feedback":{"zh":"搬家终于完成了，可以一起吃饭庆祝。以后还会有别的事情要做，不是所有任务都结束了。","en":"Completing the move supports a milestone celebration, not lifelong completion."}}],"correct":"w04-V1-d65f7e5a1a"},"summary":{"zh":"一起做成了一件事，暂时安定下来，也能感受到相聚和庆祝的喜悦。 庆祝的是这一阶段已经取得的成果，不是说以后的事情都已经完成、不会再有变化。","en":"A stage has reached a stable, shared achievement. Acknowledge the milestone and enjoy belonging or celebration without assuming every future goal is finished."},"cards":["w04"]},{"id":"w05","kind":"card","level":"I","title":{"zh":"权杖五","en":"Five of Wands"},"teachings":[{"zh":"大家都想按自己的想法做，意见彼此冲突，还没有配合起来。 几个人挥杖的方向不同，可以用来记住竞争和配合不足。有分歧，不等于彼此仇恨。","en":"Several people or forces are pushing their ideas at once, before coordination is established. Competition can reveal differences that need workable rules."},{"zh":"多人各举权杖，动作方向不一，帮助记住竞争与缺少配合。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"People lift wands in differing directions; their lack of coordinated movement helps recall competing efforts. This is a visual association for learning, not proof of an external event."},{"zh":"竞争、意见分歧、协调不足、磨合。 权杖对应行动，五在这里帮助记住竞争和分歧。争着表达、缺少配合，不等于彼此仇恨，也不能据此认定有暴力。","en":"competition; disagreement; poor coordination; working things out. Wands express colliding initiatives here; five aids recall of disruption, not proof of hatred or actual violence."}],"application":{"zh":"示范：项目争论先统一目标和发言规则。先说清共同目标，再轮流把意见讲完，才有机会商量出做法。禁止大家说话，并不会让分歧自动消失。","en":"Example: agree on goals and speaking rules during project disagreement. Coordination gives disagreement a channel; banning expression does not create cooperation."},"reversal":{"zh":"案例：团队表面不争论，却各做各的，未讨论的分歧继续拖慢工作。这里的逆位，是不肯谈分歧，结果彼此牵制、事情做不下去。","en":"Case: a team avoids open argument but works at cross-purposes. Here the reversal means unaddressed disagreement draining effort."},"visual":{"zh":"多人各举权杖，动作方向不一，帮助记住竞争与缺少配合。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"People lift wands in differing directions; their lack of coordinated movement helps recall competing efforts. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w05-Q1","prompt":{"zh":"多人动作不一，帮助记住哪个主题？","en":"What do the different directions help recall?"},"options":[{"id":"w05-Q1-0d4fb809b3","text":{"zh":"大家各说各的，还没配合起来","en":"Multiple efforts have not been coordinated"},"feedback":{"zh":"几个人挥杖的方向不同，可以用来记住竞争和配合不足。有分歧，不等于彼此仇恨。","en":"The cue is uncoordinated effort, not proof that participants hate one another."}},{"id":"w05-Q1-0cc6c801c8","text":{"zh":"所有人已达成一致并配合","en":"Everyone has agreed and is cooperating"},"feedback":{"zh":"几个人挥杖的方向不同，可以用来记住竞争和配合不足。有分歧，不等于彼此仇恨。","en":"The cue is uncoordinated effort, not proof that participants hate one another."}}],"correct":"w05-Q1-0d4fb809b3","support":"R1"},"Q2":{"id":"w05-Q2","prompt":{"zh":"运动社团讨论训练安排时，大家各说各的，讨论不下去。权杖五在建议位，哪种做法更合适？","en":"Members of a sports club are discussing training but talk over one another and cannot move forward. With the Five of Wands as advice, what fits?"},"options":[{"id":"w05-Q2-9d8e8eb908","text":{"zh":"要求所有分歧永远不能提出","en":"Forbid every disagreement permanently"},"feedback":{"zh":"先说清共同目标，再轮流把意见讲完，才有机会商量出做法。禁止大家说话，并不会让分歧自动消失。","en":"Coordination gives disagreement a channel; banning expression does not create cooperation."}},{"id":"w05-Q2-2b80093fe0","text":{"zh":"先明确训练目标和讨论顺序","en":"Clarify the training goal and discussion order"},"feedback":{"zh":"先说清共同目标，再轮流把意见讲完，才有机会商量出做法。禁止大家说话，并不会让分歧自动消失。","en":"Coordination gives disagreement a channel; banning expression does not create cooperation."}}],"correct":"w05-Q2-2b80093fe0","support":"RA"},"Q3":{"id":"w05-Q3","prompt":{"zh":"在表面不吵却各做各的案例里，这张逆位牌更贴近哪种情况？","en":"In the apparently quiet but divided team, what does this reversal mean?"},"options":[{"id":"w05-Q3-d81d338c3a","text":{"zh":"不肯谈分歧，结果事情一直做不下去","en":"Avoiding disagreement sustains internal friction"},"feedback":{"zh":"大家虽然不吵了，还是各做各的，工作照样被耽误。安静下来，不等于已经配合好了。","en":"The work is still slowed by disagreement; silence is not coordination."}},{"id":"w05-Q3-35f7f2266b","text":{"zh":"没有争吵就证明合作顺利","en":"No argument proves smooth cooperation"},"feedback":{"zh":"大家虽然不吵了，还是各做各的，工作照样被耽误。安静下来，不等于已经配合好了。","en":"The work is still slowed by disagreement; silence is not coordination."}}],"correct":"w05-Q3-d81d338c3a","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"几个人抢着说话，说明还没商量好怎么配合，不能因此认定他们一直互相仇恨。 记住：大家各说各的，还没配合起来，不是“所有人已达成一致并配合”。","en":"Talking over one another supports poor coordination, not certain enduring hatred. Compare: Multiple efforts have not been coordinated; this cannot be replaced by “Everyone has agreed and is cooperating”."}],"question":{"id":"w05-R1","prompt":{"zh":"三位同学同时抢着讲各自方案，任务没人统筹。主要问题是什么？","en":"three students push plans at once and nobody coordinates. What is central?"},"options":[{"id":"w05-R1-14b9601eea","text":{"zh":"可以确定他们彼此憎恨","en":"Their hatred of one another is certain"},"feedback":{"zh":"几个人抢着说话，说明还没商量好怎么配合，不能因此认定他们一直互相仇恨。","en":"Talking over one another supports poor coordination, not certain enduring hatred."}},{"id":"w05-R1-1ba378c361","text":{"zh":"需要先听完彼此的想法，再商量怎么配合","en":"Expression and action need coordination"},"feedback":{"zh":"几个人抢着说话，说明还没商量好怎么配合，不能因此认定他们一直互相仇恨。","en":"Talking over one another supports poor coordination, not certain enduring hatred."}}],"correct":"w05-R1-1ba378c361"}},"RA":{"teach":[{"zh":"大家意见不同时，先说清要一起做成什么，再轮流把想法讲完、比较不同方案。不让人说话，并不会解决分歧。","en":"When views collide, clarify the shared task and how people will express and compare ideas. Coordination handles disagreement rather than requiring permanent silence."}],"question":{"id":"w05-RA","prompt":{"zh":"三位成员对活动流程各有主张，会议一直互相打断。哪项针对协调问题？","en":"Three members propose different event plans and keep interrupting each other. What addresses coordination?"},"options":[{"id":"w05-RA-eae987e5e9","text":{"zh":"先确定活动目标，再让每人完整说明方案。","en":"Agree on the event goal and let each person explain a proposal."},"feedback":{"zh":"先知道要做什么，再听完每个人的方案，才好商量。禁止别人提不同意见，只是把问题藏起来。","en":"Goals and speaking rules support cooperation; banning disagreement merely hides unresolved issues."}},{"id":"w05-RA-a84e4d0d93","text":{"zh":"规定不许再提不同意见，直接结束讨论。","en":"Ban differing views and immediately end discussion."},"feedback":{"zh":"先知道要做什么，再听完每个人的方案，才好商量。禁止别人提不同意见，只是把问题藏起来。","en":"“Ban differing views and immediately end discussion.” does not address the specific conditions. Goals and speaking rules support cooperation; banning disagreement merely hides unresolved issues."}}],"correct":"w05-RA-eae987e5e9"}},"R2":{"teach":[{"zh":"各自照原来的做法做，问题就还在。需要把任务和分歧说清楚，而不只是停止争吵。 题目描述的是“不肯谈分歧，结果事情一直做不下去”，不是“没有争吵就证明合作顺利”。","en":"Visible coordination is missing; silence has not removed the disagreement. Return to the stated context: “Avoiding disagreement sustains internal friction” fits this case; “No argument proves smooth cooperation” is unsupported by that context."}],"question":{"id":"w05-R2","prompt":{"zh":"大家不敢谈分工，结果重复做了同样的工作。怎样做更合适？","en":"People avoid discussing roles and end up duplicating work. What would help?"},"options":[{"id":"w05-R2-c83fec4776","text":{"zh":"把不同意见和分工摆出来讨论","en":"Discuss differing views and responsibilities"},"feedback":{"zh":"各自照原来的做法做，问题就还在。需要把任务和分歧说清楚，而不只是停止争吵。","en":"Visible coordination is missing; silence has not removed the disagreement."}},{"id":"w05-R2-d6420a33db","text":{"zh":"继续避谈，认定问题已经消失","en":"Keep avoiding discussion and call the problem solved"},"feedback":{"zh":"各自照原来的做法做，问题就还在。需要把任务和分歧说清楚，而不只是停止争吵。","en":"Visible coordination is missing; silence has not removed the disagreement."}}],"correct":"w05-R2-c83fec4776"}}},"revisit":{"id":"w05-V1","prompt":{"zh":"几个社区小组都想优先使用同一场地。哪项建议贴近？","en":"several community groups want the same venue first. Which advice fits?"},"options":[{"id":"w05-V1-4f28acca90","text":{"zh":"凭有竞争就断言所有人心怀恶意","en":"Infer malicious intent solely from competition"},"feedback":{"zh":"几个小组都想用同一场地，需要商量规则，不能只因竞争就认定大家都怀有恶意。","en":"Competition calls for coordination and does not establish malicious motives."}},{"id":"w05-V1-5f2e31cebb","text":{"zh":"一起商量使用规则，让不同小组都能说明需要","en":"Use shared rules to coordinate competing demands"},"feedback":{"zh":"几个小组都想用同一场地，需要商量规则，不能只因竞争就认定大家都怀有恶意。","en":"Competition calls for coordination and does not establish malicious motives."}}],"correct":"w05-V1-5f2e31cebb"},"summary":{"zh":"大家都想按自己的想法做，意见彼此冲突，还没有配合起来。 几个人挥杖的方向不同，可以用来记住竞争和配合不足。有分歧，不等于彼此仇恨。","en":"Several people or forces are pushing their ideas at once, before coordination is established. Competition can reveal differences that need workable rules."},"cards":["w05"]},{"id":"w06","kind":"card","level":"I","title":{"zh":"权杖六","en":"Six of Wands"},"teachings":[{"zh":"努力有了成果，也得到别人的肯定，因此更有信心。 桂冠和周围的人群，可以帮助记住受到肯定、获得荣誉。它与“努力始终无人认可”不是同一个意思。","en":"An achievement becomes visible and receives recognition from others. Enjoy the confidence it brings while remembering that recognition is not permanent superiority."},{"zh":"戴桂冠的人骑马穿过人群，权杖上也有花环。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A laurel-crowned rider moves among people, with a wreath on the wand: these details aid recall of publicly recognised achievement. This is a visual association for learning, not proof of an external event."},{"zh":"获得成果、得到肯定、自信。 火的行动获得回应；这里的六可以帮助记住成果得到肯定，不把每张六都读成获奖。","en":"visible achievement; recognition; confidence. Action associated with fire gains a response; six here aids recognition, not a rule that every Six means winning an award."}],"application":{"zh":"示范：作品展示获肯定后庆祝，也继续改进。得到肯定，可以更有信心；但下一次仍要练习，不能认定获奖后就一直领先。","en":"Example: celebrate praise for a presentation and keep improving. Recognition supports confidence; it does not prove permanent superiority."},"reversal":{"zh":"案例：作品质量不错，却因没有获得预期掌声而全盘否定自己。这里的逆位，是太依赖别人的夸奖，才觉得自己做得好。","en":"Case: good work is dismissed by its maker because applause falls short. Here the reversal focuses on overdependence on external recognition."},"visual":{"zh":"戴桂冠的人骑马穿过人群，权杖上也有花环。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A laurel-crowned rider moves among people, with a wreath on the wand: these details aid recall of publicly recognised achievement. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w06-Q1","prompt":{"zh":"花环和周围的人群，可以帮助记住什么？","en":"What do the wreath and people help recall here?"},"options":[{"id":"w06-Q1-cc54b4365a","text":{"zh":"成果永远不可能被看见","en":"An achievement can never be seen"},"feedback":{"zh":"桂冠和周围的人群，可以帮助记住受到肯定、获得荣誉。它与“努力始终无人认可”不是同一个意思。","en":"The theme is recognition that is present, not permanent invisibility."}},{"id":"w06-Q1-14964e93fb","text":{"zh":"努力做出了成果，也得到别人肯定","en":"An achievement is seen and recognised"},"feedback":{"zh":"桂冠和周围的人群，可以帮助记住受到肯定、获得荣誉。它与“努力始终无人认可”不是同一个意思。","en":"The theme is recognition that is present, not permanent invisibility."}}],"correct":"w06-Q1-14964e93fb","support":"R1"},"Q2":{"id":"w06-Q2","prompt":{"zh":"刚获得一次奖项，很受鼓舞。权杖六在建议位，怎样对待这次成绩更合适？","en":"You have won an award and feel encouraged. With the Six of Wands as advice, how can you respond to this achievement?"},"options":[{"id":"w06-Q2-2ff01e8da2","text":{"zh":"接受肯定并继续练习","en":"Accept recognition and keep practising"},"feedback":{"zh":"得到肯定，可以更有信心；但下一次仍要练习，不能认定获奖后就一直领先。","en":"Recognition supports confidence; it does not prove permanent superiority."}},{"id":"w06-Q2-3e2b225735","text":{"zh":"因获奖认定以后不必学习","en":"Treat the award as ending the need to learn"},"feedback":{"zh":"得到肯定，可以更有信心；但下一次仍要练习，不能认定获奖后就一直领先。","en":"Recognition supports confidence; it does not prove permanent superiority."}}],"correct":"w06-Q2-2ff01e8da2","support":"RA"},"Q3":{"id":"w06-Q3","prompt":{"zh":"因掌声不足就否定所有努力，这张逆位牌更贴近哪种情况？","en":"Rejecting all effort because applause is insufficient illustrates what here?"},"options":[{"id":"w06-Q3-72e0a67440","text":{"zh":"已经不在意任何外部评价","en":"External evaluation no longer matters at all"},"feedback":{"zh":"题目里的人因为点赞少就否定自己，说明他很在意别人的评价，不是完全不在意。","en":"The case is explicitly driven by applause, not independence from recognition."}},{"id":"w06-Q3-23c7c62337","text":{"zh":"太依赖别人夸奖，才觉得自己做得好","en":"Self-evaluation depends too heavily on applause"},"feedback":{"zh":"题目里的人因为点赞少就否定自己，说明他很在意别人的评价，不是完全不在意。","en":"The case is explicitly driven by applause, not independence from recognition."}}],"correct":"w06-Q3-23c7c62337","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"被公开表扬，说明这次的努力得到了肯定，不代表以后一直会胜过所有人。 记住：努力做出了成果，也得到别人肯定，不是“成果永远不可能被看见”。","en":"One instance establishes recognition, not a lifelong ranking. Compare: An achievement is seen and recognised; this cannot be replaced by “An achievement can never be seen”."}],"question":{"id":"w06-R1","prompt":{"zh":"老师公开肯定作品，学生信心增加。可以确认什么主题？","en":"public praise increases a student's confidence. What theme is supported?"},"options":[{"id":"w06-R1-d8ecabfa9d","text":{"zh":"自己的努力得到了别人的肯定","en":"Effort receives external recognition"},"feedback":{"zh":"被公开表扬，说明这次的努力得到了肯定，不代表以后一直会胜过所有人。","en":"One instance establishes recognition, not a lifelong ranking."}},{"id":"w06-R1-c4e9492b5d","text":{"zh":"能力从此永远超过所有人","en":"Ability now permanently exceeds everyone else's"},"feedback":{"zh":"被公开表扬，说明这次的努力得到了肯定，不代表以后一直会胜过所有人。","en":"One instance establishes recognition, not a lifelong ranking."}}],"correct":"w06-R1-d8ecabfa9d"}},"RA":{"teach":[{"zh":"接受认可和继续学习并不矛盾。被表扬可以增加信心，但下一项任务仍有自己的标准；不能用上一次掌声替代后续准备。","en":"Receiving recognition and continuing to learn are compatible. Praise can build confidence, but the next task has its own requirements; past applause does not replace preparation."}],"question":{"id":"w06-RA","prompt":{"zh":"设计作品刚获校内奖，下次项目使用陌生工具。怎样应用权杖六建议？","en":"A design wins a school award, but the next project uses an unfamiliar tool. What fits Six of Wands advice?"},"options":[{"id":"w06-RA-b493184b7e","text":{"zh":"凭获奖认定任何新工具都无需学习。","en":"Assume the award removes any need to learn new tools."},"feedback":{"zh":"奖项肯定的是已有作品，不代表新工具也已经会用了。高兴之余，仍要练习没学过的内容。","en":"“Assume the award removes any need to learn new tools.” does not address the specific conditions. Recognition shows existing work was appreciated, not mastery of unlearned material."}},{"id":"w06-RA-7e7032f726","text":{"zh":"接受肯定，同时为新工具安排练习。","en":"Accept the recognition and practise the unfamiliar tool."},"feedback":{"zh":"奖项肯定的是已有作品，不代表新工具也已经会用了。高兴之余，仍要练习没学过的内容。","en":"Recognition shows existing work was appreciated, not mastery of unlearned material."}}],"correct":"w06-RA-7e7032f726"}},"R2":{"teach":[{"zh":"没有得到很多点赞，也可以看看作品本身是否达到目标。不必只靠别人夸不夸来判断自己。 题目描述的是“太依赖别人夸奖，才觉得自己做得好”，不是“已经不在意任何外部评价”。","en":"The aim is to reduce reliance on applause alone, not intensify it. Return to the stated context: “Self-evaluation depends too heavily on applause” fits this case; “External evaluation no longer matters at all” is unsupported by that context."}],"question":{"id":"w06-R2","prompt":{"zh":"项目本身做得不错，却因为点赞少就想放弃。作决定前，还可以看什么？","en":"The project is good, but few likes make you want to abandon it. What else can you consider before deciding?"},"options":[{"id":"w06-R2-ae60f33930","text":{"zh":"只把点赞数当成全部价值","en":"Use likes as the entire measure of value"},"feedback":{"zh":"没有得到很多点赞，也可以看看作品本身是否达到目标。不必只靠别人夸不夸来判断自己。","en":"The aim is to reduce reliance on applause alone, not intensify it."}},{"id":"w06-R2-6188926a4a","text":{"zh":"回看实际质量与目标，不只看点赞","en":"Review quality and goals as well as likes"},"feedback":{"zh":"没有得到很多点赞，也可以看看作品本身是否达到目标。不必只靠别人夸不夸来判断自己。","en":"The aim is to reduce reliance on applause alone, not intensify it."}}],"correct":"w06-R2-6188926a4a"}}},"revisit":{"id":"w06-V1","prompt":{"zh":"志愿服务受到社区表扬。哪句贴近牌义？","en":"a community praises volunteer service. Which fits?"},"options":[{"id":"w06-V1-fd796b6f2b","text":{"zh":"自己的付出得到肯定，因此更有信心","en":"Contribution is noticed and recognition can build confidence"},"feedback":{"zh":"被表扬说明这次做得到了认可，但以后做新事情，仍可能出错。","en":"Praise corresponds to recognition and does not eliminate possible future mistakes."}},{"id":"w06-V1-964e197e64","text":{"zh":"受到表扬证明以后不会犯错","en":"Praise proves no future mistake is possible"},"feedback":{"zh":"被表扬说明这次做得到了认可，但以后做新事情，仍可能出错。","en":"Praise corresponds to recognition and does not eliminate possible future mistakes."}}],"correct":"w06-V1-fd796b6f2b"},"summary":{"zh":"努力有了成果，也得到别人的肯定，因此更有信心。 桂冠和周围的人群，可以帮助记住受到肯定、获得荣誉。它与“努力始终无人认可”不是同一个意思。","en":"An achievement becomes visible and receives recognition from others. Enjoy the confidence it brings while remembering that recognition is not permanent superiority."},"cards":["w06"]},{"id":"w07","kind":"card","level":"I","title":{"zh":"权杖七","en":"Seven of Wands"},"teachings":[{"zh":"面对挑战或质疑，努力守住已经争取到的位置，坚持重要的立场。 重点是守住真正重要的事。每件小事都要争个输赢，反而会顾不上最该坚持的立场。","en":"Meet challenges by defending a position or boundary already gained. Decide what is worth protecting rather than treating every disagreement as a battle."},{"zh":"人物站在高处抵住下方六根权杖，帮助记住迎接挑战。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A figure on higher ground holds off six lower wands, giving a visible cue for defending a position under challenge. This is a visual association for learning, not proof of an external event."},{"zh":"守住立场、分清哪些立场值得坚持。 火支持坚持行动；七只作本牌位置编号，不用数字推导一定要对抗。","en":"holding a position; selective defence. Fire supports sustained initiative; seven is not a numerical command to oppose others."}],"application":{"zh":"示范：合作中说明不可退让的交付质量。说清哪些要求能接受、哪些不能让步，才能保住重要的工作。全部答应，可能连最关键的任务也做不好。","en":"Example: state a non-negotiable quality boundary. A boundary needs clear expression; accepting everything may sacrifice the priority."},"reversal":{"zh":"案例：为了回应每一句批评，连休息也取消，重要工作反而受影响。这里的逆位，是每次争论都要回应，反而顾不上重要的事。","en":"Case: answering every criticism eliminates rest and harms essential work. Here the reversal focuses on excessive defence losing its priorities."},"visual":{"zh":"人物站在高处抵住下方六根权杖，帮助记住迎接挑战。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A figure on higher ground holds off six lower wands, giving a visible cue for defending a position under challenge. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w07-Q1","prompt":{"zh":"权杖七说的坚持，主要是守住什么？","en":"What does persistence mainly protect?"},"options":[{"id":"w07-Q1-b3941cfd80","text":{"zh":"重要立场和已经争取的位置","en":"An important position or boundary already gained"},"feedback":{"zh":"重点是守住真正重要的事。每件小事都要争个输赢，反而会顾不上最该坚持的立场。","en":"Defence protects priorities; trying to win everything scatters effort."}},{"id":"w07-Q1-e902816d5b","text":{"zh":"每一句小分歧都必须赢","en":"Victory in every minor disagreement"},"feedback":{"zh":"重点是守住真正重要的事。每件小事都要争个输赢，反而会顾不上最该坚持的立场。","en":"Defence protects priorities; trying to win everything scatters effort."}}],"correct":"w07-Q1-b3941cfd80","support":"R1"},"Q2":{"id":"w07-Q2","prompt":{"zh":"社团不断要求你增加任务，已经影响最重要的工作。权杖七在建议位，哪种做法更合适？","en":"Extra club tasks are putting your most important work at risk. With the Seven of Wands as advice, which response fits?"},"options":[{"id":"w07-Q2-c3e25f4c8d","text":{"zh":"为了不被挑战接受所有要求","en":"Accept every demand to avoid being challenged"},"feedback":{"zh":"说清哪些要求能接受、哪些不能让步，才能保住重要的工作。全部答应，可能连最关键的任务也做不好。","en":"A boundary needs clear expression; accepting everything may sacrifice the priority."}},{"id":"w07-Q2-6e4804f986","text":{"zh":"说明能承担的范围并守住重要任务","en":"State capacity and protect the essential work"},"feedback":{"zh":"说清哪些要求能接受、哪些不能让步，才能保住重要的工作。全部答应，可能连最关键的任务也做不好。","en":"A boundary needs clear expression; accepting everything may sacrifice the priority."}}],"correct":"w07-Q2-6e4804f986","support":"RA"},"Q3":{"id":"w07-Q3","prompt":{"zh":"回应所有批评而耽误重要工作，这张逆位牌更贴近哪种情况？","en":"Answering every criticism delays essential work. What does this reversal emphasise?"},"options":[{"id":"w07-Q3-c8d0d3f87e","text":{"zh":"每次争论都要回应，反而顾不上重要的事","en":"Defence loses selectivity and scatters energy"},"feedback":{"zh":"题目说，争论已经耽误了重要工作。每条评论都要反击，反而没有守住最重要的事。","en":"The case says essential work is harmed; excessive defence is not effective protection."}},{"id":"w07-Q3-101a38e49d","text":{"zh":"已经有效保护最重要的工作","en":"The most important work is already protected effectively"},"feedback":{"zh":"题目说，争论已经耽误了重要工作。每条评论都要反击，反而没有守住最重要的事。","en":"The case says essential work is harmed; excessive defence is not effective protection."}}],"correct":"w07-Q3-c8d0d3f87e","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"先分清哪些原则不能让步，哪些小争执可以放下，不必每件事都争到底。 记住：重要立场和已经争取的位置，不是“每一句小分歧都必须赢”。","en":"The lesson distinguishes priorities rather than escalating every dispute equally. Compare: An important position or boundary already gained; this cannot be replaced by “Victory in every minor disagreement”."}],"question":{"id":"w07-R1","prompt":{"zh":"朋友误解一句无关紧要的话，与合作底线相比该怎样分配精力？","en":"how should a minor verbal misunderstanding compare with an essential partnership boundary?"},"options":[{"id":"w07-R1-e651711864","text":{"zh":"把两件事都当成必须决战","en":"Treat both as battles that must be won"},"feedback":{"zh":"先分清哪些原则不能让步，哪些小争执可以放下，不必每件事都争到底。","en":"The lesson distinguishes priorities rather than escalating every dispute equally."}},{"id":"w07-R1-595675772e","text":{"zh":"优先说明并守住真正重要的底线","en":"Prioritise the genuinely important boundary"},"feedback":{"zh":"先分清哪些原则不能让步，哪些小争执可以放下，不必每件事都争到底。","en":"The lesson distinguishes priorities rather than escalating every dispute equally."}}],"correct":"w07-R1-595675772e"}},"RA":{"teach":[{"zh":"先说清哪些要求不能让步，哪些事情可以商量。守住重要任务不是把每条意见都拒绝，也不是为了避免冲突接受所有要求。","en":"A boundary states what must be preserved and what can be negotiated. Protecting essential work means neither rejecting every suggestion nor accepting every demand to avoid conflict."}],"question":{"id":"w07-RA","prompt":{"zh":"团队临时要求加两项装饰，但安全检查时间会因此被挤掉。这张牌在建议位时，怎样做更合适？","en":"Two decorative additions would remove time for a necessary safety check. How does this card apply?"},"options":[{"id":"w07-RA-883aac28cf","text":{"zh":"说明检查不能省，协商简化装饰。","en":"Keep the necessary check and negotiate simpler decorations."},"feedback":{"zh":"必要的检查不能省，装饰要求则可以商量。把所有要求都答应下来，可能反而没时间做好检查。","en":"The defined priority is the necessary check; negotiating decoration protects it rather than replacing a boundary with compliance."}},{"id":"w07-RA-657ac51db1","text":{"zh":"为了显得配合，接受加项并取消检查。","en":"Accept additions and cancel the check to appear cooperative."},"feedback":{"zh":"必要的检查不能省，装饰要求则可以商量。把所有要求都答应下来，可能反而没时间做好检查。","en":"“Accept additions and cancel the check to appear cooperative.” does not address the specific conditions. The defined priority is the necessary check; negotiating decoration protects it rather than replacing a boundary with compliance."}}],"correct":"w07-RA-883aac28cf"}},"R2":{"teach":[{"zh":"少卷入无关争论，才能把精力留给重要的事。一直争下去，只会更累。 题目描述的是“每次争论都要回应，反而顾不上重要的事”，不是“已经有效保护最重要的工作”。","en":"Selecting what to defend restores priorities; endless argument continues the drain. Return to the stated context: “Defence loses selectivity and scatters energy” fits this case; “The most important work is already protected effectively” is unsupported by that context."}],"question":{"id":"w07-R2","prompt":{"zh":"每天花三小时反驳无关评论，重要工作却没时间做。怎样调整更合适？","en":"Three hours a day go into rebutting irrelevant comments, leaving little time for important work. What adjustment fits?"},"options":[{"id":"w07-R2-d90e7d755b","text":{"zh":"停止无关争执，把精力留给必须坚持的事","en":"Stop irrelevant disputes and protect key boundaries"},"feedback":{"zh":"少卷入无关争论，才能把精力留给重要的事。一直争下去，只会更累。","en":"Selecting what to defend restores priorities; endless argument continues the drain."}},{"id":"w07-R2-37d4d75793","text":{"zh":"增加反驳时间直到所有人同意","en":"Spend longer until everyone agrees"},"feedback":{"zh":"少卷入无关争论，才能把精力留给重要的事。一直争下去，只会更累。","en":"Selecting what to defend restores priorities; endless argument continues the drain."}}],"correct":"w07-R2-d90e7d755b"}}},"revisit":{"id":"w07-V1","prompt":{"zh":"研究小组被催省略必要检查。哪项更贴近？","en":"a research group is pressured to omit necessary checks. Which fits?"},"options":[{"id":"w07-V1-acef7524ca","text":{"zh":"为结束争执直接取消所有标准","en":"Remove every standard just to end disagreement"},"feedback":{"zh":"必要检查不能因为催促就省掉。说明理由、坚持标准，是在保护工作质量，不是为了争输赢。","en":"The necessary checks are a defined priority to protect, not a trivial contest."}},{"id":"w07-V1-0ae69085f1","text":{"zh":"说明检查的必要性并守住标准","en":"Explain why checks matter and maintain the standard"},"feedback":{"zh":"必要检查不能因为催促就省掉。说明理由、坚持标准，是在保护工作质量，不是为了争输赢。","en":"The necessary checks are a defined priority to protect, not a trivial contest."}}],"correct":"w07-V1-0ae69085f1"},"summary":{"zh":"面对挑战或质疑，努力守住已经争取到的位置，坚持重要的立场。 重点是守住真正重要的事。每件小事都要争个输赢，反而会顾不上最该坚持的立场。","en":"Meet challenges by defending a position or boundary already gained. Decide what is worth protecting rather than treating every disagreement as a battle."},"cards":["w07"]},{"id":"w08","kind":"card","level":"I","title":{"zh":"权杖八","en":"Eight of Wands"},"teachings":[{"zh":"事情开始迅速推进，消息也可能接连到来。 八根权杖同向飞行，可以帮助记住速度和进展。八根并不是“八天”，不能只靠数量确定日期。","en":"Events, messages, or coordinated actions are moving quickly. Respond and organise while keeping pace, without converting the number into a fixed deadline."},{"zh":"八根权杖同向掠过天空，呈现迅速而一致的运动。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Eight wands move in one direction across an open sky, a clear cue for swift movement. This is a visual association for learning, not proof of an external event."},{"zh":"快速推进、消息到来。 火对应行动；八不是八天。速度来自本牌主题与画面，不能由数字单独预测日期。","en":"rapid progress; incoming messages. Fire relates to action; eight does not mean eight days. Speed is a theme of this card, not a date calculated from its number."}],"application":{"zh":"示范：多条关键消息到来，及时确认并整理待办。消息来得快，更要看清内容再及时回复；回得快，不等于时间和安排都核对好了。","en":"Example: confirm incoming updates and organise tasks. Fast progress needs clear responses; speed does not replace checking."},"reversal":{"zh":"案例：几个人同时发来互相矛盾的行程更新，推进很急却出现误会。这里的逆位，是消息互相矛盾，沟通出了问题。","en":"Case: several conflicting schedule updates arrive at once. Progress is rapid but confused. Here the reversal concerns disordered communication."},"visual":{"zh":"八根权杖同向掠过天空，呈现迅速而一致的运动。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Eight wands move in one direction across an open sky, a clear cue for swift movement. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w08-Q1","prompt":{"zh":"同向飞行的权杖帮助记哪个主题？","en":"What theme does the same-direction flight help recall?"},"options":[{"id":"w08-Q1-53c6a03607","text":{"zh":"进展必定在八天后结束","en":"Progress definitely ends in eight days"},"feedback":{"zh":"八根权杖同向飞行，可以帮助记住速度和进展。八根并不是“八天”，不能只靠数量确定日期。","en":"The image aids speed; the count does not specify a time unit."}},{"id":"w08-Q1-6ddc7194bd","text":{"zh":"消息或行动快速推进","en":"Messages or actions move rapidly"},"feedback":{"zh":"八根权杖同向飞行，可以帮助记住速度和进展。八根并不是“八天”，不能只靠数量确定日期。","en":"The image aids speed; the count does not specify a time unit."}}],"correct":"w08-Q1-6ddc7194bd","support":"R1"},"Q2":{"id":"w08-Q2","prompt":{"zh":"几场面试的安排集中发来。权杖八在建议位，哪种做法更合适？","en":"Several interview arrangements arrive at once. With the Eight of Wands as advice, which response fits?"},"options":[{"id":"w08-Q2-33756f8420","text":{"zh":"及时确认时间并整理安排","en":"Confirm times promptly and organise the schedule"},"feedback":{"zh":"消息来得快，更要看清内容再及时回复；回得快，不等于时间和安排都核对好了。","en":"Fast progress needs clear responses; speed does not replace checking."}},{"id":"w08-Q2-c513002c8b","text":{"zh":"因为进展快就不用核对时间","en":"Skip checking times because progress is fast"},"feedback":{"zh":"消息来得快，更要看清内容再及时回复；回得快，不等于时间和安排都核对好了。","en":"Fast progress needs clear responses; speed does not replace checking."}}],"correct":"w08-Q2-33756f8420","support":"RA"},"Q3":{"id":"w08-Q3","prompt":{"zh":"行程通知互相冲突，这张逆位牌在建议位时，先处理什么更合适？","en":"Schedule notices conflict. What should this reversed case address first?"},"options":[{"id":"w08-Q3-8347fc7a25","text":{"zh":"凭消息多就认定安排完全清楚","en":"Assume many messages mean a fully clear schedule"},"feedback":{"zh":"几条通知给出的时间互相矛盾，需要先查清哪个有效。消息多，不代表安排已经清楚。","en":"The problem is inconsistent information; more messages do not ensure accuracy."}},{"id":"w08-Q3-10041982a3","text":{"zh":"核对消息，确认大家收到的是同一个安排","en":"Verify information and restore consistency"},"feedback":{"zh":"几条通知给出的时间互相矛盾，需要先查清哪个有效。消息多，不代表安排已经清楚。","en":"The problem is inconsistent information; more messages do not ensure accuracy."}}],"correct":"w08-Q3-10041982a3","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"这张牌可以帮助概括消息接连到来、事情加快，但不能用八根权杖算出确定日期。 记住：消息或行动快速推进，不是“进展必定在八天后结束”。","en":"The lesson supports speed and messages, not a definite date from the count. Compare: Messages or actions move rapidly; this cannot be replaced by “Progress definitely ends in eight days”."}],"question":{"id":"w08-R1","prompt":{"zh":"一周内收到多份合作回复。哪项是牌义支持的概括？","en":"several partnership replies arrive in one week. Which summary fits?"},"options":[{"id":"w08-R1-7703b782b1","text":{"zh":"回复集中到来，事情加快","en":"Responses arrive together and events accelerate"},"feedback":{"zh":"这张牌可以帮助概括消息接连到来、事情加快，但不能用八根权杖算出确定日期。","en":"The lesson supports speed and messages, not a definite date from the count."}},{"id":"w08-R1-b549eb697d","text":{"zh":"仅凭八根权杖可确定八周后结束","en":"Eight pictured wands establish an end in eight weeks"},"feedback":{"zh":"这张牌可以帮助概括消息接连到来、事情加快，但不能用八根权杖算出确定日期。","en":"The lesson supports speed and messages, not a definite date from the count."}}],"correct":"w08-R1-7703b782b1"}},"RA":{"teach":[{"zh":"事情加快时，确认时间和整理安排是为了跟上进展。及时不等于未经核对：先确认关键消息，再迅速行动，才能避免不同任务互相冲突。","en":"When events accelerate, checking times and organising tasks helps keep pace. Promptness does not mean acting unchecked; verify key details and then move quickly to avoid clashes."}],"question":{"id":"w08-RA","prompt":{"zh":"同一天收到两场线上面试通知，其中一封刚改时间。哪项应用更合适？","en":"Two online interviews are announced, and one time has just changed. Which application fits?"},"options":[{"id":"w08-RA-ca21582078","text":{"zh":"为了回应快，未经核对就同时答应两个时段。","en":"To respond quickly, accept both slots without checking."},"feedback":{"zh":"及时回复之前，先核对改过的时间。不看清就答应，可能把两场面试排在同一时段。","en":"“To respond quickly, accept both slots without checking.” does not address the specific conditions. The case needs both pace and coordination; unchecked quick commitments can create clashes."}},{"id":"w08-RA-c03d7d2878","text":{"zh":"确认最新时间，再调整当天安排并回复。","en":"Confirm the current time, adjust the day, and reply."},"feedback":{"zh":"及时回复之前，先核对改过的时间。不看清就答应，可能把两场面试排在同一时段。","en":"The case needs both pace and coordination; unchecked quick commitments can create clashes."}}],"correct":"w08-RA-c03d7d2878"}},"R2":{"teach":[{"zh":"先确认哪个时间有效，再通知大家。把两个冲突的版本都转发出去，会让人更糊涂。 题目描述的是“核对消息，确认大家收到的是同一个安排”，不是“凭消息多就认定安排完全清楚”。","en":"Verifying the version reduces confusion; spreading both maintains it. Return to the stated context: “Verify information and restore consistency” fits this case; “Assume many messages mean a fully clear schedule” is unsupported by that context."}],"question":{"id":"w08-R2","prompt":{"zh":"收到两个版本的通知，集合时间不一样。先做什么更合适？","en":"Two notices give different meeting times. What can you do first?"},"options":[{"id":"w08-R2-998219d517","text":{"zh":"把两版都继续转发不作说明","en":"Keep forwarding both without explanation"},"feedback":{"zh":"先确认哪个时间有效，再通知大家。把两个冲突的版本都转发出去，会让人更糊涂。","en":"Verifying the version reduces confusion; spreading both maintains it."}},{"id":"w08-R2-0eec4f6f02","text":{"zh":"确认唯一有效版本再通知大家","en":"Confirm the valid version and inform everyone"},"feedback":{"zh":"先确认哪个时间有效，再通知大家。把两个冲突的版本都转发出去，会让人更糊涂。","en":"Verifying the version reduces confusion; spreading both maintains it."}}],"correct":"w08-R2-0eec4f6f02"}}},"revisit":{"id":"w08-V1","prompt":{"zh":"订单突然增加，几个步骤可同时推进。哪项建议贴近？","en":"orders rise suddenly and several tasks can move together. What fits?"},"options":[{"id":"w08-V1-a001647349","text":{"zh":"快速协调处理，同时确认关键消息","en":"Coordinate promptly while verifying key information"},"feedback":{"zh":"订单增加后，可以加快协调，但什么时候能交货，要按实际工作量和人手来算，不能只看牌上的数字。","en":"Respond to acceleration, but delivery dates require real capacity information."}},{"id":"w08-V1-b350859314","text":{"zh":"按牌上数字承诺固定交付日期","en":"Promise a fixed delivery date from the printed number"},"feedback":{"zh":"订单增加后，可以加快协调，但什么时候能交货，要按实际工作量和人手来算，不能只看牌上的数字。","en":"Respond to acceleration, but delivery dates require real capacity information."}}],"correct":"w08-V1-a001647349"},"summary":{"zh":"事情开始迅速推进，消息也可能接连到来。 八根权杖同向飞行，可以帮助记住速度和进展。八根并不是“八天”，不能只靠数量确定日期。","en":"Events, messages, or coordinated actions are moving quickly. Respond and organise while keeping pace, without converting the number into a fixed deadline."},"cards":["w08"]},{"id":"w09","kind":"card","level":"I","title":{"zh":"权杖九","en":"Nine of Wands"},"teachings":[{"zh":"经历过困难，虽然疲惫，仍然没有放弃；同时也担心再受伤，保持着警惕。 头上的绷带让人想到受过伤，仍握着权杖站立则帮助记住继续坚持。两处细节要一起看。","en":"Past strain has made someone wary, yet they are still holding on. Protect what matters and allow recovery instead of confusing resilience with unlimited endurance."},{"zh":"头缠绷带的人握杖站在一排权杖前，兼有坚持和防护的意味。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A bandaged figure grips a wand before a row of wands, recalling both persistence after strain and protective alertness. This is a visual association for learning, not proof of an external event."},{"zh":"韧性、警觉、保留精力。 权杖对应火元素，在这里表现为虽然疲惫，仍想坚持；九接近这组数字的末尾，但不代表事情已经结束。","en":"resilience; vigilance; protecting capacity. Fire appears as remaining resolve; nine here suggests a later phase, not complete closure."}],"application":{"zh":"示范：保留核心复习任务，同时安排恢复。还想继续，就要留出恢复时间。已经疲惫时再不断加练，并不等于更坚强。","en":"Example: keep core revision and allow recovery. Resilience includes protecting the capacity to continue, not limitless escalation."},"reversal":{"zh":"案例：连续承担任务后已经无法集中，仍要求自己不休息。这里的逆位，是已经太累，快撑不住了。","en":"Case: prolonged demands have undermined concentration, but rest is still refused. Here the reversal focuses on depleted endurance."},"visual":{"zh":"头缠绷带的人握杖站在一排权杖前，兼有坚持和防护的意味。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A bandaged figure grips a wand before a row of wands, recalling both persistence after strain and protective alertness. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w09-Q1","prompt":{"zh":"绷带与仍然站立的姿态，合起来帮助记什么？","en":"What do the bandage and continued stance help recall together?"},"options":[{"id":"w09-Q1-3bf74da5cd","text":{"zh":"虽然累了，仍在坚持，也小心不让自己再受伤","en":"Persistence after strain, with alertness"},"feedback":{"zh":"头上的绷带让人想到受过伤，仍握着权杖站立则帮助记住继续坚持。两处细节要一起看。","en":"The bandage and grip connect previous strain with continued persistence."}},{"id":"w09-Q1-ca10c3e9fb","text":{"zh":"没有受过考验，也不需要防护","en":"No strain has occurred and no protection is needed"},"feedback":{"zh":"头上的绷带让人想到受过伤，仍握着权杖站立则帮助记住继续坚持。两处细节要一起看。","en":"The bandage and grip connect previous strain with continued persistence."}}],"correct":"w09-Q1-3bf74da5cd","support":"R1"},"Q2":{"id":"w09-Q2","prompt":{"zh":"训练后已经疲惫，但还想完成比赛准备。权杖九在建议位，哪种安排更合适？","en":"You are tired after training but still want to prepare for a competition. With the Nine of Wands as advice, which arrangement fits?"},"options":[{"id":"w09-Q2-447dadea2b","text":{"zh":"把所有休息取消以证明坚强","en":"Cancel all rest to prove strength"},"feedback":{"zh":"还想继续，就要留出恢复时间。已经疲惫时再不断加练，并不等于更坚强。","en":"Resilience includes protecting the capacity to continue, not limitless escalation."}},{"id":"w09-Q2-4b3f0a4fe6","text":{"zh":"守住关键训练并留出恢复时间","en":"Keep essential practice and allow recovery"},"feedback":{"zh":"还想继续，就要留出恢复时间。已经疲惫时再不断加练，并不等于更坚强。","en":"Resilience includes protecting the capacity to continue, not limitless escalation."}}],"correct":"w09-Q2-4b3f0a4fe6","support":"RA"},"Q3":{"id":"w09-Q3","prompt":{"zh":"连续消耗已无法集中，这张逆位牌更贴近哪种情况？","en":"Prolonged strain prevents concentration. What does this reversal concern?"},"options":[{"id":"w09-Q3-81bb7929e4","text":{"zh":"已经很累，快撑不住了","en":"The ability to keep going is depleted"},"feedback":{"zh":"已经累得无法集中，说明需要恢复精力。再加任务，并不会证明自己已经缓过来了。","en":"The case shows fatigue; increased demands are not evidence of recovery."}},{"id":"w09-Q3-11fe2a20b9","text":{"zh":"只要再加任务就证明已经恢复","en":"Adding demands would prove recovery"},"feedback":{"zh":"已经累得无法集中，说明需要恢复精力。再加任务，并不会证明自己已经缓过来了。","en":"The case shows fatigue; increased demands are not evidence of recovery."}}],"correct":"w09-Q3-81bb7929e4","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"可以一边继续努力，一边注意保护自己。有所警惕，不等于已经放弃。 记住：虽然累了，仍在坚持，也小心不让自己再受伤，不是“没有受过考验，也不需要防护”。","en":"This card can hold both continued effort and self-protection; they are not mutually exclusive. Compare: Persistence after strain, with alertness; this cannot be replaced by “No strain has occurred and no protection is needed”."}],"question":{"id":"w09-R1","prompt":{"zh":"过去受挫后仍练习，但会先检查风险。哪句贴近？","en":"someone keeps practising after setbacks but checks risks first. Which fits?"},"options":[{"id":"w09-R1-03b2eadbd4","text":{"zh":"有警觉就等于已经放弃","en":"Vigilance necessarily means giving up"},"feedback":{"zh":"可以一边继续努力，一边注意保护自己。有所警惕，不等于已经放弃。","en":"This card can hold both continued effort and self-protection; they are not mutually exclusive."}},{"id":"w09-R1-9153891027","text":{"zh":"还想继续努力，也会先注意风险","en":"Persistence and vigilance coexist"},"feedback":{"zh":"可以一边继续努力，一边注意保护自己。有所警惕，不等于已经放弃。","en":"This card can hold both continued effort and self-protection; they are not mutually exclusive."}}],"correct":"w09-R1-9153891027"}},"RA":{"teach":[{"zh":"把力气留给重要的任务，不必不断给自己加码。累了以后，保留必要练习，也安排休息，才有精力继续。","en":"Persistence protects the core task rather than adding demands without limit. After strain, keeping essential practice and recovery makes continuation possible; rest is not automatic surrender."}],"question":{"id":"w09-RA","prompt":{"zh":"连续排练后声音疲惫，明天还要走台。这张牌在建议位时，怎样做更合适？","en":"After repeated rehearsals, a performer is tired and still has a stage walkthrough tomorrow. What fits the lesson?"},"options":[{"id":"w09-RA-4fed90f134","text":{"zh":"保留必要的走位准备，并安排恢复。","en":"Keep necessary blocking preparation and allow recovery."},"feedback":{"zh":"留出恢复时间，是为了还能完成后面的任务。已经疲惫时继续加练，只会消耗更多精力。","en":"Protecting capacity serves continued work; escalating strain is not greater resilience."}},{"id":"w09-RA-68f1e78203","text":{"zh":"取消全部休息，用额外排练证明坚持。","en":"Cancel rest and add rehearsals to prove persistence."},"feedback":{"zh":"留出恢复时间，是为了还能完成后面的任务。已经疲惫时继续加练，只会消耗更多精力。","en":"“Cancel rest and add rehearsals to prove persistence.” does not address the specific conditions. Protecting capacity serves continued work; escalating strain is not greater resilience."}}],"correct":"w09-RA-4fed90f134"}},"R2":{"teach":[{"zh":"连续几天都无法完成任务，说明已经很累了。减掉非必要任务、安排休息，才是在处理这个问题。 题目描述的是“已经很累，快撑不住了”，不是“只要再加任务就证明已经恢复”。","en":"The evidence points to reduced capacity; easing demands addresses rather than denies depletion. Return to the stated context: “The ability to keep going is depleted” fits this case; “Adding demands would prove recovery” is unsupported by that context."}],"question":{"id":"w09-R2","prompt":{"zh":"已经累得连续几天都做不完重要任务。接下来怎样安排更合适？","en":"You have been too exhausted to finish important tasks for several days. What arrangement would help next?"},"options":[{"id":"w09-R2-c2588a1234","text":{"zh":"减少非必要负担并安排恢复","en":"Reduce nonessential demands and recover"},"feedback":{"zh":"连续几天都无法完成任务，说明已经很累了。减掉非必要任务、安排休息，才是在处理这个问题。","en":"The evidence points to reduced capacity; easing demands addresses rather than denies depletion."}},{"id":"w09-R2-cba84e5808","text":{"zh":"把无法完成解释成还有无限精力","en":"Interpret difficulty as unlimited energy"},"feedback":{"zh":"连续几天都无法完成任务，说明已经很累了。减掉非必要任务、安排休息，才是在处理这个问题。","en":"The evidence points to reduced capacity; easing demands addresses rather than denies depletion."}}],"correct":"w09-R2-c2588a1234"}}},"revisit":{"id":"w09-V1","prompt":{"zh":"长期筹备活动后仍需守住最后检查。哪项更贴近？","en":"after long event preparation, final checks remain. Which fits?"},"options":[{"id":"w09-V1-170c2cf5a5","text":{"zh":"因为已坚持很久就不需任何检查","en":"Skip all checks because effort has lasted a long time"},"feedback":{"zh":"坚持了很久，最后仍要做好必要检查，也要留住精力。不能因为已经很辛苦，就认定后面不会出问题。","en":"Past effort does not eliminate later problems; persistence needs capacity and reasonable protection."}},{"id":"w09-V1-281185cb43","text":{"zh":"保持必要警觉，也保护剩余精力","en":"Keep necessary vigilance and protect remaining energy"},"feedback":{"zh":"坚持了很久，最后仍要做好必要检查，也要留住精力。不能因为已经很辛苦，就认定后面不会出问题。","en":"Past effort does not eliminate later problems; persistence needs capacity and reasonable protection."}}],"correct":"w09-V1-281185cb43"},"summary":{"zh":"经历过困难，虽然疲惫，仍然没有放弃；同时也担心再受伤，保持着警惕。 头上的绷带让人想到受过伤，仍握着权杖站立则帮助记住继续坚持。两处细节要一起看。","en":"Past strain has made someone wary, yet they are still holding on. Protect what matters and allow recovery instead of confusing resilience with unlimited endurance."},"cards":["w09"]},{"id":"w10","kind":"card","level":"I","title":{"zh":"权杖十","en":"Ten of Wands"},"teachings":[{"zh":"事情和责任都揽得太多，做起来已经很吃力。 抱着那么多权杖，连走路都很吃力，可以帮助记住负担过重。忙碌本身不代表每件事都值得做。","en":"Responsibilities have accumulated beyond a manageable load. The goal may still matter, but the burden needs examining, sharing, or reducing."},{"zh":"人物抱着十根权杖弯身向前，视线和行动空间受限。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A person bends forward under ten wands, with restricted vision and movement: a direct cue for excessive load. This is a visual association for learning, not proof of an external event."},{"zh":"负担、责任过量。 火的行动积累成负担；十提示这一轮累积，不自动代表成功、价值或必须继续承担。","en":"burden; excessive responsibility. Accumulated action becomes a load; ten suggests culmination here, not automatic success, worth, or an obligation to carry on."}],"application":{"zh":"示范：重新分配过多工作。问题是一个人承担得太多。把任务分清、请别人分担，才能减轻负担；继续全包只会更累。","en":"Example: redistribute excessive work. Reducing excess addresses the problem; continuing to carry everything maintains it."},"reversal":{"zh":"案例：原来一人包办活动，后来把场地和物料任务分别交给伙伴。这里的逆位，是开始把事情分出去，不再独自承担所有任务。","en":"Case: one person formerly managed an event alone and now delegates venue and materials. Here the reversal describes beginning to release a burden."},"visual":{"zh":"人物抱着十根权杖弯身向前，视线和行动空间受限。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A person bends forward under ten wands, with restricted vision and movement: a direct cue for excessive load. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w10-Q1","prompt":{"zh":"弯身抱着许多权杖，主要帮助记什么？","en":"What does bending beneath many wands mainly help recall?"},"options":[{"id":"w10-Q1-e7af7d845d","text":{"zh":"任务越多就一定越有价值","en":"More tasks necessarily mean more value"},"feedback":{"zh":"抱着那么多权杖，连走路都很吃力，可以帮助记住负担过重。忙碌本身不代表每件事都值得做。","en":"The lesson describes the cost of carrying a load, not busyness as proof of value."}},{"id":"w10-Q1-642406b467","text":{"zh":"事情揽得太多，做起来很吃力","en":"Responsibilities are excessive and movement is burdened"},"feedback":{"zh":"抱着那么多权杖，连走路都很吃力，可以帮助记住负担过重。忙碌本身不代表每件事都值得做。","en":"The lesson describes the cost of carrying a load, not busyness as proof of value."}}],"correct":"w10-Q1-642406b467","support":"R1"},"Q2":{"id":"w10-Q2","prompt":{"zh":"一位学生包办了小组的所有任务，已经忙不过来。权杖十在建议位，哪种做法更合适？","en":"A student is overwhelmed by handling every group task alone. With the Ten of Wands as advice, which step fits?"},"options":[{"id":"w10-Q2-b0fced0804","text":{"zh":"列清任务并协商分担","en":"List tasks and agree on shared responsibilities"},"feedback":{"zh":"问题是一个人承担得太多。把任务分清、请别人分担，才能减轻负担；继续全包只会更累。","en":"Reducing excess addresses the problem; continuing to carry everything maintains it."}},{"id":"w10-Q2-2f1f9c620a","text":{"zh":"继续接下全部任务来证明投入","en":"Keep every task to prove commitment"},"feedback":{"zh":"问题是一个人承担得太多。把任务分清、请别人分担，才能减轻负担；继续全包只会更累。","en":"Reducing excess addresses the problem; continuing to carry everything maintains it."}}],"correct":"w10-Q2-b0fced0804","support":"RA"},"Q3":{"id":"w10-Q3","prompt":{"zh":"把活动任务分给伙伴后，这张逆位牌更贴近哪种情况？","en":"After event tasks are delegated, what does this reversal mean here?"},"options":[{"id":"w10-Q3-ca985f63ad","text":{"zh":"所有责任已经永久消失","en":"All responsibility has vanished permanently"},"feedback":{"zh":"把任务分给伙伴，可以减轻自己的负担，但活动仍要继续做，不是从此没有责任。","en":"Redistribution changes how responsibility is carried, not whether it ever exists."}},{"id":"w10-Q3-32edaf16d2","text":{"zh":"开始卸下并重新分配负担","en":"Beginning to release and redistribute the burden"},"feedback":{"zh":"把任务分给伙伴，可以减轻自己的负担，但活动仍要继续做，不是从此没有责任。","en":"Redistribution changes how responsibility is carried, not whether it ever exists."}}],"correct":"w10-Q3-32edaf16d2","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"人物被一大捆权杖挡住视线，走路也很费力。这里要记住负担过重，而不是认定每项任务都值得承担。 记住：事情揽得太多，做起来很吃力，不是“任务越多就一定越有价值”。","en":"Restricted movement cues the cost of overload, not the worth of every task. Compare: Responsibilities are excessive and movement is burdened; this cannot be replaced by “More tasks necessarily mean more value”."}],"question":{"id":"w10-R1","prompt":{"zh":"忙到看不到下一步路，仍说越忙越有价值。哪种理解更合适？","en":"Someone is too busy to see the next step but calls greater busyness greater worth. Which interpretation fits better?"},"options":[{"id":"w10-R1-7e267b30ca","text":{"zh":"任务太多，可能顾不上重要的事，需要重新取舍","en":"Excess work can obscure priorities and needs review"},"feedback":{"zh":"人物被一大捆权杖挡住视线，走路也很费力。这里要记住负担过重，而不是认定每项任务都值得承担。","en":"Restricted movement cues the cost of overload, not the worth of every task."}},{"id":"w10-R1-8c1954ff7e","text":{"zh":"只要工作很多就无需评估","en":"High workload makes review unnecessary"},"feedback":{"zh":"人物被一大捆权杖挡住视线，走路也很费力。这里要记住负担过重，而不是认定每项任务都值得承担。","en":"Restricted movement cues the cost of overload, not the worth of every task."}}],"correct":"w10-R1-7e267b30ca"}},"RA":{"teach":[{"zh":"重新分担不是逃避责任，而是把过量任务拆清楚：哪些必须本人做、哪些可以交接、哪些可以延期。必须明确交接，不能只是希望别人自动接手。","en":"Redistribution is not avoidance. Separate tasks that require you, can be handed over, or can wait. Make handovers explicit instead of hoping others automatically take over."}],"question":{"id":"w10-RA","prompt":{"zh":"活动负责人同时包办报名、采购和主持，已无时间核对现场。这张牌在建议位时，怎样做更合适？","en":"An organiser handles registration, purchasing, and hosting with no time for venue checks. What fits?"},"options":[{"id":"w10-RA-eb5ce3053b","text":{"zh":"继续全包，再用更忙证明自己负责。","en":"Keep every task and use greater busyness to prove responsibility."},"feedback":{"zh":"一个人已经忙不过来，就要把任务交接清楚。继续全包，可能连必要检查都没时间做。","en":"“Keep every task and use greater busyness to prove responsibility.” does not address the specific conditions. The known issue is overload; explicit sharing addresses it, while busyness alone does not show duties are covered."}},{"id":"w10-RA-d15fe18b0b","text":{"zh":"协商交接可分担任务，保留必要的现场核对。","en":"Agree on handovers and retain essential venue checks."},"feedback":{"zh":"一个人已经忙不过来，就要把任务交接清楚。继续全包，可能连必要检查都没时间做。","en":"The known issue is overload; explicit sharing addresses it, while busyness alone does not show duties are covered."}}],"correct":"w10-RA-d15fe18b0b"}},"R2":{"teach":[{"zh":"减轻负担，可以是交出一部分工作，仍负责必要的事情，不是非得什么都不做。 题目描述的是“开始卸下并重新分配负担”，不是“所有责任已经永久消失”。","en":"Release adjusts the load; it does not require abandoning every duty. Return to the stated context: “Beginning to release and redistribute the burden” fits this case; “All responsibility has vanished permanently” is unsupported by that context."}],"question":{"id":"w10-R2","prompt":{"zh":"把两项任务分给伙伴，自己仍负责协调。这样算减轻负担吗？","en":"Two tasks are delegated while you still coordinate the work. Does this count as easing your burden?"},"options":[{"id":"w10-R2-b528efae70","text":{"zh":"必须什么也不做才算卸下负担","en":"Release only counts if nothing at all is done"},"feedback":{"zh":"减轻负担，可以是交出一部分工作，仍负责必要的事情，不是非得什么都不做。","en":"Release adjusts the load; it does not require abandoning every duty."}},{"id":"w10-R2-7aafaa0f3e","text":{"zh":"分出去一部分任务，自己仍负责该做的事","en":"A more workable load with necessary responsibility retained"},"feedback":{"zh":"减轻负担，可以是交出一部分工作，仍负责必要的事情，不是非得什么都不做。","en":"Release adjusts the load; it does not require abandoning every duty."}}],"correct":"w10-R2-7aafaa0f3e"}}},"revisit":{"id":"w10-V1","prompt":{"zh":"照顾社区活动时一人承担采购、布置、联络而疲惫。哪项贴近建议？","en":"one organiser is exhausted by shopping, setup, and communication. What fits?"},"options":[{"id":"w10-V1-4023930bc2","text":{"zh":"把可分担的工作明确分出去","en":"Explicitly share work that others can carry"},"feedback":{"zh":"已经累到顾不过来，说明一个人承担太多了。把能分担的任务交接出去，才能减轻负担。","en":"Exhaustion reveals a load problem that appropriate sharing can address."}},{"id":"w10-V1-efb489ffa2","text":{"zh":"用疲惫证明所有任务不能分担","en":"Treat exhaustion as proof nothing can be shared"},"feedback":{"zh":"已经累到顾不过来，说明一个人承担太多了。把能分担的任务交接出去，才能减轻负担。","en":"Exhaustion reveals a load problem that appropriate sharing can address."}}],"correct":"w10-V1-4023930bc2"},"summary":{"zh":"事情和责任都揽得太多，做起来已经很吃力。 抱着那么多权杖，连走路都很吃力，可以帮助记住负担过重。忙碌本身不代表每件事都值得做。","en":"Responsibilities have accumulated beyond a manageable load. The goal may still matter, but the burden needs examining, sharing, or reducing."},"cards":["w10"]},{"id":"w11","kind":"card","level":"I","title":{"zh":"权杖侍从","en":"Page of Wands"},"teachings":[{"zh":"对新想法很好奇，带着热情，愿意从第一次尝试开始。 这里的“侍从”描述初学时好奇、愿意尝试的样子，不是只指某个年龄的人。","en":"Approach a new idea with a learner’s curiosity and willingness to try. Enthusiasm is an invitation to experiment, not proof of established expertise."},{"zh":"站立人物端详发芽的权杖，帮助记住刚开始探索的状态。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A standing figure examines a sprouting wand, helping recall an exploratory beginner’s attention. This is a visual association for learning, not proof of an external event."},{"zh":"好奇、热情、初步尝试。 侍从可以帮助记住刚开始接触、试着做做看的状态；火关联创意行动，不限定年轻人或任何性别。","en":"curiosity; enthusiasm; first experiments. The Page is a role of beginning and experimenting; fire relates to creative action, not a fixed age or gender."}],"application":{"zh":"示范：先上一节体验课再判断兴趣。不论几岁，都可以从初学者开始。亲手试一次，才能更清楚自己喜不喜欢。","en":"Example: take one trial class before judging an interest. A beginner role is open at any age; a small trial tests interest."},"reversal":{"zh":"案例：不断收藏新兴趣教程，却每次都在第一次实践前转向下一个兴趣。这里的逆位，是很有兴趣，却始终没有亲手试过。","en":"Case: new-hobby tutorials are collected, but attention shifts before any first attempt. Here the reversal concerns enthusiasm that never reaches a trial."},"visual":{"zh":"站立人物端详发芽的权杖，帮助记住刚开始探索的状态。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A standing figure examines a sprouting wand, helping recall an exploratory beginner’s attention. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w11-Q1","prompt":{"zh":"权杖侍从描述的是哪一种状态？","en":"What does the Page describe?"},"options":[{"id":"w11-Q1-0955c6efc7","text":{"zh":"带着好奇尝试新想法的状态","en":"A curious state of trying new ideas"},"feedback":{"zh":"这里的“侍从”描述初学时好奇、愿意尝试的样子，不是只指某个年龄的人。","en":"The court role describes a learning and action style rather than fixing age."}},{"id":"w11-Q1-ad60de4d7a","text":{"zh":"只能指某个年龄的人","en":"Only a person of a particular age"},"feedback":{"zh":"这里的“侍从”描述初学时好奇、愿意尝试的样子，不是只指某个年龄的人。","en":"The court role describes a learning and action style rather than fixing age."}}],"correct":"w11-Q1-0955c6efc7","support":"R1"},"Q2":{"id":"w11-Q2","prompt":{"zh":"一位成年人第一次对陶艺产生兴趣。权杖侍从在建议位，哪种做法更合适？","en":"An adult has become interested in pottery for the first time. With the Page of Wands as advice, which step fits?"},"options":[{"id":"w11-Q2-5c1c8180c2","text":{"zh":"因不是年轻人就不能开始","en":"Rule out starting because the learner is not young"},"feedback":{"zh":"不论几岁，都可以从初学者开始。亲手试一次，才能更清楚自己喜不喜欢。","en":"A beginner role is open at any age; a small trial tests interest."}},{"id":"w11-Q2-d0ecd86b68","text":{"zh":"亲手试做一个简单器物","en":"Try making one simple piece"},"feedback":{"zh":"不论几岁，都可以从初学者开始。亲手试一次，才能更清楚自己喜不喜欢。","en":"A beginner role is open at any age; a small trial tests interest."}}],"correct":"w11-Q2-d0ecd86b68","support":"RA"},"Q3":{"id":"w11-Q3","prompt":{"zh":"只收藏教程却不停换兴趣，这张逆位牌更贴近哪种情况？","en":"Collecting tutorials while changing interests illustrates what here?"},"options":[{"id":"w11-Q3-fd8e2b11e7","text":{"zh":"很有兴趣，却始终没有亲手试过","en":"Enthusiasm is not becoming an initial experiment"},"feedback":{"zh":"他收藏了很多教程，却一次都没有做过，所以问题是迟迟没开始，而不是已经试过了。","en":"Practice is precisely what is missing; collecting does not replace trying."}},{"id":"w11-Q3-83cb8abda4","text":{"zh":"已经通过实践确认全部兴趣","en":"Every interest has already been tested in practice"},"feedback":{"zh":"他收藏了很多教程，却一次都没有做过，所以问题是迟迟没开始，而不是已经试过了。","en":"Practice is precisely what is missing; collecting does not replace trying."}}],"correct":"w11-Q3-fd8e2b11e7","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"兴奋地开始尝试，正是这张牌的初学状态；这还不等于已经有了长期的专业经验。 记住：带着好奇尝试新想法的状态，不是“只能指某个年龄的人”。","en":"Willingness to try shows Page-like exploration, not established mastery. Compare: A curious state of trying new ideas; this cannot be replaced by “Only a person of a particular age”."}],"question":{"id":"w11-R1","prompt":{"zh":"第一次接触摄影，兴奋地尝试拍一组照片。怎样概括？","en":"a photography newcomer excitedly tries a photo series. What describes it?"},"options":[{"id":"w11-R1-cd719f139d","text":{"zh":"已经拥有长期成熟的专业经验","en":"Long-established expertise is already proven"},"feedback":{"zh":"兴奋地开始尝试，正是这张牌的初学状态；这还不等于已经有了长期的专业经验。","en":"Willingness to try shows Page-like exploration, not established mastery."}},{"id":"w11-R1-02e07c18a7","text":{"zh":"因为好奇，开始亲手试一试","en":"Curiosity drives an initial exploration"},"feedback":{"zh":"兴奋地开始尝试，正是这张牌的初学状态；这还不等于已经有了长期的专业经验。","en":"Willingness to try shows Page-like exploration, not established mastery."}}],"correct":"w11-R1-02e07c18a7"}},"RA":{"teach":[{"zh":"新兴趣可以先用一次具体体验来了解。认真试一次，比只看介绍更能知道自己是否愿意继续；体验不是要求立刻成为专业人士。","en":"Explore a new interest through one concrete experience. Trying it reveals more about continued interest than descriptions alone; a trial does not demand instant expertise."}],"question":{"id":"w11-RA","prompt":{"zh":"对版画感兴趣，只读过介绍，还没操作过。这张牌在建议位时，怎样做更合适？","en":"A beginner is interested in printmaking but has only read descriptions. What applies the advice?"},"options":[{"id":"w11-RA-0e43ddb4dc","text":{"zh":"参加一次基础体验，亲手完成一个小练习。","en":"Take an introductory session and complete one small exercise."},"feedback":{"zh":"初学当然可以从基础做起。要求自己先达到专业水平才肯试，就一直没法开始。","en":"Page-like exploration allows a basic start; requiring mastery first blocks initial learning."}},{"id":"w11-RA-d04d29b172","text":{"zh":"先要求自己具备专业水平，才能首次尝试。","en":"Require professional competence before any first attempt."},"feedback":{"zh":"初学当然可以从基础做起。要求自己先达到专业水平才肯试，就一直没法开始。","en":"“Require professional competence before any first attempt.” does not address the specific conditions. Page-like exploration allows a basic start; requiring mastery first blocks initial learning."}}],"correct":"w11-RA-0e43ddb4dc"}},"R2":{"teach":[{"zh":"亲手做一次，才真正体验了这项兴趣；只收藏教程，还没有开始实践。 题目描述的是“很有兴趣，却始终没有亲手试过”，不是“已经通过实践确认全部兴趣”。","en":"A real trial grounds enthusiasm; bookmarking remains preparation. Return to the stated context: “Enthusiasm is not becoming an initial experiment” fits this case; “Every interest has already been tested in practice” is unsupported by that context."}],"question":{"id":"w11-R2","prompt":{"zh":"兴趣很多，却一次都没亲手试过。今天可以先做什么？","en":"You have many interests but have never tried any. What can you do first today?"},"options":[{"id":"w11-R2-c32ceaf810","text":{"zh":"挑一个兴趣完成一次小体验","en":"Pick one interest for a small first experience"},"feedback":{"zh":"亲手做一次，才真正体验了这项兴趣；只收藏教程，还没有开始实践。","en":"A real trial grounds enthusiasm; bookmarking remains preparation."}},{"id":"w11-R2-105f5ea23a","text":{"zh":"继续增加收藏并称为已经实践","en":"Add more bookmarks and call that practice"},"feedback":{"zh":"亲手做一次，才真正体验了这项兴趣；只收藏教程，还没有开始实践。","en":"A real trial grounds enthusiasm; bookmarking remains preparation."}}],"correct":"w11-R2-c32ceaf810"}}},"revisit":{"id":"w11-V1","prompt":{"zh":"退休后第一次加入戏剧体验活动。哪句贴近？","en":"someone joins a first drama workshop after retirement. Which fits?"},"options":[{"id":"w11-V1-628b471675","text":{"zh":"年龄使侍从角色不适用","en":"Age makes the Page role inapplicable"},"feedback":{"zh":"这里的侍从说的是初学时的热情和好奇。退休后开始新兴趣，也可以有这种状态。","en":"The role describes an attitude; age does not exclude curiosity or beginning."}},{"id":"w11-V1-4e9ac750d8","text":{"zh":"带着初学时的热情，尝试新的体验","en":"Explore a new experience with a beginner's enthusiasm"},"feedback":{"zh":"这里的侍从说的是初学时的热情和好奇。退休后开始新兴趣，也可以有这种状态。","en":"The role describes an attitude; age does not exclude curiosity or beginning."}}],"correct":"w11-V1-4e9ac750d8"},"summary":{"zh":"对新想法很好奇，带着热情，愿意从第一次尝试开始。 这里的“侍从”描述初学时好奇、愿意尝试的样子，不是只指某个年龄的人。","en":"Approach a new idea with a learner’s curiosity and willingness to try. Enthusiasm is an invitation to experiment, not proof of established expertise."},"cards":["w11"]},{"id":"w12","kind":"card","level":"I","title":{"zh":"权杖骑士","en":"Knight of Wands"},"teachings":[{"zh":"热情高涨，主动行动，想尽快体验新事物、把事情往前推。 骑士和马正在向前，可以帮助记住主动出发；这里不只是心里有想法。","en":"Move toward a new venture with boldness, energy, and a desire to explore. Momentum needs follow-through; a spirited start alone does not establish lasting commitment."},{"zh":"跃起的马与骑士举起的权杖，呈现快速行动的姿态。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The energetic horse and raised wand suggest a rider already moving into action. This is a visual association for learning, not proof of an external event."},{"zh":"冲劲、主动追求、冒险、推进。 骑士强调主动追求；火增加冲劲，不能据宫廷身份猜性别或承诺期限。","en":"drive; active pursuit; adventure; movement. The Knight represents active pursuit; fire adds drive, not evidence of gender or commitment length."}],"application":{"zh":"示范：迅速启动活动，同时补上后续安排。热情能让人很快开始，但之后怎么做、什么时候再做，仍要安排好。","en":"Example: launch an activity and arrange follow-through. Enthusiasm enables a start, but continuity still requires arrangements."},"reversal":{"zh":"案例：每遇新想法就立刻启动，几天后又换方向，原任务无人收尾。这里的逆位，是太急着开新项目，总换方向，原来的事却没做完。","en":"Case: every new idea triggers a start, then another switch leaves work unfinished. Here the reversal focuses on impulsiveness and inconsistent action."},"visual":{"zh":"跃起的马与骑士举起的权杖，呈现快速行动的姿态。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The energetic horse and raised wand suggest a rider already moving into action. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w12-Q1","prompt":{"zh":"跃起的马，可以帮助记住哪种行动？","en":"What action style does the energetic horse help recall here?"},"options":[{"id":"w12-Q1-b77da351bd","text":{"zh":"一直停在原地而不行动","en":"Remaining still without acting"},"feedback":{"zh":"骑士和马正在向前，可以帮助记住主动出发；这里不只是心里有想法。","en":"This Knight's theme is moving into action, not merely holding an idea."}},{"id":"w12-Q1-b346d34f5a","text":{"zh":"带着热情主动出发","en":"Setting out actively with enthusiasm"},"feedback":{"zh":"骑士和马正在向前，可以帮助记住主动出发；这里不只是心里有想法。","en":"This Knight's theme is moving into action, not merely holding an idea."}}],"correct":"w12-Q1-b346d34f5a","support":"R1"},"Q2":{"id":"w12-Q2","prompt":{"zh":"准备开始一次创作挑战。权杖骑士在建议位，怎样把热情变成持续的行动？","en":"You are preparing for a creative challenge. With the Knight of Wands as advice, how can enthusiasm become continued action?"},"options":[{"id":"w12-Q2-b80d1cb56a","text":{"zh":"先动手做，再安排下次接着做什么","en":"Begin and schedule the next follow-through step"},"feedback":{"zh":"热情能让人很快开始，但之后怎么做、什么时候再做，仍要安排好。","en":"Enthusiasm enables a start, but continuity still requires arrangements."}},{"id":"w12-Q2-79055c2f47","text":{"zh":"有热情开始，就认为以后不用再安排","en":"Treat starting enthusiasm as removing all need for follow-through"},"feedback":{"zh":"热情能让人很快开始，但之后怎么做、什么时候再做，仍要安排好。","en":"Enthusiasm enables a start, but continuity still requires arrangements."}}],"correct":"w12-Q2-b80d1cb56a","support":"RA"},"Q3":{"id":"w12-Q3","prompt":{"zh":"不断启动又换方向，这张逆位牌更贴近哪种情况？","en":"Repeated starts followed by switching illustrate what here?"},"options":[{"id":"w12-Q3-b94c76ceca","text":{"zh":"每项计划都已稳定推进","en":"Every plan is progressing steadily"},"feedback":{"zh":"题目说，原来的任务总是没人做完。开始很多次，不等于每件事都在好好进行。","en":"Tasks are explicitly abandoned; frequent starts do not equal steady progress."}},{"id":"w12-Q3-2ad781e99d","text":{"zh":"开始时很有冲劲，却没坚持做完","en":"Drive lacks continuity and completion"},"feedback":{"zh":"题目说，原来的任务总是没人做完。开始很多次，不等于每件事都在好好进行。","en":"Tasks are explicitly abandoned; frequent starts do not equal steady progress."}}],"correct":"w12-Q3-2ad781e99d","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"现在主动、热情，不等于以后一定能履行承诺；还要看后续行动。 记住：带着热情主动出发，不是“一直停在原地而不行动”。","en":"The lesson teaches pursuit, not a guarantee derived from present energy. Compare: Setting out actively with enthusiasm; this cannot be replaced by “Remaining still without acting”."}],"question":{"id":"w12-R1","prompt":{"zh":"有人积极邀请合作，能仅凭这张牌确认长期承诺吗？","en":"someone eagerly proposes collaboration. Does this card alone establish lasting commitment?"},"options":[{"id":"w12-R1-8aa48793d9","text":{"zh":"不能，现在很主动，不代表以后一定会按约做到","en":"No; energetic action differs from lasting follow-through"},"feedback":{"zh":"现在主动、热情，不等于以后一定能履行承诺；还要看后续行动。","en":"The lesson teaches pursuit, not a guarantee derived from present energy."}},{"id":"w12-R1-371413ef6c","text":{"zh":"能，只要热情就保证长期履约","en":"Yes; enthusiasm guarantees lasting commitment"},"feedback":{"zh":"现在主动、热情，不等于以后一定能履行承诺；还要看后续行动。","en":"The lesson teaches pursuit, not a guarantee derived from present energy."}}],"correct":"w12-R1-8aa48793d9"}},"RA":{"teach":[{"zh":"开始之后，还要安排下次什么时候做、谁负责把作品完成。光是不断开新项目，原来的事情不会自动做完。","en":"After a quick launch, define the next step. Enthusiasm fuels action, but follow-through needs timing and responsibility so repeated starts are not mistaken for completion."}],"question":{"id":"w12-RA","prompt":{"zh":"社团决定立刻做一个短视频，已拍了开头，却没安排剪辑。哪项应用更完整？","en":"A club quickly films the start of a video but has no editing arrangement. Which application is more complete?"},"options":[{"id":"w12-RA-1061ac9460","text":{"zh":"马上再开一个新视频，以新的兴奋替代收尾。","en":"Start another video and replace completion with new excitement."},"feedback":{"zh":"开头已经拍了，现在缺的是剪辑。再开一个视频，也不会让这个作品自动完成。","en":"“Start another video and replace completion with new excitement.” does not address the specific conditions. Follow-through is missing; a new start does not finish the existing work."}},{"id":"w12-RA-29fdeaed1d","text":{"zh":"说清谁来剪辑、什么时候接着做。","en":"Assign editing and schedule the next step."},"feedback":{"zh":"开头已经拍了，现在缺的是剪辑。再开一个视频，也不会让这个作品自动完成。","en":"Follow-through is missing; a new start does not finish the existing work."}}],"correct":"w12-RA-29fdeaed1d"}},"R2":{"teach":[{"zh":"先选一件做完，才能减少反复换方向的情况。继续开新项目，旧任务还是没人收尾。 题目描述的是“开始时很有冲劲，却没坚持做完”，不是“每项计划都已稳定推进”。","en":"Focusing action addresses inconsistency; more starts perpetuate unfinished work. Return to the stated context: “Drive lacks continuity and completion” fits this case; “Every plan is progressing steadily” is unsupported by that context."}],"question":{"id":"w12-R2","prompt":{"zh":"每周都换一个新项目，之前的总是做不完。怎样调整更合适？","en":"You switch projects every week and never finish the earlier ones. What adjustment fits?"},"options":[{"id":"w12-R2-517ddaa2c3","text":{"zh":"再开更多项目维持兴奋","en":"Start more projects to maintain excitement"},"feedback":{"zh":"先选一件做完，才能减少反复换方向的情况。继续开新项目，旧任务还是没人收尾。","en":"Focusing action addresses inconsistency; more starts perpetuate unfinished work."}},{"id":"w12-R2-e0b1a736d6","text":{"zh":"选定一项并安排明确收尾步骤","en":"Choose one project and schedule its completion steps"},"feedback":{"zh":"先选一件做完，才能减少反复换方向的情况。继续开新项目，旧任务还是没人收尾。","en":"Focusing action addresses inconsistency; more starts perpetuate unfinished work."}}],"correct":"w12-R2-e0b1a736d6"}}},"revisit":{"id":"w12-V1","prompt":{"zh":"户外社团积极启动新路线探索。哪句话更贴近权杖骑士的意思？","en":"an outdoor club actively begins exploring a new route. Which fits?"},"options":[{"id":"w12-V1-8dd91b6c56","text":{"zh":"有行动冲劲，同时仍要做准备与后续安排","en":"There is initiative, while preparation and follow-through still matter"},"feedback":{"zh":"这张牌强调积极出发；路线是否合适、需要什么准备，还得实际检查。","en":"Active departure is the theme; real conditions still need separate checking."}},{"id":"w12-V1-14388358e1","text":{"zh":"行动热情本身证明路线没有风险","en":"Enthusiasm itself proves the route has no risks"},"feedback":{"zh":"这张牌强调积极出发；路线是否合适、需要什么准备，还得实际检查。","en":"Active departure is the theme; real conditions still need separate checking."}}],"correct":"w12-V1-8dd91b6c56"},"summary":{"zh":"热情高涨，主动行动，想尽快体验新事物、把事情往前推。 骑士和马正在向前，可以帮助记住主动出发；这里不只是心里有想法。","en":"Move toward a new venture with boldness, energy, and a desire to explore. Momentum needs follow-through; a spirited start alone does not establish lasting commitment."},"cards":["w12"]},{"id":"w13","kind":"card","level":"I","title":{"zh":"权杖王后","en":"Queen of Wands"},"teachings":[{"zh":"自信、热情，愿意展现自己，也能带动周围的人。 自信可以让别人也愿意参与，不需要把所有人的注意力都抢到自己身上。","en":"Express enthusiasm with grounded confidence and invite others into what matters to you. Influence comes through a warm, engaging presence, not a requirement to dominate attention."},{"zh":"王后持权杖与向日葵，坐姿开放，可帮助记住自信的表达。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The seated figure holds a wand and sunflower with an open posture, helping recall confident, welcoming expression. This is a visual association for learning, not proof of an external event."},{"zh":"自信、热情、感染力。 王后在这里强调自信地展现自己、带动别人；权杖对应的火元素帮助记住热情。这种状态不限定性别。","en":"confidence; warmth; engaging presence. The Queen describes inhabiting and nurturing a quality steadily; fire relates to enthusiasm, not a female-only role."}],"application":{"zh":"示范：分享擅长的手工并邀请伙伴试做。可以大方分享自己的喜好，也给别人发言的机会。让人愿意加入，靠的不是压住别人的声音。","en":"Example: share a craft skill and invite others to try. Confident expression and others' participation can coexist; influence need not suppress."},"reversal":{"zh":"案例：原来喜欢分享作品，现在因为担心不够好而完全不敢展示。这里的逆位，是变得不自信，不敢再展示自己。","en":"Case: someone once enjoyed sharing work but now avoids any display out of fear of inadequacy. Here the reversal focuses on diminished confidence."},"visual":{"zh":"王后持权杖与向日葵，坐姿开放，可帮助记住自信的表达。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The seated figure holds a wand and sunflower with an open posture, helping recall confident, welcoming expression. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w13-Q1","prompt":{"zh":"权杖王后的自信和热情，怎样表现出来？","en":"How is confident influence expressed?"},"options":[{"id":"w13-Q1-4e41a2c4e9","text":{"zh":"自然表达热情并邀请别人参与","en":"Express enthusiasm naturally and invite participation"},"feedback":{"zh":"自信可以让别人也愿意参与，不需要把所有人的注意力都抢到自己身上。","en":"Warm confidence can engage others without monopolising attention."}},{"id":"w13-Q1-34a4b6978d","text":{"zh":"必须让所有目光都只看自己","en":"Require all attention to remain on oneself"},"feedback":{"zh":"自信可以让别人也愿意参与，不需要把所有人的注意力都抢到自己身上。","en":"Warm confidence can engage others without monopolising attention."}}],"correct":"w13-Q1-4e41a2c4e9","support":"R1"},"Q2":{"id":"w13-Q2","prompt":{"zh":"你准备组织读书活动。权杖王后在建议位，怎样让自己的热情带动大家？","en":"You are organising a reading group. With the Queen of Wands as advice, how can your enthusiasm encourage participation?"},"options":[{"id":"w13-Q2-7e5adfd0d9","text":{"zh":"把别人的发言都当成抢走光彩","en":"Treat others' contributions as stealing attention"},"feedback":{"zh":"可以大方分享自己的喜好，也给别人发言的机会。让人愿意加入，靠的不是压住别人的声音。","en":"Confident expression and others' participation can coexist; influence need not suppress."}},{"id":"w13-Q2-fdf748cd3d","text":{"zh":"真诚介绍喜欢的书并给别人参与空间","en":"Introduce a loved book warmly and leave space for others"},"feedback":{"zh":"可以大方分享自己的喜好，也给别人发言的机会。让人愿意加入，靠的不是压住别人的声音。","en":"Confident expression and others' participation can coexist; influence need not suppress."}}],"correct":"w13-Q2-fdf748cd3d","support":"RA"},"Q3":{"id":"w13-Q3","prompt":{"zh":"害怕不够好而不再展示作品，这张逆位牌更贴近哪种情况？","en":"Fear of inadequacy stops all sharing. What does this reversal concern?"},"options":[{"id":"w13-Q3-6811084620","text":{"zh":"变得不自信，喜欢的事情也不敢展示了","en":"Reduced confidence is constraining expression"},"feedback":{"zh":"题目说他害怕作品不够好，已经不敢展示，不能理解成他正自在地表达自己。","en":"The stated case is withdrawal, not ease in being seen."}},{"id":"w13-Q3-4910cbae50","text":{"zh":"已经自在地表达并接纳关注","en":"Expression and attention are already comfortable"},"feedback":{"zh":"题目说他害怕作品不够好，已经不敢展示，不能理解成他正自在地表达自己。","en":"The stated case is withdrawal, not ease in being seen."}}],"correct":"w13-Q3-6811084620","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"这里看的是一个人是否自信、热情、愿意带动别人，不是看性别。 记住：自然表达热情并邀请别人参与，不是“必须让所有目光都只看自己”。","en":"This lesson reads court cards as qualities, not gender restrictions. Compare: Express enthusiasm naturally and invite participation; this cannot be replaced by “Require all attention to remain on oneself”."}],"question":{"id":"w13-R1","prompt":{"zh":"一个男性导师热情分享所长，鼓励别人加入。王后角色适用吗？","en":"a male mentor shares skills warmly and invites others in. Can the Queen role apply?"},"options":[{"id":"w13-R1-142089592b","text":{"zh":"不可以，角色只允许女性","en":"No; the role applies only to women"},"feedback":{"zh":"这里看的是一个人是否自信、热情、愿意带动别人，不是看性别。","en":"This lesson reads court cards as qualities, not gender restrictions."}},{"id":"w13-R1-f39d317181","text":{"zh":"可以，描述的是自信热情的方式","en":"Yes; it describes a confident and warm style"},"feedback":{"zh":"这里看的是一个人是否自信、热情、愿意带动别人，不是看性别。","en":"This lesson reads court cards as qualities, not gender restrictions."}}],"correct":"w13-R1-f39d317181"}},"RA":{"teach":[{"zh":"可以大方分享自己喜欢的事，也邀请别人说说。不必包揽所有发言，别人参与也不会让自己变得不重要。","en":"Confidence makes your enthusiasm visible while leaving room for others. Energising an activity does not require all speaking time; inviting others does not diminish your worth."}],"question":{"id":"w13-RA","prompt":{"zh":"你主持手工交流会，新成员想展示自己的小作品。这张牌在建议位时，怎样做更合适？","en":"You host a craft gathering and a newcomer wants to show a small piece. What fits the lesson?"},"options":[{"id":"w13-RA-b87933543a","text":{"zh":"热情介绍自己的经验，也邀请新人分享。","en":"Share your experience warmly and invite the newcomer."},"feedback":{"zh":"邀请新人分享，能让更多人参与。怕被抢走注意力就禁止别人展示，不是这张牌所说的自信。","en":"An engaging presence grows participation; banning expression mistakes confidence for monopolising attention."}},{"id":"w13-RA-6fdacc1c05","text":{"zh":"因怕注意力被分走，禁止别人展示。","en":"Ban other displays to prevent attention being shared."},"feedback":{"zh":"邀请新人分享，能让更多人参与。怕被抢走注意力就禁止别人展示，不是这张牌所说的自信。","en":"“Ban other displays to prevent attention being shared.” does not address the specific conditions. An engaging presence grows participation; banning expression mistakes confidence for monopolising attention."}}],"correct":"w13-RA-b87933543a"}},"R2":{"teach":[{"zh":"先给可信的伙伴看一小部分，就能重新试着分享。要求自己完美之后才能展示，只会继续不敢开口。 题目描述的是“变得不自信，喜欢的事情也不敢展示了”，不是“已经自在地表达并接纳关注”。","en":"A real, modest act can restore participation; a perfection requirement keeps expression closed. Return to the stated context: “Reduced confidence is constraining expression” fits this case; “Expression and attention are already comfortable” is unsupported by that context."}],"question":{"id":"w13-R2","prompt":{"zh":"担心作品不够完美，一直不敢给别人看。可以先试着做什么？","en":"Fear that your work is imperfect keeps you from showing it to anyone. What could you try first?"},"options":[{"id":"w13-R2-bcb761fbb8","text":{"zh":"先向可信伙伴展示一个已完成部分","en":"Share one completed part with a trusted person"},"feedback":{"zh":"先给可信的伙伴看一小部分，就能重新试着分享。要求自己完美之后才能展示，只会继续不敢开口。","en":"A real, modest act can restore participation; a perfection requirement keeps expression closed."}},{"id":"w13-R2-253c77f645","text":{"zh":"必须证明永远完美才允许表达","en":"Allow expression only after proving permanent perfection"},"feedback":{"zh":"先给可信的伙伴看一小部分，就能重新试着分享。要求自己完美之后才能展示，只会继续不敢开口。","en":"A real, modest act can restore participation; a perfection requirement keeps expression closed."}}],"correct":"w13-R2-bcb761fbb8"}}},"revisit":{"id":"w13-V1","prompt":{"zh":"同学主动带动校园园艺活动，也让新人尝试。哪句贴近？","en":"a student energises a gardening group and welcomes newcomers. Which fits?"},"options":[{"id":"w13-V1-da05cfa4c0","text":{"zh":"领导参与必须排除其他人的主意","en":"Engagement requires excluding others' ideas"},"feedback":{"zh":"能带动别人一起做，就是这张牌的热情和感染力，不必排除别人的主意。","en":"The card's engaging quality includes others rather than requiring their exclusion."}},{"id":"w13-V1-858a6ff547","text":{"zh":"自信热情使他人愿意参与","en":"Confident enthusiasm invites participation"},"feedback":{"zh":"能带动别人一起做，就是这张牌的热情和感染力，不必排除别人的主意。","en":"The card's engaging quality includes others rather than requiring their exclusion."}}],"correct":"w13-V1-858a6ff547"},"summary":{"zh":"自信、热情，愿意展现自己，也能带动周围的人。 自信可以让别人也愿意参与，不需要把所有人的注意力都抢到自己身上。","en":"Express enthusiasm with grounded confidence and invite others into what matters to you. Influence comes through a warm, engaging presence, not a requirement to dominate attention."},"cards":["w13"]},{"id":"w14","kind":"card","level":"I","title":{"zh":"权杖国王","en":"King of Wands"},"teachings":[{"zh":"有明确的目标，能带领大家行动，也愿意为自己的决定负责。 要看这个人有没有带大家做事、承担责任，不是看有没有领导头衔。","en":"Give energetic activity a coherent direction and take responsibility for decisions. Leadership is shown through vision and enabling action, not merely by holding a job title."},{"zh":"国王坐在有狮子图案的宝座上持杖，体现稳定的主导姿态。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The seated figure holds a wand on a lion-decorated throne, a cue for an established directing presence. This is a visual association for learning, not proof of an external event."},{"zh":"愿景、领导、担当。 国王在这里强调带领大家、为决定负责；火元素帮助记住热情和行动力。这种做事方式不只属于老板。","en":"vision; leadership; accountability. The King is a role of directing and owning decisions; fire adds vision and initiative, not a literal boss identity."}],"application":{"zh":"示范：明确项目目标和优先级，并协调所需资源。带大家做事，既要说清目标，也要安排人手和资源、处理困难。只喊口号还不够。","en":"Example: clarify goals and priorities and coordinate resources. Leading action needs enabling conditions and accountability, not slogans alone."},"reversal":{"zh":"案例：负责人不断要求扩大项目，却不给资源，也拒绝承担决策后果。这里的逆位，是只提大目标，却不肯提供条件、承担责任。","en":"Case: a leader demands expansion without resources and rejects responsibility for outcomes. Here the reversal concerns vision detached from accountability."},"visual":{"zh":"国王坐在有狮子图案的宝座上持杖，体现稳定的主导姿态。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The seated figure holds a wand on a lion-decorated throne, a cue for an established directing presence. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"w14-Q1","prompt":{"zh":"权杖国王所说的带领大家，重点是什么？","en":"How is leadership understood?"},"options":[{"id":"w14-Q1-a002b084a2","text":{"zh":"只要拥有领导头衔就已足够","en":"A leadership title alone is sufficient"},"feedback":{"zh":"要看这个人有没有带大家做事、承担责任，不是看有没有领导头衔。","en":"The role is shown through responsibility, not a title replacing action."}},{"id":"w14-Q1-758239b0d9","text":{"zh":"说清目标、安排好条件，也为自己的决定负责","en":"Set direction, own decisions, and enable action"},"feedback":{"zh":"要看这个人有没有带大家做事、承担责任，不是看有没有领导头衔。","en":"The role is shown through responsibility, not a title replacing action."}}],"correct":"w14-Q1-758239b0d9","support":"R1"},"Q2":{"id":"w14-Q2","prompt":{"zh":"你要带领大家做一次志愿服务。权杖国王在建议位，哪种做法更合适？","en":"You are leading a volunteer activity. With the King of Wands as advice, which approach fits?"},"options":[{"id":"w14-Q2-7d1cf6e0c3","text":{"zh":"说清目标、分工，并承担协调责任","en":"Clarify goals and roles, taking coordination responsibility"},"feedback":{"zh":"带大家做事，既要说清目标，也要安排人手和资源、处理困难。只喊口号还不够。","en":"Leading action needs enabling conditions and accountability, not slogans alone."}},{"id":"w14-Q2-44c29abfb7","text":{"zh":"只说大目标，把所有困难留给别人","en":"State a grand vision and leave every obstacle to others"},"feedback":{"zh":"带大家做事，既要说清目标，也要安排人手和资源、处理困难。只喊口号还不够。","en":"Leading action needs enabling conditions and accountability, not slogans alone."}}],"correct":"w14-Q2-7d1cf6e0c3","support":"RA"},"Q3":{"id":"w14-Q3","prompt":{"zh":"不断要求扩张却拒绝承担后果，这张逆位牌更贴近哪种情况？","en":"Demanding expansion while rejecting consequences illustrates what here?"},"options":[{"id":"w14-Q3-af78ba3774","text":{"zh":"已经给出充分资源并负责到底","en":"Resources and full accountability are already provided"},"feedback":{"zh":"题目已经说他不给人手和资源、也不肯负责，不能当成他已经安排好了一切。","en":"The case explicitly lacks resources and accountability, not their fulfilment."}},{"id":"w14-Q3-d78a3ce242","text":{"zh":"想主导一切，却不肯承担责任","en":"Directing ambition is detached from responsibility"},"feedback":{"zh":"题目已经说他不给人手和资源、也不肯负责，不能当成他已经安排好了一切。","en":"The case explicitly lacks resources and accountability, not their fulfilment."}}],"correct":"w14-Q3-d78a3ce242","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"这里看的是怎样做事，没有正式职位的人，也可以带大家明确目标、负责把事情做成。 记住：说清目标、安排好条件，也为自己的决定负责，不是“只要拥有领导头衔就已足够”。","en":"Court roles can describe conduct without a formal position. Compare: Set direction, own decisions, and enable action; this cannot be replaced by “A leadership title alone is sufficient”."}],"question":{"id":"w14-R1","prompt":{"zh":"没有管理头衔的人带大家明确方向并负责落实。角色是否可能适用？","en":"someone without a manager title directs and takes responsibility. Can this role apply?"},"options":[{"id":"w14-R1-0ae29a03a6","text":{"zh":"可以，他确实在带大家做事，也肯负责","en":"Yes; behaviour shows direction and accountability"},"feedback":{"zh":"这里看的是怎样做事，没有正式职位的人，也可以带大家明确目标、负责把事情做成。","en":"Court roles can describe conduct without a formal position."}},{"id":"w14-R1-854daebbf6","text":{"zh":"不可以，没有头衔就不能体现","en":"No; it cannot apply without the title"},"feedback":{"zh":"这里看的是怎样做事，没有正式职位的人，也可以带大家明确目标、负责把事情做成。","en":"Court roles can describe conduct without a formal position."}}],"correct":"w14-R1-0ae29a03a6"}},"RA":{"teach":[{"zh":"不仅要让大家知道目标是什么，还要安排好人手和资源，让事情能做起来。先做什么、谁来做、需要什么，都要安排；遇到困难也要负责，不能只喊口号。","en":"A vision tells people where to go and must enable the work. Priorities, resources, and accountability make leadership practical; a slogan alone does not do this."}],"question":{"id":"w14-RA","prompt":{"zh":"带领志愿团队筹办周末活动，大家认同目标但任务无人负责。下一步怎样应用？","en":"A volunteer team agrees on a weekend event's goal but no one owns the tasks. What applies next?"},"options":[{"id":"w14-RA-e7d8361f6a","text":{"zh":"再次喊出更大目标，仍不确认任务条件。","en":"Announce a bigger goal without arranging tasks or conditions."},"feedback":{"zh":"大家已经认同目标，现在缺的是谁来做、需要什么条件。再喊一遍目标，任务还是没人负责。","en":"“Announce a bigger goal without arranging tasks or conditions.” does not address the specific conditions. The vision needs organisation and accountability; repeating it does not assign work."}},{"id":"w14-RA-57e87da0de","text":{"zh":"明确任务与优先级，确认负责人和所需条件。","en":"Define tasks and priorities, confirm owners and resources."},"feedback":{"zh":"大家已经认同目标，现在缺的是谁来做、需要什么条件。再喊一遍目标，任务还是没人负责。","en":"The vision needs organisation and accountability; repeating it does not assign work."}}],"correct":"w14-RA-57e87da0de"}},"R2":{"teach":[{"zh":"先确认人手、预算和责任，再决定做多大。只提高目标，不会让缺少的条件自动出现。 题目描述的是“想主导一切，却不肯承担责任”，不是“已经给出充分资源并负责到底”。","en":"Reconnect vision to conditions and accountability to address the disconnect. Return to the stated context: “Directing ambition is detached from responsibility” fits this case; “Resources and full accountability are already provided” is unsupported by that context."}],"question":{"id":"w14-R2","prompt":{"zh":"负责人要求扩大活动规模，却没有给预算。答应之前，先做什么更合适？","en":"An organiser wants a larger event without providing a budget. What should happen before committing?"},"options":[{"id":"w14-R2-47a506ed17","text":{"zh":"继续提高目标而不处理条件","en":"Raise the target again without addressing conditions"},"feedback":{"zh":"先确认人手、预算和责任，再决定做多大。只提高目标，不会让缺少的条件自动出现。","en":"Reconnect vision to conditions and accountability to address the disconnect."}},{"id":"w14-R2-f65bea614c","text":{"zh":"先确认资源与责任，再承诺规模","en":"Confirm resources and responsibility before committing scale"},"feedback":{"zh":"先确认人手、预算和责任，再决定做多大。只提高目标，不会让缺少的条件自动出现。","en":"Reconnect vision to conditions and accountability to address the disconnect."}}],"correct":"w14-R2-f65bea614c"}}},"revisit":{"id":"w14-V1","prompt":{"zh":"剧社负责人明确演出方向，也处理时间和场地冲突。哪句贴近？","en":"a theatre organiser sets direction and resolves schedule and venue conflicts. Which fits?"},"options":[{"id":"w14-V1-aa5f08f327","text":{"zh":"说清目标、安排工作，并负责把事情做下去","en":"Vision becomes action through responsibility and organisation"},"feedback":{"zh":"除了说清演出方向，他还解决时间和场地的冲突，这正是带领大家把事情做下去。","en":"The lesson includes direction and execution; practical coordination is part of leadership."}},{"id":"w14-V1-71b70875c3","text":{"zh":"只要方向响亮就无须协调现实","en":"A stirring vision removes any need for coordination"},"feedback":{"zh":"除了说清演出方向，他还解决时间和场地的冲突，这正是带领大家把事情做下去。","en":"The lesson includes direction and execution; practical coordination is part of leadership."}}],"correct":"w14-V1-aa5f08f327"},"summary":{"zh":"有明确的目标，能带领大家行动，也愿意为自己的决定负责。 要看这个人有没有带大家做事、承担责任，不是看有没有领导头衔。","en":"Give energetic activity a coherent direction and take responsibility for decisions. Leadership is shown through vision and enabling action, not merely by holding a job title."},"cards":["w14"]},{"id":"c01","kind":"card","level":"I","title":{"zh":"圣杯王牌","en":"Ace of Cups"},"teachings":[{"zh":"开始有了新的感动、关心或创作灵感，也愿意接纳这些感受。 刚开始有感情，只说明新的感受出现了，还不代表两个人已经建立稳定关系。","en":"A new feeling, capacity for care, or creative receptivity begins to emerge. Notice and receive it without treating a fresh feeling as an established relationship."},{"zh":"云中手托着溢水的杯，帮助记住感受正在涌现。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A hand holds an overflowing cup above water, helping recall feelings becoming available and flowing outward. This is a visual association for learning, not proof of an external event."},{"zh":"新的感受、愿意接纳。 圣杯对应水元素，和感受、情感有关；王牌帮助记住新的开始。新的感受也可能来自创作，不一定是恋爱。","en":"emerging feeling; receptivity. Cups relate to water and feeling; the Ace recalls an emerging opening, not a rule that water always means romance."}],"application":{"zh":"示范：发现自己很感谢对方，就用合适的话表达出来。可以先感受这份触动、试着表达，但它不能保证未来的关系会怎样。","en":"Example: recognise gratitude and express it appropriately. The lesson welcomes an emerging feeling without making it a guarantee about the future."},"reversal":{"zh":"案例：对朋友有感谢，却一直否认自己想表达关怀。这里的逆位，是明明有关心，却压着不愿表达。","en":"Case: gratitude toward a friend is felt but the wish to express care is repeatedly denied. Here the reversal concerns feelings being held back."},"visual":{"zh":"云中手托着溢水的杯，帮助记住感受正在涌现。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A hand holds an overflowing cup above water, helping recall feelings becoming available and flowing outward. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c01-Q1","prompt":{"zh":"杯里溢出的水，可以帮助记住什么？","en":"What does the overflowing cup help recall here?"},"options":[{"id":"c01-Q1-2b13ae570a","text":{"zh":"开始有了新的感动，也想关心别人","en":"New feeling and care begin to emerge"},"feedback":{"zh":"刚开始有感情，只说明新的感受出现了，还不代表两个人已经建立稳定关系。","en":"Emerging feeling is a beginning, not proof of an established stable relationship."}},{"id":"c01-Q1-deb6017d47","text":{"zh":"稳定关系已经完全建立","en":"A stable relationship is fully established"},"feedback":{"zh":"刚开始有感情，只说明新的感受出现了，还不代表两个人已经建立稳定关系。","en":"Emerging feeling is a beginning, not proof of an established stable relationship."}}],"correct":"c01-Q1-2b13ae570a","support":"R1"},"Q2":{"id":"c01-Q2","prompt":{"zh":"第一次被一首诗深深打动。圣杯王牌在建议位，怎样对待这份感受更合适？","en":"A poem moves you deeply for the first time. With the Ace of Cups as advice, which response fits this feeling?"},"options":[{"id":"c01-Q2-03ef8081cc","text":{"zh":"立刻认定所有未来情感都确定了","en":"Immediately treat every future feeling as settled"},"feedback":{"zh":"可以先感受这份触动、试着表达，但它不能保证未来的关系会怎样。","en":"The lesson welcomes an emerging feeling without making it a guarantee about the future."}},{"id":"c01-Q2-4e168b7d1f","text":{"zh":"留意这份感动，试着把它表达出来","en":"Receive the feeling and try expressing it simply"},"feedback":{"zh":"可以先感受这份触动、试着表达，但它不能保证未来的关系会怎样。","en":"The lesson welcomes an emerging feeling without making it a guarantee about the future."}}],"correct":"c01-Q2-4e168b7d1f","support":"RA"},"Q3":{"id":"c01-Q3","prompt":{"zh":"一直压住想感谢朋友的感受，这张逆位牌更贴近哪种情况？","en":"Holding back gratitude toward a friend illustrates what here?"},"options":[{"id":"c01-Q3-d67f2a8c58","text":{"zh":"明明有感受，却压着不说、也不愿承认","en":"Feeling is difficult to receive and express"},"feedback":{"zh":"他明明很感谢朋友，只是压着不肯说，不能因此认定他没有感受。","en":"Gratitude is explicitly present; the block is in receiving and expressing it, not its existence."}},{"id":"c01-Q3-297347c934","text":{"zh":"完全没有任何感受出现","en":"No feeling exists at all"},"feedback":{"zh":"他明明很感谢朋友，只是压着不肯说，不能因此认定他没有感受。","en":"Gratitude is explicitly present; the block is in receiving and expressing it, not its existence."}}],"correct":"c01-Q3-d67f2a8c58","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"开始关心一个人，和两个人已经作出长期承诺，是两回事。是否有承诺，要看双方实际说了什么、做了什么。 记住：开始有了新的感动，也想关心别人，不是“稳定关系已经完全建立”。","en":"Emerging care differs from mutual commitment, which needs real evidence. Compare: New feeling and care begin to emerge; this cannot be replaced by “A stable relationship is fully established”."}],"question":{"id":"c01-R1","prompt":{"zh":"第一次感到愿意关心新伙伴，能确认什么？","en":"care for a new companion first emerges. What is supported?"},"options":[{"id":"c01-R1-aab10beb55","text":{"zh":"两人已经作出长期承诺","en":"Both have made a lasting commitment"},"feedback":{"zh":"开始关心一个人，和两个人已经作出长期承诺，是两回事。是否有承诺，要看双方实际说了什么、做了什么。","en":"Emerging care differs from mutual commitment, which needs real evidence."}},{"id":"c01-R1-75a3099e60","text":{"zh":"开始想关心对方","en":"Care is beginning to emerge"},"feedback":{"zh":"开始关心一个人，和两个人已经作出长期承诺，是两回事。是否有承诺，要看双方实际说了什么、做了什么。","en":"Emerging care differs from mutual commitment, which needs real evidence."}}],"correct":"c01-R1-75a3099e60"}},"RA":{"teach":[{"zh":"发现自己被打动了，可以说一句感谢，写一点东西，或关心对方。不必刚有感受，就决定两个人的长期关系。","en":"Receive a new feeling by acknowledging it and finding a small fitting expression. This can be gratitude, creation, or care, without an immediate long-term commitment."}],"question":{"id":"c01-RA","prompt":{"zh":"听到朋友帮助自己的细节后很感动，这张牌在建议位时，怎样做更合适？","en":"Hearing how a friend helped you feels moving. How can this advice apply?"},"options":[{"id":"c01-RA-d9d3b2fbe1","text":{"zh":"用一句真诚的话，把感谢说出来。","en":"Acknowledge gratitude and respond sincerely."},"feedback":{"zh":"一句真诚的感谢，就能表达现在的感动，不需要先决定一辈子的关系。","en":"A simple expression can meet the present feeling; gratitude needs no prior lifelong arrangement."}},{"id":"c01-RA-0b3cc01404","text":{"zh":"必须先确认终身关系，才允许表达感谢。","en":"Require lifelong commitment before expressing thanks."},"feedback":{"zh":"一句真诚的感谢，就能表达现在的感动，不需要先决定一辈子的关系。","en":"“Require lifelong commitment before expressing thanks.” does not address the specific conditions. A simple expression can meet the present feeling; gratitude needs no prior lifelong arrangement."}}],"correct":"c01-RA-d9d3b2fbe1"}},"R2":{"teach":[{"zh":"感谢说不出口，不代表没有感谢。先承认自己想表达，再试着说一句简单的话。 题目描述的是“明明有感受，却压着不说、也不愿承认”，不是“完全没有任何感受出现”。","en":"Difficulty expressing is not absence of feeling; acknowledging it addresses the block. Return to the stated context: “Feeling is difficult to receive and express” fits this case; “No feeling exists at all” is unsupported by that context."}],"question":{"id":"c01-R2","prompt":{"zh":"很想感谢朋友，却总说不出口。可以先试着做什么？","en":"You want to thank a friend but cannot get the words out. What could you try first?"},"options":[{"id":"c01-R2-5bf6236b83","text":{"zh":"先承认自己想感谢对方，再用一句简单的话说出来","en":"Acknowledge gratitude and choose a simple expression"},"feedback":{"zh":"感谢说不出口，不代表没有感谢。先承认自己想表达，再试着说一句简单的话。","en":"Difficulty expressing is not absence of feeling; acknowledging it addresses the block."}},{"id":"c01-R2-b1b1fdf3a3","text":{"zh":"认为说不出就证明从未在意","en":"Treat difficulty speaking as proof of never caring"},"feedback":{"zh":"感谢说不出口，不代表没有感谢。先承认自己想表达，再试着说一句简单的话。","en":"Difficulty expressing is not absence of feeling; acknowledging it addresses the block."}}],"correct":"c01-R2-5bf6236b83"}}},"revisit":{"id":"c01-V1","prompt":{"zh":"重新接触绘画时涌起温柔的创作感受。哪句贴近？","en":"returning to painting brings tender creative feeling. Which fits?"},"options":[{"id":"c01-V1-87a5bbab7f","text":{"zh":"圣杯只能解释恋爱所以不适用","en":"Cups only mean romance and cannot apply"},"feedback":{"zh":"被一幅画或一首诗打动，也属于圣杯所说的感受，不一定是在谈恋爱。","en":"Cups also include feeling and creative receptivity, not romance alone."}},{"id":"c01-V1-533d116663","text":{"zh":"开始有了新的感受和创作灵感","en":"A new emotional and creative experience is opening"},"feedback":{"zh":"被一幅画或一首诗打动，也属于圣杯所说的感受，不一定是在谈恋爱。","en":"Cups also include feeling and creative receptivity, not romance alone."}}],"correct":"c01-V1-533d116663"},"summary":{"zh":"开始有了新的感动、关心或创作灵感，也愿意接纳这些感受。 刚开始有感情，只说明新的感受出现了，还不代表两个人已经建立稳定关系。","en":"A new feeling, capacity for care, or creative receptivity begins to emerge. Notice and receive it without treating a fresh feeling as an established relationship."},"cards":["c01"]},{"id":"c02","kind":"card","level":"I","title":{"zh":"圣杯二","en":"Two of Cups"},"teachings":[{"zh":"两个人愿意交流，也愿意回应彼此，关系中有相互的好感和认可。 两个人都愿意回应，才算相互认可。只有自己愿意，不能代表对方也答应了。","en":"Two parties are willing to respond to one another and establish a mutually recognised connection. This can describe partnership as well as affection; mutuality is the central condition."},{"zh":"两个人面对面举杯，可以帮助记住彼此回应，而不是只有一方主动。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Two people face each other and raise cups, a direct memory cue for reciprocal exchange. This is a visual association for learning, not proof of an external event."},{"zh":"相互回应、好感、合作。 水关注感受与回应；二在本牌帮助记双向关系，但不自动保证婚姻或永远和谐。","en":"reciprocity; connection; partnership. Water concerns feeling and response; two here recalls mutual connection, not a guarantee of marriage or permanent harmony."}],"application":{"zh":"示范：合作双方愿意沟通，继续谈清约定。双方都愿意合作，也还要谈清各自需要什么、愿意做什么，不能只靠好感替对方决定。","en":"Example: willing partners clarify their agreement. Response becomes practical through communication; goodwill does not replace checking with the other party."},"reversal":{"zh":"案例：合作时一方不断提议，另一方从不回应，也不确认约定。这里的逆位，是总由一方主动，另一方却没有回应。","en":"Case: one partner repeatedly proposes arrangements while the other neither replies nor confirms. Here the reversal concerns unequal response."},"visual":{"zh":"两个人面对面举杯，可以帮助记住彼此回应，而不是只有一方主动。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Two people face each other and raise cups, a direct memory cue for reciprocal exchange. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c02-Q1","prompt":{"zh":"两个人面对面举杯，可以帮助记住关系中的哪一点？","en":"What is the key condition recalled by the two facing figures?"},"options":[{"id":"c02-Q1-86f533433b","text":{"zh":"只要一方愿意就已形成双向共识","en":"One willing party alone establishes mutual agreement"},"feedback":{"zh":"两个人都愿意回应，才算相互认可。只有自己愿意，不能代表对方也答应了。","en":"Mutuality needs participation from both sides; one person's wish is not agreement from both."}},{"id":"c02-Q1-0094522134","text":{"zh":"双方都有回应和交流意愿","en":"Both parties are willing to respond and communicate"},"feedback":{"zh":"两个人都愿意回应，才算相互认可。只有自己愿意，不能代表对方也答应了。","en":"Mutuality needs participation from both sides; one person's wish is not agreement from both."}}],"correct":"c02-Q1-0094522134","support":"R1"},"Q2":{"id":"c02-Q2","prompt":{"zh":"两位同学都想合办活动。圣杯二在建议位，下一步怎样沟通更合适？","en":"Two students both want to organise an event together. With the Two of Cups as advice, how can they communicate next?"},"options":[{"id":"c02-Q2-ba623ad134","text":{"zh":"互相表达需求并确认分工","en":"Exchange needs and confirm responsibilities"},"feedback":{"zh":"双方都愿意合作，也还要谈清各自需要什么、愿意做什么，不能只靠好感替对方决定。","en":"Response becomes practical through communication; goodwill does not replace checking with the other party."}},{"id":"c02-Q2-ffc58c2fef","text":{"zh":"因有好感就不必询问对方需求","en":"Skip asking about needs because goodwill exists"},"feedback":{"zh":"双方都愿意合作，也还要谈清各自需要什么、愿意做什么，不能只靠好感替对方决定。","en":"Response becomes practical through communication; goodwill does not replace checking with the other party."}}],"correct":"c02-Q2-ba623ad134","support":"RA"},"Q3":{"id":"c02-Q3","prompt":{"zh":"一方提议、另一方长期不回应，这张逆位牌更贴近哪种情况？","en":"One side proposes and the other does not respond. What is this reversal?"},"options":[{"id":"c02-Q3-f4dd24a2aa","text":{"zh":"双方共识已清楚形成","en":"Mutual agreement is already clear"},"feedback":{"zh":"对方一直没答复，就还不知道他愿不愿意，不能当成两个人已经商量好了。","en":"The second party's response is absent, so agreement is not established."}},{"id":"c02-Q3-bc36b3a99c","text":{"zh":"总是一方主动，另一方没有回应","en":"Exchange is unbalanced and not reciprocal"},"feedback":{"zh":"对方一直没答复，就还不知道他愿不愿意，不能当成两个人已经商量好了。","en":"The second party's response is absent, so agreement is not established."}}],"correct":"c02-Q3-bc36b3a99c","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"重点是双方愿意交流、回应。朋友或合作伙伴也可以这样相处，不一定非得是恋人。 记住：双方都有回应和交流意愿，不是“只要一方愿意就已形成双向共识”。","en":"Reciprocity is central, not romantic status. Compare: Both parties are willing to respond and communicate; this cannot be replaced by “One willing party alone establishes mutual agreement”."}],"question":{"id":"c02-R1","prompt":{"zh":"两家社团互相听取需求并确认合作。圣杯二适用吗？","en":"two clubs listen and confirm cooperation. Can the Two of Cups apply?"},"options":[{"id":"c02-R1-bace1a0bac","text":{"zh":"可以，合作也需要双方交流、彼此回应","en":"Yes; mutual connection also includes partnership"},"feedback":{"zh":"重点是双方愿意交流、回应。朋友或合作伙伴也可以这样相处，不一定非得是恋人。","en":"Reciprocity is central, not romantic status."}},{"id":"c02-R1-233e05698f","text":{"zh":"不可以，必须是恋人才适用","en":"No; only romantic partners qualify"},"feedback":{"zh":"重点是双方愿意交流、回应。朋友或合作伙伴也可以这样相处，不一定非得是恋人。","en":"Reciprocity is central, not romantic status."}}],"correct":"c02-R1-bace1a0bac"}},"RA":{"teach":[{"zh":"先听听彼此想要什么，再确认两个人愿不愿意一起做。即使互有好感，也不能把自己喜欢的安排当成双方已经说好的事。","en":"Reciprocal exchange means hearing each person's needs and checking shared willingness. Goodwill does not turn one person's preference into a joint agreement."}],"question":{"id":"c02-RA","prompt":{"zh":"两位同学都愿意合办展览，但一人想周末、一人只有平日晚间有空。怎样应用？","en":"Two students want a joint exhibition, but one prefers weekends and the other is free only on weekday evenings. What fits?"},"options":[{"id":"c02-RA-fcab4b9b72","text":{"zh":"因为都愿合作，就按自己喜欢的日期宣布定案。","en":"Declare your preferred date final because both want to collaborate."},"feedback":{"zh":"两个人都想合作，但有空的时间不同，还得一起商量。都愿意，并不代表时间自动合适。","en":"“Declare your preferred date final because both want to collaborate.” does not address the specific conditions. Willingness still needs a mutually confirmed arrangement; goodwill does not erase practical differences."}},{"id":"c02-RA-1675c56b78","text":{"zh":"互相说明条件，再确认双方可接受的安排。","en":"Exchange constraints and confirm an arrangement both accept."},"feedback":{"zh":"两个人都想合作，但有空的时间不同，还得一起商量。都愿意，并不代表时间自动合适。","en":"Willingness still needs a mutually confirmed arrangement; goodwill does not erase practical differences."}}],"correct":"c02-RA-1675c56b78"}},"R2":{"teach":[{"zh":"要问清对方愿不愿意参与，不能只凭自己想合作，就替对方答应。 题目描述的是“总是一方主动，另一方没有回应”，不是“双方共识已清楚形成”。","en":"The other's response must be checked; a wish cannot substitute for their agreement. Return to the stated context: “Exchange is unbalanced and not reciprocal” fits this case; “Mutual agreement is already clear” is unsupported by that context."}],"question":{"id":"c02-R2","prompt":{"zh":"总是自己联系，对方从不确认安排。先做什么，才能知道对方愿不愿意参与？","en":"You always initiate contact, but the other person never confirms plans. What can you do to find out whether they want to participate?"},"options":[{"id":"c02-R2-f3a6ca3c6f","text":{"zh":"把自己的愿望直接记作对方同意","en":"Record one's own wish as the other's consent"},"feedback":{"zh":"要问清对方愿不愿意参与，不能只凭自己想合作，就替对方答应。","en":"The other's response must be checked; a wish cannot substitute for their agreement."}},{"id":"c02-R2-8607c0b699","text":{"zh":"明确询问对方是否愿意参与","en":"Ask clearly whether the other person wants to participate"},"feedback":{"zh":"要问清对方愿不愿意参与，不能只凭自己想合作，就替对方答应。","en":"The other's response must be checked; a wish cannot substitute for their agreement."}}],"correct":"c02-R2-8607c0b699"}}},"revisit":{"id":"c02-V1","prompt":{"zh":"导师与学生都愿意倾听，谈清合作期待。哪句贴近？","en":"mentor and student listen and clarify expectations. Which fits?"},"options":[{"id":"c02-V1-55e6763d8b","text":{"zh":"双方愿意听取意见、回应彼此，有助于一起做事","en":"Mutual recognition and response support cooperation"},"feedback":{"zh":"彼此愿意听取意见，有助于合作；以后有了分歧，仍然需要继续商量。","en":"Reciprocity supports connection without eliminating future adjustments."}},{"id":"c02-V1-b2f98f1137","text":{"zh":"彼此认可就保证永远没有分歧","en":"Recognition guarantees no future disagreement"},"feedback":{"zh":"彼此愿意听取意见，有助于合作；以后有了分歧，仍然需要继续商量。","en":"Reciprocity supports connection without eliminating future adjustments."}}],"correct":"c02-V1-55e6763d8b"},"summary":{"zh":"两个人愿意交流，也愿意回应彼此，关系中有相互的好感和认可。 两个人都愿意回应，才算相互认可。只有自己愿意，不能代表对方也答应了。","en":"Two parties are willing to respond to one another and establish a mutually recognised connection. This can describe partnership as well as affection; mutuality is the central condition."},"cards":["c02"]},{"id":"c03","kind":"card","level":"I","title":{"zh":"圣杯三","en":"Three of Cups"},"teachings":[{"zh":"和朋友一起分享喜悦，在相聚中得到关心、鼓励和支持。 画面上的三个人正在举杯庆祝。要记住的是朋友相聚的喜悦，不能只数出三个人就认定有第三者。","en":"Share joy and receive emotional support in friendship or community. The group matters because its members genuinely participate in one another’s experience."},{"zh":"三个人举杯相聚，脚边有果实，呈现共同庆祝。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Three people raise cups together among fruit, helping recall shared celebration and friendship. This is a visual association for learning, not proof of an external event."},{"zh":"友谊、分享喜悦、群体支持。 水关联情感支持；三在这里提示多人共享，不根据人数判断现实第三者。","en":"friendship; shared joy; group support. Water relates to emotional support; three here recalls shared participation, not evidence of an affair."}],"application":{"zh":"示范：找可信朋友分享经历。和信任的朋友分享这次经历，可以一起庆祝，也能得到鼓励；把所有感受都隔绝起来，就失去了这种交流。","en":"Example: share an experience with trusted friends. The lesson emphasises sharing with a trusted group rather than cutting off support."},"reversal":{"zh":"案例：聚会很多，却每次都被打断和忽视，没人愿意认真听。这里的逆位，是聚会虽然多，却没有人真正关心、倾听。","en":"Case: gatherings are frequent but a person is interrupted and ignored. Here the reversal concerns social activity without genuine support."},"visual":{"zh":"三个人举杯相聚，脚边有果实，呈现共同庆祝。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Three people raise cups together among fruit, helping recall shared celebration and friendship. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c03-Q1","prompt":{"zh":"几个人一起举杯，可以帮助记住什么？","en":"What does gathering with raised cups help recall here?"},"options":[{"id":"c03-Q1-0e70b60921","text":{"zh":"朋友之间分享喜悦与支持","en":"Friends share joy and support"},"feedback":{"zh":"画面上的三个人正在举杯庆祝。要记住的是朋友相聚的喜悦，不能只数出三个人就认定有第三者。","en":"The figures show shared celebration; their number does not establish an actual relationship event."}},{"id":"c03-Q1-288aaaead7","text":{"zh":"只要出现三人就确定有第三者","en":"Three figures establish a romantic affair"},"feedback":{"zh":"画面上的三个人正在举杯庆祝。要记住的是朋友相聚的喜悦，不能只数出三个人就认定有第三者。","en":"The figures show shared celebration; their number does not establish an actual relationship event."}}],"correct":"c03-Q1-0e70b60921","support":"R1"},"Q2":{"id":"c03-Q2","prompt":{"zh":"终于完成了一门很难的课程。圣杯三在建议位，哪种做法更合适？","en":"You have finished a difficult course. With the Three of Cups as advice, which response fits?"},"options":[{"id":"c03-Q2-7a0d762c6b","text":{"zh":"把所有感受隔绝以避免任何分享","en":"Exclude all feeling to prevent any sharing"},"feedback":{"zh":"和信任的朋友分享这次经历，可以一起庆祝，也能得到鼓励；把所有感受都隔绝起来，就失去了这种交流。","en":"The lesson emphasises sharing with a trusted group rather than cutting off support."}},{"id":"c03-Q2-5c7dc35ab8","text":{"zh":"与支持自己的伙伴一起庆祝","en":"Celebrate with supportive companions"},"feedback":{"zh":"和信任的朋友分享这次经历，可以一起庆祝，也能得到鼓励；把所有感受都隔绝起来，就失去了这种交流。","en":"The lesson emphasises sharing with a trusted group rather than cutting off support."}}],"correct":"c03-Q2-5c7dc35ab8","support":"RA"},"Q3":{"id":"c03-Q3","prompt":{"zh":"聚会很多却没人倾听，这张逆位牌更贴近哪种情况？","en":"Frequent gatherings lack listening. What does this reversal emphasise?"},"options":[{"id":"c03-Q3-7ff1ac0355","text":{"zh":"聚会很热闹，自己却没有得到关心和支持","en":"Social activity is not providing genuine support"},"feedback":{"zh":"有没有支持，要看朋友是否愿意听你说、关心你的处境，不是看参加了多少次聚会。","en":"Support depends on interaction quality; frequency does not replace being heard."}},{"id":"c03-Q3-6313fe2e47","text":{"zh":"聚会次数已经证明关系有支持","en":"Frequency of gatherings proves support"},"feedback":{"zh":"有没有支持，要看朋友是否愿意听你说、关心你的处境，不是看参加了多少次聚会。","en":"Support depends on interaction quality; frequency does not replace being heard."}}],"correct":"c03-Q3-7ff1ac0355","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"题目说三位同事在互相祝贺，可以概括为一起高兴，不能因为有三个人就认定有感情纠纷。 记住：朋友之间分享喜悦与支持，不是“只要出现三人就确定有第三者”。","en":"The stated interaction is congratulations; three participants do not imply romantic conflict. Compare: Friends share joy and support; this cannot be replaced by “Three figures establish a romantic affair”."}],"question":{"id":"c03-R1","prompt":{"zh":"三位同事互相祝贺项目完成。可以概括什么？","en":"three colleagues congratulate each other on completion. What is supported?"},"options":[{"id":"c03-R1-fdc4b98ddd","text":{"zh":"必然存在恋爱纠纷","en":"A romantic conflict must exist"},"feedback":{"zh":"题目说三位同事在互相祝贺，可以概括为一起高兴，不能因为有三个人就认定有感情纠纷。","en":"The stated interaction is congratulations; three participants do not imply romantic conflict."}},{"id":"c03-R1-aa76259da3","text":{"zh":"大家一起为做成的事高兴","en":"Shared joy in a group"},"feedback":{"zh":"题目说三位同事在互相祝贺，可以概括为一起高兴，不能因为有三个人就认定有感情纠纷。","en":"The stated interaction is congratulations; three participants do not imply romantic conflict."}}],"correct":"c03-R1-aa76259da3"}},"RA":{"teach":[{"zh":"不用勉强自己参加更多聚会。找信任、愿意听你说话的人，聊聊经历，一起开心、互相鼓励，比人数多少更重要。","en":"Sharing is not forcing more attendance; it exchanges experience, joy, and support with trusted people. Listening and participation provide support, not the size of a gathering."}],"question":{"id":"c03-RA","prompt":{"zh":"完成一次困难演讲，想和支持自己的朋友庆祝。这张牌在建议位时，怎样做更合适？","en":"After a difficult presentation, you want to celebrate with supportive friends. What fits?"},"options":[{"id":"c03-RA-2f4890bb65","text":{"zh":"找愿意倾听的伙伴分享这次经历和喜悦。","en":"Share the experience and joy with friends who listen."},"feedback":{"zh":"找愿意听的朋友分享，才能一起为这次经历高兴。人再多，如果没人愿意交流，也没有得到这种支持。","en":"The goal is shared support; a large crowd cannot replace mutual participation."}},{"id":"c03-RA-d9b091944d","text":{"zh":"只追求参加人数，不让任何人交流真实经历。","en":"Maximise attendance while allowing no real exchange."},"feedback":{"zh":"找愿意听的朋友分享，才能一起为这次经历高兴。人再多，如果没人愿意交流，也没有得到这种支持。","en":"“Maximise attendance while allowing no real exchange.” does not address the specific conditions. The goal is shared support; a large crowd cannot replace mutual participation."}}],"correct":"c03-RA-2f4890bb65"}},"R2":{"teach":[{"zh":"需要的是找愿意听你说话的朋友。多参加几次仍然没人倾听的聚会，并不会解决问题。 题目描述的是“聚会很热闹，自己却没有得到关心和支持”，不是“聚会次数已经证明关系有支持”。","en":"Change the quality of support rather than merely increase superficial contact. Return to the stated context: “Social activity is not providing genuine support” fits this case; “Frequency of gatherings proves support” is unsupported by that context."}],"question":{"id":"c03-R2","prompt":{"zh":"每次聚会都没人认真听自己说话。想得到朋友的支持，怎样做更合适？","en":"Nobody listens to you at these gatherings. What could help you find support from friends?"},"options":[{"id":"c03-R2-7f15df1f5f","text":{"zh":"选择愿意倾听的朋友交流","en":"Seek conversation with friends who listen"},"feedback":{"zh":"需要的是找愿意听你说话的朋友。多参加几次仍然没人倾听的聚会，并不会解决问题。","en":"Change the quality of support rather than merely increase superficial contact."}},{"id":"c03-R2-c182d42a3a","text":{"zh":"只增加相同聚会次数就认定解决","en":"Add more identical gatherings and call it solved"},"feedback":{"zh":"需要的是找愿意听你说话的朋友。多参加几次仍然没人倾听的聚会，并不会解决问题。","en":"Change the quality of support rather than merely increase superficial contact."}}],"correct":"c03-R2-7f15df1f5f"}}},"revisit":{"id":"c03-V1","prompt":{"zh":"读书伙伴彼此分享心得和鼓励。哪句贴近？","en":"reading partners exchange reflections and encouragement. Which fits?"},"options":[{"id":"c03-V1-1691748ab3","text":{"zh":"只有正式庆典才能体现这张牌","en":"Only a formal ceremony can express this card"},"feedback":{"zh":"平时一起读书、交流心得，也能互相鼓励，不一定要有正式庆典。","en":"Group support can occur in everyday gatherings, not only formal ceremonies."}},{"id":"c03-V1-e140bb05db","text":{"zh":"在熟悉的伙伴中分享经历、得到支持","en":"A community offers sharing and emotional support"},"feedback":{"zh":"平时一起读书、交流心得，也能互相鼓励，不一定要有正式庆典。","en":"Group support can occur in everyday gatherings, not only formal ceremonies."}}],"correct":"c03-V1-e140bb05db"},"summary":{"zh":"和朋友一起分享喜悦，在相聚中得到关心、鼓励和支持。 画面上的三个人正在举杯庆祝。要记住的是朋友相聚的喜悦，不能只数出三个人就认定有第三者。","en":"Share joy and receive emotional support in friendship or community. The group matters because its members genuinely participate in one another’s experience."},"cards":["c03"]},{"id":"c04","kind":"card","level":"I","title":{"zh":"圣杯四","en":"Four of Cups"},"teachings":[{"zh":"心思放在自己身上，对眼前的事或新的邀请暂时提不起兴趣，也不太想回应。 旁边明明有一只杯子递过来，人物却抱着双臂，没有伸手。可以这样记：有机会出现，但自己暂时不想回应。","en":"Attention turns inward and engagement with available opportunities is low. Distinguish needing reflection from overlooking an offer; lack of response does not prove that no opportunity exists."},{"zh":"树下抱臂者面对三杯，侧面还有递来的第四杯。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A folded-armed figure sits beneath a tree with three cups ahead and another offered from the side, a cue for offers and limited response. This is a visual association for learning, not proof of an external event."},{"zh":"提不起兴趣、独处思考、不想回应。 圣杯对应水元素，和感受有关；四可以帮助记住暂时停下来的状态。是在独处思考，还是对事情冷淡，要看具体情况。","en":"withdrawn interest; reflection; low engagement. Water concerns feeling; four can help recall a held state, but reflection versus disengagement needs context."}],"application":{"zh":"示范：对邀请无感时先分清疲惫还是不适合。自己现在有没有兴趣，和机会本身适不适合，是两件事。提不起劲，不代表外面没有机会。","en":"Example: distinguish fatigue from poor fit when an invitation feels unappealing. Internal interest and external opportunity need separate consideration."},"reversal":{"zh":"案例：休整后开始愿意回复邀请，重新评估之前忽略的机会。这里的逆位，是又愿意了解活动、回复邀请了。","en":"Case: after a pause, invitations receive replies and overlooked opportunities are reconsidered. Here the reversal means renewed engagement."},"visual":{"zh":"树下抱臂者面对三杯，侧面还有递来的第四杯。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A folded-armed figure sits beneath a tree with three cups ahead and another offered from the side, a cue for offers and limited response. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c04-Q1","prompt":{"zh":"没有回应，就说明没有机会吗？","en":"How does this card distinguish no response from no opportunity?"},"options":[{"id":"c04-Q1-be48a6a0f6","text":{"zh":"没有回应就证明机会完全不存在","en":"No response proves there is no opportunity"},"feedback":{"zh":"旁边明明有一只杯子递过来，人物却抱着双臂，没有伸手。可以这样记：有机会出现，但自己暂时不想回应。","en":"The offered cup and withdrawn posture coexist, showing the distinction."}},{"id":"c04-Q1-f396df7ff7","text":{"zh":"有机会出现，也可能暂时不想回应","en":"An opportunity may be present without a response"},"feedback":{"zh":"旁边明明有一只杯子递过来，人物却抱着双臂，没有伸手。可以这样记：有机会出现，但自己暂时不想回应。","en":"The offered cup and withdrawn posture coexist, showing the distinction."}}],"correct":"c04-Q1-f396df7ff7","support":"R1"},"Q2":{"id":"c04-Q2","prompt":{"zh":"收到课程邀请，却提不起兴趣。圣杯四在建议位，先做什么更合适？","en":"You receive a course invitation but feel little interest. With the Four of Cups as advice, what fits first?"},"options":[{"id":"c04-Q2-080270ac95","text":{"zh":"先了解自己的状态，再评估邀请","en":"Check one's state and then assess the invitation"},"feedback":{"zh":"自己现在有没有兴趣，和机会本身适不适合，是两件事。提不起劲，不代表外面没有机会。","en":"Internal interest and external opportunity need separate consideration."}},{"id":"c04-Q2-22e48e151a","text":{"zh":"只因没兴趣就认定外界没有任何机会","en":"Infer no opportunity exists anywhere from low interest"},"feedback":{"zh":"自己现在有没有兴趣，和机会本身适不适合，是两件事。提不起劲，不代表外面没有机会。","en":"Internal interest and external opportunity need separate consideration."}}],"correct":"c04-Q2-080270ac95","support":"RA"},"Q3":{"id":"c04-Q3","prompt":{"zh":"休整后愿意回复邀请，这张逆位牌更贴近哪种变化？","en":"Replying to invitations after a pause shows which reversal here?"},"options":[{"id":"c04-Q3-1475f905c3","text":{"zh":"越来越完全拒绝任何回应","en":"Increasingly refusing all response"},"feedback":{"zh":"原来不想回复，现在开始答复邀请，说明又愿意了解和参加了。","en":"The behaviour explicitly changes from silence to replies, showing renewed engagement."}},{"id":"c04-Q3-9c49d87d54","text":{"zh":"又愿意了解活动、回复邀请了","en":"Re-engaging with opportunities"},"feedback":{"zh":"原来不想回复，现在开始答复邀请，说明又愿意了解和参加了。","en":"The behaviour explicitly changes from silence to replies, showing renewed engagement."}}],"correct":"c04-Q3-9c49d87d54","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"人物没有伸手，杯子仍然在那里。因此要分清“有东西递过来”和“愿不愿意接”。 记住：有机会出现，也可能暂时不想回应，不是“没有回应就证明机会完全不存在”。","en":"An object's presence does not depend on the figure responding; that is the distinction taught. Compare: An opportunity may be present without a response; this cannot be replaced by “No response proves there is no opportunity”."}],"question":{"id":"c04-R1","prompt":{"zh":"地上有三只杯子，旁边还有一只杯子递过来。哪句更准确？","en":"Three cups stand on the ground and another is being offered. Which is more accurate?"},"options":[{"id":"c04-R1-0624818ce5","text":{"zh":"杯子就在眼前，不想接不等于没有杯子","en":"Opportunity and response should be observed separately"},"feedback":{"zh":"人物没有伸手，杯子仍然在那里。因此要分清“有东西递过来”和“愿不愿意接”。","en":"An object's presence does not depend on the figure responding; that is the distinction taught."}},{"id":"c04-R1-c245d33f85","text":{"zh":"没有主动伸手就说明没有杯子","en":"Not reaching out means no cup is present"},"feedback":{"zh":"人物没有伸手，杯子仍然在那里。因此要分清“有东西递过来”和“愿不愿意接”。","en":"An object's presence does not depend on the figure responding; that is the distinction taught."}}],"correct":"c04-R1-0624818ce5"}},"RA":{"teach":[{"zh":"先分清两件事：机会本身是否适合，以及自己当下是否有精力回应。疲惫可能让任何邀请都显得乏味，不能因此直接断定外界没有机会。","en":"Separate whether an offer fits from whether you currently have capacity to respond. Fatigue can make invitations unappealing without proving there are no opportunities."}],"question":{"id":"c04-RA","prompt":{"zh":"刚完成紧张项目，收到本来感兴趣的讲座邀请却提不起劲。下一步怎样应用？","en":"After an intense project, an otherwise interesting lecture invitation feels unappealing. What fits next?"},"options":[{"id":"c04-RA-39cb4e3f25","text":{"zh":"仅凭一时没兴趣就确定讲座毫无价值。","en":"Declare the lecture worthless from momentary disinterest."},"feedback":{"zh":"刚忙完项目，可能只是太累了。先休息，再看看讲座内容，不能只因现在没精神就认定讲座没价值。","en":"“Declare the lecture worthless from momentary disinterest.” does not address the specific conditions. The task separates current state from offer quality; fatigue alone does not establish value."}},{"id":"c04-RA-87e33420a3","text":{"zh":"先检查是否需要休息，再了解讲座是否适合。","en":"Check the need for rest, then assess the lecture's fit."},"feedback":{"zh":"刚忙完项目，可能只是太累了。先休息，再看看讲座内容，不能只因现在没精神就认定讲座没价值。","en":"The task separates current state from offer quality; fatigue alone does not establish value."}}],"correct":"c04-RA-87e33420a3"}},"R2":{"teach":[{"zh":"他已经开始主动问活动内容，说明愿意重新了解了。不能还按之前的不回应来判断。 题目描述的是“又愿意了解活动、回复邀请了”，不是“越来越完全拒绝任何回应”。","en":"The new action supports renewed engagement; the changed context matters. Return to the stated context: “Re-engaging with opportunities” fits this case; “Increasingly refusing all response” is unsupported by that context."}],"question":{"id":"c04-R2","prompt":{"zh":"原来不想参加活动，现在开始主动询问内容。哪句话更贴近这个变化？","en":"Someone who did not want to join an event now asks about it. Which statement best describes the change?"},"options":[{"id":"c04-R2-bece91a5df","text":{"zh":"继续认定此人绝不会回应","en":"Continue declaring they will never respond"},"feedback":{"zh":"他已经开始主动问活动内容，说明愿意重新了解了。不能还按之前的不回应来判断。","en":"The new action supports renewed engagement; the changed context matters."}},{"id":"c04-R2-609157050c","text":{"zh":"不再那么冷淡，开始愿意了解活动","en":"Disengagement eases and curiosity returns"},"feedback":{"zh":"他已经开始主动问活动内容，说明愿意重新了解了。不能还按之前的不回应来判断。","en":"The new action supports renewed engagement; the changed context matters."}}],"correct":"c04-R2-609157050c"}}},"revisit":{"id":"c04-V1","prompt":{"zh":"工作机会不少，但连续疲惫使人都不想看。哪句贴近？","en":"opportunities exist, but fatigue makes all unappealing. Which fits?"},"options":[{"id":"c04-V1-40c69a5e69","text":{"zh":"现在提不起劲，先看看是自己累了，还是机会不适合","en":"Engagement is low; distinguish current state from the offers"},"feedback":{"zh":"题目已经说有不少工作机会，只是累得不想看，不能说外面完全没有机会。","en":"Opportunities are explicitly present; the issue concerns response, not their total absence."}},{"id":"c04-V1-79158b8ba8","text":{"zh":"机会不存在，所以无需了解状态","en":"No opportunities exist, so the current state is irrelevant"},"feedback":{"zh":"题目已经说有不少工作机会，只是累得不想看，不能说外面完全没有机会。","en":"Opportunities are explicitly present; the issue concerns response, not their total absence."}}],"correct":"c04-V1-40c69a5e69"},"summary":{"zh":"心思放在自己身上，对眼前的事或新的邀请暂时提不起兴趣，也不太想回应。 旁边明明有一只杯子递过来，人物却抱着双臂，没有伸手。可以这样记：有机会出现，但自己暂时不想回应。","en":"Attention turns inward and engagement with available opportunities is low. Distinguish needing reflection from overlooking an offer; lack of response does not prove that no opportunity exists."},"cards":["c04"]},{"id":"c05","kind":"card","level":"I","title":{"zh":"圣杯五","en":"Five of Cups"},"teachings":[{"zh":"一直想着已经失去的东西，很难注意到身边还留下了什么、还有谁愿意帮助自己。 人物面前有三只倒下的杯，身后还有两只立着的杯。失去的是真的，但并不是所有东西都失去了。","en":"A loss occupies attention while some support remains. Acknowledge disappointment without erasing what is still available; neither forced positivity nor total hopelessness captures the whole card."},{"zh":"三杯倒下、两杯仍立，人物面向倒杯，是核心助记。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Three cups are fallen and two remain upright while the cloaked figure faces the fallen cups: a clear memory cue for loss and remaining support. This is a visual association for learning, not proof of an external event."},{"zh":"失落、遗憾、关注损失、仍在的支持。 圣杯对应水元素，和感受有关；五可以帮助记住受到打击。再看人物朝着倒杯、背后仍有立杯，就能记住这张牌的失落和仍在的支持。","en":"loss; regret; attention to loss; remaining support. Water concerns emotional loss; five may aid disruption, while the particular meaning is supported by fallen and upright cups and the figure’s attention."}],"application":{"zh":"示范：承认合作落空，再联系仍愿意帮助的人。可以为失利难过，也可以接受仍然有的帮助。不必假装没失败，才能继续往前走。","en":"Example: acknowledge a lost partnership and contact remaining supporters. The lesson holds both real loss and remaining support; neither should be erased."},"reversal":{"zh":"案例：失去一个合作机会后，逐渐愿意联系仍支持自己的伙伴。这里的逆位，是慢慢接受失利，也重新注意到仍愿意帮助自己的人。","en":"Case: after losing a partnership opportunity, someone begins contacting supportive companions again. Here the reversal concerns accepting loss and noticing remaining support."},"visual":{"zh":"三杯倒下、两杯仍立，人物面向倒杯，是核心助记。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Three cups are fallen and two remain upright while the cloaked figure faces the fallen cups: a clear memory cue for loss and remaining support. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c05-Q1","prompt":{"zh":"三只杯倒了，还有两只立着。把这两处一起看，哪句话更贴近牌义？","en":"Three cups have fallen but two stand. What is the lesson's summary?"},"options":[{"id":"c05-Q1-1a02cbe6cd","text":{"zh":"失落占据注意，但支持并未全部消失","en":"Loss dominates attention but support is not entirely gone"},"feedback":{"zh":"人物面前有三只倒下的杯，身后还有两只立着的杯。失去的是真的，但并不是所有东西都失去了。","en":"The upright cups preserve remaining support without denying the loss recalled by the fallen cups."}},{"id":"c05-Q1-41a1d0ae7c","text":{"zh":"已经失去全部可能的支持","en":"Every possible support has been lost"},"feedback":{"zh":"人物面前有三只倒下的杯，身后还有两只立着的杯。失去的是真的，但并不是所有东西都失去了。","en":"The upright cups preserve remaining support without denying the loss recalled by the fallen cups."}}],"correct":"c05-Q1-1a02cbe6cd","support":"R1"},"Q2":{"id":"c05-Q2","prompt":{"zh":"考试失利，心里很难过。圣杯五在建议位，哪种做法更合适？","en":"You feel upset after an exam setback. With the Five of Cups as advice, which response fits?"},"options":[{"id":"c05-Q2-91399ac751","text":{"zh":"要求自己立刻开心，假装没有失利","en":"Demand instant happiness and pretend no setback occurred"},"feedback":{"zh":"可以为失利难过，也可以接受仍然有的帮助。不必假装没失败，才能继续往前走。","en":"The lesson holds both real loss and remaining support; neither should be erased."}},{"id":"c05-Q2-93f9fec882","text":{"zh":"允许自己难过，再看看还有哪些帮助和机会","en":"Acknowledge sadness and use remaining help and opportunities"},"feedback":{"zh":"可以为失利难过，也可以接受仍然有的帮助。不必假装没失败，才能继续往前走。","en":"The lesson holds both real loss and remaining support; neither should be erased."}}],"correct":"c05-Q2-93f9fec882","support":"RA"},"Q3":{"id":"c05-Q3","prompt":{"zh":"失去机会后开始联系支持者，这张逆位牌更贴近哪种情况？","en":"Reconnecting with supporters after a lost opportunity illustrates what here?"},"options":[{"id":"c05-Q3-dc41ec0bf2","text":{"zh":"慢慢接受失利，也开始注意到仍愿意帮助自己的人","en":"Gradually accepting loss and noticing support"},"feedback":{"zh":"重新愿意求助，说明正在慢慢走出失落，不代表之前的损失没有发生过。","en":"Recovery changes the response to loss, not the fact that it occurred."}},{"id":"c05-Q3-ca01739649","text":{"zh":"证明过去的失落从未发生","en":"Proving the loss never occurred"},"feedback":{"zh":"重新愿意求助，说明正在慢慢走出失落，不代表之前的损失没有发生过。","en":"Recovery changes the response to loss, not the fact that it occurred."}}],"correct":"c05-Q3-dc41ec0bf2","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"还有朋友支持，并不代表不该难过。遗憾和得到帮助，可以同时存在。 记住：失落占据注意，但支持并未全部消失，不是“已经失去全部可能的支持”。","en":"Remaining support does not invalidate sadness; both can coexist. Compare: Loss dominates attention but support is not entirely gone; this cannot be replaced by “Every possible support has been lost”."}],"question":{"id":"c05-R1","prompt":{"zh":"错过一个活动，但还有两位朋友愿意一起安排别的。哪句符合？","en":"an event is missed but two friends offer another plan. Which fits?"},"options":[{"id":"c05-R1-8d20c997d0","text":{"zh":"有支持就说明不应该难过","en":"Available support means sadness is illegitimate"},"feedback":{"zh":"还有朋友支持，并不代表不该难过。遗憾和得到帮助，可以同时存在。","en":"Remaining support does not invalidate sadness; both can coexist."}},{"id":"c05-R1-c1679c4aa7","text":{"zh":"虽然遗憾，还有朋友愿意陪着自己","en":"Regret exists alongside available support"},"feedback":{"zh":"还有朋友支持，并不代表不该难过。遗憾和得到帮助，可以同时存在。","en":"Remaining support does not invalidate sadness; both can coexist."}}],"correct":"c05-R1-c1679c4aa7"}},"RA":{"teach":[{"zh":"失利后，不必逼自己立刻开心，也不用认定什么都没了。可以为失去的东西难过，再看看身边还有谁、还有哪些机会。","en":"Responding to loss need not choose instant happiness or total hopelessness. Acknowledge what was lost, then notice remaining people and resources without denying either part."}],"question":{"id":"c05-RA","prompt":{"zh":"一次选拔没通过，但老师愿意帮忙复盘。这张牌在建议位时，怎样做更合适？","en":"A selection is unsuccessful, but a teacher offers a review. What fits the advice?"},"options":[{"id":"c05-RA-275845b6b7","text":{"zh":"承认失望，并接受仍可获得的复盘帮助。","en":"Acknowledge disappointment and accept the available review."},"feedback":{"zh":"没通过选拔，可以失望；老师愿意帮忙，也可以接受。有人帮助，并不意味着这次没有受挫。","en":"Support and disappointment can coexist; accepting help does not rewrite the setback."}},{"id":"c05-RA-19f6b280e6","text":{"zh":"因为有人帮助，就要求自己承认从来没受挫。","en":"Because help exists, insist no setback ever occurred."},"feedback":{"zh":"没通过选拔，可以失望；老师愿意帮忙，也可以接受。有人帮助，并不意味着这次没有受挫。","en":"“Because help exists, insist no setback ever occurred.” does not address the specific conditions. Support and disappointment can coexist; accepting help does not rewrite the setback."}}],"correct":"c05-RA-275845b6b7"}},"R2":{"teach":[{"zh":"接受失利需要时间。还会难过，也可以开始求助、继续生活，不用等到一点都不难过。 题目描述的是“慢慢接受失利，也开始注意到仍愿意帮助自己的人”，不是“证明过去的失落从未发生”。","en":"Acceptance is a process and does not require eliminating every feeling before continuing. Return to the stated context: “Gradually accepting loss and noticing support” fits this case; “Proving the loss never occurred” is unsupported by that context."}],"question":{"id":"c05-R2","prompt":{"zh":"已经开始向别人求助，但想起失败还是难过。怎样看待这种变化更合适？","en":"You have started asking for help but still feel sad about the setback. How can you understand this change?"},"options":[{"id":"c05-R2-b608797b4f","text":{"zh":"可以边难过边重新接受帮助","en":"Help can be accepted while sadness remains"},"feedback":{"zh":"接受失利需要时间。还会难过，也可以开始求助、继续生活，不用等到一点都不难过。","en":"Acceptance is a process and does not require eliminating every feeling before continuing."}},{"id":"c05-R2-7d4883f22f","text":{"zh":"必须完全不难过才算恢复","en":"Recovery only counts after all sadness disappears"},"feedback":{"zh":"接受失利需要时间。还会难过，也可以开始求助、继续生活，不用等到一点都不难过。","en":"Acceptance is a process and does not require eliminating every feeling before continuing."}}],"correct":"c05-R2-b608797b4f"}}},"revisit":{"id":"c05-V1","prompt":{"zh":"演出取消令人遗憾，团队仍愿意支持新安排。哪句贴近？","en":"a cancelled show hurts, while the team supports a new plan. Which fits?"},"options":[{"id":"c05-V1-c07ba9e468","text":{"zh":"取消一场演出证明所有资源消失","en":"One cancellation proves all resources are gone"},"feedback":{"zh":"演出确实取消了，但团队还愿意继续支持，不能把一次取消当成什么都没有了。","en":"A particular loss does not erase all support; both parts matter."}},{"id":"c05-V1-4332262aef","text":{"zh":"承认这次的遗憾，也看看谁还愿意一起想办法","en":"Recognise the loss and the people still present"},"feedback":{"zh":"演出确实取消了，但团队还愿意继续支持，不能把一次取消当成什么都没有了。","en":"A particular loss does not erase all support; both parts matter."}}],"correct":"c05-V1-4332262aef"},"summary":{"zh":"一直想着已经失去的东西，很难注意到身边还留下了什么、还有谁愿意帮助自己。 人物面前有三只倒下的杯，身后还有两只立着的杯。失去的是真的，但并不是所有东西都失去了。","en":"A loss occupies attention while some support remains. Acknowledge disappointment without erasing what is still available; neither forced positivity nor total hopelessness captures the whole card."},"cards":["c05"]},{"id":"c06","kind":"card","level":"I","title":{"zh":"圣杯六","en":"Six of Cups"},"teachings":[{"zh":"想起过去，或遇到熟悉的人，心里感到温暖、亲切，也愿意真诚地关心别人。 孩子递出装着花的杯子，可以帮助记住童年、善意和温暖回忆；这不等于某位旧友一定会回来。","en":"Familiar memories or people may bring warmth, with simple generosity and goodwill. Let the past offer something useful without assuming it must return unchanged."},{"zh":"较大的孩子把盛花的杯递向较小者，呈现善意与童年主题。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"One child offers a flower-filled cup to another, giving a cue for kindness and a childhood atmosphere. This is a visual association for learning, not proof of an external event."},{"zh":"温暖回忆、善意。 水与熟悉的情感联系；六在本牌帮助整理回忆和善意，不用于推算旧人回来的日期。","en":"warm memory; kindness. Water relates to familiar feeling; six here helps organise memory and kindness, not calculate a former partner’s return."}],"application":{"zh":"示范：想想过去哪些经历让自己开心，哪些还适合带进现在的生活。可以保留小时候读书的快乐，再按现在有空的时间安排，不需要让整个生活回到小时候。","en":"Example: draw support from old experience and keep what fits now. Memory can offer warmth, while practical arrangements still need present-day fit."},"reversal":{"zh":"案例：坚持照搬学生时代的合作方式，忽略如今彼此已有不同时间条件。这里的逆位，是一直照旧做，反而不适合现在的生活。","en":"Case: old school-era collaboration rules are imposed despite changed schedules. Here the reversal concerns past patterns constraining the present."},"visual":{"zh":"较大的孩子把盛花的杯递向较小者，呈现善意与童年主题。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"One child offers a flower-filled cup to another, giving a cue for kindness and a childhood atmosphere. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c06-Q1","prompt":{"zh":"孩子递出装着花的杯子，可以帮助记住什么？","en":"What does offering the flower-filled cup connect to here?"},"options":[{"id":"c06-Q1-3708185f3c","text":{"zh":"某个旧人一定会回来","en":"A particular person from the past must return"},"feedback":{"zh":"孩子递出装着花的杯子，可以帮助记住童年、善意和温暖回忆；这不等于某位旧友一定会回来。","en":"The image aids kindness and the past, not certainty about someone else's actions."}},{"id":"c06-Q1-62b387bafc","text":{"zh":"单纯善意与温暖回忆","en":"Simple goodwill and warm memory"},"feedback":{"zh":"孩子递出装着花的杯子，可以帮助记住童年、善意和温暖回忆；这不等于某位旧友一定会回来。","en":"The image aids kindness and the past, not certainty about someone else's actions."}}],"correct":"c06-Q1-62b387bafc","support":"R1"},"Q2":{"id":"c06-Q2","prompt":{"zh":"想重新拾起小时候的阅读爱好。圣杯六在建议位，哪种做法更合适？","en":"You want to return to a childhood love of reading. With the Six of Cups as advice, which approach fits?"},"options":[{"id":"c06-Q2-697f7cbf62","text":{"zh":"保留阅读带来的乐趣，按现在节奏安排","en":"Keep the pleasure and adapt it to the current routine"},"feedback":{"zh":"可以保留小时候读书的快乐，再按现在有空的时间安排，不需要让整个生活回到小时候。","en":"Memory can offer warmth, while practical arrangements still need present-day fit."}},{"id":"c06-Q2-8ec91f08dd","text":{"zh":"要求生活完全回到小时候","en":"Require life to become exactly as it was in childhood"},"feedback":{"zh":"可以保留小时候读书的快乐，再按现在有空的时间安排，不需要让整个生活回到小时候。","en":"Memory can offer warmth, while practical arrangements still need present-day fit."}}],"correct":"c06-Q2-697f7cbf62","support":"RA"},"Q3":{"id":"c06-Q3","prompt":{"zh":"旧合作方式已不合新时间条件却坚持照搬，这张逆位牌更贴近哪种情况？","en":"An outdated arrangement is imposed despite changed schedules. What is this reversal?"},"options":[{"id":"c06-Q3-0085f4ae36","text":{"zh":"只要熟悉就证明永远适合","en":"Familiarity proves permanent suitability"},"feedback":{"zh":"大家现在有了不同的时间安排，旧办法即使熟悉，也不一定还适合。","en":"Familiarity does not establish fit; the context explicitly changed."}},{"id":"c06-Q3-90082136cd","text":{"zh":"仍坚持旧做法，没有按现在的条件调整","en":"A past pattern limits present adjustment"},"feedback":{"zh":"大家现在有了不同的时间安排，旧办法即使熟悉，也不一定还适合。","en":"Familiarity does not establish fit; the context explicitly changed."}}],"correct":"c06-Q3-90082136cd","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"收到老朋友的问候，可以感到温暖，但不能因此认定所有旧关系都会回到从前。 记住：单纯善意与温暖回忆，不是“某个旧人一定会回来”。","en":"One kind interaction cannot establish that the entire past will return. Compare: Simple goodwill and warm memory; this cannot be replaced by “A particular person from the past must return”."}],"question":{"id":"c06-R1","prompt":{"zh":"收到老朋友一句温暖问候，可以确认什么？","en":"an old friend sends a warm greeting. What is supported?"},"options":[{"id":"c06-R1-b0dd89dbe6","text":{"zh":"老朋友的关心让人觉得温暖、亲切","en":"A familiar connection brings goodwill and warmth"},"feedback":{"zh":"收到老朋友的问候，可以感到温暖，但不能因此认定所有旧关系都会回到从前。","en":"One kind interaction cannot establish that the entire past will return."}},{"id":"c06-R1-18d295cd9a","text":{"zh":"所有旧关系都会恢复原样","en":"Every old relationship will return unchanged"},"feedback":{"zh":"收到老朋友的问候，可以感到温暖，但不能因此认定所有旧关系都会回到从前。","en":"One kind interaction cannot establish that the entire past will return."}}],"correct":"c06-R1-b0dd89dbe6"}},"RA":{"teach":[{"zh":"过去喜欢的事，今天仍然可以做，只是时间和方式可能要调整。不必把整个生活变回从前，才能保留那份快乐。","en":"Keep the parts of past experience that support the present, not every old condition. A workable current arrangement can preserve familiar warmth while acknowledging change."}],"question":{"id":"c06-RA","prompt":{"zh":"重新喜欢上学生时代的读书会，但现在只有每月一晚空闲。怎样应用？","en":"You miss a school-era reading group but now have only one evening a month. What fits?"},"options":[{"id":"c06-RA-6a570e31d9","text":{"zh":"认为不能每天相聚，就完全否定这份旧爱好。","en":"Reject the old interest entirely because daily meetings are impossible."},"feedback":{"zh":"仍然可以一起读书，只需改成现在做得到的频率。不必要求和学生时代一模一样，也不用彻底放弃。","en":"“Reject the old interest entirely because daily meetings are impossible.” does not address the specific conditions. A valuable memory can continue in an adapted form, not only exact repetition or total rejection."}},{"id":"c06-RA-00d9ba3e10","text":{"zh":"按现在时间安排一次小聚，保留阅读与联系。","en":"Arrange a small meeting within current time, keeping reading and connection."},"feedback":{"zh":"仍然可以一起读书，只需改成现在做得到的频率。不必要求和学生时代一模一样，也不用彻底放弃。","en":"A valuable memory can continue in an adapted form, not only exact repetition or total rejection."}}],"correct":"c06-RA-00d9ba3e10"}},"R2":{"teach":[{"zh":"大家工作后空闲变少，需要重新约时间；没法天天见面，不等于不在乎这段关系。 题目描述的是“仍坚持旧做法，没有按现在的条件调整”，不是“只要熟悉就证明永远适合”。","en":"Changed time constraints call for adaptation, not denial of goodwill. Return to the stated context: “A past pattern limits present adjustment” fits this case; “Familiarity proves permanent suitability” is unsupported by that context."}],"question":{"id":"c06-R2","prompt":{"zh":"想像学生时代那样天天相聚，但大家现在都要工作。怎样安排更合适？","en":"You want to meet daily as you did at school, but everyone now has a job. What arrangement fits better?"},"options":[{"id":"c06-R2-44891be353","text":{"zh":"把不同时间条件当成没人有善意","en":"Treat changed schedules as proof nobody cares"},"feedback":{"zh":"大家工作后空闲变少，需要重新约时间；没法天天见面，不等于不在乎这段关系。","en":"Changed time constraints call for adaptation, not denial of goodwill."}},{"id":"c06-R2-ad92b901fb","text":{"zh":"保留联系，调整成现实可行的频率","en":"Keep the connection and choose a workable frequency"},"feedback":{"zh":"大家工作后空闲变少，需要重新约时间；没法天天见面，不等于不在乎这段关系。","en":"Changed time constraints call for adaptation, not denial of goodwill."}}],"correct":"c06-R2-ad92b901fb"}}},"revisit":{"id":"c06-V1","prompt":{"zh":"祖辈教过的手艺让人感到亲切，想重新练习。哪句贴近？","en":"a craft taught by a grandparent feels comforting to revisit. Which fits?"},"options":[{"id":"c06-V1-721501f325","text":{"zh":"过去的美好经历，仍能给现在的自己温暖和支持","en":"Past experience can be a warm resource in the present"},"feedback":{"zh":"重拾旧手艺，可以感到亲切，也可以学新做法，不必认为只有过去才好。","en":"The lesson welcomes memory's support without rejecting present life or new methods."}},{"id":"c06-V1-103cdb9c06","text":{"zh":"只有过去才有价值，新的做法都应拒绝","en":"Only the past has value and all new methods should be rejected"},"feedback":{"zh":"重拾旧手艺，可以感到亲切，也可以学新做法，不必认为只有过去才好。","en":"The lesson welcomes memory's support without rejecting present life or new methods."}}],"correct":"c06-V1-721501f325"},"summary":{"zh":"想起过去，或遇到熟悉的人，心里感到温暖、亲切，也愿意真诚地关心别人。 孩子递出装着花的杯子，可以帮助记住童年、善意和温暖回忆；这不等于某位旧友一定会回来。","en":"Familiar memories or people may bring warmth, with simple generosity and goodwill. Let the past offer something useful without assuming it must return unchanged."},"cards":["c06"]},{"id":"c07","kind":"card","level":"I","title":{"zh":"圣杯七","en":"Seven of Cups"},"teachings":[{"zh":"想做的事很多，每一种都很吸引人，但还没弄清哪些真正做得到。 想到很多可能，不等于每一种都能实现。还要看看时间、预算和其他条件够不够。","en":"Many imagined possibilities attract attention, while desires and realistic conditions remain insufficiently separated. Explore options, then check which can actually be pursued."},{"zh":"云中的七只杯装着不同形象，人物面对它们，可记为多种诱惑与想象。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Seven cups hold varied images in clouds before a figure, helping recall diverse attractions and imagined possibilities. This is a visual association for learning, not proof of an external event."},{"zh":"幻想、多种选项、按实际条件选择。 水关联愿望和想象；七不表示必须做七个选择，判断要回到实际条件。","en":"fantasy; multiple options; practical screening. Water relates to desire and imagination; seven does not prescribe seven choices, and judgement returns to actual conditions."}],"application":{"zh":"示范：候选方向按实际条件筛选。喜欢一门课，不等于有时间和钱上完；选择前，要把这些条件一起看。","en":"Example: screen directions against real conditions. Preference and resources are different conditions; screening considers both."},"reversal":{"zh":"案例：原来不断幻想多种职业，后来开始查资格和预算并缩小范围。这里的逆位，是不再只凭想象，而是开始按实际条件选择。","en":"Case: many careers were imagined; qualifications and budgets are now checked and the list narrows. Here the reversal means screening options and reducing fantasy."},"visual":{"zh":"云中的七只杯装着不同形象，人物面对它们，可记为多种诱惑与想象。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Seven cups hold varied images in clouds before a figure, helping recall diverse attractions and imagined possibilities. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c07-Q1","prompt":{"zh":"面对杯中许多吸引人的东西，人物像处在哪种状态？","en":"What do the many images in cups illustrate here?"},"options":[{"id":"c07-Q1-fd1b47b1a0","text":{"zh":"想做的事很多，还要看看哪些做得到","en":"Possibilities are many; wishes need separating from conditions"},"feedback":{"zh":"想到很多可能，不等于每一种都能实现。还要看看时间、预算和其他条件够不够。","en":"Imagination presents options, but feasibility needs checking separately."}},{"id":"c07-Q1-02b3ed9045","text":{"zh":"看起来诱人的选项都已可实现","en":"Every attractive option is already achievable"},"feedback":{"zh":"想到很多可能，不等于每一种都能实现。还要看看时间、预算和其他条件够不够。","en":"Imagination presents options, but feasibility needs checking separately."}}],"correct":"c07-Q1-fd1b47b1a0","support":"R1"},"Q2":{"id":"c07-Q2","prompt":{"zh":"同时对很多课程感兴趣，想全部报名。圣杯七在建议位，先做什么更合适？","en":"Many courses appeal to you and you want to enrol in all of them. With the Seven of Cups as advice, what fits first?"},"options":[{"id":"c07-Q2-963e892e8e","text":{"zh":"只要都喜欢就认定都有时间完成","en":"Assume liking them creates time to finish them all"},"feedback":{"zh":"喜欢一门课，不等于有时间和钱上完；选择前，要把这些条件一起看。","en":"Preference and resources are different conditions; screening considers both."}},{"id":"c07-Q2-bc1a5daa42","text":{"zh":"比较时间、费用与目标，再选一项","en":"Compare time, cost, and goals before choosing one"},"feedback":{"zh":"喜欢一门课，不等于有时间和钱上完；选择前，要把这些条件一起看。","en":"Preference and resources are different conditions; screening considers both."}}],"correct":"c07-Q2-bc1a5daa42","support":"RA"},"Q3":{"id":"c07-Q3","prompt":{"zh":"开始查资格、预算并缩小职业范围，这张逆位牌更贴近哪种情况？","en":"Checking qualifications and budgets narrows career options. What is this reversal?"},"options":[{"id":"c07-Q3-d2b94c6c57","text":{"zh":"从空想转向按实际条件选择","en":"Moving from fantasy toward practical selection"},"feedback":{"zh":"已经在查资格、算预算、排除不合适的方向，说明开始认真选择，而不是继续空想。","en":"The case is narrowing options, not replacing judgement with quantity."}},{"id":"c07-Q3-f609f3ad7b","text":{"zh":"选项越多越能证明无需选择","en":"More options prove no choice is needed"},"feedback":{"zh":"已经在查资格、算预算、排除不合适的方向，说明开始认真选择，而不是继续空想。","en":"The case is narrowing options, not replacing judgement with quantity."}}],"correct":"c07-Q3-d2b94c6c57","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"写下十个想去的地方，只说明有这些愿望，还不知道预算和时间够不够。 记住：想做的事很多，还要看看哪些做得到，不是“看起来诱人的选项都已可实现”。","en":"A list presents possibilities, not evidence of budget or time. Compare: Possibilities are many; wishes need separating from conditions; this cannot be replaced by “Every attractive option is already achievable”."}],"question":{"id":"c07-R1","prompt":{"zh":"列出十个旅行目的地，还没查预算。现在可以确认什么？","en":"ten destinations are listed without checking budget. What is established?"},"options":[{"id":"c07-R1-a2ca24a5fb","text":{"zh":"所有目的地都已经可以成行","en":"Every trip is already feasible"},"feedback":{"zh":"写下十个想去的地方，只说明有这些愿望，还不知道预算和时间够不够。","en":"A list presents possibilities, not evidence of budget or time."}},{"id":"c07-R1-d2877f75d8","text":{"zh":"有几个想去的地方，还不知道能不能成行","en":"Several wishes exist but feasibility is not established"},"feedback":{"zh":"写下十个想去的地方，只说明有这些愿望，还不知道预算和时间够不够。","en":"A list presents possibilities, not evidence of budget or time."}}],"correct":"c07-R1-d2877f75d8"}},"RA":{"teach":[{"zh":"筛选要把喜欢什么和能投入什么放在一起。明确有限的时间、预算和目标之后，先试一个方向，才能知道设想是否能实际进行。","en":"Screen options by combining interest with available investment. Given limited time, budget, and a goal, try one direction to see whether the imagined plan works."}],"question":{"id":"c07-RA","prompt":{"zh":"同时想报摄影、陶艺和舞蹈，但本月只够一门课的时间。怎样应用？","en":"Photography, pottery, and dance appeal, but this month has time for one course. What fits?"},"options":[{"id":"c07-RA-6bb6f0d3b8","text":{"zh":"比较当下目标和安排，选一门先试。","en":"Compare present goals and schedules and try one."},"feedback":{"zh":"本月只有上一门课的时间，就需要先选一门。三门都喜欢，也不会自动多出时间。","en":"Available time is explicitly limited; choosing must respect it, and more wishes do not create time."}},{"id":"c07-RA-0a6e258ced","text":{"zh":"三门都报名，把喜欢当成时间自动增加。","en":"Enrol in all three as though interest creates more time."},"feedback":{"zh":"本月只有上一门课的时间，就需要先选一门。三门都喜欢，也不会自动多出时间。","en":"“Enrol in all three as though interest creates more time.” does not address the specific conditions. Available time is explicitly limited; choosing must respect it, and more wishes do not create time."}}],"correct":"c07-RA-6bb6f0d3b8"}},"R2":{"teach":[{"zh":"根据预算排除不合适的计划，是在作出可行的选择，不是失去了想象力。 题目描述的是“从空想转向按实际条件选择”，不是“选项越多越能证明无需选择”。","en":"Screening uses conditions for judgement; it is not loss of imagination. Return to the stated context: “Moving from fantasy toward practical selection” fits this case; “More options prove no choice is needed” is unsupported by that context."}],"question":{"id":"c07-R2","prompt":{"zh":"查过预算后，排除了三个不合适的计划。哪句话更贴近这件事？","en":"After checking your budget, you remove three unsuitable plans. Which statement best describes this?"},"options":[{"id":"c07-R2-865456dd86","text":{"zh":"在减少幻想、让选择更具体","en":"Reducing fantasy and making selection more concrete"},"feedback":{"zh":"根据预算排除不合适的计划，是在作出可行的选择，不是失去了想象力。","en":"Screening uses conditions for judgement; it is not loss of imagination."}},{"id":"c07-R2-c605fa7932","text":{"zh":"删掉选项就代表完全没有想象力","en":"Removing options means imagination is entirely absent"},"feedback":{"zh":"根据预算排除不合适的计划，是在作出可行的选择，不是失去了想象力。","en":"Screening uses conditions for judgement; it is not loss of imagination."}}],"correct":"c07-R2-865456dd86"}}},"revisit":{"id":"c07-V1","prompt":{"zh":"创业想法很多，但团队只有一个月试做时间。哪项贴近建议？","en":"many venture ideas compete for one month of trial time. Which fits?"},"options":[{"id":"c07-V1-cc12275a18","text":{"zh":"把所有想法同时列为确定成果","en":"List every idea as an assured result"},"feedback":{"zh":"只有一个月，就要挑一个条件允许的想法先试。想到了很多，并不等于已经做出了成果。","en":"Connecting wishes to resources answers the lesson; ideas are not achievements."}},{"id":"c07-V1-6bb97eafff","text":{"zh":"按可用资源选一个小试验","en":"Select one small trial using available resources"},"feedback":{"zh":"只有一个月，就要挑一个条件允许的想法先试。想到了很多，并不等于已经做出了成果。","en":"Connecting wishes to resources answers the lesson; ideas are not achievements."}}],"correct":"c07-V1-6bb97eafff"},"summary":{"zh":"想做的事很多，每一种都很吸引人，但还没弄清哪些真正做得到。 想到很多可能，不等于每一种都能实现。还要看看时间、预算和其他条件够不够。","en":"Many imagined possibilities attract attention, while desires and realistic conditions remain insufficiently separated. Explore options, then check which can actually be pursued."},"cards":["c07"]},{"id":"c08","kind":"card","level":"I","title":{"zh":"圣杯八","en":"Eight of Cups"},"teachings":[{"zh":"原来投入的事情，已经不再让自己满足，开始想离开，寻找更值得做的事。 这张牌强调的是不再满足、转身寻找。它不保证只要离开，就一定选对了方向。","en":"A previously valued situation no longer meets inner needs, and someone turns away to seek a more meaningful direction. Leaving is a considered theme, not proof every departure is wise."},{"zh":"人物背向整齐摆放的杯子走向山地，重点是主动转身离开。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A figure walks away from arranged cups toward hills, making the turn away from something once present a visible memory cue. This is a visual association for learning, not proof of an external event."},{"zh":"转身离开、寻找意义。 水关联满足与需求；八的编号不独立决定离开，必须结合牌面和问题。","en":"turning away; seeking meaning. Water concerns fulfilment and needs; the number eight does not itself dictate departure, which needs the card and context."}],"application":{"zh":"示范：想清楚为什么不再满足，再准备下一步。要先了解为什么想离开、下一步准备做什么，不能看见这张牌就马上放弃所有投入。","en":"Example: identify unmet needs and prepare a next step. The lesson emphasises a reasoned turn, not an instruction to leave without judgement."},"reversal":{"zh":"案例：已清楚旧活动不再适合，却因为怕改变而反复答应留下。这里的逆位，是明知不再适合，却迟迟走不开。","en":"Case: an activity no longer fits, yet fear of change repeatedly leads to staying. Here the reversal focuses on difficulty leaving and returning to the old pattern."},"visual":{"zh":"人物背向整齐摆放的杯子走向山地，重点是主动转身离开。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A figure walks away from arranged cups toward hills, making the turn away from something once present a visible memory cue. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c08-Q1","prompt":{"zh":"人物背向杯子走开，主要表达了什么？","en":"What is mainly taught by the figure walking away from the cups?"},"options":[{"id":"c08-Q1-694cc38951","text":{"zh":"只要离开就保证选择永远正确","en":"Any departure guarantees the correct choice"},"feedback":{"zh":"这张牌强调的是不再满足、转身寻找。它不保证只要离开，就一定选对了方向。","en":"The card describes departure and seeking without guaranteeing every departure is wise."}},{"id":"c08-Q1-e2a4219954","text":{"zh":"原来的事情不再让自己满足，开始找更值得做的事","en":"An old situation no longer fulfils needs, prompting a search"},"feedback":{"zh":"这张牌强调的是不再满足、转身寻找。它不保证只要离开，就一定选对了方向。","en":"The card describes departure and seeking without guaranteeing every departure is wise."}}],"correct":"c08-Q1-e2a4219954","support":"R1"},"Q2":{"id":"c08-Q2","prompt":{"zh":"参加多年的活动已不再符合现在的目标。圣杯八在建议位，哪种做法更合适？","en":"An activity you have pursued for years no longer fits your goals. With the Eight of Cups as advice, which step fits?"},"options":[{"id":"c08-Q2-f973fbbabd","text":{"zh":"确认需求后安排退出或转向","en":"Clarify needs and plan an exit or change"},"feedback":{"zh":"要先了解为什么想离开、下一步准备做什么，不能看见这张牌就马上放弃所有投入。","en":"The lesson emphasises a reasoned turn, not an instruction to leave without judgement."}},{"id":"c08-Q2-bbd9e49d7f","text":{"zh":"不问原因就立即放弃一切投入","en":"Abandon all commitments without examining why"},"feedback":{"zh":"要先了解为什么想离开、下一步准备做什么，不能看见这张牌就马上放弃所有投入。","en":"The lesson emphasises a reasoned turn, not an instruction to leave without judgement."}}],"correct":"c08-Q2-f973fbbabd","support":"RA"},"Q3":{"id":"c08-Q3","prompt":{"zh":"明确不再适合却因怕变化反复留下，这张逆位牌更贴近哪种情况？","en":"Knowing it no longer fits but repeatedly staying from fear illustrates what?"},"options":[{"id":"c08-Q3-be62dd0dba","text":{"zh":"已经顺利完成转向","en":"A change of direction is already completed smoothly"},"feedback":{"zh":"题目说他每次都又答应留下，说明还没有离开，不能当成已经顺利换了方向。","en":"The case explicitly involves staying and repetition, not a completed departure."}},{"id":"c08-Q3-9be14cd7db","text":{"zh":"明知不再适合，还是很难离开","en":"Difficulty leaving an unfulfilling pattern"},"feedback":{"zh":"题目说他每次都又答应留下，说明还没有离开，不能当成已经顺利换了方向。","en":"The case explicitly involves staying and repetition, not a completed departure."}}],"correct":"c08-Q3-9be14cd7db","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"杯子还好好地摆在那里，人物却转身离开了。可以这样记：不是一无所有，而是已有的东西不再让自己满足。 记住：原来的事情不再让自己满足，开始找更值得做的事，不是“只要离开就保证选择永远正确”。","en":"The cups remain; the focus is changed fulfilment and direction, not total destruction. Compare: An old situation no longer fulfils needs, prompting a search; this cannot be replaced by “Any departure guarantees the correct choice”."}],"question":{"id":"c08-R1","prompt":{"zh":"仍拥有原来的成果，却决定寻找不同方向。离开是否必须因为一无所有？","en":"past achievements remain, but a new direction is sought. Must departure mean nothing remains?"},"options":[{"id":"c08-R1-91b1a9e598","text":{"zh":"不是，拥有一些成果也可能不再满足","en":"No; achievements can remain without fulfilling current needs"},"feedback":{"zh":"杯子还好好地摆在那里，人物却转身离开了。可以这样记：不是一无所有，而是已有的东西不再让自己满足。","en":"The cups remain; the focus is changed fulfilment and direction, not total destruction."}},{"id":"c08-R1-78ddc10685","text":{"zh":"是，只有失去全部才能转向","en":"Yes; a new direction requires total loss"},"feedback":{"zh":"杯子还好好地摆在那里，人物却转身离开了。可以这样记：不是一无所有，而是已有的东西不再让自己满足。","en":"The cups remain; the focus is changed fulfilment and direction, not total destruction."}}],"correct":"c08-R1-91b1a9e598"}},"RA":{"teach":[{"zh":"先想清楚为什么不想继续、下一步要怎么走。过去的付出仍有价值，不必全盘否定；也不是一有不舒服就必须离开。","en":"Before changing direction, clarify what no longer fulfils you and what a next step requires. Leaving can respect past value; not every discomfort is an order to leave immediately."}],"question":{"id":"c08-RA","prompt":{"zh":"参与多年的兴趣社团已不符合现在目标，但还有已答应的任务。怎样应用？","en":"A long-term club no longer fits current goals, but agreed duties remain. What fits?"},"options":[{"id":"c08-RA-55b4c39dc1","text":{"zh":"不说明需求就突然取消全部约定。","en":"Cancel every agreement abruptly without clarifying needs."},"feedback":{"zh":"可以去找更合适的方向，同时把已经答应的任务交接好。想离开，不等于必须突然取消所有约定。","en":"“Cancel every agreement abruptly without clarifying needs.” does not address the specific conditions. A prepared transition addresses new needs and existing responsibilities; abrupt cancellation is not required by the lesson."}},{"id":"c08-RA-c3fab413a6","text":{"zh":"理清需求，安排交接后探索新方向。","en":"Clarify needs, arrange a handover, then explore a new direction."},"feedback":{"zh":"可以去找更合适的方向，同时把已经答应的任务交接好。想离开，不等于必须突然取消所有约定。","en":"A prepared transition addresses new needs and existing responsibilities; abrupt cancellation is not required by the lesson."}}],"correct":"c08-RA-c3fab413a6"}},"R2":{"teach":[{"zh":"他留下，是怕让别人失望，不是因为这件事已经重新让他满意。 题目描述的是“明知不再适合，还是很难离开”，不是“已经顺利完成转向”。","en":"Fear explains staying here; it does not establish fulfilment. Return to the stated context: “Difficulty leaving an unfulfilling pattern” fits this case; “A change of direction is already completed smoothly” is unsupported by that context."}],"question":{"id":"c08-R2","prompt":{"zh":"明知不想继续，每次却因为怕别人失望而留下。先做什么更合适？","en":"You know you no longer want to continue, yet stay each time for fear of disappointing others. What can you do first?"},"options":[{"id":"c08-R2-8f8f79bebd","text":{"zh":"把不敢离开当成已经满足","en":"Treat difficulty leaving as proof of fulfilment"},"feedback":{"zh":"他留下，是怕让别人失望，不是因为这件事已经重新让他满意。","en":"Fear explains staying here; it does not establish fulfilment."}},{"id":"c08-R2-57f89ad863","text":{"zh":"理清自己需求，安排自己做得到的退出步骤","en":"Clarify needs and plan manageable departure steps"},"feedback":{"zh":"他留下，是怕让别人失望，不是因为这件事已经重新让他满意。","en":"Fear explains staying here; it does not establish fulfilment."}}],"correct":"c08-R2-57f89ad863"}}},"revisit":{"id":"c08-V1","prompt":{"zh":"已经读过许多书，但原来的读书方向不再回答关心的问题。哪句贴近？","en":"much reading has been done, but the old subject no longer answers current questions. Which fits?"},"options":[{"id":"c08-V1-a46a5486b1","text":{"zh":"承认旧投入价值，同时寻找新方向","en":"Acknowledge past investment while seeking a new direction"},"feedback":{"zh":"过去的投入仍然有价值，只是现在想解决的问题变了，所以需要找新方向。","en":"Changing direction need not erase past value; current needs have changed."}},{"id":"c08-V1-2f9ac62abb","text":{"zh":"只有否认全部过去才能开始寻找","en":"All past value must be denied before seeking"},"feedback":{"zh":"过去的投入仍然有价值，只是现在想解决的问题变了，所以需要找新方向。","en":"Changing direction need not erase past value; current needs have changed."}}],"correct":"c08-V1-a46a5486b1"},"summary":{"zh":"原来投入的事情，已经不再让自己满足，开始想离开，寻找更值得做的事。 这张牌强调的是不再满足、转身寻找。它不保证只要离开，就一定选对了方向。","en":"A previously valued situation no longer meets inner needs, and someone turns away to seek a more meaningful direction. Leaving is a considered theme, not proof every departure is wise."},"cards":["c08"]},{"id":"c09","kind":"card","level":"I","title":{"zh":"圣杯九","en":"Nine of Cups"},"teachings":[{"zh":"自己的愿望得到满足，能为已有的成果高兴，也愿意好好享受。 这里说的是自己感到满意，不能据此认定其他人也都满意。","en":"A personal wish or need finds satisfaction, and what has been attained can be enjoyed. Personal contentment is not automatically evidence that everyone else shares it."},{"zh":"人物坐在九只杯前，姿态安定，可记为享受已有的满足。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A seated figure rests before nine displayed cups, helping recall enjoyment of what one has. This is a visual association for learning, not proof of an external event."},{"zh":"个人满足、愿望实现、享受。 圣杯对应水元素，和感受有关；九在这里帮助记住已经得到一些想要的东西。但自己满足，不代表所有人都一样满意。","en":"personal satisfaction; fulfilled wishes; enjoyment. Water concerns personal satisfaction; nine recalls accumulated attainment here, not automatic happiness for everyone."}],"application":{"zh":"示范：完成自己重视的目标，允许自己享受成果。自己学会了喜欢的曲子，当然可以高兴；别人可能喜欢不同的音乐，不必和自己一样。","en":"Example: enjoy completing a valued goal. One may enjoy an achievement without deciding everyone else's preferences."},"reversal":{"zh":"案例：买到一直想要的东西，却发现真正需要的是休息与联系。这里的逆位，是得到了想要的东西，却没有真正感到满足。","en":"Case: a long-desired purchase is obtained, yet rest and connection remain unmet. Here the reversal concerns outer gratification missing inner needs."},"visual":{"zh":"人物坐在九只杯前，姿态安定，可记为享受已有的满足。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A seated figure rests before nine displayed cups, helping recall enjoyment of what one has. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c09-Q1","prompt":{"zh":"圣杯九说的满足，主要是谁的感受？","en":"Whose experience of satisfaction is central here?"},"options":[{"id":"c09-Q1-ab934781b8","text":{"zh":"个人愿望或需要得到满足","en":"An individual's wish or need is satisfied"},"feedback":{"zh":"这里说的是自己感到满意，不能据此认定其他人也都满意。","en":"Personal satisfaction cannot speak for others; the subject matters."}},{"id":"c09-Q1-c41277d437","text":{"zh":"所有相关者一定同样满意","en":"Every involved person must be equally satisfied"},"feedback":{"zh":"这里说的是自己感到满意，不能据此认定其他人也都满意。","en":"Personal satisfaction cannot speak for others; the subject matters."}}],"correct":"c09-Q1-ab934781b8","support":"R1"},"Q2":{"id":"c09-Q2","prompt":{"zh":"终于学会了一首很喜欢的曲子。圣杯九在建议位，怎样对待这份成绩更合适？","en":"You have learned a piece of music you love. With the Nine of Cups as advice, which response fits?"},"options":[{"id":"c09-Q2-c50c81feb1","text":{"zh":"因为满意就认定别人都必须喜欢","en":"Assume personal satisfaction obliges everyone else to like it"},"feedback":{"zh":"自己学会了喜欢的曲子，当然可以高兴；别人可能喜欢不同的音乐，不必和自己一样。","en":"One may enjoy an achievement without deciding everyone else's preferences."}},{"id":"c09-Q2-a797621d2d","text":{"zh":"欣赏成果并享受这份满足","en":"Appreciate the achievement and enjoy satisfaction"},"feedback":{"zh":"自己学会了喜欢的曲子，当然可以高兴；别人可能喜欢不同的音乐，不必和自己一样。","en":"One may enjoy an achievement without deciding everyone else's preferences."}}],"correct":"c09-Q2-a797621d2d","support":"RA"},"Q3":{"id":"c09-Q3","prompt":{"zh":"购物愿望达成却仍缺休息与联系，这张逆位牌更贴近哪种情况？","en":"A purchase is obtained but rest and connection remain unmet. What is this reversal?"},"options":[{"id":"c09-Q3-5b4ad02370","text":{"zh":"东西买到了，但真正缺的休息和陪伴没有得到满足","en":"Outer gratification has missed the underlying need"},"feedback":{"zh":"案例区分了获得物品与真实需要，不能把两者等同。","en":"The case distinguishes obtaining an item from meeting the actual need."}},{"id":"c09-Q3-c9c4b3b4d3","text":{"zh":"只要买到东西就证明全部需要满足","en":"Getting the item proves every need is met"},"feedback":{"zh":"案例区分了获得物品与真实需要，不能把两者等同。","en":"The case distinguishes obtaining an item from meeting the actual need."}}],"correct":"c09-Q3-5b4ad02370","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"自己喜欢这个方案，只能说明自己的想法。对方满不满意，还要听对方怎么说。 记住：个人愿望或需要得到满足，不是“所有相关者一定同样满意”。","en":"The Nine's personal perspective does not supply the other person's response. Compare: An individual's wish or need is satisfied; this cannot be replaced by “Every involved person must be equally satisfied”."}],"question":{"id":"c09-R1","prompt":{"zh":"自己喜欢一个合作方案，能确认双方都满意吗？","en":"liking a partnership plan personally establishes mutual satisfaction?"},"options":[{"id":"c09-R1-1f730c2fc8","text":{"zh":"能，自己的满意就是双方满意","en":"Yes; one's satisfaction equals mutual satisfaction"},"feedback":{"zh":"自己喜欢这个方案，只能说明自己的想法。对方满不满意，还要听对方怎么说。","en":"The Nine's personal perspective does not supply the other person's response."}},{"id":"c09-R1-61205ddc74","text":{"zh":"不能，还要询问另一方","en":"No; the other party still needs to be asked"},"feedback":{"zh":"自己喜欢这个方案，只能说明自己的想法。对方满不满意，还要听对方怎么说。","en":"The Nine's personal perspective does not supply the other person's response."}}],"correct":"c09-R1-61205ddc74"}},"RA":{"teach":[{"zh":"先看看自己为什么为这个成果高兴。可以喜欢自己的作品，也允许别人有不同喜好，不必等所有人都赞同才开心。","en":"Enjoy an achievement by recognising the need it meets for you. You can like your work while others have different preferences; personal joy need not become universal agreement."}],"question":{"id":"c09-RA","prompt":{"zh":"做成一直想做的蛋糕，自己很满意，朋友更喜欢另一种口味。怎样应用？","en":"You are pleased with a long-desired cake, while a friend prefers another flavour. What fits?"},"options":[{"id":"c09-RA-a57ef8f09e","text":{"zh":"享受自己的满足，也允许朋友有不同喜好。","en":"Enjoy your satisfaction and allow the friend's different preference."},"feedback":{"zh":"自己喜欢这个蛋糕，可以高兴；朋友喜欢另一种口味，也不影响自己的满足。","en":"Personal satisfaction does not require identical preferences or demand that others validate the feeling."}},{"id":"c09-RA-8e750e9cfb","text":{"zh":"要求朋友必须同样喜欢，才能承认自己满意。","en":"Require the friend to like it equally before allowing your satisfaction."},"feedback":{"zh":"自己喜欢这个蛋糕，可以高兴；朋友喜欢另一种口味，也不影响自己的满足。","en":"“Require the friend to like it equally before allowing your satisfaction.” does not address the specific conditions. Personal satisfaction does not require identical preferences or demand that others validate the feeling."}}],"correct":"c09-RA-a57ef8f09e"}},"R2":{"teach":[{"zh":"如果真正缺的是陪伴，再买东西也不能代替和人相处。先弄清缺什么，才知道该怎么补上。 题目描述的是“东西买到了，但真正缺的休息和陪伴没有得到满足”，不是“只要买到东西就证明全部需要满足”。","en":"Meeting a need first requires identifying it; more purchases do not directly provide companionship. Return to the stated context: “Outer gratification has missed the underlying need” fits this case; “Getting the item proves every need is met” is unsupported by that context."}],"question":{"id":"c09-R2","prompt":{"zh":"买了很多东西犒劳自己，还是觉得缺少陪伴。怎样做更合适？","en":"You buy many treats for yourself but still miss companionship. What response fits?"},"options":[{"id":"c09-R2-d0d5a776bd","text":{"zh":"弄清自己缺的是陪伴，找人聊聊、相处一下","en":"Identify the need for connection and arrange real contact"},"feedback":{"zh":"如果真正缺的是陪伴，再买东西也不能代替和人相处。先弄清缺什么，才知道该怎么补上。","en":"Meeting a need first requires identifying it; more purchases do not directly provide companionship."}},{"id":"c09-R2-9d9ff9bc1c","text":{"zh":"继续购买并认定孤单必然消失","en":"Keep buying and assume loneliness must disappear"},"feedback":{"zh":"如果真正缺的是陪伴，再买东西也不能代替和人相处。先弄清缺什么，才知道该怎么补上。","en":"Meeting a need first requires identifying it; more purchases do not directly provide companionship."}}],"correct":"c09-R2-d0d5a776bd"}}},"revisit":{"id":"c09-V1","prompt":{"zh":"完成长期想做的个人画作，自己很满意。哪句贴近？","en":"a long-desired personal painting is completed and enjoyed. Which fits?"},"options":[{"id":"c09-V1-138ad21cb9","text":{"zh":"个人满意证明作品得到所有人认可","en":"Personal satisfaction proves universal acclaim"},"feedback":{"zh":"自己为作品满意，就已经符合这张牌的个人满足；别人可能有不同看法。","en":"The theme can hold in personal experience without requiring or proving universal approval."}},{"id":"c09-V1-af056889be","text":{"zh":"个人愿望实现带来满足","en":"A fulfilled personal wish brings satisfaction"},"feedback":{"zh":"自己为作品满意，就已经符合这张牌的个人满足；别人可能有不同看法。","en":"The theme can hold in personal experience without requiring or proving universal approval."}}],"correct":"c09-V1-af056889be"},"summary":{"zh":"自己的愿望得到满足，能为已有的成果高兴，也愿意好好享受。 这里说的是自己感到满意，不能据此认定其他人也都满意。","en":"A personal wish or need finds satisfaction, and what has been attained can be enjoyed. Personal contentment is not automatically evidence that everyone else shares it."},"cards":["c09"]},{"id":"c10","kind":"card","level":"I","title":{"zh":"圣杯十","en":"Ten of Cups"},"teachings":[{"zh":"和亲近的人相处融洽，彼此关心，感到幸福和安心。家人、恋人，或一群相处得好的朋友，都可能有这种感受。图中的成人和孩子一起站在家园前，可以帮助记住“和重要的人一起感到幸福”。","en":"Feel happy and at ease with people close to you, caring for one another. This can be shared by family, partners or a close group of friends. The adults and children together in front of their home help you remember happiness shared with people who matter to you."},{"zh":"两位成人抬起手臂，孩子在旁边玩耍，远处还有家园。把这些细节放在一起，可以记住和亲近的人共同感受幸福。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Adults raise their arms, children move nearby, and a rainbow of cups arches over a home landscape: the scene places happiness within shared life. This is a visual association for learning, not proof of an external event."},{"zh":"和谐、归属、一起生活的幸福。 圣杯对应情感，十在这里强调和亲近的人一起感到幸福。它不代表这种幸福永远不会改变。","en":"harmony; belonging; shared happiness. Water relates to feeling; ten here recalls fulfilment gathered into shared life, not unchanging perfection."}],"application":{"zh":"几位室友希望相处得更融洽。圣杯十在建议位，可以这样做：先聊聊各自的生活习惯和需要，比如什么时候需要安静、公共空间怎样用，再一起商量。重点是大家能不能彼此照顾、住得舒服，不只是把房间布置漂亮。","en":"Several housemates want to get along better. With the Ten of Cups as advice, discuss daily habits and needs, such as quiet hours and how to use shared space, then agree together. What matters is caring for one another and feeling comfortable at home, not just decorating the rooms."},"reversal":{"zh":"案例：家里人对外总说日子过得很好，私下却不谈各自想要怎样的生活，彼此的想法越来越不一样。这里的逆位，强调表面和睦、实际期待不同。","en":"Case: a household presents perfection but never discusses members’ different daily needs. Here the reversal focuses on different expectations behind an appearance of harmony."},"visual":{"zh":"两位成人抬起手臂，孩子在旁边玩耍，远处还有家园。把这些细节放在一起，可以记住和亲近的人共同感受幸福。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"Adults raise their arms, children move nearby, and a rainbow of cups arches over a home landscape: the scene places happiness within shared life. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c10-Q1","prompt":{"zh":"这张牌说的幸福，重点在哪里？","en":"What is central beyond one person's satisfaction?"},"options":[{"id":"c10-Q1-f86ecabb95","text":{"zh":"只要一人满意就可代表所有人","en":"One satisfied person represents everyone"},"feedback":{"zh":"成人和孩子一起出现在家园前，可以帮助记住“一起生活的幸福”。这里不只是一个人对自己的生活满意。","en":"The shared setting aids belonging and shared fulfilment; the communal element matters."}},{"id":"c10-Q1-12c5a73f1d","text":{"zh":"和亲近的人一起感到幸福、彼此支持","en":"Happiness is shared in relationships and communal life"},"feedback":{"zh":"成人和孩子一起出现在家园前，可以帮助记住“一起生活的幸福”。这里不只是一个人对自己的生活满意。","en":"The shared setting aids belonging and shared fulfilment; the communal element matters."}}],"correct":"c10-Q1-12c5a73f1d","support":"R1"},"Q2":{"id":"c10-Q2","prompt":{"zh":"几位室友希望住在一起更融洽。圣杯十在建议位，哪种做法更合适？","en":"Several housemates want to get along better in their shared home. With the Ten of Cups as advice, which approach fits?"},"options":[{"id":"c10-Q2-24fbda78a9","text":{"zh":"聊清楚各自的生活习惯和需要，平时互相照顾","en":"Discuss expectations and practise mutual support"},"feedback":{"zh":"一起住得幸福，要看大家是否互相关心、彼此支持，不只是房子布置得好不好看。","en":"Living happily together depends on care and mutual support, not just how the home looks."}},{"id":"c10-Q2-f1ace0242d","text":{"zh":"只顾把房间布置漂亮，不管大家住得舒不舒服","en":"Decorate the space while ignoring members' needs"},"feedback":{"zh":"一起住得幸福，要看大家是否互相关心、彼此支持，不只是房子布置得好不好看。","en":"Living happily together depends on care and mutual support, not just how the home looks."}}],"correct":"c10-Q2-24fbda78a9","support":"RA"},"Q3":{"id":"c10-Q3","prompt":{"zh":"表面完美却不谈不同生活需求，这张逆位牌更贴近哪种情况？","en":"An image of perfection hides different daily needs. What is this reversal?"},"options":[{"id":"c10-Q3-ba2cbbd69f","text":{"zh":"照片好看就证明所有人和谐","en":"A pleasing image proves harmony for everyone"},"feedback":{"zh":"题目已经说，大家想要的生活不同、又不愿说出来。照片好看，不能说明这些分歧已经解决。","en":"Appearance cannot replace actual needs and interaction; disagreement is explicitly given."}},{"id":"c10-Q3-90833750d1","text":{"zh":"表面相处和睦，彼此想要的生活却不一样","en":"The shared ideal is disconnected from the lived relationship"},"feedback":{"zh":"题目已经说，大家想要的生活不同、又不愿说出来。照片好看，不能说明这些分歧已经解决。","en":"Appearance cannot replace actual needs and interaction; disagreement is explicitly given."}}],"correct":"c10-Q3-90833750d1","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"圣杯十强调大家一起感到幸福。一个人满意，还不能代表其他人都开心；要看其他人的需要有没有被照顾到，是否也觉得自己受到重视。","en":"The Ten of Cups emphasizes happiness shared by the group. One person's satisfaction does not establish that everyone is happy. Consider whether the others' needs are met and whether they feel valued too."}],"question":{"id":"c10-R1","prompt":{"zh":"几位朋友一起旅行，其中一人玩得很开心，其他人却一直觉得被忽略。这能说明大家共享幸福吗？","en":"Friends travel together. One has a wonderful time, but the others keep feeling ignored. Does this show happiness shared by the group?"},"options":[{"id":"c10-R1-f2395bf6c2","text":{"zh":"还不能，要看其他人的需要有没有被照顾到","en":"Not yet; the others' needs matter too"},"feedback":{"zh":"题目里其他人觉得被忽略，说明他们还没有一起感到开心。圣杯十强调的是大家共享的幸福。","en":"The others feel ignored, so the enjoyment is not yet shared. The Ten of Cups emphasizes happiness experienced together."}},{"id":"c10-R1-de927e3463","text":{"zh":"能，只要其中一人开心就够了","en":"Yes; one happy person is enough"},"feedback":{"zh":"一个人开心不能代表所有人都开心。这里要把其他人的感受和需要也算进去。","en":"One person's happiness does not represent everyone's experience. Include the others' feelings and needs too."}}],"correct":"c10-R1-f2395bf6c2"}},"RA":{"teach":[{"zh":"住在一起是否幸福，要看大家的需要有没有被认真对待。布置得漂亮固然好，但不能代替平时的关心和照顾。","en":"Shared fulfilment requires participants to be heard and cared for. Attractive surroundings can help, but appearance cannot replace shared satisfaction when needs are ignored."}],"question":{"id":"c10-RA","prompt":{"zh":"室友准备共同聚餐，有人需要安静、有人希望多交流。这张牌在建议位时，怎样做更合适？","en":"Housemates plan a shared meal: one needs quiet and another wants conversation. What fits?"},"options":[{"id":"c10-RA-694f6964da","text":{"zh":"只装饰餐桌，认定好看就代表人人被照顾。","en":"Decorate the table and assume appearance means everyone is cared for."},"feedback":{"zh":"有人想安静、有人想聊天，需要先商量。餐桌再漂亮，也不能替大家决定怎样相处才舒服。","en":"“Decorate the table and assume appearance means everyone is cared for.” does not address the specific conditions. Shared fulfilment concerns lived experience; decoration does not establish that needs were met."}},{"id":"c10-RA-e3d3381aef","text":{"zh":"先了解各自需要，协商大家能接受的安排。","en":"Hear each person's needs and agree on an acceptable arrangement."},"feedback":{"zh":"有人想安静、有人想聊天，需要先商量。餐桌再漂亮，也不能替大家决定怎样相处才舒服。","en":"Shared fulfilment concerns lived experience; decoration does not establish that needs were met."}}],"correct":"c10-RA-e3d3381aef"}},"R2":{"teach":[{"zh":"先把不同的想法说出来，才能商量怎样一起生活。只装作和睦，分歧仍然在那里。 题目描述的是“表面相处和睦，彼此想要的生活却不一样”，不是“照片好看就证明所有人和谐”。","en":"Acknowledging differences enables a shared vision; appearances hide the issue. Return to the stated context: “The shared ideal is disconnected from the lived relationship” fits this case; “A pleasing image proves harmony for everyone” is unsupported by that context."}],"question":{"id":"c10-R2","prompt":{"zh":"大家想过的生活不一样，却一直假装没有分歧。先做什么更合适？","en":"People want different ways of living but keep pretending they agree. What can they do first?"},"options":[{"id":"c10-R2-8561be8062","text":{"zh":"只要求继续展示和谐外表","en":"Demand continued display of harmony only"},"feedback":{"zh":"先把不同的想法说出来，才能商量怎样一起生活。只装作和睦，分歧仍然在那里。","en":"Acknowledging differences enables a shared vision; appearances hide the issue."}},{"id":"c10-R2-7a98cb3cc2","text":{"zh":"说清各自想要怎样的生活，商量哪些事情能一起做到","en":"Clarify expectations and seek what can be shared"},"feedback":{"zh":"先把不同的想法说出来，才能商量怎样一起生活。只装作和睦，分歧仍然在那里。","en":"Acknowledging differences enables a shared vision; appearances hide the issue."}}],"correct":"c10-R2-7a98cb3cc2"}}},"revisit":{"id":"c10-V1","prompt":{"zh":"一群长期合住的朋友平时互相照顾，也愿意继续住在一起。哪句贴近？","en":"Friends who have lived together for years support one another and want to keep sharing a home. Which fits?"},"options":[{"id":"c10-V1-341c9a1073","text":{"zh":"和亲近的人一起感到幸福、像有一个家","en":"Belonging and fulfilment within shared relationships"},"feedback":{"zh":"现在相处幸福、彼此支持，不代表以后永远不会意见不同。","en":"Shared fulfilment is the present theme, not a prediction of permanent agreement."}},{"id":"c10-V1-ce210a6aac","text":{"zh":"从此永远不会出现任何分歧","en":"No disagreement can ever arise again"},"feedback":{"zh":"现在相处幸福、彼此支持，不代表以后永远不会意见不同。","en":"Shared fulfilment is the present theme, not a prediction of permanent agreement."}}],"correct":"c10-V1-341c9a1073"},"summary":{"zh":"和亲近的人相处融洽，彼此关心，感到幸福和安心。家人、恋人，或一群相处得好的朋友，都可能有这种感受。图中的成人和孩子一起站在家园前，可以帮助记住“和重要的人一起感到幸福”。","en":"Feel happy and at ease with people close to you, caring for one another. This can be shared by family, partners or a close group of friends. The adults and children together in front of their home help you remember happiness shared with people who matter to you."},"cards":["c10"]},{"id":"c11","kind":"card","level":"I","title":{"zh":"圣杯侍从","en":"Page of Cups"},"teachings":[{"zh":"第一次留意到新的感受或灵感，觉得新鲜，想试着表达，却还不太熟练。 侍从好奇地看着杯中的鱼，可以帮助记住对新感受的好奇。它不能证明某个人一定会发消息来。","en":"Meet new feelings or inspiration with openness and a learner’s sensitivity. A small sincere expression can begin exploration without requiring a dramatic promise."},{"zh":"侍从看着从杯子里探出头的鱼。用这个新奇的画面，记住第一次发现某种感受或灵感时的好奇。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The figure watches a fish emerging from a cup, giving a memorable cue for something emotionally surprising or new. This is a visual association for learning, not proof of an external event."},{"zh":"新的感受、好奇、试着表达。 侍从强调第一次接触、开始学习；水关联感受，不能把鱼读成某人一定发来消息。","en":"emotional curiosity; sensitivity; first expression. The Page is a role of first contact; water relates to feeling, not proof that the fish predicts a message from a particular person."}],"application":{"zh":"示范：用一句简单的话表达感谢。第一次表达，不熟练很正常。先写一小段，才能慢慢找到适合自己的表达方式。","en":"Example: express thanks in one simple sentence. Beginner expression can be tentative; a small trial helps explore feeling."},"reversal":{"zh":"案例：想告诉伙伴自己很感激，却担心表达不好而完全缩回去。这里的逆位，是因为害羞、担心说不好，而不敢表达。","en":"Case: gratitude toward a companion remains unexpressed because of fear of saying it badly. Here the reversal concerns shy, blocked expression."},"visual":{"zh":"侍从看着从杯子里探出头的鱼。用这个新奇的画面，记住第一次发现某种感受或灵感时的好奇。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The figure watches a fish emerging from a cup, giving a memorable cue for something emotionally surprising or new. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c11-Q1","prompt":{"zh":"侍从好奇地看着杯里的鱼，可以帮助记住什么？","en":"What does the unexpected fish help recall?"},"options":[{"id":"c11-Q1-83b7c5da6f","text":{"zh":"好奇地接触新的感受与灵感","en":"Curiously encountering new feeling and inspiration"},"feedback":{"zh":"侍从好奇地看着杯中的鱼，可以帮助记住对新感受的好奇。它不能证明某个人一定会发消息来。","en":"The surprising image aids emotional openness, not evidence of another person's future actions."}},{"id":"c11-Q1-1c02720bef","text":{"zh":"已经确定某个人会发来消息","en":"Certainty that a specific person will send a message"},"feedback":{"zh":"侍从好奇地看着杯中的鱼，可以帮助记住对新感受的好奇。它不能证明某个人一定会发消息来。","en":"The surprising image aids emotional openness, not evidence of another person's future actions."}}],"correct":"c11-Q1-83b7c5da6f","support":"R1"},"Q2":{"id":"c11-Q2","prompt":{"zh":"刚发现自己喜欢写诗，还不太会表达。圣杯侍从在建议位，哪种做法更合适？","en":"You have discovered an interest in writing poetry but feel inexperienced. With the Page of Cups as advice, which step fits?"},"options":[{"id":"c11-Q2-343b0ef16d","text":{"zh":"认为还不够成熟，就不允许自己写","en":"Forbid expression until complete maturity"},"feedback":{"zh":"第一次表达，不熟练很正常。先写一小段，才能慢慢找到适合自己的表达方式。","en":"Beginner expression can be tentative; a small trial helps explore feeling."}},{"id":"c11-Q2-600dc1c111","text":{"zh":"先写一小段，试着表达刚有的感受","en":"Try a short piece and explore the new feeling"},"feedback":{"zh":"第一次表达，不熟练很正常。先写一小段，才能慢慢找到适合自己的表达方式。","en":"Beginner expression can be tentative; a small trial helps explore feeling."}}],"correct":"c11-Q2-600dc1c111","support":"RA"},"Q3":{"id":"c11-Q3","prompt":{"zh":"因害怕说不好而压住感谢，这张逆位牌更贴近哪种情况？","en":"Fear of imperfect wording suppresses gratitude. What is this reversal?"},"options":[{"id":"c11-Q3-056cfaf0f0","text":{"zh":"明明有感谢，却因为害羞说不出口","en":"Shyness obstructs expression of real feeling"},"feedback":{"zh":"题目说他很感谢伙伴，只是担心说不好，所以没有表达，不是完全不在意。","en":"Gratitude is already stated; expression, not feeling itself, is difficult."}},{"id":"c11-Q3-612e98da6a","text":{"zh":"没有表达就证明完全不在意","en":"No expression proves there is no care"},"feedback":{"zh":"题目说他很感谢伙伴，只是担心说不好，所以没有表达，不是完全不在意。","en":"Gratitude is already stated; expression, not feeling itself, is difficult."}}],"correct":"c11-Q3-056cfaf0f0","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"可以先感受这份触动，试着了解它，不必刚有灵感就决定一辈子都要做什么。 记住：好奇地接触新的感受与灵感，不是“已经确定某个人会发来消息”。","en":"A new feeling can be explored without an unsupported major promise. Compare: Curiously encountering new feeling and inspiration; this cannot be replaced by “Certainty that a specific person will send a message”."}],"question":{"id":"c11-R1","prompt":{"zh":"第一次感到某个创作想法很打动自己。可以怎样理解？","en":"a creative idea feels moving for the first time. How can it be understood?"},"options":[{"id":"c11-R1-9bef4011f3","text":{"zh":"必须立刻作出一生的承诺","en":"An immediate lifelong promise is required"},"feedback":{"zh":"可以先感受这份触动，试着了解它，不必刚有灵感就决定一辈子都要做什么。","en":"A new feeling can be explored without an unsupported major promise."}},{"id":"c11-R1-722c4f7223","text":{"zh":"带着好奇，慢慢了解刚出现的感受","en":"Open exploration of an emerging feeling"},"feedback":{"zh":"可以先感受这份触动，试着了解它，不必刚有灵感就决定一辈子都要做什么。","en":"A new feeling can be explored without an unsupported major promise."}}],"correct":"c11-R1-722c4f7223"}},"RA":{"teach":[{"zh":"初次表达可以小而具体，不需要先把感受整理得完美。先尝试一句话、一小段创作，给新感受一个出口，再慢慢学习怎样表达得更清楚。","en":"An initial expression can be small and specific rather than perfect. Try a sentence or short creative piece to give a new feeling an outlet, then learn greater clarity."}],"question":{"id":"c11-RA","prompt":{"zh":"第一次想写一张感谢卡，却觉得不会写长文。这张牌在建议位时，怎样做更合适？","en":"You want to write a first thank-you card but cannot write a long letter. What fits?"},"options":[{"id":"c11-RA-2b86c71a7d","text":{"zh":"写下一个具体感谢的小细节。","en":"Write one specific detail you appreciate."},"feedback":{"zh":"初次写感谢卡，可以先写一件想感谢的小事。等到会写完美长文才动笔，就迟迟没有开始。","en":"A small expression fits open beginner exploration; a perfection threshold blocks the start."}},{"id":"c11-RA-ab14a24777","text":{"zh":"等到能写完美长文才允许任何表达。","en":"Allow no expression until a perfect long letter is possible."},"feedback":{"zh":"初次写感谢卡，可以先写一件想感谢的小事。等到会写完美长文才动笔，就迟迟没有开始。","en":"“Allow no expression until a perfect long letter is possible.” does not address the specific conditions. A small expression fits open beginner exploration; a perfection threshold blocks the start."}}],"correct":"c11-RA-2b86c71a7d"}},"R2":{"teach":[{"zh":"先说一件具体感谢的事，就比要求自己说得完美更容易开口。 题目描述的是“明明有感谢，却因为害羞说不出口”，不是“没有表达就证明完全不在意”。","en":"A simple specific expression reduces the block; waiting for perfection maintains silence. Return to the stated context: “Shyness obstructs expression of real feeling” fits this case; “No expression proves there is no care” is unsupported by that context."}],"question":{"id":"c11-R2","prompt":{"zh":"想感谢合作伙伴，又不知道怎样说才好。可以先试着做什么？","en":"You want to thank a collaborator but do not know how to say it. What could you try first?"},"options":[{"id":"c11-R2-24d44465e1","text":{"zh":"先说一件具体感谢的小事","en":"Name one specific thing to be thankful for"},"feedback":{"zh":"先说一件具体感谢的事，就比要求自己说得完美更容易开口。","en":"A simple specific expression reduces the block; waiting for perfection maintains silence."}},{"id":"c11-R2-07479b9433","text":{"zh":"等到保证永不说错才表达","en":"Wait until flawless expression is guaranteed"},"feedback":{"zh":"先说一件具体感谢的事，就比要求自己说得完美更容易开口。","en":"A simple specific expression reduces the block; waiting for perfection maintains silence."}}],"correct":"c11-R2-24d44465e1"}}},"revisit":{"id":"c11-V1","prompt":{"zh":"孩子或成年人第一次尝试把心情画出来。哪句贴近？","en":"a child or adult first tries drawing a feeling. Which fits?"},"options":[{"id":"c11-V1-d91fc27beb","text":{"zh":"只有孩子才能体现侍从","en":"Only a child can embody the Page"},"feedback":{"zh":"第一次试着画出心情，无论孩子还是成年人，都可以有这种好奇又不熟练的状态。","en":"The Page is a beginner state in this lesson and can appear at any age."}},{"id":"c11-V1-f8dbf2e3b8","text":{"zh":"留意到自己的感受，开始试着表达","en":"Begin expressing with curiosity and sensitivity"},"feedback":{"zh":"第一次试着画出心情，无论孩子还是成年人，都可以有这种好奇又不熟练的状态。","en":"The Page is a beginner state in this lesson and can appear at any age."}}],"correct":"c11-V1-f8dbf2e3b8"},"summary":{"zh":"第一次留意到新的感受或灵感，觉得新鲜，想试着表达，却还不太熟练。 侍从好奇地看着杯中的鱼，可以帮助记住对新感受的好奇。它不能证明某个人一定会发消息来。","en":"Meet new feelings or inspiration with openness and a learner’s sensitivity. A small sincere expression can begin exploration without requiring a dramatic promise."},"cards":["c11"]},{"id":"c12","kind":"card","level":"I","title":{"zh":"圣杯骑士","en":"Knight of Cups"},"teachings":[{"zh":"因为喜欢、向往或被打动，主动表达心意，去接近想认识的人、想做的事。 骑士端着杯子向前走，可以帮助记住主动靠近、表达心意，不只是放在心里想。","en":"Bring a feeling or ideal into an active offer, invitation, or creative proposal. Moving toward what is valued is central; the gesture alone does not prove lasting reliability."},{"zh":"骑士持杯，马缓步前进，可记为带着情感目标主动靠近。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The rider carries a cup while the horse advances calmly, recalling movement guided by feeling rather than merely thinking about it. This is a visual association for learning, not proof of an external event."},{"zh":"表达心意、浪漫、追求理想。 骑士强调主动接近，圣杯对应的水元素帮助记住感情和理想。但不能仅凭这张牌认定某个人就是恋爱对象，或一定会长期履行承诺。","en":"expressing feeling; romance; pursuing ideals. The Knight is active pursuit; water gives an emotional aim, not certainty about a romantic person or lasting commitment."}],"application":{"zh":"示范：把审美想法做成具体提案。可以主动把邀请说出来，但对方愿不愿意，还要听对方的回答。","en":"Example: make an aesthetic idea into a concrete proposal. Making an invitation is one's own action; the other's response still needs checking."},"reversal":{"zh":"案例：不断提出动人的合作想法，却从不兑现约定的准备工作。这里的逆位，是说得很动人，却没有照着承诺去做。","en":"Case: moving proposals are repeatedly made, but promised preparation never happens. Here the reversal concerns idealised expression disconnected from follow-through."},"visual":{"zh":"骑士持杯，马缓步前进，可记为带着情感目标主动靠近。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The rider carries a cup while the horse advances calmly, recalling movement guided by feeling rather than merely thinking about it. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c12-Q1","prompt":{"zh":"骑士端着杯子向前，重点是哪种行动？","en":"Where is the emphasis of the rider moving with a cup here?"},"options":[{"id":"c12-Q1-99a7c52da1","text":{"zh":"只在心里想，从不接近或表达","en":"Only think privately, never approach or express"},"feedback":{"zh":"骑士端着杯子向前走，可以帮助记住主动靠近、表达心意，不只是放在心里想。","en":"This Knight includes active approach, not feeling held entirely still."}},{"id":"c12-Q1-240d46d20c","text":{"zh":"主动表达自己的感受或理想","en":"Turn feeling or an ideal into an active expression"},"feedback":{"zh":"骑士端着杯子向前走，可以帮助记住主动靠近、表达心意，不只是放在心里想。","en":"This Knight includes active approach, not feeling held entirely still."}}],"correct":"c12-Q1-240d46d20c","support":"R1"},"Q2":{"id":"c12-Q2","prompt":{"zh":"想邀请朋友一起创作音乐。圣杯骑士在建议位，哪种做法更合适？","en":"You want to invite a friend to create music together. With the Knight of Cups as advice, which step fits?"},"options":[{"id":"c12-Q2-c9699b569d","text":{"zh":"真诚说明想法并发出具体邀请","en":"Explain the idea sincerely and make a concrete invitation"},"feedback":{"zh":"可以主动把邀请说出来，但对方愿不愿意，还要听对方的回答。","en":"Making an invitation is one's own action; the other's response still needs checking."}},{"id":"c12-Q2-e67cc32d54","text":{"zh":"仅凭愿望就认定朋友已经答应","en":"Assume the friend has agreed because one wishes it"},"feedback":{"zh":"可以主动把邀请说出来，但对方愿不愿意，还要听对方的回答。","en":"Making an invitation is one's own action; the other's response still needs checking."}}],"correct":"c12-Q2-c9699b569d","support":"RA"},"Q3":{"id":"c12-Q3","prompt":{"zh":"动人提议反复出现却从不准备，这张逆位牌更贴近哪种情况？","en":"Repeated moving proposals lack preparation. What does the reversal mean here?"},"options":[{"id":"c12-Q3-859061c852","text":{"zh":"说得动人就已证明长期可靠","en":"Moving words already establish lasting reliability"},"feedback":{"zh":"题目说他从不完成答应的准备工作。提议再动听，也不能代替把答应的事做好。","en":"Follow-through is absent; expression cannot substitute for delivery."}},{"id":"c12-Q3-b0efa79be0","text":{"zh":"说得很动人，却没有照着承诺去做","en":"Ideal expression is disconnected from action"},"feedback":{"zh":"题目说他从不完成答应的准备工作。提议再动听，也不能代替把答应的事做好。","en":"Follow-through is absent; expression cannot substitute for delivery."}}],"correct":"c12-Q3-b0efa79be0","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"主动邀请，说明现在愿意靠近；以后是否可靠，还要看答应的事能不能做到。 记住：主动表达自己的感受或理想，不是“只在心里想，从不接近或表达”。","en":"The lesson supports an active expression; reliability depends on later conduct. Compare: Turn feeling or an ideal into an active expression; this cannot be replaced by “Only think privately, never approach or express”."}],"question":{"id":"c12-R1","prompt":{"zh":"收到浪漫邀请，能仅凭这张牌保证长久关系吗？","en":"a romantic invitation arrives. Does this card alone guarantee a lasting relationship?"},"options":[{"id":"c12-R1-dd4f841ba4","text":{"zh":"不能，发出一次邀请，不等于以后一定会守约","en":"No; an invitation differs from sustained commitment"},"feedback":{"zh":"主动邀请，说明现在愿意靠近；以后是否可靠，还要看答应的事能不能做到。","en":"The lesson supports an active expression; reliability depends on later conduct."}},{"id":"c12-R1-47342b88a2","text":{"zh":"能，一次邀请等于永久承诺","en":"Yes; one invitation equals a permanent promise"},"feedback":{"zh":"主动邀请，说明现在愿意靠近；以后是否可靠，还要看答应的事能不能做到。","en":"The lesson supports an active expression; reliability depends on later conduct."}}],"correct":"c12-R1-dd4f841ba4"}},"RA":{"teach":[{"zh":"邀请是把自己的心意送出去，让对方有机会回应。说明想做什么、为什么在意，并询问对方意愿，比替对方宣布同意更符合主动表达。","en":"An invitation carries your feeling outward and lets the other person respond. Explain the idea and why it matters, then ask about willingness rather than declaring agreement for them."}],"question":{"id":"c12-RA","prompt":{"zh":"想邀请另一社团合办音乐会，对方还没有答复。这张牌在建议位时，怎样做更合适？","en":"You invite another club to hold a concert together and have no reply yet. What fits?"},"options":[{"id":"c12-RA-9e52e206fc","text":{"zh":"因为自己的邀请很热情，就公布对方已加入。","en":"Announce their participation because your invitation was enthusiastic."},"feedback":{"zh":"自己介绍得真诚、热情，也还要听对方愿不愿意加入，不能替对方答应。","en":"“Announce their participation because your invitation was enthusiastic.” does not address the specific conditions. Enthusiasm is your action; participation still requires the other's response."}},{"id":"c12-RA-91c613609a","text":{"zh":"真诚介绍想办怎样的音乐会，再问对方愿不愿意一起商量。","en":"Explain the shared vision sincerely and ask whether they wish to discuss it."},"feedback":{"zh":"自己介绍得真诚、热情，也还要听对方愿不愿意加入，不能替对方答应。","en":"Enthusiasm is your action; participation still requires the other's response."}}],"correct":"c12-RA-91c613609a"}},"R2":{"teach":[{"zh":"缺的是按约完成准备工作，不是再换一种更动听的说法。 题目描述的是“说得很动人，却没有照着承诺去做”，不是“说得动人就已证明长期可靠”。","en":"The missing part is delivery, not sufficiently attractive language. Return to the stated context: “Ideal expression is disconnected from action” fits this case; “Moving words already establish lasting reliability” is unsupported by that context."}],"question":{"id":"c12-R2","prompt":{"zh":"合作方把计划说得很好，却已两次没交答应的材料。下一步怎样安排更合适？","en":"A partner describes an appealing plan but has twice failed to provide promised materials. What arrangement would help next?"},"options":[{"id":"c12-R2-011c16cac7","text":{"zh":"用更浪漫的说法替代所有交付","en":"Replace every deliverable with more romantic wording"},"feedback":{"zh":"缺的是按约完成准备工作，不是再换一种更动听的说法。","en":"The missing part is delivery, not sufficiently attractive language."}},{"id":"c12-R2-7ede74537d","text":{"zh":"约定先完成哪一项准备，再看是否按约做到了","en":"Set a clear small deliverable and observe follow-through"},"feedback":{"zh":"缺的是按约完成准备工作，不是再换一种更动听的说法。","en":"The missing part is delivery, not sufficiently attractive language."}}],"correct":"c12-R2-7ede74537d"}}},"revisit":{"id":"c12-V1","prompt":{"zh":"为喜欢的社区设计活动，主动递交一份提案。哪句贴近？","en":"affection for a community leads to submitting an event proposal. Which fits?"},"options":[{"id":"c12-V1-921a523d01","text":{"zh":"因为喜欢或认同，主动表达想法、争取参与","en":"Feeling and ideals drive a concrete approach and offer"},"feedback":{"zh":"主动表达也可用于创作和关怀，不限爱情。","en":"Active expression can concern creativity and care, not romance alone."}},{"id":"c12-V1-5e699582f1","text":{"zh":"圣杯骑士只能用在恋爱告白","en":"The Knight of Cups only applies to romantic confession"},"feedback":{"zh":"主动表达也可用于创作和关怀，不限爱情。","en":"Active expression can concern creativity and care, not romance alone."}}],"correct":"c12-V1-921a523d01"},"summary":{"zh":"因为喜欢、向往或被打动，主动表达心意，去接近想认识的人、想做的事。 骑士端着杯子向前走，可以帮助记住主动靠近、表达心意，不只是放在心里想。","en":"Bring a feeling or ideal into an active offer, invitation, or creative proposal. Moving toward what is valued is central; the gesture alone does not prove lasting reliability."},"cards":["c12"]},{"id":"c13","kind":"card","level":"I","title":{"zh":"圣杯王后","en":"Queen of Cups"},"teachings":[{"zh":"细心留意自己和别人的感受，愿意倾听，也懂得关心、体谅。 要理解别人，先听对方怎么说，再确认自己有没有听懂，不能凭感觉认定自己全知道。","en":"Attend closely to feeling and respond with empathy and care. Understanding another’s experience requires listening rather than assuming access to their private thoughts."},{"zh":"王后专注看着有盖的杯，靠近水面，帮助记住内在感受。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The seated figure studies an ornate covered cup near water, helping recall sustained attention to inner experience. This is a visual association for learning, not proof of an external event."},{"zh":"理解感受、倾听、关心、不过度承担。 王后在这里强调细心体会感受，圣杯对应的水元素帮助记住关心和理解。理解别人不等于读心，也不需要替别人承担所有事情。","en":"empathy; listening; care; boundaries. The Queen here sustains and responds to feeling; water relates to empathy, not mind-reading or carrying everyone’s responsibilities."}],"application":{"zh":"示范：先听懂难过的原因，再问需要什么帮助。先听、再问，才知道对方真正需要什么。没听完就说“我全明白”，可能把自己的想法当成了对方的感受。","en":"Example: understand the sadness and ask what help is wanted. Checking helps the response fit; defining feelings for someone bypasses listening."},"reversal":{"zh":"案例：倾听朋友后把对方所有困难都当成自己的责任，长期忽略自己的休息。这里的逆位，是太受朋友的情绪影响，把对方的责任也都揽到自己身上。","en":"Case: after listening to a friend, every difficulty becomes one’s own responsibility and rest is neglected. Here the reversal concerns overinvolvement and unclear boundaries."},"visual":{"zh":"王后专注看着有盖的杯，靠近水面，帮助记住内在感受。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"The seated figure studies an ornate covered cup near water, helping recall sustained attention to inner experience. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c13-Q1","prompt":{"zh":"圣杯王后所说的体谅别人，哪种做法更贴近？","en":"How is empathy understood?"},"options":[{"id":"c13-Q1-5a2a510ac2","text":{"zh":"认真倾听、体会感受再回应","en":"Listen carefully, understand feeling, then respond"},"feedback":{"zh":"要理解别人，先听对方怎么说，再确认自己有没有听懂，不能凭感觉认定自己全知道。","en":"Empathy depends on listening and understanding, not direct access to another mind."}},{"id":"c13-Q1-6ee692209d","text":{"zh":"不用询问就能确定对方全部想法","en":"Know all another person's thoughts without asking"},"feedback":{"zh":"要理解别人，先听对方怎么说，再确认自己有没有听懂，不能凭感觉认定自己全知道。","en":"Empathy depends on listening and understanding, not direct access to another mind."}}],"correct":"c13-Q1-5a2a510ac2","support":"R1"},"Q2":{"id":"c13-Q2","prompt":{"zh":"朋友正在为一件事烦恼。圣杯王后在建议位，怎样回应更合适？","en":"A friend is troubled by something. With the Queen of Cups as advice, which response fits?"},"options":[{"id":"c13-Q2-8db55a75ac","text":{"zh":"直接宣布自己知道对方全部感受","en":"Announce complete knowledge of the other's feelings"},"feedback":{"zh":"先听、再问，才知道对方真正需要什么。没听完就说“我全明白”，可能把自己的想法当成了对方的感受。","en":"Checking helps the response fit; defining feelings for someone bypasses listening."}},{"id":"c13-Q2-64e9c41a9e","text":{"zh":"先倾听并确认对方需要的支持","en":"Listen and check what support is needed"},"feedback":{"zh":"先听、再问，才知道对方真正需要什么。没听完就说“我全明白”，可能把自己的想法当成了对方的感受。","en":"Checking helps the response fit; defining feelings for someone bypasses listening."}}],"correct":"c13-Q2-64e9c41a9e","support":"RA"},"Q3":{"id":"c13-Q3","prompt":{"zh":"朋友的所有困难都变成自己的责任，这张逆位牌更贴近哪种情况？","en":"A friend's every difficulty becomes one’s own responsibility. What is this reversal?"},"options":[{"id":"c13-Q3-1a11e69ef6","text":{"zh":"太受对方情绪影响，分不清哪些事该由谁负责","en":"Emotional involvement blurs boundaries"},"feedback":{"zh":"替朋友做更多事，不等于更懂朋友。题目里已经连自己的休息都顾不上了。","en":"Extent of responsibility differs from depth of understanding; personal needs are being neglected."}},{"id":"c13-Q3-ef1a7a3c6f","text":{"zh":"承担越多就一定越懂对方","en":"Taking on more always means understanding better"},"feedback":{"zh":"替朋友做更多事，不等于更懂朋友。题目里已经连自己的休息都顾不上了。","en":"Extent of responsibility differs from depth of understanding; personal needs are being neglected."}}],"correct":"c13-Q3-1a11e69ef6","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"对方已经说明是累了，就应当按这个信息重新理解，不能坚持自己猜的“他在生气”。 记住：认真倾听、体会感受再回应，不是“不用询问就能确定对方全部想法”。","en":"Listening allows a guess to change; sensitivity is not certainty. Compare: Listen carefully, understand feeling, then respond; this cannot be replaced by “Know all another person's thoughts without asking”."}],"question":{"id":"c13-R1","prompt":{"zh":"对方说沉默是疲惫，你原先猜是生气。共情应该怎样做？","en":"silence is explained as fatigue rather than your guess of anger. What does empathy require?"},"options":[{"id":"c13-R1-417f174067","text":{"zh":"坚持自己的猜测一定更懂对方","en":"Insist your guess understands them better"},"feedback":{"zh":"对方已经说明是累了，就应当按这个信息重新理解，不能坚持自己猜的“他在生气”。","en":"Listening allows a guess to change; sensitivity is not certainty."}},{"id":"c13-R1-ce8d9b16dc","text":{"zh":"以对方说明为依据，继续倾听","en":"Use their explanation and keep listening"},"feedback":{"zh":"对方已经说明是累了，就应当按这个信息重新理解，不能坚持自己猜的“他在生气”。","en":"Listening allows a guess to change; sensitivity is not certainty."}}],"correct":"c13-R1-ce8d9b16dc"}},"RA":{"teach":[{"zh":"倾听时先让对方说明感受，再确认自己理解得是否准确。共情不是把自己的经历直接套到对方身上，也不是在对方开口前替他决定需要什么。","en":"Let someone explain their feelings and check your understanding. Empathy does not overwrite their experience with yours or decide their needs before they speak."}],"question":{"id":"c13-RA","prompt":{"zh":"朋友说工作压力大，但尚未说明最困难的部分。这张牌在建议位时，怎样做更合适？","en":"A friend mentions work pressure but has not described the hardest part. What fits?"},"options":[{"id":"c13-RA-3105d0c0b3","text":{"zh":"先听他说明，再确认希望得到哪种支持。","en":"Listen first, then check what support is wanted."},"feedback":{"zh":"朋友还没说清最难的是什么，就要先听完。自己经历过类似的事，也不能直接认定他遇到的完全一样。","en":"When the issue is unclear, listening and checking are needed; a similar experience is not the person's current information."}},{"id":"c13-RA-91af2134d1","text":{"zh":"直接按自己的经历认定原因和解决办法。","en":"Assume the cause and solution from your own past experience."},"feedback":{"zh":"朋友还没说清最难的是什么，就要先听完。自己经历过类似的事，也不能直接认定他遇到的完全一样。","en":"“Assume the cause and solution from your own past experience.” does not address the specific conditions. When the issue is unclear, listening and checking are needed; a similar experience is not the person's current information."}}],"correct":"c13-RA-3105d0c0b3"}},"R2":{"teach":[{"zh":"可以关心朋友，也可以保留自己的休息时间。不必把自己累坏，才能证明在乎对方。 题目描述的是“太受对方情绪影响，分不清哪些事该由谁负责”，不是“承担越多就一定越懂对方”。","en":"Care can have boundaries; empathy need not be proven by self-neglect. Return to the stated context: “Emotional involvement blurs boundaries” fits this case; “Taking on more always means understanding better” is unsupported by that context."}],"question":{"id":"c13-R2","prompt":{"zh":"为了陪伴朋友，总是取消自己的休息。怎样做才能关心对方，也顾到自己？","en":"You repeatedly cancel your rest to support a friend. How can you care for them while also caring for yourself?"},"options":[{"id":"c13-R2-7f9e899f62","text":{"zh":"说清自己能帮到哪一步，也留出休息时间","en":"Agree on support one can offer and keep recovery time"},"feedback":{"zh":"可以关心朋友，也可以保留自己的休息时间。不必把自己累坏，才能证明在乎对方。","en":"Care can have boundaries; empathy need not be proven by self-neglect."}},{"id":"c13-R2-9809c486e2","text":{"zh":"认定只有完全牺牲自己才是关怀","en":"Treat total self-sacrifice as the only form of care"},"feedback":{"zh":"可以关心朋友，也可以保留自己的休息时间。不必把自己累坏，才能证明在乎对方。","en":"Care can have boundaries; empathy need not be proven by self-neglect."}}],"correct":"c13-R2-7f9e899f62"}}},"revisit":{"id":"c13-V1","prompt":{"zh":"同事受挫，先倾听其感受，再确认是否需要协助。哪句贴近？","en":"a colleague is heard and asked whether help is wanted. Which fits?"},"options":[{"id":"c13-V1-98253284fb","text":{"zh":"自己感觉准确就无须确认","en":"A strong intuition removes the need to check"},"feedback":{"zh":"先听同事说，再问他是否需要帮助，就不容易把自己的猜测当成他的想法。","en":"The lesson connects care with checking, not treating a feeling as fact."}},{"id":"c13-V1-2e504bb492","text":{"zh":"先听懂对方，再提供自己能做到的帮助","en":"Respond with bounded care after attentive listening"},"feedback":{"zh":"先听同事说，再问他是否需要帮助，就不容易把自己的猜测当成他的想法。","en":"The lesson connects care with checking, not treating a feeling as fact."}}],"correct":"c13-V1-2e504bb492"},"summary":{"zh":"细心留意自己和别人的感受，愿意倾听，也懂得关心、体谅。 要理解别人，先听对方怎么说，再确认自己有没有听懂，不能凭感觉认定自己全知道。","en":"Attend closely to feeling and respond with empathy and care. Understanding another’s experience requires listening rather than assuming access to their private thoughts."},"cards":["c13"]},{"id":"c14","kind":"card","level":"I","title":{"zh":"圣杯国王","en":"King of Cups"},"teachings":[{"zh":"即使心里有难过、生气等情绪，也能稳住自己，想清楚再回应。 水面仍有波动，国王却坐得平稳。可以这样记：有情绪，也能冷静处理，不是完全没有情绪。","en":"Make room for complex emotions while keeping judgement and response steady. Maturity includes feeling and understanding emotions, not eliminating them."},{"zh":"国王拿着杯子端坐，周围的水面仍有波动。用这个画面记住：即使有情绪，也能稳住自己。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A seated figure holds a cup amid moving water, helping recall steadiness within an emotionally changing setting. This is a visual association for learning, not proof of an external event."},{"zh":"情绪稳定、包容、调解。 圣杯对应水元素，和感受有关；国王强调能稳妥处理这些感受。这不等于冷漠，也不限定性别或职位。","en":"emotional steadiness; tolerance; mediation. The King manages the emotional theme of water; steadiness is not coldness, a gender, or an authority title."}],"application":{"zh":"示范：先听清大家为什么不满，再商量怎样分工。先听清大家为什么不满，再商量分工。只禁止谈感受，看起来安静了，问题却还在。","en":"Example: hear emotions on each side, then decide roles clearly. A mature response addresses feeling and the issue rather than manufacturing calm through denial."},"reversal":{"zh":"案例：表面总说没事，却拒绝承认愤怒，最后在讨论中突然失控。这里的逆位，是一直压着情绪不说，后来忍不住发火。","en":"Case: anger is denied behind repeated claims that everything is fine, then erupts in discussion. Here the reversal concerns imbalance through suppression."},"visual":{"zh":"国王拿着杯子端坐，周围的水面仍有波动。用这个画面记住：即使有情绪，也能稳住自己。 这些画面细节用来帮助记住牌义，不能证明现实中一定会发生什么。","en":"A seated figure holds a cup amid moving water, helping recall steadiness within an emotionally changing setting. This is a visual association for learning, not proof of an external event."},"questions":{"Q1":{"id":"c14-Q1","prompt":{"zh":"水面有波动，国王却坐得平稳，可以帮助记住什么？","en":"What does the seated figure amid moving water teach here?"},"options":[{"id":"c14-Q1-8b59d72848","text":{"zh":"成熟意味着没有任何情绪","en":"Maturity means having no emotion at all"},"feedback":{"zh":"水面仍有波动，国王却坐得平稳。可以这样记：有情绪，也能冷静处理，不是完全没有情绪。","en":"The moving water remains; steadiness concerns response, not the absence of emotion."}},{"id":"c14-Q1-e32382e21b","text":{"zh":"有情绪，也能想清楚、稳妥地处理事情","en":"Allow emotion while keeping judgement and response steady"},"feedback":{"zh":"水面仍有波动，国王却坐得平稳。可以这样记：有情绪，也能冷静处理，不是完全没有情绪。","en":"The moving water remains; steadiness concerns response, not the absence of emotion."}}],"correct":"c14-Q1-e32382e21b","support":"R1"},"Q2":{"id":"c14-Q2","prompt":{"zh":"团队因为分工发生争执。圣杯国王在建议位，怎样处理更合适？","en":"A team is arguing about how work is divided. With the King of Cups as advice, which response fits?"},"options":[{"id":"c14-Q2-79d05cb0ff","text":{"zh":"先听清大家为什么不满，再冷静商量分歧","en":"Acknowledge feelings and handle the practical disagreement steadily"},"feedback":{"zh":"先听清大家为什么不满，再商量分工。只禁止谈感受，看起来安静了，问题却还在。","en":"A mature response addresses feeling and the issue rather than manufacturing calm through denial."}},{"id":"c14-Q2-02217a624d","text":{"zh":"禁止任何人提感受就算解决","en":"Ban mention of feelings and call the issue solved"},"feedback":{"zh":"先听清大家为什么不满，再商量分工。只禁止谈感受，看起来安静了，问题却还在。","en":"A mature response addresses feeling and the issue rather than manufacturing calm through denial."}}],"correct":"c14-Q2-79d05cb0ff","support":"RA"},"Q3":{"id":"c14-Q3","prompt":{"zh":"长期否认愤怒后突然爆发，这张逆位牌更贴近哪种情况？","en":"Denied anger eventually erupts. What is this reversal?"},"options":[{"id":"c14-Q3-0ad0d3c735","text":{"zh":"只要平时不说就证明情绪已处理","en":"Usual silence proves the emotion was resolved"},"feedback":{"zh":"一直不说，不代表怒气已经处理好了。后来忍不住发火，正说明之前的问题还在。","en":"Not expressing is not the same as understanding and regulating; the eruption shows the stated imbalance."}},{"id":"c14-Q3-7cf1c97abe","text":{"zh":"一直压着情绪不说，后来忍不住发火","en":"Suppression destabilises the response"},"feedback":{"zh":"一直不说，不代表怒气已经处理好了。后来忍不住发火，正说明之前的问题还在。","en":"Not expressing is not the same as understanding and regulating; the eruption shows the stated imbalance."}}],"correct":"c14-Q3-7cf1c97abe","support":"R2"}},"remediation":{"R1":{"teach":[{"zh":"难过不代表不能冷静商量事情。要看怎样处理，而不是要求自己一点情绪都没有。 记住：有情绪，也能想清楚、稳妥地处理事情，不是“成熟意味着没有任何情绪”。","en":"The lesson distinguishes having emotion from being entirely governed by it. Compare: Allow emotion while keeping judgement and response steady; this cannot be replaced by “Maturity means having no emotion at all”."}],"question":{"id":"c14-R1","prompt":{"zh":"承认自己难过，但仍能清楚商量下一步。算稳定吗？","en":"sadness is acknowledged while next steps are discussed clearly. Can this be steady?"},"options":[{"id":"c14-R1-3ead11d0fc","text":{"zh":"可以，有难过，也能冷静地回应","en":"Yes; a steady response can include emotion"},"feedback":{"zh":"难过不代表不能冷静商量事情。要看怎样处理，而不是要求自己一点情绪都没有。","en":"The lesson distinguishes having emotion from being entirely governed by it."}},{"id":"c14-R1-6361a11631","text":{"zh":"不可以，有难过就一定不成熟","en":"No; sadness necessarily means immaturity"},"feedback":{"zh":"难过不代表不能冷静商量事情。要看怎样处理，而不是要求自己一点情绪都没有。","en":"The lesson distinguishes having emotion from being entirely governed by it."}}],"correct":"c14-R1-3ead11d0fc"}},"RA":{"teach":[{"zh":"先听大家为什么不满，再商量具体怎么办。让人说出感受，不等于谁最激动就听谁的，事情仍要按清楚的规则处理。","en":"A steady response acknowledges feelings and then addresses the disagreement. Allowing feelings does not make them the sole basis for decisions; clear standards and empathy can coexist."}],"question":{"id":"c14-RA","prompt":{"zh":"活动成员因分工不满而激动，负责人需要继续安排任务。怎样应用？","en":"Members are upset about roles, and the organiser needs to assign work. What fits?"},"options":[{"id":"c14-RA-281ebddecf","text":{"zh":"只要求所有人别有情绪，不处理分工问题。","en":"Demand that nobody feel upset and leave roles unresolved."},"feedback":{"zh":"先听清不满，再协商分工，才能处理真正的问题。只叫大家别激动，分工上的分歧仍然没有解决。","en":"“Demand that nobody feel upset and leave roles unresolved.” does not address the specific conditions. The lesson combines emotional understanding and practical judgement; banning emotion does not resolve the dispute."}},{"id":"c14-RA-560fec4a24","text":{"zh":"先听清不满，再按明确条件协商分工。","en":"Hear the concerns, then agree on roles using clear conditions."},"feedback":{"zh":"先听清不满，再协商分工，才能处理真正的问题。只叫大家别激动，分工上的分歧仍然没有解决。","en":"The lesson combines emotional understanding and practical judgement; banning emotion does not resolve the dispute."}}],"correct":"c14-RA-560fec4a24"}},"R2":{"teach":[{"zh":"先承认自己在生气，才有机会好好表达。一直说“没事”，不代表情绪已经处理好了。 题目描述的是“一直压着情绪不说，后来忍不住发火”，不是“只要平时不说就证明情绪已处理”。","en":"Acknowledgement begins processing; protecting an image perpetuates suppression. Return to the stated context: “Suppression destabilises the response” fits this case; “Usual silence proves the emotion was resolved” is unsupported by that context."}],"question":{"id":"c14-R2","prompt":{"zh":"每次都说没事，过后却忍不住向伙伴发火。先做什么更合适？","en":"You repeatedly say you are fine, then lose your temper with your partner. What can you do first?"},"options":[{"id":"c14-R2-35525f90bc","text":{"zh":"继续否认情绪以维持成熟形象","en":"Keep denying feelings to preserve an image of maturity"},"feedback":{"zh":"先承认自己在生气，才有机会好好表达。一直说“没事”，不代表情绪已经处理好了。","en":"Acknowledgement begins processing; protecting an image perpetuates suppression."}},{"id":"c14-R2-72ca404b96","text":{"zh":"先承认自己在生气，再想怎样好好说出来","en":"Acknowledge the actual feeling and choose a steady expression"},"feedback":{"zh":"先承认自己在生气，才有机会好好表达。一直说“没事”，不代表情绪已经处理好了。","en":"Acknowledgement begins processing; protecting an image perpetuates suppression."}}],"correct":"c14-R2-72ca404b96"}}},"revisit":{"id":"c14-V1","prompt":{"zh":"活动取消让负责人失望，但他听取成员意见后安排替代方案。哪句贴近？","en":"a disappointed organiser listens and arranges an alternative after cancellation. Which fits?"},"options":[{"id":"c14-V1-0311b00ba9","text":{"zh":"理解情绪同时作成熟决定","en":"Understand emotion while making a mature decision"},"feedback":{"zh":"负责人可以为取消活动失望，也可以听完意见后安排新方案。难过不代表无法作决定。","en":"Feeling and judgement can coexist; the focus is response rather than eliminating disappointment."}},{"id":"c14-V1-733ca14c39","text":{"zh":"有失望就不可能作稳妥决定","en":"Disappointment makes a sound decision impossible"},"feedback":{"zh":"负责人可以为取消活动失望，也可以听完意见后安排新方案。难过不代表无法作决定。","en":"Feeling and judgement can coexist; the focus is response rather than eliminating disappointment."}}],"correct":"c14-V1-0311b00ba9"},"summary":{"zh":"即使心里有难过、生气等情绪，也能稳住自己，想清楚再回应。 水面仍有波动，国王却坐得平稳。可以这样记：有情绪，也能冷静处理，不是完全没有情绪。","en":"Make room for complex emotions while keeping judgement and response steady. Maturity includes feeling and understanding emotions, not eliminating them."},"cards":["c14"]},{"id":"s01","kind":"card","level":"I","title":{"zh":"宝剑王牌","en":"Ace of Swords"},"teachings":[{"zh":"宝剑王牌强调新的理解：先弄清事实和词语的意思，再作判断。它可以是找到问题关键的起点，不表示事情已经做完。","en":"The Ace of Swords concerns new clarity: distinguish facts and concepts to reach a clear judgment. It can mark an intellectual breakthrough, not completed execution."},{"zh":"云中伸出的手举着一把直立的剑，剑尖穿过王冠。可以用这把直立的剑，记住把思路理清、抓住重点；画面不证明某个结论必然正确。","en":"A hand emerges from a cloud holding an upright sword through a crown. Its clear, focused outline supports remembering concentrated thought; it does not prove a conclusion true."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关；王牌表示新的起点。这张牌可以记成：想清楚、看清事实、找到突破口。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air directs attention to thought and communication; an Ace suggests a beginning. Clarity, distinguishing facts, and breakthrough organize the meaning without requiring verbatim recall."}],"application":{"zh":"两位同学争论“作业是否完成”，却分别指初稿和终稿。建议位先让他们统一“完成”的定义，再检查实际进度。这是让判断有明确依据。","en":"Two students argue over whether work is finished, but one means a draft and the other a final version. In advice, first agree on the definition, then check progress: make the judgment well grounded."},"reversal":{"zh":"团队把未经核实的传言当成事实，作出了错误判断。这个例子里，宝剑王牌逆位提醒我们：思路出了问题，要先查来源、弄清事实。它也不表示传言一定是假的。","en":"Here, a team treats an unverified rumor as fact and becomes confused. Reversed, the card can indicate muddled judgment: verify and clarify first, rather than declare the rumor false."},"visual":{"zh":"云中伸出的手举着一把直立的剑，剑尖穿过王冠。可以用这把直立的剑，记住把思路理清、抓住重点；画面不证明某个结论必然正确。","en":"A hand emerges from a cloud holding an upright sword through a crown. Its clear, focused outline supports remembering concentrated thought; it does not prove a conclusion true."},"questions":{"Q1":{"id":"s01-Q1","prompt":{"zh":"宝剑王牌说的“想清楚”，首先指什么？","en":"What does clarity mean here?"},"options":[{"id":"s01-Q1-cfa9a5f79b","text":{"zh":"先弄清事实和词语的意思，再作判断。","en":"Distinguish facts and concepts before judging."},"feedback":{"zh":"弄懂要做什么，还不等于已经做完；这里先练习把问题想清楚。","en":"Understanding and completed execution are different."}},{"id":"s01-Q1-e833a7c2ec","text":{"zh":"既然想通了，工作就已经完成。","en":"Once understood, the work is already complete."},"feedback":{"zh":"弄懂要做什么，还不等于已经做完；这里先练习把问题想清楚。","en":"Understanding and completed execution are different."}}],"correct":"s01-Q1-cfa9a5f79b","support":"R1"},"Q2":{"id":"s01-Q2","prompt":{"zh":"回到刚才的作业例子，两位同学应该先做什么？","en":"In the assignment example, what comes first?"},"options":[{"id":"s01-Q2-a403f8d6f6","text":{"zh":"不说清“完成”指什么，只看谁说话更有把握。","en":"Skip the definition and count who sounds more certain."},"feedback":{"zh":"两人说的“完成”不是一回事：一个指初稿，一个指终稿。先说清这一点，才能继续讨论。","en":"Different definitions caused the dispute; clarify them first."}},{"id":"s01-Q2-779bb97e0d","text":{"zh":"先说清“完成”指写好初稿，还是交出终稿。","en":"Agree whether finished means draft or final."},"feedback":{"zh":"两人说的“完成”不是一回事：一个指初稿，一个指终稿。先说清这一点，才能继续讨论。","en":"Different definitions caused the dispute; clarify them first."}}],"correct":"s01-Q2-779bb97e0d","support":"R2"},"Q3":{"id":"s01-Q3","prompt":{"zh":"团队把传言当事实，本例逆位提醒什么？","en":"The team treats rumor as fact. What does this reversal suggest?"},"options":[{"id":"s01-Q3-5a1c4bec50","text":{"zh":"先查传言的来源，再重新判断。","en":"Check sources and reconsider the judgment."},"feedback":{"zh":"还没核实传言，就既不能认定它是真的，也不能认定它是假的。","en":"Confusion calls for verification, not another unsupported conclusion."}},{"id":"s01-Q3-01b9462a37","text":{"zh":"立刻认定传言一定是假的。","en":"Immediately declare the rumor false."},"feedback":{"zh":"还没核实传言，就既不能认定它是真的，也不能认定它是假的。","en":"Confusion calls for verification, not another unsupported conclusion."}}],"correct":"s01-Q3-5a1c4bec50","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"弄懂要做什么，还不等于已经做完；这里先练习把问题想清楚。","en":"Understanding and completed execution are different."},{"zh":"把答题纸写满不表示读懂了题目。先弄清题目要求，才抓住了这张牌强调的重点。","en":"The card concerns grasping the issue, not the appearance of completion."}],"question":{"id":"s01-R1","prompt":{"zh":"“弄清题目”和“完成作业”，哪一个更贴近宝剑王牌的意思？","en":"Which more directly illustrates this theme?"},"options":[{"id":"s01-R1-80f3773e55","text":{"zh":"无需理解，只把答题纸填满。","en":"Fill the page without understanding."},"feedback":{"zh":"把答题纸写满不表示读懂了题目。先弄清题目要求，才抓住了这张牌强调的重点。","en":"The card concerns grasping the issue, not the appearance of completion."}},{"id":"s01-R1-fb257d080b","text":{"zh":"弄清题目到底要求什么。","en":"Clarify what the question asks."},"feedback":{"zh":"把答题纸写满不表示读懂了题目。先弄清题目要求，才抓住了这张牌强调的重点。","en":"The card concerns grasping the issue, not the appearance of completion."}}],"correct":"s01-R1-fb257d080b"}},"R2":{"teach":[{"zh":"两人说的“完成”不是一回事：一个指初稿，一个指终稿。先说清这一点，才能继续讨论。","en":"Different definitions caused the dispute; clarify them first."},{"zh":"两人对“快”的理解不同。先约定到底是一小时还是一天，才知道怎样配合。","en":"A clear standard resolves the conceptual disagreement."}],"question":{"id":"s01-R2","prompt":{"zh":"项目争论“响应快”，一方指一小时一方指一天。先做什么？","en":"A project disputes fast response: one person means an hour, another a day. First?"},"options":[{"id":"s01-R2-c7202e6eab","text":{"zh":"说清双方要求多久回复，并写下来。","en":"Define a shared response-time standard."},"feedback":{"zh":"两人对“快”的理解不同。先约定到底是一小时还是一天，才知道怎样配合。","en":"A clear standard resolves the conceptual disagreement."}},{"id":"s01-R2-16167fb9b4","text":{"zh":"继续重复“我们都要更快”。","en":"Keep repeating that everyone should be faster."},"feedback":{"zh":"两人对“快”的理解不同。先约定到底是一小时还是一天，才知道怎样配合。","en":"A clear standard resolves the conceptual disagreement."}}],"correct":"s01-R2-c7202e6eab"}},"R3":{"teach":[{"zh":"团队把未经核实的传言当成事实，作出了错误判断。这个例子里，宝剑王牌逆位提醒我们：思路出了问题，要先查来源、弄清事实。它也不表示传言一定是假的。","en":"Here, a team treats an unverified rumor as fact and becomes confused. Reversed, the card can indicate muddled judgment: verify and clarify first, rather than declare the rumor false."},{"zh":"把话说得很肯定，并不会让传言更可靠；仍然要查来源。","en":"Clarity needs verification, not confident tone."}],"question":{"id":"s01-R3","prompt":{"zh":"现在有两种相反的传言，还没核实。按照宝剑王牌逆位的提醒，先做什么？","en":"Before verification, two claims conflict. After this reversal lesson, what next?"},"options":[{"id":"s01-R3-15eda8ed9d","text":{"zh":"分别查两种说法的来源，再作判断。","en":"Seek checkable evidence before concluding."},"feedback":{"zh":"把话说得很肯定，并不会让传言更可靠；仍然要查来源。","en":"Clarity needs verification, not confident tone."}},{"id":"s01-R3-73a5ff8565","text":{"zh":"随便选一种坚定说出来，就算澄清。","en":"State one confidently and call it clarity."},"feedback":{"zh":"把话说得很肯定，并不会让传言更可靠；仍然要查来源。","en":"Clarity needs verification, not confident tone."}}],"correct":"s01-R3-15eda8ed9d"}}},"revisit":{"id":"s01-V1","prompt":{"zh":"两份说明书用了不同的术语，借助宝剑王牌的提醒，先做什么？","en":"Two manuals use different terminology. Apply this theme."},"options":[{"id":"s01-V1-f747676371","text":{"zh":"看哪份更长，就认定哪份正确。","en":"Assume the longer manual is right."},"feedback":{"zh":"先弄清两份说明书的术语各指什么，才能比较内容；写得长不代表写得对。","en":"Clarity comes from meaning, not length."}},{"id":"s01-V1-5a969ef3ef","text":{"zh":"先弄清两份说明书里的术语各指什么，再比较内容。","en":"Map the terms before comparing the content."},"feedback":{"zh":"先弄清两份说明书的术语各指什么，才能比较内容；写得长不代表写得对。","en":"Clarity comes from meaning, not length."}}],"correct":"s01-V1-5a969ef3ef"},"summary":{"zh":"宝剑王牌强调新的理解：先弄清事实和词语的意思，再作判断。它可以是找到问题关键的起点，不表示事情已经做完。","en":"The Ace of Swords concerns new clarity: distinguish facts and concepts to reach a clear judgment. It can mark an intellectual breakthrough, not completed execution."},"cards":["s01"]},{"id":"s02","kind":"card","level":"I","title":{"zh":"宝剑二","en":"Two of Swords"},"teachings":[{"zh":"宝剑二呈现暂时把决定搁置，迟迟不肯作选择的状态。回避信息或不愿承认感受会让僵持延续；它不表示两个选项本来就一样好。","en":"The Two of Swords depicts a balance held at the cost of a stalled decision. Avoiding information or feelings can sustain the stalemate; it does not mean both options are equally good."},{"zh":"蒙眼的人交叉持剑，坐在水边。蒙眼和交叉持剑的姿态，帮助记住不愿面对信息、暂时保护自己的状态；我们不能从姿态读出具体选择内容。","en":"A blindfolded figure crosses two swords beside water. The blindfold and guarded posture support remembering closure and defense, not the exact options being considered."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关。数字二让我们留意两边的关系；在这张牌里，两边难以取舍，形成了僵持。可以记成：难以决定、回避选择。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air concerns judgment; two draws attention to tension between alternatives, but not every Two means stalemate. Helpers: stalemate, avoiding a decision."}],"application":{"zh":"小周在两门课之间犹豫，却一直不看课程要求。建议位可以先核对时间与先修条件，了解作决定前必须知道的事情，而不是继续把选择搁置。","en":"Zhou cannot choose between two classes but avoids reading their requirements. Advice is to check schedules and prerequisites so the decision gains necessary information."},"reversal":{"zh":"报名快截止了，小周又收到两门课的新要求，已经不能继续拖着不选。这个例子里，宝剑二逆位表示原来回避的选择必须面对了；信息增加，也带来了压力。但选哪门课，仍要看具体条件。","en":"With the deadline near and new requirements arriving, not deciding is no longer sustainable. This reversal means the stalemate is breaking under information pressure, not that one option is guaranteed right."},"visual":{"zh":"蒙眼的人交叉持剑，坐在水边。蒙眼和交叉持剑的姿态，帮助记住不愿面对信息、暂时保护自己的状态；我们不能从姿态读出具体选择内容。","en":"A blindfolded figure crosses two swords beside water. The blindfold and guarded posture support remembering closure and defense, not the exact options being considered."},"questions":{"Q1":{"id":"s02-Q1","prompt":{"zh":"宝剑二所说的“迟迟不决定”，是怎样的情况？","en":"What kind of pause is shown here?"},"options":[{"id":"s02-Q1-bf48d80238","text":{"zh":"已经充分比较，确定两个选项一样好。","en":"A full comparison proved the options identical."},"feedback":{"zh":"不去了解选项，只是暂时避开决定；这不表示已经比较过，也不表示两边一样好。","en":"Defensive balance differs from an informed conclusion."}},{"id":"s02-Q1-2d564e37c9","text":{"zh":"不愿看需要了解的信息，迟迟作不了决定。","en":"Information is blocked and a decision stalls."},"feedback":{"zh":"不去了解选项，只是暂时避开决定；这不表示已经比较过，也不表示两边一样好。","en":"Defensive balance differs from an informed conclusion."}}],"correct":"s02-Q1-2d564e37c9","support":"R1"},"Q2":{"id":"s02-Q2","prompt":{"zh":"小周没读课程要求，先做什么？","en":"Zhou has not read the class requirements. First?"},"options":[{"id":"s02-Q2-d7bd6b6abb","text":{"zh":"查看时间和先修条件。","en":"Check schedules and prerequisites."},"feedback":{"zh":"小周还不知道上课时间和先修要求。先查清这些条件，才知道哪门课适合自己。","en":"The missing information is known; obtain it to move forward."}},{"id":"s02-Q2-0ca62b2a19","text":{"zh":"不看要求，继续保持两边都不选。","en":"Avoid requirements and keep neither choice."},"feedback":{"zh":"小周还不知道上课时间和先修要求。先查清这些条件，才知道哪门课适合自己。","en":"The missing information is known; obtain it to move forward."}}],"correct":"s02-Q2-d7bd6b6abb","support":"R2"},"Q3":{"id":"s02-Q3","prompt":{"zh":"报名快截止了，又收到新的课程要求，这个逆位例子在说什么？","en":"Deadline and new information arrive. What does this reversal describe?"},"options":[{"id":"s02-Q3-1c1687ddc7","text":{"zh":"已经能保证其中一门课一定适合小周。","en":"One course is now guaranteed suitable."},"feedback":{"zh":"小周不能再靠拖延避开选择了，但还得比较两门课，牌不会替他决定。","en":"The context supports pressure breaking balance, not a guaranteed outcome."}},{"id":"s02-Q3-ead4901566","text":{"zh":"已经不能继续拖着不选了。","en":"The old stalemate cannot be maintained."},"feedback":{"zh":"小周不能再靠拖延避开选择了，但还得比较两门课，牌不会替他决定。","en":"The context supports pressure breaking balance, not a guaranteed outcome."}}],"correct":"s02-Q3-ead4901566","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"不去了解选项，只是暂时避开决定；这不表示已经比较过，也不表示两边一样好。","en":"Defensive balance differs from an informed conclusion."},{"zh":"不去看课程要求，仍然会有时间和难度的差别，只是小周还不知道。","en":"Avoidance stalls a decision; it cannot remove real differences."}],"question":{"id":"s02-R1","prompt":{"zh":"“暂时不看”为什么不等于“已经想清楚”？","en":"Why is refusing to look different from reaching clarity?"},"options":[{"id":"s02-R1-a80523d793","text":{"zh":"因为还没了解作决定需要的信息。","en":"Needed information has not entered the judgment."},"feedback":{"zh":"不去看课程要求，仍然会有时间和难度的差别，只是小周还不知道。","en":"Avoidance stalls a decision; it cannot remove real differences."}},{"id":"s02-R1-a41d62a590","text":{"zh":"因为只要闭眼就会自动消除差异。","en":"Closing one’s eyes removes differences."},"feedback":{"zh":"不去看课程要求，仍然会有时间和难度的差别，只是小周还不知道。","en":"Avoidance stalls a decision; it cannot remove real differences."}}],"correct":"s02-R1-a80523d793"}},"R2":{"teach":[{"zh":"小周还不知道上课时间和先修要求。先查清这些条件，才知道哪门课适合自己。","en":"The missing information is known; obtain it to move forward."},{"zh":"看过排班，才能知道哪份兼职与自己的时间冲突；一直收着不看，就仍然无从选择。","en":"Facts help resolve stalemate better than maintaining appearances."}],"question":{"id":"s02-R2","prompt":{"zh":"两份兼职邀请都没读排班，怎样推进？","en":"Two job offers remain unread. How can the decision move?"},"options":[{"id":"s02-R2-bf3c616d9c","text":{"zh":"把两份邀请收起来，假定完全一样。","en":"Put them away and assume they are identical."},"feedback":{"zh":"看过排班，才能知道哪份兼职与自己的时间冲突；一直收着不看，就仍然无从选择。","en":"Facts help resolve stalemate better than maintaining appearances."}},{"id":"s02-R2-19483c1dee","text":{"zh":"先核对排班与自己的可用时间。","en":"Compare schedules with actual availability."},"feedback":{"zh":"看过排班，才能知道哪份兼职与自己的时间冲突；一直收着不看，就仍然无从选择。","en":"Facts help resolve stalemate better than maintaining appearances."}}],"correct":"s02-R2-19483c1dee"}},"R3":{"teach":[{"zh":"报名快截止了，小周又收到两门课的新要求，已经不能继续拖着不选。这个例子里，宝剑二逆位表示原来回避的选择必须面对了；信息增加，也带来了压力。但选哪门课，仍要看具体条件。","en":"With the deadline near and new requirements arriving, not deciding is no longer sustainable. This reversal means the stalemate is breaking under information pressure, not that one option is guaranteed right."},{"zh":"截止日期逼近，只说明必须面对选择了；选哪一项仍要看具体条件。","en":"Pressure breaks stalemate without replacing comparison."}],"question":{"id":"s02-R3","prompt":{"zh":"原来回避的决定已不能拖，下一步是什么？","en":"An avoided decision can no longer wait. What next?"},"options":[{"id":"s02-R3-7c8c227d68","text":{"zh":"既然压力增加，就假定两个选项都自动失效。","en":"Assume both options are invalid because pressure rose."},"feedback":{"zh":"截止日期逼近，只说明必须面对选择了；选哪一项仍要看具体条件。","en":"Pressure breaks stalemate without replacing comparison."}},{"id":"s02-R3-f29f8c5d4c","text":{"zh":"根据新要求重新比较两门课，再作决定。","en":"Include new information and face the decision."},"feedback":{"zh":"截止日期逼近，只说明必须面对选择了；选哪一项仍要看具体条件。","en":"Pressure breaks stalemate without replacing comparison."}}],"correct":"s02-R3-f29f8c5d4c"}}},"revisit":{"id":"s02-V1","prompt":{"zh":"决定合租前不愿谈作息，宝剑二提醒我们什么？","en":"Before sharing an apartment, someone avoids discussing routines. What fits?"},"options":[{"id":"s02-V1-5b025ca3a8","text":{"zh":"把彼此的作息和生活习惯说清楚。","en":"Discuss the avoided living conditions."},"feedback":{"zh":"不谈作息，彼此的作息差异也不会消失；合租前仍要说清楚。","en":"Undiscussed information still affects the decision."}},{"id":"s02-V1-6531efc8d7","text":{"zh":"不谈差异就表示没有差异。","en":"Unmentioned differences do not exist."},"feedback":{"zh":"不谈作息，彼此的作息差异也不会消失；合租前仍要说清楚。","en":"Undiscussed information still affects the decision."}}],"correct":"s02-V1-5b025ca3a8"},"summary":{"zh":"宝剑二呈现暂时把决定搁置，迟迟不肯作选择的状态。回避信息或不愿承认感受会让僵持延续；它不表示两个选项本来就一样好。","en":"The Two of Swords depicts a balance held at the cost of a stalled decision. Avoiding information or feelings can sustain the stalemate; it does not mean both options are equally good."},"cards":["s02"]},{"id":"s03","kind":"card","level":"I","title":{"zh":"宝剑三","en":"Three of Swords"},"teachings":[{"zh":"宝剑三表达因事实、冲突或分离带来的伤痛。先承认伤在哪里，再决定怎样回应；它不自动指三角关系，也不证明第三个人存在。","en":"The Three of Swords expresses pain caused by a fact, conflict, or separation. Acknowledge the hurt before responding; it does not automatically indicate a love triangle or a third person."},{"zh":"三把剑穿过心，背景有雨云。这是伤痛的象征画面，不是对现实伤害方式的记录。","en":"Three swords pierce a heart against rain clouds. This is symbolic imagery of pain, not a record of a real injury."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关。听到事实或某句话，也可能让人难过。这里的三把剑不能直接换算成三个人。可以记成：伤痛、分离、面对事实。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air reminds us that facts and words can cause emotional pain; three swords do not count people. Helpers: hurt, separation, facing facts."}],"application":{"zh":"朋友明确拒绝合作，小安很难过。建议位先承认被拒绝的失落，弄清合作为何停止，再决定后续沟通；不用假装没有受伤。","en":"A friend clearly declines a collaboration and An feels hurt. Advice is to acknowledge disappointment, clarify why the collaboration stopped, and then decide how to communicate."},"reversal":{"zh":"小安已经愿意谈这次受伤的经历，也开始重新安排生活。这个例子里，宝剑三逆位表示痛苦正在慢慢减轻、生活开始恢复，不表示那次拒绝没有发生过。","en":"An has begun talking about the hurt and rebuilding daily life. Here the reversal represents gradual release and repair, not denial that the rejection happened."},"visual":{"zh":"三把剑穿过心，背景有雨云。这是伤痛的象征画面，不是对现实伤害方式的记录。","en":"Three swords pierce a heart against rain clouds. This is symbolic imagery of pain, not a record of a real injury."},"questions":{"Q1":{"id":"s03-Q1","prompt":{"zh":"宝剑三首先让我们留意什么？","en":"What is the central lesson?"},"options":[{"id":"s03-Q1-fc14100a12","text":{"zh":"承认事实带来的伤痛。","en":"Acknowledge pain caused by what happened."},"feedback":{"zh":"三把剑用来表现伤痛，不是说这件事里一定有三个人。","en":"Symbolic pain cannot establish a number of people."}},{"id":"s03-Q1-c2d2d0ba1f","text":{"zh":"从三把剑确定有三个当事人。","en":"Infer exactly three people from three swords."},"feedback":{"zh":"三把剑用来表现伤痛，不是说这件事里一定有三个人。","en":"Symbolic pain cannot establish a number of people."}}],"correct":"s03-Q1-fc14100a12","support":"R1"},"Q2":{"id":"s03-Q2","prompt":{"zh":"朋友拒绝合作后，应该先怎样做？","en":"After the friend declines collaboration, which follows the example?"},"options":[{"id":"s03-Q2-6934b4a00b","text":{"zh":"因为牌有三剑，就指控有人插手。","en":"Accuse another person because there are three swords."},"feedback":{"zh":"已知事实是合作被拒，不是第三人介入。","en":"The known fact is rejection, not third-party involvement."}},{"id":"s03-Q2-33e5d9f9e6","text":{"zh":"先承认失落，再澄清停止合作的原因。","en":"Acknowledge disappointment and clarify the reason."},"feedback":{"zh":"已知事实是合作被拒，不是第三人介入。","en":"The known fact is rejection, not third-party involvement."}}],"correct":"s03-Q2-33e5d9f9e6","support":"R2"},"Q3":{"id":"s03-Q3","prompt":{"zh":"已经开始谈伤痛并恢复生活，逆位怎样表达？","en":"Speaking about hurt and rebuilding life: interpret this reversal."},"options":[{"id":"s03-Q3-6f4a132170","text":{"zh":"开始承认这次伤痛，慢慢恢复生活。","en":"Gradual repair after acknowledging the pain."},"feedback":{"zh":"慢慢好起来，不等于当初没有受伤；恢复是在承认这段经历之后发生的。","en":"Recovery follows experience; it does not erase it."}},{"id":"s03-Q3-8da0a11dec","text":{"zh":"从来没有受伤，不需要承认。","en":"There was never any hurt to acknowledge."},"feedback":{"zh":"慢慢好起来，不等于当初没有受伤；恢复是在承认这段经历之后发生的。","en":"Recovery follows experience; it does not erase it."}}],"correct":"s03-Q3-6f4a132170","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"三把剑用来表现伤痛，不是说这件事里一定有三个人。","en":"Symbolic pain cannot establish a number of people."},{"zh":"难过是真实的，但“有人背叛了我”仍是需要证据的判断。","en":"A real feeling does not verify every guessed cause."}],"question":{"id":"s03-R1","prompt":{"zh":"“感到受伤”和“确定有人背叛”，哪一个是宝剑三能够表达的？","en":"Which is supported by this lesson?"},"options":[{"id":"s03-R1-0c542da612","text":{"zh":"只要痛苦，就已证明别人背叛。","en":"Pain itself proves betrayal."},"feedback":{"zh":"难过是真实的，但“有人背叛了我”仍是需要证据的判断。","en":"A real feeling does not verify every guessed cause."}},{"id":"s03-R1-2bce562498","text":{"zh":"这张牌表达伤痛；有没有人背叛，还需要事实来判断。","en":"Hurt is a theme; betrayal needs separate evidence."},"feedback":{"zh":"难过是真实的，但“有人背叛了我”仍是需要证据的判断。","en":"A real feeling does not verify every guessed cause."}}],"correct":"s03-R1-2bce562498"}},"R2":{"teach":[{"zh":"已知事实是合作被拒，不是第三人介入。","en":"The known fact is rejection, not third-party involvement."},{"zh":"承认落选后的失落，才能接着处理这件事；要求自己立刻开心，并没有处理难过的原因。","en":"Facing hurt fits the theme better than denying it."}],"question":{"id":"s03-R2","prompt":{"zh":"选拔落选后很失落，先怎样处理？","en":"After missing a selection, what fits?"},"options":[{"id":"s03-R2-3b62b45a2a","text":{"zh":"承认失落，了解反馈再决定下一步。","en":"Acknowledge disappointment and seek feedback."},"feedback":{"zh":"承认落选后的失落，才能接着处理这件事；要求自己立刻开心，并没有处理难过的原因。","en":"Facing hurt fits the theme better than denying it."}},{"id":"s03-R2-acd52e87c7","text":{"zh":"先否认难过，要求自己马上开心。","en":"Deny sadness and demand instant happiness."},"feedback":{"zh":"承认落选后的失落，才能接着处理这件事；要求自己立刻开心，并没有处理难过的原因。","en":"Facing hurt fits the theme better than denying it."}}],"correct":"s03-R2-3b62b45a2a"}},"R3":{"teach":[{"zh":"小安已经愿意谈这次受伤的经历，也开始重新安排生活。这个例子里，宝剑三逆位表示痛苦正在慢慢减轻、生活开始恢复，不表示那次拒绝没有发生过。","en":"An has begun talking about the hurt and rebuilding daily life. Here the reversal represents gradual release and repair, not denial that the rejection happened."},{"zh":"恢复需要时间，偶尔难过并不表示前面的恢复都白费了。","en":"Repair is a process, not denial."}],"question":{"id":"s03-R3","prompt":{"zh":"开始恢复时偶尔仍难过，会否定本例逆位吗？","en":"Does occasional sadness negate recovery here?"},"options":[{"id":"s03-R3-f49d5740d1","text":{"zh":"不会，慢慢恢复不表示痛苦要一下全部消失。","en":"No; gradual repair need not erase pain instantly."},"feedback":{"zh":"恢复需要时间，偶尔难过并不表示前面的恢复都白费了。","en":"Repair is a process, not denial."}},{"id":"s03-R3-93643dcded","text":{"zh":"会，恢复必须证明从未难过。","en":"Yes; recovery must prove there was never pain."},"feedback":{"zh":"恢复需要时间，偶尔难过并不表示前面的恢复都白费了。","en":"Repair is a process, not denial."}}],"correct":"s03-R3-f49d5740d1"}}},"revisit":{"id":"s03-V1","prompt":{"zh":"一次坦白让关系受伤，哪句话更贴近宝剑三的意思？","en":"An honest conversation hurts a relationship. Which fits?"},"options":[{"id":"s03-V1-c3055bbdfd","text":{"zh":"牌已经确定双方永远无法修复。","en":"The card guarantees the relationship can never heal."},"feedback":{"zh":"这张牌让我们注意当下的伤痛，不能由此断定关系永远无法修复。","en":"The meaning describes hurt without fixing the permanent outcome."}},{"id":"s03-V1-8bff26e42d","text":{"zh":"先处理听到事实后的痛苦。","en":"Address the pain of hearing the facts."},"feedback":{"zh":"这张牌让我们注意当下的伤痛，不能由此断定关系永远无法修复。","en":"The meaning describes hurt without fixing the permanent outcome."}}],"correct":"s03-V1-8bff26e42d"},"summary":{"zh":"宝剑三表达因事实、冲突或分离带来的伤痛。先承认伤在哪里，再决定怎样回应；它不自动指三角关系，也不证明第三个人存在。","en":"The Three of Swords expresses pain caused by a fact, conflict, or separation. Acknowledge the hurt before responding; it does not automatically indicate a love triangle or a third person."},"cards":["s03"]},{"id":"s04","kind":"card","level":"I","title":{"zh":"宝剑四","en":"Four of Swords"},"teachings":[{"zh":"宝剑四强调暂时离开一直让自己疲惫的事情，好好休息，理清思路，再考虑下一步。休整是阶段性的，不等于失败或永远放弃。","en":"The Four of Swords concerns stepping back from ongoing strain to regain capacity before deciding what comes next. Rest is temporary, not failure or permanent surrender."},{"zh":"室内横卧的人像与静止的剑形成安静场景。用静止的画面记住暂时休息，不把墓像解释成现实死亡。","en":"A reclining effigy and motionless swords create a quiet interior. Remember restoration through stillness without predicting literal death."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关。数字四可以帮助记住稳定与安静；这张牌的安静画面，进一步提醒我们让思绪休息。可以记成：休息、暂停、恢复。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air relates to thought; four can suggest a stable space. Restoration belongs to this card, not every Four. Helpers: rest, pause, recovery."}],"application":{"zh":"连日赶作业使小许难以集中。建议位先安排一段真正不处理作业的休息，再回到计划；不是把休息换成继续刷工作消息。","en":"After days of assignments, Xu cannot concentrate. Advice is a genuine break from the work, then a return to planning—not replacing work with work messages."},"reversal":{"zh":"小许说自己在休息，却一直回复任务消息、担心漏掉工作。这个例子里，宝剑四逆位表示还没能真正休息，需要减少打扰、留出休息时间，不表示以后永远恢复不了。","en":"Xu calls it rest but keeps answering task messages. Here the reversal indicates interrupted restoration and the need to change conditions, not permanent inability to recover."},"visual":{"zh":"室内横卧的人像与静止的剑形成安静场景。用静止的画面记住暂时休息，不把墓像解释成现实死亡。","en":"A reclining effigy and motionless swords create a quiet interior. Remember restoration through stillness without predicting literal death."},"questions":{"Q1":{"id":"s04-Q1","prompt":{"zh":"宝剑四所说的暂停，是为了什么？","en":"What is the pause for?"},"options":[{"id":"s04-Q1-95c3e2321d","text":{"zh":"证明自己失败，永久退出。","en":"Prove failure and leave forever."},"feedback":{"zh":"暂停是为了恢复后再继续，不是宣布从此不做了。","en":"Temporary recovery differs from permanent withdrawal."}},{"id":"s04-Q1-8d8cda5485","text":{"zh":"恢复状态，再考虑下一步。","en":"Regain capacity before the next step."},"feedback":{"zh":"暂停是为了恢复后再继续，不是宣布从此不做了。","en":"Temporary recovery differs from permanent withdrawal."}}],"correct":"s04-Q1-8d8cda5485","support":"R1"},"Q2":{"id":"s04-Q2","prompt":{"zh":"小许赶作业后难以集中，哪项更符合建议？","en":"Xu cannot focus after prolonged work. What fits?"},"options":[{"id":"s04-Q2-8e00797ed1","text":{"zh":"先停下作业休息，并约好什么时候回来继续。","en":"Take a real break and plan a return."},"feedback":{"zh":"虽然没在写作业，但一直看任务消息，注意力仍被工作占着，还没有真正休息。","en":"Constant task input continues the strain."}},{"id":"s04-Q2-d26305765a","text":{"zh":"停下写作业，但持续刷新任务消息。","en":"Stop writing but keep checking task messages."},"feedback":{"zh":"虽然没在写作业，但一直看任务消息，注意力仍被工作占着，还没有真正休息。","en":"Constant task input continues the strain."}}],"correct":"s04-Q2-8e00797ed1","support":"R2"},"Q3":{"id":"s04-Q3","prompt":{"zh":"休息时仍不断回任务消息，本例逆位提示什么？","en":"Task messages continue during rest. What does this reversal suggest?"},"options":[{"id":"s04-Q3-624bc32c24","text":{"zh":"已经永远失去恢复能力。","en":"Recovery is permanently impossible."},"feedback":{"zh":"这个例子只说明休息不断被打断，不能说小许以后再也恢复不了。","en":"The background supports insufficient rest, not permanence."}},{"id":"s04-Q3-d34cc4d14a","text":{"zh":"休息一直被打断，需要留出不处理任务的时间。","en":"Rest is interrupted; protect the break."},"feedback":{"zh":"这个例子只说明休息不断被打断，不能说小许以后再也恢复不了。","en":"The background supports insufficient rest, not permanence."}}],"correct":"s04-Q3-d34cc4d14a","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"暂停是为了恢复后再继续，不是宣布从此不做了。","en":"Temporary recovery differs from permanent withdrawal."},{"zh":"想继续做好一件事，也可以先停下来休息；不停工作不一定做得更好。","en":"Continued commitment does not require eliminating rest."}],"question":{"id":"s04-R1","prompt":{"zh":"暂停一晚再整理计划，是否等于放弃？","en":"Does a night off before replanning equal surrender?"},"options":[{"id":"s04-R1-e7061acc8a","text":{"zh":"不是，暂停可以帮助自己恢复状态。","en":"No; a pause can support recovery."},"feedback":{"zh":"想继续做好一件事，也可以先停下来休息；不停工作不一定做得更好。","en":"Continued commitment does not require eliminating rest."}},{"id":"s04-R1-dda4103af8","text":{"zh":"是，只有不停工作才算继续。","en":"Yes; only uninterrupted work counts."},"feedback":{"zh":"想继续做好一件事，也可以先停下来休息；不停工作不一定做得更好。","en":"Continued commitment does not require eliminating rest."}}],"correct":"s04-R1-e7061acc8a"}},"R2":{"teach":[{"zh":"虽然没在写作业，但一直看任务消息，注意力仍被工作占着，还没有真正休息。","en":"Constant task input continues the strain."},{"zh":"想缓过来，需要暂时不处理排练的事；一直看失误录像，注意力仍在任务上。","en":"Restoration needs space away from task strain."}],"question":{"id":"s04-R2","prompt":{"zh":"密集排练后失误变多，按照宝剑四的提醒，先做什么？","en":"Errors rise after intensive rehearsal. Apply the theme."},"options":[{"id":"s04-R2-bdb7c16bef","text":{"zh":"把休息全部换成观看自己的失误录像。","en":"Replace all rest with reviewing mistakes."},"feedback":{"zh":"想缓过来，需要暂时不处理排练的事；一直看失误录像，注意力仍在任务上。","en":"Restoration needs space away from task strain."}},{"id":"s04-R2-19ed3cdb9f","text":{"zh":"先安静休息，再看接下来的排练怎么安排。","en":"Rest quietly, then reassess the schedule."},"feedback":{"zh":"想缓过来，需要暂时不处理排练的事；一直看失误录像，注意力仍在任务上。","en":"Restoration needs space away from task strain."}}],"correct":"s04-R2-19ed3cdb9f"}},"R3":{"teach":[{"zh":"小许说自己在休息，却一直回复任务消息、担心漏掉工作。这个例子里，宝剑四逆位表示还没能真正休息，需要减少打扰、留出休息时间，不表示以后永远恢复不了。","en":"Xu calls it rest but keeps answering task messages. Here the reversal indicates interrupted restoration and the need to change conditions, not permanent inability to recover."},{"zh":"关掉消息只是减少打扰，还要真正休息一段时间，才能看看状态有没有恢复。","en":"Removing interruption improves conditions; recovery still takes time."}],"question":{"id":"s04-R3","prompt":{"zh":"关闭工作消息后仍需休整，下一步是什么？","en":"After muting work messages, rest is still needed. What next?"},"options":[{"id":"s04-R3-de32b68708","text":{"zh":"既已关消息，就立即恢复满负荷工作。","en":"Resume maximum work instantly because messages are off."},"feedback":{"zh":"关掉消息只是减少打扰，还要真正休息一段时间，才能看看状态有没有恢复。","en":"Removing interruption improves conditions; recovery still takes time."}},{"id":"s04-R3-06409fb18b","text":{"zh":"真正休息一段时间，再看看自己缓过来没有。","en":"Allow real recovery time, then reassess."},"feedback":{"zh":"关掉消息只是减少打扰，还要真正休息一段时间，才能看看状态有没有恢复。","en":"Removing interruption improves conditions; recovery still takes time."}}],"correct":"s04-R3-06409fb18b"}}},"revisit":{"id":"s04-V1","prompt":{"zh":"争论后思路混乱，哪种做法符合宝剑四的提醒？","en":"Thinking is muddled after an argument. Which fits?"},"options":[{"id":"s04-V1-4195505917","text":{"zh":"约好稍后再谈，先让自己安静下来。","en":"Agree to talk later and settle first."},"feedback":{"zh":"约好稍后再谈，是先让自己平静下来，并没有放弃之后的沟通。","en":"The pause supports recovery rather than canceling communication."}},{"id":"s04-V1-e35a3567a7","text":{"zh":"以暂停为由永久拒绝所有沟通。","en":"Use the pause to refuse all future discussion."},"feedback":{"zh":"约好稍后再谈，是先让自己平静下来，并没有放弃之后的沟通。","en":"The pause supports recovery rather than canceling communication."}}],"correct":"s04-V1-4195505917"},"summary":{"zh":"宝剑四强调暂时离开一直让自己疲惫的事情，好好休息，理清思路，再考虑下一步。休整是阶段性的，不等于失败或永远放弃。","en":"The Four of Swords concerns stepping back from ongoing strain to regain capacity before deciding what comes next. Rest is temporary, not failure or permanent surrender."},"cards":["s04"]},{"id":"s05","kind":"card","level":"I","title":{"zh":"宝剑五","en":"Five of Swords"},"teachings":[{"zh":"宝剑五关注冲突中的胜负与代价：赢下一场争执，也可能让同伴不再愿意合作。它提醒检查赢的方式，而不是给某人贴坏人标签。","en":"The Five of Swords concerns winning and its cost: an argument may be won while cooperation is damaged. Examine the manner of winning rather than labeling someone bad."},{"zh":"一人收拢剑，另两人离去，胜者与离开者同时出现在画面。记住“赢了什么，又失去了什么”。","en":"One figure gathers swords while two leave. Remember both what was won and what was lost."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关；数字五可以帮助记住冲突和变化。结合有人收剑、有人离开的画面，可以记成：争输赢、赢了也有损失。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air concerns arguments and judgment; five suggests disturbance without proving malice. Helpers: competing to win, costly victory."}],"application":{"zh":"会议里小陈用羞辱同伴的方式让方案通过，但同伴不愿再协作。建议位应回到共同目标、处理羞辱给合作带来的伤害，不只庆祝方案获胜。","en":"Chen gets a proposal accepted by humiliating teammates, who then withdraw cooperation. Advice is to repair collaboration around the shared goal, not merely celebrate approval."},"reversal":{"zh":"同一团队决定停止互相指责，愿意商量怎样修复合作。这个例子里，宝剑五逆位表示开始愿意和解；接下来还要处理分歧和伤害，不表示冲突已经全部消失。","en":"The team stops blaming and agrees to discuss repair. Here reversal points toward reconciliation, while actual repair is still needed."},"visual":{"zh":"一人收拢剑，另两人离去，胜者与离开者同时出现在画面。记住“赢了什么，又失去了什么”。","en":"One figure gathers swords while two leave. Remember both what was won and what was lost."},"questions":{"Q1":{"id":"s05-Q1","prompt":{"zh":"宝剑五为什么提醒我们看“赢的代价”？","en":"Why examine the cost of winning?"},"options":[{"id":"s05-Q1-fc69a43dfc","text":{"zh":"争赢了，却可能让大家原本想一起做的事更难完成。","en":"A win may damage the shared goal."},"feedback":{"zh":"不能只看争论赢没赢，还要看这样赢了以后，同伴是否还愿意合作。","en":"Winning does not replace examining consequences."}},{"id":"s05-Q1-75bed4fd35","text":{"zh":"赢过争论就证明方法一定合适。","en":"Winning proves the method was appropriate."},"feedback":{"zh":"不能只看争论赢没赢，还要看这样赢了以后，同伴是否还愿意合作。","en":"Winning does not replace examining consequences."}}],"correct":"s05-Q1-fc69a43dfc","support":"R1"},"Q2":{"id":"s05-Q2","prompt":{"zh":"方案通过但同伴退出合作，先处理什么？","en":"A proposal passes but teammates withdraw. What needs attention?"},"options":[{"id":"s05-Q2-d041632ae1","text":{"zh":"只重复方案获胜，无需关心后续。","en":"Repeat that the proposal won and ignore what follows."},"feedback":{"zh":"方案虽然通过了，同伴却不愿继续合作。这里要处理的正是这种代价。","en":"The example includes both the win and the damage."}},{"id":"s05-Q2-5831cae960","text":{"zh":"先处理羞辱同伴造成的伤害，想想怎样恢复合作。","en":"Damage to cooperation caused by the tactics."},"feedback":{"zh":"方案虽然通过了，同伴却不愿继续合作。这里要处理的正是这种代价。","en":"The example includes both the win and the damage."}}],"correct":"s05-Q2-5831cae960","support":"R2"},"Q3":{"id":"s05-Q3","prompt":{"zh":"团队愿意停止指责，本例逆位怎么读？","en":"The team agrees to stop blaming. Interpret the reversal."},"options":[{"id":"s05-Q3-e7f2291923","text":{"zh":"愿意和解了，还需要实际行动来修复关系。","en":"Willingness to reconcile appears; repair remains."},"feedback":{"zh":"愿意和解只是第一步。彼此的意见和受到的伤害，仍需要好好处理。","en":"Willingness is a starting point, not completed repair."}},{"id":"s05-Q3-d8c5ff06e6","text":{"zh":"冲突已经自动彻底解决。","en":"All conflict has automatically vanished."},"feedback":{"zh":"愿意和解只是第一步。彼此的意见和受到的伤害，仍需要好好处理。","en":"Willingness is a starting point, not completed repair."}}],"correct":"s05-Q3-e7f2291923","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"不能只看争论赢没赢，还要看这样赢了以后，同伴是否还愿意合作。","en":"Winning does not replace examining consequences."},{"zh":"最后一句话被你说了，不表示你就是对的，也不表示合作没有受影响。","en":"Speaking order proves neither accuracy nor cooperation."}],"question":{"id":"s05-R1","prompt":{"zh":"争到最后一句话，却失去了伙伴，重点是什么？","en":"Having the last word costs a partner. What matters here?"},"options":[{"id":"s05-R1-c3ed859e61","text":{"zh":"最后发言就足以证明判断正确。","en":"Speaking last proves the judgment right."},"feedback":{"zh":"最后一句话被你说了，不表示你就是对的，也不表示合作没有受影响。","en":"Speaking order proves neither accuracy nor cooperation."}},{"id":"s05-R1-b8ba4287d2","text":{"zh":"看看为了争赢，失去了什么。","en":"Examine the cost of insisting on a win."},"feedback":{"zh":"最后一句话被你说了，不表示你就是对的，也不表示合作没有受影响。","en":"Speaking order proves neither accuracy nor cooperation."}}],"correct":"s05-R1-b8ba4287d2"}},"R2":{"teach":[{"zh":"方案虽然通过了，同伴却不愿继续合作。这里要处理的正是这种代价。","en":"The example includes both the win and the damage."},{"zh":"还想一起玩，就要处理嘲讽造成的伤害；赢过多少场，都不能让这些伤害消失。","en":"Shared goals require cooperation; wins do not erase costs."}],"question":{"id":"s05-R2","prompt":{"zh":"游戏队友因嘲讽而离队，按照宝剑五的提醒，应该怎样处理？","en":"Teammates leave after mockery. Apply the theme."},"options":[{"id":"s05-R2-6c2db6deb6","text":{"zh":"先处理嘲讽造成的伤害，再说好以后怎样一起玩。","en":"Address the harm and rebuild cooperation rules."},"feedback":{"zh":"还想一起玩，就要处理嘲讽造成的伤害；赢过多少场，都不能让这些伤害消失。","en":"Shared goals require cooperation; wins do not erase costs."}},{"id":"s05-R2-bd146e6f79","text":{"zh":"只用赢的次数说明嘲讽没问题。","en":"Use victory counts to justify mockery."},"feedback":{"zh":"还想一起玩，就要处理嘲讽造成的伤害；赢过多少场，都不能让这些伤害消失。","en":"Shared goals require cooperation; wins do not erase costs."}}],"correct":"s05-R2-6c2db6deb6"}},"R3":{"teach":[{"zh":"同一团队决定停止互相指责，愿意商量怎样修复合作。这个例子里，宝剑五逆位表示开始愿意和解；接下来还要处理分歧和伤害，不表示冲突已经全部消失。","en":"The team stops blaming and agrees to discuss repair. Here reversal points toward reconciliation, while actual repair is still needed."},{"zh":"说好和解后，还要谈清哪里受了伤、接下来怎样改变，关系才有机会改善。","en":"Willingness does not replace actual repair."}],"question":{"id":"s05-R3","prompt":{"zh":"同意和解后仍有不满，怎样继续？","en":"After agreeing to reconcile, resentment remains. What next?"},"options":[{"id":"s05-R3-98a421b545","text":{"zh":"谈清哪件事伤害了彼此，以及接下来怎样改变。","en":"Discuss specific harm and repair actions."},"feedback":{"zh":"说好和解后，还要谈清哪里受了伤、接下来怎样改变，关系才有机会改善。","en":"Willingness does not replace actual repair."}},{"id":"s05-R3-3119aa539e","text":{"zh":"用和解二字要求所有人立刻忘记。","en":"Demand instant forgetting because reconciliation was named."},"feedback":{"zh":"说好和解后，还要谈清哪里受了伤、接下来怎样改变，关系才有机会改善。","en":"Willingness does not replace actual repair."}}],"correct":"s05-R3-98a421b545"}}},"revisit":{"id":"s05-V1","prompt":{"zh":"讨论预算时为了面子压过别人，建议是什么？","en":"Someone dominates a budget discussion to save face. What fits?"},"options":[{"id":"s05-V1-537e562265","text":{"zh":"继续升级争执来保住面子。","en":"Escalate to protect pride."},"feedback":{"zh":"预算讨论是为了一起把钱安排好。只顾争面子，反而可能耽误这件正事。","en":"This theme checks whether winning undermines the real goal."}},{"id":"s05-V1-cadc6f7258","text":{"zh":"先讨论预算要解决什么问题，别只顾争一口气。","en":"Return from competition to the real budget goal."},"feedback":{"zh":"预算讨论是为了一起把钱安排好。只顾争面子，反而可能耽误这件正事。","en":"This theme checks whether winning undermines the real goal."}}],"correct":"s05-V1-cadc6f7258"},"summary":{"zh":"宝剑五关注冲突中的胜负与代价：赢下一场争执，也可能让同伴不再愿意合作。它提醒检查赢的方式，而不是给某人贴坏人标签。","en":"The Five of Swords concerns winning and its cost: an argument may be won while cooperation is damaged. Examine the manner of winning rather than labeling someone bad."},"cards":["s05"]},{"id":"s06","kind":"card","level":"I","title":{"zh":"宝剑六","en":"Six of Swords"},"teachings":[{"zh":"宝剑六描述离开较困难的处境，慢慢走向平稳；过去的经历和问题可能仍会影响自己。开始移动不等于所有问题立刻消失。","en":"The Six of Swords describes carrying past experience away from difficulty toward calmer conditions. Movement does not mean every problem disappears immediately."},{"zh":"船上有人与六把剑，船驶向对岸。船在移动，剑仍随行，帮助记住“开始往前走，过去的问题还可能跟着自己”。","en":"People and six swords travel in a boat toward another shore. The boat moves while the swords remain: transition carries experience with it."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关；数字六可以帮助记住调整后慢慢缓和的状态。这张牌可以记成：慢慢过渡、逐渐缓和、离开困境。它不一定指实际旅行。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air relates to thinking and methods; six may aid remembering adjustment and relief without requiring literal travel. Helpers: transition, relief, leaving difficulty."}],"application":{"zh":"旧复习方法让小孟疲惫，他开始转向更清楚的分段计划。建议位支持逐步换方法，并承认尚需适应，而非要求立刻毫无压力。","en":"Meng leaves an exhausting study method for a clearer segmented plan. Advice supports gradual transition and adjustment, not instant freedom from pressure."},"reversal":{"zh":"小孟换了计划，却仍每天照旧熬夜，旧问题并没有解决。这个例子里，宝剑六逆位表示改变没有顺利进行，还要调整一直没改的作息；不表示他永远改不了。","en":"Meng changes plans but keeps the same late-night habit. The reversal describes a blocked transition requiring attention to what followed along."},"visual":{"zh":"船上有人与六把剑，船驶向对岸。船在移动，剑仍随行，帮助记住“开始往前走，过去的问题还可能跟着自己”。","en":"People and six swords travel in a boat toward another shore. The boat moves while the swords remain: transition carries experience with it."},"questions":{"Q1":{"id":"s06-Q1","prompt":{"zh":"这张牌的过渡是否要求问题立即消失？","en":"Must all problems vanish in this transition?"},"options":[{"id":"s06-Q1-fb2ba77606","text":{"zh":"要求，否则就不能算开始改变。","en":"Yes; otherwise change has not begun."},"feedback":{"zh":"开始改变时，旧问题不一定马上消失；迈出第一步仍然有意义。","en":"Moving and fully resolving need not coincide."}},{"id":"s06-Q1-9862a62b70","text":{"zh":"不要求，开始改变时，旧经历仍可能影响自己。","en":"No; past experience can travel through change."},"feedback":{"zh":"开始改变时，旧问题不一定马上消失；迈出第一步仍然有意义。","en":"Moving and fully resolving need not coincide."}}],"correct":"s06-Q1-9862a62b70","support":"R1"},"Q2":{"id":"s06-Q2","prompt":{"zh":"换复习方法后仍需适应，怎样回应？","en":"The new study method requires adjustment. What fits?"},"options":[{"id":"s06-Q2-7ca84e067d","text":{"zh":"按新计划一步步做，同时处理仍然存在的困难。","en":"Implement it gradually and address old difficulties."},"feedback":{"zh":"换了复习方法，还需要一段适应时间；有压力不表示新方法一定无效。","en":"The example concerns transition, not instant perfection."}},{"id":"s06-Q2-51accd422d","text":{"zh":"只要还有压力就立即否定新方法。","en":"Reject it immediately because pressure remains."},"feedback":{"zh":"换了复习方法，还需要一段适应时间；有压力不表示新方法一定无效。","en":"The example concerns transition, not instant perfection."}}],"correct":"s06-Q2-7ca84e067d","support":"R2"},"Q3":{"id":"s06-Q3","prompt":{"zh":"计划换了，熬夜习惯没变，本例逆位提示什么？","en":"The plan changes but late nights remain. What fits?"},"options":[{"id":"s06-Q3-66b69ece9f","text":{"zh":"一次换计划就应消除全部习惯。","en":"A new plan should erase every habit instantly."},"feedback":{"zh":"计划改了，熬夜的做法却没改；要真正减轻疲惫，还得调整作息。","en":"Behavior must change; a new label is insufficient."}},{"id":"s06-Q3-cc41a5c716","text":{"zh":"旧习惯还在影响自己，需要继续调整。","en":"Old problems follow; transition needs adjustment."},"feedback":{"zh":"计划改了，熬夜的做法却没改；要真正减轻疲惫，还得调整作息。","en":"Behavior must change; a new label is insufficient."}}],"correct":"s06-Q3-cc41a5c716","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"开始改变时，旧问题不一定马上消失；迈出第一步仍然有意义。","en":"Moving and fully resolving need not coincide."},{"zh":"船在向前走，剑还在船上。可以用这幅画记住：改变开始了，过去的问题未必马上消失。","en":"The picture combines movement and carrying, not total erasure."}],"question":{"id":"s06-R1","prompt":{"zh":"船在前进但剑还在，适合记住什么？","en":"Boat moving, swords remaining: remember what?"},"options":[{"id":"s06-R1-1e155cbdfd","text":{"zh":"开始离开困境后，过去的问题可能还在。","en":"Leaving difficulty can carry experience along."},"feedback":{"zh":"船在向前走，剑还在船上。可以用这幅画记住：改变开始了，过去的问题未必马上消失。","en":"The picture combines movement and carrying, not total erasure."}},{"id":"s06-R1-724c7c286e","text":{"zh":"任何新阶段都与过去完全无关。","en":"A new stage has no connection to the past."},"feedback":{"zh":"船在向前走，剑还在船上。可以用这幅画记住：改变开始了，过去的问题未必马上消失。","en":"The picture combines movement and carrying, not total erasure."}}],"correct":"s06-R1-1e155cbdfd"}},"R2":{"teach":[{"zh":"换了复习方法，还需要一段适应时间；有压力不表示新方法一定无效。","en":"The example concerns transition, not instant perfection."},{"zh":"换流程后，旧任务仍要有人接手处理，不能假定它们已经消失了。","en":"Transition requires handling what remains."}],"question":{"id":"s06-R2","prompt":{"zh":"团队开始用新流程，仍有旧任务，怎样安排？","en":"A team adopts a new process with old tasks remaining. What fits?"},"options":[{"id":"s06-R2-b77d1ccf63","text":{"zh":"假定换了流程，旧任务就不存在。","en":"Assume the new process makes old tasks disappear."},"feedback":{"zh":"换流程后，旧任务仍要有人接手处理，不能假定它们已经消失了。","en":"Transition requires handling what remains."}},{"id":"s06-R2-4c693c2781","text":{"zh":"说清旧任务由谁接手，再一项项处理完。","en":"Plan handover so old tasks gradually clear."},"feedback":{"zh":"换流程后，旧任务仍要有人接手处理，不能假定它们已经消失了。","en":"Transition requires handling what remains."}}],"correct":"s06-R2-4c693c2781"}},"R3":{"teach":[{"zh":"小孟换了计划，却仍每天照旧熬夜，旧问题并没有解决。这个例子里，宝剑六逆位表示改变没有顺利进行，还要调整一直没改的作息；不表示他永远改不了。","en":"Meng changes plans but keeps the same late-night habit. The reversal describes a blocked transition requiring attention to what followed along."},{"zh":"如果仍照旧熬夜，再给计划换个名字也没有用；作息本身需要改变。","en":"The obstacle is behavioral; renaming does not complete transition."}],"question":{"id":"s06-R3","prompt":{"zh":"新计划仍被旧作息拖住，下一步是什么？","en":"Old routines block the new plan. What next?"},"options":[{"id":"s06-R3-0612a6eda5","text":{"zh":"只再给计划改一个名字。","en":"Merely rename the plan again."},"feedback":{"zh":"如果仍照旧熬夜，再给计划换个名字也没有用；作息本身需要改变。","en":"The obstacle is behavioral; renaming does not complete transition."}},{"id":"s06-R3-dde2b5d7ec","text":{"zh":"连同旧作息一起调整。","en":"Adjust the old routine as well."},"feedback":{"zh":"如果仍照旧熬夜，再给计划换个名字也没有用；作息本身需要改变。","en":"The obstacle is behavioral; renaming does not complete transition."}}],"correct":"s06-R3-dde2b5d7ec"}}},"revisit":{"id":"s06-V1","prompt":{"zh":"搬到安静学习处后仍难集中，如何理解？","en":"A quieter study space does not immediately restore focus. Interpret."},"options":[{"id":"s06-V1-c1f2694bea","text":{"zh":"环境改善只是过渡的一步，仍需适应。","en":"Better conditions are one step; adjustment remains."},"feedback":{"zh":"换个安静地方有帮助，但专注状态不一定立刻恢复，还可以给自己一点适应时间。","en":"This theme does not require instantaneous improvement."}},{"id":"s06-V1-9a8f29079e","text":{"zh":"没有立刻轻松就证明任何改变无效。","en":"No immediate relief proves all change useless."},"feedback":{"zh":"换个安静地方有帮助，但专注状态不一定立刻恢复，还可以给自己一点适应时间。","en":"This theme does not require instantaneous improvement."}}],"correct":"s06-V1-c1f2694bea"},"summary":{"zh":"宝剑六描述离开较困难的处境，慢慢走向平稳；过去的经历和问题可能仍会影响自己。开始移动不等于所有问题立刻消失。","en":"The Six of Swords describes carrying past experience away from difficulty toward calmer conditions. Movement does not mean every problem disappears immediately."},"cards":["s06"]},{"id":"s07","kind":"card","level":"I","title":{"zh":"宝剑七","en":"Seven of Swords"},"teachings":[{"zh":"宝剑七涉及不公开行动、绕开正面冲突，或独自处理事情。这样做可能有策略上的考虑，也可能是在回避问题；要看哪些事可以自己处理、哪些事应告诉别人，不能直接指控欺骗。","en":"The Seven of Swords concerns indirect, private, or solitary methods. These may be strategic or evasive; examine what should be disclosed rather than accuse deception."},{"zh":"人物带走五把剑，回头看，另两把剑留在身后。动作帮助记住悄悄安排、没有公开说明的做法；我们不知道现实中谁做了什么。","en":"A figure carries five swords while looking back, leaving two. The action supports remembering covert arrangements, not identifying a real culprit."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关。不能单凭数字七认定有人隐瞒；还要结合画面和具体情况。这张牌可以记成：想办法绕过去、隐瞒、回避。是合理安排还是隐瞒了该说的事，要看背景。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air relates to strategy; seven does not prove concealment. Helpers: strategy, indirect action, concealment, avoidance; context distinguishes them."}],"application":{"zh":"小林独自改合作文件，却没告诉需要配合的同伴。建议位应区分个人草稿与影响他人的决定，把会影响同伴的信息告诉他们，而非把一切保密都当聪明策略。","en":"Lin privately changes a shared file without telling affected teammates. Advice distinguishes private drafts from decisions others need to know and calls for necessary disclosure."},"reversal":{"zh":"小林主动说明先前修改了什么，也愿意和同伴一起核对。这个例子里，宝剑七逆位表示开始坦白、重新面对问题；不能据此认定他之前一定有恶意。","en":"Lin explains the edits and offers a joint review. Here reversal suggests disclosure and facing the issue, without proving past malice."},"visual":{"zh":"人物带走五把剑，回头看，另两把剑留在身后。动作帮助记住悄悄安排、没有公开说明的做法；我们不知道现实中谁做了什么。","en":"A figure carries five swords while looking back, leaving two. The action supports remembering covert arrangements, not identifying a real culprit."},"questions":{"Q1":{"id":"s07-Q1","prompt":{"zh":"宝剑七中的“不公开地行动”，应该怎样理解？","en":"How should private action be interpreted?"},"options":[{"id":"s07-Q1-289fe3b0fc","text":{"zh":"看具体情况，分清是在想办法，还是在躲问题。","en":"Use context to distinguish strategy from avoidance."},"feedback":{"zh":"牌图可以帮助理解隐瞒或策略，却不能证明现实里某个人偷了东西。","en":"Imagery supplies a theme, not evidence against someone."}},{"id":"s07-Q1-172a02642b","text":{"zh":"仅凭牌面认定现实中有人偷窃。","en":"Infer a real theft from the card alone."},"feedback":{"zh":"牌图可以帮助理解隐瞒或策略，却不能证明现实里某个人偷了东西。","en":"Imagery supplies a theme, not evidence against someone."}}],"correct":"s07-Q1-289fe3b0fc","support":"R1"},"Q2":{"id":"s07-Q2","prompt":{"zh":"修改影响同伴的文件，建议是什么？","en":"Changes affect teammates. What is the advice?"},"options":[{"id":"s07-Q2-c8030feebf","text":{"zh":"把所有隐瞒都解释成高明策略。","en":"Treat every concealment as clever strategy."},"feedback":{"zh":"文件改动会影响同伴接下来的工作，就应告诉他们；不能把这种隐瞒一律说成聪明。","en":"Coordination requires information; appropriateness depends on effects."}},{"id":"s07-Q2-741a1acfc1","text":{"zh":"把会影响合作的改动告诉同伴。","en":"Share information needed for coordination."},"feedback":{"zh":"文件改动会影响同伴接下来的工作，就应告诉他们；不能把这种隐瞒一律说成聪明。","en":"Coordination requires information; appropriateness depends on effects."}}],"correct":"s07-Q2-741a1acfc1","support":"R2"},"Q3":{"id":"s07-Q3","prompt":{"zh":"主动说明修改并核对，本例逆位表达什么？","en":"Explaining edits and reviewing them together: what fits?"},"options":[{"id":"s07-Q3-1e5fd47da3","text":{"zh":"开始坦白并处理原问题。","en":"Disclosure and renewed engagement."},"feedback":{"zh":"主动说明改动，是开始坦白的表现，但不能因此推断他之前一定有恶意。","en":"Disclosure supports that direction without proving motives."}},{"id":"s07-Q3-96cf5c470a","text":{"zh":"已经证明以前一定恶意欺骗。","en":"Proof of deliberate past deception."},"feedback":{"zh":"主动说明改动，是开始坦白的表现，但不能因此推断他之前一定有恶意。","en":"Disclosure supports that direction without proving motives."}}],"correct":"s07-Q3-1e5fd47da3","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"牌图可以帮助理解隐瞒或策略，却不能证明现实里某个人偷了东西。","en":"Imagery supplies a theme, not evidence against someone."},{"zh":"自己先写一份草稿，和瞒着伙伴改共同决定，不是一回事；瞒着伙伴改共同决定会影响别人，应该沟通。","en":"Strategy and avoidance depend on responsibilities and consequences."}],"question":{"id":"s07-R1","prompt":{"zh":"独自做草稿和隐瞒共同决定为何不同？","en":"Why distinguish a private draft from a hidden shared decision?"},"options":[{"id":"s07-R1-3c441b52ea","text":{"zh":"只要独自行动就一定是背叛。","en":"Any solitary action is betrayal."},"feedback":{"zh":"自己先写一份草稿，和瞒着伙伴改共同决定，不是一回事；瞒着伙伴改共同决定会影响别人，应该沟通。","en":"Strategy and avoidance depend on responsibilities and consequences."}},{"id":"s07-R1-7d469aafd9","text":{"zh":"共同决定会影响伙伴怎么做，所以改动后需要告诉他们。","en":"A hidden shared decision affects others and needs communication."},"feedback":{"zh":"自己先写一份草稿，和瞒着伙伴改共同决定，不是一回事；瞒着伙伴改共同决定会影响别人，应该沟通。","en":"Strategy and avoidance depend on responsibilities and consequences."}}],"correct":"s07-R1-7d469aafd9"}},"R2":{"teach":[{"zh":"文件改动会影响同伴接下来的工作，就应告诉他们；不能把这种隐瞒一律说成聪明。","en":"Coordination requires information; appropriateness depends on effects."},{"zh":"集合时间一改，参加的人都会受影响，所以要通知他们并确认收到。","en":"Shared arrangements require informing those involved."}],"question":{"id":"s07-R2","prompt":{"zh":"组织活动时悄悄改集合时间，应怎么做？","en":"An organizer quietly changes the meeting time. What fits?"},"options":[{"id":"s07-R2-a58421c6d9","text":{"zh":"通知受影响的人并确认收到。","en":"Notify affected people and confirm receipt."},"feedback":{"zh":"集合时间一改，参加的人都会受影响，所以要通知他们并确认收到。","en":"Shared arrangements require informing those involved."}},{"id":"s07-R2-29a0256469","text":{"zh":"让大家自己猜新时间，以保持灵活。","en":"Let everyone guess to preserve flexibility."},"feedback":{"zh":"集合时间一改，参加的人都会受影响，所以要通知他们并确认收到。","en":"Shared arrangements require informing those involved."}}],"correct":"s07-R2-a58421c6d9"}},"R3":{"teach":[{"zh":"小林主动说明先前修改了什么，也愿意和同伴一起核对。这个例子里，宝剑七逆位表示开始坦白、重新面对问题；不能据此认定他之前一定有恶意。","en":"Lin explains the edits and offers a joint review. Here reversal suggests disclosure and facing the issue, without proving past malice."},{"zh":"解释过改动之后，还应让伙伴检查、提问，并说好以后怎样通知，才算认真处理这件事。","en":"Facing an issue includes review, not merely declaring disclosure."}],"question":{"id":"s07-R3","prompt":{"zh":"补充说明先前改动后，还要做什么？","en":"After explaining earlier edits, what remains?"},"options":[{"id":"s07-R3-76e5dfb878","text":{"zh":"请受影响的伙伴核对改动，并说好以后怎样通知。","en":"Let affected partners review and agree on future updates."},"feedback":{"zh":"解释过改动之后，还应让伙伴检查、提问，并说好以后怎样通知，才算认真处理这件事。","en":"Facing an issue includes review, not merely declaring disclosure."}},{"id":"s07-R3-fba59faf16","text":{"zh":"因为已经解释，就不允许任何人询问。","en":"Ban questions because an explanation was given."},"feedback":{"zh":"解释过改动之后，还应让伙伴检查、提问，并说好以后怎样通知，才算认真处理这件事。","en":"Facing an issue includes review, not merely declaring disclosure."}}],"correct":"s07-R3-76e5dfb878"}}},"revisit":{"id":"s07-V1","prompt":{"zh":"为惊喜准备私人草稿，是否能直接判欺骗？","en":"Does a private draft for a surprise establish deception?"},"options":[{"id":"s07-V1-9184b16dd0","text":{"zh":"能，任何保密都说明恶意。","en":"Yes; privacy always proves malice."},"feedback":{"zh":"为惊喜暂时保密，不一定是在伤害别人；要看具体安排和双方原有的约定。","en":"The lesson separates strategy from avoidance, not privacy from morality."}},{"id":"s07-V1-fb5c62d2b1","text":{"zh":"不能，要看实际背景与有没有违反双方的约定。","en":"No; consider context and obligations."},"feedback":{"zh":"为惊喜暂时保密，不一定是在伤害别人；要看具体安排和双方原有的约定。","en":"The lesson separates strategy from avoidance, not privacy from morality."}}],"correct":"s07-V1-fb5c62d2b1"},"summary":{"zh":"宝剑七涉及不公开行动、绕开正面冲突，或独自处理事情。这样做可能有策略上的考虑，也可能是在回避问题；要看哪些事可以自己处理、哪些事应告诉别人，不能直接指控欺骗。","en":"The Seven of Swords concerns indirect, private, or solitary methods. These may be strategic or evasive; examine what should be disclosed rather than accuse deception."},"cards":["s07"]},{"id":"s08","kind":"card","level":"I","title":{"zh":"宝剑八","en":"Eight of Swords"},"teachings":[{"zh":"宝剑八表现的是被困住、觉得没有办法的状态。需要分清实际遇到了什么限制，以及哪些事只是暂时没有想到办法；寻找可做的一小步，不等于说困难全是想出来的。","en":"The Eight of Swords depicts restriction and difficulty seeing options. Take both real constraints and helplessness seriously; finding one possible step does not make all difficulty imaginary."},{"zh":"蒙眼、受缚的人站在剑之间，剑阵留有间隙。绳索说明人物确实受了限制，剑之间又有空隙；两处一起看，帮助我们记住：承认困难，也继续寻找还有没有别的办法。","en":"A blindfolded, bound figure stands among swords with gaps. Binding and space together suggest constraints alongside options not yet seen."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关。不能只看到数字八，就认定一个人受困；要一起看绳索、蒙眼布和剑之间的空隙。可以记成：受到限制、觉得无能为力、寻找别的办法。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air supports examining judgments and information; eight is not a universal formula for entrapment. Helpers: restriction, helplessness, unseen options."}],"application":{"zh":"小夏觉得课程太难，也不知道如何求助。建议位先列出具体卡点，找一个能询问的人；不要求一句“想开点”解决全部困难。","en":"Xia finds a course overwhelming and does not know how to seek help. Advice is to identify a specific block and one person to ask, rather than dismiss difficulty with think positively."},"reversal":{"zh":"小夏找到助教，发现可以分步骤补上基础。这个例子里，宝剑八逆位表示开始找到办法，不再觉得完全走不出去；但具体课程仍要一步步学。","en":"Xia finds a tutor and sees a stepwise way to rebuild basics. The reversal suggests emerging options, while actual work remains."},"visual":{"zh":"蒙眼、受缚的人站在剑之间，剑阵留有间隙。绳索说明人物确实受了限制，剑之间又有空隙；两处一起看，帮助我们记住：承认困难，也继续寻找还有没有别的办法。","en":"A blindfolded, bound figure stands among swords with gaps. Binding and space together suggest constraints alongside options not yet seen."},"questions":{"Q1":{"id":"s08-Q1","prompt":{"zh":"感到自己没有办法时，宝剑八提醒我们先做什么？","en":"When restricted, what comes first here?"},"options":[{"id":"s08-Q1-3e6837a294","text":{"zh":"认定全部困难都是自己想多了。","en":"Declare every difficulty imaginary."},"feedback":{"zh":"寻找还能做什么，不等于否认困难。先弄清卡在哪里，才能找到一个可行步骤。","en":"Finding options does not require denying real constraints."}},{"id":"s08-Q1-a1d91706f9","text":{"zh":"弄清卡在哪一步，再找目前能做的事。","en":"Identify real blocks and remaining possible actions."},"feedback":{"zh":"寻找还能做什么，不等于否认困难。先弄清卡在哪里，才能找到一个可行步骤。","en":"Finding options does not require denying real constraints."}}],"correct":"s08-Q1-a1d91706f9","support":"R1"},"Q2":{"id":"s08-Q2","prompt":{"zh":"小夏不知道怎样求助，按照刚才的例子，哪项做法更合适？","en":"Xia does not know how to seek help. Which follows?"},"options":[{"id":"s08-Q2-93b8289813","text":{"zh":"选一个具体难点向助教询问。","en":"Ask a tutor about one specific difficulty."},"feedback":{"zh":"先问清一个具体难点，就开始有了办法；不必要求自己一下解决所有问题。","en":"A feasible small step better fits finding options."}},{"id":"s08-Q2-2b9091cdf0","text":{"zh":"要求自己立刻独立解决所有困难。","en":"Demand an immediate solo solution to everything."},"feedback":{"zh":"先问清一个具体难点，就开始有了办法；不必要求自己一下解决所有问题。","en":"A feasible small step better fits finding options."}}],"correct":"s08-Q2-93b8289813","support":"R2"},"Q3":{"id":"s08-Q3","prompt":{"zh":"找到分步补基础的方法，逆位如何表达？","en":"A stepwise support plan appears. Interpret."},"options":[{"id":"s08-Q3-a7839acbe6","text":{"zh":"所有课程任务已经自动完成。","en":"Every task has automatically been completed."},"feedback":{"zh":"找到补基础的方法，只是开始知道怎样学；具体课程仍要一步步完成。","en":"Seeing a way forward starts change, not task completion."}},{"id":"s08-Q3-8abc928f63","text":{"zh":"开始发现自己还有别的办法。","en":"Options begin to become visible."},"feedback":{"zh":"找到补基础的方法，只是开始知道怎样学；具体课程仍要一步步完成。","en":"Seeing a way forward starts change, not task completion."}}],"correct":"s08-Q3-8abc928f63","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"寻找还能做什么，不等于否认困难。先弄清卡在哪里，才能找到一个可行步骤。","en":"Finding options does not require denying real constraints."},{"zh":"人物仍被绑着，所以有空隙不等于没有限制。两处细节要一起看。","en":"The binding remains; the image does not deny difficulty."}],"question":{"id":"s08-R1","prompt":{"zh":"剑阵有空隙，是否意味着约束不存在？","en":"Do gaps mean there are no constraints?"},"options":[{"id":"s08-R1-2d0b27a5da","text":{"zh":"不是，人物仍被绑着，但可以继续寻找有没有别的办法。","en":"No; consider both constraints and openings."},"feedback":{"zh":"人物仍被绑着，所以有空隙不等于没有限制。两处细节要一起看。","en":"The binding remains; the image does not deny difficulty."}},{"id":"s08-R1-af1755cbd9","text":{"zh":"是，有空隙就表示人物根本没有受限制。","en":"Yes; helplessness must be invented."},"feedback":{"zh":"人物仍被绑着，所以有空隙不等于没有限制。两处细节要一起看。","en":"The binding remains; the image does not deny difficulty."}}],"correct":"s08-R1-2d0b27a5da"}},"R2":{"teach":[{"zh":"先问清一个具体难点，就开始有了办法；不必要求自己一下解决所有问题。","en":"A feasible small step better fits finding options."},{"zh":"说清卡在哪一步，才容易找到可以询问的人；只说“全都没办法”，就难以开始。","en":"A concrete issue is more workable than global helplessness."}],"question":{"id":"s08-R2","prompt":{"zh":"流程复杂又不知找谁，怎样开始？","en":"A process is confusing and contacts unclear. Start how?"},"options":[{"id":"s08-R2-08cfb7347a","text":{"zh":"因为暂时不会，就确定永远没有办法。","en":"Conclude no solution will ever exist."},"feedback":{"zh":"说清卡在哪一步，才容易找到可以询问的人；只说“全都没办法”，就难以开始。","en":"A concrete issue is more workable than global helplessness."}},{"id":"s08-R2-5b022824f5","text":{"zh":"先确定卡在哪一步，查询对应负责人。","en":"Identify the blocked step and its contact."},"feedback":{"zh":"说清卡在哪一步，才容易找到可以询问的人；只说“全都没办法”，就难以开始。","en":"A concrete issue is more workable than global helplessness."}}],"correct":"s08-R2-5b022824f5"}},"R3":{"teach":[{"zh":"小夏找到助教，发现可以分步骤补上基础。这个例子里，宝剑八逆位表示开始找到办法，不再觉得完全走不出去；但具体课程仍要一步步学。","en":"Xia finds a tutor and sees a stepwise way to rebuild basics. The reversal suggests emerging options, while actual work remains."},{"zh":"知道可以找谁帮忙之后，还要实际开口询问，事情才会往前走。","en":"Recovered options still need action."}],"question":{"id":"s08-R3","prompt":{"zh":"知道可以找谁帮忙之后，下一步做什么？","en":"A help option becomes visible. How follow through?"},"options":[{"id":"s08-R3-8a2d3a962e","text":{"zh":"认为找到一个办法，就表示所有限制都消失了。","en":"Treat seeing an option as every restriction disappearing."},"feedback":{"zh":"知道可以找谁帮忙之后，还要实际开口询问，事情才会往前走。","en":"Recovered options still need action."}},{"id":"s08-R3-54dc8a94ac","text":{"zh":"先尝试一个具体求助步骤。","en":"Try one concrete step toward help."},"feedback":{"zh":"知道可以找谁帮忙之后，还要实际开口询问，事情才会往前走。","en":"Recovered options still need action."}}],"correct":"s08-R3-54dc8a94ac"}}},"revisit":{"id":"s08-V1","prompt":{"zh":"学新软件时说“我什么都不会”，先怎样？","en":"Learning software, someone says I can do nothing. First?"},"options":[{"id":"s08-V1-968713fcc5","text":{"zh":"找出一个已经会的操作，再指出一个需要求助的操作。","en":"Name one known action and one needing help."},"feedback":{"zh":"先分清哪些会、哪些不会，才知道要学什么；不用否认自己遇到的困难。","en":"Defining the difficulty fits better than denying it."}},{"id":"s08-V1-dd9b04da4a","text":{"zh":"直接宣布不需要任何学习支持。","en":"Declare that no support is needed."},"feedback":{"zh":"先分清哪些会、哪些不会，才知道要学什么；不用否认自己遇到的困难。","en":"Defining the difficulty fits better than denying it."}}],"correct":"s08-V1-968713fcc5"},"summary":{"zh":"宝剑八表现的是被困住、觉得没有办法的状态。需要分清实际遇到了什么限制，以及哪些事只是暂时没有想到办法；寻找可做的一小步，不等于说困难全是想出来的。","en":"The Eight of Swords depicts restriction and difficulty seeing options. Take both real constraints and helplessness seriously; finding one possible step does not make all difficulty imaginary."},"cards":["s08"]},{"id":"s09","kind":"card","level":"I","title":{"zh":"宝剑九","en":"Nine of Swords"},"teachings":[{"zh":"宝剑九关注反复担忧占据思绪的状态。忧虑带来的压力真实存在，但脑中想象的最坏结果，不会因为担心就成为事实。","en":"The Nine of Swords concerns recurring worries occupying the mind. The distress is real; the worst imagined story is not thereby a fact."},{"zh":"人物在床上坐起掩面，九把剑排列在背景。姿态与夜间环境帮助记住难以停下的忧虑，不用于医学诊断。","en":"A figure sits up in bed covering their face, with swords behind. The nighttime setting supports remembering persistent worry, not medical diagnosis."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关。这张牌先记画面中的担忧状态，不要把数字九当成出事的天数。可以记成：担忧、反复想同一件事、精神压力。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air concerns thought; nine is a structural aid, not a nine-day prediction. Helpers: worry, rumination, mental strain."}],"application":{"zh":"等面试回复时，小宁不断想“没有马上回复就是失败”。建议位先区分尚未收到消息这一事实和失败的猜测，再安排可做的准备。","en":"Waiting for an interview reply, Ning equates no immediate answer with failure. Advice separates the fact of no reply from the guess of failure, then returns to feasible preparation."},"reversal":{"zh":"小宁向可信的人说出担忧，开始分清哪些是事实、哪些是猜测。这个例子里，宝剑九逆位表示压力有机会慢慢减轻，不表示以后绝不会再焦虑。","en":"Ning shares worries with someone trusted and distinguishes fact from guess. The reversal can suggest easing pressure, not a guarantee of never worrying again."},"visual":{"zh":"人物在床上坐起掩面，九把剑排列在背景。姿态与夜间环境帮助记住难以停下的忧虑，不用于医学诊断。","en":"A figure sits up in bed covering their face, with swords behind. The nighttime setting supports remembering persistent worry, not medical diagnosis."},"questions":{"Q1":{"id":"s09-Q1","prompt":{"zh":"强烈担心是否证明最坏结果会发生？","en":"Does intense worry prove the worst outcome?"},"options":[{"id":"s09-Q1-7b51e93dc3","text":{"zh":"不能，担心不等于事情一定会那样发生。","en":"No; distress and external evidence differ."},"feedback":{"zh":"担心确实会让人难受，但不能据此判断最坏的事一定会发生。","en":"The lesson acknowledges worry without treating it as prophecy."}},{"id":"s09-Q1-dcc07edddb","text":{"zh":"证明，越担心就越说明结果确定。","en":"Yes; stronger worry makes the outcome certain."},"feedback":{"zh":"担心确实会让人难受，但不能据此判断最坏的事一定会发生。","en":"The lesson acknowledges worry without treating it as prophecy."}}],"correct":"s09-Q1-7b51e93dc3","support":"R1"},"Q2":{"id":"s09-Q2","prompt":{"zh":"没有立即收到面试回复，小宁应该怎样理解？","en":"No immediate interview reply: which fits?"},"options":[{"id":"s09-Q2-290741a985","text":{"zh":"没立即回复已经证明完全失败。","en":"No instant reply proves total failure."},"feedback":{"zh":"目前只知道还没收到回复；“面试失败”是小宁的猜测，还没有得到证实。","en":"Known fact and inference must be separated."}},{"id":"s09-Q2-7d42cb8262","text":{"zh":"目前没回复，失败仍只是猜测。","en":"No reply is known; failure remains a guess."},"feedback":{"zh":"目前只知道还没收到回复；“面试失败”是小宁的猜测，还没有得到证实。","en":"Known fact and inference must be separated."}}],"correct":"s09-Q2-7d42cb8262","support":"R2"},"Q3":{"id":"s09-Q3","prompt":{"zh":"说出担忧并得到支持，本例逆位指什么？","en":"Sharing worry and receiving support: reversal?"},"options":[{"id":"s09-Q3-0331d3580a","text":{"zh":"压力可能逐渐缓和。","en":"Pressure may gradually ease."},"feedback":{"zh":"说出担忧、得到支持，可能让小宁慢慢轻松一些，但不表示以后绝不会再紧张。","en":"The context supports gradual relief, not a permanent guarantee."}},{"id":"s09-Q3-bef2f4cf2c","text":{"zh":"此后永远不可能再担心。","en":"Worry can never recur."},"feedback":{"zh":"说出担忧、得到支持，可能让小宁慢慢轻松一些，但不表示以后绝不会再紧张。","en":"The context supports gradual relief, not a permanent guarantee."}}],"correct":"s09-Q3-0331d3580a","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"担心确实会让人难受，但不能据此判断最坏的事一定会发生。","en":"The lesson acknowledges worry without treating it as prophecy."},{"zh":"害怕出错，说明你正在担心；要知道有没有真的出错，还得检查实际情况。","en":"An emotion is real without verifying an external event."}],"question":{"id":"s09-R1","prompt":{"zh":"“我很怕出错”能够直接证明什么？","en":"What does I fear an error directly establish?"},"options":[{"id":"s09-R1-7c87ac64a7","text":{"zh":"错误一定已发生而且无法修复。","en":"An irreversible error must already exist."},"feedback":{"zh":"害怕出错，说明你正在担心；要知道有没有真的出错，还得检查实际情况。","en":"An emotion is real without verifying an external event."}},{"id":"s09-R1-986201aeb2","text":{"zh":"现在确实很担心，需要先弄清自己在担心什么。","en":"Worry is present and deserves attention."},"feedback":{"zh":"害怕出错，说明你正在担心；要知道有没有真的出错，还得检查实际情况。","en":"An emotion is real without verifying an external event."}}],"correct":"s09-R1-986201aeb2"}},"R2":{"teach":[{"zh":"目前只知道还没收到回复；“面试失败”是小宁的猜测，还没有得到证实。","en":"Known fact and inference must be separated."},{"zh":"“还没回消息”是已知情况，“关系结束了”是猜测；反复想这个猜测，也不会让它成为证据。","en":"Separating fact prevents rumination from masquerading as evidence."}],"question":{"id":"s09-R2","prompt":{"zh":"朋友暂未回消息就猜关系结束，先怎样？","en":"No reply leads to imagining a friendship ending. First?"},"options":[{"id":"s09-R2-75bbec9a09","text":{"zh":"把未回复与关系结束分开判断。","en":"Separate no reply from an ended friendship."},"feedback":{"zh":"“还没回消息”是已知情况，“关系结束了”是猜测；反复想这个猜测，也不会让它成为证据。","en":"Separating fact prevents rumination from masquerading as evidence."}},{"id":"s09-R2-b910e0807a","text":{"zh":"不断重读猜测直到把它当事实。","en":"Repeat the guess until it feels factual."},"feedback":{"zh":"“还没回消息”是已知情况，“关系结束了”是猜测；反复想这个猜测，也不会让它成为证据。","en":"Separating fact prevents rumination from masquerading as evidence."}}],"correct":"s09-R2-75bbec9a09"}},"R3":{"teach":[{"zh":"小宁向可信的人说出担忧，开始分清哪些是事实、哪些是猜测。这个例子里，宝剑九逆位表示压力有机会慢慢减轻，不表示以后绝不会再焦虑。","en":"Ning shares worries with someone trusted and distinguishes fact from guess. The reversal can suggest easing pressure, not a guarantee of never worrying again."},{"zh":"得到支持后，担忧也可能慢慢才减轻；偶尔仍紧张，不等于之前的帮助全无用处。","en":"Relief need not eliminate worry permanently in one step."}],"question":{"id":"s09-R3","prompt":{"zh":"说出担忧后仍有紧张，怎样理解？","en":"Tension remains after sharing worry. Interpret."},"options":[{"id":"s09-R3-e4f0252f11","text":{"zh":"缓和可以逐步发生，继续区分事实和猜测。","en":"Relief can be gradual; keep separating fact from guess."},"feedback":{"zh":"得到支持后，担忧也可能慢慢才减轻；偶尔仍紧张，不等于之前的帮助全无用处。","en":"Relief need not eliminate worry permanently in one step."}},{"id":"s09-R3-a4a28d86d6","text":{"zh":"只要再紧张就证明支持完全无效。","en":"Any further tension proves support useless."},"feedback":{"zh":"得到支持后，担忧也可能慢慢才减轻；偶尔仍紧张，不等于之前的帮助全无用处。","en":"Relief need not eliminate worry permanently in one step."}}],"correct":"s09-R3-e4f0252f11"}}},"revisit":{"id":"s09-V1","prompt":{"zh":"担心报告有错，按照宝剑九的提醒，先做什么？","en":"Worried about a report error, how apply this?"},"options":[{"id":"s09-V1-9ffc424f50","text":{"zh":"只按担忧强度判断错误多少。","en":"Count errors by intensity of worry."},"feedback":{"zh":"检查报告的数据，才能知道哪里有错；担心得多，并不能说明错得多。","en":"Checking yields evidence; worry intensity yields no count."}},{"id":"s09-V1-8dbb2b5fb2","text":{"zh":"检查报告的数据，分清实际发现的错误和自己的猜测。","en":"Check data and distinguish found errors from imagined ones."},"feedback":{"zh":"检查报告的数据，才能知道哪里有错；担心得多，并不能说明错得多。","en":"Checking yields evidence; worry intensity yields no count."}}],"correct":"s09-V1-8dbb2b5fb2"},"summary":{"zh":"宝剑九关注反复担忧占据思绪的状态。忧虑带来的压力真实存在，但脑中想象的最坏结果，不会因为担心就成为事实。","en":"The Nine of Swords concerns recurring worries occupying the mind. The distress is real; the worst imagined story is not thereby a fact."},"cards":["s09"]},{"id":"s10","kind":"card","level":"I","title":{"zh":"宝剑十","en":"Ten of Swords"},"teachings":[{"zh":"宝剑十指某种做法或处境已到难以继续的终点，需要承认结束和受挫。它不是说人的所有未来都结束了。","en":"The Ten of Swords points to a method or situation reaching an unsustainable end. Acknowledge the ending and setback without declaring a person’s entire future over."},{"zh":"人物伏地、背后十剑，远方天际渐亮。这幅强烈的画面帮助我们记住“已经到极限了”；远方渐亮的天空则提醒我们，结束之后仍可能有下一步。","en":"A fallen figure bears ten swords as the horizon brightens. The strong image recalls a limit; the changing horizon allows a future beyond it."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关。数字十可以帮助记住一个阶段到了终点；结合整幅画，可以记成：结束、撑到极限、接受这一阶段已结束。它不能用来预言现实中的死亡。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air concerns thought and conflict; ten can aid remembering an ending, never literal death prediction. Helpers: ending, limit, acknowledging closure."}],"application":{"zh":"一个项目已取消，原定交付方式不再可行。建议位先接受旧方案结束，整理可以保留的成果，再安排下一步，而非假装项目仍按原计划运行。","en":"A project is canceled and the original delivery route no longer works. Advice acknowledges the end, preserves useful work, and plans next steps instead of pretending nothing changed."},"reversal":{"zh":"团队接受项目已经结束，开始整理已有成果、准备新的计划。这个例子里，宝剑十逆位表示从挫折中慢慢恢复，不表示旧项目会自动重新开始。","en":"The team accepts closure and organizes usable work and a new plan. Here reversal means beginning recovery, not automatically reviving the old project."},"visual":{"zh":"人物伏地、背后十剑，远方天际渐亮。这幅强烈的画面帮助我们记住“已经到极限了”；远方渐亮的天空则提醒我们，结束之后仍可能有下一步。","en":"A fallen figure bears ten swords as the horizon brightens. The strong image recalls a limit; the changing horizon allows a future beyond it."},"questions":{"Q1":{"id":"s10-Q1","prompt":{"zh":"宝剑十所说的“结束”，是哪种意思？","en":"Which matches this ending?"},"options":[{"id":"s10-Q1-efa2e17555","text":{"zh":"一个人此后绝无任何可能。","en":"A person has no future possibilities."},"feedback":{"zh":"结束的是眼前这个阶段或做法，不是说这个人以后一切都没有希望。","en":"The lesson concerns a specific phase, not an entire life."}},{"id":"s10-Q1-b1d127eec5","text":{"zh":"某种旧处境已无法继续。","en":"An old situation cannot continue."},"feedback":{"zh":"结束的是眼前这个阶段或做法，不是说这个人以后一切都没有希望。","en":"The lesson concerns a specific phase, not an entire life."}}],"correct":"s10-Q1-b1d127eec5","support":"R1"},"Q2":{"id":"s10-Q2","prompt":{"zh":"项目已经确定取消，按照刚才的例子，应该怎样处理？","en":"For the canceled project, which follows?"},"options":[{"id":"s10-Q2-e671c9a6b5","text":{"zh":"承认旧方案结束并整理可保留成果。","en":"Acknowledge closure and preserve usable work."},"feedback":{"zh":"项目已经明确取消，就要接受旧安排结束了，再整理可以保留的成果。","en":"The known cancellation requires acknowledging an end."}},{"id":"s10-Q2-0324ee5a84","text":{"zh":"继续假定旧安排完全有效。","en":"Keep assuming the old arrangement is valid."},"feedback":{"zh":"项目已经明确取消，就要接受旧安排结束了，再整理可以保留的成果。","en":"The known cancellation requires acknowledging an end."}}],"correct":"s10-Q2-e671c9a6b5","support":"R2"},"Q3":{"id":"s10-Q3","prompt":{"zh":"开始整理新计划，本例逆位表达什么？","en":"Starting a new plan: interpret this reversal."},"options":[{"id":"s10-Q3-352868b3de","text":{"zh":"旧项目已被保证恢复原样。","en":"The original project is guaranteed restored."},"feedback":{"zh":"从受挫中恢复，可以是开始新计划，不一定是把旧项目重新办起来。","en":"Recovery can take a new direction."}},{"id":"s10-Q3-9ed20afde8","text":{"zh":"从低点逐步恢复。","en":"Gradually recover from the low point."},"feedback":{"zh":"从受挫中恢复，可以是开始新计划，不一定是把旧项目重新办起来。","en":"Recovery can take a new direction."}}],"correct":"s10-Q3-9ed20afde8","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"结束的是眼前这个阶段或做法，不是说这个人以后一切都没有希望。","en":"The lesson concerns a specific phase, not an entire life."},{"zh":"已知的是旧方案行不通，不能因此断定以后所有方案都行不通。","en":"Limit the ending to the known situation."}],"question":{"id":"s10-R1","prompt":{"zh":"旧方案走到终点，是否等于所有方案都不可能？","en":"Does one plan ending rule out all plans?"},"options":[{"id":"s10-R1-9f1dbfbeaa","text":{"zh":"不是，旧方案行不通，还可以考虑新的方案。","en":"No; distinguish that plan from future possibilities."},"feedback":{"zh":"已知的是旧方案行不通，不能因此断定以后所有方案都行不通。","en":"Limit the ending to the known situation."}},{"id":"s10-R1-fc8ed0ea5c","text":{"zh":"是，结束一次就永远不能再开始。","en":"Yes; one ending prevents every new beginning."},"feedback":{"zh":"已知的是旧方案行不通，不能因此断定以后所有方案都行不通。","en":"Limit the ending to the known situation."}}],"correct":"s10-R1-9f1dbfbeaa"}},"R2":{"teach":[{"zh":"项目已经明确取消，就要接受旧安排结束了，再整理可以保留的成果。","en":"The known cancellation requires acknowledging an end."},{"zh":"课程已经停办，继续等原课表不会让它恢复；可以整理已学内容，再找替代课程。","en":"A clearly ended arrangement calls for closure."}],"question":{"id":"s10-R2","prompt":{"zh":"停办的课程无法续报，下一步怎样？","en":"A discontinued class cannot be renewed. What fits?"},"options":[{"id":"s10-R2-8a843c0d00","text":{"zh":"继续等待已明确取消的原课表。","en":"Keep waiting for the canceled schedule."},"feedback":{"zh":"课程已经停办，继续等原课表不会让它恢复；可以整理已学内容，再找替代课程。","en":"A clearly ended arrangement calls for closure."}},{"id":"s10-R2-1ece617772","text":{"zh":"接受这门课结束，整理所学再找替代。","en":"Accept closure, organize learning, and seek an alternative."},"feedback":{"zh":"课程已经停办，继续等原课表不会让它恢复；可以整理已学内容，再找替代课程。","en":"A clearly ended arrangement calls for closure."}}],"correct":"s10-R2-1ece617772"}},"R3":{"teach":[{"zh":"团队接受项目已经结束，开始整理已有成果、准备新的计划。这个例子里，宝剑十逆位表示从挫折中慢慢恢复，不表示旧项目会自动重新开始。","en":"The team accepts closure and organizes usable work and a new plan. Here reversal means beginning recovery, not automatically reviving the old project."},{"zh":"团队开始整理成果、准备新计划，就是在恢复；不需要旧项目恢复原样才算数。","en":"Recovery concerns action and planning, not reviving the old form."}],"question":{"id":"s10-R3","prompt":{"zh":"恢复阶段准备新方案，是否必须回到旧项目？","en":"Must recovery return to the old project?"},"options":[{"id":"s10-R3-751ea03605","text":{"zh":"必须，否则任何恢复都不算数。","en":"Yes; otherwise no recovery counts."},"feedback":{"zh":"团队开始整理成果、准备新计划，就是在恢复；不需要旧项目恢复原样才算数。","en":"Recovery concerns action and planning, not reviving the old form."}},{"id":"s10-R3-6886d7cf4f","text":{"zh":"不需要，可以接受旧项目结束，再开始新的计划。","en":"No; acknowledging closure can lead to a new direction."},"feedback":{"zh":"团队开始整理成果、准备新计划，就是在恢复；不需要旧项目恢复原样才算数。","en":"Recovery concerns action and planning, not reviving the old form."}}],"correct":"s10-R3-6886d7cf4f"}}},"revisit":{"id":"s10-V1","prompt":{"zh":"一段无效流程已被正式废止，如何理解？","en":"An ineffective process is formally retired. Interpret."},"options":[{"id":"s10-V1-202927ff64","text":{"zh":"承认旧流程结束，再建立新方式。","en":"Close the old process and build a new one."},"feedback":{"zh":"被废止的是一段流程，不是整个团队的未来；还可以建立新的做法。","en":"A local ending does not justify global hopelessness."}},{"id":"s10-V1-0d643af6ec","text":{"zh":"认为一段流程废止了，整个团队以后就没有希望。","en":"Interpret retirement as the end of the team’s future."},"feedback":{"zh":"被废止的是一段流程，不是整个团队的未来；还可以建立新的做法。","en":"A local ending does not justify global hopelessness."}}],"correct":"s10-V1-202927ff64"},"summary":{"zh":"宝剑十指某种做法或处境已到难以继续的终点，需要承认结束和受挫。它不是说人的所有未来都结束了。","en":"The Ten of Swords points to a method or situation reaching an unsustainable end. Acknowledge the ending and setback without declaring a person’s entire future over."},"cards":["s10"]},{"id":"s11","kind":"card","level":"I","title":{"zh":"宝剑侍从","en":"Page of Swords"},"teachings":[{"zh":"宝剑侍从表现出愿意观察、提问，并练习表达的初学者状态。敏锐和好奇值得保留，但听到信息还不等于已经核实。","en":"The Page of Swords approaches observation, questioning, and expression as skills being learned. Curiosity is useful; receiving information is not verifying it."},{"zh":"人物举剑、转头观察，风吹动周围树木和云。动作帮助记住留意周围、好奇求知，不用于判定现实年龄或性别。","en":"The figure holds a sword and looks aside amid windblown trees and clouds. The posture aids remembering alert inquiry, not a real person’s age or gender."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关；侍从让我们想到刚开始探索、愿意学习的状态。这张牌可以记成：好奇、留心观察、问清楚。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air supplies the domain of thought; Page suggests learning and exploration. Helpers: curiosity, alertness, specific questions."}],"application":{"zh":"小叶第一次读专业文章，看见陌生术语。建议位把“不懂”改成具体问题，核对定义和来源，再尝试复述。","en":"Ye encounters unfamiliar terms in a first specialist article. Advice turns confusion into specific questions, checks definitions and sources, then attempts an explanation."},"reversal":{"zh":"小叶只看标题就转发结论，没有读正文。这个例子里，宝剑侍从逆位提醒我们：还没核实就急着说了，需要回到原文检查。问题在没有核实，不在好奇心本身。","en":"Ye shares a conclusion after reading only a headline. Here reversal concerns unverified information and premature expression, calling for source checking rather than suppressing curiosity."},"visual":{"zh":"人物举剑、转头观察，风吹动周围树木和云。动作帮助记住留意周围、好奇求知，不用于判定现实年龄或性别。","en":"The figure holds a sword and looks aside amid windblown trees and clouds. The posture aids remembering alert inquiry, not a real person’s age or gender."},"questions":{"Q1":{"id":"s11-Q1","prompt":{"zh":"好奇和已掌握事实有什么区别？","en":"How does curiosity differ from established knowledge?"},"options":[{"id":"s11-Q1-6e80046559","text":{"zh":"感兴趣以后，还要提问、核实，才能真正弄懂。","en":"Curiosity needs inquiry and verification to become understanding."},"feedback":{"zh":"侍从愿意问、愿意学，但还在学习中；感兴趣不表示已经知道答案。","en":"A Page is learning, not already complete in knowledge."}},{"id":"s11-Q1-335e6694ff","text":{"zh":"只要感兴趣，猜测就自动正确。","en":"Interest automatically makes guesses correct."},"feedback":{"zh":"侍从愿意问、愿意学，但还在学习中；感兴趣不表示已经知道答案。","en":"A Page is learning, not already complete in knowledge."}}],"correct":"s11-Q1-6e80046559","support":"R1"},"Q2":{"id":"s11-Q2","prompt":{"zh":"面对陌生术语，小叶先怎样？","en":"Facing an unfamiliar term, Ye should first?"},"options":[{"id":"s11-Q2-2a1700db48","text":{"zh":"按字面猜完就当作可靠定义。","en":"Treat a literal guess as a verified definition."},"feedback":{"zh":"先查术语的实际定义，再问不懂的地方；只按字面猜，可能从一开始就理解错了。","en":"The example requires verification rather than guessing."}},{"id":"s11-Q2-498fb6341e","text":{"zh":"先查术语的意思，再问不懂的地方。","en":"Check its definition and ask a specific question."},"feedback":{"zh":"先查术语的实际定义，再问不懂的地方；只按字面猜，可能从一开始就理解错了。","en":"The example requires verification rather than guessing."}}],"correct":"s11-Q2-498fb6341e","support":"R2"},"Q3":{"id":"s11-Q3","prompt":{"zh":"只看标题就转发，本例逆位提示什么？","en":"Sharing from a headline alone: what fits?"},"options":[{"id":"s11-Q3-6ae7d86bed","text":{"zh":"转发前先读原文，检查说法对不对。","en":"Check the original before sharing."},"feedback":{"zh":"小叶的问题是没读正文就转发，不是好奇心太多；应该补上核查。","en":"The problem is lack of verification, not curiosity."}},{"id":"s11-Q3-7162fed8fd","text":{"zh":"停止提出任何问题。","en":"Stop asking questions altogether."},"feedback":{"zh":"小叶的问题是没读正文就转发，不是好奇心太多；应该补上核查。","en":"The problem is lack of verification, not curiosity."}}],"correct":"s11-Q3-6ae7d86bed","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"侍从愿意问、愿意学，但还在学习中；感兴趣不表示已经知道答案。","en":"A Page is learning, not already complete in knowledge."},{"zh":"遇到新说法可以好奇，也可以猜想，但在告诉别人“这是真的”之前，要先查来源。","en":"Exploration needs verification for reliable expression."}],"question":{"id":"s11-R1","prompt":{"zh":"遇到一句陌生说法，怎样保留好奇又避免乱猜？","en":"How can curiosity avoid careless guessing?"},"options":[{"id":"s11-R1-515957cb6c","text":{"zh":"把第一个联想直接写成事实。","en":"Write the first association as fact."},"feedback":{"zh":"遇到新说法可以好奇，也可以猜想，但在告诉别人“这是真的”之前，要先查来源。","en":"Exploration needs verification for reliable expression."}},{"id":"s11-R1-38cc7cca8e","text":{"zh":"把疑问问具体，并找可核对的来源。","en":"Ask specifically and find a checkable source."},"feedback":{"zh":"遇到新说法可以好奇，也可以猜想，但在告诉别人“这是真的”之前，要先查来源。","en":"Exploration needs verification for reliable expression."}}],"correct":"s11-R1-38cc7cca8e"}},"R2":{"teach":[{"zh":"先查术语的实际定义，再问不懂的地方；只按字面猜，可能从一开始就理解错了。","en":"The example requires verification rather than guessing."},{"zh":"先查清术语的意思、试过操作，再告诉别人，比把猜测转发出去更可靠。","en":"Confirming before spreading fits inquiry and verification."}],"question":{"id":"s11-R2","prompt":{"zh":"学软件时教程术语不懂，怎样补学？","en":"A software tutorial uses an unknown term. What fits?"},"options":[{"id":"s11-R2-665d4b79be","text":{"zh":"查看官方说明里的定义，再试一次操作。","en":"Check the documented definition and try the action."},"feedback":{"zh":"先查清术语的意思、试过操作，再告诉别人，比把猜测转发出去更可靠。","en":"Confirming before spreading fits inquiry and verification."}},{"id":"s11-R2-1443177ae3","text":{"zh":"转发猜测让别人照做。","en":"Share a guess as instructions."},"feedback":{"zh":"先查清术语的意思、试过操作，再告诉别人，比把猜测转发出去更可靠。","en":"Confirming before spreading fits inquiry and verification."}}],"correct":"s11-R2-665d4b79be"}},"R3":{"teach":[{"zh":"小叶只看标题就转发结论，没有读正文。这个例子里，宝剑侍从逆位提醒我们：还没核实就急着说了，需要回到原文检查。问题在没有核实，不在好奇心本身。","en":"Ye shares a conclusion after reading only a headline. Here reversal concerns unverified information and premature expression, calling for source checking rather than suppressing curiosity."},{"zh":"既然原来的消息没核实，就要回查原文；再加一个猜测，只会让说法更不可靠。","en":"Missing verification calls for evidence, not more guessing."}],"question":{"id":"s11-R3","prompt":{"zh":"发现转发未经核实，怎样修正？","en":"A shared claim was not verified. Correct it how?"},"options":[{"id":"s11-R3-14a83e9f90","text":{"zh":"回去查原文，并说清哪些已经确认、哪些还不知道。","en":"Check the original and clarify known and unknown."},"feedback":{"zh":"既然原来的消息没核实，就要回查原文；再加一个猜测，只会让说法更不可靠。","en":"Missing verification calls for evidence, not more guessing."}},{"id":"s11-R3-52a2f074b3","text":{"zh":"再加一个猜测，让说法显得完整。","en":"Add another guess to make it seem complete."},"feedback":{"zh":"既然原来的消息没核实，就要回查原文；再加一个猜测，只会让说法更不可靠。","en":"Missing verification calls for evidence, not more guessing."}}],"correct":"s11-R3-14a83e9f90"}}},"revisit":{"id":"s11-V1","prompt":{"zh":"小组收到新消息，适合怎样参与？","en":"A group receives new information. How should this style contribute?"},"options":[{"id":"s11-V1-dc53d09f86","text":{"zh":"为了显得敏锐，抢先下最终结论。","en":"Rush to a final verdict to look sharp."},"feedback":{"zh":"发现信息缺了什么、及时问清楚，也是一种敏锐；不用急着抢先下结论。","en":"Alertness can mean good questions rather than fast verdicts."}},{"id":"s11-V1-67446392a2","text":{"zh":"问清来源与具体内容。","en":"Ask about the source and precise content."},"feedback":{"zh":"发现信息缺了什么、及时问清楚，也是一种敏锐；不用急着抢先下结论。","en":"Alertness can mean good questions rather than fast verdicts."}}],"correct":"s11-V1-67446392a2"},"summary":{"zh":"宝剑侍从表现出愿意观察、提问，并练习表达的初学者状态。敏锐和好奇值得保留，但听到信息还不等于已经核实。","en":"The Page of Swords approaches observation, questioning, and expression as skills being learned. Curiosity is useful; receiving information is not verifying it."},"cards":["s11"]},{"id":"s12","kind":"card","level":"I","title":{"zh":"宝剑骑士","en":"Knight of Swords"},"teachings":[{"zh":"宝剑骑士把一个判断转成迅速、直接的行动，主动争取把事情往前推进。速度可以有用，但坚定语气不等于判断必然正确。","en":"The Knight of Swords turns a judgment into fast, direct action. Speed can help, but conviction does not guarantee accuracy."},{"zh":"骑士举剑前冲，马和风势强化速度。画面有行动方向，但没有保证方向正确的证据。","en":"The charging rider, raised sword, horse, and wind emphasize speed and direction without proving that direction correct."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关；骑士强调把想法付诸行动。这张牌可以记成：果断行动、迅速推进、直接表达。它描述做事方式，不限定年龄或性别。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air concerns judgment and expression; Knight emphasizes active pursuit without age or gender limits. Helpers: decisiveness, rapid action, direct expression."}],"application":{"zh":"会议即将结束，一个关键需求仍未说清。建议位可直接提出关键问题并推动确认，同时核对必要事实；不是打断别人、抢着说话就算有效。","en":"A key requirement remains unclear as a meeting ends. Advice is to raise it directly and secure confirmation while checking facts, not simply interrupt loudly."},"reversal":{"zh":"有人没核对任务，就催全组立刻开始做，后来发现方向错了。这个例子里，宝剑骑士逆位表示行动太急，需要先慢下来核对要求，再继续推进，而不是从此什么都不做。","en":"Someone rushes everyone into execution without checking the task, then finds the direction wrong. Here reversal concerns haste and calls for verification, not abandoning action."},"visual":{"zh":"骑士举剑前冲，马和风势强化速度。画面有行动方向，但没有保证方向正确的证据。","en":"The charging rider, raised sword, horse, and wind emphasize speed and direction without proving that direction correct."},"questions":{"Q1":{"id":"s12-Q1","prompt":{"zh":"果断是否自动代表正确？","en":"Does decisiveness guarantee correctness?"},"options":[{"id":"s12-Q1-a2da048e2b","text":{"zh":"代表，速度越快判断越可靠。","en":"Yes; faster judgments are more reliable."},"feedback":{"zh":"动作快，不等于想得对。还要看这个判断有没有事实支持。","en":"Check speed and judgment quality separately."}},{"id":"s12-Q1-6a3a0c8800","text":{"zh":"不代表，仍需事实支持。","en":"No; it still needs factual support."},"feedback":{"zh":"动作快，不等于想得对。还要看这个判断有没有事实支持。","en":"Check speed and judgment quality separately."}}],"correct":"s12-Q1-6a3a0c8800","support":"R1"},"Q2":{"id":"s12-Q2","prompt":{"zh":"会议快结束了，关键需求还不清楚，怎样运用宝剑骑士的做事方式？","en":"A key requirement is unclear at meeting end. What fits?"},"options":[{"id":"s12-Q2-bd24569991","text":{"zh":"直接提出关键问题并确认事实。","en":"Raise the key question directly and confirm facts."},"feedback":{"zh":"先直接问清关键需求，才知道该往哪里做；不问清就催大家行动，可能走错方向。","en":"Rapid progress still needs a clear judgment."}},{"id":"s12-Q2-cf70a80fdc","text":{"zh":"不问需求，立刻要求所有人照猜测做。","en":"Skip the requirement and demand action on a guess."},"feedback":{"zh":"先直接问清关键需求，才知道该往哪里做；不问清就催大家行动，可能走错方向。","en":"Rapid progress still needs a clear judgment."}}],"correct":"s12-Q2-bd24569991","support":"R2"},"Q3":{"id":"s12-Q3","prompt":{"zh":"没核对就催全组执行，逆位提醒什么？","en":"Rushing execution without checking: what fits?"},"options":[{"id":"s12-Q3-34c7204cf5","text":{"zh":"既然已开始，就绝不能检查方向。","en":"Once started, never check direction."},"feedback":{"zh":"这次是没核对任务就开始，才做错了方向；先把条件查清，才能避免继续做错。","en":"Haste caused the problem; checking is the correction."}},{"id":"s12-Q3-0f540a7fc8","text":{"zh":"先核实关键条件再推进。","en":"Verify critical conditions before proceeding."},"feedback":{"zh":"这次是没核对任务就开始，才做错了方向；先把条件查清，才能避免继续做错。","en":"Haste caused the problem; checking is the correction."}}],"correct":"s12-Q3-0f540a7fc8","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"动作快，不等于想得对。还要看这个判断有没有事实支持。","en":"Check speed and judgment quality separately."},{"zh":"表达可以直接，但说得大声、坚定，不能代替事实依据。","en":"Directness is not substituting tone for evidence."}],"question":{"id":"s12-R1","prompt":{"zh":"想让事情快一点，哪种做法符合宝剑骑士的提醒？","en":"To move things quickly, which fits?"},"options":[{"id":"s12-R1-0d7a7751e9","text":{"zh":"直接问清关键问题，核实后开始做。","en":"Focus, act directly, and verify."},"feedback":{"zh":"表达可以直接，但说得大声、坚定，不能代替事实依据。","en":"Directness is not substituting tone for evidence."}},{"id":"s12-R1-614e0cafde","text":{"zh":"靠更大声掩盖不知道的事实。","en":"Hide unknown facts by speaking louder."},"feedback":{"zh":"表达可以直接，但说得大声、坚定，不能代替事实依据。","en":"Directness is not substituting tone for evidence."}}],"correct":"s12-R1-0d7a7751e9"}},"R2":{"teach":[{"zh":"先直接问清关键需求，才知道该往哪里做；不问清就催大家行动，可能走错方向。","en":"Rapid progress still needs a clear judgment."},{"zh":"先问清提交要求，才能交对内容；交得很快但不符合要求，也没有解决问题。","en":"Efficiency should serve the goal, not speed alone."}],"question":{"id":"s12-R2","prompt":{"zh":"临近提交时发现要求不明，先怎样？","en":"Requirements are unclear near submission. First?"},"options":[{"id":"s12-R2-0c44e8226d","text":{"zh":"立即提交未检查的版本来证明效率。","en":"Submit an unchecked version to prove efficiency."},"feedback":{"zh":"先问清提交要求，才能交对内容；交得很快但不符合要求，也没有解决问题。","en":"Efficiency should serve the goal, not speed alone."}},{"id":"s12-R2-f32c542d28","text":{"zh":"赶快问清关键要求，再做已经确认的部分。","en":"Quickly clarify the requirement and act on what is clear."},"feedback":{"zh":"先问清提交要求，才能交对内容；交得很快但不符合要求，也没有解决问题。","en":"Efficiency should serve the goal, not speed alone."}}],"correct":"s12-R2-f32c542d28"}},"R3":{"teach":[{"zh":"有人没核对任务，就催全组立刻开始做，后来发现方向错了。这个例子里，宝剑骑士逆位表示行动太急，需要先慢下来核对要求，再继续推进，而不是从此什么都不做。","en":"Someone rushes everyone into execution without checking the task, then finds the direction wrong. Here reversal concerns haste and calls for verification, not abandoning action."},{"zh":"发现方向错了，先停下来核对任务，再继续做，才不会越忙越偏。","en":"Slowing to verify supports effective progress."}],"question":{"id":"s12-R3","prompt":{"zh":"推进方向有误，怎样保留行动力？","en":"Direction is wrong. How retain useful momentum?"},"options":[{"id":"s12-R3-a32763a11f","text":{"zh":"把所有核对都看成阻碍，继续冲。","en":"Treat all checking as obstruction and charge on."},"feedback":{"zh":"发现方向错了，先停下来核对任务，再继续做，才不会越忙越偏。","en":"Slowing to verify supports effective progress."}},{"id":"s12-R3-8f9bccf4f5","text":{"zh":"核实任务，修正方向后继续。","en":"Verify the task, correct direction, and continue."},"feedback":{"zh":"发现方向错了，先停下来核对任务，再继续做，才不会越忙越偏。","en":"Slowing to verify supports effective progress."}}],"correct":"s12-R3-8f9bccf4f5"}}},"revisit":{"id":"s12-V1","prompt":{"zh":"讨论中有人很坚定，怎样理解这个角色？","en":"Someone argues firmly. How interpret this style?"},"options":[{"id":"s12-V1-aa498e67c3","text":{"zh":"可能积极争取，但观点仍需核对。","en":"They may press actively; their claim still needs checking."},"feedback":{"zh":"这个人积极、说话坚定，描述的是做事风格；他的观点对不对，仍要核对事实。","en":"The lesson separates action style from truth."}},{"id":"s12-V1-91513fb6ed","text":{"zh":"坚定本身就能替代全部证据。","en":"Firmness replaces all evidence."},"feedback":{"zh":"这个人积极、说话坚定，描述的是做事风格；他的观点对不对，仍要核对事实。","en":"The lesson separates action style from truth."}}],"correct":"s12-V1-aa498e67c3"},"summary":{"zh":"宝剑骑士把一个判断转成迅速、直接的行动，主动争取把事情往前推进。速度可以有用，但坚定语气不等于判断必然正确。","en":"The Knight of Swords turns a judgment into fast, direct action. Speed can help, but conviction does not guarantee accuracy."},"cards":["s12"]},{"id":"s13","kind":"card","level":"I","title":{"zh":"宝剑王后","en":"Queen of Swords"},"teachings":[{"zh":"宝剑王后强调自己想清楚、根据事实作判断，并说清什么可以接受、什么不能接受。可以直接说明事实和底线，同时愿意听对方说明；不需要用冷漠证明理性。","en":"The Queen of Swords emphasizes clear judgment, independent thought, and boundaries. State facts and limits while allowing dialogue; coldness is not required for reason."},{"zh":"一手直立持剑，另一手向外伸出。用两种动作一起记忆：有明确界限，也可以交流。","en":"One hand holds an upright sword while the other reaches outward. Remember both a clear boundary and openness to dialogue."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关；王后强调根据经验作判断、把话说清楚。这张牌可以记成：独立思考、看清事实、说清底线。它不限定性别或婚姻状况。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air concerns judgment; Queen here suggests mature use of this domain, not gender or marital status. Helpers: independence, clarity, boundaries."}],"application":{"zh":"朋友常临时取消约定。建议位可清楚说明自己能接受的通知时间，并听取对方现实困难，而非沉默惩罚。","en":"A friend often cancels at short notice. Advice is to state an acceptable notice period and hear practical difficulties rather than punish through silence."},"reversal":{"zh":"一个人以前受过伤，现在把新朋友每次晚回消息都当成恶意，也不愿听解释。这个例子里，宝剑王后逆位表示过去的伤害影响了眼前的判断，需要重新看这次的事实；不能据此给某个人下人格诊断。","en":"Past hurt leads someone to treat every delayed reply from a new friend as malice. Here reversal concerns bias from past pain and calls for checking current facts, not diagnosing personality."},"visual":{"zh":"一手直立持剑，另一手向外伸出。用两种动作一起记忆：有明确界限，也可以交流。","en":"One hand holds an upright sword while the other reaches outward. Remember both a clear boundary and openness to dialogue."},"questions":{"Q1":{"id":"s13-Q1","prompt":{"zh":"把自己的底线说清楚，就必须拒绝听对方解释吗？","en":"Do clear boundaries require refusing dialogue?"},"options":[{"id":"s13-Q1-0b5bcfd63b","text":{"zh":"不需要，可以说清自己的底线，也听听对方的情况。","en":"No; state them and hear an explanation."},"feedback":{"zh":"你可以坚持自己的底线，也可以听对方解释；两件事并不冲突。","en":"The lesson preserves both judgment and dialogue."}},{"id":"s13-Q1-72a58545a0","text":{"zh":"必须，不听任何解释才算清醒。","en":"Yes; clarity means hearing no explanation."},"feedback":{"zh":"你可以坚持自己的底线，也可以听对方解释；两件事并不冲突。","en":"The lesson preserves both judgment and dialogue."}}],"correct":"s13-Q1-0b5bcfd63b","support":"R1"},"Q2":{"id":"s13-Q2","prompt":{"zh":"朋友临时取消约定，怎样回应？","en":"A friend cancels at short notice. What fits?"},"options":[{"id":"s13-Q2-2ec4f5d02e","text":{"zh":"不说需求，只以沉默让对方猜。","en":"Say nothing and make them guess."},"feedback":{"zh":"想让对方提前通知，就把要求说清楚；一直沉默，对方可能仍不知道你介意什么。","en":"Stated boundaries fit the example better than hidden ones."}},{"id":"s13-Q2-487eb1dbdb","text":{"zh":"说明可接受的提前通知方式。","en":"State an acceptable notice arrangement."},"feedback":{"zh":"想让对方提前通知，就把要求说清楚；一直沉默，对方可能仍不知道你介意什么。","en":"Stated boundaries fit the example better than hidden ones."}}],"correct":"s13-Q2-487eb1dbdb","support":"R2"},"Q3":{"id":"s13-Q3","prompt":{"zh":"把旧伤套在新朋友身上，本例逆位提示什么？","en":"Applying past hurt to a new friend: reversal?"},"options":[{"id":"s13-Q3-1474b4e2a2","text":{"zh":"把过去受伤的经历和这次实际发生的事分开看。","en":"Separate past experience from current evidence."},"feedback":{"zh":"过去受过伤可以理解，但新朋友为什么晚回消息，需要根据这次的事实判断。","en":"Experience can inform but cannot prove current motives."}},{"id":"s13-Q3-cdf00f8c01","text":{"zh":"旧经历已证明新朋友动机。","en":"Past experience proves the new friend’s motive."},"feedback":{"zh":"过去受过伤可以理解，但新朋友为什么晚回消息，需要根据这次的事实判断。","en":"Experience can inform but cannot prove current motives."}}],"correct":"s13-Q3-1474b4e2a2","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"你可以坚持自己的底线，也可以听对方解释；两件事并不冲突。","en":"The lesson preserves both judgment and dialogue."},{"zh":"说清自己哪里不方便后，仍可以听听有没有别的安排，不必把不同意见都当成冒犯。","en":"Boundaries do not require rejecting disagreement."}],"question":{"id":"s13-R1","prompt":{"zh":"直接表达“不方便”，怎样既清楚又可交流？","en":"How can declining be clear and open?"},"options":[{"id":"s13-R1-c3631ab16e","text":{"zh":"把所有不同意见都当冒犯。","en":"Treat every disagreement as an insult."},"feedback":{"zh":"说清自己哪里不方便后，仍可以听听有没有别的安排，不必把不同意见都当成冒犯。","en":"Boundaries do not require rejecting disagreement."}},{"id":"s13-R1-a5a60931de","text":{"zh":"说清自己哪里不方便，再商量有没有别的安排。","en":"State the limit and discuss feasible alternatives."},"feedback":{"zh":"说清自己哪里不方便后，仍可以听听有没有别的安排，不必把不同意见都当成冒犯。","en":"Boundaries do not require rejecting disagreement."}}],"correct":"s13-R1-a5a60931de"}},"R2":{"teach":[{"zh":"想让对方提前通知，就把要求说清楚；一直沉默，对方可能仍不知道你介意什么。","en":"Stated boundaries fit the example better than hidden ones."},{"zh":"先指出哪项分工与约定不符，才能讨论怎么调整；只评价对方是什么人，解决不了这次分工问题。","en":"Clear judgment needs facts and defined scope."}],"question":{"id":"s13-R2","prompt":{"zh":"同伴反复超出约定分工，怎样补救？","en":"A teammate repeatedly exceeds agreed scope. What fits?"},"options":[{"id":"s13-R2-1f58ba2549","text":{"zh":"指出具体约定，再谈如何调整。","en":"Refer to the agreement and discuss adjustments."},"feedback":{"zh":"先指出哪项分工与约定不符，才能讨论怎么调整；只评价对方是什么人，解决不了这次分工问题。","en":"Clear judgment needs facts and defined scope."}},{"id":"s13-R2-a692a1728d","text":{"zh":"避开具体事实，只评价对方人格。","en":"Avoid facts and judge their character."},"feedback":{"zh":"先指出哪项分工与约定不符，才能讨论怎么调整；只评价对方是什么人，解决不了这次分工问题。","en":"Clear judgment needs facts and defined scope."}}],"correct":"s13-R2-1f58ba2549"}},"R3":{"teach":[{"zh":"一个人以前受过伤，现在把新朋友每次晚回消息都当成恶意，也不愿听解释。这个例子里，宝剑王后逆位表示过去的伤害影响了眼前的判断，需要重新看这次的事实；不能据此给某个人下人格诊断。","en":"Past hurt leads someone to treat every delayed reply from a new friend as malice. Here reversal concerns bias from past pain and calls for checking current facts, not diagnosing personality."},{"zh":"先听新朋友这次的说明，再看是否可信；过去的经历不能直接证明这次也一样。","en":"Experience should not block judgment of new facts."}],"question":{"id":"s13-R3","prompt":{"zh":"新朋友说明迟回复原因，如何修正旧伤带来的判断？","en":"A new friend explains a late reply. Correct the past-pain bias how?"},"options":[{"id":"s13-R3-40b367273c","text":{"zh":"听听这次的解释、核对事实，也保留自己的底线。","en":"Hear and check current facts while keeping boundaries."},"feedback":{"zh":"先听新朋友这次的说明，再看是否可信；过去的经历不能直接证明这次也一样。","en":"Experience should not block judgment of new facts."}},{"id":"s13-R3-661ad2632a","text":{"zh":"无需听说明，旧经历已经证明全部。","en":"Ignore the explanation because the past proves everything."},"feedback":{"zh":"先听新朋友这次的说明，再看是否可信；过去的经历不能直接证明这次也一样。","en":"Experience should not block judgment of new facts."}}],"correct":"s13-R3-40b367273c"}}},"revisit":{"id":"s13-V1","prompt":{"zh":"家人的安排不适合你，按照宝剑王后的提醒，怎样回应？","en":"Family proposes an unsuitable arrangement. Apply the theme."},"options":[{"id":"s13-V1-cc84c7eb27","text":{"zh":"认为独立就必须永远断绝沟通。","en":"Assume independence requires permanent silence."},"feedback":{"zh":"你可以说明自己能接受什么，再讨论安排；有自己的判断，不等于必须断绝沟通。","en":"Independent judgment can coexist with dialogue."}},{"id":"s13-V1-8d977c49f7","text":{"zh":"说明自己的条件与可接受范围。","en":"Explain your conditions and acceptable limits."},"feedback":{"zh":"你可以说明自己能接受什么，再讨论安排；有自己的判断，不等于必须断绝沟通。","en":"Independent judgment can coexist with dialogue."}}],"correct":"s13-V1-8d977c49f7"},"summary":{"zh":"宝剑王后强调自己想清楚、根据事实作判断，并说清什么可以接受、什么不能接受。可以直接说明事实和底线，同时愿意听对方说明；不需要用冷漠证明理性。","en":"The Queen of Swords emphasizes clear judgment, independent thought, and boundaries. State facts and limits while allowing dialogue; coldness is not required for reason."},"cards":["s13"]},{"id":"s14","kind":"card","level":"I","title":{"zh":"宝剑国王","en":"King of Swords"},"teachings":[{"zh":"宝剑国王根据知识和原则作决定，对同类事情采用同一标准，并为自己的决定负责。即使是权威人物，也需要说明决定的依据。","en":"The King of Swords uses knowledge, principles, and consistent standards for complex decisions and accepts responsibility. Authority does not replace checkable reasons."},{"zh":"人物正面坐稳并持剑，呈现正式判断的姿态。可以用来记住认真作决定、承担责任，不据此认定现实某位专家永远正确。","en":"A seated figure faces forward holding a sword, suggesting formal judgment. Remember responsibility without assuming an expert is infallible."},{"zh":"宝剑对应风元素，常和思考、判断、表达有关；国王强调作决定，并为决定负责。这张牌可以记成：按事实判断、有原则、运用专业知识、标准一致。它不限定性别。","en":"Swords correspond to Air and commonly concern thought, judgment, and communication. Air concerns analysis and expression; King emphasizes oversight and responsibility without gender limits. Helpers: reason, principles, expert judgment, consistent standards."}],"application":{"zh":"团队需要评选方案。建议位先公开评价标准，再用同样标准比较各方案，最后说明决定，而不是只说“听我的”。","en":"A team must select a proposal. Advice is to publish criteria, apply them consistently, and explain the decision rather than simply demand obedience."},"reversal":{"zh":"负责人说自己按规则评分，却临时为喜欢的方案改标准。这个例子里，宝剑国王逆位提醒我们：有人在用权威和看似合理的说法偏袒或压制别人。需要重新检查，所有方案是否用了同一标准。","en":"A leader claims rule-based scoring but changes criteria for a favored proposal. Here reversal concerns authority and rational language being used to dominate or favor."},"visual":{"zh":"人物正面坐稳并持剑，呈现正式判断的姿态。可以用来记住认真作决定、承担责任，不据此认定现实某位专家永远正确。","en":"A seated figure faces forward holding a sword, suggesting formal judgment. Remember responsibility without assuming an expert is infallible."},"questions":{"Q1":{"id":"s14-Q1","prompt":{"zh":"专业判断靠什么建立可信度？","en":"What makes a judgment accountable?"},"options":[{"id":"s14-Q1-1667300c88","text":{"zh":"只要有头衔就不需要说明。","en":"A title removes the need to explain."},"feedback":{"zh":"一个判断是否可靠，要看理由和证据；有头衔的人也应该说明依据。","en":"The lesson emphasizes checkable judgment, not status replacing reasons."}},{"id":"s14-Q1-ebe7d03028","text":{"zh":"理由、证据和一致标准。","en":"Reasons, evidence, and consistent standards."},"feedback":{"zh":"一个判断是否可靠，要看理由和证据；有头衔的人也应该说明依据。","en":"The lesson emphasizes checkable judgment, not status replacing reasons."}}],"correct":"s14-Q1-ebe7d03028","support":"R1"},"Q2":{"id":"s14-Q2","prompt":{"zh":"评选团队方案，先做什么？","en":"Selecting a team proposal: first?"},"options":[{"id":"s14-Q2-aca3d7774f","text":{"zh":"先说清评选标准，再按同一标准评选。","en":"Publish and consistently apply criteria."},"feedback":{"zh":"先说清怎么评，再用同一标准比较各方案，大家才知道决定是怎样作出的。","en":"Shared criteria support accountable decisions."}},{"id":"s14-Q2-fe45b27477","text":{"zh":"看是谁提交，再换成对他有利的标准。","en":"Change criteria based on the submitter."},"feedback":{"zh":"先说清怎么评，再用同一标准比较各方案，大家才知道决定是怎样作出的。","en":"Shared criteria support accountable decisions."}}],"correct":"s14-Q2-aca3d7774f","support":"R2"},"Q3":{"id":"s14-Q3","prompt":{"zh":"为偏爱方案改评分标准，逆位怎么理解？","en":"Changing criteria for a favorite: interpret."},"options":[{"id":"s14-Q3-6661b381d5","text":{"zh":"只要负责人决定就一定公平。","en":"A leader’s decision is automatically fair."},"feedback":{"zh":"负责人说自己“按规则办”，不表示真的做到了；还要看有没有为喜欢的方案改标准。","en":"Rule-based language does not prove consistency."}},{"id":"s14-Q3-706588d2b4","text":{"zh":"负责人在偏袒喜欢的方案，需要检查评分标准是否一样。","en":"Authority favors someone; examine the criteria."},"feedback":{"zh":"负责人说自己“按规则办”，不表示真的做到了；还要看有没有为喜欢的方案改标准。","en":"Rule-based language does not prove consistency."}}],"correct":"s14-Q3-706588d2b4","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"一个判断是否可靠，要看理由和证据；有头衔的人也应该说明依据。","en":"The lesson emphasizes checkable judgment, not status replacing reasons."},{"zh":"把事实和标准说明白，别人才能检查决定是否合理；堆术语并不能代替这些依据。","en":"Responsible judgment allows scrutiny, not jargon."}],"question":{"id":"s14-R1","prompt":{"zh":"为什么要说明决定依据？","en":"Why explain a decision’s basis?"},"options":[{"id":"s14-R1-4281b387e5","text":{"zh":"让别人能检查事实和标准。","en":"Let others examine facts and standards."},"feedback":{"zh":"把事实和标准说明白，别人才能检查决定是否合理；堆术语并不能代替这些依据。","en":"Responsible judgment allows scrutiny, not jargon."}},{"id":"s14-R1-b2c91c5b1d","text":{"zh":"只是为了多说几个专业词，让自己显得懂得多。","en":"Merely to sound more technical."},"feedback":{"zh":"把事实和标准说明白，别人才能检查决定是否合理；堆术语并不能代替这些依据。","en":"Responsible judgment allows scrutiny, not jargon."}}],"correct":"s14-R1-4281b387e5"}},"R2":{"teach":[{"zh":"先说清怎么评，再用同一标准比较各方案，大家才知道决定是怎样作出的。","en":"Shared criteria support accountable decisions."},{"zh":"不论申请者是不是熟人，都应按事先说明的同一套条件审核。","en":"Consistent standards must hold across people."}],"question":{"id":"s14-R2","prompt":{"zh":"社团分配名额，怎样运用宝剑国王强调的统一标准？","en":"A club allocates places. Apply the theme."},"options":[{"id":"s14-R2-8c439e3ee0","text":{"zh":"看到熟人后临时放宽要求。","en":"Relax requirements for acquaintances."},"feedback":{"zh":"不论申请者是不是熟人，都应按事先说明的同一套条件审核。","en":"Consistent standards must hold across people."}},{"id":"s14-R2-2e456eeaae","text":{"zh":"先说明资格，再按同样条件审核。","en":"State eligibility and review under the same conditions."},"feedback":{"zh":"不论申请者是不是熟人，都应按事先说明的同一套条件审核。","en":"Consistent standards must hold across people."}}],"correct":"s14-R2-2e456eeaae"}},"R3":{"teach":[{"zh":"负责人说自己按规则评分，却临时为喜欢的方案改标准。这个例子里，宝剑国王逆位提醒我们：有人在用权威和看似合理的说法偏袒或压制别人。需要重新检查，所有方案是否用了同一标准。","en":"A leader claims rule-based scoring but changes criteria for a favored proposal. Here reversal concerns authority and rational language being used to dominate or favor."},{"zh":"问题是评分标准因人而变；重新按同一标准评分，比换一套专业说法更重要。","en":"Jargon cannot repair inconsistent standards."}],"question":{"id":"s14-R3","prompt":{"zh":"发现评分偏袒后，怎样修复？","en":"Biased scoring is found. Repair it how?"},"options":[{"id":"s14-R3-3aaf11a2d5","text":{"zh":"给临时偏袒加更多专业术语。","en":"Add technical jargon to the favoritism."},"feedback":{"zh":"问题是评分标准因人而变；重新按同一标准评分，比换一套专业说法更重要。","en":"Jargon cannot repair inconsistent standards."}},{"id":"s14-R3-95a1848aeb","text":{"zh":"重新按事先说好的同一标准，核对各方案的分数。","en":"Restore consistent public criteria and review scores."},"feedback":{"zh":"问题是评分标准因人而变；重新按同一标准评分，比换一套专业说法更重要。","en":"Jargon cannot repair inconsistent standards."}}],"correct":"s14-R3-95a1848aeb"}}},"revisit":{"id":"s14-V1","prompt":{"zh":"两位专家意见不同，宝剑国王提醒我们怎样判断？","en":"Two experts disagree. What fits?"},"options":[{"id":"s14-V1-369e729bbb","text":{"zh":"比较他们各自根据什么、在什么情况下成立。","en":"Compare their evidence and conditions."},"feedback":{"zh":"专家意见不同，就比较他们各自依据什么、在什么条件下成立；不能只看头衔。","en":"Knowledge-based judgment returns to reasons and scope."}},{"id":"s14-V1-23c4473c4f","text":{"zh":"只比较头衔长度。","en":"Compare the length of their titles."},"feedback":{"zh":"专家意见不同，就比较他们各自依据什么、在什么条件下成立；不能只看头衔。","en":"Knowledge-based judgment returns to reasons and scope."}}],"correct":"s14-V1-369e729bbb"},"summary":{"zh":"宝剑国王根据知识和原则作决定，对同类事情采用同一标准，并为自己的决定负责。即使是权威人物，也需要说明决定的依据。","en":"The King of Swords uses knowledge, principles, and consistent standards for complex decisions and accepts responsibility. Authority does not replace checkable reasons."},"cards":["s14"]},{"id":"p01","kind":"card","level":"I","title":{"zh":"星币王牌","en":"Ace of Pentacles"},"teachings":[{"zh":"星币王牌表示一个值得着手的机会：你已经有了一些资源、时间或条件，接下来还要动手去做，才可能有成果。它不是收到财富的保证。","en":"The Ace of Pentacles is an opportunity that can be cultivated in practice. Resources, time, or conditions offer a starting point, but development still requires investment; wealth is not guaranteed."},{"zh":"云中手托着星币，下方有花园和拱门。花园和入口帮助我们记住：机会已经出现，还需要走进去、开始做，不把星币当成确定收入。","en":"A hand holds a pentacle above a garden and archway. The accessible setting suggests a practical beginning, not guaranteed income."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关；王牌表示新的起点。这张牌可以记成：新的机会、可用的资源、开始动手。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth directs attention to practical conditions; an Ace suggests a beginning. Helpers: a cultivable opportunity, resources, practical grounding."}],"application":{"zh":"小陆有机会借到绘画工具，也有每周两小时空闲。放在建议位，可以先确认怎么借工具、哪天练习、第一次画什么，让这个机会变成一次真正的学习。","en":"Lu can borrow drawing tools and has two free hours weekly. Advice is to secure the tools, time, and first exercise so the opportunity becomes practical learning."},"reversal":{"zh":"小陆答应开始学画，却没确认工具怎么借、什么时候能练。这个例子里，星币王牌逆位表示机会还没有真正用起来，需要先把工具和时间安排好；不表示他永远学不会。","en":"Lu agrees to begin but has not secured tools or time. Here reversal means an unrealized opportunity requiring practical preparation, not permanent inability."},"visual":{"zh":"云中手托着星币，下方有花园和拱门。花园和入口帮助我们记住：机会已经出现，还需要走进去、开始做，不把星币当成确定收入。","en":"A hand holds a pentacle above a garden and archway. The accessible setting suggests a practical beginning, not guaranteed income."},"questions":{"Q1":{"id":"p01-Q1","prompt":{"zh":"机会出现是否等于成果已到手？","en":"Does an opportunity mean the result is already secured?"},"options":[{"id":"p01-Q1-3cb7202f17","text":{"zh":"不等于，还需要安排时间、准备资源并实际去做。","en":"No; practical investment is still needed."},"feedback":{"zh":"有机会开始，不表示已经做好；还需要准备和行动。","en":"An Ace is a starting point, not a completion guarantee."}},{"id":"p01-Q1-dae485d40a","text":{"zh":"等于，看到机会就不用行动。","en":"Yes; an opportunity removes the need to act."},"feedback":{"zh":"有机会开始，不表示已经做好；还需要准备和行动。","en":"An Ace is a starting point, not a completion guarantee."}}],"correct":"p01-Q1-3cb7202f17","support":"R1"},"Q2":{"id":"p01-Q2","prompt":{"zh":"已经能借到工具，也有空闲时间，先做什么？","en":"Tools and time may be available. First?"},"options":[{"id":"p01-Q2-bbb8697b94","text":{"zh":"只想象最终作品，不安排开始。","en":"Imagine the final artwork without arranging a start."},"feedback":{"zh":"有工具可借之后，再留出练习时间、准备好材料，才能真正开始画画。","en":"The example turns possibility into workable conditions."}},{"id":"p01-Q2-fc3368c370","text":{"zh":"确认借用，安排第一项练习。","en":"Confirm access and schedule the first exercise."},"feedback":{"zh":"有工具可借之后，再留出练习时间、准备好材料，才能真正开始画画。","en":"The example turns possibility into workable conditions."}}],"correct":"p01-Q2-fc3368c370","support":"R2"},"Q3":{"id":"p01-Q3","prompt":{"zh":"工具怎么借、什么时候练都没安排好，这个逆位例子在提醒什么？","en":"Neither tools nor time are secured. Reversal?"},"options":[{"id":"p01-Q3-562d2a44f6","text":{"zh":"机会已经有了，但工具和时间还需要安排好。","en":"The opportunity needs practical preparation."},"feedback":{"zh":"现在还没准备好，不表示以后也做不到；可以先把缺少的工具和时间安排好。","en":"Lack of preparation differs from permanent inability."}},{"id":"p01-Q3-fa49b2d65b","text":{"zh":"绘画能力永远无法形成。","en":"Drawing ability can never develop."},"feedback":{"zh":"现在还没准备好，不表示以后也做不到；可以先把缺少的工具和时间安排好。","en":"Lack of preparation differs from permanent inability."}}],"correct":"p01-Q3-562d2a44f6","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"有机会开始，不表示已经做好；还需要准备和行动。","en":"An Ace is a starting point, not a completion guarantee."},{"zh":"成长仍需要资源与行动。","en":"Growth still needs resources and action."}],"question":{"id":"p01-R1","prompt":{"zh":"有了新的机会，就表示已经有成果了吗？","en":"What does cultivable mean?"},"options":[{"id":"p01-R1-64f4d9757c","text":{"zh":"只要能开始，就表示最后已经做好了。","en":"The beginning contains every finished result."},"feedback":{"zh":"成长仍需要资源与行动。","en":"Growth still needs resources and action."}},{"id":"p01-R1-ccad4a6d48","text":{"zh":"有机会开始，之后还要花时间实际去做。","en":"There is a start that needs continued care."},"feedback":{"zh":"成长仍需要资源与行动。","en":"Growth still needs resources and action."}}],"correct":"p01-R1-ccad4a6d48"}},"R2":{"teach":[{"zh":"有工具可借之后，再留出练习时间、准备好材料，才能真正开始画画。","en":"The example turns possibility into workable conditions."},{"zh":"拿到工具只是开始，还要实际练习，才能学会使用。","en":"Access to resources is not acquired skill."}],"question":{"id":"p01-R2","prompt":{"zh":"有了试用学习软件的机会，按照星币王牌的提醒，先做什么？","en":"A trial learning tool becomes available. Ground it how?"},"options":[{"id":"p01-R2-cde95d5802","text":{"zh":"确认设备可用并完成第一项练习。","en":"Check device access and complete a first exercise."},"feedback":{"zh":"拿到工具只是开始，还要实际练习，才能学会使用。","en":"Access to resources is not acquired skill."}},{"id":"p01-R2-cb06a26107","text":{"zh":"只保存注册链接，认为技能已获得。","en":"Save the link and assume the skill is acquired."},"feedback":{"zh":"拿到工具只是开始，还要实际练习，才能学会使用。","en":"Access to resources is not acquired skill."}}],"correct":"p01-R2-cde95d5802"}},"R3":{"teach":[{"zh":"小陆答应开始学画，却没确认工具怎么借、什么时候能练。这个例子里，星币王牌逆位表示机会还没有真正用起来，需要先把工具和时间安排好；不表示他永远学不会。","en":"Lu agrees to begin but has not secured tools or time. Here reversal means an unrealized opportunity requiring practical preparation, not permanent inability."},{"zh":"这次缺的是设备和时间；光说“我一定行”，不会让设备和时间自动出现。","en":"The gap concerns preparation, not strength of belief."}],"question":{"id":"p01-R3","prompt":{"zh":"机会已经有了，但还没安排好，先做哪一步？","en":"The opportunity remains unrealized. What directly addresses the gap?"},"options":[{"id":"p01-R3-3015b856c7","text":{"zh":"确认所需工具和实际开始时间。","en":"Secure needed tools and a real start time."},"feedback":{"zh":"这次缺的是设备和时间；光说“我一定行”，不会让设备和时间自动出现。","en":"The gap concerns preparation, not strength of belief."}},{"id":"p01-R3-df8babc1d2","text":{"zh":"只要求自己相信结果一定会来。","en":"Merely believe the result must arrive."},"feedback":{"zh":"这次缺的是设备和时间；光说“我一定行”，不会让设备和时间自动出现。","en":"The gap concerns preparation, not strength of belief."}}],"correct":"p01-R3-3015b856c7"}}},"revisit":{"id":"p01-V1","prompt":{"zh":"朋友愿意提供练习场地，按照星币王牌的提醒，先做什么？","en":"A friend offers practice space. Apply the theme."},"options":[{"id":"p01-V1-1e05421ac3","text":{"zh":"认为有人提供场地就保证获奖。","en":"Assume access guarantees an award."},"feedback":{"zh":"有场地可用，让计划有了开始的条件；能做到什么程度，还要看后续怎么做。","en":"Conditions support beginning without guaranteeing outcomes."}},{"id":"p01-V1-abee0af9fe","text":{"zh":"约定可用时间，实际开始练习。","en":"Agree on access times and begin practicing."},"feedback":{"zh":"有场地可用，让计划有了开始的条件；能做到什么程度，还要看后续怎么做。","en":"Conditions support beginning without guaranteeing outcomes."}}],"correct":"p01-V1-abee0af9fe"},"summary":{"zh":"星币王牌表示一个值得着手的机会：你已经有了一些资源、时间或条件，接下来还要动手去做，才可能有成果。它不是收到财富的保证。","en":"The Ace of Pentacles is an opportunity that can be cultivated in practice. Resources, time, or conditions offer a starting point, but development still requires investment; wealth is not guaranteed."},"cards":["p01"]},{"id":"p02","kind":"card","level":"I","title":{"zh":"星币二","en":"Two of Pentacles"},"teachings":[{"zh":"星币二表示同时照顾几件事情，随情况调整时间、精力和资源的安排。平衡会随条件变化，必要时需要取舍，而不是永远两全。","en":"The Two of Pentacles manages time, energy, and resources across practical demands. Balance changes with conditions and can require tradeoffs, not permanent success at everything."},{"zh":"人物手持两枚相连的星币，远处船随波起伏。这个画面帮助我们记住：事情会变化，安排也需要跟着调整。","en":"A figure holds two linked pentacles as distant ships rise and fall with waves. Coordination and changing conditions support remembering dynamic balance."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关。数字二让我们留意两边的需求；这张牌表现的是怎样安排几件实际的事。可以记成：兼顾几件事、灵活调整、必要时取舍。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns practical arrangements; two suggests coordination between demands. Helpers: coordination, flexibility, tradeoffs."}],"application":{"zh":"小方同时有兼职和考试，时间不能增加。建议位调整排班与复习份量，明确先后，而不是把两个满负荷计划直接叠加。","en":"Fang has work and exams without extra hours. Advice adjusts shifts and study load and sets priorities rather than stacking two full schedules."},"reversal":{"zh":"小方接下更多班次后，连续漏交作业。这个例子里，星币二逆位表示任务已经排得太满，需要减少一部分、重新安排；不能简单归咎于他不够努力。","en":"Fang takes more shifts and misses assignments. Here reversal indicates overload requiring reduction or rescheduling, not a lack of effort."},"visual":{"zh":"人物手持两枚相连的星币，远处船随波起伏。这个画面帮助我们记住：事情会变化，安排也需要跟着调整。","en":"A figure holds two linked pentacles as distant ships rise and fall with waves. Coordination and changing conditions support remembering dynamic balance."},"questions":{"Q1":{"id":"p02-Q1","prompt":{"zh":"星币二说要兼顾几件事，还可以减少任务吗？","en":"Does dynamic balance allow tradeoffs?"},"options":[{"id":"p02-Q1-5133ac691d","text":{"zh":"不可以，必须永远兼顾全部。","en":"No; everything must always be maintained."},"feedback":{"zh":"每件事都会花时间和精力；安排不过来时，就需要调整先后或减少任务。","en":"Coordination includes recognizing limited time and energy."}},{"id":"p02-Q1-f082dac359","text":{"zh":"可以，情况变了，就需要重新安排。","en":"Yes; changing conditions require reallocation."},"feedback":{"zh":"每件事都会花时间和精力；安排不过来时，就需要调整先后或减少任务。","en":"Coordination includes recognizing limited time and energy."}}],"correct":"p02-Q1-f082dac359","support":"R1"},"Q2":{"id":"p02-Q2","prompt":{"zh":"兼职班次增加，考试也临近了，怎样安排？","en":"Work and exam demands rise. What fits?"},"options":[{"id":"p02-Q2-f79d6662c2","text":{"zh":"重新分配排班和复习时间。","en":"Reallocate shifts and study time."},"feedback":{"zh":"时间没有增加，必须调整投入。","en":"Time has not expanded; allocation must change."}},{"id":"p02-Q2-21f855302d","text":{"zh":"把两个满负荷计划原样相加。","en":"Add both full schedules unchanged."},"feedback":{"zh":"时间没有增加，必须调整投入。","en":"Time has not expanded; allocation must change."}}],"correct":"p02-Q2-f79d6662c2","support":"R2"},"Q3":{"id":"p02-Q3","prompt":{"zh":"接下更多班次后，连续漏交作业，逆位提示什么？","en":"More shifts lead to missed work. Reversal?"},"options":[{"id":"p02-Q3-c6cc508d74","text":{"zh":"只要更用力，时间就会自动增加。","en":"More effort automatically creates more time."},"feedback":{"zh":"一天的时间有限，喊“我都能做到”不会多出几个小时；需要重新安排任务。","en":"Practical capacity cannot disappear through slogans."}},{"id":"p02-Q3-f45616ceea","text":{"zh":"事情排得太多，需要减少一些或重新安排。","en":"Demand exceeds capacity; reduce or reschedule."},"feedback":{"zh":"一天的时间有限，喊“我都能做到”不会多出几个小时；需要重新安排任务。","en":"Practical capacity cannot disappear through slogans."}}],"correct":"p02-Q3-f45616ceea","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"每件事都会花时间和精力；安排不过来时，就需要调整先后或减少任务。","en":"Coordination includes recognizing limited time and energy."},{"zh":"即使你擅长同时做几件事，每件事也会花时间和精力，不能无限加任务。","en":"Every task still uses limited resources."}],"question":{"id":"p02-R1","prompt":{"zh":"“灵活”为什么不等于全部答应？","en":"Why is flexibility not saying yes to everything?"},"options":[{"id":"p02-R1-42eb4c4c6f","text":{"zh":"灵活安排，也包括分清先后、拒绝做不完的任务。","en":"It includes priorities and declining excess."},"feedback":{"zh":"即使你擅长同时做几件事，每件事也会花时间和精力，不能无限加任务。","en":"Every task still uses limited resources."}},{"id":"p02-R1-40470ad1d3","text":{"zh":"灵活意味着所有任务都无需时间。","en":"It means tasks require no time."},"feedback":{"zh":"即使你擅长同时做几件事，每件事也会花时间和精力，不能无限加任务。","en":"Every task still uses limited resources."}}],"correct":"p02-R1-42eb4c4c6f"}},"R2":{"teach":[{"zh":"时间没有增加，必须调整投入。","en":"Time has not expanded; allocation must change."},{"zh":"课程与家务时间冲突，就要改时间、分工或先后顺序；只说都重要，冲突仍然存在。","en":"Coordination requires real scheduling changes."}],"question":{"id":"p02-R2","prompt":{"zh":"家务和课程冲突，怎样协调？","en":"Chores and a class conflict. Coordinate how?"},"options":[{"id":"p02-R2-26ee70c179","text":{"zh":"假定同时开始就能同时完成。","en":"Assume starting both means finishing both."},"feedback":{"zh":"课程与家务时间冲突，就要改时间、分工或先后顺序；只说都重要，冲突仍然存在。","en":"Coordination requires real scheduling changes."}},{"id":"p02-R2-0acda53aab","text":{"zh":"调整时间或分工，保留必要任务。","en":"Change timing or sharing and preserve essentials."},"feedback":{"zh":"课程与家务时间冲突，就要改时间、分工或先后顺序；只说都重要，冲突仍然存在。","en":"Coordination requires real scheduling changes."}}],"correct":"p02-R2-0acda53aab"}},"R3":{"teach":[{"zh":"小方接下更多班次后，连续漏交作业。这个例子里，星币二逆位表示任务已经排得太满，需要减少一部分、重新安排；不能简单归咎于他不够努力。","en":"Fang takes more shifts and misses assignments. Here reversal indicates overload requiring reduction or rescheduling, not a lack of effort."},{"zh":"时间不够时，可以减少一项任务，把重要的事安排好；这也是调整，并不是失败。","en":"Reallocation under limited time may require reduction."}],"question":{"id":"p02-R3","prompt":{"zh":"任务超载后先减少一项，是否违背协调？","en":"Does dropping one task violate coordination?"},"options":[{"id":"p02-R3-a4d8c8bedc","text":{"zh":"违背，协调永远不许减少任何任务。","en":"Yes; coordination forbids reducing any task."},"feedback":{"zh":"时间不够时，可以减少一项任务，把重要的事安排好；这也是调整，并不是失败。","en":"Reallocation under limited time may require reduction."}},{"id":"p02-R3-e8bfa50eb5","text":{"zh":"不违背，少做一件，可能才有时间把重要的事做好。","en":"No; tradeoffs can restore a workable balance."},"feedback":{"zh":"时间不够时，可以减少一项任务，把重要的事安排好；这也是调整，并不是失败。","en":"Reallocation under limited time may require reduction."}}],"correct":"p02-R3-e8bfa50eb5"}}},"revisit":{"id":"p02-V1","prompt":{"zh":"新增志愿活动占用了周末，星币二提醒我们怎样安排？","en":"Volunteering uses weekend time. Apply the theme."},"options":[{"id":"p02-V1-552e0a7384","text":{"zh":"检查原安排，决定哪些要减少。","en":"Review commitments and decide what to reduce."},"feedback":{"zh":"多了一项志愿活动，就要重新看看时间够不够，再调整原来的安排。","en":"New demands require rebalancing."}},{"id":"p02-V1-89a5e99518","text":{"zh":"不检查时间，承诺所有事情照旧。","en":"Promise everything unchanged without checking."},"feedback":{"zh":"多了一项志愿活动，就要重新看看时间够不够，再调整原来的安排。","en":"New demands require rebalancing."}}],"correct":"p02-V1-552e0a7384"},"summary":{"zh":"星币二表示同时照顾几件事情，随情况调整时间、精力和资源的安排。平衡会随条件变化，必要时需要取舍，而不是永远两全。","en":"The Two of Pentacles manages time, energy, and resources across practical demands. Balance changes with conditions and can require tradeoffs, not permanent success at everything."},"cards":["p02"]},{"id":"p03","kind":"card","level":"I","title":{"zh":"星币三","en":"Three of Pentacles"},"teachings":[{"zh":"星币三强调把不同技能组织起来，依照共同标准完成实际工作。合作不是人多就自动发生，需要分工、交流和尊重能力。","en":"The Three of Pentacles combines different skills under shared standards to accomplish work. Collaboration needs roles, communication, and respect for competence, not just more people."},{"zh":"工匠与两人围绕建筑交流，其中一人拿着图纸。有人动手做，有人拿图纸讨论，帮助我们记住：运用各自的技能，一起把工作做好。","en":"A craftsperson consults two others, one holding plans. Tools, plans, and distinct roles support craftsmanship and collaboration."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关。数字三可以帮助记住一起做事，但不是三个人在场就一定合作得好；还要像画中那样沟通、配合。可以记成：专业技能、合作、说好要求。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns practical results; three can aid remembering joint work without guaranteeing any trio cooperates well. Helpers: skill, collaboration, shared standards."}],"application":{"zh":"小组做海报，有人写文案、有人设计。建议位先约定读者、尺寸与交付标准，再分工并互相检查，避免做完后才发现尺寸不对、内容接不上。","en":"A poster team has writers and designers. Advice establishes audience, size, and delivery standards before dividing work and reviewing compatibility."},"reversal":{"zh":"小组成员各按不同尺寸完成自己的部分，最后拼不在一起。这个例子里，星币三逆位表示合作的要求没说清，需要重新约定尺寸、分工和交付要求，不表示所有人都没能力。","en":"Everyone delivers different sizes that cannot fit together. Here reversal means misaligned standards and roles, not universal incompetence."},"visual":{"zh":"工匠与两人围绕建筑交流，其中一人拿着图纸。有人动手做，有人拿图纸讨论，帮助我们记住：运用各自的技能，一起把工作做好。","en":"A craftsperson consults two others, one holding plans. Tools, plans, and distinct roles support craftsmanship and collaboration."},"questions":{"Q1":{"id":"p03-Q1","prompt":{"zh":"合作怎样形成？","en":"How does collaboration work here?"},"options":[{"id":"p03-Q1-2a18dcaeff","text":{"zh":"大家发挥各自的技能，并按事先说好的要求一起完成工作。","en":"Different skills coordinate around shared standards."},"feedback":{"zh":"大家要知道在一起做什么、各自负责什么，遇到问题也要交流；不是人聚在一起就算合作。","en":"Coordination needs common goals and communication."}},{"id":"p03-Q1-c833ed7e41","text":{"zh":"只要多人在场就自动高效。","en":"Several people together automatically work well."},"feedback":{"zh":"大家要知道在一起做什么、各自负责什么，遇到问题也要交流；不是人聚在一起就算合作。","en":"Coordination needs common goals and communication."}}],"correct":"p03-Q1-2a18dcaeff","support":"R1"},"Q2":{"id":"p03-Q2","prompt":{"zh":"写作与设计协作做海报，先明确什么？","en":"Writers and designers make a poster. Clarify what first?"},"options":[{"id":"p03-Q2-57f612d9f3","text":{"zh":"只数人数，不讨论要求。","en":"Count people without discussing requirements."},"feedback":{"zh":"写文案和做设计的人先说好尺寸、内容和交付要求，做出来的东西才能用在同一张海报上。","en":"Shared requirements allow separate work to combine."}},{"id":"p03-Q2-8bf88d4af5","text":{"zh":"读者、尺寸与交付标准。","en":"Audience, dimensions, and delivery standards."},"feedback":{"zh":"写文案和做设计的人先说好尺寸、内容和交付要求，做出来的东西才能用在同一张海报上。","en":"Shared requirements allow separate work to combine."}}],"correct":"p03-Q2-8bf88d4af5","support":"R2"},"Q3":{"id":"p03-Q3","prompt":{"zh":"作品尺寸不一致，逆位提示什么？","en":"Delivered pieces differ in size. Reversal?"},"options":[{"id":"p03-Q3-4d5e3e5819","text":{"zh":"重新说清尺寸、内容和交付要求。","en":"Agree on dimensions, content, and delivery requirements again."},"feedback":{"zh":"每个人都会做自己的部分，不代表彼此的要求已经说清；这次需要先把要求统一。","en":"Technical skill and coordination standards differ."}},{"id":"p03-Q3-c6f217ecf4","text":{"zh":"必然是所有成员都没有技能。","en":"Every member must lack skill."},"feedback":{"zh":"每个人都会做自己的部分，不代表彼此的要求已经说清；这次需要先把要求统一。","en":"Technical skill and coordination standards differ."}}],"correct":"p03-Q3-4d5e3e5819","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"大家要知道在一起做什么、各自负责什么，遇到问题也要交流；不是人聚在一起就算合作。","en":"Coordination needs common goals and communication."},{"zh":"人多不一定做得好。大家要先说清怎么配合，才能把各自的工作接起来。","en":"The problem is coordination, not headcount."}],"question":{"id":"p03-R1","prompt":{"zh":"各自做得好却拼不起来，缺了什么？","en":"Good individual work does not fit together. What is missing?"},"options":[{"id":"p03-R1-58fd5e8327","text":{"zh":"只要再加人就一定解决。","en":"More people will necessarily solve it."},"feedback":{"zh":"人多不一定做得好。大家要先说清怎么配合，才能把各自的工作接起来。","en":"The problem is coordination, not headcount."}},{"id":"p03-R1-ad9b914696","text":{"zh":"缺少事先说好的要求，以及交接时的检查。","en":"Shared agreements and integration checks."},"feedback":{"zh":"人多不一定做得好。大家要先说清怎么配合，才能把各自的工作接起来。","en":"The problem is coordination, not headcount."}}],"correct":"p03-R1-ad9b914696"}},"R2":{"teach":[{"zh":"写文案和做设计的人先说好尺寸、内容和交付要求，做出来的东西才能用在同一张海报上。","en":"Shared requirements allow separate work to combine."},{"zh":"表演和灯光先说好提示信号、进场时间，各自的技能才能配合起来。","en":"Shared standards turn expertise into collaboration."}],"question":{"id":"p03-R2","prompt":{"zh":"社团准备演出，怎样运用星币三讲的合作？","en":"A club prepares a show. What fits?"},"options":[{"id":"p03-R2-86b2e1a088","text":{"zh":"表演与灯光先确认同一套流程。","en":"Performers and lighting agree on one cue plan."},"feedback":{"zh":"表演和灯光先说好提示信号、进场时间，各自的技能才能配合起来。","en":"Shared standards turn expertise into collaboration."}},{"id":"p03-R2-14bf83d207","text":{"zh":"各方完全不沟通，等上台再碰运气。","en":"Keep teams separate and improvise compatibility on stage."},"feedback":{"zh":"表演和灯光先说好提示信号、进场时间，各自的技能才能配合起来。","en":"Shared standards turn expertise into collaboration."}}],"correct":"p03-R2-86b2e1a088"}},"R3":{"teach":[{"zh":"小组成员各按不同尺寸完成自己的部分，最后拼不在一起。这个例子里，星币三逆位表示合作的要求没说清，需要重新约定尺寸、分工和交付要求，不表示所有人都没能力。","en":"Everyone delivers different sizes that cannot fit together. Here reversal means misaligned standards and roles, not universal incompetence."},{"zh":"尺寸不一致，是因为要求没说清；先统一尺寸并修改作品，比再增加一个人更有用。","en":"The issue is missing standards, not headcount."}],"question":{"id":"p03-R3","prompt":{"zh":"尺寸不一致的作品，怎样修复协作？","en":"Pieces use different sizes. Repair cooperation how?"},"options":[{"id":"p03-R3-a79ee9a017","text":{"zh":"确认统一尺寸，再分工调整。","en":"Agree on dimensions and assign corrections."},"feedback":{"zh":"尺寸不一致，是因为要求没说清；先统一尺寸并修改作品，比再增加一个人更有用。","en":"The issue is missing standards, not headcount."}},{"id":"p03-R3-38185442ef","text":{"zh":"先增加成员人数，不讨论尺寸。","en":"Add members without discussing dimensions."},"feedback":{"zh":"尺寸不一致，是因为要求没说清；先统一尺寸并修改作品，比再增加一个人更有用。","en":"The issue is missing standards, not headcount."}}],"correct":"p03-R3-a79ee9a017"}}},"revisit":{"id":"p03-V1","prompt":{"zh":"老师评作品，怎样利用专业反馈？","en":"A teacher reviews work. How use the feedback?"},"options":[{"id":"p03-V1-0ef86af410","text":{"zh":"认为请人看过就无需再修改。","en":"Assume review removes the need to revise."},"feedback":{"zh":"老师已经指出哪里需要修改，把建议用到作品上，才让这次讨论真正帮助了合作。","en":"Collaboration includes using feedback, not mere involvement."}},{"id":"p03-V1-3d71a5aeb4","text":{"zh":"按照大家说好的要求，讨论作品哪里要改。","en":"Discuss specific improvements against agreed criteria."},"feedback":{"zh":"老师已经指出哪里需要修改，把建议用到作品上，才让这次讨论真正帮助了合作。","en":"Collaboration includes using feedback, not mere involvement."}}],"correct":"p03-V1-3d71a5aeb4"},"summary":{"zh":"星币三强调把不同技能组织起来，依照共同标准完成实际工作。合作不是人多就自动发生，需要分工、交流和尊重能力。","en":"The Three of Pentacles combines different skills under shared standards to accomplish work. Collaboration needs roles, communication, and respect for competence, not just more people."},"cards":["p03"]},{"id":"p04","kind":"card","level":"I","title":{"zh":"星币四","en":"Four of Pentacles"},"teachings":[{"zh":"星币四通过抓紧已有资源寻求稳定和安全。保留必要储备有价值，但抓得太紧，也会让资源没法用在需要的地方；要看保留它是在保护生活，还是妨碍必要的事情。","en":"The Four of Pentacles seeks security by holding resources tightly. Reserves can help, but excessive holding restricts movement; examine the degree and purpose of control."},{"zh":"人物抱币、脚踩币、头顶币。多处抓紧的姿态帮助记住守住资源，不把所有节约都判成吝啬。","en":"A figure hugs a pentacle, pins two underfoot, and wears one overhead. The repeated holding supports remembering control without labeling all saving as stinginess."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关；数字四可以帮助记住稳定。结合人物紧抓星币的动作，可以记成：守住已有的东西、安全感、控制。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns resources; four suggests stability that can protect or constrain. Helpers: preservation, security, control."}],"application":{"zh":"小程怕花钱，把必要课程材料也拒绝购买。放在建议位，可以先留好生活需要的钱，再从预算里安排必要的材料费用；不需要一下把钱全花光。","en":"Cheng fears spending and refuses essential course materials. Advice distinguishes reserves from reasonable use, allowing purposeful spending while preserving a minimum."},"reversal":{"zh":"小程开始设定可用预算，不再把每一笔支出都当成危险。这个例子里，星币四逆位表示开始放松过度的控制，愿意合理使用资源；不表示任何花费都合理。","en":"Cheng sets a usable budget instead of treating every expense as danger. Reversal here means loosening excessive control, not approving every purchase."},"visual":{"zh":"人物抱币、脚踩币、头顶币。多处抓紧的姿态帮助记住守住资源，不把所有节约都判成吝啬。","en":"A figure hugs a pentacle, pins two underfoot, and wears one overhead. The repeated holding supports remembering control without labeling all saving as stinginess."},"questions":{"Q1":{"id":"p04-Q1","prompt":{"zh":"抓紧资源为什么需要看程度？","en":"Why examine how tightly resources are held?"},"options":[{"id":"p04-Q1-fce49a1a50","text":{"zh":"任何保留资源都必然错误。","en":"Any retention of resources is wrong."},"feedback":{"zh":"保留资源可以带来安全感；但抓得太紧，也可能让你不敢做必要的事。","en":"The lesson recognizes both protection and restriction."}},{"id":"p04-Q1-27801a2ddd","text":{"zh":"留点储备能让人安心，但抓得太紧，也会妨碍必要的使用。","en":"Reserves protect; excessive control restricts use."},"feedback":{"zh":"保留资源可以带来安全感；但抓得太紧，也可能让你不敢做必要的事。","en":"The lesson recognizes both protection and restriction."}}],"correct":"p04-Q1-27801a2ddd","support":"R1"},"Q2":{"id":"p04-Q2","prompt":{"zh":"连必要材料也不买，建议是什么？","en":"Essential materials are refused. What fits?"},"options":[{"id":"p04-Q2-0bb45fc846","text":{"zh":"先留好生活需要的钱，再安排付得起的材料费用。","en":"Separate minimum reserves from affordable essentials."},"feedback":{"zh":"可以在预算内支付必要费用，不需要一下把存款全花掉。","en":"Adjusting control does not require the opposite extreme."}},{"id":"p04-Q2-c757bcc2c2","text":{"zh":"为了不受限制，立刻花完全部储备。","en":"Spend all reserves immediately to feel free."},"feedback":{"zh":"可以在预算内支付必要费用，不需要一下把存款全花掉。","en":"Adjusting control does not require the opposite extreme."}}],"correct":"p04-Q2-0bb45fc846","support":"R2"},"Q3":{"id":"p04-Q3","prompt":{"zh":"开始用预算允许合理支出，逆位指什么？","en":"A budget allows reasonable spending. Reversal?"},"options":[{"id":"p04-Q3-b7b7455ea2","text":{"zh":"所有消费因此无需判断。","en":"Every purchase now needs no judgment."},"feedback":{"zh":"愿意花必要的钱，不表示不看预算；先留好生活费用，再决定怎么使用。","en":"Less control still requires practical judgment."}},{"id":"p04-Q3-7a0200073e","text":{"zh":"开始不再抓得那么紧，愿意合理花费了。","en":"Excessive holding is loosening."},"feedback":{"zh":"愿意花必要的钱，不表示不看预算；先留好生活费用，再决定怎么使用。","en":"Less control still requires practical judgment."}}],"correct":"p04-Q3-7a0200073e","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"保留资源可以带来安全感；但抓得太紧，也可能让你不敢做必要的事。","en":"The lesson recognizes both protection and restriction."},{"zh":"留好必要储备后，也可以使用一部分资源；不必把每一次使用都当成危险。","en":"Security can coexist with measured use."}],"question":{"id":"p04-R1","prompt":{"zh":"“留好储备”与“什么都不能用”相同吗？","en":"Are keeping reserves and using nothing the same?"},"options":[{"id":"p04-R1-0dc89cb88e","text":{"zh":"不同，留好储备后，也可以把一部分用在需要的地方。","en":"No; resources beyond reserves can have sensible uses."},"feedback":{"zh":"留好必要储备后，也可以使用一部分资源；不必把每一次使用都当成危险。","en":"Security can coexist with measured use."}},{"id":"p04-R1-a37f2b6bad","text":{"zh":"相同，想安心就必须一分钱都不花。","en":"Yes; stability requires no movement."},"feedback":{"zh":"留好必要储备后，也可以使用一部分资源；不必把每一次使用都当成危险。","en":"Security can coexist with measured use."}}],"correct":"p04-R1-0dc89cb88e"}},"R2":{"teach":[{"zh":"可以在预算内支付必要费用，不需要一下把存款全花掉。","en":"Adjusting control does not require the opposite extreme."},{"zh":"借用时约好归还时间和维护方式，既能保护器材，也不必拒绝所有借用。","en":"Rules can protect resources without blocking all use."}],"question":{"id":"p04-R2","prompt":{"zh":"团队囤着设备不许合理借用，怎样调整？","en":"Equipment is hoarded despite reasonable needs. What fits?"},"options":[{"id":"p04-R2-38c44b8bbd","text":{"zh":"为保持完整而永久禁止使用。","en":"Permanently ban use to preserve everything."},"feedback":{"zh":"借用时约好归还时间和维护方式，既能保护器材，也不必拒绝所有借用。","en":"Rules can protect resources without blocking all use."}},{"id":"p04-R2-8c799bc4c2","text":{"zh":"建立借用与归还规则，让资源可用。","en":"Set borrowing and return rules so resources can be used."},"feedback":{"zh":"借用时约好归还时间和维护方式，既能保护器材，也不必拒绝所有借用。","en":"Rules can protect resources without blocking all use."}}],"correct":"p04-R2-8c799bc4c2"}},"R3":{"teach":[{"zh":"小程开始设定可用预算，不再把每一笔支出都当成危险。这个例子里，星币四逆位表示开始放松过度的控制，愿意合理使用资源；不表示任何花费都合理。","en":"Cheng sets a usable budget instead of treating every expense as danger. Reversal here means loosening excessive control, not approving every purchase."},{"zh":"先留好生活费，再支付必要的学习费用；放松一点不等于放弃所有保障。","en":"Adjusting control need not abandon practical security."}],"question":{"id":"p04-R3","prompt":{"zh":"控制松动后，怎样避免走到另一极端？","en":"After loosening control, avoid the opposite extreme how?"},"options":[{"id":"p04-R3-65907a1cb4","text":{"zh":"把所有保留都取消，以证明开放。","en":"Eliminate all reserves to prove openness."},"feedback":{"zh":"先留好生活费，再支付必要的学习费用；放松一点不等于放弃所有保障。","en":"Adjusting control need not abandon practical security."}},{"id":"p04-R3-99bac16b68","text":{"zh":"先留好生活费，再看哪些学习费用确实需要支付。","en":"Preserve essentials and use resources purposefully."},"feedback":{"zh":"先留好生活费，再支付必要的学习费用；放松一点不等于放弃所有保障。","en":"Adjusting control need not abandon practical security."}}],"correct":"p04-R3-99bac16b68"}}},"revisit":{"id":"p04-V1","prompt":{"zh":"时间全部排满、不留余地，星币四提醒我们检查什么？","en":"Every minute is locked down with no flexibility. Apply."},"options":[{"id":"p04-V1-ef1a7aa6f6","text":{"zh":"保留关键安排并留出可调整部分。","en":"Keep essentials and allow some adjustment."},"feedback":{"zh":"如果日程定得太死，连必要调整都做不了，就要看看这套安排是否还在帮助你。","en":"Holding tightly must be judged by practical effects."}},{"id":"p04-V1-4ddd730abd","text":{"zh":"把控制越紧直接等同于越有效。","en":"Equate tighter control with greater effectiveness."},"feedback":{"zh":"如果日程定得太死，连必要调整都做不了，就要看看这套安排是否还在帮助你。","en":"Holding tightly must be judged by practical effects."}}],"correct":"p04-V1-ef1a7aa6f6"},"summary":{"zh":"星币四通过抓紧已有资源寻求稳定和安全。保留必要储备有价值，但抓得太紧，也会让资源没法用在需要的地方；要看保留它是在保护生活，还是妨碍必要的事情。","en":"The Four of Pentacles seeks security by holding resources tightly. Reserves can help, but excessive holding restricts movement; examine the degree and purpose of control."},"cards":["p04"]},{"id":"p05","kind":"card","level":"I","title":{"zh":"星币五","en":"Five of Pentacles"},"teachings":[{"zh":"星币五关注现实资源不足或缺少支持的困难。先看见眼前缺少什么，再寻找能够获得的帮助，不把困境归结成个人不够努力，也不预测必然破产。","en":"The Five of Pentacles concerns material hardship or insufficient support. Identify needs and available help without blaming effort or predicting inevitable ruin."},{"zh":"雪地中的两人经过明亮的窗，困难与支持之间存在距离。窗让我们想到寻找支持，但画面不保证门一定为他们开放。","en":"Two people pass a lit window in snow. The distance suggests looking for support without proving access is guaranteed."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关；数字五可以帮助记住遇到困难、原来的稳定被打乱。这张牌可以记成：资源不足、生活困难、缺少支持。不能凭它诊断疾病。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns material conditions; five suggests disruption without diagnosing health. Helpers: scarcity, hardship, insufficient support."}],"application":{"zh":"小唐缺教材，跟不上课程。建议位先确认最急需的材料，再查询借阅或课程提供的支持；“只劝自己积极一点”不能代替教材。","en":"Tang lacks course materials and falls behind. Advice identifies urgent needs and checks borrowing or course support; optimism cannot replace the materials."},"reversal":{"zh":"小唐借到了教材，也得到辅导，眼前的学习条件改善了。这个例子里，星币五逆位表示困难逐步得到缓解，不表示此后不会再缺少资源或支持。","en":"Tang obtains materials and tutoring. Here reversal suggests improving support and circumstances, not the absence of every future constraint."},"visual":{"zh":"雪地中的两人经过明亮的窗，困难与支持之间存在距离。窗让我们想到寻找支持，但画面不保证门一定为他们开放。","en":"Two people pass a lit window in snow. The distance suggests looking for support without proving access is guaranteed."},"questions":{"Q1":{"id":"p05-Q1","prompt":{"zh":"星币五先让我们看见什么问题？","en":"What does this lesson first examine?"},"options":[{"id":"p05-Q1-ee0e95b470","text":{"zh":"眼前缺少什么，以及需要哪些帮助。","en":"Practical needs and gaps in support."},"feedback":{"zh":"缺少教材，需要解决教材从哪里来；不能因此认定这个人不努力。","en":"Resource gaps need practical responses, not moral blame."}},{"id":"p05-Q1-fbbaeca29c","text":{"zh":"只要困难就认定本人懒惰。","en":"Treat hardship as proof of laziness."},"feedback":{"zh":"缺少教材，需要解决教材从哪里来；不能因此认定这个人不努力。","en":"Resource gaps need practical responses, not moral blame."}}],"correct":"p05-Q1-ee0e95b470","support":"R1"},"Q2":{"id":"p05-Q2","prompt":{"zh":"缺教材影响学习，先怎样？","en":"Missing materials disrupt learning. First?"},"options":[{"id":"p05-Q2-fe9ffe5dd8","text":{"zh":"只要求自己积极想象，不找材料。","en":"Only imagine positively and seek no materials."},"feedback":{"zh":"这次缺的是教材，借阅、申请援助等办法才能直接解决；只鼓励自己还不够。","en":"The practical gap requires actual resources."}},{"id":"p05-Q2-62dcc5ace6","text":{"zh":"查清缺哪些教材，再找可以借阅的地方。","en":"Identify missing materials and borrowing support."},"feedback":{"zh":"这次缺的是教材，借阅、申请援助等办法才能直接解决；只鼓励自己还不够。","en":"The practical gap requires actual resources."}}],"correct":"p05-Q2-62dcc5ace6","support":"R2"},"Q3":{"id":"p05-Q3","prompt":{"zh":"已借到材料并获得辅导，逆位怎么读？","en":"Materials and tutoring become available. Reversal?"},"options":[{"id":"p05-Q3-b265de77b5","text":{"zh":"支持增加，困难开始改善。","en":"Support grows and hardship begins easing."},"feedback":{"zh":"借到教材、得到辅导，让眼前的困难有了改善；并不保证以后不会再遇到困难。","en":"Improved conditions are not a permanent guarantee."}},{"id":"p05-Q3-1efcd99c82","text":{"zh":"从此所有困难永久消失。","en":"Every difficulty disappears forever."},"feedback":{"zh":"借到教材、得到辅导，让眼前的困难有了改善；并不保证以后不会再遇到困难。","en":"Improved conditions are not a permanent guarantee."}}],"correct":"p05-Q3-b265de77b5","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"缺少教材，需要解决教材从哪里来；不能因此认定这个人不努力。","en":"Resource gaps need practical responses, not moral blame."},{"zh":"一个人暂时缺钱或缺支持，需要的是帮助；这不能说明他比别人差。","en":"The theme concerns needs, not personal worth."}],"question":{"id":"p05-R1","prompt":{"zh":"看到“支持不足”，下一步应该找什么？","en":"Insufficient support: what should be identified?"},"options":[{"id":"p05-R1-6539b07f11","text":{"zh":"寻找证明自己不值得帮助的理由。","en":"Reasons why one does not deserve help."},"feedback":{"zh":"一个人暂时缺钱或缺支持，需要的是帮助；这不能说明他比别人差。","en":"The theme concerns needs, not personal worth."}},{"id":"p05-R1-cbeec81da8","text":{"zh":"具体缺什么，以及哪里可能提供。","en":"What is missing and where it may be available."},"feedback":{"zh":"一个人暂时缺钱或缺支持，需要的是帮助；这不能说明他比别人差。","en":"The theme concerns needs, not personal worth."}}],"correct":"p05-R1-cbeec81da8"}},"R2":{"teach":[{"zh":"这次缺的是教材，借阅、申请援助等办法才能直接解决；只鼓励自己还不够。","en":"The practical gap requires actual resources."},{"zh":"社团已知缺少活动场地，先查可借用的场地才有帮助；心情变好也不会自动多出场地。","en":"Missing space is a concrete condition, not an enthusiasm problem."}],"question":{"id":"p05-R2","prompt":{"zh":"社团没有场地，活动办不下去，按照星币五的提醒，先做什么？","en":"A club lacks space and stalls. Apply."},"options":[{"id":"p05-R2-cede4911f9","text":{"zh":"查询可借场地与实际使用条件。","en":"Check available spaces and access conditions."},"feedback":{"zh":"社团已知缺少活动场地，先查可借用的场地才有帮助；心情变好也不会自动多出场地。","en":"Missing space is a concrete condition, not an enthusiasm problem."}},{"id":"p05-R2-b9b4571179","text":{"zh":"只责备成员缺少热情。","en":"Blame members for insufficient enthusiasm."},"feedback":{"zh":"社团已知缺少活动场地，先查可借用的场地才有帮助；心情变好也不会自动多出场地。","en":"Missing space is a concrete condition, not an enthusiasm problem."}}],"correct":"p05-R2-cede4911f9"}},"R3":{"teach":[{"zh":"小唐借到了教材，也得到辅导，眼前的学习条件改善了。这个例子里，星币五逆位表示困难逐步得到缓解，不表示此后不会再缺少资源或支持。","en":"Tang obtains materials and tutoring. Here reversal suggests improving support and circumstances, not the absence of every future constraint."},{"zh":"得到设备或教材后，更容易继续学习，但作业和练习仍要自己完成。","en":"Support improves conditions without completing every task."}],"question":{"id":"p05-R3","prompt":{"zh":"得到支持后仍有作业要完成，怎样理解？","en":"Work remains after receiving support. Interpret."},"options":[{"id":"p05-R3-430fe2162f","text":{"zh":"有了教材和帮助，就更方便继续学习，但作业仍要自己做。","en":"Better conditions create a basis for action."},"feedback":{"zh":"得到设备或教材后，更容易继续学习，但作业和练习仍要自己完成。","en":"Support improves conditions without completing every task."}},{"id":"p05-R3-ea1221ed3d","text":{"zh":"没有自动做完就说明帮助没有价值。","en":"If work is not automatic, help has no value."},"feedback":{"zh":"得到设备或教材后，更容易继续学习，但作业和练习仍要自己完成。","en":"Support improves conditions without completing every task."}}],"correct":"p05-R3-430fe2162f"}}},"revisit":{"id":"p05-V1","prompt":{"zh":"设备损坏使作业做不了，先怎样？","en":"Broken equipment prevents work. First?"},"options":[{"id":"p05-V1-0ba1826c92","text":{"zh":"直接把困难解释为必然失败。","en":"Declare failure inevitable."},"feedback":{"zh":"先问清有没有设备可以借、有没有维修帮助，才能知道下一步有哪些办法。","en":"Available support needs checking first."}},{"id":"p05-V1-4fe11702fd","text":{"zh":"确认临时借用或替代设备。","en":"Check temporary loans or replacement access."},"feedback":{"zh":"先问清有没有设备可以借、有没有维修帮助，才能知道下一步有哪些办法。","en":"Available support needs checking first."}}],"correct":"p05-V1-4fe11702fd"},"summary":{"zh":"星币五关注现实资源不足或缺少支持的困难。先看见眼前缺少什么，再寻找能够获得的帮助，不把困境归结成个人不够努力，也不预测必然破产。","en":"The Five of Pentacles concerns material hardship or insufficient support. Identify needs and available help without blaming effort or predicting inevitable ruin."},"cards":["p05"]},{"id":"p06","kind":"card","level":"I","title":{"zh":"星币六","en":"Six of Pentacles"},"teachings":[{"zh":"星币六讨论给予、接受和资源如何分配。援助可能有用，但给予者往往掌握更多决定权，需要说清条件与双方可接受的范围。","en":"The Six of Pentacles concerns giving, receiving, and allocation. Assistance can help, but the giver often has more decision power; clarify conditions and acceptable limits."},{"zh":"一人持秤并发放钱币，两人接受帮助。一人决定把钱给谁，另两人等待接受；这个画面提醒我们，给予者和接受者手里的选择并不一样多。","en":"A person holds scales and distributes coins to two recipients. Resource flow and unequal positions together illustrate allocation power."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关。数字六可以帮助记住人与人之间的给予和接受，但公平与否还要看实际条件。这张牌可以记成：给予、接受、分配、相互帮助。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns resources; six helps remember exchange without guaranteeing fairness. Helpers: giving, receiving, allocation, reciprocity."}],"application":{"zh":"同学愿借小顾设备，但要求约定归还时间。建议位说清借用期限和责任，确认双方接受，再决定是否借；接受帮助并不意味着失去一切边界。","en":"A classmate offers Gu equipment with an agreed return date. Advice clarifies duration and responsibility so both can consent; receiving help does not erase boundaries."},"reversal":{"zh":"有人提供帮助后，又追加事先没说、接受者也难以承担的要求。这个例子里，星币六逆位表示双方付出和接受的条件不合适，需要重新讨论；接受帮助不表示必须答应所有追加要求。","en":"Help comes with excessive conditions revealed only later, making refusal difficult. Here reversal concerns unequal demands and calls for renegotiation."},"visual":{"zh":"一人持秤并发放钱币，两人接受帮助。一人决定把钱给谁，另两人等待接受；这个画面提醒我们，给予者和接受者手里的选择并不一样多。","en":"A person holds scales and distributes coins to two recipients. Resource flow and unequal positions together illustrate allocation power."},"questions":{"Q1":{"id":"p06-Q1","prompt":{"zh":"有人愿意提供帮助，就一定公平吗？","en":"Is giving automatically fair?"},"options":[{"id":"p06-Q1-334220b553","text":{"zh":"一定，提供资源的人无需解释条件。","en":"Yes; a giver need not explain conditions."},"feedback":{"zh":"有人愿意帮忙，不代表条件一定公平；还要看对方要求你付出什么、你能不能拒绝。","en":"Resource flow does not guarantee balanced power or conditions."}},{"id":"p06-Q1-0f561d6598","text":{"zh":"不一定，要看谁决定给谁、附带什么条件。","en":"Not necessarily; examine conditions and power."},"feedback":{"zh":"有人愿意帮忙，不代表条件一定公平；还要看对方要求你付出什么、你能不能拒绝。","en":"Resource flow does not guarantee balanced power or conditions."}}],"correct":"p06-Q1-0f561d6598","support":"R1"},"Q2":{"id":"p06-Q2","prompt":{"zh":"借设备时先说清什么？","en":"What should equipment borrowers clarify?"},"options":[{"id":"p06-Q2-1432332d2c","text":{"zh":"期限、责任和双方可接受的条件。","en":"Duration, responsibility, and acceptable terms."},"feedback":{"zh":"接受帮助后要遵守说好的约定，但不表示以后必须答应对方所有要求。","en":"Reciprocity needs clear terms, not unlimited obligation."}},{"id":"p06-Q2-ea96147252","text":{"zh":"默认接受帮助就必须答应所有要求。","en":"Assume receiving help requires accepting every demand."},"feedback":{"zh":"接受帮助后要遵守说好的约定，但不表示以后必须答应对方所有要求。","en":"Reciprocity needs clear terms, not unlimited obligation."}}],"correct":"p06-Q2-1432332d2c","support":"R2"},"Q3":{"id":"p06-Q3","prompt":{"zh":"援助后来附加过量要求，逆位提示什么？","en":"Excessive demands are added later. Reversal?"},"options":[{"id":"p06-Q3-2b4b4371f0","text":{"zh":"既然接受过帮助，就失去拒绝权。","en":"Receiving help removes the right to refuse."},"feedback":{"zh":"接受了帮助，也可以拒绝事先没说、自己又承担不了的要求；需要重新谈清双方的约定。","en":"Receiving resources does not mean surrendering boundaries."}},{"id":"p06-Q3-5d5c712e58","text":{"zh":"追加的要求不合适，需要重新商量。","en":"Conditions are unbalanced and need renegotiation."},"feedback":{"zh":"接受了帮助，也可以拒绝事先没说、自己又承担不了的要求；需要重新谈清双方的约定。","en":"Receiving resources does not mean surrendering boundaries."}}],"correct":"p06-Q3-5d5c712e58","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"有人愿意帮忙，不代表条件一定公平；还要看对方要求你付出什么、你能不能拒绝。","en":"Resource flow does not guarantee balanced power or conditions."},{"zh":"这份帮助是否合适，要看对方附带什么要求，以及接受者能否承担。","en":"The effect of help depends on recipients’ circumstances."}],"question":{"id":"p06-R1","prompt":{"zh":"为什么要同时看给的人和收的人？","en":"Why look at giver and recipient?"},"options":[{"id":"p06-R1-528f26d6f5","text":{"zh":"谁决定怎么分、附带什么条件，都会影响双方能不能接受或拒绝。","en":"Allocation affects both parties’ choices."},"feedback":{"zh":"这份帮助是否合适，要看对方附带什么要求，以及接受者能否承担。","en":"The effect of help depends on recipients’ circumstances."}},{"id":"p06-R1-288c70a568","text":{"zh":"只要给出东西，接受者处境就不用问。","en":"A gift makes the recipient’s situation irrelevant."},"feedback":{"zh":"这份帮助是否合适，要看对方附带什么要求，以及接受者能否承担。","en":"The effect of help depends on recipients’ circumstances."}}],"correct":"p06-R1-528f26d6f5"}},"R2":{"teach":[{"zh":"接受帮助后要遵守说好的约定，但不表示以后必须答应对方所有要求。","en":"Reciprocity needs clear terms, not unlimited obligation."},{"zh":"先说好辅导的时间、内容和双方各自承担的事情，才知道这份帮助是否合适。","en":"Clear scope protects both parties."}],"question":{"id":"p06-R2","prompt":{"zh":"学长提供辅导，怎样把合作说清？","en":"A senior offers tutoring. How clarify it?"},"options":[{"id":"p06-R2-745cee30ca","text":{"zh":"把辅导理解成以后任何请求都得答应。","en":"Treat tutoring as obligation to accept all later requests."},"feedback":{"zh":"先说好辅导的时间、内容和双方各自承担的事情，才知道这份帮助是否合适。","en":"Clear scope protects both parties."}},{"id":"p06-R2-b2a89d8e34","text":{"zh":"说好辅导的时间、内容，以及对方希望你怎样回报。","en":"Agree on time, scope, and feasible reciprocity."},"feedback":{"zh":"先说好辅导的时间、内容和双方各自承担的事情，才知道这份帮助是否合适。","en":"Clear scope protects both parties."}}],"correct":"p06-R2-b2a89d8e34"}},"R3":{"teach":[{"zh":"有人提供帮助后，又追加事先没说、接受者也难以承担的要求。这个例子里，星币六逆位表示双方付出和接受的条件不合适，需要重新讨论；接受帮助不表示必须答应所有追加要求。","en":"Help comes with excessive conditions revealed only later, making refusal difficult. Here reversal concerns unequal demands and calls for renegotiation."},{"zh":"对方后来追加的要求，如果超出了原来的约定，就应该重新讨论；接受过帮助不表示必须全部答应。","en":"Giving and receiving both need boundaries."}],"question":{"id":"p06-R3","prompt":{"zh":"后加的要求超过可承担范围，怎样处理？","en":"Added conditions exceed capacity. What next?"},"options":[{"id":"p06-R3-543aa2550e","text":{"zh":"因曾接受帮助就必须无限答应。","en":"Accept unlimited demands because help was received."},"feedback":{"zh":"对方后来追加的要求，如果超出了原来的约定，就应该重新讨论；接受过帮助不表示必须全部答应。","en":"Giving and receiving both need boundaries."}},{"id":"p06-R3-871902f71c","text":{"zh":"说清哪些要求自己做不到，再商量双方都能接受的条件。","en":"State limits and renegotiate acceptable terms."},"feedback":{"zh":"对方后来追加的要求，如果超出了原来的约定，就应该重新讨论；接受过帮助不表示必须全部答应。","en":"Giving and receiving both need boundaries."}}],"correct":"p06-R3-871902f71c"}}},"revisit":{"id":"p06-V1","prompt":{"zh":"分配公共工具时，怎样运用星币六讲的公平分配？","en":"Allocating shared tools: apply."},"options":[{"id":"p06-V1-19666a2396","text":{"zh":"说明分配标准和归还规则。","en":"Explain allocation and return rules."},"feedback":{"zh":"分配公用工具时，要说清谁可以用、按什么顺序用，不能只由掌管工具的人随意决定。","en":"The theme examines the conditions and power of allocation."}},{"id":"p06-V1-33786e8752","text":{"zh":"只看谁掌管工具就让谁任意变规则。","en":"Let whoever holds them change rules arbitrarily."},"feedback":{"zh":"分配公用工具时，要说清谁可以用、按什么顺序用，不能只由掌管工具的人随意决定。","en":"The theme examines the conditions and power of allocation."}}],"correct":"p06-V1-19666a2396"},"summary":{"zh":"星币六讨论给予、接受和资源如何分配。援助可能有用，但给予者往往掌握更多决定权，需要说清条件与双方可接受的范围。","en":"The Six of Pentacles concerns giving, receiving, and allocation. Assistance can help, but the giver often has more decision power; clarify conditions and acceptable limits."},"cards":["p06"]},{"id":"p07","kind":"card","level":"I","title":{"zh":"星币七","en":"Seven of Pentacles"},"teachings":[{"zh":"星币七是在投入一段时间后停下来，看看已经做出了什么、花了多少时间和精力，再决定接下来怎么做。耐心不等于一直照旧做；如果方法没有帮助，就需要检查和调整。","en":"The Seven of Pentacles pauses after sustained investment to assess results, costs, and direction. Patience works with evaluation, not endless commitment to ineffective effort."},{"zh":"人物靠着工具望向作物上的星币，当前动作是查看而非正在采收。可用它记住：做了一段时间后，停下来看看效果，不据此断言收获日期。","en":"A figure leans on a tool and looks at pentacles on a plant. The current action is assessing rather than harvesting, not predicting a harvest date."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关。这张牌先看人物停下来查看作物的动作，不能只用数字七推定结果。可以记成：检查效果、耐心、付出与收获。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns investment and results; seven offers a structural reminder of assessment. Helpers: evaluation, patience, return on effort."}],"application":{"zh":"小胡复习三周后，某类题仍错得多。建议位先看错题记录，判断方法哪里有效、哪里需改，再决定下一轮投入。","en":"After three weeks of study, Hu still misses one type of problem. Advice reviews errors and evaluates the method before committing to the next round."},"reversal":{"zh":"小胡已经发现方法没有效果，却因为花了很多时间而不愿调整。这个例子里，星币七逆位提醒我们：没有效果的做法还在耗时间，应该重新检查。已经花了多少时间，不能单独成为继续照旧做的理由。","en":"Hu keeps an ineffective method solely because much time was spent. Here reversal concerns ongoing unproductive investment, calling for reassessment rather than sunk-cost justification."},"visual":{"zh":"人物靠着工具望向作物上的星币，当前动作是查看而非正在采收。可用它记住：做了一段时间后，停下来看看效果，不据此断言收获日期。","en":"A figure leans on a tool and looks at pentacles on a plant. The current action is assessing rather than harvesting, not predicting a harvest date."},"questions":{"Q1":{"id":"p07-Q1","prompt":{"zh":"按照星币七的提醒，怎样做才算有耐心地坚持？","en":"How do patience and evaluation relate?"},"options":[{"id":"p07-Q1-9d721c7990","text":{"zh":"坚持做，也定期看看方法有没有效果。","en":"Invest patiently and periodically check results."},"feedback":{"zh":"先看看方法有没有帮助，再决定继续还是调整；这不是轻易放弃，而是让后面的努力更有方向。","en":"Review informs continuation rather than automatic quitting."}},{"id":"p07-Q1-ed92d1cb4a","text":{"zh":"耐心就是永远不能改变方法。","en":"Patience means never changing the method."},"feedback":{"zh":"先看看方法有没有帮助，再决定继续还是调整；这不是轻易放弃，而是让后面的努力更有方向。","en":"Review informs continuation rather than automatic quitting."}}],"correct":"p07-Q1-9d721c7990","support":"R1"},"Q2":{"id":"p07-Q2","prompt":{"zh":"复习三周仍反复错一类题，先怎样？","en":"The same errors persist after three weeks. First?"},"options":[{"id":"p07-Q2-7161c1aaea","text":{"zh":"只把原来的时长再加倍，不查看原因。","en":"Double the hours without looking at causes."},"feedback":{"zh":"已经学了三周却总错在同一处，就先检查错题和练习方法，再决定下一步怎么练。","en":"The example evaluates investment before extending it."}},{"id":"p07-Q2-cbfa218761","text":{"zh":"检查错题和方法效果。","en":"Review errors and method effectiveness."},"feedback":{"zh":"已经学了三周却总错在同一处，就先检查错题和练习方法，再决定下一步怎么练。","en":"The example evaluates investment before extending it."}}],"correct":"p07-Q2-cbfa218761","support":"R2"},"Q3":{"id":"p07-Q3","prompt":{"zh":"因已花很多时间就拒绝改法，逆位提示什么？","en":"Past time spent becomes the only reason to continue. Reversal?"},"options":[{"id":"p07-Q3-50cd0aa9d6","text":{"zh":"重新看看这套方法有没有帮助，值不值得继续花时间。","en":"Reassess whether future investment is worthwhile."},"feedback":{"zh":"已经花过的时间收不回来，但接下来要不要继续，还得看这套方法有没有帮助。","en":"Past cost cannot replace assessing future effectiveness."}},{"id":"p07-Q3-a18cb90e1a","text":{"zh":"过去花得越多，未来越不准调整。","en":"More past effort forbids future adjustments."},"feedback":{"zh":"已经花过的时间收不回来，但接下来要不要继续，还得看这套方法有没有帮助。","en":"Past cost cannot replace assessing future effectiveness."}}],"correct":"p07-Q3-50cd0aa9d6","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"先看看方法有没有帮助，再决定继续还是调整；这不是轻易放弃，而是让后面的努力更有方向。","en":"Review informs continuation rather than automatic quitting."},{"zh":"停下来检查方法，不等于放弃；找到问题后，反而更知道该怎样继续。","en":"Evaluation can support more purposeful persistence."}],"question":{"id":"p07-R1","prompt":{"zh":"暂停查看成果，是不是一定放弃？","en":"Does reviewing results necessarily mean quitting?"},"options":[{"id":"p07-R1-99d0d2b8f4","text":{"zh":"是，只要停下检查就失去耐心。","en":"Yes; any review proves impatience."},"feedback":{"zh":"停下来检查方法，不等于放弃；找到问题后，反而更知道该怎样继续。","en":"Evaluation can support more purposeful persistence."}},{"id":"p07-R1-07240f51e4","text":{"zh":"不是，是为了看看哪些做法可以继续、哪些需要改。","en":"No; it informs what to keep or change."},"feedback":{"zh":"停下来检查方法，不等于放弃；找到问题后，反而更知道该怎样继续。","en":"Evaluation can support more purposeful persistence."}}],"correct":"p07-R1-07240f51e4"}},"R2":{"teach":[{"zh":"已经学了三周却总错在同一处，就先检查错题和练习方法，再决定下一步怎么练。","en":"The example evaluates investment before extending it."},{"zh":"练得久不表示练得有效；还要看哪里进步了、哪里仍然卡住。","en":"Duration and results need separate examination."}],"question":{"id":"p07-R2","prompt":{"zh":"练了一段时间口语，不知道有没有进步，按照星币七的提醒，应该怎样检查？","en":"Progress after speaking practice is unclear. What fits?"},"options":[{"id":"p07-R2-a128c3ffbd","text":{"zh":"对照录音检查具体变化，再调整。","en":"Compare recordings, identify changes, and adjust."},"feedback":{"zh":"练得久不表示练得有效；还要看哪里进步了、哪里仍然卡住。","en":"Duration and results need separate examination."}},{"id":"p07-R2-f09cf5a600","text":{"zh":"只按练了多少天判断方法必然有效。","en":"Assume the method works from the day count alone."},"feedback":{"zh":"练得久不表示练得有效；还要看哪里进步了、哪里仍然卡住。","en":"Duration and results need separate examination."}}],"correct":"p07-R2-a128c3ffbd"}},"R3":{"teach":[{"zh":"小胡已经发现方法没有效果，却因为花了很多时间而不愿调整。这个例子里，星币七逆位提醒我们：没有效果的做法还在耗时间，应该重新检查。已经花了多少时间，不能单独成为继续照旧做的理由。","en":"Hu keeps an ineffective method solely because much time was spent. Here reversal concerns ongoing unproductive investment, calling for reassessment rather than sunk-cost justification."},{"zh":"决定明天怎么练，要看当前方法有没有效果，不能只因为已经练了很久就照旧做。","en":"Future choices depend on effectiveness, not sunk costs alone."}],"question":{"id":"p07-R3","prompt":{"zh":"检查证实旧方法无效，下一步是什么？","en":"Review confirms the old method is ineffective. What next?"},"options":[{"id":"p07-R3-d89ad47373","text":{"zh":"根据已经检查出的结果，调整接下来怎么练。","en":"Adjust future effort based on results."},"feedback":{"zh":"决定明天怎么练，要看当前方法有没有效果，不能只因为已经练了很久就照旧做。","en":"Future choices depend on effectiveness, not sunk costs alone."}},{"id":"p07-R3-7d2d7261d4","text":{"zh":"只因已经投入很多就拒绝修改。","en":"Refuse change because much was invested."},"feedback":{"zh":"决定明天怎么练，要看当前方法有没有效果，不能只因为已经练了很久就照旧做。","en":"Future choices depend on effectiveness, not sunk costs alone."}}],"correct":"p07-R3-d89ad47373"}}},"revisit":{"id":"p07-V1","prompt":{"zh":"种了几周植物，按照星币七的提醒，怎样决定接下来怎么照料？","en":"Weeks into growing a plant, apply the theme."},"options":[{"id":"p07-V1-197a4b86fd","text":{"zh":"不看植物的情况，只管不断增加浇水和施肥。","en":"Increase input indefinitely regardless of conditions."},"feedback":{"zh":"先看看植物长得怎样、土壤和光照是否合适，再调整照料；不能因为长得慢就一味增加浇水。","en":"Reviewing outcomes and conditions fits better than blind escalation."}},{"id":"p07-V1-c0435812ea","text":{"zh":"查看生长条件和变化，决定下一步。","en":"Review conditions and growth before deciding."},"feedback":{"zh":"先看看植物长得怎样、土壤和光照是否合适，再调整照料；不能因为长得慢就一味增加浇水。","en":"Reviewing outcomes and conditions fits better than blind escalation."}}],"correct":"p07-V1-c0435812ea"},"summary":{"zh":"星币七是在投入一段时间后停下来，看看已经做出了什么、花了多少时间和精力，再决定接下来怎么做。耐心不等于一直照旧做；如果方法没有帮助，就需要检查和调整。","en":"The Seven of Pentacles pauses after sustained investment to assess results, costs, and direction. Patience works with evaluation, not endless commitment to ineffective effort."},"cards":["p07"]},{"id":"p08","kind":"card","level":"I","title":{"zh":"星币八","en":"Eight of Pentacles"},"teachings":[{"zh":"星币八表示认真做事、练习技能，并把细节做好。它强调的不只是花了多少时间，还包括动作有没有更熟练、作品有没有做得更好；忙碌或反复做很多次，不一定就是进步。","en":"The Eight of Pentacles concerns dedicated work, learning skills, and refining quality. Practice, attention, and detail support each other; busyness or repetition alone does not prove improvement."},{"zh":"工匠正在雕刻星币，旁边已有完成的作品。用“正在做”和“已经做过”一起记住：认真练习，把手里的活做细致。","en":"A craftsperson engraves a pentacle beside completed pieces. Remember both work in progress and earlier work: practise attentively and take care with the details."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关。这里用工匠做作品的画面，帮助记住手艺需要认真练习；不能只凭数字八猜出整张牌的意思。可以用“专注、练习、不断改进、细心”帮助记忆。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth focuses attention on tangible work and quality; eight alone cannot generate the meaning. Focus, skill learning, detail, and refinement can help you remember the card."}],"application":{"zh":"小青练琴，总在同一小节出错。星币八在建议位，可以建议先把那一小节单独拿出来慢练，找出错在哪里，改好后再连起来弹整首。","en":"Qing keeps making mistakes in the same musical passage. As advice, Eight of Pentacles suggests practising that passage slowly on its own, finding and correcting the mistakes, then playing it within the whole piece."},"reversal":{"zh":"小青每天把同一段曲子反复弹，却一直不检查出错的地方。这个例子里，星币八逆位表示花了很多时间，却没有把细节练好，需要检查错误、调整练法。其他情况下也可能涉及对细节过分苛求，但这里没有这样的背景，不能硬套。","en":"Qing repeats mechanically without examining mistakes. Here reversal concerns effort disconnected from quality. Overpolishing belongs to another context and is not simultaneously imposed."},"visual":{"zh":"工匠正在雕刻星币，旁边已有完成的作品。用“正在做”和“已经做过”一起记住：认真练习，把手里的活做细致。","en":"A craftsperson engraves a pentacle beside completed pieces. Remember both work in progress and earlier work: practise attentively and take care with the details."},"questions":{"Q1":{"id":"p08-Q1","prompt":{"zh":"哪句话把星币八的意思说完整？","en":"Which captures this lesson?"},"options":[{"id":"p08-Q1-aa65f87a7a","text":{"zh":"只要忙得久，就已证明水平提高。","en":"Long hours alone prove improvement."},"feedback":{"zh":"不只是花时间做，还要看动作有没有更熟练、作品有没有做得更细致。","en":"Time spent is not enough: check whether your technique is becoming more fluent and your work more carefully finished."}},{"id":"p08-Q1-4d251eee08","text":{"zh":"认真练习，把动作做熟，把细节做好。","en":"Attend to skill and detail to improve work quality."},"feedback":{"zh":"不只是花时间做，还要看动作有没有更熟练、作品有没有做得更细致。","en":"Time spent is not enough: check whether your technique is becoming more fluent and your work more carefully finished."}}],"correct":"p08-Q1-4d251eee08","support":"R1"},"Q2":{"id":"p08-Q2","prompt":{"zh":"同一小节反复出错，按照刚才的例子，哪种练法更合适？","en":"The same passage repeatedly fails. Which follows?"},"options":[{"id":"p08-Q2-0bac52f39c","text":{"zh":"分段慢练，检查动作再连回全曲。","en":"Practice slowly in isolation, check technique, then reintegrate."},"feedback":{"zh":"把总出错的部分拆开慢练，并检查动作，才能知道哪里错了、怎样练得更熟。","en":"Slow down the difficult passage and check your technique to identify errors and practise more accurately."}},{"id":"p08-Q2-8e8f632189","text":{"zh":"不看错在哪里，只增加整曲重复次数。","en":"Increase full repetitions without examining the error."},"feedback":{"zh":"把总出错的部分拆开慢练，并检查动作，才能知道哪里错了、怎样练得更熟。","en":"Slow down the difficult passage and check your technique to identify errors and practise more accurately."}}],"correct":"p08-Q2-0bac52f39c","support":"R2"},"Q3":{"id":"p08-Q3","prompt":{"zh":"同一段曲子反复弹，却不检查错误。这里的星币八逆位提醒了什么问题？","en":"The same passage is played repeatedly without checking mistakes. What problem does the reversed Eight of Pentacles highlight here?"},"options":[{"id":"p08-Q3-db60b7ed2d","text":{"zh":"所有练习都毫无意义，应永远停止。","en":"All practice is meaningless and must stop forever."},"feedback":{"zh":"问题是同一个错误一直没有纠正；需要换一种练法，不是认定自己学不会。","en":"The issue is ineffective practice, not learning itself."}},{"id":"p08-Q3-b6aad421c2","text":{"zh":"花了很多时间，动作却没有练得更准确。","en":"Effort is disconnected from learning quality."},"feedback":{"zh":"问题是同一个错误一直没有纠正；需要换一种练法，不是认定自己学不会。","en":"The issue is ineffective practice, not learning itself."}}],"correct":"p08-Q3-b6aad421c2","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"不只是花时间做，还要看动作有没有更熟练、作品有没有做得更细致。","en":"Time spent is not enough: check whether your technique is becoming more fluent and your work more carefully finished."},{"zh":"次数只能说明你练过多少遍；还要检查错误有没有减少，才能知道有没有进步。","en":"Counts record effort but do not alone prove improvement."}],"question":{"id":"p08-R1","prompt":{"zh":"“重复很多次”和“确实进步了”有什么不同？","en":"What is the difference between repeating something many times and actually improving?"},"options":[{"id":"p08-R1-23ef7de9f7","text":{"zh":"要看动作有没有更熟练，做出来的东西有没有更好。","en":"Check whether your technique is more fluent and your work is better."},"feedback":{"zh":"次数只能说明你练过多少遍；还要检查错误有没有减少，才能知道有没有进步。","en":"Counts record effort but do not alone prove improvement."}},{"id":"p08-R1-8508d3a2fc","text":{"zh":"只看重复了多少遍，次数多就算进步。","en":"Count only repetitions: more repetitions mean improvement."},"feedback":{"zh":"次数只能说明你练过多少遍；还要检查错误有没有减少，才能知道有没有进步。","en":"Counts record effort but do not alone prove improvement."}}],"correct":"p08-R1-23ef7de9f7"}},"R2":{"teach":[{"zh":"把总出错的部分拆开慢练，并检查动作，才能知道哪里错了、怎样练得更熟。","en":"Slow down the difficult passage and check your technique to identify errors and practise more accurately."},{"zh":"把写得不稳的笔画单独拿出来练，再和之前比较，才知道练习有没有帮助。","en":"Practise the unstable stroke separately, then compare it with earlier attempts to check whether the practice helped."}],"question":{"id":"p08-R2","prompt":{"zh":"练字时同一笔画总歪，按照星币八的提醒，怎样练习？","en":"One stroke stays crooked in handwriting practice. What fits?"},"options":[{"id":"p08-R2-0c88ae9173","text":{"zh":"不看字形，只把整页抄得更多。","en":"Ignore form and copy more entire pages."},"feedback":{"zh":"把写得不稳的笔画单独拿出来练，再和之前比较，才知道练习有没有帮助。","en":"Practise the unstable stroke separately, then compare it with earlier attempts to check whether the practice helped."}},{"id":"p08-R2-ea775cf37c","text":{"zh":"把这个笔画单独拿出来练，再和范例比较。","en":"Isolate the stroke and check against an example."},"feedback":{"zh":"把写得不稳的笔画单独拿出来练，再和之前比较，才知道练习有没有帮助。","en":"Practise the unstable stroke separately, then compare it with earlier attempts to check whether the practice helped."}}],"correct":"p08-R2-ea775cf37c"}},"R3":{"teach":[{"zh":"小青每天把同一段曲子反复弹，却一直不检查出错的地方。这个例子里，星币八逆位表示花了很多时间，却没有把细节练好，需要检查错误、调整练法。其他情况下也可能涉及对细节过分苛求，但这里没有这样的背景，不能硬套。","en":"Qing repeats mechanically without examining mistakes. Here reversal concerns effort disconnected from quality. Overpolishing belongs to another context and is not simultaneously imposed."},{"zh":"这个逆位例子提醒我们：先找出总错的地方，再有针对性地练，不要只增加次数。","en":"This reversal reconnects effort to skill quality."}],"question":{"id":"p08-R3","prompt":{"zh":"总在同一处出错，却一直没检查原因。接下来应该怎样练？","en":"The same mistake keeps recurring, but its cause has never been checked. How should the learner practise next?"},"options":[{"id":"p08-R3-391ad16378","text":{"zh":"完全取消细节，只追求更快重复。","en":"Eliminate detail and repeat faster."},"feedback":{"zh":"这个逆位例子提醒我们：先找出总错的地方，再有针对性地练，不要只增加次数。","en":"This reversal reconnects effort to skill quality."}},{"id":"p08-R3-a00a625eb7","text":{"zh":"先检查错在哪里，再专门练习出错的部分。","en":"Add error-focused checking and practice."},"feedback":{"zh":"这个逆位例子提醒我们：先找出总错的地方，再有针对性地练，不要只增加次数。","en":"This reversal reconnects effort to skill quality."}}],"correct":"p08-R3-a00a625eb7"}}},"revisit":{"id":"p08-V1","prompt":{"zh":"做演示文稿时图表经常错位，按照星币八的提醒，应该怎样改进？","en":"Your charts often misalign in presentations. Following the Eight of Pentacles, how could you improve?"},"options":[{"id":"p08-V1-a82f9b49fa","text":{"zh":"练习对齐操作，并检查实际效果。","en":"Practice alignment and check results."},"feedback":{"zh":"先检查幻灯片哪里没对齐，再练习调整；页数做得更多，不表示做得更仔细。","en":"Check where the charts misalign and practise correcting them. Making more slides does not necessarily mean making them more carefully."}},{"id":"p08-V1-1d2ec33d9a","text":{"zh":"仅按坐在电脑前的小时数评价水平。","en":"Rate skill only by hours at the computer."},"feedback":{"zh":"先检查幻灯片哪里没对齐，再练习调整；页数做得更多，不表示做得更仔细。","en":"Check where the charts misalign and practise correcting them. Making more slides does not necessarily mean making them more carefully."}}],"correct":"p08-V1-a82f9b49fa"},"summary":{"zh":"星币八表示认真做事、练习技能，并把细节做好。它强调的不只是花了多少时间，还包括动作有没有更熟练、作品有没有做得更好；忙碌或反复做很多次，不一定就是进步。","en":"The Eight of Pentacles concerns dedicated work, learning skills, and refining quality. Practice, attention, and detail support each other; busyness or repetition alone does not prove improvement."},"cards":["p08"]},{"id":"p09","kind":"card","level":"I","title":{"zh":"星币九","en":"Nine of Pentacles"},"teachings":[{"zh":"星币九是长期积累、自我管理与从容享受成果。独立强调有能力安排自己的生活，不等于拒绝任何帮助或关系。","en":"The Nine of Pentacles concerns accumulated resources, self-management, and enjoying results. Independence means capacity to manage life, not refusing all help or connection."},{"zh":"人物站在葡萄园里，戴手套的手上停着猎鹰。丰盛的花园和从容的人物，帮助我们记住积累后的成果与生活安排；仅凭画面不能确定现实中的职业或身份。","en":"A figure stands in a vineyard with a falcon on a gloved hand. Abundance and composure suggest results and management, not a fixed real-world identity."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关。数字九可以帮助记住积累已经有了成果；画中的花园和人物，则让我们想到怎样照顾自己的生活、享受努力后的收获。可以记成：独立、自律、享受成果。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns living conditions; nine can aid remembering mature personal results. Helpers: independence, self-discipline, enjoyment."}],"application":{"zh":"小余持续练习后能独立完成作品。建议位承认自己的积累，安排可承担的奖励，也允许需要时请教别人。","en":"Yu can complete a work independently after sustained practice. Advice acknowledges achievement and allows an affordable reward while retaining the option to seek advice."},"reversal":{"zh":"小余为了维持“我很成功”的形象，买了超出预算的东西，自己的生活反而受到影响。这个例子里，星币九逆位提醒我们：先顾好实际收支和生活，不要只顾让别人觉得自己过得好；这不是在评价一个人的价值。","en":"Yu overspends to maintain an image of success. Here reversal concerns display overriding genuine independence, calling for a return to actual conditions."},"visual":{"zh":"人物站在葡萄园里，戴手套的手上停着猎鹰。丰盛的花园和从容的人物，帮助我们记住积累后的成果与生活安排；仅凭画面不能确定现实中的职业或身份。","en":"A figure stands in a vineyard with a falcon on a gloved hand. Abundance and composure suggest results and management, not a fixed real-world identity."},"questions":{"Q1":{"id":"p09-Q1","prompt":{"zh":"独立是否意味着完全不需要别人？","en":"Does independence mean never needing anyone?"},"options":[{"id":"p09-Q1-c760051ce7","text":{"zh":"不是，能管理自己也可以接受帮助。","en":"No; self-management can include receiving help."},"feedback":{"zh":"有能力安排自己的生活，也可以接受别人的帮助，两者并不冲突。","en":"Capability and connection can coexist."}},{"id":"p09-Q1-78d2e92088","text":{"zh":"是，求助一次就失去全部独立。","en":"Yes; one request erases independence."},"feedback":{"zh":"有能力安排自己的生活，也可以接受别人的帮助，两者并不冲突。","en":"Capability and connection can coexist."}}],"correct":"p09-Q1-c760051ce7","support":"R1"},"Q2":{"id":"p09-Q2","prompt":{"zh":"已经能独立完成作品，按照刚才的例子，怎样肯定自己的进步？","en":"Able to complete a work independently: what fits?"},"options":[{"id":"p09-Q2-912625a285","text":{"zh":"为证明独立拒绝所有必要建议。","en":"Refuse all useful advice to prove independence."},"feedback":{"zh":"可以在预算内奖励自己、享受成果；不必为了证明独立而拒绝所有人的帮助。","en":"Appreciating results does not require isolation."}},{"id":"p09-Q2-513bb8f92d","text":{"zh":"肯定自己的努力，在预算内安排一份享受。","en":"Acknowledge progress and enjoy within means."},"feedback":{"zh":"可以在预算内奖励自己、享受成果；不必为了证明独立而拒绝所有人的帮助。","en":"Appreciating results does not require isolation."}}],"correct":"p09-Q2-513bb8f92d","support":"R2"},"Q3":{"id":"p09-Q3","prompt":{"zh":"为成功形象超预算购买，逆位提醒什么？","en":"Overspending for a success image: reversal?"},"options":[{"id":"p09-Q3-d4f137aba1","text":{"zh":"先看看自己实际能负担什么，再安排消费和生活。","en":"Return to real capability and affordable conditions."},"feedback":{"zh":"买得贵、看起来富足，不表示能安排好自己的收支；已经超支，就要先调整预算。","en":"Consumption cannot replace self-management."}},{"id":"p09-Q3-77a1bfdec1","text":{"zh":"购买越贵就越证明独立。","en":"Higher prices prove greater independence."},"feedback":{"zh":"买得贵、看起来富足，不表示能安排好自己的收支；已经超支，就要先调整预算。","en":"Consumption cannot replace self-management."}}],"correct":"p09-Q3-d4f137aba1","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"有能力安排自己的生活，也可以接受别人的帮助，两者并不冲突。","en":"Capability and connection can coexist."},{"zh":"重点是能把自己的日子安排好，而不是让别人觉得你比他们过得好。","en":"The theme centers on sustainable personal life."}],"question":{"id":"p09-R1","prompt":{"zh":"怎样区分享受成果与证明身份？","en":"Distinguish enjoying results from proving status."},"options":[{"id":"p09-R1-bfdc81a5a8","text":{"zh":"只要让别人羡慕就算自我管理。","en":"Envy from others proves self-management."},"feedback":{"zh":"重点是能把自己的日子安排好，而不是让别人觉得你比他们过得好。","en":"The theme centers on sustainable personal life."}},{"id":"p09-R1-d8427f53f6","text":{"zh":"肯定自己已经做好的事，在负担得起的范围内享受成果。","en":"Enjoyment fits actual conditions and accumulated work."},"feedback":{"zh":"重点是能把自己的日子安排好，而不是让别人觉得你比他们过得好。","en":"The theme centers on sustainable personal life."}}],"correct":"p09-R1-d8427f53f6"}},"R2":{"teach":[{"zh":"可以在预算内奖励自己、享受成果；不必为了证明独立而拒绝所有人的帮助。","en":"Appreciating results does not require isolation."},{"zh":"完成长期学习目标，值得给自己一点奖励；不用比别人强，才有资格肯定自己的努力。","en":"Achievement can be appreciated without comparison."}],"question":{"id":"p09-R2","prompt":{"zh":"完成长期学习目标后，按照星币九的提醒，怎样看待自己的成果？","en":"After a long-term study goal, apply."},"options":[{"id":"p09-R2-4c7944ec4b","text":{"zh":"肯定能力进步，安排适量放松。","en":"Recognize capability gained and allow measured relaxation."},"feedback":{"zh":"完成长期学习目标，值得给自己一点奖励；不用比别人强，才有资格肯定自己的努力。","en":"Achievement can be appreciated without comparison."}},{"id":"p09-R2-01f1ce40a3","text":{"zh":"因为还有人更强，就否定全部成果。","en":"Dismiss all achievement because others are stronger."},"feedback":{"zh":"完成长期学习目标，值得给自己一点奖励；不用比别人强，才有资格肯定自己的努力。","en":"Achievement can be appreciated without comparison."}}],"correct":"p09-R2-4c7944ec4b"}},"R3":{"teach":[{"zh":"小余为了维持“我很成功”的形象，买了超出预算的东西，自己的生活反而受到影响。这个例子里，星币九逆位提醒我们：先顾好实际收支和生活，不要只顾让别人觉得自己过得好；这不是在评价一个人的价值。","en":"Yu overspends to maintain an image of success. Here reversal concerns display overriding genuine independence, calling for a return to actual conditions."},{"zh":"先让收支安排得过来，比维持“我过得很好”的印象更重要。","en":"External impressions cannot replace self-management."}],"question":{"id":"p09-R3","prompt":{"zh":"超预算消费让生活受压，怎样修正？","en":"Overspending strains daily life. Correct how?"},"options":[{"id":"p09-R3-e36911d397","text":{"zh":"先按预算安排生活，分清自己真的享受什么、哪些只是买给别人看。","en":"Return to affordable conditions and separate enjoyment from display."},"feedback":{"zh":"先让收支安排得过来，比维持“我过得很好”的印象更重要。","en":"External impressions cannot replace self-management."}},{"id":"p09-R3-8b0fde62f9","text":{"zh":"继续加购，让别人更确信自己成功。","en":"Buy more so others believe in the success."},"feedback":{"zh":"先让收支安排得过来，比维持“我过得很好”的印象更重要。","en":"External impressions cannot replace self-management."}}],"correct":"p09-R3-e36911d397"}}},"revisit":{"id":"p09-V1","prompt":{"zh":"靠自己整理好生活，怎样保持独立？","en":"Life is organized through personal effort. Maintain independence how?"},"options":[{"id":"p09-V1-cf22d6da69","text":{"zh":"把一切关系都视为失败证据。","en":"Treat every relationship as evidence of failure."},"feedback":{"zh":"能够自己安排生活，不表示必须事事独自承担；遇到需要时仍可以求助。","en":"Independence is capability, not total isolation."}},{"id":"p09-V1-abc40f57fd","text":{"zh":"继续安排好自己的生活，需要时也可以求助或帮助别人。","en":"Maintain conditions and sensible mutual support."},"feedback":{"zh":"能够自己安排生活，不表示必须事事独自承担；遇到需要时仍可以求助。","en":"Independence is capability, not total isolation."}}],"correct":"p09-V1-abc40f57fd"},"summary":{"zh":"星币九是长期积累、自我管理与从容享受成果。独立强调有能力安排自己的生活，不等于拒绝任何帮助或关系。","en":"The Nine of Pentacles concerns accumulated resources, self-management, and enjoying results. Independence means capacity to manage life, not refusing all help or connection."},"cards":["p09"]},{"id":"p10","kind":"card","level":"I","title":{"zh":"星币十","en":"Ten of Pentacles"},"teachings":[{"zh":"星币十关注长期积累下来的资源、经验，以及家人或团队共同拥有的保障。已有的成果通过共同约定、交接或代际传承保留下来，让后来的人也能使用，不只是某一个人此刻拥有多少东西。","en":"The Ten of Pentacles concerns long-term resources, experience, and shared security. Results endure through systems, transmission, or community beyond one person’s current possessions."},{"zh":"长者、成人、孩子、犬和建筑共同出现。不同年龄的人生活在同一环境里，帮助我们记住把积累的东西传给后来的人，不等于现实中必然继承财产。","en":"Elders, adults, a child, dogs, and architecture share the scene. Generations and a common environment suggest continuity, not guaranteed inheritance."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关。数字十可以帮助记住长期积累；画中不同年龄的人，让我们想到把成果留给后来的人。可以记成：长期积累、传给后来的人、共同保障。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns tangible security; ten can aid remembering accumulated structure. Helpers: lasting accumulation, transmission, shared security."}],"application":{"zh":"社团骨干即将离开。建议位把经验整理成流程、保存共同资料并做好交接，让成果不依赖单一成员。","en":"Experienced club members are leaving. Advice documents processes, preserves shared materials, and prepares handover so outcomes do not depend on one person."},"reversal":{"zh":"资料只留在离开成员的个人设备上，新成员拿不到资料，工作无法继续。这个例子里，星币十逆位表示本来该共同保留的成果没有交接好，需要补上文件和操作说明；不表示社团一定会解散。","en":"Shared knowledge remains on a departing member’s device. Here reversal concerns an unstable shared foundation and calls for handover, not a prediction of dissolution."},"visual":{"zh":"长者、成人、孩子、犬和建筑共同出现。不同年龄的人生活在同一环境里，帮助我们记住把积累的东西传给后来的人，不等于现实中必然继承财产。","en":"Elders, adults, a child, dogs, and architecture share the scene. Generations and a common environment suggest continuity, not guaranteed inheritance."},"questions":{"Q1":{"id":"p10-Q1","prompt":{"zh":"星币十为什么不只看某个人现在拥有多少东西？","en":"Why look beyond individual results?"},"options":[{"id":"p10-Q1-139ca16ba8","text":{"zh":"只有马上拿到个人奖励才有意义。","en":"Only immediate personal rewards matter."},"feedback":{"zh":"这张牌关注长期积累，以及家人或团队怎样一起保留、使用这些成果。","en":"The meaning concerns shared structures and long-term accumulation."}},{"id":"p10-Q1-0140841cf6","text":{"zh":"还要看积累下来的东西，怎样留给家人或团队继续使用。","en":"Consider how results endure and support others."},"feedback":{"zh":"这张牌关注长期积累，以及家人或团队怎样一起保留、使用这些成果。","en":"The meaning concerns shared structures and long-term accumulation."}}],"correct":"p10-Q1-0140841cf6","support":"R1"},"Q2":{"id":"p10-Q2","prompt":{"zh":"社团骨干离开前，怎样做才能让后来的人继续工作？","en":"Before experienced members leave, which fits?"},"options":[{"id":"p10-Q2-1fd40a7b53","text":{"zh":"整理流程资料并完成交接。","en":"Organize process knowledge and complete handover."},"feedback":{"zh":"把经验、文件和操作方法交接清楚，接手的人才能继续做；只说“交给你了”还不够。","en":"Transmission requires a usable practical foundation."}},{"id":"p10-Q2-ce18229bf4","text":{"zh":"只说大家以后自己猜就好。","en":"Tell successors to guess later."},"feedback":{"zh":"把经验、文件和操作方法交接清楚，接手的人才能继续做；只说“交给你了”还不够。","en":"Transmission requires a usable practical foundation."}}],"correct":"p10-Q2-1fd40a7b53","support":"R2"},"Q3":{"id":"p10-Q3","prompt":{"zh":"资料随个人离开，逆位指出什么？","en":"Knowledge leaves with one person. Reversal?"},"options":[{"id":"p10-Q3-af5bbac234","text":{"zh":"社团已被保证必然解散。","en":"The club is guaranteed to dissolve."},"feedback":{"zh":"可以备份文件、补上交接，来解决眼前的问题；不能因此断定整个社团一定失败。","en":"The gap can be addressed without fixing the outcome."}},{"id":"p10-Q3-23df2e6cff","text":{"zh":"资料只在一个人的设备里，其他人离开他就没法接着做。","en":"The foundation for continuity is insecure."},"feedback":{"zh":"可以备份文件、补上交接，来解决眼前的问题；不能因此断定整个社团一定失败。","en":"The gap can be addressed without fixing the outcome."}}],"correct":"p10-Q3-23df2e6cff","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"这张牌关注长期积累，以及家人或团队怎样一起保留、使用这些成果。","en":"The meaning concerns shared structures and long-term accumulation."},{"zh":"接手的人需要找得到文件，也知道怎样使用；只有一句口头叮嘱，往往不够。","en":"Continuity needs accessible, usable knowledge."}],"question":{"id":"p10-R1","prompt":{"zh":"经验传承为什么不是只讲一次故事？","en":"Why is transmission more than telling a story once?"},"options":[{"id":"p10-R1-40446e3d98","text":{"zh":"后续成员要能实际使用经验。","en":"Future members must be able to use it."},"feedback":{"zh":"接手的人需要找得到文件，也知道怎样使用；只有一句口头叮嘱，往往不够。","en":"Continuity needs accessible, usable knowledge."}},{"id":"p10-R1-f2e04f7f0b","text":{"zh":"只要过去成功过，资料就不重要。","en":"Past success makes documentation irrelevant."},"feedback":{"zh":"接手的人需要找得到文件，也知道怎样使用；只有一句口头叮嘱，往往不够。","en":"Continuity needs accessible, usable knowledge."}}],"correct":"p10-R1-40446e3d98"}},"R2":{"teach":[{"zh":"把经验、文件和操作方法交接清楚，接手的人才能继续做；只说“交给你了”还不够。","en":"Transmission requires a usable practical foundation."},{"zh":"把家中共用物品放在哪里、怎样维护说清楚，家人才能继续使用，而不必总依赖某一个人。","en":"Shared security depends on sustainable arrangements."}],"question":{"id":"p10-R2","prompt":{"zh":"家人一起管理共用物品，怎样运用星币十讲的长期保留和共同使用？","en":"A household manages shared items. Apply."},"options":[{"id":"p10-R2-421132b2d2","text":{"zh":"只让一个人知道所有安排且不交接。","en":"Keep all arrangements with one person and no handover."},"feedback":{"zh":"把家中共用物品放在哪里、怎样维护说清楚，家人才能继续使用，而不必总依赖某一个人。","en":"Shared security depends on sustainable arrangements."}},{"id":"p10-R2-19520a1b59","text":{"zh":"说清物品放在哪里、怎样使用和维护，让家人都能继续用。","en":"Clarify care and access for continued use."},"feedback":{"zh":"把家中共用物品放在哪里、怎样维护说清楚，家人才能继续使用，而不必总依赖某一个人。","en":"Shared security depends on sustainable arrangements."}}],"correct":"p10-R2-19520a1b59"}},"R3":{"teach":[{"zh":"资料只留在离开成员的个人设备上，新成员拿不到资料，工作无法继续。这个例子里，星币十逆位表示本来该共同保留的成果没有交接好，需要补上文件和操作说明；不表示社团一定会解散。","en":"Shared knowledge remains on a departing member’s device. Here reversal concerns an unstable shared foundation and calls for handover, not a prediction of dissolution."},{"zh":"把文件放到团队能访问的地方，并写好使用说明，才能让别人接着工作。","en":"Continuity needs usable information."}],"question":{"id":"p10-R3","prompt":{"zh":"交接缺失导致新人不能继续，先补什么？","en":"Missing handover blocks successors. Fill what first?"},"options":[{"id":"p10-R3-a7793d6343","text":{"zh":"只告诉新人过去曾经成功过。","en":"Merely tell successors that things once succeeded."},"feedback":{"zh":"把文件放到团队能访问的地方，并写好使用说明，才能让别人接着工作。","en":"Continuity needs usable information."}},{"id":"p10-R3-312c94c6e8","text":{"zh":"新人找得到的资料、做事步骤，以及各项工作由谁负责。","en":"Accessible materials, processes, and responsibilities."},"feedback":{"zh":"把文件放到团队能访问的地方，并写好使用说明，才能让别人接着工作。","en":"Continuity needs usable information."}}],"correct":"p10-R3-312c94c6e8"}}},"revisit":{"id":"p10-V1","prompt":{"zh":"团队换负责人，怎样保留成果？","en":"A team changes leaders. Preserve outcomes how?"},"options":[{"id":"p10-V1-caf8e01c5a","text":{"zh":"交接流程、资源与维护责任。","en":"Hand over processes, resources, and maintenance duties."},"feedback":{"zh":"负责人会更换，但资料、分工和操作方法交接好了，团队仍可以接着做。","en":"Long-term structures can carry through personnel changes."}},{"id":"p10-V1-f9f81122ab","text":{"zh":"认为负责人离开就必须否定全部积累。","en":"Assume a departing leader invalidates all past work."},"feedback":{"zh":"负责人会更换，但资料、分工和操作方法交接好了，团队仍可以接着做。","en":"Long-term structures can carry through personnel changes."}}],"correct":"p10-V1-caf8e01c5a"},"summary":{"zh":"星币十关注长期积累下来的资源、经验，以及家人或团队共同拥有的保障。已有的成果通过共同约定、交接或代际传承保留下来，让后来的人也能使用，不只是某一个人此刻拥有多少东西。","en":"The Ten of Pentacles concerns long-term resources, experience, and shared security. Results endure through systems, transmission, or community beyond one person’s current possessions."},"cards":["p10"]},{"id":"p11","kind":"card","level":"I","title":{"zh":"星币侍从","en":"Page of Pentacles"},"teachings":[{"zh":"星币侍从认真开始学习一项技能，或把计划变成可以动手做的事，愿意从基础做起。学习意愿是开始，仍需实际练习才能形成技能。","en":"The Page of Pentacles approaches practical knowledge or a plan with attention and willingness to start from basics. Interest begins learning; practice builds skill."},{"zh":"人物凝视手中星币，脚下有土地。这帮助我们记住从眼前这件具体的事开始学习，不限定学生年龄。","en":"The figure studies a pentacle while standing on the ground. A concrete focus suggests practical learning, without an age requirement."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关；侍从表示刚开始学习、愿意尝试。这张牌可以记成：动手学、专心、新的学习机会。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth supplies practical skills and resources; Page suggests beginning to learn. Helpers: practical learning, attention, a starting opportunity."}],"application":{"zh":"小施想学摄影。建议位先认识一个基础设置，拍一组照片检查差异，不把购买全套器材当成已经学会。","en":"Shi wants to learn photography. Advice learns one basic setting and takes comparison photos rather than treating equipment purchases as acquired skill."},"reversal":{"zh":"小施收藏了很多教程，却跳过基础操作，一直没有实际拍摄。这个例子里，星币侍从逆位表示一直计划、没有动手。先完成一次基础练习，比继续收集教程更有帮助。","en":"Shi saves tutorials but skips basic operations and never shoots. Here reversal means a plan not put into practice, calling for one basic exercise."},"visual":{"zh":"人物凝视手中星币，脚下有土地。这帮助我们记住从眼前这件具体的事开始学习，不限定学生年龄。","en":"The figure studies a pentacle while standing on the ground. A concrete focus suggests practical learning, without an age requirement."},"questions":{"Q1":{"id":"p11-Q1","prompt":{"zh":"学习意愿和熟练掌握是否相同？","en":"Are willingness and proficiency the same?"},"options":[{"id":"p11-Q1-e372b0edde","text":{"zh":"不同，愿意学之后，还需要动手练习。","en":"No; willingness still needs practice."},"feedback":{"zh":"侍从在这里表示刚开始学习、愿意认真尝试，还不是已经熟练掌握。","en":"The Page represents a learning beginning."}},{"id":"p11-Q1-c88d357fee","text":{"zh":"相同，有兴趣就已经会做。","en":"Yes; interest already means competence."},"feedback":{"zh":"侍从在这里表示刚开始学习、愿意认真尝试，还不是已经熟练掌握。","en":"The Page represents a learning beginning."}}],"correct":"p11-Q1-e372b0edde","support":"R1"},"Q2":{"id":"p11-Q2","prompt":{"zh":"刚开始学摄影，按照刚才的例子，先怎样练习？","en":"Beginning photography: which follows?"},"options":[{"id":"p11-Q2-53e68533ac","text":{"zh":"只购器材，不进行任何操作。","en":"Buy equipment without practicing."},"feedback":{"zh":"选一个相机设置实际拍摄、比较照片，才能知道这个设置会带来什么变化。","en":"Practical learning requires concrete action."}},{"id":"p11-Q2-733bf20ef5","text":{"zh":"练一个设置并观察照片差异。","en":"Practice one setting and compare photos."},"feedback":{"zh":"选一个相机设置实际拍摄、比较照片，才能知道这个设置会带来什么变化。","en":"Practical learning requires concrete action."}}],"correct":"p11-Q2-733bf20ef5","support":"R2"},"Q3":{"id":"p11-Q3","prompt":{"zh":"收藏教程却不操作，逆位提醒什么？","en":"Saving tutorials without practice: reversal?"},"options":[{"id":"p11-Q3-bd3654dc9e","text":{"zh":"把一个基础步骤实际做出来。","en":"Carry out one foundational step."},"feedback":{"zh":"收藏教程只是存下资料；还需要拿起相机试一试，才是在练习技能。","en":"Collecting resources differs from practicing skills."}},{"id":"p11-Q3-f95bc93c70","text":{"zh":"继续收藏就等于已完成练习。","en":"More saved tutorials equal completed practice."},"feedback":{"zh":"收藏教程只是存下资料；还需要拿起相机试一试，才是在练习技能。","en":"Collecting resources differs from practicing skills."}}],"correct":"p11-Q3-bd3654dc9e","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"侍从在这里表示刚开始学习、愿意认真尝试，还不是已经熟练掌握。","en":"The Page represents a learning beginning."},{"zh":"知道有哪些工具还不够，要实际用过、练过，才能慢慢学会。","en":"Capability develops through practice."}],"question":{"id":"p11-R1","prompt":{"zh":"怎样把兴趣变成学习起点？","en":"Turn interest into learning how?"},"options":[{"id":"p11-R1-464e5bc641","text":{"zh":"只给自己贴上熟练者标签。","en":"Merely label yourself proficient."},"feedback":{"zh":"知道有哪些工具还不够，要实际用过、练过，才能慢慢学会。","en":"Capability develops through practice."}},{"id":"p11-R1-d19c4319c8","text":{"zh":"选择一个能实际操作的基础任务。","en":"Choose one workable foundational task."},"feedback":{"zh":"知道有哪些工具还不够，要实际用过、练过，才能慢慢学会。","en":"Capability develops through practice."}}],"correct":"p11-R1-d19c4319c8"}},"R2":{"teach":[{"zh":"选一个相机设置实际拍摄、比较照片，才能知道这个设置会带来什么变化。","en":"Practical learning requires concrete action."},{"zh":"第一次做面包，先按一种简单配方称量、操作，比同时尝试很多复杂做法更容易学清楚。","en":"Practical beginnings stay within a learnable scope."}],"question":{"id":"p11-R2","prompt":{"zh":"想学做面包，先如何开始？","en":"Wanting to bake bread, start how?"},"options":[{"id":"p11-R2-3492e33435","text":{"zh":"先学会按配方称量，再试做一小份。","en":"Learn basic measurements and make one small batch."},"feedback":{"zh":"第一次做面包，先按一种简单配方称量、操作，比同时尝试很多复杂做法更容易学清楚。","en":"Practical beginnings stay within a learnable scope."}},{"id":"p11-R2-83017cf5b2","text":{"zh":"先跳过基础，直接证明自己会复杂造型。","en":"Skip basics to claim complex shaping skill."},"feedback":{"zh":"第一次做面包，先按一种简单配方称量、操作，比同时尝试很多复杂做法更容易学清楚。","en":"Practical beginnings stay within a learnable scope."}}],"correct":"p11-R2-3492e33435"}},"R3":{"teach":[{"zh":"小施收藏了很多教程，却跳过基础操作，一直没有实际拍摄。这个例子里，星币侍从逆位表示一直计划、没有动手。先完成一次基础练习，比继续收集教程更有帮助。","en":"Shi saves tutorials but skips basic operations and never shoots. Here reversal means a plan not put into practice, calling for one basic exercise."},{"zh":"教程已经收集了很多，这次缺的是实际操作；先选一个设置试拍，不用继续囤教程。","en":"The gap is practice, not the number of tutorials."}],"question":{"id":"p11-R3","prompt":{"zh":"收藏很多教程却未实践，下一步是什么？","en":"Many tutorials saved, no practice done. What next?"},"options":[{"id":"p11-R3-7091a53461","text":{"zh":"选一个基础任务亲手完成。","en":"Complete one foundational task in practice."},"feedback":{"zh":"教程已经收集了很多，这次缺的是实际操作；先选一个设置试拍，不用继续囤教程。","en":"The gap is practice, not the number of tutorials."}},{"id":"p11-R3-0f346bcba5","text":{"zh":"再收藏更多高级教程代替练习。","en":"Save more advanced tutorials instead of practicing."},"feedback":{"zh":"教程已经收集了很多，这次缺的是实际操作；先选一个设置试拍，不用继续囤教程。","en":"The gap is practice, not the number of tutorials."}}],"correct":"p11-R3-7091a53461"}}},"revisit":{"id":"p11-V1","prompt":{"zh":"第一次接触表格工具，按照星币侍从的提醒，怎样开始学？","en":"First using spreadsheets, apply."},"options":[{"id":"p11-V1-24137c9814","text":{"zh":"阅读软件名后认定自己已熟练。","en":"Assume proficiency after reading the software name."},"feedback":{"zh":"听过表格功能的名字，不等于会用；可以先跟着例子实际做一遍。","en":"Knowing a name is not practical competence."}},{"id":"p11-V1-2b736db971","text":{"zh":"从输入数据和一项基础操作开始。","en":"Start with data entry and one basic operation."},"feedback":{"zh":"听过表格功能的名字，不等于会用；可以先跟着例子实际做一遍。","en":"Knowing a name is not practical competence."}}],"correct":"p11-V1-2b736db971"},"summary":{"zh":"星币侍从认真开始学习一项技能，或把计划变成可以动手做的事，愿意从基础做起。学习意愿是开始，仍需实际练习才能形成技能。","en":"The Page of Pentacles approaches practical knowledge or a plan with attention and willingness to start from basics. Interest begins learning; practice builds skill."},"cards":["p11"]},{"id":"p12","kind":"card","level":"I","title":{"zh":"星币骑士","en":"Knight of Pentacles"},"teachings":[{"zh":"星币骑士做事稳妥、认真负责，按自己能坚持的节奏完成任务。慢一点不等于做得差，但也要检查：每天照着做的事，是否仍符合现在的目标。","en":"The Knight of Pentacles follows steady, responsible steps with sustainable execution. Slow does not automatically mean poor, but routines must still serve an appropriate goal."},{"zh":"马静立，骑士持币，背景是耕地。安稳的姿态和耕地，帮助记住耐心把事情做完，不据此说他永远不行动。","en":"The horse stands still, the rider holds a pentacle, and fields lie behind. Stability and cultivation suggest patient execution, not permanent inactivity."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关；骑士强调持续去做。这张牌可以记成：可靠、坚持做完、耐心、负责。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns practical tasks; Knight emphasizes committed action. Helpers: reliability, execution, patience, responsibility."}],"application":{"zh":"小罗要参加一场需要准备较长时间的考试。放在建议位，可以把复习分成每天做得完的任务，并定期检查进度；不要头几天安排太多，累得后来完全停下来。","en":"Luo prepares for a long-term exam. Advice sets a manageable daily unit, follows through, and reviews periodically rather than overworking briefly and stopping."},"reversal":{"zh":"考试要求已经改变，小罗却不看新要求，仍照旧清单复习。这个例子里，星币骑士逆位表示做法过于死板，需要检查每天做的事是否还符合目标；不是让他放弃规律学习。","en":"Requirements change but Luo mechanically follows the old list. Here reversal means rigid routine and calls for reviewing the purpose, not abandoning all consistency."},"visual":{"zh":"马静立，骑士持币，背景是耕地。安稳的姿态和耕地，帮助记住耐心把事情做完，不据此说他永远不行动。","en":"The horse stands still, the rider holds a pentacle, and fields lie behind. Stability and cultivation suggest patient execution, not permanent inactivity."},"questions":{"Q1":{"id":"p12-Q1","prompt":{"zh":"做事是否稳妥可靠，主要看什么？","en":"What defines reliable execution?"},"options":[{"id":"p12-Q1-40c3b507e9","text":{"zh":"只看第一天冲得多快。","en":"Only first-day speed."},"feedback":{"zh":"每天完成必要的复习，比只在某一天特别拼、之后全停下来，更能体现认真负责。","en":"Sustained responsibility fits better than one burst."}},{"id":"p12-Q1-f4a95e251b","text":{"zh":"按自己能坚持的安排，持续完成该做的事。","en":"Consistently carrying out feasible steps."},"feedback":{"zh":"每天完成必要的复习，比只在某一天特别拼、之后全停下来，更能体现认真负责。","en":"Sustained responsibility fits better than one burst."}}],"correct":"p12-Q1-f4a95e251b","support":"R1"},"Q2":{"id":"p12-Q2","prompt":{"zh":"考试需要准备较长时间，怎样安排更符合刚才的例子？","en":"Preparing for a long-term exam: which fits?"},"options":[{"id":"p12-Q2-41236a0e59","text":{"zh":"安排每天能完成的复习量，并检查有没有完成。","en":"Set sustainable daily tasks and check follow-through."},"feedback":{"zh":"每天的量要安排得过来，才能坚持；一下塞太多，很容易第二天就停下来。","en":"Sustainable execution needs a workable pace."}},{"id":"p12-Q2-90e5f53e21","text":{"zh":"第一天做尽所有计划，之后不再安排。","en":"Exhaust the plan on day one and schedule nothing later."},"feedback":{"zh":"每天的量要安排得过来，才能坚持；一下塞太多，很容易第二天就停下来。","en":"Sustainable execution needs a workable pace."}}],"correct":"p12-Q2-41236a0e59","support":"R2"},"Q3":{"id":"p12-Q3","prompt":{"zh":"要求已变仍机械照旧，逆位提示什么？","en":"Requirements change but routine does not. Reversal?"},"options":[{"id":"p12-Q3-e70f461308","text":{"zh":"稳定意味着永远不准调整。","en":"Stability means never adjusting."},"feedback":{"zh":"考试要求已经变了，就要更新复习安排；认真做旧清单，也可能漏掉现在要考的内容。","en":"Reliability serves the goal, not an outdated list."}},{"id":"p12-Q3-dc60e7987a","text":{"zh":"先看新的考试要求，再调整复习安排。","en":"Review the goal and update steps."},"feedback":{"zh":"考试要求已经变了，就要更新复习安排；认真做旧清单，也可能漏掉现在要考的内容。","en":"Reliability serves the goal, not an outdated list."}}],"correct":"p12-Q3-dc60e7987a","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"每天完成必要的复习，比只在某一天特别拼、之后全停下来，更能体现认真负责。","en":"Sustained responsibility fits better than one burst."},{"zh":"做得快不快是一回事，有没有持续把该做的事做完，是另一回事。","en":"Evaluate follow-through, not speed alone."}],"question":{"id":"p12-R1","prompt":{"zh":"慢而稳定为何仍可能有效？","en":"Why can slow, steady work be effective?"},"options":[{"id":"p12-R1-954a0c11ab","text":{"zh":"每一步都认真完成，日子久了也能不断进步。","en":"Steps are completed and can accumulate."},"feedback":{"zh":"做得快不快是一回事，有没有持续把该做的事做完，是另一回事。","en":"Evaluate follow-through, not speed alone."}},{"id":"p12-R1-54a9dd381c","text":{"zh":"因为只要慢就不需要成果。","en":"Because slowness removes the need for results."},"feedback":{"zh":"做得快不快是一回事，有没有持续把该做的事做完，是另一回事。","en":"Evaluate follow-through, not speed alone."}}],"correct":"p12-R1-954a0c11ab"}},"R2":{"teach":[{"zh":"每天的量要安排得过来，才能坚持；一下塞太多，很容易第二天就停下来。","en":"Sustainable execution needs a workable pace."},{"zh":"按计划检查和保养设备，才能减少遗漏；不能只在出问题时才想起来。","en":"Responsibility appears in consistent essential actions."}],"question":{"id":"p12-R2","prompt":{"zh":"每天维护社团器材，怎样体现星币骑士认真负责的做事方式？","en":"Maintaining club equipment daily: what fits?"},"options":[{"id":"p12-R2-ba76172a48","text":{"zh":"想起来才做，每次都忘掉关键步骤。","en":"Act only when remembered and omit essentials."},"feedback":{"zh":"按计划检查和保养设备，才能减少遗漏；不能只在出问题时才想起来。","en":"Responsibility appears in consistent essential actions."}},{"id":"p12-R2-90f7a77379","text":{"zh":"按清单检查并记录需要处理的项。","en":"Follow a checklist and note needed repairs."},"feedback":{"zh":"按计划检查和保养设备，才能减少遗漏；不能只在出问题时才想起来。","en":"Responsibility appears in consistent essential actions."}}],"correct":"p12-R2-90f7a77379"}},"R3":{"teach":[{"zh":"考试要求已经改变，小罗却不看新要求，仍照旧清单复习。这个例子里，星币骑士逆位表示做法过于死板，需要检查每天做的事是否还符合目标；不是让他放弃规律学习。","en":"Requirements change but Luo mechanically follows the old list. Here reversal means rigid routine and calls for reviewing the purpose, not abandoning all consistency."},{"zh":"认真负责也包括检查要求有没有变化，再调整做法，而不是永远照旧做。","en":"Responsibility includes keeping action aligned with purpose."}],"question":{"id":"p12-R3","prompt":{"zh":"过时清单造成停滞，怎样重新把该做的事做好？","en":"An outdated checklist causes stagnation. Restore execution how?"},"options":[{"id":"p12-R3-eba327f234","text":{"zh":"认为只要每天照旧做，就一定算负责。","en":"Treat mechanical repetition as the only responsibility."},"feedback":{"zh":"认真负责也包括检查要求有没有变化，再调整做法，而不是永远照旧做。","en":"Responsibility includes keeping action aligned with purpose."}},{"id":"p12-R3-9f5e72b737","text":{"zh":"先确认现在要达到什么目标，再调整每天要做的事。","en":"Confirm the current goal and update repeatable steps."},"feedback":{"zh":"认真负责也包括检查要求有没有变化，再调整做法，而不是永远照旧做。","en":"Responsibility includes keeping action aligned with purpose."}}],"correct":"p12-R3-9f5e72b737"}}},"revisit":{"id":"p12-V1","prompt":{"zh":"学外语时，怎样运用星币骑士坚持做事的方式？","en":"Apply this style to language study."},"options":[{"id":"p12-V1-579b8fd368","text":{"zh":"安排每天做得完的练习，并坚持去做。","en":"Plan and carry out sustainable daily practice."},"feedback":{"zh":"按自己能坚持的节奏练习，并完成每天的任务，比一味追求学得比别人快更重要。","en":"Consistent execution does not require outrunning others."}},{"id":"p12-V1-8d63954600","text":{"zh":"只用学习速度排名决定是否继续。","en":"Decide whether to continue only from speed ranking."},"feedback":{"zh":"按自己能坚持的节奏练习，并完成每天的任务，比一味追求学得比别人快更重要。","en":"Consistent execution does not require outrunning others."}}],"correct":"p12-V1-579b8fd368"},"summary":{"zh":"星币骑士做事稳妥、认真负责，按自己能坚持的节奏完成任务。慢一点不等于做得差，但也要检查：每天照着做的事，是否仍符合现在的目标。","en":"The Knight of Pentacles follows steady, responsible steps with sustainable execution. Slow does not automatically mean poor, but routines must still serve an appropriate goal."},"cards":["p12"]},{"id":"p13","kind":"card","level":"I","title":{"zh":"星币王后","en":"Queen of Pentacles"},"teachings":[{"zh":"星币王后用实际行动照顾生活需要，比如安排好吃住、用品和休息，让日常生活更舒适稳定。照顾别人时，也要留意自己的时间、精力和基本需要，不限定任何性别或家庭身份。","en":"The Queen of Pentacles turns care into practical conditions and resource arrangements that sustain daily life. Care includes one’s own capacity and is not tied to gender or family role."},{"zh":"人物在繁茂环境中捧着星币。手中的星币和周围的植物，帮助记住照顾生活中的实际需要，而不是把她限定为母亲。","en":"A figure holds a pentacle in a lush setting. Resources and comfort suggest practical care without restricting the role to motherhood."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关；王后强调用实际行动照顾生活需要。这张牌可以记成：实际照顾、安排生活需要、生活安稳。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns everyday resources; Queen emphasizes mature care. Helpers: practical care, resource arrangement, stable daily life."}],"application":{"zh":"小严要长期学习，却总找不到材料、没有固定休息。放在建议位，可以先整理桌面和材料、安排好休息，让自己更方便继续学习；只喊“坚持”解决不了这些问题。","en":"Yan plans long-term study but loses materials and has no rest routine. Advice arranges space, materials, and daily rhythm to support learning in practice."},"reversal":{"zh":"小严忙着给所有人准备材料，连自己吃饭、休息的时间都没有了。这个例子里，星币王后逆位表示照顾别人时忽略了自己，需要重新分工、留出休息；不是说关心别人有错。","en":"Yan prepares everyone’s materials while skipping personal needs. Here reversal means overextending care and neglecting oneself, calling for shared work and capacity limits."},"visual":{"zh":"人物在繁茂环境中捧着星币。手中的星币和周围的植物，帮助记住照顾生活中的实际需要，而不是把她限定为母亲。","en":"A figure holds a pentacle in a lush setting. Resources and comfort suggest practical care without restricting the role to motherhood."},"questions":{"Q1":{"id":"p13-Q1","prompt":{"zh":"按照星币王后的意思，怎样用行动照顾生活？","en":"How does care become practical?"},"options":[{"id":"p13-Q1-56f39dbfde","text":{"zh":"安排好场地、物品和日常需要的帮助。","en":"Arrange space, resources, and daily support."},"feedback":{"zh":"关心可以变成实际行动，比如整理学习环境、准备用品，让对方更方便学习。","en":"The theme emphasizes concrete forms of care."}},{"id":"p13-Q1-6b6409bd05","text":{"zh":"只说希望生活更好，不处理实际需要。","en":"Express wishes without arranging conditions."},"feedback":{"zh":"关心可以变成实际行动，比如整理学习环境、准备用品，让对方更方便学习。","en":"The theme emphasizes concrete forms of care."}}],"correct":"p13-Q1-56f39dbfde","support":"R1"},"Q2":{"id":"p13-Q2","prompt":{"zh":"学习材料总找不到，建议是什么？","en":"Study materials are always missing. What fits?"},"options":[{"id":"p13-Q2-f082677a3b","text":{"zh":"只责备自己不够有毅力。","en":"Merely blame insufficient willpower."},"feedback":{"zh":"已经知道材料杂乱、休息不足，就先整理材料、安排休息；只鼓励自己还不够。","en":"Environment and resources are identified conditions to improve."}},{"id":"p13-Q2-6f7fe4c43f","text":{"zh":"整理常用的桌面和材料，让需要的东西容易找到。","en":"Organize the workspace and materials."},"feedback":{"zh":"已经知道材料杂乱、休息不足，就先整理材料、安排休息；只鼓励自己还不够。","en":"Environment and resources are identified conditions to improve."}}],"correct":"p13-Q2-6f7fe4c43f","support":"R2"},"Q3":{"id":"p13-Q3","prompt":{"zh":"照顾所有人却忽略自己，逆位提示什么？","en":"Caring for everyone while neglecting oneself: reversal?"},"options":[{"id":"p13-Q3-754515d435","text":{"zh":"重新分工，也留出自己吃饭、休息的时间。","en":"Share tasks and preserve personal needs."},"feedback":{"zh":"想继续照顾别人，自己也需要吃饭、休息，不能一直透支精力。","en":"Sustainable care includes the caregiver’s capacity."}},{"id":"p13-Q3-144878540e","text":{"zh":"关怀越多就越该取消自己的休息。","en":"More care requires eliminating personal rest."},"feedback":{"zh":"想继续照顾别人，自己也需要吃饭、休息，不能一直透支精力。","en":"Sustainable care includes the caregiver’s capacity."}}],"correct":"p13-Q3-754515d435","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"关心可以变成实际行动，比如整理学习环境、准备用品，让对方更方便学习。","en":"The theme emphasizes concrete forms of care."},{"zh":"这里的“王后”描述照顾生活需要的做事方式，不限定某个性别、年龄或家庭身份。","en":"Court roles here are behavior patterns, not identity labels."}],"question":{"id":"p13-R1","prompt":{"zh":"能够照顾生活需要的人，必须是某个性别或某种家庭身份吗？","en":"Does practical care require a particular identity?"},"options":[{"id":"p13-R1-f6e7ab2989","text":{"zh":"需要，只能由女性家长承担。","en":"Yes; only a female parent can do it."},"feedback":{"zh":"这里的“王后”描述照顾生活需要的做事方式，不限定某个性别、年龄或家庭身份。","en":"Court roles here are behavior patterns, not identity labels."}},{"id":"p13-R1-e9de76c57f","text":{"zh":"不需要，任何人都可以照顾生活中的实际需要。","en":"No; anyone can provide practical support."},"feedback":{"zh":"这里的“王后”描述照顾生活需要的做事方式，不限定某个性别、年龄或家庭身份。","en":"Court roles here are behavior patterns, not identity labels."}}],"correct":"p13-R1-e9de76c57f"}},"R2":{"teach":[{"zh":"已经知道材料杂乱、休息不足，就先整理材料、安排休息；只鼓励自己还不够。","en":"Environment and resources are identified conditions to improve."},{"zh":"把场地、用品和休息安排好，参与活动的人才能实际得到照顾；只有一句关心还不够。","en":"Practical arrangements make care usable."}],"question":{"id":"p13-R2","prompt":{"zh":"准备团体活动，怎样体现星币王后照顾实际需要的方式？","en":"Preparing a group activity, what fits?"},"options":[{"id":"p13-R2-a7a8db5dce","text":{"zh":"安排好场地和用品，也问清参加者有哪些实际需要。","en":"Arrange space, supplies, and participants’ needs."},"feedback":{"zh":"把场地、用品和休息安排好，参与活动的人才能实际得到照顾；只有一句关心还不够。","en":"Practical arrangements make care usable."}},{"id":"p13-R2-7a0bc92ea2","text":{"zh":"只说大家开心就好，不检查条件。","en":"Say have fun without checking conditions."},"feedback":{"zh":"把场地、用品和休息安排好，参与活动的人才能实际得到照顾；只有一句关心还不够。","en":"Practical arrangements make care usable."}}],"correct":"p13-R2-a7a8db5dce"}},"R3":{"teach":[{"zh":"小严忙着给所有人准备材料，连自己吃饭、休息的时间都没有了。这个例子里，星币王后逆位表示照顾别人时忽略了自己，需要重新分工、留出休息；不是说关心别人有错。","en":"Yan prepares everyone’s materials while skipping personal needs. Here reversal means overextending care and neglecting oneself, calling for shared work and capacity limits."},{"zh":"负责照顾的人也有精力限制，需要休息和分工，才能继续提供帮助。","en":"Caregiver capacity is part of sustainable support."}],"question":{"id":"p13-R3","prompt":{"zh":"替别人承担过多后，怎样继续关怀？","en":"Overextended by helping others, how continue caring?"},"options":[{"id":"p13-R3-c75ecff3ac","text":{"zh":"商量哪些事能请别人分担，也给自己留出休息时间。","en":"Share tasks and preserve essential recovery."},"feedback":{"zh":"负责照顾的人也有精力限制，需要休息和分工，才能继续提供帮助。","en":"Caregiver capacity is part of sustainable support."}},{"id":"p13-R3-3cc4e8bbdf","text":{"zh":"取消全部个人需要来证明关怀。","en":"Eliminate personal needs to prove care."},"feedback":{"zh":"负责照顾的人也有精力限制，需要休息和分工，才能继续提供帮助。","en":"Caregiver capacity is part of sustainable support."}}],"correct":"p13-R3-c75ecff3ac"}}},"revisit":{"id":"p13-V1","prompt":{"zh":"考试周朋友忙乱，怎样提供适当支持？","en":"A friend struggles during exams. Offer suitable support how?"},"options":[{"id":"p13-V1-ab8c829887","text":{"zh":"包办一切并永久取消自己的安排。","en":"Take over everything and cancel all personal plans."},"feedback":{"zh":"先问朋友需要什么，再看看自己能帮多少；不必把对方所有事情都接过来。","en":"Care considers both needs and feasible capacity."}},{"id":"p13-V1-1dbe5a56db","text":{"zh":"先问对方需要什么，再提供自己做得到的帮助。","en":"Ask what is needed and help within capacity."},"feedback":{"zh":"先问朋友需要什么，再看看自己能帮多少；不必把对方所有事情都接过来。","en":"Care considers both needs and feasible capacity."}}],"correct":"p13-V1-1dbe5a56db"},"summary":{"zh":"星币王后用实际行动照顾生活需要，比如安排好吃住、用品和休息，让日常生活更舒适稳定。照顾别人时，也要留意自己的时间、精力和基本需要，不限定任何性别或家庭身份。","en":"The Queen of Pentacles turns care into practical conditions and resource arrangements that sustain daily life. Care includes one’s own capacity and is not tied to gender or family role."},"cards":["p13"]},{"id":"p14","kind":"card","level":"I","title":{"zh":"星币国王","en":"King of Pentacles"},"teachings":[{"zh":"星币国王善于安排和管理资源，把能力用到实际工作中，并让成果能长期保留下来、继续发挥作用。重点是管理、维护和责任，不是单凭财富外观判断成功。","en":"The King of Pentacles manages resources maturely, turning capability into lasting results and security. Management, maintenance, and responsibility matter more than a wealthy appearance."},{"zh":"国王持币，周围有葡萄与城堡。成果与稳定环境可帮助记住长期经营，不保证任何投资收益。","en":"A figure holds a pentacle among vines and a castle. Results and stable surroundings suggest long-term stewardship without guaranteeing investment returns."},{"zh":"星币对应土元素，常和金钱、物品、身体及实际生活有关；国王强调安排资源、作决定并承担责任。这张牌可以记成：稳妥管理、经营成果、长期保障。","en":"Pentacles correspond to Earth and commonly concern money, possessions, the body, and practical life. Earth concerns practical conditions; King emphasizes stewardship and responsibility, not gender or wealth. Helpers: steady management, results, lasting security."}],"application":{"zh":"团队想长期运营共享工具间。建议位核对购买、维护和使用安排，明确谁负责，让成果能持续，而非只买最贵设备。","en":"A team wants to run a shared workshop long term. Advice checks purchase, maintenance, access, and responsibility rather than simply buying the most expensive equipment."},"reversal":{"zh":"管理者为了让人看到自己拥有很多设备而不断购买，却不愿保养，设备陆续无法使用。这个例子里，星币国王逆位表示只顾拥有、没有管理好，需要重新安排用途和维护责任。","en":"A manager buys for the appearance of ownership but refuses maintenance, leaving equipment idle. Here reversal means possession overriding stewardship, requiring a review of use and upkeep."},"visual":{"zh":"国王持币，周围有葡萄与城堡。成果与稳定环境可帮助记住长期经营，不保证任何投资收益。","en":"A figure holds a pentacle among vines and a castle. Results and stable surroundings suggest long-term stewardship without guaranteeing investment returns."},"questions":{"Q1":{"id":"p14-Q1","prompt":{"zh":"怎样让已经获得的成果长期发挥作用？","en":"What makes results sustainable?"},"options":[{"id":"p14-Q1-c34cb3ebec","text":{"zh":"只要拥有昂贵物品就自动稳定。","en":"Expensive possessions automatically create stability."},"feedback":{"zh":"设备买回来以后，还要安排使用、保养和维修，才能一直有用。","en":"Enduring results need stewardship, not mere possession."}},{"id":"p14-Q1-334459c5e1","text":{"zh":"不只拥有资源，还安排好怎样使用、谁来维护。","en":"Resources, maintenance, and responsibility align."},"feedback":{"zh":"设备买回来以后，还要安排使用、保养和维修，才能一直有用。","en":"Enduring results need stewardship, not mere possession."}}],"correct":"p14-Q1-334459c5e1","support":"R1"},"Q2":{"id":"p14-Q2","prompt":{"zh":"运营共享工具间，先核对什么？","en":"Running a shared workshop: check what?"},"options":[{"id":"p14-Q2-0dbcf1d796","text":{"zh":"购买、维护、使用与负责人的安排。","en":"Purchase, upkeep, access, and responsibility."},"feedback":{"zh":"共用工作室想长期运行，就要考虑设备怎么保养、费用由谁承担，而不只是开张那一天。","en":"Long-term security includes conditions for ongoing use."}},{"id":"p14-Q2-f47d4f3ee6","text":{"zh":"只比较哪种设备看起来最昂贵。","en":"Only compare which equipment looks most expensive."},"feedback":{"zh":"共用工作室想长期运行，就要考虑设备怎么保养、费用由谁承担，而不只是开张那一天。","en":"Long-term security includes conditions for ongoing use."}}],"correct":"p14-Q2-0dbcf1d796","support":"R2"},"Q3":{"id":"p14-Q3","prompt":{"zh":"不断购买却拒绝维护，逆位提示什么？","en":"Buying repeatedly while refusing maintenance: reversal?"},"options":[{"id":"p14-Q3-0c89acd8ff","text":{"zh":"购买越多就说明维护越不重要。","en":"More purchases make maintenance less important."},"feedback":{"zh":"设备买了却不能用，说明光是拥有不够；还需要维护、修理和安排使用。","en":"Idle equipment shows possession cannot replace upkeep."}},{"id":"p14-Q3-bcffeebb7d","text":{"zh":"只顾购买、忽略维护，需要重新安排设备的使用和保养。","en":"Possession and stewardship are unbalanced; restore management."},"feedback":{"zh":"设备买了却不能用，说明光是拥有不够；还需要维护、修理和安排使用。","en":"Idle equipment shows possession cannot replace upkeep."}}],"correct":"p14-Q3-bcffeebb7d","support":"R3"}},"remediation":{"R1":{"teach":[{"zh":"设备买回来以后，还要安排使用、保养和维修，才能一直有用。","en":"Enduring results need stewardship, not mere possession."},{"zh":"一项资源想长期有用，就要有人负责后续的保养和管理，不能买完就不管。","en":"Practical security requires continuing responsibility."}],"question":{"id":"p14-R1","prompt":{"zh":"为什么有成果后仍需要管理？","en":"Why manage after obtaining results?"},"options":[{"id":"p14-R1-935e9c87c2","text":{"zh":"有人维护、也有后续费用，成果才能继续使用下去。","en":"Results require upkeep and continuity."},"feedback":{"zh":"一项资源想长期有用，就要有人负责后续的保养和管理，不能买完就不管。","en":"Practical security requires continuing responsibility."}},{"id":"p14-R1-8e118f08a5","text":{"zh":"成果一出现就永远不会变化。","en":"Once achieved, results never change."},"feedback":{"zh":"一项资源想长期有用，就要有人负责后续的保养和管理，不能买完就不管。","en":"Practical security requires continuing responsibility."}}],"correct":"p14-R1-935e9c87c2"}},"R2":{"teach":[{"zh":"共用工作室想长期运行，就要考虑设备怎么保养、费用由谁承担，而不只是开张那一天。","en":"Long-term security includes conditions for ongoing use."},{"zh":"社团道具不只要买回来，还要安排存放、使用和维修，才能反复使用。","en":"Stewardship concerns the full use cycle."}],"question":{"id":"p14-R2","prompt":{"zh":"社团已经买好道具，下一步怎样？","en":"A club has bought props. What next?"},"options":[{"id":"p14-R2-e54d4894fa","text":{"zh":"认为买好就永远不必再管理。","en":"Assume purchases need no further management."},"feedback":{"zh":"社团道具不只要买回来，还要安排存放、使用和维修，才能反复使用。","en":"Stewardship concerns the full use cycle."}},{"id":"p14-R2-4c0959bd3c","text":{"zh":"说清谁保管、谁检查维修，以后谁负责安排使用。","en":"Assign storage, repair, and use responsibilities."},"feedback":{"zh":"社团道具不只要买回来，还要安排存放、使用和维修，才能反复使用。","en":"Stewardship concerns the full use cycle."}}],"correct":"p14-R2-4c0959bd3c"}},"R3":{"teach":[{"zh":"管理者为了让人看到自己拥有很多设备而不断购买，却不愿保养，设备陆续无法使用。这个例子里，星币国王逆位表示只顾拥有、没有管理好，需要重新安排用途和维护责任。","en":"A manager buys for the appearance of ownership but refuses maintenance, leaving equipment idle. Here reversal means possession overriding stewardship, requiring a review of use and upkeep."},{"zh":"先让现有设备能正常使用、有人保养，比一味购买更多设备更重要。","en":"Stewardship concerns sustainable use, not more possessions."}],"question":{"id":"p14-R3","prompt":{"zh":"设备拥有很多却闲置，应该怎样重新安排管理？","en":"Much equipment is idle. Restore stewardship how?"},"options":[{"id":"p14-R3-0fce256fb6","text":{"zh":"继续买更多，以数量掩盖闲置。","en":"Buy more to disguise the idle stock."},"feedback":{"zh":"先让现有设备能正常使用、有人保养，比一味购买更多设备更重要。","en":"Stewardship concerns sustainable use, not more possessions."}},{"id":"p14-R3-fed33f04c8","text":{"zh":"检查设备能做什么、哪里要修，以及谁负责处理。","en":"Check use, upkeep, and assigned responsibilities."},"feedback":{"zh":"先让现有设备能正常使用、有人保养，比一味购买更多设备更重要。","en":"Stewardship concerns sustainable use, not more possessions."}}],"correct":"p14-R3-fed33f04c8"}}},"revisit":{"id":"p14-V1","prompt":{"zh":"想靠自己的技能长期提供服务，按照星币国王的提醒，先考虑什么？","en":"Turning a skill into a reliable service: apply."},"options":[{"id":"p14-V1-ecdc09b49d","text":{"zh":"先确认自己的时间、设备和工作安排，能不能持续完成答应客户的服务。","en":"Check capacity, resources, and repeatable delivery."},"feedback":{"zh":"把技能做成服务后，还需要安排时间、维护设备、按约定完成工作，才能持续做下去。","en":"Sustained results need sustained stewardship."}},{"id":"p14-V1-88ba94bf1b","text":{"zh":"只靠一次成功保证以后全部成功。","en":"Treat one success as a guarantee of all future success."},"feedback":{"zh":"把技能做成服务后，还需要安排时间、维护设备、按约定完成工作，才能持续做下去。","en":"Sustained results need sustained stewardship."}}],"correct":"p14-V1-ecdc09b49d"},"summary":{"zh":"星币国王善于安排和管理资源，把能力用到实际工作中，并让成果能长期保留下来、继续发挥作用。重点是管理、维护和责任，不是单凭财富外观判断成功。","en":"The King of Pentacles manages resources maturely, turning capability into lasting results and security. Management, maintenance, and responsibility matter more than a wealthy appearance."},"cards":["p14"]}]};
